CREATE FUNCTION api.accept_invitation(p_token text, p_user_id text) RETURNS api.workspace_invitations
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE v api.workspace_invitations;
BEGIN
  IF p_user_id IS DISTINCT FROM api.current_user_id() THEN RAISE EXCEPTION 'user identity mismatch' USING ERRCODE='SB062'; END IF;
  SELECT * INTO v FROM api.workspace_invitations WHERE token_hash=encode(sha256(convert_to(p_token,'UTF8')),'hex') FOR UPDATE;
  IF v IS NULL OR v.status <> 'pending' THEN RAISE EXCEPTION 'invitation is not pending' USING ERRCODE='SB061'; END IF;
  IF v.expires_at <= now() THEN UPDATE api.workspace_invitations SET status='expired',updated_at=now() WHERE id=v.id; RAISE EXCEPTION 'invitation expired' USING ERRCODE='SB061'; END IF;
  INSERT INTO api.workspace_memberships(workspace_id,user_id,role,client_id)
    VALUES(v.workspace_id,p_user_id,v.role,v.client_id)
    ON CONFLICT (workspace_id,user_id) DO UPDATE
      SET role=CASE WHEN api.workspace_memberships.suspended_at IS NULL THEN api.workspace_memberships.role ELSE EXCLUDED.role END,client_id=CASE WHEN api.workspace_memberships.suspended_at IS NULL THEN api.workspace_memberships.client_id ELSE EXCLUDED.client_id END,suspended_at=NULL,updated_at=now();
  IF v.role = 'client_viewer' AND v.client_id IS NOT NULL THEN
    INSERT INTO api.project_access(workspace_id, project_id, user_id, can_view, can_edit, can_review, client_portal, can_manage, granted_by_user_id)
    SELECT p.workspace_id, p.id, p_user_id, false, false, false, true, false, p_user_id
      FROM api.projects p
     WHERE p.workspace_id = v.workspace_id
       AND p.client_id = v.client_id
       AND p.auto_share_to_client
    ON CONFLICT (workspace_id, project_id, user_id)
    DO UPDATE SET client_portal = true, updated_at = now();
  END IF;
  v.accepted_by_user_id:=p_user_id;
  PERFORM api.apply_invitation_project_grants(v);
  UPDATE api.workspace_invitations SET status='accepted',accepted_at=now(),accepted_by_user_id=p_user_id,updated_at=now() WHERE id=v.id RETURNING * INTO v;
  RETURN v;
END $$;
