    CONSTRAINT chk_agent_workflows_author_xor CHECK (((created_by_user_id IS NULL) <> (created_by_credential_id IS NULL))),
    CONSTRAINT chk_agent_workflows_budgets CHECK ((((max_operations >= 1) AND (max_operations <= 50)) AND (max_tokens >= 0) AND (max_cost_microusd >= 0))),
    CONSTRAINT chk_agent_workflows_digest CHECK ((plan_digest ~ '^[0-9a-f]{64}$'::text)),
    CONSTRAINT chk_agent_workflows_revision CHECK ((revision > 0)),
    CONSTRAINT chk_agent_workflows_status CHECK ((status = ANY (ARRAY['waiting_approval'::text, 'paused'::text, 'succeeded'::text, 'cancelled'::text, 'budget_exhausted'::text]))),
    CONSTRAINT chk_agent_workflows_usage CHECK (((used_operations >= 0) AND (used_tokens >= 0) AND (used_cost_microusd >= 0)))
);
