CREATE FUNCTION api.advance_agent_workflow(p_workflow_id uuid, p_expected_revision bigint) RETURNS api.agent_workflows
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
  v_workflow api.agent_workflows;
  v_step api.agent_workflow_steps;
  v_proposal api.agent_operation_proposals;
  v_step_count integer;
BEGIN
  SELECT * INTO v_workflow
    FROM api.agent_workflows
   WHERE id = p_workflow_id
     AND workspace_id = api.current_workspace_id()
   FOR UPDATE;
  IF v_workflow.id IS NULL THEN
    RAISE EXCEPTION 'workflow not found' USING ERRCODE = '42501';
  END IF;
  PERFORM internal.require_agent_workflow_control(v_workflow);
  IF v_workflow.revision <> p_expected_revision
     OR v_workflow.status <> 'waiting_approval' THEN
    RAISE EXCEPTION 'workflow is not waiting at the expected revision'
      USING ERRCODE = 'SB001';
  END IF;
  SELECT * INTO v_step
    FROM api.agent_workflow_steps
   WHERE workflow_id = v_workflow.id
     AND position = v_workflow.current_step
   FOR UPDATE;
  SELECT * INTO v_proposal
    FROM api.agent_operation_proposals
   WHERE id = v_step.proposal_id;

  IF v_proposal.status IN ('pending','approved','executing') THEN
    RETURN v_workflow;
  ELSIF v_proposal.status IN ('rejected','failed','cancelled') THEN
    UPDATE api.agent_workflow_steps
       SET status = CASE v_proposal.status
         WHEN 'rejected' THEN 'rejected'
         WHEN 'failed' THEN 'failed'
         ELSE 'cancelled'
       END,
       updated_at = now()
     WHERE id = v_step.id;
    UPDATE api.agent_workflows
       SET status = 'paused', revision = revision + 1, updated_at = now()
     WHERE id = v_workflow.id
     RETURNING * INTO v_workflow;
    PERFORM internal.agent_workflow_append_event(
      v_workflow,'paused',
      jsonb_build_object(
        'stepKey',v_step.step_key,'proposalId',v_proposal.id,
        'proposalStatus',v_proposal.status,'errorCode',v_proposal.error_code
      )
    );
    RETURN v_workflow;
  ELSIF v_proposal.status <> 'succeeded' THEN
    RAISE EXCEPTION 'workflow proposal has an unknown state' USING ERRCODE = 'SB001';
  END IF;

  UPDATE api.agent_workflow_steps
     SET status = 'succeeded', completed_at = now(), updated_at = now()
   WHERE id = v_step.id;
  UPDATE api.agent_workflows
     SET revision = revision + 1, updated_at = now()
   WHERE id = v_workflow.id
   RETURNING * INTO v_workflow;
  PERFORM internal.agent_workflow_append_event(
    v_workflow,'step_succeeded',
    jsonb_build_object(
      'stepKey',v_step.step_key,'proposalId',v_proposal.id,
      'canonicalResult',v_proposal.result
    )
  );
  SELECT count(*)::integer INTO v_step_count
    FROM api.agent_workflow_steps
   WHERE workflow_id = v_workflow.id;
  IF v_workflow.current_step + 1 >= v_step_count THEN
    UPDATE api.agent_workflows
       SET status = 'succeeded', completed_at = now(),
           revision = revision + 1, updated_at = now()
     WHERE id = v_workflow.id
     RETURNING * INTO v_workflow;
    PERFORM internal.agent_workflow_append_event(
      v_workflow,'succeeded',
      jsonb_build_object('planDigest',v_workflow.plan_digest)
    );
    RETURN v_workflow;
  END IF;
  RETURN internal.agent_workflow_propose_step(
    v_workflow.id, v_workflow.current_step + 1
  );
END;
$$;
--> statement-breakpoint
ALTER FUNCTION api.advance_agent_workflow(p_workflow_id uuid, p_expected_revision bigint) OWNER TO migrator;
--> statement-breakpoint
CREATE FUNCTION api.aliquot_sample(p_record_id uuid, p_count integer, p_quantity_each numeric, p_purpose_experiment_id uuid, p_expected_metadata_version integer, p_unit text DEFAULT NULL::text, p_notes text DEFAULT NULL::text, p_new_container jsonb DEFAULT NULL::jsonb) RETURNS jsonb
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
DECLARE
  v_source "api"."records";
  v_version int := p_expected_metadata_version;
  v_free numeric;
  v_reserved numeric;
  v_result jsonb;
  v_container jsonb;
  v_derived jsonb := '[]'::jsonb;
  v_base_title text;
  v_i int;
BEGIN
  IF p_count IS NULL OR p_count < 1 OR p_count > 96 THEN
    RAISE EXCEPTION 'aliquot count must be between 1 and 96' USING ERRCODE = '22023';
  END IF;
  IF p_quantity_each IS NULL OR p_quantity_each <= 0 THEN
    RAISE EXCEPTION 'aliquot quantity must be positive' USING ERRCODE = 'SB006';
  END IF;
  IF p_new_container IS NOT NULL AND p_new_container <> 'null'::jsonb
     AND jsonb_typeof(p_new_container) <> 'object' THEN
    RAISE EXCEPTION 'new container must be a JSON object' USING ERRCODE = '22023';
  END IF;

  SELECT * INTO v_source FROM "api"."records" WHERE id = p_record_id AND kind = 'sample';
  IF v_source.id IS NULL THEN
    RAISE EXCEPTION 'record not found in active workspace' USING ERRCODE = '42501';
  END IF;

  -- Refuse the whole split up front when the tubes together would overdraw the
  -- free balance, so the message names the total rather than the last tube.
  v_reserved := coalesce("internal"."sample_reserved_quantity"(p_record_id), 0);
  v_free := coalesce(nullif(v_source.properties ->> 'quantity', '')::numeric, 0) - v_reserved;
  IF p_count * p_quantity_each > v_free THEN
    RAISE EXCEPTION 'insufficient free quantity: available %, reserved %, aliquoting % x % = %',
      v_free, v_reserved, p_count, p_quantity_each, p_count * p_quantity_each
      USING ERRCODE = 'SB006';
  END IF;

  v_base_title := coalesce(
    nullif(btrim(coalesce(p_new_container ->> 'title', '')), ''),
    coalesce(v_source.title, v_source.identifier)
  );

  FOR v_i IN 1..p_count LOOP
    v_container := coalesce(p_new_container, '{}'::jsonb) || jsonb_build_object(
      'title', format('%s aliquot %s of %s', v_base_title, v_i, p_count)
    );
    v_result := "api"."withdraw_sample"(
      p_record_id => p_record_id,
      p_quantity => p_quantity_each,
      p_expected_metadata_version => v_version,
      p_purpose_experiment_id => p_purpose_experiment_id,
      p_unit => p_unit,
      p_notes => p_notes,
      p_new_container => v_container
    );
    v_derived := v_derived || jsonb_build_array(v_result -> 'derivedSample');
    v_version := (v_result -> 'sample' ->> 'metadata_version')::int;
  END LOOP;

  RETURN jsonb_build_object(
    'sample', v_result -> 'sample',
    'derivedSamples', v_derived
  );
END;
$$;
--> statement-breakpoint
ALTER FUNCTION api.aliquot_sample(p_record_id uuid, p_count integer, p_quantity_each numeric, p_purpose_experiment_id uuid, p_expected_metadata_version integer, p_unit text, p_notes text, p_new_container jsonb) OWNER TO migrator;
--> statement-breakpoint
COMMENT ON FUNCTION api.aliquot_sample(p_record_id uuid, p_count integer, p_quantity_each numeric, p_purpose_experiment_id uuid, p_expected_metadata_version integer, p_unit text, p_notes text, p_new_container jsonb) IS 'Phase 6: split a sample into p_count tubes of p_quantity_each, each a withdrawal into a derived container for the purpose experiment, in one transaction (all or nothing). Returns { sample, derivedSamples[] }.';
