    id uuid DEFAULT gen_random_uuid() NOT NULL,
    workspace_id uuid NOT NULL,
    run_id uuid NOT NULL,
    sequence integer NOT NULL,
    level text DEFAULT 'info'::text NOT NULL,
    stage text NOT NULL,
    message text NOT NULL,
    detail jsonb DEFAULT '{}'::jsonb NOT NULL,
    at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT chk_pipeline_run_logs_level CHECK ((level = ANY (ARRAY['info'::text, 'warning'::text, 'error'::text]))),
    CONSTRAINT chk_pipeline_run_logs_message CHECK (((length(btrim(message)) >= 1) AND (length(btrim(message)) <= 2000))),
    CONSTRAINT chk_pipeline_run_logs_sequence CHECK ((sequence >= 1)),
    CONSTRAINT chk_pipeline_run_logs_stage CHECK (((length(btrim(stage)) >= 1) AND (length(btrim(stage)) <= 100)))
);
