CREATE FUNCTION api.apply_column_promotion(p_promotion_id uuid, p_idempotency_key uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
  v_promotion api.column_promotions;
  v_approval api.approval_requests;
  v_instance api.sheet_instances;
  v_preview jsonb;
  v_materialized jsonb;
  v_output api.datasets;
  v_snapshot api.dataset_versions;
  v_batch jsonb;
  v_rows jsonb;
  v_result jsonb;
BEGIN
  SELECT * INTO v_promotion FROM api.column_promotions WHERE id = p_promotion_id FOR UPDATE;
  IF v_promotion.id IS NULL
     OR v_promotion.workspace_id IS DISTINCT FROM api.current_workspace_id() THEN
    RAISE EXCEPTION 'Unknown promotion' USING ERRCODE = '22023';
  END IF;
  IF v_promotion.state <> 'pending' THEN
    RAISE EXCEPTION 'This promotion is already settled' USING ERRCODE = '22023';
  END IF;

  SELECT * INTO v_instance FROM api.sheet_instances WHERE id = v_promotion.sheet_instance_id FOR UPDATE;
  PERFORM internal.assert_object_access('instance', v_promotion.sheet_instance_id, 'edit');
  PERFORM api.require_capability(v_promotion.workspace_id, 'schema.edit');

  SELECT * INTO v_approval FROM api.approval_requests WHERE id = v_promotion.approval_request_id;
  IF v_approval.id IS NULL OR v_approval.state = 'pending' THEN
    RAISE EXCEPTION 'This promotion has not been decided' USING ERRCODE = 'SB086';
  END IF;

  IF v_approval.state <> 'approved' THEN
    -- Returned or withdrawn: the reason is recorded and nothing moves.
    UPDATE api.column_promotions
       SET state = CASE WHEN v_approval.state = 'withdrawn' THEN 'withdrawn' ELSE 'returned' END,
           decided_at = now(),
           reason = coalesce(nullif(btrim(coalesce(v_approval.decision_reason, '')), ''), reason),
           updated_at = now()
     WHERE id = v_promotion.id
    RETURNING * INTO v_promotion;
    RETURN jsonb_build_object(
      'ok', true,
      'state', v_promotion.state,
      'applied', false,
      'reason', v_promotion.reason
    );
  END IF;

  IF v_promotion.target <> 'dataset_schema' OR v_promotion.schema_version_id IS NULL THEN
    RAISE EXCEPTION 'Only a Dataset Schema promotion can be applied' USING ERRCODE = '22023';
  END IF;

  -- The preview and its digest are the canonical materialization contract; passing the
  -- digest is what stops a stale preview from writing a snapshot of data that moved.
  -- SHEET-02.2: a Sheet with no dataset composition cannot be materialized, so its
  -- own local values become a new dataset instead.
  IF jsonb_array_length(coalesce(v_instance.state->'bindings','[]'::jsonb)) = 0 THEN
    INSERT INTO api.datasets(workspace_id, schema_version_id, name, created_by_user_id)
    VALUES (v_instance.workspace_id, v_promotion.schema_version_id,
            btrim(coalesce(v_instance.name,'Promoted column')), api.current_user_id())
    RETURNING * INTO v_output;

    SELECT coalesce(jsonb_agg(jsonb_build_object(
             'operation','create',
             'rowId',gen_random_uuid(),
             'values',jsonb_build_object(v_promotion.field_id::text, cell.value)
           )), '[]'::jsonb) INTO v_rows
      FROM jsonb_each(coalesce(v_instance.state->'localValues','{}'::jsonb)) row_item,
           LATERAL jsonb_each(row_item.value) cell
     WHERE cell.key = v_promotion.field_id::text;

    IF jsonb_array_length(v_rows) > 0 THEN
      SELECT api.commit_dataset_row_batch(
        v_output.id, v_output.revision, v_rows,
        'column-promotion:' || p_promotion_id::text
      ) INTO v_batch;
      IF (v_batch->>'ok')::boolean IS NOT TRUE THEN
        RAISE EXCEPTION 'the promoted values failed Dataset validation: %', v_batch
          USING ERRCODE = 'SB089';
      END IF;
    END IF;

    SELECT * INTO v_snapshot FROM api.snapshot_dataset(
      v_output.id, (SELECT revision FROM api.datasets WHERE id = v_output.id),
      'Column promotion output'
    );
    v_materialized := jsonb_build_object(
      'datasetId',v_output.id,'datasetVersionId',v_snapshot.id
    );
  ELSE
  v_preview := api.preview_sheet_materialization(
    v_promotion.sheet_instance_id, v_instance.revision, v_promotion.schema_version_id
  );
  v_materialized := api.materialize_sheet_instance(
    v_promotion.sheet_instance_id,
    v_instance.revision,
    coalesce(v_instance.name, 'Promoted column'),
    v_promotion.schema_version_id,
    v_preview->>'previewDigest',
    p_idempotency_key
  );
  END IF;

  -- The values now live in the dataset, so the column stops being local. Retiring it is
  -- the switch; the materialization above did not change the instance revision.
  PERFORM api.mutate_sheet_instance_local_state(
    v_promotion.sheet_instance_id,
    v_instance.revision,
    p_idempotency_key,
    jsonb_build_array(jsonb_build_object(
      'operation', 'retire',
      'fieldId', v_promotion.field_id
    )),
    '[]'::jsonb,
    '[]'::jsonb
  );

  UPDATE api.column_promotions
     SET state = 'applied', decided_at = now(), updated_at = now()
   WHERE id = v_promotion.id;

  v_result := jsonb_build_object(
    'ok', true,
    'state', 'applied',
    'applied', true,
    'datasetId', v_materialized->>'datasetId',
    'datasetVersionId', v_materialized->>'datasetVersionId'
  );
  RETURN v_result;
END $$;
--> statement-breakpoint
ALTER FUNCTION api.apply_column_promotion(p_promotion_id uuid, p_idempotency_key uuid) OWNER TO migrator;
--> statement-breakpoint
CREATE FUNCTION api.apply_dataset_model_upgrade(p_dataset_id uuid, p_target_version_id uuid, p_expected_revision bigint) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
  v_dataset api.datasets;
  v_preview jsonb;
BEGIN
  SELECT * INTO v_dataset FROM api.datasets WHERE id = p_dataset_id FOR UPDATE;
  IF v_dataset.id IS NULL OR NOT api.is_workspace_writer(v_dataset.workspace_id)
    OR NOT internal.can_access_object('dataset', v_dataset.id, 'edit') THEN
    RAISE EXCEPTION 'dataset not found' USING ERRCODE = '42501';
  END IF;
  PERFORM api.require_capability(v_dataset.workspace_id, 'schema.edit');
  IF p_expected_revision IS NOT NULL AND v_dataset.revision <> p_expected_revision THEN
    RAISE EXCEPTION 'dataset revision conflict' USING ERRCODE = 'SB001';
  END IF;
  IF v_dataset.lifecycle <> 'active' THEN
    RAISE EXCEPTION 'an archived dataset cannot be upgraded' USING ERRCODE = '55000';
  END IF;
  v_preview := api.preview_dataset_model_upgrade(p_dataset_id, p_target_version_id);
  IF (v_preview->>'blocked')::boolean THEN
    RAISE EXCEPTION '%', v_preview->>'reason' USING ERRCODE = '22023';
  END IF;

  UPDATE api.datasets
     SET schema_version_id = p_target_version_id,
         revision = revision + 1,
         updated_at = now()
   WHERE id = v_dataset.id;

  PERFORM internal.emit_change_event(v_dataset.workspace_id, 'dataset', v_dataset.id, 'update',
    NULL, v_dataset.primary_project_id,
    jsonb_build_object(
      'effect', 'dataset_model_upgrade',
      'datasetId', v_dataset.id,
      'datasetRevision', v_dataset.revision + 1,
      'changes', jsonb_build_object(
        'model_version', jsonb_build_object(
          'from', v_preview->>'fromVersion',
          'to', v_preview->>'toVersion',
          'label', 'Model version'))));

  RETURN v_preview || jsonb_build_object('applied', true, 'datasetRevision', v_dataset.revision + 1);
END $$;
--> statement-breakpoint
ALTER FUNCTION api.apply_dataset_model_upgrade(p_dataset_id uuid, p_target_version_id uuid, p_expected_revision bigint) OWNER TO migrator;
--> statement-breakpoint
CREATE FUNCTION api.apply_dataset_schema_evolution(p_schema_version_id uuid, p_fields jsonb, p_idempotency_key text, p_expected_revision bigint DEFAULT NULL::bigint) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
  version api.dataset_schema_versions;
  write_version api.dataset_schema_versions;
  workspace uuid;
  actor text := api.current_user_id();
  digest text;
  replay jsonb;
  preview jsonb;
  published api.dataset_schema_versions;
  result jsonb;
BEGIN
  SELECT * INTO version FROM api.dataset_schema_versions WHERE id = p_schema_version_id;
  SELECT s.workspace_id INTO workspace FROM api.dataset_schema_definitions s WHERE s.id = version.schema_id;
  IF version.id IS NULL THEN RAISE EXCEPTION 'Dataset Schema Version not found' USING ERRCODE = '42501'; END IF;
  PERFORM api.require_capability(workspace, 'schema.publish');
  digest := encode(sha256(convert_to(jsonb_build_object(
    'base', p_schema_version_id, 'fields', p_fields
  )::text, 'UTF8')), 'hex');
  replay := internal.replay_configuration_change(
    workspace, actor, 'dataset_schema_evolution', p_idempotency_key, digest
  );
  IF replay IS NOT NULL THEN
    RETURN replay;
  END IF;
  preview := api.preview_dataset_schema_evolution(p_schema_version_id, p_fields);
  write_version := internal.lock_dataset_schema_write_version(p_schema_version_id, p_expected_revision);
  PERFORM api.replace_dataset_schema_version_fields(write_version.id, p_fields);
  published := api.publish_dataset_schema_version(write_version.id);
  result := preview || jsonb_build_object(
    'ok', true,
    'schemaVersionId', published.id,
    'version', published.version,
    'idempotent', false
  );
  PERFORM internal.record_configuration_change(
    workspace, actor, 'dataset_schema_evolution', p_idempotency_key, digest, result
  );
  RETURN result;
END;
$$;
--> statement-breakpoint
ALTER FUNCTION api.apply_dataset_schema_evolution(p_schema_version_id uuid, p_fields jsonb, p_idempotency_key text, p_expected_revision bigint) OWNER TO migrator;
--> statement-breakpoint
CREATE FUNCTION api.apply_invitation_project_grants(p_invitation api.workspace_invitations) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE v_grant jsonb; v_level text;
BEGIN
  -- A project that has been archived or deleted since the invitation was made
  -- is skipped rather than failing the join.
  FOR v_grant IN SELECT * FROM jsonb_array_elements(p_invitation.project_grants) LOOP
    v_level:=v_grant->>'access_level';
    INSERT INTO api.project_access(workspace_id,project_id,user_id,can_view,can_edit,can_review,client_portal,can_manage,granted_by_user_id)
    SELECT p_invitation.workspace_id,p.id,p_invitation.accepted_by_user_id,true,v_level IN ('owner','editor'),v_level IN ('owner','reviewer'),false,v_level='owner',p_invitation.created_by_user_id
      FROM api.projects p
     WHERE p.id=(v_grant->>'project_id')::uuid AND p.workspace_id=p_invitation.workspace_id
    ON CONFLICT(workspace_id,project_id,user_id) DO UPDATE
      SET can_view=excluded.can_view,can_edit=excluded.can_edit,can_review=excluded.can_review,
          can_manage=excluded.can_manage,granted_by_user_id=excluded.granted_by_user_id,updated_at=now();
  END LOOP;
END $$;
--> statement-breakpoint
ALTER FUNCTION api.apply_invitation_project_grants(p_invitation api.workspace_invitations) OWNER TO migrator;
--> statement-breakpoint
CREATE FUNCTION api.apply_model_field_evolution(p_definition_id uuid, p_action text, p_patch jsonb DEFAULT '{}'::jsonb, p_confirm boolean DEFAULT false) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
  preview jsonb;
  field api.record_field_definitions;
BEGIN
  preview := api.preview_model_field_evolution(p_definition_id, p_action, p_patch);
  IF (preview->>'blocked')::boolean THEN
    RAISE EXCEPTION 'destructive Model field change is blocked' USING ERRCODE = 'SB072';
  END IF;
  IF preview->>'classification' = 'migration-requiring' AND p_confirm IS NOT TRUE THEN
    RAISE EXCEPTION 'consequential Model field change requires confirmation' USING ERRCODE = 'SB071';
  END IF;
  IF p_action = 'retire' THEN
    field := api.retire_model_field(p_definition_id);
  ELSE
    field := api.update_model_field(p_definition_id, p_patch);
  END IF;
  RETURN preview || jsonb_build_object('ok', true, 'field', to_jsonb(field));
END;
$$;
--> statement-breakpoint
ALTER FUNCTION api.apply_model_field_evolution(p_definition_id uuid, p_action text, p_patch jsonb, p_confirm boolean) OWNER TO migrator;
--> statement-breakpoint
CREATE FUNCTION api.apply_notebook_template_upgrade(p_record_id uuid, p_expected_structure_version integer, p_target_version_id uuid, p_decisions jsonb, p_parameter_inputs jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
  workspace uuid := api.current_workspace_id();
  preview jsonb;
  rec api.records;
  actor text := api.current_user_id();
  conflict jsonb;
  decision jsonb;
  item jsonb;
  target api.notebook_template_versions;
  target_placement jsonb;
  mapped jsonb;
  instance api.sheet_instances;
  apply_result jsonb;
  inserted jsonb;
BEGIN
 IF p_record_id IS NOT NULL THEN PERFORM internal.assert_object_access('record',p_record_id,'edit'); END IF;
  IF workspace IS NULL OR actor IS NULL OR NOT api.is_workspace_writer(workspace) THEN
    RAISE EXCEPTION 'workspace member required' USING ERRCODE = '42501';
  END IF;
  SELECT * INTO rec FROM api.records WHERE id = p_record_id AND workspace_id = workspace FOR UPDATE;
  IF rec.id IS NULL THEN RAISE EXCEPTION 'record not found in active workspace' USING ERRCODE = '42501'; END IF;
  IF rec.locked_at IS NOT NULL THEN RAISE EXCEPTION 'record is locked' USING ERRCODE = 'SB011'; END IF;
  IF rec.structure_version <> p_expected_structure_version THEN
    RAISE EXCEPTION 'structure version mismatch: expected %, got %',
      p_expected_structure_version, rec.structure_version USING ERRCODE = 'SB001';
  END IF;
  preview := api.preview_notebook_template_upgrade(p_record_id, p_target_version_id);
  IF jsonb_typeof(coalesce(p_decisions,'[]'::jsonb)) <> 'array' THEN
    RAISE EXCEPTION 'upgrade decisions are required' USING ERRCODE = 'SB090';
  END IF;
  FOR conflict IN SELECT value FROM jsonb_array_elements(coalesce(preview->'conflicts','[]'::jsonb)) LOOP
    SELECT value INTO decision
      FROM jsonb_array_elements(p_decisions) value
      WHERE value->>'conflictId' = conflict->>'id';
    IF decision IS NULL OR NOT (conflict->'allowedOutcomes' @> jsonb_build_array(decision->>'outcome')) THEN
      RAISE EXCEPTION 'invalid or stale Template upgrade decision' USING ERRCODE = 'SB090';
    END IF;
  END LOOP;

  FOR conflict IN SELECT value FROM jsonb_array_elements(coalesce(preview->'conflicts','[]'::jsonb)) LOOP
    SELECT value INTO decision FROM jsonb_array_elements(p_decisions) value WHERE value->>'conflictId' = conflict->>'id';
    IF decision->>'outcome' = 'retarget' THEN
      SELECT * INTO target FROM api.notebook_template_versions WHERE id = p_target_version_id;
      SELECT value INTO target_placement
        FROM jsonb_array_elements(target.configuration->'placements') value
        WHERE value->>'id' = conflict->>'placementId';
      mapped := internal.template_parameter_inputs_for_placement(
        target_placement, coalesce(p_parameter_inputs,'[]'::jsonb)
      );
      apply_result := api.apply_sheet_instance_definition_upgrade(
        (conflict->>'instanceId')::uuid,
        (SELECT si.revision FROM api.sheet_instances si WHERE si.id = (conflict->>'instanceId')::uuid),
        (target_placement->>'definitionVersionId')::uuid,
        coalesce(decision->'instanceDecisions','[]'::jsonb),
        mapped
      );
      IF apply_result->>'status' IS DISTINCT FROM 'applied' THEN
        RAISE EXCEPTION 'Sheet Instance upgrade did not apply' USING ERRCODE = 'SB090';
      END IF;
    END IF;
  END LOOP;

  FOR item IN SELECT value FROM jsonb_array_elements(coalesce(preview->'automatic','[]'::jsonb)) LOOP
    IF item->>'kind' = 'sheet-definition-compatible' THEN
      SELECT * INTO target FROM api.notebook_template_versions WHERE id = p_target_version_id;
      SELECT value INTO target_placement
        FROM jsonb_array_elements(target.configuration->'placements') value
        WHERE value->>'id' = item->>'placementId';
      mapped := internal.template_parameter_inputs_for_placement(
        coalesce(target_placement, '{"parameterMappings":[]}'::jsonb),
        coalesce(p_parameter_inputs,'[]'::jsonb)
      );
      PERFORM api.apply_sheet_instance_definition_upgrade(
        (item->>'instanceId')::uuid,
        (SELECT si.revision FROM api.sheet_instances si WHERE si.id = (item->>'instanceId')::uuid),
        (item->>'targetDefinitionVersionId')::uuid,
        '[]'::jsonb,
        mapped
      );
    ELSIF item->>'kind' = 'placement-added' THEN
      SELECT * INTO target FROM api.notebook_template_versions WHERE id = p_target_version_id;
      SELECT value INTO target_placement
        FROM jsonb_array_elements(target.configuration->'placements') value
        WHERE value->>'id' = item->>'placementId';
      IF target_placement->>'kind' = 'narrative' THEN
        PERFORM api.insert_block(rec.id, target_placement->>'blockType', target_placement->'payload', 1, NULL, NULL);
      ELSIF target_placement->>'kind' = 'sheet' THEN
        mapped := internal.template_parameter_inputs_for_placement(target_placement, coalesce(p_parameter_inputs,'[]'::jsonb));
        instance := api.create_sheet_instance_from_definition(
          rec.workspace_id,
          coalesce(nullif(btrim(target_placement->>'title'),''), 'Notebook sheet'),
          NULL,
          (target_placement->>'definitionVersionId')::uuid,
          rec.project_id,
          rec.id,
          internal.definition_derived_instance_state(),
          mapped
        );
        inserted := api.insert_sheet_instance_block(rec.id, NULL, NULL, instance.id);
        PERFORM internal.assign_sheet_block_template_placement(
          (inserted->'block'->>'id')::uuid,
          (target_placement->>'id')::uuid
        );
      END IF;
    END IF;
  END LOOP;

  PERFORM set_config('sheetbase.notebook_template_upgrade', 'v1', true);
  UPDATE api.records
    SET source_notebook_template_version_id = p_target_version_id,
        updated_at = now(),
        updated_by_user_id = actor
    WHERE id = rec.id
  RETURNING * INTO rec;
  INSERT INTO api.notebook_template_upgrades(
    workspace_id, record_id, source_version_id, target_version_id, decisions, actor_user_id
  ) VALUES (
    rec.workspace_id, rec.id,
    (preview->>'sourceVersionId')::uuid, p_target_version_id,
    coalesce(p_decisions,'[]'::jsonb), actor
  );
  RETURN jsonb_build_object('record', to_jsonb(rec), 'preview', preview);
END
$$;
--> statement-breakpoint
