    CONSTRAINT chk_approval_requests_required_approvals CHECK ((required_approvals >= 1)),
    CONSTRAINT chk_approval_requests_roles CHECK ((required_approver_roles <@ ARRAY['owner'::text, 'admin'::text, 'member'::text, 'steward'::text, 'scientist'::text, 'analyst'::text, 'reviewer'::text, 'viewer'::text])),
    CONSTRAINT chk_approval_requests_state CHECK ((state = ANY (ARRAY['pending'::text, 'approved'::text, 'returned'::text, 'withdrawn'::text])))
