    updated_by_credential_id uuid,
    display_id text,
    CONSTRAINT chk_sheet_instances_created_by_actor CHECK ((NOT ((created_by_user_id IS NOT NULL) AND (created_by_credential_id IS NOT NULL)))),
    CONSTRAINT chk_sheet_instances_description CHECK (((description IS NULL) OR (length(description) <= 2000))),
    CONSTRAINT chk_sheet_instances_lifecycle CHECK ((lifecycle = ANY (ARRAY['active'::text, 'archived'::text]))),
    CONSTRAINT chk_sheet_instances_name CHECK (((length(btrim(name)) >= 1) AND (length(btrim(name)) <= 200))),
    CONSTRAINT chk_sheet_instances_revision CHECK ((revision > 0)),
    CONSTRAINT chk_sheet_instances_updated_by_actor CHECK ((NOT ((updated_by_user_id IS NOT NULL) AND (updated_by_credential_id IS NOT NULL))))
);
