    AS $$
DECLARE instance_row api.sheet_instances; actor text:=api.current_user_id();
BEGIN
 IF p_instance_id IS NOT NULL THEN PERFORM internal.assert_object_access('instance',p_instance_id,'edit'); END IF; SELECT * INTO instance_row FROM api.sheet_instances WHERE id=p_instance_id FOR UPDATE; IF instance_row.id IS NULL OR NOT api.is_workspace_writer(instance_row.workspace_id) THEN RAISE EXCEPTION 'workspace member required' USING ERRCODE='42501'; END IF; IF instance_row.lifecycle<>'active' THEN RAISE EXCEPTION 'Sheet Instance is already archived' USING ERRCODE='SB073'; END IF; IF instance_row.revision<>p_expected_revision THEN RAISE EXCEPTION 'Sheet Instance revision conflict' USING ERRCODE='SB073'; END IF; PERFORM set_config('sheetbase.sheet_instance_write','rpc-v1',true); UPDATE api.sheet_instances SET lifecycle='archived',revision=revision+1,updated_at=now(),updated_by_user_id=actor WHERE id=instance_row.id RETURNING * INTO instance_row; RETURN instance_row; END $$;
