CREATE FUNCTION api.assign_task_resource(p_workspace_id uuid, p_task_id uuid, p_calendar_resource_id uuid, p_starts_at timestamp with time zone, p_ends_at timestamp with time zone, p_notes text DEFAULT NULL::text) RETURNS api.study_task_resources
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
  v_ws_id uuid;
  v_row "api"."study_task_resources";
  v_resource "api"."calendar_resources";
  v_conflict "api"."study_task_resources";
  v_cal_conflict "api"."calendar_bookings";
BEGIN
 IF p_task_id IS NOT NULL THEN PERFORM internal.assert_object_access('task',p_task_id,'edit'); END IF;
  v_ws_id := "api"."current_workspace_id"();
  IF v_ws_id IS NULL OR v_ws_id <> p_workspace_id THEN
    RAISE EXCEPTION 'not a member of the target workspace' USING ERRCODE = '42501';
  END IF;
  IF p_ends_at <= p_starts_at THEN
    RAISE EXCEPTION 'ends_at must be after starts_at' USING ERRCODE = 'SB032';
  END IF;

  -- Verify task.
  PERFORM 1 FROM "api"."study_tasks"
    WHERE id = p_task_id AND workspace_id = v_ws_id FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'task not found in active workspace' USING ERRCODE = 'SB026';
  END IF;

  -- Lock the resource row.
  SELECT * INTO v_resource FROM "api"."calendar_resources"
    WHERE id = p_calendar_resource_id AND workspace_id = v_ws_id FOR UPDATE;
  IF v_resource IS NULL THEN
    RAISE EXCEPTION 'calendar resource not found in active workspace' USING ERRCODE = 'SB021';
  END IF;

  -- Overbooking check against study task resources.
  SELECT * INTO v_conflict FROM "api"."study_task_resources"
    WHERE calendar_resource_id = p_calendar_resource_id
      AND workspace_id = v_ws_id
      AND tstzrange(starts_at, ends_at) && tstzrange(p_starts_at, p_ends_at)
    LIMIT 1;
  IF v_conflict.id IS NOT NULL THEN
    RAISE EXCEPTION 'resource % is overbooked: overlaps with task resource %',
      v_resource.name, v_conflict.id USING ERRCODE = 'SB030';
  END IF;

  -- Overbooking check against calendar bookings.
  SELECT * INTO v_cal_conflict FROM "api"."calendar_bookings"
    WHERE resource_id = p_calendar_resource_id
      AND workspace_id = v_ws_id
      AND status <> 'cancelled'
      AND tstzrange(starts_at, ends_at) && tstzrange(p_starts_at, p_ends_at)
    LIMIT 1;
  IF v_cal_conflict.id IS NOT NULL THEN
    RAISE EXCEPTION 'resource % is booked by calendar booking %',
      v_resource.name, v_cal_conflict.id USING ERRCODE = 'SB030';
  END IF;

  INSERT INTO "api"."study_task_resources"
    (workspace_id, task_id, calendar_resource_id, starts_at, ends_at,
     notes, created_by_user_id)
  VALUES
    (v_ws_id, p_task_id, p_calendar_resource_id, p_starts_at, p_ends_at,
     p_notes, "api"."current_user_id"())
  RETURNING * INTO v_row;

  RETURN v_row;
END;
$$;
--> statement-breakpoint
ALTER FUNCTION api.assign_task_resource(p_workspace_id uuid, p_task_id uuid, p_calendar_resource_id uuid, p_starts_at timestamp with time zone, p_ends_at timestamp with time zone, p_notes text) OWNER TO migrator;
--> statement-breakpoint
CREATE FUNCTION api.audit_events(p_entity_type text DEFAULT NULL::text, p_operation text DEFAULT NULL::text, p_actor_user_id text DEFAULT NULL::text, p_from timestamp with time zone DEFAULT NULL::timestamp with time zone, p_to timestamp with time zone DEFAULT NULL::timestamp with time zone, p_search text DEFAULT NULL::text, p_object uuid DEFAULT NULL::uuid, p_before_sequence bigint DEFAULT NULL::bigint, p_limit integer DEFAULT 50) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
  v_claims jsonb;
  v_workspace uuid;
  v_role text;
  v_privileged boolean;
  v_search_like text;
  v_limit integer;
BEGIN
  v_claims := api.claim_probe();
  IF v_claims IS NULL
     OR nullif(v_claims->>'sub', '') IS NULL
     OR nullif(v_claims->>'session_id', '') IS NULL
     OR v_claims->>'role' <> 'authenticated' THEN
    RAISE EXCEPTION 'audit denied' USING ERRCODE = '42501';
  END IF;
  v_workspace := nullif(v_claims->>'workspace_id', '')::uuid;
  IF v_workspace IS NULL OR NOT api.is_workspace_member(v_workspace) THEN
    RAISE EXCEPTION 'audit denied' USING ERRCODE = '42501';
  END IF;

  -- Suspended members lost their seat: fail closed entirely rather than
  -- serving the workspace-scoped subset.
  SELECT membership.role INTO v_role
    FROM api.workspace_memberships membership
   WHERE membership.workspace_id = v_workspace
     AND membership.user_id = api.current_user_id()
     AND membership.suspended_at IS NULL;
  IF v_role IS NULL THEN
    RAISE EXCEPTION 'audit denied' USING ERRCODE = '42501';
  END IF;
  v_privileged := v_role IN ('owner', 'admin', 'steward');

  v_limit := LEAST(GREATEST(COALESCE(p_limit, 50), 1), 200);
  -- ILIKE wildcard escaping: backslash first, then escape % and _ each as
  -- themselves (\% and \_) so user input matches literally.
  v_search_like := '%' ||
    replace(replace(replace(btrim(COALESCE(p_search, '')), '\', '\\'), '%', '\%'), '_', '\_') ||
    '%';

  RETURN (
    WITH matches AS MATERIALIZED (
      SELECT e.sequence AS seq,
             e.id AS event_id,
             e.created_at AS created_at,
             e.entity_type AS entity_type,
             e.entity_uuid AS entity_uuid,
             e.operation AS operation,
             e.record_id AS record_id,
             e.project_id AS project_id,
             e.actor_user_id AS actor_user_id,
             e.actor_credential_id AS actor_credential_id,
             e.client_id AS client_id,
             e.payload AS payload,
             actor.name AS actor_name
      FROM api.change_events e
      LEFT JOIN "internal"."user" actor ON actor.id = e.actor_user_id
      WHERE e.workspace_id = v_workspace AND internal.can_read_change_event(e)
        AND (p_entity_type IS NULL OR e.entity_type = p_entity_type)
        AND (p_operation IS NULL OR e.operation = p_operation)
        AND (p_actor_user_id IS NULL OR e.actor_user_id = p_actor_user_id)
        AND (p_from IS NULL OR e.created_at >= p_from)
        AND (p_to IS NULL OR e.created_at < p_to)
        AND (p_before_sequence IS NULL OR e.sequence < p_before_sequence)
        -- Object-readability boundary. See the contract note in 0134: this
        -- implements each underlying object's canonical SELECT rule, which
        -- is workspace membership for every governed class, narrowed
        -- further for admin/security event classes.
        AND (
          v_privileged
          OR e.entity_type NOT IN (
            'api_credential', 'workspace_invitation', 'workspace_settings',
            'project_access'
          )
        )
        AND (
          btrim(COALESCE(p_search, '')) = ''
          OR e.payload::text ILIKE v_search_like
          OR e.entity_type ILIKE v_search_like
          OR e.operation ILIKE v_search_like
        )
        AND (
          p_object IS NULL
          OR e.entity_uuid = p_object
          OR e.record_id = p_object
          OR e.payload->>'datasetId' = p_object::text
          OR e.payload->>'templateId' = p_object::text
          OR e.payload->>'definitionId' = p_object::text
          OR e.payload->>'instanceId' = p_object::text
          OR e.payload->>'rotatedFromCredentialId' = p_object::text
          OR e.payload->>'rotatedToCredentialId' = p_object::text
          OR e.payload->>'extension_id' = p_object::text
          OR e.payload->>'extensionId' = p_object::text
        )
    ),
    page AS (
      SELECT * FROM matches ORDER BY seq DESC LIMIT v_limit
    )
    SELECT jsonb_build_object(
      'formatVersion', 1,
      'events', COALESCE((
        SELECT jsonb_agg(jsonb_build_object(
          'sequence', seq,
          'id', event_id,
          'createdAt', to_char(created_at AT TIME ZONE 'UTC',
            'YYYY-MM-DD"T"HH24:MI:SS.US"Z"'),
          'entityType', entity_type,
          'entityUuid', entity_uuid,
          'operation', operation,
          'recordId', record_id,
          'projectId', project_id,
          'actorUserId', actor_user_id,
          'actorName', actor_name,
          'actorCredentialId', actor_credential_id,
          'clientId', client_id,
          'payload', payload
        ) ORDER BY seq DESC)
        FROM page
      ), '[]'::jsonb),
      'hasMore', EXISTS (SELECT 1 FROM matches OFFSET v_limit),
      'nextCursor', (SELECT MIN(seq) FROM page)
    )
  );
END;
$$;
--> statement-breakpoint
ALTER FUNCTION api.audit_events(p_entity_type text, p_operation text, p_actor_user_id text, p_from timestamp with time zone, p_to timestamp with time zone, p_search text, p_object uuid, p_before_sequence bigint, p_limit integer) OWNER TO migrator;
