CREATE FUNCTION api.bind_chart_revision(p_block_id uuid, p_revision_id uuid, p_expected_version integer) RETURNS api.blocks
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
  v_block "api"."blocks";
  v_owner "api"."records";
  v_rev "api"."revisions";
  v_rev_owner "api"."records";
  v_frozen jsonb;
  v_payload jsonb;
BEGIN
 IF p_block_id IS NOT NULL THEN PERFORM internal.assert_object_access('block',p_block_id,'edit'); END IF;
 IF p_revision_id IS NOT NULL THEN PERFORM internal.assert_object_access('revision',p_revision_id,'edit'); END IF;
  SELECT * INTO v_block FROM "api"."blocks" WHERE id = p_block_id FOR UPDATE;
  IF v_block.id IS NULL THEN
    RAISE EXCEPTION 'block not found in active workspace' USING ERRCODE = '42501';
  END IF;
  IF v_block.type <> 'chart' THEN
    RAISE EXCEPTION 'block is not a chart' USING ERRCODE = '23514';
  END IF;
  IF v_block.version <> p_expected_version THEN
    RAISE EXCEPTION 'block version mismatch: expected %, got %',
      p_expected_version, v_block.version USING ERRCODE = 'SB001';
  END IF;
  v_frozen := v_block.payload->'frozen';
  IF jsonb_typeof(v_frozen) IS DISTINCT FROM 'object' THEN
    RAISE EXCEPTION 'chart is not frozen' USING ERRCODE = '23514';
  END IF;
  IF v_frozen->>'revisionId' IS NOT NULL THEN
    RAISE EXCEPTION 'chart is already bound to a revision' USING ERRCODE = '23514';
  END IF;
  SELECT * INTO v_owner FROM "api"."records" WHERE id = v_block.record_id;
  IF v_owner.id IS NULL
     OR v_owner.workspace_id IS DISTINCT FROM "api"."current_workspace_id"()
     OR NOT api.is_workspace_writer(v_owner.workspace_id) THEN
    RAISE EXCEPTION 'block not found in active workspace' USING ERRCODE = '42501';
  END IF;
  SELECT * INTO v_rev FROM "api"."revisions" WHERE id = p_revision_id;
  IF v_rev.id IS NULL THEN RAISE EXCEPTION 'revision not found' USING ERRCODE = '23503'; END IF;
  SELECT * INTO v_rev_owner FROM "api"."records" WHERE id = v_rev.record_id;
  IF v_rev_owner.id IS NULL
     OR v_rev_owner.workspace_id IS DISTINCT FROM v_owner.workspace_id
     OR v_rev.record_id <> v_block.record_id THEN
    RAISE EXCEPTION 'revision does not belong to this record' USING ERRCODE = '23514';
  END IF;
  v_payload := jsonb_set(v_block.payload, ARRAY['frozen','revisionId'], to_jsonb(p_revision_id::text));
  UPDATE "api"."blocks"
    SET payload = v_payload,
        version = v_block.version + 1,
        updated_by_user_id = "api"."current_user_id"()
    WHERE id = p_block_id
    RETURNING * INTO v_block;
  RETURN v_block;
END;
$$;
--> statement-breakpoint
ALTER FUNCTION api.bind_chart_revision(p_block_id uuid, p_revision_id uuid, p_expected_version integer) OWNER TO migrator;
--> statement-breakpoint
CREATE FUNCTION api.bind_report_section_source(p_workspace_id uuid, p_section_id uuid, p_source_revision_id uuid, p_source_ref jsonb DEFAULT '{}'::jsonb) RETURNS api.report_sections
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
  v api.report_sections;
  v_rev api.revisions;
  v_snapshot jsonb;
  v_block_id text;
  v_blocks jsonb;
  v_block jsonb;
  v_frozen jsonb;
  v_status text := 'valid';
  v_detail jsonb := '{}'::jsonb;
BEGIN
 IF p_section_id IS NOT NULL THEN PERFORM internal.assert_object_access('section',p_section_id,'edit'); END IF;
 IF p_source_revision_id IS NOT NULL THEN PERFORM internal.assert_object_access('revision',p_source_revision_id,'view'); END IF;
 IF NOT internal.sources_readable(p_source_ref) THEN RAISE EXCEPTION 'Source access denied' USING ERRCODE='42501'; END IF;
  IF api.current_workspace_id() IS DISTINCT FROM p_workspace_id THEN
    RAISE EXCEPTION 'wrong workspace' USING ERRCODE='SB033';
  END IF;
  SELECT * INTO v FROM api.report_sections WHERE id=p_section_id AND workspace_id=p_workspace_id;
  IF v IS NULL THEN RAISE EXCEPTION 'section not found' USING ERRCODE='SB048'; END IF;
  SELECT * INTO v_rev FROM api.revisions WHERE id=p_source_revision_id AND workspace_id=p_workspace_id;
  IF v_rev IS NULL THEN RAISE EXCEPTION 'revision not found' USING ERRCODE='SB049'; END IF;
  v_snapshot := COALESCE(v_rev.canonical_snapshot, v_rev.block_snapshot);
  -- Freeze the referenced block, or the whole snapshot for record_metadata.
  v_block_id := p_source_ref->>'blockId';
  IF v_block_id IS NOT NULL THEN
    v_blocks := COALESCE(v_snapshot->'blocks', v_snapshot);
    IF jsonb_typeof(v_blocks)='array' THEN
      SELECT elem INTO v_block FROM jsonb_array_elements(v_blocks) elem WHERE elem->>'id'=v_block_id LIMIT 1;
    ELSIF jsonb_typeof(v_blocks)='object' THEN
      v_block := v_blocks->v_block_id;
    END IF;
    IF v_block IS NULL THEN
      v_status := 'missing_source';
      v_detail := jsonb_build_object('blockId',v_block_id,'reason','block not found in frozen snapshot');
      v_frozen := '{}'::jsonb;
    ELSE
      v_frozen := jsonb_build_object('block',v_block,'revisionDigest',v_rev.integrity_digest);
    END IF;
  ELSE
    v_frozen := jsonb_build_object('snapshot',v_snapshot,'revisionDigest',v_rev.integrity_digest);
  END IF;
  -- Flag locked source records: still valid frozen evidence, but surfaced.
  IF EXISTS(SELECT 1 FROM api.records WHERE id=v_rev.record_id AND locked_at IS NOT NULL) THEN
    v_status := 'locked';
    v_detail := v_detail || jsonb_build_object('lockedAt', (SELECT locked_at FROM api.records WHERE id=v_rev.record_id));
  END IF;
  UPDATE api.report_sections SET
    source_revision_id=p_source_revision_id,
    source_ref=COALESCE(p_source_ref,'{}'::jsonb),
    frozen_payload=v_frozen,
    validation_status=v_status,
    validation_detail=v_detail,
    updated_at=now(),
    updated_by_user_id=api.current_user_id()
  WHERE id=p_section_id RETURNING * INTO v;
  RETURN v;
END $$;
--> statement-breakpoint
