    CONSTRAINT chk_pipeline_runs_actor_xor CHECK (((actor_user_id IS NULL) <> (actor_credential_id IS NULL))),
    CONSTRAINT chk_pipeline_runs_attempt CHECK ((attempt >= 1)),
    CONSTRAINT chk_pipeline_runs_digest CHECK (((input_digest IS NULL) OR (input_digest ~ '^[0-9a-f]{64}$'::text))),
    CONSTRAINT chk_pipeline_runs_error CHECK (((status <> 'failed'::text) OR ((error_code IS NOT NULL) AND ((length(btrim(error_code)) >= 1) AND (length(btrim(error_code)) <= 100))))),
    CONSTRAINT chk_pipeline_runs_input_versions CHECK ((jsonb_typeof(input_versions) = 'object'::text)),
    CONSTRAINT chk_pipeline_runs_occurrence CHECK (((trigger_occurrence_id IS NULL) OR (((length(trigger_occurrence_id) >= 8) AND (length(trigger_occurrence_id) <= 128)) AND (trigger_occurrence_id ~ '^[a-z]+:[A-Za-z0-9:_+-]+$'::text)))),
    CONSTRAINT chk_pipeline_runs_occurrence_trigger CHECK ((((trigger_kind = 'manual'::text) AND ((trigger_occurrence_id IS NULL) OR (trigger_occurrence_id ~~ 'manual:%'::text))) OR ((trigger_kind <> 'manual'::text) AND (trigger_occurrence_id IS NOT NULL)))),
    CONSTRAINT chk_pipeline_runs_parameters CHECK ((jsonb_typeof(parameters) = 'object'::text)),
    CONSTRAINT chk_pipeline_runs_schedule CHECK ((((trigger_kind = 'manual'::text) AND (schedule_id IS NULL)) OR ((trigger_kind = 'event'::text) AND (trigger_occurrence_id ~~ 'webhook:%'::text) AND (schedule_id IS NULL)) OR ((trigger_kind = ANY (ARRAY['scheduled'::text, 'event'::text])) AND (trigger_occurrence_id IS NOT NULL) AND (schedule_id IS NOT NULL)))),
    CONSTRAINT chk_pipeline_runs_status CHECK ((status = ANY (ARRAY['running'::text, 'waiting'::text, 'succeeded'::text, 'failed'::text, 'cancelled'::text]))),
    CONSTRAINT chk_pipeline_runs_trigger CHECK ((trigger_kind = ANY (ARRAY['manual'::text, 'scheduled'::text, 'event'::text])))
