CREATE FUNCTION api.chart_filter_matches(p_row jsonb, p_filter jsonb) RETURNS boolean
    LANGUAGE plpgsql IMMUTABLE PARALLEL SAFE
    AS $$
DECLARE
  v_field text := p_filter->>'fieldId';
  v_op text := p_filter->>'op';
  v_value jsonb := p_filter->'value';
  v_cell jsonb := p_row->v_field;
  v_num numeric;
  v_arg numeric;
  v_arg2 numeric;
BEGIN
  IF v_field IS NULL OR v_op IS NULL THEN RETURN false; END IF;
  v_num := "api"."chart_to_number"(v_cell #>> '{}');
  CASE v_op
    WHEN 'eq' THEN RETURN v_cell = v_value;
    WHEN 'ne' THEN RETURN v_cell IS DISTINCT FROM v_value;
    WHEN 'gt' THEN
      v_arg := "api"."chart_to_number"(v_value #>> '{}');
      RETURN v_num IS NOT NULL AND v_arg IS NOT NULL AND v_num > v_arg;
    WHEN 'gte' THEN
      v_arg := "api"."chart_to_number"(v_value #>> '{}');
      RETURN v_num IS NOT NULL AND v_arg IS NOT NULL AND v_num >= v_arg;
    WHEN 'lt' THEN
      v_arg := "api"."chart_to_number"(v_value #>> '{}');
      RETURN v_num IS NOT NULL AND v_arg IS NOT NULL AND v_num < v_arg;
    WHEN 'lte' THEN
      v_arg := "api"."chart_to_number"(v_value #>> '{}');
      RETURN v_num IS NOT NULL AND v_arg IS NOT NULL AND v_num <= v_arg;
    WHEN 'in' THEN
      RETURN jsonb_typeof(v_value) = 'array' AND EXISTS (
        SELECT 1 FROM jsonb_array_elements(v_value) el WHERE el = v_cell
      );
    WHEN 'between' THEN
      IF jsonb_typeof(v_value) IS DISTINCT FROM 'array' OR jsonb_array_length(v_value) <> 2 THEN
        RETURN false;
      END IF;
      v_arg := "api"."chart_to_number"(v_value->0 #>> '{}');
      v_arg2 := "api"."chart_to_number"(v_value->1 #>> '{}');
      RETURN v_num IS NOT NULL AND v_arg IS NOT NULL AND v_arg2 IS NOT NULL
        AND v_num >= v_arg AND v_num <= v_arg2;
    WHEN 'is_null' THEN
      RETURN v_cell IS NULL OR v_cell = 'null'::jsonb OR v_cell = '""'::jsonb;
    WHEN 'not_null' THEN
      RETURN NOT (v_cell IS NULL OR v_cell = 'null'::jsonb OR v_cell = '""'::jsonb);
    ELSE RETURN false;
  END CASE;
END;
$$;
--> statement-breakpoint
ALTER FUNCTION api.chart_filter_matches(p_row jsonb, p_filter jsonb) OWNER TO migrator;
--> statement-breakpoint
CREATE FUNCTION api.chart_quantile(p_values double precision[], p_p double precision) RETURNS double precision
    LANGUAGE plpgsql IMMUTABLE PARALLEL SAFE
    AS $$
DECLARE
  v_sorted double precision[];
  v_n int;
  v_h double precision;
  v_lo int;
  v_hi int;
BEGIN
  IF p_values IS NULL OR array_length(p_values, 1) IS NULL THEN
    RETURN NULL;
  END IF;
  SELECT array_agg(x ORDER BY x) INTO v_sorted FROM unnest(p_values) AS t(x);
  v_n := array_length(v_sorted, 1);
  v_h := (v_n - 1) * p_p;
  v_lo := floor(v_h)::int;
  v_hi := ceil(v_h)::int;
  RETURN v_sorted[v_lo + 1] + (v_sorted[v_hi + 1] - v_sorted[v_lo + 1]) * (v_h - v_lo);
END;
$$;
--> statement-breakpoint
ALTER FUNCTION api.chart_quantile(p_values double precision[], p_p double precision) OWNER TO migrator;
--> statement-breakpoint
CREATE FUNCTION api.chart_spec_referenced_field_ids(p_spec jsonb) RETURNS text[]
    LANGUAGE plpgsql IMMUTABLE PARALLEL SAFE
    SET search_path TO ''
    AS $$
DECLARE
  ids text[] := ARRAY[]::text[];
  fields jsonb := COALESCE(p_spec->'fields', '{}'::jsonb);
  filter jsonb;
  transformation jsonb;
  params jsonb;
BEGIN
  ids := ARRAY[
    fields->'x'->>'fieldId',
    fields->'y'->>'fieldId',
    fields->'series'->>'fieldId',
    fields->'color'->>'fieldId',
    fields->'size'->>'fieldId',
    fields->'facet'->>'fieldId',
    fields->'facetRow'->>'fieldId',
    fields->'facetCol'->>'fieldId',
    fields->'group'->>'fieldId',
    fields->'shape'->>'fieldId',
    fields->'label'->>'fieldId',
    p_spec#>>'{overlays,errorBars,fieldId}',
    p_spec#>>'{overlays,errorBars,lowerFieldId}',
    p_spec#>>'{overlays,errorBars,upperFieldId}',
    p_spec#>>'{typeParams,heatmap,valueField,fieldId}'
  ];
  IF jsonb_typeof(p_spec->'filters') = 'array' THEN
    FOR filter IN SELECT value FROM jsonb_array_elements(p_spec->'filters')
    LOOP
      ids := ids || (filter->>'fieldId');
    END LOOP;
  END IF;
  IF jsonb_typeof(p_spec->'transformations') = 'array' THEN
    FOR transformation IN SELECT value FROM jsonb_array_elements(p_spec->'transformations')
    LOOP
      params := COALESCE(transformation->'params', '{}'::jsonb);
      ids := ids || ARRAY[
        params->>'fieldId',
        params->>'xField',
        params->>'yField',
        params->>'seriesField'
      ];
    END LOOP;
  END IF;
  RETURN ARRAY(
    SELECT DISTINCT u
      FROM unnest(ids) AS u
     WHERE u IS NOT NULL AND u <> ''
     ORDER BY 1
  );
END;
$$;
--> statement-breakpoint
ALTER FUNCTION api.chart_spec_referenced_field_ids(p_spec jsonb) OWNER TO migrator;
