CREATE FUNCTION api.claim_probe() RETURNS jsonb
    LANGUAGE plpgsql STABLE
    AS $$
DECLARE
  raw text;
  parsed jsonb;
BEGIN
  raw := current_setting('request.jwt.claims', true);
  IF raw IS NULL OR raw = '' THEN
    RETURN NULL;
  END IF;
  BEGIN
    parsed := raw::jsonb;
  EXCEPTION WHEN invalid_text_representation THEN
    RETURN NULL;
  END;
  RETURN parsed;
END;
$$;
