CREATE TABLE api.dataset_value_flags (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    workspace_id uuid NOT NULL,
    dataset_id uuid NOT NULL,
    row_id uuid NOT NULL,
    field_id uuid NOT NULL,
    kind text NOT NULL,
    reason text NOT NULL,
    comment text,
    set_by_user_id text,
    set_at timestamp with time zone DEFAULT now() NOT NULL,
    cleared_at timestamp with time zone,
    cleared_by_user_id text,
    source text DEFAULT 'manual'::text NOT NULL,
    system_rule text,
    evaluated_value jsonb,
    threshold jsonb,
    evaluated_at timestamp with time zone,
    cleared_reason text,
    CONSTRAINT chk_dataset_value_flags_cleared_reason CHECK (((cleared_reason IS NULL) OR (cleared_at IS NOT NULL))),
    CONSTRAINT chk_dataset_value_flags_kind CHECK ((kind = ANY (ARRAY['out_of_range'::text, 'missing_unit'::text, 'above_curve'::text, 'high_cv'::text]))),
    CONSTRAINT chk_dataset_value_flags_provenance CHECK ((((source = 'manual'::text) AND (system_rule IS NULL)) OR ((source = 'system'::text) AND (system_rule IS NOT NULL)))),
    CONSTRAINT chk_dataset_value_flags_reason CHECK (((length(btrim(reason)) >= 1) AND (length(btrim(reason)) <= 200))),
    CONSTRAINT chk_dataset_value_flags_source CHECK ((source = ANY (ARRAY['manual'::text, 'system'::text]))),
    CONSTRAINT chk_dataset_value_flags_system_rule CHECK (((system_rule IS NULL) OR (system_rule = ANY (ARRAY['out_of_range'::text, 'missing_unit'::text, 'high_cv'::text]))))
);
