CREATE FUNCTION api.client_portal_preview_projects(p_client_id uuid) RETURNS TABLE(project_id uuid, display_id text, title text, stage text, status text, modality text, lead_name text, last_update timestamp with time zone, client_name text, client_code text)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
BEGIN
  IF NOT EXISTS (
    SELECT 1 FROM api.clients c
     WHERE c.id = p_client_id
       AND c.workspace_id = api.current_workspace_id()
       AND api.is_workspace_writer(c.workspace_id)
  ) THEN
    RAISE EXCEPTION 'Client denied' USING ERRCODE = '42501';
  END IF;
  RETURN QUERY
  SELECT p.id, p.display_id, p.title, p.stage, p.status, p.modality,
         u.name,
         (SELECT max(r.updated_at)
            FROM api.records r
           WHERE r.project_id = p.id AND r.deleted_at IS NULL),
         c.name, c.code
    FROM api.projects p
    JOIN api.clients c ON c.id = p.client_id
    LEFT JOIN internal."user" u ON u.id = p.lead_user_id
   WHERE c.id = p_client_id
     AND c.workspace_id = api.current_workspace_id()
     AND p.auto_share_to_client
   ORDER BY p.title;
END $$;
