    CONSTRAINT chk_connector_runs_actor_xor CHECK (((actor_user_id IS NULL) <> (actor_credential_id IS NULL))),
    CONSTRAINT chk_connector_runs_attempt CHECK ((attempt >= 1)),
    CONSTRAINT chk_connector_runs_error CHECK (((status <> 'failed'::text) OR ((error_code IS NOT NULL) AND ((length(btrim(error_code)) >= 1) AND (length(btrim(error_code)) <= 100))))),
    CONSTRAINT chk_connector_runs_selector CHECK (((selector_digest IS NULL) OR ((length(btrim(selector_digest)) >= 16) AND (length(btrim(selector_digest)) <= 128)))),
    CONSTRAINT chk_connector_runs_status CHECK ((status = ANY (ARRAY['running'::text, 'succeeded'::text, 'failed'::text]))),
