CREATE TABLE api.calendar_resources (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    workspace_id uuid NOT NULL,
    project_id uuid,
    name text NOT NULL,
    code text NOT NULL,
    resource_type text DEFAULT 'instrument'::text NOT NULL,
    location text,
    capacity integer DEFAULT 1 NOT NULL,
    timezone text DEFAULT 'UTC'::text NOT NULL,
    status text DEFAULT 'active'::text NOT NULL,
    metadata jsonb DEFAULT '{}'::jsonb NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    created_by_user_id text,
    updated_by_user_id text,
    CONSTRAINT chk_calendar_resources_capacity CHECK ((capacity > 0)),
    CONSTRAINT chk_calendar_resources_code CHECK (((length(btrim(code)) >= 1) AND (length(btrim(code)) <= 100))),
    CONSTRAINT chk_calendar_resources_name CHECK (((length(btrim(name)) >= 1) AND (length(btrim(name)) <= 200))),
    CONSTRAINT chk_calendar_resources_status CHECK ((status = ANY (ARRAY['active'::text, 'inactive'::text]))),
    CONSTRAINT chk_calendar_resources_type CHECK ((resource_type = ANY (ARRAY['instrument'::text, 'room'::text, 'equipment'::text])))
);
