    id uuid DEFAULT gen_random_uuid() NOT NULL,
    workspace_id uuid NOT NULL,
    predecessor_id uuid NOT NULL,
    successor_id uuid NOT NULL,
    dependency_type text DEFAULT 'finish_to_start'::text NOT NULL,
    lag_days integer DEFAULT 0 NOT NULL,
    is_external boolean DEFAULT false NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    created_by_user_id text,
    CONSTRAINT chk_study_task_deps_self CHECK ((predecessor_id <> successor_id)),
    CONSTRAINT chk_study_task_deps_type CHECK ((dependency_type = ANY (ARRAY['finish_to_start'::text, 'start_to_start'::text, 'finish_to_finish'::text, 'start_to_finish'::text])))
);
