    last_run_at timestamp with time zone,
    next_run_at timestamp with time zone,
    last_evaluated_at timestamp with time zone,
    last_evaluated_sequence bigint,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    created_by_user_id text,
    input_watermarks jsonb DEFAULT '{}'::jsonb NOT NULL,
    CONSTRAINT chk_pipeline_schedules_kind CHECK ((kind = ANY (ARRAY['interval'::text, 'daily'::text, 'cron'::text, 'event'::text]))),
    CONSTRAINT chk_pipeline_schedules_sequence CHECK (((last_evaluated_sequence IS NULL) OR (last_evaluated_sequence >= 0))),
    CONSTRAINT chk_pipeline_schedules_spec CHECK ((jsonb_typeof(spec) = 'object'::text)),
    CONSTRAINT chk_pipeline_schedules_watermarks CHECK ((jsonb_typeof(input_watermarks) = 'object'::text))
);
--> statement-breakpoint
ALTER TABLE api.pipeline_schedules OWNER TO migrator;
--> statement-breakpoint
COMMENT ON TABLE api.pipeline_schedules IS 'AUTO-02 schedule/event triggers. interval/daily schedules are evaluated by the server sweep; event schedules fire when the sweep observes matching change_events past last_evaluated_sequence.';
--> statement-breakpoint
CREATE FUNCTION api.create_pipeline_schedule(p_workspace_id uuid, p_definition_id uuid, p_kind text, p_spec jsonb, p_enabled boolean DEFAULT true) RETURNS api.pipeline_schedules
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
  v api.pipeline_schedules;
  v_definition api.pipeline_definitions;
  v_spec jsonb;
BEGIN
  IF api.current_workspace_id() IS DISTINCT FROM p_workspace_id THEN
    RAISE EXCEPTION 'wrong workspace' USING ERRCODE = 'SB033';
  END IF;
  PERFORM api.require_capability(p_workspace_id, 'pipelines.manage');
  SELECT * INTO v_definition FROM api.pipeline_definitions
   WHERE id = p_definition_id AND workspace_id = p_workspace_id;
  IF v_definition IS NULL THEN
    RAISE EXCEPTION 'pipeline definition not found' USING ERRCODE = 'SB036';
  END IF;
  IF p_kind NOT IN ('interval', 'daily', 'cron', 'event') THEN
    RAISE EXCEPTION 'invalid schedule kind' USING ERRCODE = 'SB034';
  END IF;
  v_spec := api.validate_pipeline_schedule_spec(p_workspace_id, p_kind, p_spec);
  INSERT INTO api.pipeline_schedules(
    workspace_id, definition_id, kind, spec, enabled, next_run_at,
    last_evaluated_sequence, created_by_user_id
  ) VALUES (
    p_workspace_id, p_definition_id, p_kind, v_spec, p_enabled,
    api.pipeline_schedule_next_run(p_kind, v_spec, now()),
    -- A new event trigger watches what happens from now on; it does not
    -- replay the workspace's history.
    CASE WHEN p_kind = 'event' THEN COALESCE((
      SELECT max(sequence) FROM api.change_events WHERE workspace_id = p_workspace_id
    ), 0) END,
    api.current_user_id()
  ) RETURNING * INTO v;
  RETURN v;
END $$;
--> statement-breakpoint
ALTER FUNCTION api.create_pipeline_schedule(p_workspace_id uuid, p_definition_id uuid, p_kind text, p_spec jsonb, p_enabled boolean) OWNER TO migrator;
--> statement-breakpoint
CREATE FUNCTION api.create_plan_from_project(p_target_project_id uuid, p_source_project_id uuid, p_start_date date) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
  v_ws uuid := api.current_workspace_id();
  v_target api.projects;
  v_source api.projects;
  v_first date;
  v_phase api.study_workstreams;
  v_phase_map jsonb := '{}'::jsonb;
  v_phase_new uuid;
  v_task api.study_tasks;
  v_new_task uuid;
  v_deliverable api.study_deliverables;
  v_due timestamptz;
  v_phases integer := 0;
  v_milestones integer := 0;
  v_conditions integer := 0;
BEGIN
  IF p_target_project_id IS NULL
     OR p_source_project_id IS NULL
     OR p_start_date IS NULL THEN
    RAISE EXCEPTION 'target project, source project and start date are required'
      USING ERRCODE = '22023';
  END IF;
  IF p_target_project_id = p_source_project_id THEN
    RAISE EXCEPTION 'a plan cannot be started from itself' USING ERRCODE = '22023';
  END IF;

  SELECT * INTO v_target FROM api.projects
    WHERE id = p_target_project_id AND workspace_id = v_ws;
  IF v_target.id IS NULL THEN
    RAISE EXCEPTION 'target project not found in active workspace' USING ERRCODE = 'SB026';
  END IF;
  IF NOT api.is_workspace_writer(v_ws) THEN
    RAISE EXCEPTION 'plan creation denied' USING ERRCODE = '42501';
  END IF;

  SELECT * INTO v_source FROM api.projects
    WHERE id = p_source_project_id AND workspace_id = v_ws;
  IF v_source.id IS NULL OR NOT internal.can_view_project(v_source.id) THEN
    RAISE EXCEPTION 'source project not found in active workspace' USING ERRCODE = 'SB026';
  END IF;

  -- Offsets are measured from the source plan's first milestone, so a template
  -- keeps its shape whatever start date is chosen.
  SELECT min(t.due_at::date) INTO v_first
    FROM api.study_tasks t
   WHERE t.project_id = p_source_project_id AND t.task_type = 'milestone';
  IF v_first IS NULL THEN
    RAISE EXCEPTION 'the source project has no milestones' USING ERRCODE = '22023';
  END IF;

  -- Recreate only the phases the source plan actually uses.
  FOR v_phase IN
    SELECT w.* FROM api.study_workstreams w
     WHERE w.id IN (
       SELECT DISTINCT t.workstream_id FROM api.study_tasks t
        WHERE t.project_id = p_source_project_id
          AND t.task_type = 'milestone'
          AND t.workstream_id IS NOT NULL)
     ORDER BY w.position, w.id
  LOOP
    v_phase_new := (api.create_study_workstream(
      v_ws, v_phase.name, p_target_project_id, v_phase.color, v_phase.position)).id;
    v_phase_map := v_phase_map || jsonb_build_object(v_phase.id::text, v_phase_new);
    v_phases := v_phases + 1;
  END LOOP;

  FOR v_task IN
    SELECT * FROM api.study_tasks
     WHERE project_id = p_source_project_id AND task_type = 'milestone'
     ORDER BY position, created_at, id
  LOOP
    v_due := (p_start_date + (v_task.due_at::date - v_first))::timestamptz;
    v_new_task := (api.create_study_task(
      p_workspace_id => v_ws,
      p_title => v_task.title,
      p_task_type => 'milestone',
      p_workstream_id => CASE WHEN v_task.workstream_id IS NULL THEN NULL
                              ELSE (v_phase_map ->> v_task.workstream_id::text)::uuid END,
      p_project_id => p_target_project_id,
      p_description => v_task.description,
      p_status => 'not_started',
      p_priority => v_task.priority,
      p_due_at => v_due,
      p_timezone => v_task.timezone,
      p_position => v_task.position,
      p_color => v_task.color,
      p_tags => v_task.tags)).id;
    v_milestones := v_milestones + 1;

    IF v_task.client_visible THEN
      PERFORM api.set_study_task_client_visible(v_new_task, NULL, true, NULL);
    END IF;

    FOR v_deliverable IN
      SELECT * FROM api.study_deliverables
       WHERE task_id = v_task.id
       ORDER BY position NULLS LAST, created_at, id
    LOOP
      PERFORM api.create_study_deliverable(
        v_new_task,
        v_deliverable.name,
        v_deliverable.description,
        'planned',
        CASE WHEN v_deliverable.due_at IS NULL THEN NULL
             ELSE (p_start_date + (v_deliverable.due_at::date - v_first))::timestamptz END);
      v_conditions := v_conditions + 1;
    END LOOP;
  END LOOP;

  RETURN jsonb_build_object(
    'targetProjectId', p_target_project_id,
    'sourceProjectId', p_source_project_id,
    'startDate', p_start_date,
    'phases', v_phases,
    'milestones', v_milestones,
    'conditions', v_conditions);
END $$;
--> statement-breakpoint
ALTER FUNCTION api.create_plan_from_project(p_target_project_id uuid, p_source_project_id uuid, p_start_date date) OWNER TO migrator;
--> statement-breakpoint
CREATE FUNCTION api.create_plate_design(p_workspace_id uuid, p_name text, p_project_id uuid DEFAULT NULL::uuid, p_format text DEFAULT '96_well'::text, p_rows integer DEFAULT 8, p_cols integer DEFAULT 12, p_validation jsonb DEFAULT '{}'::jsonb) RETURNS api.plate_designs
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
  v_row "api"."plate_designs";
BEGIN
 IF p_project_id IS NOT NULL THEN PERFORM internal.assert_object_access('project',p_project_id,'edit'); END IF;
  IF NOT api.is_workspace_writer(p_workspace_id) THEN
    RAISE EXCEPTION 'not a member of the target workspace' USING ERRCODE = '42501';
  END IF;
  IF p_format NOT IN ('96_well') THEN
    RAISE EXCEPTION 'unsupported plate format: %', p_format USING ERRCODE = 'SB005';
  END IF;
  IF p_rows IS NULL OR p_cols IS NULL OR p_rows < 1 OR p_cols < 1
     OR p_rows > 26 OR p_cols > 26 THEN
    RAISE EXCEPTION 'rows and cols must be between 1 and 26' USING ERRCODE = 'SB005';
  END IF;

  INSERT INTO "api"."plate_designs"
    (workspace_id, project_id, name, format, rows, cols, validation,
     created_by_user_id, updated_by_user_id)
  VALUES
    (p_workspace_id, p_project_id, btrim(p_name), p_format, p_rows, p_cols,
     COALESCE(p_validation, '{}'::jsonb),
     "api"."current_user_id"(), "api"."current_user_id"())
  RETURNING * INTO v_row;

  RETURN v_row;
END;
$$;
