CREATE FUNCTION api.create_protocol_version(p_protocol_record_id uuid, p_change_summary text, p_reason text DEFAULT NULL::text) RETURNS api.protocol_versions
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
  v_protocol api.records;
  v_revision api.revisions;
  v_version api.protocol_versions;
  v_next integer;
BEGIN
  SELECT * INTO v_protocol FROM api.records WHERE id = p_protocol_record_id FOR UPDATE;
  IF v_protocol.id IS NULL OR v_protocol.workspace_id IS DISTINCT FROM api.current_workspace_id()
    OR v_protocol.kind <> 'protocol_template' OR v_protocol.deleted_at IS NOT NULL THEN
    RAISE EXCEPTION 'protocol not found' USING ERRCODE = '42501';
  END IF;
  PERFORM api.require_capability(v_protocol.workspace_id, 'record.create');
  SELECT coalesce(max(version), 0) + 1 INTO v_next FROM api.protocol_versions WHERE protocol_record_id = v_protocol.id;
  INSERT INTO api.revisions(
    record_id, structure_version, metadata_version, metadata_snapshot, block_snapshot, reason, created_by_user_id
  )
  SELECT v_protocol.id, v_protocol.structure_version, v_protocol.metadata_version,
    jsonb_build_object('id', v_protocol.id, 'identifier', v_protocol.identifier, 'title', v_protocol.title,
      'status', v_protocol.status, 'properties', v_protocol.properties, 'tags', v_protocol.tags,
      'metadataVersion', v_protocol.metadata_version),
    coalesce(jsonb_agg(to_jsonb(x) ORDER BY x."order") FILTER (WHERE x.id IS NOT NULL), '[]'),
    'manual', api.current_user_id()
  FROM api.blocks x WHERE x.record_id = v_protocol.id
  RETURNING * INTO v_revision;
  INSERT INTO api.protocol_versions(
    id, workspace_id, protocol_record_id, version, status, change_summary, reason, created_by_user_id, updated_by_user_id
  ) VALUES (
    v_revision.id, v_protocol.workspace_id, v_protocol.id, v_next, 'draft',
    nullif(btrim(coalesce(p_change_summary, '')), ''), nullif(btrim(coalesce(p_reason, '')), ''),
    api.current_user_id(), api.current_user_id()
  ) RETURNING * INTO v_version;
  PERFORM internal.emit_change_event(v_protocol.workspace_id, 'protocol_version', v_version.id, 'create', v_protocol.id, v_protocol.project_id,
    jsonb_build_object('protocolRecordId', v_protocol.id, 'version', v_next));
  RETURN v_version;
END $$;
--> statement-breakpoint
ALTER FUNCTION api.create_protocol_version(p_protocol_record_id uuid, p_change_summary text, p_reason text) OWNER TO migrator;
--> statement-breakpoint
CREATE FUNCTION api.create_record(p_project_id uuid, p_kind text, p_title text, p_status text DEFAULT 'draft'::text, p_tags text[] DEFAULT '{}'::text[], p_properties jsonb DEFAULT '{}'::jsonb) RETURNS api.records
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_workspace_id uuid;
  v_identifier text;
  v_row "api"."records";
  v_is_template boolean;
BEGIN
  -- H5: legacy records.kind = notebook_template is removal-compatibility only;
  -- the dynamically injected guard is preserved here.
  PERFORM "internal"."reject_new_legacy_notebook_template"(p_kind);

  v_workspace_id := "api"."current_workspace_id"();
  IF v_workspace_id IS NULL THEN
    RAISE EXCEPTION 'no active workspace in request claims' USING ERRCODE = '42804';
  END IF;
  IF NOT "api"."is_workspace_writer"(v_workspace_id) THEN
    RAISE EXCEPTION 'caller cannot write to the active workspace' USING ERRCODE = '42501';
  END IF;

  -- Templates (protocol_template, notebook_template) are workspace-scoped and
  -- accept a NULL project; everything else must resolve to a workspace project.
  v_is_template := p_kind IN ('protocol_template', 'notebook_template');
  IF NOT v_is_template OR p_project_id IS NOT NULL THEN
    IF NOT EXISTS (
      SELECT 1 FROM "api"."projects" p
      WHERE p.id = p_project_id AND p.workspace_id = v_workspace_id
    ) THEN
      RAISE EXCEPTION 'project not found in active workspace' USING ERRCODE = '42501';
    END IF;
  END IF;

  v_identifier := "api"."next_record_identifier"(v_workspace_id, p_kind);

  p_title := btrim(coalesce(p_title, ''));
  IF p_title = '' THEN
    p_title := v_identifier;
  END IF;

  INSERT INTO "api"."records"
    (workspace_id, project_id, kind, identifier, title, status, tags,
     properties, created_by_user_id)
  VALUES
    (v_workspace_id, p_project_id, p_kind, v_identifier, p_title, p_status,
     p_tags, COALESCE(p_properties, '{}'::jsonb), "api"."current_user_id"())
  RETURNING * INTO v_row;

  RETURN v_row;
END;
$$;
