    CONSTRAINT chk_record_links_link_type CHECK ((link_type = ANY (ARRAY['sample'::text, 'protocol'::text, 'dataset'::text, 'material'::text, 'analysis'::text, 'file'::text, 'general'::text, 'template'::text, 'follows'::text, 'upstream'::text, 'booking'::text]))),
    CONSTRAINT chk_record_links_template_metadata CHECK (((link_type <> 'template'::text) OR (link_metadata ? 'template_revision_id'::text)))
);
