CREATE FUNCTION api.create_record_link(p_source_record_id uuid, p_target_kind text, p_target_identifier text, p_link_type text, p_target_record_id uuid DEFAULT NULL::uuid, p_label text DEFAULT NULL::text) RETURNS api.record_links
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_row "api"."record_links";
  v_target_ws uuid;
BEGIN
  IF p_target_record_id IS NOT NULL THEN
    SELECT workspace_id INTO v_target_ws
      FROM "api"."records" WHERE id = p_target_record_id;
    IF v_target_ws IS NULL THEN
      RAISE EXCEPTION 'target record not found in active workspace'
        USING ERRCODE = 'SB002';
    END IF;
    IF v_target_ws <> "api"."current_workspace_id"() THEN
      RAISE EXCEPTION 'record link crosses workspaces' USING ERRCODE = 'SB002';
    END IF;

    -- LAB-04.2: a reagent usage link records a material as used.
    IF p_link_type = 'material' THEN
      IF EXISTS (SELECT 1 FROM api.records r
                  WHERE r.id = p_target_record_id AND r.status = 'quarantined') THEN
        RAISE EXCEPTION 'material % is quarantined and cannot be referenced', p_target_identifier
          USING ERRCODE = 'SB120';
      END IF;
      IF EXISTS (SELECT 1 FROM api.records r
                  WHERE r.id = p_target_record_id AND r.status = 'expired') THEN
        RAISE EXCEPTION 'material % has expired and cannot be referenced', p_target_identifier
          USING ERRCODE = 'SB124';
      END IF;
    END IF;
  END IF;

  INSERT INTO "api"."record_links" (
    source_record_id, target_record_id, target_kind, target_identifier,
    link_type, created_by_user_id
  ) VALUES (
    p_source_record_id, p_target_record_id, p_target_kind,
    p_target_identifier, p_link_type, "api"."current_user_id"()
  )
  RETURNING * INTO v_row;

  RETURN v_row;
END;
$$;
--> statement-breakpoint
