CREATE TABLE api.sheet_definition_versions (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    definition_id uuid NOT NULL,
    version integer NOT NULL,
    lifecycle text DEFAULT 'draft'::text NOT NULL,
    configuration_format_version integer DEFAULT 1 NOT NULL,
    configuration jsonb NOT NULL,
    revision bigint DEFAULT 1 NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    created_by_user_id text,
    updated_by_user_id text,
    published_at timestamp with time zone,
    published_by_user_id text,
    retired_at timestamp with time zone,
    retired_by_user_id text,
    CONSTRAINT chk_sheet_definition_versions_format CHECK ((configuration_format_version = 1)),
    CONSTRAINT chk_sheet_definition_versions_lifecycle CHECK ((lifecycle = ANY (ARRAY['draft'::text, 'published'::text, 'retired'::text]))),
    CONSTRAINT chk_sheet_definition_versions_revision CHECK ((revision > 0)),
    CONSTRAINT chk_sheet_definition_versions_version CHECK ((version > 0))
);
