CREATE FUNCTION api.create_sheet_instance_from_definition(p_workspace_id uuid, p_name text, p_description text, p_source_definition_version_id uuid, p_project_id uuid, p_notebook_record_id uuid, p_state jsonb, p_parameter_inputs jsonb) RETURNS api.sheet_instances
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE defaults jsonb; result api.sheet_instances;
BEGIN
 IF p_project_id IS NOT NULL THEN PERFORM internal.assert_object_access('project',p_project_id,'edit'); END IF;
 IF p_notebook_record_id IS NOT NULL THEN PERFORM internal.assert_object_access('record',p_notebook_record_id,'edit'); END IF;
 IF NOT internal.sources_readable(p_state) THEN RAISE EXCEPTION 'Source access denied' USING ERRCODE='42501'; END IF;
  IF NOT api.is_workspace_writer(p_workspace_id) THEN
    RAISE EXCEPTION 'workspace member required' USING ERRCODE='42501';
  END IF;
  IF NOT EXISTS(
    SELECT 1
    FROM api.sheet_definition_versions version
    JOIN api.sheet_definitions definition ON definition.id=version.definition_id
    WHERE version.id=p_source_definition_version_id
      AND version.lifecycle='published'
      AND definition.workspace_id=p_workspace_id
      AND definition.lifecycle='active'
  ) THEN
    RAISE EXCEPTION 'source Definition Version must be published, active, and in this workspace' USING ERRCODE='SB074';
  END IF;
  IF NOT p_state ? 'presentation' THEN
    SELECT configuration->'presentation' INTO defaults FROM api.sheet_definition_versions WHERE id=p_source_definition_version_id;
    p_state:=jsonb_set(p_state,'{presentation}',defaults,true);
  END IF;
  PERFORM internal.validate_sheet_instance_presentation(p_source_definition_version_id,p_state);
  result:=api.create_sheet_instance_from_definition_core0311(
    p_workspace_id,p_name,p_description,p_source_definition_version_id,p_project_id,p_notebook_record_id,
    internal.sheet_document_without_presentation_queries(p_state),
    p_parameter_inputs
  );
  PERFORM set_config('sheetbase.sheet_instance_write','rpc-v1',true);
  UPDATE api.sheet_instances SET state=jsonb_set(result.state,'{presentation}',p_state->'presentation') WHERE id=result.id RETURNING * INTO result;
  RETURN result;
END $$;
--> statement-breakpoint
ALTER FUNCTION api.create_sheet_instance_from_definition(p_workspace_id uuid, p_name text, p_description text, p_source_definition_version_id uuid, p_project_id uuid, p_notebook_record_id uuid, p_state jsonb, p_parameter_inputs jsonb) OWNER TO migrator;
--> statement-breakpoint
CREATE FUNCTION api.create_sheet_instance_from_definition_core0311(p_workspace_id uuid, p_name text, p_description text, p_source_definition_version_id uuid, p_project_id uuid, p_notebook_record_id uuid, p_state jsonb, p_parameter_inputs jsonb) RETURNS api.sheet_instances
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE result api.sheet_instances; actor text:=api.current_user_id(); resolved jsonb; identity_kind text;
BEGIN
  IF NOT api.is_workspace_member(p_workspace_id) THEN RAISE EXCEPTION 'workspace member required' USING ERRCODE='42501'; END IF;
  IF length(btrim(p_name)) NOT BETWEEN 1 AND 200 OR (p_description IS NOT NULL AND length(p_description)>2000) THEN RAISE EXCEPTION 'invalid Sheet Instance name or description' USING ERRCODE='SB073'; END IF;
  IF jsonb_array_length(coalesce(p_state->'instanceCalculations','[]'::jsonb))<>0 THEN RAISE EXCEPTION 'initial calculation definitions require the controlled calculation mutation RPC' USING ERRCODE='SB083'; END IF;
  resolved:=internal.resolve_sheet_parameters(p_workspace_id,p_source_definition_version_id,p_parameter_inputs);
  SELECT configuration->'rowIdentity'->>'kind' INTO identity_kind FROM api.sheet_definition_versions WHERE id=p_source_definition_version_id;
  p_state:=(p_state-'bindings'-'parameterValues'-'provenance'-'resolutionProvenance'-'resolvedRowIdentity'-'instanceCalculations')||resolved||jsonb_build_object('provenance',jsonb_build_object('createdFrom','definition_version'));
  IF (identity_kind<>'local' AND p_state->'localValues'<>'{}'::jsonb) OR EXISTS(SELECT 1 FROM jsonb_object_keys(p_state->'localValues') key WHERE key ~ '^sb-row-v1:') THEN RAISE EXCEPTION 'initial local values do not match the unresolved Definition row identity' USING ERRCODE='SB073'; END IF;
  IF EXISTS(
    SELECT 1 FROM jsonb_each(p_state->'localValues') row_entry
    CROSS JOIN LATERAL jsonb_each(row_entry.value) cell
    JOIN LATERAL jsonb_array_elements(p_state->'localFields') field ON field->>'fieldId'=cell.key
    WHERE internal.sheet_local_cell_error(p_workspace_id,field,cell.value) IS NOT NULL
  ) THEN RAISE EXCEPTION 'invalid initial local value' USING ERRCODE='SB073'; END IF;
  PERFORM internal.validate_sheet_instance_state(p_state); PERFORM set_config('sheetbase.sheet_instance_write','rpc-v1',true);
  INSERT INTO api.sheet_instances(workspace_id,name,description,source_definition_version_id,project_id,notebook_record_id,state,created_by_user_id,updated_by_user_id) VALUES(p_workspace_id,btrim(p_name),nullif(btrim(p_description),''),p_source_definition_version_id,p_project_id,p_notebook_record_id,p_state,actor,actor) RETURNING * INTO result;
  RETURN result;
END $$;
--> statement-breakpoint
