CREATE TABLE api.storage_boxes (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    workspace_id uuid NOT NULL,
    rack_id uuid NOT NULL,
    name text NOT NULL,
    code text NOT NULL,
    rows integer NOT NULL,
    cols integer NOT NULL,
    capacity integer NOT NULL,
    metadata jsonb DEFAULT '{}'::jsonb NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT chk_storage_boxes_capacity CHECK ((capacity = (rows * cols))),
    CONSTRAINT chk_storage_boxes_code CHECK (((length(btrim(code)) >= 1) AND (length(btrim(code)) <= 64))),
    CONSTRAINT chk_storage_boxes_cols CHECK (((cols >= 1) AND (cols <= 26))),
    CONSTRAINT chk_storage_boxes_name CHECK (((length(btrim(name)) >= 1) AND (length(btrim(name)) <= 200))),
    CONSTRAINT chk_storage_boxes_rows CHECK (((rows >= 1) AND (rows <= 26)))
);
--> statement-breakpoint
ALTER TABLE api.storage_boxes OWNER TO migrator;
