CREATE FUNCTION api.create_study_deliverable(p_task_id uuid, p_name text, p_description text DEFAULT NULL::text, p_status text DEFAULT 'planned'::text, p_due_at timestamp with time zone DEFAULT NULL::timestamp with time zone) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
  v_task api.study_tasks;
  v_position integer;
  v_row api.study_deliverables;
BEGIN
  SELECT * INTO v_task FROM api.study_tasks WHERE id = p_task_id;
  IF v_task.id IS NULL THEN
    RAISE EXCEPTION 'task not found' USING ERRCODE = 'SB036';
  END IF;
  IF NOT api.is_workspace_writer(v_task.workspace_id) THEN
    RAISE EXCEPTION 'capability required: workspace write' USING ERRCODE = '42501';
  END IF;
  IF p_name IS NULL OR length(btrim(p_name)) NOT BETWEEN 1 AND 200 THEN
    RAISE EXCEPTION 'a milestone name is required' USING ERRCODE = '22023';
  END IF;
  IF p_status IS NULL OR p_status NOT IN ('planned', 'in_progress', 'delivered', 'overdue') THEN
    RAISE EXCEPTION 'invalid milestone status' USING ERRCODE = '22023';
  END IF;

  SELECT coalesce(max(position), 0) + 1 INTO v_position
    FROM api.study_deliverables WHERE task_id = p_task_id;

  INSERT INTO api.study_deliverables
    (workspace_id, task_id, name, description, status, due_at, position)
  VALUES (v_task.workspace_id, p_task_id, btrim(p_name),
          nullif(btrim(coalesce(p_description, '')), ''), p_status, p_due_at, v_position)
  RETURNING * INTO v_row;

  PERFORM internal.emit_change_event(v_task.workspace_id, 'study_task', p_task_id, 'update',
    NULL, v_task.project_id,
    jsonb_build_object('effect', 'milestone_created', 'milestoneId', v_row.id));

  RETURN jsonb_build_object('id', v_row.id, 'taskId', v_row.task_id, 'name', v_row.name,
    'status', v_row.status, 'dueAt', v_row.due_at, 'position', v_row.position);
END $$;
--> statement-breakpoint
ALTER FUNCTION api.create_study_deliverable(p_task_id uuid, p_name text, p_description text, p_status text, p_due_at timestamp with time zone) OWNER TO migrator;
--> statement-breakpoint
CREATE TABLE api.study_tasks (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    workspace_id uuid NOT NULL,
    workstream_id uuid,
    project_id uuid,
    title text NOT NULL,
    description text,
    task_type text DEFAULT 'task'::text NOT NULL,
    status text DEFAULT 'not_started'::text NOT NULL,
    priority text DEFAULT 'medium'::text NOT NULL,
    starts_at timestamp with time zone,
    ends_at timestamp with time zone,
    due_at timestamp with time zone,
    timezone text DEFAULT 'UTC'::text NOT NULL,
    "position" integer DEFAULT 0 NOT NULL,
    color text,
    progress_percent integer DEFAULT 0 NOT NULL,
    linked_experiment_record_id uuid,
    linked_experiment_identifier text,
    linked_experiment_title text,
    linked_protocol_record_id uuid,
    linked_protocol_identifier text,
    approval_required boolean DEFAULT false NOT NULL,
    approval_status text DEFAULT 'not_required'::text NOT NULL,
    tags text[] DEFAULT '{}'::text[] NOT NULL,
    metadata_version integer DEFAULT 1 NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    created_by_user_id text,
    updated_by_user_id text,
    study_record_id uuid,
    client_visible boolean DEFAULT false NOT NULL,
    shared_since timestamp with time zone,
    client_visible_reason text,
    CONSTRAINT chk_study_tasks_approval CHECK ((approval_status = ANY (ARRAY['not_required'::text, 'pending'::text, 'approved'::text, 'rejected'::text]))),
    CONSTRAINT chk_study_tasks_milestone_dates CHECK ((((task_type = 'milestone'::text) AND (due_at IS NOT NULL)) OR (task_type = 'task'::text))),
    CONSTRAINT chk_study_tasks_position CHECK (("position" >= 0)),
    CONSTRAINT chk_study_tasks_priority CHECK ((priority = ANY (ARRAY['low'::text, 'medium'::text, 'high'::text, 'critical'::text]))),
    CONSTRAINT chk_study_tasks_progress CHECK (((progress_percent >= 0) AND (progress_percent <= 100))),
    CONSTRAINT chk_study_tasks_status CHECK ((status = ANY (ARRAY['not_started'::text, 'in_progress'::text, 'review'::text, 'completed'::text, 'blocked'::text, 'cancelled'::text]))),
    CONSTRAINT chk_study_tasks_title CHECK (((length(btrim(title)) >= 1) AND (length(btrim(title)) <= 200))),
    CONSTRAINT chk_study_tasks_type CHECK ((task_type = ANY (ARRAY['task'::text, 'milestone'::text]))),
    CONSTRAINT chk_study_tasks_version CHECK ((metadata_version > 0))
);
