    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
  v_row "api"."study_workstreams";
  v_ws_id uuid;
BEGIN
 IF p_project_id IS NOT NULL THEN PERFORM internal.assert_object_access('project',p_project_id,'edit'); END IF;
  v_ws_id := "api"."current_workspace_id"();
  IF v_ws_id IS NULL OR v_ws_id <> p_workspace_id THEN
