CREATE TABLE api.record_models (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    workspace_id uuid NOT NULL,
    key text NOT NULL,
    name text NOT NULL,
    description text,
    identifier_prefix text NOT NULL,
    lifecycle text DEFAULT 'draft'::text NOT NULL,
    current_version integer DEFAULT 1 NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    created_by_user_id text,
    updated_by_user_id text,
    CONSTRAINT chk_record_models_current_version CHECK ((current_version > 0)),
    CONSTRAINT chk_record_models_identifier_prefix CHECK ((identifier_prefix ~ '^[A-Z][A-Z0-9]{0,7}$'::text)),
    CONSTRAINT chk_record_models_key CHECK ((key ~ '^[a-z][a-z0-9_]{0,59}$'::text)),
    CONSTRAINT chk_record_models_lifecycle CHECK ((lifecycle = ANY (ARRAY['draft'::text, 'published'::text, 'retired'::text])))
);
