    LANGUAGE plpgsql STABLE
    AS $$
DECLARE
  claims jsonb;
  value text;
BEGIN
  claims := "api"."claim_probe"();
  IF claims IS NULL THEN
    RETURN NULL;
  END IF;
  value := claims ->> 'workspace_id';
  IF value IS NULL THEN
    RETURN NULL;
  END IF;
  BEGIN
    RETURN value::uuid;
  EXCEPTION WHEN invalid_text_representation THEN
    RETURN NULL;
  END;
END;
