CREATE FUNCTION api.dataset_list_summary(p_project_id uuid DEFAULT NULL::uuid, p_include_archived boolean DEFAULT true, p_limit integer DEFAULT NULL::integer, p_offset integer DEFAULT 0) RETURNS TABLE(id uuid, display_id text, name text, model text, project_id uuid, created_by_user_id text, row_count bigint, issue_count bigint, updated_at timestamp with time zone, archived_at timestamp with time zone, experiment_display_id text, out_of_range_count bigint, missing_unit_count bigint, missing_unit_fields text[], review_state text)
    LANGUAGE sql STABLE
    SET search_path TO 'pg_catalog', 'api'
    AS $$
  SELECT d.id, d.display_id, d.name,
    -- The design's Model column carries the schema version ("ViCell v2").
    sd.name || ' v' || sv.version,
    d.primary_project_id,
    d.created_by_user_id,
    (SELECT count(*) FROM api.dataset_rows r WHERE r.dataset_id = d.id),
    (SELECT count(*) FROM api.dataset_value_flags f
      WHERE f.dataset_id = d.id AND f.cleared_at IS NULL),
    d.updated_at, d.archived_at,
    exp.identifier,
    -- One row per out-of-range value, not per flag: a person's manual flag on a
    -- value the system rule already flagged is a second flag on the same value.
    (SELECT count(DISTINCT (f.row_id, f.field_id)) FROM api.dataset_value_flags f
      WHERE f.dataset_id = d.id AND f.cleared_at IS NULL
        AND f.kind = 'out_of_range'),
    -- One row per column with a missing unit, matching `missing_unit_fields`.
    (SELECT count(DISTINCT f.field_id) FROM api.dataset_value_flags f
      WHERE f.dataset_id = d.id AND f.cleared_at IS NULL
        AND f.kind = 'missing_unit'),
    (SELECT array_agg(DISTINCT fv.label ORDER BY fv.label)
       FROM api.dataset_value_flags f
       JOIN api.dataset_schema_version_fields fv
         ON fv.schema_version_id = d.schema_version_id
        AND fv.field_id = f.field_id
      WHERE f.dataset_id = d.id AND f.cleared_at IS NULL
        AND f.kind = 'missing_unit'),
    CASE
      WHEN exp.status = 'approved' THEN 'locked'
      WHEN exp.status = 'in_review' AND exp.locked_at IS NULL THEN 'in_review'
      ELSE NULL
    END
  FROM api.datasets d
  LEFT JOIN api.dataset_schema_versions sv ON sv.id = d.schema_version_id
  LEFT JOIN api.dataset_schema_definitions sd ON sd.id = sv.schema_id
  LEFT JOIN LATERAL (
    SELECT r.identifier, r.status, r.locked_at
      FROM api.record_links l
      JOIN api.records r ON r.id = l.source_record_id
     WHERE l.target_kind = 'dataset'
       AND l.link_type = 'dataset'
       AND l.target_identifier = d.display_id
     ORDER BY r.created_at
     LIMIT 1
  ) exp ON true
  WHERE (p_project_id IS NULL OR d.primary_project_id = p_project_id)
    AND (p_include_archived OR d.archived_at IS NULL)
  ORDER BY d.updated_at DESC, d.id
  LIMIT p_limit OFFSET coalesce(p_offset, 0)
$$;
--> statement-breakpoint
ALTER FUNCTION api.dataset_list_summary(p_project_id uuid, p_include_archived boolean, p_limit integer, p_offset integer) OWNER TO migrator;
--> statement-breakpoint
CREATE FUNCTION api.dataset_sheet_options(p_dataset_id uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
  dataset api.datasets;
  candidate record;
  parameter jsonb;
  inputs jsonb;
  options jsonb := '[]'::jsonb;
  refusal text;
  chosen_id text;
BEGIN
  SELECT * INTO dataset FROM api.datasets
    WHERE id = p_dataset_id AND workspace_id = api.current_workspace_id()
      AND lifecycle = 'active';
  IF dataset.id IS NULL OR NOT api.is_workspace_member(dataset.workspace_id) THEN
    RAISE EXCEPTION 'Dataset unavailable' USING ERRCODE = '42501';
  END IF;
  PERFORM internal.assert_object_access('dataset', dataset.id, 'view');
  FOR candidate IN
    SELECT DISTINCT ON (d.id) d.id AS definition_id, d.name, v.id, v.version, v.configuration
      FROM api.sheet_definitions d JOIN api.sheet_definition_versions v ON v.definition_id = d.id
      WHERE d.workspace_id = dataset.workspace_id AND d.lifecycle = 'active' AND v.lifecycle = 'published'
      ORDER BY d.id, v.version DESC
  LOOP
    refusal := NULL;
    chosen_id := NULL;
    FOR parameter IN SELECT value FROM jsonb_array_elements(candidate.configuration->'parameters')
      WHERE value->'type'->>'kind' = 'dataset'
    LOOP
      inputs := jsonb_build_array(jsonb_build_object(
        'parameterId', parameter->>'id', 'kind', 'dataset', 'datasetId', dataset.id));
      BEGIN
        PERFORM internal.resolve_sheet_parameters(dataset.workspace_id, candidate.id, inputs);
        chosen_id := parameter->>'id';
        refusal := NULL;
        EXIT;
      EXCEPTION WHEN SQLSTATE 'SB074' THEN
        refusal := SQLERRM;
      END;
    END LOOP;
    IF chosen_id IS NOT NULL OR refusal IS NOT NULL THEN
      options := options || jsonb_build_array(jsonb_build_object(
        'versionId', candidate.id, 'definitionId', candidate.definition_id,
        'definitionName', candidate.name, 'version', candidate.version,
        'datasetParameterId', chosen_id, 'unavailableReason', refusal));
    END IF;
  END LOOP;
  RETURN options;
END $$;
--> statement-breakpoint
ALTER FUNCTION api.dataset_sheet_options(p_dataset_id uuid) OWNER TO migrator;
--> statement-breakpoint
CREATE FUNCTION api.dataset_value_context(p_dataset_id uuid, p_row_id uuid) RETURNS jsonb
    LANGUAGE sql STABLE
    SET search_path TO ''
    AS $$
  SELECT jsonb_build_object('datasetId',d.id,'schemaVersionId',d.schema_version_id,'totalCount',1,'offset',0,'limit',1,
    'rows',jsonb_build_array(jsonb_build_object('rowId',r.id,'revision',r.revision,
      'values',coalesce((SELECT jsonb_object_agg(field_id,value) FROM (
        SELECT v.field_id,CASE WHEN f.cardinality='one' THEN (jsonb_agg(
          coalesce(to_jsonb(v.text_value),to_jsonb(v.integer_value),to_jsonb(v.numeric_value),to_jsonb(v.boolean_value),to_jsonb(v.date_value),to_jsonb(v.timestamp_value),to_jsonb(v.category_option_id),to_jsonb(v.reference_id)) ORDER BY v.ordinal))->0
        ELSE jsonb_agg(coalesce(to_jsonb(v.text_value),to_jsonb(v.integer_value),to_jsonb(v.numeric_value),to_jsonb(v.boolean_value),to_jsonb(v.date_value),to_jsonb(v.timestamp_value),to_jsonb(v.category_option_id),to_jsonb(v.reference_id)) ORDER BY v.ordinal) END AS value
        FROM api.dataset_row_values v JOIN api.dataset_schema_version_fields f
          ON f.schema_version_id=d.schema_version_id AND f.field_id=v.field_id
        WHERE v.row_id=r.id GROUP BY v.field_id,f.cardinality
      ) fields),'{}'::jsonb))))
  FROM api.datasets d JOIN api.dataset_rows r ON r.dataset_id=d.id
  WHERE d.id=p_dataset_id AND r.id=p_row_id AND d.workspace_id=api.current_workspace_id()
$$;
--> statement-breakpoint
ALTER FUNCTION api.dataset_value_context(p_dataset_id uuid, p_row_id uuid) OWNER TO migrator;
--> statement-breakpoint
CREATE FUNCTION api.dataset_version_list(p_dataset_id uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
  d api.datasets;
BEGIN
  SELECT * INTO d FROM api.datasets
    WHERE id = p_dataset_id AND workspace_id = api.current_workspace_id()
      AND api.is_workspace_member(workspace_id);
  IF d.id IS NULL THEN
    RAISE EXCEPTION 'Dataset denied' USING ERRCODE = '42501';
  END IF;

  RETURN coalesce((
    SELECT jsonb_agg(
      jsonb_build_object(
        'id', v.id,
        'label', v.label,
        'createdAt', v.created_at,
        'createdByUserId', v.created_by_user_id,
        'createdByCredentialId', v.created_by_credential_id,
        'createdByName', coalesce(
          (SELECT u.name FROM internal."user" u WHERE u.id = v.created_by_user_id),
          (SELECT c.name FROM internal.api_credentials c WHERE c.id = v.created_by_credential_id)
        ),
        'sourceDatasetRevision', v.source_dataset_revision,
        'rowCount', (
          SELECT count(*) FROM api.dataset_version_rows r
          WHERE r.dataset_version_id = v.id
        ),
        'rowsRemovedAt', (
          SELECT p.rows_removed_at FROM api.dataset_version_prunes p
          WHERE p.dataset_version_id = v.id
        ),
        'contentHash', internal.dataset_version_content_hash(v.id),
        'change', CASE WHEN prev.id IS NULL THEN NULL
          ELSE api.compare_dataset_versions(prev.id, v.id, 1, 0) -> 'counts'
        END,
        'retention', api.dataset_version_retention(v.id) || jsonb_build_object(
          'policy', jsonb_build_object(
            'citedYears', coalesce(ws.snapshot_cited_retention_years, 15),
            'uncitedYears', coalesce(ws.snapshot_uncited_retention_years, 2)
          )
        ),
        'source', coalesce(
          (
            SELECT jsonb_build_object(
              'kind', 'pipeline_run',
              'runId', o.run_id,
              'definitionName', pd.name,
              'triggerKind', r.trigger_kind,
              'status', r.status,
              'label', o.label,
              'startedAt', r.started_at
            )
            FROM api.pipeline_run_outputs o
            LEFT JOIN api.pipeline_runs r
              ON r.id = o.run_id AND r.workspace_id = o.workspace_id
            LEFT JOIN api.pipeline_definition_versions dv
              ON dv.id = r.definition_version_id
            LEFT JOIN api.pipeline_definitions pd
              ON pd.id = dv.definition_id
            WHERE o.dataset_version_id = v.id
              AND o.workspace_id = v.workspace_id
            ORDER BY o.created_at DESC, o.id DESC
            LIMIT 1
          ),
          -- The import receipt that froze this snapshot: the import wizard and
          -- a connector both commit through the migration RPCs, which snapshot
          -- with 'Import <file>' as the label. Without this the snapshot was
          -- attributed to the person who ran the import ("Saved by hand")
          -- while its label said an import made it.
          (
            SELECT jsonb_build_object(
              'kind', 'import',
              'runId', NULL,
              'definitionName', NULL,
              'triggerKind', NULL,
              'status', NULL,
              'label', f.filename,
              'startedAt', NULL
            )
            FROM api.dataset_imports i
            LEFT JOIN api.dataset_import_files f ON f.id = i.file_id
            WHERE i.snapshot_version_id = v.id
              AND i.workspace_id = v.workspace_id
              AND i.status = 'committed'
            ORDER BY i.created_at DESC, i.id DESC
            LIMIT 1
          ),
          jsonb_build_object(
            'kind', CASE WHEN v.created_by_credential_id IS NOT NULL THEN 'api' ELSE 'manual' END,
            'runId', NULL,
            'definitionName', NULL,
            'triggerKind', NULL,
            'status', NULL,
            'label', NULL,
            'startedAt', NULL
          )
        ),
        'citedBy', jsonb_build_object(
          'signedRevisions', coalesce((
            SELECT jsonb_agg(jsonb_build_object(
              'revisionId', e.revision_id,
              'signedAt', s.signed_at,
              'signerUserId', s.signer_user_id
            ) ORDER BY s.signed_at)
            FROM api.revision_sheet_evidence e
            JOIN api.signatures s
              ON s.revision_id = e.revision_id AND s.workspace_id = e.workspace_id
            WHERE e.workspace_id = v.workspace_id
              AND e.dataset_versions ? v.id::text
              AND s.signature_meaning = 'approve-for-record'
          ), '[]'::jsonb),
          'pipelineRuns', coalesce((
            SELECT jsonb_agg(jsonb_build_object(
              'runId', r.id,
              'status', r.status,
              'triggerKind', r.trigger_kind,
              'startedAt', r.started_at
            ) ORDER BY r.started_at)
            FROM api.pipeline_runs r
            WHERE r.workspace_id = v.workspace_id
              AND EXISTS (
                SELECT 1 FROM jsonb_each_text(r.input_versions) x
                WHERE x.value = v.id::text
              )
          ), '[]'::jsonb),
          'analyses', coalesce((
            SELECT jsonb_agg(jsonb_build_object(
              'blockId', b.id,
              'recordId', b.record_id
            ) ORDER BY b.id)
            FROM api.blocks b
            JOIN api.records rec ON rec.id = b.record_id
            WHERE rec.workspace_id = v.workspace_id
              AND b.type = 'analysis'
              AND EXISTS (
                SELECT 1
                FROM jsonb_array_elements(
                  coalesce(b.payload->'frozen'->'datasetProvenance', '[]'::jsonb)
                ) p
                WHERE p->>'datasetVersionId' = v.id::text
              )
          ), '[]'::jsonb)
        )
      )
      ORDER BY v.created_at DESC, v.id DESC
    )
    FROM api.dataset_versions v
    LEFT JOIN LATERAL (
      SELECT p.id FROM api.dataset_versions p
      WHERE p.dataset_id = v.dataset_id
        AND (p.created_at, p.id) < (v.created_at, v.id)
      ORDER BY p.created_at DESC, p.id DESC
      LIMIT 1
    ) prev ON true
    LEFT JOIN api.workspace_settings ws ON ws.workspace_id = v.workspace_id
    WHERE v.dataset_id = d.id
  ), '[]'::jsonb);
END;
$$;
--> statement-breakpoint
ALTER FUNCTION api.dataset_version_list(p_dataset_id uuid) OWNER TO migrator;
--> statement-breakpoint
CREATE FUNCTION api.dataset_version_retention(p_version_id uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
  v api.dataset_versions;
  d api.datasets;
  ws api.workspace_settings;
  keep api.dataset_version_keeps;
  cited timestamptz;
  cited_years integer;
  uncited_years integer;
BEGIN
 IF p_version_id IS NOT NULL THEN PERFORM internal.assert_object_access('dataset_version',p_version_id,'view'); END IF;
  SELECT * INTO v FROM api.dataset_versions
    WHERE id = p_version_id AND workspace_id = api.current_workspace_id()
      AND api.is_workspace_member(workspace_id);
  IF v.id IS NULL THEN
    RAISE EXCEPTION 'Dataset Version denied' USING ERRCODE = '42501';
  END IF;
  SELECT * INTO d FROM api.datasets WHERE id = v.dataset_id;
  SELECT * INTO ws FROM api.workspace_settings WHERE workspace_id = v.workspace_id;
  SELECT * INTO keep FROM api.dataset_version_keeps WHERE dataset_version_id = v.id;
  cited_years := coalesce(ws.snapshot_cited_retention_years, 15);
  uncited_years := coalesce(ws.snapshot_uncited_retention_years, 2);

  SELECT max(s.signed_at) INTO cited
    FROM api.revision_sheet_evidence e
    JOIN api.signatures s ON s.revision_id = e.revision_id
    WHERE s.signature_meaning = 'approve-for-record'
      AND e.dataset_versions ? v.id::text;


  IF internal.import_block_references('datasetVersionId',v.id) THEN
    RETURN jsonb_build_object('reason','notebook_import_evidence','keptUntil',NULL);
  END IF;
  IF cited IS NOT NULL THEN
    RETURN jsonb_build_object(
      'reason', 'cited_by_signed_record',
      'keptUntil', cited + make_interval(years => cited_years)
    );
  END IF;
  IF keep.kept_until IS NOT NULL AND keep.kept_until > now() THEN
    RETURN jsonb_build_object('reason', 'kept', 'keptUntil', keep.kept_until);
  END IF;
  IF d.archived_at IS NOT NULL THEN
    RETURN jsonb_build_object(
      'reason', 'uncited_after_archive',
      'keptUntil', d.archived_at + make_interval(years => uncited_years)
    );
  END IF;
  RETURN jsonb_build_object('reason', 'active', 'keptUntil', NULL);
END;
$$;
--> statement-breakpoint
ALTER FUNCTION api.dataset_version_retention(p_version_id uuid) OWNER TO migrator;
--> statement-breakpoint
CREATE TABLE api.agent_operation_proposals (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    workspace_id uuid NOT NULL,
    title text NOT NULL,
