    revision bigint DEFAULT 1 NOT NULL,
    idempotency_key text NOT NULL,
    request_digest text NOT NULL,
    provenance jsonb NOT NULL,
    proposed_by_user_id text,
    proposed_by_credential_id uuid,
    approved_by_user_id text,
    approved_at timestamp with time zone,
    rejected_by_user_id text,
    rejected_at timestamp with time zone,
    rejection_reason text,
    executed_by_user_id text,
    executed_at timestamp with time zone,
    result jsonb,
    error_code text,
    error_message text,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    risk_class text DEFAULT 'consequential_write'::text NOT NULL,
    policy_id uuid,
    policy_reason text DEFAULT ''::text NOT NULL,
    policy_limits jsonb DEFAULT '{}'::jsonb NOT NULL,
    policy_target jsonb DEFAULT '{}'::jsonb NOT NULL,
    policy_evidence jsonb DEFAULT '{}'::jsonb NOT NULL,
    executed_by_credential_id uuid,
    CONSTRAINT chk_agent_operation_proposals_approval_actor CHECK (((approval_policy <> 'human_required'::text) OR (status <> ALL (ARRAY['approved'::text, 'executing'::text, 'succeeded'::text, 'failed'::text])) OR ((approved_by_user_id IS NOT NULL) AND (approved_at IS NOT NULL)))),
    CONSTRAINT chk_agent_operation_proposals_author_xor CHECK (((proposed_by_user_id IS NULL) <> (proposed_by_credential_id IS NULL))),
    CONSTRAINT chk_agent_operation_proposals_digest CHECK ((request_digest ~ '^[0-9a-f]{64}$'::text)),
    CONSTRAINT chk_agent_operation_proposals_execution_actor CHECK (((status <> ALL (ARRAY['executing'::text, 'succeeded'::text, 'failed'::text])) OR ((((executed_by_user_id IS NOT NULL))::integer + ((executed_by_credential_id IS NOT NULL))::integer) = 1))),
    CONSTRAINT chk_agent_operation_proposals_kind CHECK ((operation_kind = ANY (ARRAY['dataset_schema.create'::text, 'sheet_definition.create'::text, 'sheet_definition.update_draft'::text, 'pipeline_definition.create'::text, 'pipeline_definition.create_version'::text, 'pipeline_definition.update_draft'::text, 'dataset_rows.commit'::text, 'notebook_block.insert'::text]))),
    CONSTRAINT chk_agent_operation_proposals_policy CHECK ((approval_policy = ANY (ARRAY['automatic'::text, 'human_required'::text, 'delegated'::text]))),
    CONSTRAINT chk_agent_operation_proposals_policy_payload CHECK (((jsonb_typeof(policy_limits) = 'object'::text) AND (jsonb_typeof(policy_target) = 'object'::text) AND (jsonb_typeof(policy_evidence) = 'object'::text))),
    CONSTRAINT chk_agent_operation_proposals_revision CHECK ((revision > 0)),
    CONSTRAINT chk_agent_operation_proposals_risk CHECK ((risk_class = ANY (ARRAY['safe_draft'::text, 'consequential_write'::text]))),
    CONSTRAINT chk_agent_operation_proposals_status CHECK ((status = ANY (ARRAY['pending'::text, 'approved'::text, 'rejected'::text, 'executing'::text, 'succeeded'::text, 'failed'::text, 'cancelled'::text])))
);
