CREATE FUNCTION api.decide_agent_operation(p_proposal_id uuid, p_expected_revision bigint, p_decision text, p_reason text DEFAULT NULL::text) RETURNS api.agent_operation_proposals
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
  v_result api.agent_operation_proposals;
  v_user text := api.current_user_id();
BEGIN
  IF v_user IS NULL OR api.current_credential_id() IS NOT NULL THEN
    RAISE EXCEPTION 'human session required for approval' USING ERRCODE='42501';
  END IF;
  SELECT * INTO v_result FROM api.agent_operation_proposals
   WHERE id=p_proposal_id AND workspace_id=api.current_workspace_id() FOR UPDATE;
  IF v_result.id IS NULL THEN
    RAISE EXCEPTION 'proposal not found' USING ERRCODE='42501';
  END IF;
  PERFORM internal.require_agent_operation_capability(v_result);
  IF v_result.status <> 'pending' OR v_result.revision <> p_expected_revision THEN
    RAISE EXCEPTION 'stale or decided proposal' USING ERRCODE='SB001';
  END IF;
  IF p_decision = 'approve' THEN
    UPDATE api.agent_operation_proposals
       SET status='approved',revision=revision+1,approved_by_user_id=v_user,
           approved_at=now(),updated_at=now()
     WHERE id=v_result.id RETURNING * INTO v_result;
    PERFORM internal.agent_operation_append_event(v_result,'approved','{}'::jsonb);
  ELSIF p_decision = 'reject' AND length(btrim(coalesce(p_reason,''))) BETWEEN 1 AND 1000 THEN
    UPDATE api.agent_operation_proposals
       SET status='rejected',revision=revision+1,rejected_by_user_id=v_user,
           rejected_at=now(),rejection_reason=btrim(p_reason),updated_at=now()
     WHERE id=v_result.id RETURNING * INTO v_result;
    PERFORM internal.agent_operation_append_event(v_result,'rejected',jsonb_build_object('reason',v_result.rejection_reason));
  ELSE
    RAISE EXCEPTION 'decision must be approve or reject with a reason' USING ERRCODE='22023';
  END IF;
  PERFORM internal.emit_change_event(
    v_result.workspace_id,'agent_operation_proposal',v_result.id,'update',
    NULL,NULL,jsonb_build_object('status',v_result.status,'operationKind',v_result.operation_kind)
  );
  RETURN v_result;
END;
$$;
--> statement-breakpoint
ALTER FUNCTION api.decide_agent_operation(p_proposal_id uuid, p_expected_revision bigint, p_decision text, p_reason text) OWNER TO migrator;
--> statement-breakpoint
CREATE FUNCTION api.decide_project_access_request(p_request_id uuid, p_approve boolean) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE r api.project_access_requests; existing api.project_access;
BEGIN
  SELECT * INTO r FROM api.project_access_requests WHERE id=p_request_id FOR UPDATE;
  IF NOT internal.can_manage_project(r.project_id) THEN RAISE EXCEPTION 'Explicit project management rule required' USING ERRCODE='42501'; END IF;
  IF r.status<>'pending' THEN RAISE EXCEPTION 'Request is already decided' USING ERRCODE='22023'; END IF;
  IF p_approve THEN
    SELECT * INTO existing FROM api.project_access WHERE project_id=r.project_id AND user_id=r.user_id;
    PERFORM api.set_project_access_rule(r.project_id,r.user_id,NULL,true,true,coalesce(existing.can_review,false),coalesce(existing.client_portal,false),coalesce(existing.can_manage,false));
  END IF;
  UPDATE api.project_access_requests SET status=CASE WHEN p_approve THEN 'approved' ELSE 'denied' END,decided_by_user_id=api.current_user_id(),updated_at=now() WHERE id=r.id;
END $$;
--> statement-breakpoint
ALTER FUNCTION api.decide_project_access_request(p_request_id uuid, p_approve boolean) OWNER TO migrator;
--> statement-breakpoint
CREATE FUNCTION api.delete_block(p_block_id uuid, p_expected_structure_version integer DEFAULT NULL::integer) RETURNS jsonb
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_block "api"."blocks";
  v_record_id uuid;
  v_sv int;
  v_order_list jsonb;
BEGIN
  SELECT * INTO v_block FROM "api"."blocks" WHERE id = p_block_id FOR UPDATE;
  IF v_block IS NULL THEN
    RAISE EXCEPTION 'block not found in active workspace' USING ERRCODE = '42501';
  END IF;
  v_record_id := v_block.record_id;

  SELECT structure_version INTO v_sv FROM "api"."records" WHERE id = v_record_id FOR UPDATE;
  IF v_sv IS NULL THEN
    RAISE EXCEPTION 'record not found in active workspace' USING ERRCODE = '42501';
  END IF;
  IF p_expected_structure_version IS NOT NULL AND v_sv <> p_expected_structure_version THEN
    RAISE EXCEPTION 'structure version mismatch: expected %, got %',
      p_expected_structure_version, v_sv USING ERRCODE = 'SB001';
  END IF;

  DELETE FROM "api"."blocks" WHERE id = p_block_id;

  UPDATE "api"."records"
    SET structure_version = v_sv + 1
    WHERE id = v_record_id;

  SELECT jsonb_agg(jsonb_build_object('id', id, 'order', "order") ORDER BY "order")
    INTO v_order_list
    FROM "api"."blocks" WHERE record_id = v_record_id;

  RETURN jsonb_build_object(
    'structure_version', v_sv + 1,
    'order', COALESCE(v_order_list, '[]'::jsonb)
  );
END;
$$;
--> statement-breakpoint
ALTER FUNCTION api.delete_block(p_block_id uuid, p_expected_structure_version integer) OWNER TO migrator;
--> statement-breakpoint
CREATE FUNCTION api.delete_dataset_schema_version(p_schema_version_id uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE version api.dataset_schema_versions; workspace uuid;
BEGIN
  SELECT * INTO version FROM api.dataset_schema_versions WHERE id=p_schema_version_id FOR UPDATE;
  IF version.id IS NULL THEN
    RAISE EXCEPTION 'Dataset Schema Version not found' USING ERRCODE = '42501';
  END IF;
  SELECT s.workspace_id INTO workspace FROM api.dataset_schema_definitions s WHERE s.id=version.schema_id;
  PERFORM api.require_capability(workspace,'schema.edit');
  IF version.lifecycle<>'draft' THEN
    RAISE EXCEPTION 'only draft Dataset Schema Versions may be discarded' USING ERRCODE = 'SB073';
  END IF;
  IF EXISTS(SELECT 1 FROM api.approval_requests r WHERE r.workspace_id=workspace
    AND r.object_kind='dataset_schema_version' AND r.object_id=version.id AND r.state='pending') THEN
    RAISE EXCEPTION 'draft is locked while approval is pending' USING ERRCODE = 'SB085';
  END IF;
  DELETE FROM api.dataset_schema_versions WHERE id=version.id;
END $$;
