    CONSTRAINT chk_webhook_subscriptions_channel_type CHECK ((channel_type = ANY (ARRAY['webhook'::text, 'teams'::text, 'email'::text]))),
    CONSTRAINT chk_webhook_subscriptions_desc CHECK (((description IS NULL) OR ((length(btrim(description)) >= 1) AND (length(btrim(description)) <= 2000)))),
    CONSTRAINT chk_webhook_subscriptions_failure_threshold CHECK (((failure_threshold >= 0) AND (failure_threshold <= 100))),
    CONSTRAINT chk_webhook_subscriptions_key CHECK ((key ~ '^[a-z][a-z0-9-]{0,48}$'::text)),
    CONSTRAINT chk_webhook_subscriptions_max_retries CHECK (((max_retries >= 0) AND (max_retries <= 25))),
    CONSTRAINT chk_webhook_subscriptions_rate_limit CHECK (((rate_limit_per_minute IS NULL) OR ((rate_limit_per_minute >= 1) AND (rate_limit_per_minute <= 60000)))),
    CONSTRAINT chk_webhook_subscriptions_recipient CHECK ((((channel_type = 'email'::text) AND (recipient_user_id IS NOT NULL)) OR ((channel_type <> 'email'::text) AND (recipient_user_id IS NULL)))),
    CONSTRAINT chk_webhook_subscriptions_status CHECK ((status = ANY (ARRAY['active'::text, 'paused'::text, 'disabled'::text, 'archived'::text]))),
    CONSTRAINT chk_webhook_subscriptions_url CHECK ((((channel_type = 'email'::text) AND (url IS NULL)) OR ((channel_type <> 'email'::text) AND (url ~ '^https://'::text) AND (length(url) <= 2048))))
);
