CREATE FUNCTION api.discover_model_dependencies(p_model_key text) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
  workspace uuid := api.current_workspace_id();
  model api.model_kinds;
  items jsonb := '[]'::jsonb;
  class_items jsonb;
  class_count integer;
  truncated boolean := false;
  sheet_version_ids uuid[] := '{}';
BEGIN
  IF workspace IS NULL OR NOT api.is_workspace_member(workspace) THEN
    RAISE EXCEPTION 'capability required: record.link' USING ERRCODE = '42501';
  END IF;
  IF p_model_key IS NULL OR btrim(p_model_key) = '' THEN
    RAISE EXCEPTION 'model key is required' USING ERRCODE = '22023';
  END IF;
  SELECT * INTO model FROM api.model_kinds WHERE key = p_model_key;
  IF model.key IS NULL THEN
    -- ADR-0051: a workspace-defined record model is a record host too. Resolve
    -- it from this workspace's registry so the same field/record dependency
    -- classes apply. Only this workspace's model is visible (RLS + workspace
    -- filter); another workspace's key reads as not found.
    SELECT m.key INTO model.key
      FROM api.record_models m
      WHERE m.workspace_id = workspace AND m.key = p_model_key;
    IF model.key IS NULL THEN
      RAISE EXCEPTION 'model not found' USING ERRCODE = '42501';
    END IF;
    model.identity_table := 'api.records';
    model.record_kind := p_model_key;
    model.label := (
      SELECT m.name FROM api.record_models m
      WHERE m.workspace_id = workspace AND m.key = p_model_key
    );
  END IF;

  -- Field definitions of this model, annotated with their stored-value
  -- usage so the report shows which fields carry migration weight.
  SELECT coalesce(jsonb_agg(internal.dependency_item(
      'model_field', d.id, 'defines_field',
      CASE WHEN d.lifecycle = 'active' THEN 'active' ELSE 'historical' END,
      'informational',
      d.label || ' (' || d.field_name || ') · '
        || coalesce(api.model_field_usage(d.id), 0)::text || ' records'
    ) ORDER BY d.field_name), '[]'::jsonb),
    count(*)
    INTO class_items, class_count
    FROM (
      SELECT * FROM api.record_field_definitions
       WHERE workspace_id = workspace AND kind = p_model_key
       ORDER BY field_name LIMIT 26
    ) d;
  IF class_count > 25 THEN
    truncated := true;
    SELECT coalesce(jsonb_agg(value), '[]'::jsonb) INTO class_items
      FROM (
        SELECT value FROM jsonb_array_elements(class_items)
        WITH ORDINALITY ORDER BY ordinality LIMIT 25
      ) s;
  END IF;
  items := items || coalesce(class_items, '[]'::jsonb);

  -- Host rows carrying any custom value for this model (records via
  -- custom fields; other hosts via their own custom_fields column).
  IF model.identity_table = 'api.records' AND model.record_kind IS NOT NULL THEN
    SELECT coalesce(jsonb_agg(internal.dependency_item(
        'record', r.id, 'carries_custom_values',
        CASE WHEN r.archived_at IS NULL THEN 'active' ELSE 'historical' END,
        'requires_migration', r.identifier
      ) ORDER BY r.identifier), '[]'::jsonb),
      count(*)
      INTO class_items, class_count
      FROM (
        SELECT * FROM api.records
         WHERE workspace_id = workspace AND kind = model.record_kind
           AND custom_fields <> '{}'::jsonb
         ORDER BY identifier LIMIT 26
      ) r;
  ELSIF model.identity_table = 'api.projects' THEN
    SELECT coalesce(jsonb_agg(internal.dependency_item(
        'project', p.id, 'carries_custom_values',
        CASE WHEN p.status = 'active' THEN 'active' ELSE 'historical' END,
        'requires_migration', p.title
      ) ORDER BY p.title), '[]'::jsonb),
      count(*)
      INTO class_items, class_count
      FROM (
        SELECT * FROM api.projects
         WHERE workspace_id = workspace AND custom_fields <> '{}'::jsonb
         ORDER BY title LIMIT 26
      ) p;
  ELSIF model.identity_table = 'api.plate_designs' THEN
    SELECT coalesce(jsonb_agg(internal.dependency_item(
        'plate_design', p.id, 'carries_custom_values',
        CASE WHEN p.status = 'archived' THEN 'historical' ELSE 'active' END,
        'requires_migration', p.name
      ) ORDER BY p.name), '[]'::jsonb),
      count(*)
      INTO class_items, class_count
      FROM (
        SELECT * FROM api.plate_designs
         WHERE workspace_id = workspace AND custom_fields <> '{}'::jsonb
         ORDER BY name LIMIT 26
      ) p;
  ELSIF model.identity_table = 'api.instruments' THEN
    SELECT coalesce(jsonb_agg(internal.dependency_item(
        'instrument', p.id, 'carries_custom_values',
        'active', 'requires_migration', p.name
      ) ORDER BY p.name), '[]'::jsonb),
      count(*)
      INTO class_items, class_count
      FROM (
        SELECT * FROM api.instruments
         WHERE workspace_id = workspace AND custom_fields <> '{}'::jsonb
         ORDER BY name LIMIT 26
      ) p;
  ELSIF model.identity_table = 'api.instrument_runs' THEN
    SELECT coalesce(jsonb_agg(internal.dependency_item(
        'instrument_run', p.id, 'carries_custom_values',
        'active', 'requires_migration', p.name
      ) ORDER BY p.name), '[]'::jsonb),
      count(*)
      INTO class_items, class_count
      FROM (
        SELECT * FROM api.instrument_runs
         WHERE workspace_id = workspace AND custom_fields <> '{}'::jsonb
         ORDER BY name LIMIT 26
      ) p;
  ELSIF model.identity_table = 'api.dataset_schemas' THEN
    SELECT coalesce(jsonb_agg(internal.dependency_item(
        'dataset_schema', p.id, 'carries_custom_values',
        CASE WHEN p.status = 'published' THEN 'active' ELSE 'historical' END,
        'requires_migration', p.name
      ) ORDER BY p.name), '[]'::jsonb),
      count(*)
      INTO class_items, class_count
      FROM (
        SELECT * FROM api.dataset_schemas
         WHERE workspace_id = workspace AND custom_fields <> '{}'::jsonb
         ORDER BY name LIMIT 26
      ) p;
  ELSIF model.identity_table = 'api.scientific_tables' THEN
    SELECT coalesce(jsonb_agg(internal.dependency_item(
        'scientific_table', p.id, 'carries_custom_values',
        CASE WHEN p.lifecycle = 'active' THEN 'active' ELSE 'historical' END,
        'requires_migration', p.name
      ) ORDER BY p.name), '[]'::jsonb),
      count(*)
      INTO class_items, class_count
      FROM (
        SELECT * FROM api.scientific_tables
         WHERE workspace_id = workspace AND custom_fields <> '{}'::jsonb
         ORDER BY name LIMIT 26
      ) p;
  ELSE
    -- Unknown host table: fail closed rather than silently omitting the
    -- class — the report must never claim completeness it cannot prove.
    RAISE EXCEPTION 'model host is not supported for impact analysis' USING ERRCODE = '22023';
  END IF;
  IF class_count > 25 THEN
    truncated := true;
    SELECT coalesce(jsonb_agg(value), '[]'::jsonb) INTO class_items
      FROM (
        SELECT value FROM jsonb_array_elements(class_items)
        WITH ORDINALITY ORDER BY ordinality LIMIT 25
      ) s;
  END IF;
  items := items || coalesce(class_items, '[]'::jsonb);

  -- MODEL-03 rules referencing this model as source or target.
  SELECT coalesce(jsonb_agg(internal.dependency_item(
      'model_relationship_rule', r.id,
      CASE WHEN r.source_model_key = p_model_key
        THEN 'constrains_source_links' ELSE 'referenced_as_target' END,
      'active',
      CASE WHEN r.source_model_key = p_model_key THEN 'requires_migration'
        ELSE 'informational' END,
      CASE WHEN r.source_model_key = p_model_key
        THEN r.link_type || ' → ' || r.target_model_key
          || ' (' || r.min_links::text || '–' || coalesce(r.max_links::text, '∞') || ')'
          || coalesce(' · “' || r.label || '”', '')
        ELSE r.source_model_key || ' · ' || r.link_type || ' → ' || r.target_model_key
      END
    ) ORDER BY r.source_model_key, r.link_type, r.target_model_key), '[]'::jsonb),
    count(*)
    INTO class_items, class_count
    FROM (
      SELECT * FROM api.model_relationship_rules
       WHERE workspace_id = workspace
         AND (source_model_key = p_model_key OR target_model_key = p_model_key)
       ORDER BY source_model_key, link_type, target_model_key LIMIT 26
    ) r;
  IF class_count > 25 THEN
    truncated := true;
    SELECT coalesce(jsonb_agg(value), '[]'::jsonb) INTO class_items
      FROM (
        SELECT value FROM jsonb_array_elements(class_items)
        WITH ORDINALITY ORDER BY ordinality LIMIT 25
      ) s;
  END IF;
  items := items || coalesce(class_items, '[]'::jsonb);

  -- Sheets via record parameters: definition versions whose configuration
  -- declares a record parameter bound to this model (stable modelKey,
  -- same shape internal.validate_parameter enforces).
  SELECT coalesce(jsonb_agg(internal.dependency_item(
      'sheet_definition_version', v.id, 'parameter_model_contract',
      CASE WHEN v.lifecycle = 'published' AND d.lifecycle = 'active'
        THEN 'active' ELSE 'historical' END,
      'requires_migration', d.name || ' v' || v.version::text
    ) ORDER BY d.key, v.version), '[]'::jsonb),
    count(*)
    INTO class_items, class_count
    FROM (
      SELECT v.* FROM api.sheet_definition_versions v
      JOIN api.sheet_definitions d ON d.id = v.definition_id
      WHERE d.workspace_id = workspace
        AND EXISTS (
          SELECT 1 FROM jsonb_array_elements(
            coalesce(v.configuration->'parameters', '[]'::jsonb)) param
          WHERE param->'type'->>'kind' = 'record'
            AND param->'type'->>'modelKey' = p_model_key
        )
      ORDER BY d.key, v.version LIMIT 26
    ) v
    JOIN api.sheet_definitions d ON d.id = v.definition_id;
  IF class_count > 25 THEN
    truncated := true;
    SELECT coalesce(jsonb_agg(value), '[]'::jsonb) INTO class_items
      FROM (
        SELECT value FROM jsonb_array_elements(class_items)
        WITH ORDINALITY ORDER BY ordinality LIMIT 25
      ) s;
  END IF;
  items := items || coalesce(class_items, '[]'::jsonb);
  SELECT coalesce(array_agg((value->>'id')::uuid), '{}') INTO sheet_version_ids
    FROM jsonb_array_elements(items) value
   WHERE value->>'kind' = 'sheet_definition_version';

  -- Sheets via bindings/record links: instances binding a record whose
  -- model is this model. Record IDs resolve through api.records so a
  -- malformed binding can never leak or match across workspaces
  -- (internal.collect_uuid returns NULL instead of raising).
  SELECT coalesce(jsonb_agg(internal.dependency_item(
      'sheet_instance', i.id, 'binds_model_record',
      CASE WHEN i.lifecycle = 'active' THEN 'active' ELSE 'historical' END,
      'requires_migration', i.name
    ) ORDER BY i.name), '[]'::jsonb),
    count(*)
    INTO class_items, class_count
    FROM (
      SELECT i.* FROM api.sheet_instances i
      WHERE i.workspace_id = workspace
        AND EXISTS (
          SELECT 1 FROM jsonb_array_elements(
            coalesce(i.state->'bindings', '[]'::jsonb)) b
          JOIN api.records r
            ON r.id = internal.collect_uuid(b->>'recordId')
          JOIN api.model_kinds m
            ON m.record_kind = r.kind
           AND m.identity_table = 'api.records'
          WHERE b->>'kind' = 'record'
            AND r.workspace_id = workspace
            AND m.key = p_model_key
        )
      ORDER BY i.name LIMIT 26
    ) i;
  IF class_count > 25 THEN
    truncated := true;
    SELECT coalesce(jsonb_agg(value), '[]'::jsonb) INTO class_items
      FROM (
        SELECT value FROM jsonb_array_elements(class_items)
        WITH ORDINALITY ORDER BY ordinality LIMIT 25
      ) s;
  END IF;
  items := items || coalesce(class_items, '[]'::jsonb);

  -- Templates via record parameters: template versions declaring a record
  -- parameter bound to this model (same validate_parameter shape).
  SELECT coalesce(jsonb_agg(internal.dependency_item(
      'notebook_template_version', v.id, 'parameter_model_contract',
      CASE WHEN v.lifecycle = 'published' THEN 'active' ELSE 'historical' END,
      'requires_migration', t.key || ' v' || v.version::text
    ) ORDER BY t.key, v.version), '[]'::jsonb),
    count(*)
    INTO class_items, class_count
    FROM (
      SELECT v.* FROM api.notebook_template_versions v
      JOIN api.notebook_templates t ON t.id = v.template_id
      WHERE t.workspace_id = workspace
        AND EXISTS (
          SELECT 1 FROM jsonb_array_elements(
            coalesce(v.configuration->'parameters', '[]'::jsonb)) param
          WHERE param->'type'->>'kind' = 'record'
            AND param->'type'->>'modelKey' = p_model_key
        )
      ORDER BY t.key, v.version LIMIT 26
    ) v
    JOIN api.notebook_templates t ON t.id = v.template_id;
  IF class_count > 25 THEN
    truncated := true;
    SELECT coalesce(jsonb_agg(value), '[]'::jsonb) INTO class_items
      FROM (
        SELECT value FROM jsonb_array_elements(class_items)
        WITH ORDINALITY ORDER BY ordinality LIMIT 25
      ) s;
  END IF;
  items := items || coalesce(class_items, '[]'::jsonb);

  -- Templates via placements: versions pinning a dependent Sheet version
  -- found above. Informational: the sheet dependency itself carries the
  -- migration weight; the template only names a consequence.
  IF sheet_version_ids <> '{}' THEN
    SELECT coalesce(jsonb_agg(internal.dependency_item(
        'notebook_template_version', v.id, 'pins_dependent_sheet',
        CASE WHEN v.lifecycle = 'published' THEN 'active' ELSE 'historical' END,
        'informational', t.key || ' v' || v.version::text
      ) ORDER BY t.key, v.version), '[]'::jsonb),
      count(*)
      INTO class_items, class_count
      FROM (
        SELECT v.* FROM api.notebook_template_versions v
        JOIN api.notebook_templates t ON t.id = v.template_id
        WHERE t.workspace_id = workspace
          AND EXISTS (
            SELECT 1 FROM jsonb_array_elements(
              coalesce(v.configuration->'placements', '[]'::jsonb)) placement
            WHERE placement->>'kind' = 'sheet'
              AND internal.collect_uuid(placement->>'definitionVersionId')
                = ANY(sheet_version_ids)
          )
        ORDER BY t.key, v.version LIMIT 26
      ) v
      JOIN api.notebook_templates t ON t.id = v.template_id;
    IF class_count > 25 THEN
      truncated := true;
      SELECT coalesce(jsonb_agg(value), '[]'::jsonb) INTO class_items
        FROM (
          SELECT value FROM jsonb_array_elements(class_items)
          WITH ORDINALITY ORDER BY ordinality LIMIT 25
        ) s;
    END IF;
    items := items || coalesce(class_items, '[]'::jsonb);
  END IF;

  RETURN jsonb_build_object(
    'kind', 'model',
    'id', p_model_key,
    'dependencies', coalesce(items, '[]'::jsonb),
    'truncated', truncated
  );
END;
$$;
--> statement-breakpoint
ALTER FUNCTION api.discover_model_dependencies(p_model_key text) OWNER TO migrator;
--> statement-breakpoint
CREATE FUNCTION api.discover_object_dependencies(p_kind text, p_object_id uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
  workspace uuid := api.current_workspace_id();
  base jsonb;
  items jsonb;
  definition api.record_field_definitions;
  model api.model_kinds;
  sample jsonb := '[]'::jsonb;
  total bigint := 0;
  sampled integer := 0;
  truncated boolean := false;
BEGIN
 IF p_kind IN ('record','notebook_record','dataset','sheet_instance') THEN PERFORM internal.assert_object_access(CASE p_kind WHEN 'sheet_instance' THEN 'instance' WHEN 'notebook_record' THEN 'record' ELSE p_kind END,p_object_id,'view'); END IF;
  IF p_kind = 'model_field' THEN
    base := api.discover_object_dependencies_core158(p_kind, p_object_id);
    -- The core branch already raised for a missing or out-of-workspace
    -- definition; re-read it workspace-scoped so every scan below stays
    -- inside the verified workspace (fail closed, never cross-workspace).
    SELECT * INTO definition FROM api.record_field_definitions
     WHERE id = p_object_id AND workspace_id = workspace;
    IF definition.id IS NULL THEN
      RETURN base;
    END IF;
    SELECT * INTO model FROM api.model_kinds WHERE key = definition.kind;
    total := coalesce(api.model_field_usage(definition.id), 0);
    IF model.identity_table = 'api.records' THEN
      SELECT coalesce(jsonb_agg(internal.dependency_item(
          'record', r.id, 'carries_field_value',
          CASE WHEN r.archived_at IS NULL THEN 'active' ELSE 'historical' END,
          'requires_migration', r.identifier
        ) ORDER BY r.identifier), '[]'::jsonb),
        count(*)
        INTO sample, sampled
        FROM (
          SELECT * FROM api.records
           WHERE workspace_id = workspace AND internal.can_access_object('record',id,'view')
             AND kind = coalesce(model.record_kind, definition.kind)
             AND custom_fields ? definition.field_name
           ORDER BY identifier LIMIT 26
        ) r;
    ELSIF model.identity_table = 'api.projects' THEN
      SELECT coalesce(jsonb_agg(internal.dependency_item(
          'project', p.id, 'carries_field_value',
          CASE WHEN p.status = 'active' THEN 'active' ELSE 'historical' END,
          'requires_migration', p.title
        ) ORDER BY p.title), '[]'::jsonb),
        count(*)
        INTO sample, sampled
        FROM (
          SELECT * FROM api.projects
           WHERE workspace_id = workspace AND internal.can_access_object('project',id,'view')
             AND custom_fields ? definition.field_name
           ORDER BY title LIMIT 26
        ) p;
    ELSIF model.identity_table = 'api.plate_designs' THEN
      SELECT coalesce(jsonb_agg(internal.dependency_item(
          'plate_design', p.id, 'carries_field_value',
          CASE WHEN p.status = 'archived' THEN 'historical' ELSE 'active' END,
          'requires_migration', p.name
        ) ORDER BY p.name), '[]'::jsonb),
        count(*)
        INTO sample, sampled
        FROM (
          SELECT * FROM api.plate_designs
           WHERE workspace_id = workspace AND internal.can_access_object('design',id,'view')
             AND custom_fields ? definition.field_name
           ORDER BY name LIMIT 26
        ) p;
    ELSIF model.identity_table = 'api.instruments' THEN
      SELECT coalesce(jsonb_agg(internal.dependency_item(
          'instrument', p.id, 'carries_field_value',
          'active', 'requires_migration', p.name
        ) ORDER BY p.name), '[]'::jsonb),
        count(*)
        INTO sample, sampled
        FROM (
          SELECT * FROM api.instruments
           WHERE workspace_id = workspace
             AND custom_fields ? definition.field_name
           ORDER BY name LIMIT 26
        ) p;
    ELSIF model.identity_table = 'api.instrument_runs' THEN
      SELECT coalesce(jsonb_agg(internal.dependency_item(
          'instrument_run', p.id, 'carries_field_value',
          'active', 'requires_migration', p.name
        ) ORDER BY p.name), '[]'::jsonb),
        count(*)
        INTO sample, sampled
        FROM (
          SELECT * FROM api.instrument_runs
           WHERE workspace_id = workspace AND internal.can_access_object('run',id,'view')
             AND custom_fields ? definition.field_name
           ORDER BY name LIMIT 26
        ) p;
    ELSIF model.identity_table = 'api.dataset_schemas' THEN
      SELECT coalesce(jsonb_agg(internal.dependency_item(
          'dataset_schema', p.id, 'carries_field_value',
          CASE WHEN p.status = 'published' THEN 'active' ELSE 'historical' END,
          'requires_migration', p.name
        ) ORDER BY p.name), '[]'::jsonb),
        count(*)
        INTO sample, sampled
        FROM (
          SELECT * FROM api.dataset_schemas
           WHERE workspace_id = workspace
             AND custom_fields ? definition.field_name
           ORDER BY name LIMIT 26
        ) p;
    ELSIF model.identity_table = 'api.scientific_tables' THEN
      SELECT coalesce(jsonb_agg(internal.dependency_item(
          'scientific_table', p.id, 'carries_field_value',
          CASE WHEN p.lifecycle = 'active' THEN 'active' ELSE 'historical' END,
          'requires_migration', p.name
        ) ORDER BY p.name), '[]'::jsonb),
        count(*)
        INTO sample, sampled
        FROM (
          SELECT * FROM api.scientific_tables
           WHERE workspace_id = workspace AND internal.can_access_object('table',id,'view')
             AND custom_fields ? definition.field_name
           ORDER BY name LIMIT 26
        ) p;
    ELSE
      RAISE EXCEPTION 'model host is not supported for impact analysis' USING ERRCODE = '22023';
    END IF;
    IF sampled > 25 THEN
      truncated := true;
      SELECT coalesce(jsonb_agg(value), '[]'::jsonb) INTO sample
        FROM (
          SELECT value FROM jsonb_array_elements(sample)
          WITH ORDINALITY ORDER BY ordinality LIMIT 25
        ) s;
    END IF;
    items := coalesce(base->'dependencies', '[]'::jsonb);
    IF total > 0 THEN
      -- A stored value needs steward handling on retire: the count item
      -- previously claimed informational, which understated the gate
      -- (apply already requires explicit confirmation for retire).
      SELECT coalesce(jsonb_agg(
        CASE WHEN value->>'kind' = 'model_field_usage'
          THEN value || '{"effect":"requires_migration"}'::jsonb
          ELSE value END
      ), '[]'::jsonb) INTO items
      FROM jsonb_array_elements(items) value;
    END IF;
    items := items || coalesce(sample, '[]'::jsonb);
    RETURN jsonb_build_object(
      'kind', p_kind,
      'id', p_object_id,
      'dependencies', items,
      'truncated', truncated
    );
  END IF;
  RETURN api.discover_object_dependencies_core158(p_kind, p_object_id);
END;
$$;
--> statement-breakpoint
ALTER FUNCTION api.discover_object_dependencies(p_kind text, p_object_id uuid) OWNER TO migrator;
--> statement-breakpoint
CREATE FUNCTION api.discover_object_dependencies_core054(p_kind text, p_object_id uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
  workspace uuid := api.current_workspace_id();
  items jsonb := '[]'::jsonb;
  schema_def api.dataset_schema_definitions;
  schema_ver api.dataset_schema_versions;
  sheet_def api.sheet_definitions;
  sheet_ver api.sheet_definition_versions;
  instance api.sheet_instances;
  dataset api.datasets;
  field_def api.record_field_definitions;
BEGIN
  IF workspace IS NULL OR NOT api.is_workspace_member(workspace) THEN
    RAISE EXCEPTION 'capability required: record.link' USING ERRCODE = '42501';
  END IF;
  IF p_kind IS NULL OR p_object_id IS NULL THEN
    RAISE EXCEPTION 'object kind and id are required' USING ERRCODE = '22023';
  END IF;

  IF p_kind = 'dataset_schema_version' THEN
    SELECT * INTO schema_ver FROM api.dataset_schema_versions WHERE id = p_object_id;
    SELECT * INTO schema_def FROM api.dataset_schema_definitions WHERE id = schema_ver.schema_id AND workspace_id = workspace;
    IF schema_def.id IS NULL THEN RAISE EXCEPTION 'object not found' USING ERRCODE = '42501'; END IF;
    SELECT coalesce(jsonb_agg(internal.dependency_item(
      'dataset', d.id, 'binds_schema_version',
      CASE WHEN d.lifecycle = 'active' THEN 'active' ELSE 'historical' END,
      'blocks_deletion', d.name
    ) ORDER BY d.name), '[]'::jsonb) INTO items
      FROM api.datasets d WHERE d.schema_version_id = p_object_id AND d.workspace_id = workspace AND internal.can_access_object('dataset',d.id,'view');
    items := coalesce(items, '[]'::jsonb) || coalesce((
      SELECT jsonb_agg(internal.dependency_item(
        'dataset_version', v.id, 'snapshot_schema_version', 'historical', 'blocks_deletion',
        coalesce(d.name, v.id::text)
      ) ORDER BY v.created_at)
      FROM api.dataset_versions v
      JOIN api.datasets d ON d.id = v.dataset_id
      WHERE v.schema_version_id = p_object_id AND v.workspace_id = workspace AND internal.can_access_object('dataset_version',v.id,'view')
    ), '[]'::jsonb);
    items := items || coalesce((
      SELECT jsonb_agg(internal.dependency_item(
        'sheet_definition_version', version.id, 'configuration_schema_version',
        CASE WHEN version.lifecycle = 'published' AND definition.lifecycle = 'active' THEN 'active' ELSE 'historical' END,
        'requires_migration', definition.name
      ) ORDER BY definition.key, version.version)
      FROM api.sheet_definition_versions version
      JOIN api.sheet_definitions definition ON definition.id = version.definition_id
      JOIN LATERAL internal.sheet_configuration_references(version.configuration) ref ON true
      WHERE definition.workspace_id = workspace
        AND ref.kind = 'dataset_schema_version'
        AND ref.object_id = p_object_id
    ), '[]'::jsonb);

  ELSIF p_kind = 'dataset_schema_field' THEN
    items := coalesce((
      SELECT jsonb_agg(internal.dependency_item(
        'dataset_schema_version', v.id, 'contains_field',
        CASE WHEN v.lifecycle = 'active' THEN 'active' ELSE 'historical' END,
        CASE WHEN v.lifecycle IN ('active','retired') THEN 'blocks_deletion' ELSE 'informational' END,
        s.key || ' v' || v.version::text
      ) ORDER BY s.key, v.version)
      FROM api.dataset_schema_version_fields f
      JOIN api.dataset_schema_versions v ON v.id = f.schema_version_id
      JOIN api.dataset_schema_definitions s ON s.id = v.schema_id
      WHERE f.field_id = p_object_id AND s.workspace_id = workspace
    ), '[]'::jsonb);
    items := items || coalesce((
      SELECT jsonb_agg(internal.dependency_item(
        'sheet_definition_version', version.id, 'configuration_field',
        CASE WHEN version.lifecycle = 'published' AND definition.lifecycle = 'active' THEN 'active' ELSE 'historical' END,
        'requires_migration', definition.name
      ) ORDER BY definition.key)
      FROM api.sheet_definition_versions version
      JOIN api.sheet_definitions definition ON definition.id = version.definition_id
      JOIN LATERAL internal.sheet_configuration_references(version.configuration) ref ON true
      WHERE definition.workspace_id = workspace
        AND ref.kind = 'dataset_schema_field'
        AND ref.object_id = p_object_id
    ), '[]'::jsonb);

  ELSIF p_kind = 'dataset_schema_definition' THEN
    SELECT * INTO schema_def FROM api.dataset_schema_definitions WHERE id = p_object_id AND workspace_id = workspace;
    IF schema_def.id IS NULL THEN RAISE EXCEPTION 'object not found' USING ERRCODE = '42501'; END IF;
    SELECT coalesce(jsonb_agg(internal.dependency_item(
      'dataset_schema_version', v.id, 'version_of_definition',
      CASE WHEN v.lifecycle = 'active' THEN 'active' ELSE 'historical' END,
      CASE WHEN v.lifecycle IN ('active','retired') THEN 'blocks_deletion' ELSE 'informational' END,
      'v' || v.version::text
    ) ORDER BY v.version), '[]'::jsonb) INTO items
      FROM api.dataset_schema_versions v WHERE v.schema_id = schema_def.id;

  ELSIF p_kind = 'sheet_definition_version' THEN
    SELECT * INTO sheet_ver FROM api.sheet_definition_versions WHERE id = p_object_id;
    SELECT * INTO sheet_def FROM api.sheet_definitions WHERE id = sheet_ver.definition_id AND workspace_id = workspace;
    IF sheet_def.id IS NULL THEN RAISE EXCEPTION 'object not found' USING ERRCODE = '42501'; END IF;
    SELECT coalesce(jsonb_agg(internal.dependency_item(
      'sheet_instance', i.id, 'pinned_definition_version',
      CASE WHEN i.lifecycle = 'active' THEN 'active' ELSE 'historical' END,
      'blocks_deletion', i.name
    ) ORDER BY i.name), '[]'::jsonb) INTO items
      FROM api.sheet_instances i
     WHERE i.source_definition_version_id = p_object_id AND i.workspace_id = workspace AND internal.can_access_object('instance',i.id,'view');
    items := items || coalesce((
      SELECT jsonb_agg(internal.dependency_item(
        'sheet_instance', u.instance_id, 'upgrade_provenance', 'historical', 'informational', 'upgrade'
      ))
      FROM api.sheet_instance_definition_upgrades u
      WHERE u.workspace_id = workspace AND internal.can_access_object('instance',u.instance_id,'view')
        AND (u.source_definition_version_id = p_object_id OR u.target_definition_version_id = p_object_id)
    ), '[]'::jsonb);

  ELSIF p_kind = 'sheet_definition' THEN
    SELECT * INTO sheet_def FROM api.sheet_definitions WHERE id = p_object_id AND workspace_id = workspace;
    IF sheet_def.id IS NULL THEN RAISE EXCEPTION 'object not found' USING ERRCODE = '42501'; END IF;
    SELECT coalesce(jsonb_agg(internal.dependency_item(
      'sheet_definition_version', v.id, 'version_of_definition',
      CASE WHEN v.lifecycle = 'published' THEN 'active' ELSE 'historical' END,
      'informational', 'v' || v.version::text
    ) ORDER BY v.version), '[]'::jsonb) INTO items
      FROM api.sheet_definition_versions v WHERE v.definition_id = sheet_def.id;
    items := items || coalesce((
      SELECT jsonb_agg(internal.dependency_item(
        'sheet_instance', i.id, 'pinned_definition_version',
        CASE WHEN i.lifecycle = 'active' THEN 'active' ELSE 'historical' END,
        'blocks_deletion', i.name
      ) ORDER BY i.name)
      FROM api.sheet_instances i
      JOIN api.sheet_definition_versions v ON v.id = i.source_definition_version_id
      WHERE v.definition_id = sheet_def.id AND i.workspace_id = workspace AND internal.can_access_object('instance',i.id,'view')
    ), '[]'::jsonb);

  ELSIF p_kind = 'dataset' THEN
    SELECT * INTO dataset FROM api.datasets WHERE id = p_object_id AND workspace_id = workspace;
    IF dataset.id IS NULL THEN RAISE EXCEPTION 'object not found' USING ERRCODE = '42501'; END IF;
    SELECT coalesce(jsonb_agg(internal.dependency_item(
      'dataset_version', v.id, 'snapshot_of_dataset', 'historical', 'blocks_deletion', v.id::text
    ) ORDER BY v.created_at), '[]'::jsonb) INTO items
      FROM api.dataset_versions v WHERE v.dataset_id = dataset.id;
    items := items || coalesce((
      SELECT jsonb_agg(internal.dependency_item(
        'sheet_instance', i.id, 'resolved_dataset_binding',
        CASE WHEN i.lifecycle = 'active' THEN 'active' ELSE 'historical' END,
        'blocks_deletion', i.name
      ) ORDER BY i.name)
      FROM api.sheet_instances i
      WHERE i.workspace_id = workspace AND internal.can_access_object('instance',i.id,'view')
        AND EXISTS (
          SELECT 1 FROM jsonb_array_elements(coalesce(i.state->'bindings','[]'::jsonb)) b
           WHERE b->>'datasetId' = dataset.id::text
        )
    ), '[]'::jsonb);

  ELSIF p_kind = 'sheet_instance' THEN
    SELECT * INTO instance FROM api.sheet_instances WHERE id = p_object_id AND workspace_id = workspace;
    IF instance.id IS NULL THEN RAISE EXCEPTION 'object not found' USING ERRCODE = '42501'; END IF;
    IF instance.source_definition_version_id IS NOT NULL THEN
      items := items || jsonb_build_array(internal.dependency_item(
        'sheet_definition_version', instance.source_definition_version_id, 'instance_source',
        'active', 'informational', 'pinned definition'
      ));
    END IF;

  ELSIF p_kind = 'model_field' THEN
    SELECT * INTO field_def FROM api.record_field_definitions WHERE id = p_object_id AND workspace_id = workspace;
    IF field_def.id IS NULL THEN RAISE EXCEPTION 'object not found' USING ERRCODE = '42501'; END IF;
    items := jsonb_build_array(internal.dependency_item(
      'model_field_usage', field_def.id, 'record_custom_field_count', 'informational', 'informational',
      coalesce(api.model_field_usage(field_def.id), 0)::text || ' records'
    ));

  ELSE
    RAISE EXCEPTION 'unsupported dependency kind' USING ERRCODE = '22023';
  END IF;

  RETURN jsonb_build_object(
    'kind', p_kind,
    'id', p_object_id,
    'dependencies', coalesce(items, '[]'::jsonb)
  );
END;
$$;
--> statement-breakpoint
ALTER FUNCTION api.discover_object_dependencies_core054(p_kind text, p_object_id uuid) OWNER TO migrator;
--> statement-breakpoint
CREATE FUNCTION api.discover_object_dependencies_core062(p_kind text, p_object_id uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
  workspace uuid := api.current_workspace_id();
  base jsonb;
  items jsonb := '[]'::jsonb;
  rec api.records;
  instance api.sheet_instances;
BEGIN
  IF p_kind IN ('record', 'notebook_record') THEN
    IF workspace IS NULL OR NOT api.is_workspace_member(workspace) THEN
      RAISE EXCEPTION 'capability required: record.link' USING ERRCODE = '42501';
    END IF;
    SELECT * INTO rec FROM api.records WHERE id = p_object_id AND workspace_id = workspace;
    IF rec.id IS NULL THEN RAISE EXCEPTION 'object not found' USING ERRCODE = '42501'; END IF;
    SELECT coalesce(jsonb_agg(internal.dependency_item(
      'sheet_instance', instance_id, 'notebook_sheet_block',
      'active', 'blocks_deletion', rec.identifier
    ) ORDER BY instance_id), '[]'::jsonb) INTO items
    FROM (
      SELECT DISTINCT internal.collect_uuid(b.payload->>'instanceId') AS instance_id
      FROM api.blocks b
      WHERE b.record_id = rec.id
        AND b.type = 'sheet'
        AND b.payload ? 'instanceId'
    ) refs
    WHERE instance_id IS NOT NULL;
    RETURN jsonb_build_object(
      'kind', p_kind,
      'id', p_object_id,
      'dependencies', coalesce(items, '[]'::jsonb)
    );
  END IF;

  base := api.discover_object_dependencies_core054(p_kind, p_object_id);
  IF p_kind = 'sheet_instance' THEN
    SELECT * INTO instance FROM api.sheet_instances
      WHERE id = p_object_id AND workspace_id = workspace;
    items := coalesce(base->'dependencies', '[]'::jsonb) || coalesce((
      SELECT jsonb_agg(internal.dependency_item(
        'notebook_block', b.id, 'embeds_sheet_instance',
        CASE WHEN instance.lifecycle = 'active' THEN 'active' ELSE 'historical' END,
        'blocks_deletion', r.identifier
      ) ORDER BY b.id)
      FROM api.blocks b
      JOIN api.records r ON r.id = b.record_id
      WHERE r.workspace_id = workspace AND internal.can_access_object('record',r.id,'view')
        AND b.type = 'sheet'
        AND b.payload->>'instanceId' = p_object_id::text
    ), '[]'::jsonb);
    RETURN jsonb_build_object(
      'kind', p_kind,
      'id', p_object_id,
      'dependencies', coalesce(items, '[]'::jsonb)
    );
  END IF;
  RETURN base;
END
$$;
--> statement-breakpoint
ALTER FUNCTION api.discover_object_dependencies_core062(p_kind text, p_object_id uuid) OWNER TO migrator;
--> statement-breakpoint
CREATE FUNCTION api.discover_object_dependencies_core063(p_kind text, p_object_id uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
  workspace uuid := api.current_workspace_id();
  base jsonb;
  items jsonb := '[]'::jsonb;
  template api.notebook_templates;
  version api.notebook_template_versions;
BEGIN
  IF p_kind = 'notebook_template' THEN
    IF workspace IS NULL OR NOT api.is_workspace_member(workspace) THEN
      RAISE EXCEPTION 'capability required: record.link' USING ERRCODE = '42501';
    END IF;
    SELECT * INTO template FROM api.notebook_templates
      WHERE id = p_object_id AND workspace_id = workspace;
    IF template.id IS NULL THEN RAISE EXCEPTION 'object not found' USING ERRCODE = '42501'; END IF;
    SELECT coalesce(jsonb_agg(internal.dependency_item(
      'notebook_template_version', v.id, 'template_version',
      CASE WHEN v.lifecycle = 'published' THEN 'active' ELSE 'historical' END,
      'blocks_deletion', 'v' || v.version::text
    ) ORDER BY v.version), '[]'::jsonb) INTO items
    FROM api.notebook_template_versions v WHERE v.template_id = template.id;
    RETURN jsonb_build_object('kind', p_kind, 'id', p_object_id, 'dependencies', coalesce(items,'[]'::jsonb));
  END IF;

  IF p_kind = 'notebook_template_version' THEN
    IF workspace IS NULL OR NOT api.is_workspace_member(workspace) THEN
      RAISE EXCEPTION 'capability required: record.link' USING ERRCODE = '42501';
    END IF;
    SELECT v.* INTO version
      FROM api.notebook_template_versions v
      JOIN api.notebook_templates t ON t.id = v.template_id
      WHERE v.id = p_object_id AND t.workspace_id = workspace;
    IF version.id IS NULL THEN RAISE EXCEPTION 'object not found' USING ERRCODE = '42501'; END IF;
    SELECT coalesce(jsonb_agg(internal.dependency_item(
      'sheet_definition_version', def_id, 'template_sheet_placement',
      'active', 'informational', 'pinned definition'
    ) ORDER BY def_id), '[]'::jsonb) INTO items
    FROM (
      SELECT DISTINCT internal.collect_uuid(placement->>'definitionVersionId') AS def_id
      FROM jsonb_array_elements(coalesce(version.configuration->'placements','[]'::jsonb)) placement
      WHERE placement->>'kind' = 'sheet'
    ) refs
    WHERE def_id IS NOT NULL;
    RETURN jsonb_build_object('kind', p_kind, 'id', p_object_id, 'dependencies', coalesce(items,'[]'::jsonb));
  END IF;

  base := api.discover_object_dependencies_core062(p_kind, p_object_id);
  RETURN base;
END
$$;
--> statement-breakpoint
ALTER FUNCTION api.discover_object_dependencies_core063(p_kind text, p_object_id uuid) OWNER TO migrator;
--> statement-breakpoint
CREATE FUNCTION api.discover_object_dependencies_core158(p_kind text, p_object_id uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
  workspace uuid := api.current_workspace_id();
  base jsonb;
  rec api.records;
  items jsonb := '[]'::jsonb;
BEGIN
  IF p_kind IN ('record','notebook_record') THEN
    base := api.discover_object_dependencies_core063(p_kind, p_object_id);
    SELECT * INTO rec FROM api.records WHERE id = p_object_id AND workspace_id = workspace;
    IF rec.source_notebook_template_version_id IS NOT NULL THEN
      items := coalesce(base->'dependencies','[]'::jsonb) || jsonb_build_array(internal.dependency_item(
        'notebook_template_version', rec.source_notebook_template_version_id,
        'instantiated_from', 'active', 'informational', rec.identifier
      ));
      RETURN jsonb_build_object('kind', p_kind, 'id', p_object_id, 'dependencies', items);
    END IF;
    RETURN base;
  END IF;
  RETURN api.discover_object_dependencies_core063(p_kind, p_object_id);
END
$$;
