COMMENT ON FUNCTION api.dispose_sample(p_record_id uuid, p_expected_metadata_version integer, p_reason text, p_notes text) IS 'LAB-02: moves a non-terminal sample to the terminal disposed state with a required reason, recording the disposal in properties and a canonical dispose sample_event. Remaining quantity is kept for lineage and audit.';
--> statement-breakpoint
CREATE FUNCTION api.duplicate_booking(p_booking_id uuid, p_starts_at timestamp with time zone, p_ends_at timestamp with time zone, p_title text DEFAULT NULL::text) RETURNS api.calendar_bookings
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
  v_ws_id uuid;
  v_src "api"."calendar_bookings";
  v_part jsonb;
  v_samp jsonb;
  v_new "api"."calendar_bookings";
BEGIN
 IF p_booking_id IS NOT NULL THEN PERFORM internal.assert_object_access('booking',p_booking_id,'edit'); END IF;
  v_ws_id := "api"."current_workspace_id"();
  SELECT * INTO v_src FROM "api"."calendar_bookings"
    WHERE id = p_booking_id AND workspace_id = v_ws_id;
  IF v_src IS NULL THEN
    RAISE EXCEPTION 'booking not found in active workspace' USING ERRCODE = 'SB022';
  END IF;
  IF p_ends_at <= p_starts_at THEN
    RAISE EXCEPTION 'invalid time range: ends_at must be after starts_at'
      USING ERRCODE = 'SB023';
  END IF;

  SELECT COALESCE(
    jsonb_agg(jsonb_build_object(
      'userId', user_id, 'displayName', display_name, 'role', role
    )),
    '[]'::jsonb
  ) INTO v_part FROM "api"."calendar_booking_participants"
    WHERE booking_id = p_booking_id;

  SELECT COALESCE(
    jsonb_agg(jsonb_build_object(
      'sampleRecordId', sample_record_id, 'sampleIdentifier', sample_identifier,
      'sampleTitle', sample_title, 'quantityValue', quantity_value::text,
      'quantityUnit', quantity_unit
    )),
    '[]'::jsonb
  ) INTO v_samp FROM "api"."calendar_booking_samples"
    WHERE booking_id = p_booking_id;

  v_new := "api"."create_booking"(
    v_ws_id, v_src.resource_id,
    COALESCE(p_title, v_src.title),
    p_starts_at, p_ends_at,
    v_src.timezone, v_src.status, v_src.all_day, v_src.location, v_src.color,
    v_src.notes, v_src.project_id, v_src.linked_experiment_record_id,
    v_part, v_samp
  );

  RETURN v_new;
END;
$$;
--> statement-breakpoint
ALTER FUNCTION api.duplicate_booking(p_booking_id uuid, p_starts_at timestamp with time zone, p_ends_at timestamp with time zone, p_title text) OWNER TO migrator;
--> statement-breakpoint
CREATE FUNCTION api.duplicate_sheet_instance(p_instance_id uuid, p_expected_revision bigint, p_name text) RETURNS api.sheet_instances
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE source api.sheet_instances; result api.sheet_instances; actor text:=api.current_user_id(); copied_state jsonb;
BEGIN
 IF p_instance_id IS NOT NULL THEN PERFORM internal.assert_object_access('instance',p_instance_id,'edit'); END IF; SELECT * INTO source FROM api.sheet_instances WHERE id=p_instance_id FOR UPDATE; IF source.id IS NULL OR NOT api.is_workspace_writer(source.workspace_id) THEN RAISE EXCEPTION 'workspace member required' USING ERRCODE='42501'; END IF; IF source.lifecycle<>'active' THEN RAISE EXCEPTION 'Sheet Instance is archived' USING ERRCODE='SB073'; END IF; IF source.revision<>p_expected_revision THEN RAISE EXCEPTION 'Sheet Instance revision conflict' USING ERRCODE='SB073'; END IF; IF length(btrim(p_name)) NOT BETWEEN 1 AND 200 THEN RAISE EXCEPTION 'invalid Sheet Instance name' USING ERRCODE='SB073'; END IF; copied_state:=jsonb_set(source.state,'{provenance}',jsonb_build_object('createdFrom','duplicate','duplicatedFromInstanceId',source.id),true); PERFORM set_config('sheetbase.sheet_instance_write','rpc-v1',true); INSERT INTO api.sheet_instances(workspace_id,project_id,notebook_record_id,source_definition_version_id,name,description,state,duplicated_from_instance_id,created_by_user_id,updated_by_user_id) VALUES(source.workspace_id,source.project_id,source.notebook_record_id,source.source_definition_version_id,btrim(p_name),source.description,copied_state,source.id,actor,actor) RETURNING * INTO result; RETURN result; END $$;
--> statement-breakpoint
ALTER FUNCTION api.duplicate_sheet_instance(p_instance_id uuid, p_expected_revision bigint, p_name text) OWNER TO migrator;
--> statement-breakpoint
CREATE FUNCTION api.duplicate_sheet_instance_block(p_block_id uuid, p_expected_structure_version integer) RETURNS jsonb
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
DECLARE
  source api.blocks;
  instance api.sheet_instances;
  copy api.sheet_instances;
  inserted jsonb;
BEGIN
  SELECT * INTO source FROM api.blocks WHERE id = p_block_id FOR UPDATE;
  IF source.id IS NULL THEN
    RAISE EXCEPTION 'block not found in active workspace' USING ERRCODE = '42501';
  END IF;
  IF source.type <> 'sheet' OR NOT (source.payload ? 'instanceId') THEN
    RAISE EXCEPTION 'only canonical Sheet Instance blocks can be duplicated this way'
      USING ERRCODE = '23514';
  END IF;
  SELECT * INTO instance FROM api.sheet_instances
    WHERE id = (source.payload->>'instanceId')::uuid;
  IF instance.id IS NULL THEN
    RAISE EXCEPTION 'Sheet Instance not found' USING ERRCODE = '42501';
  END IF;
  copy := api.duplicate_sheet_instance(instance.id, instance.revision, instance.name || ' copy');
  BEGIN
    inserted := api.insert_sheet_instance_block(
      source.record_id,
      source.id,
      p_expected_structure_version,
      copy.id
    );
  EXCEPTION WHEN OTHERS THEN
    PERFORM api.archive_sheet_instance(copy.id, copy.revision);
    RAISE;
  END;
  RETURN inserted;
END
$$;
--> statement-breakpoint
ALTER FUNCTION api.duplicate_sheet_instance_block(p_block_id uuid, p_expected_structure_version integer) OWNER TO migrator;
