CREATE FUNCTION api.edit_sample(p_record_id uuid, p_expected_metadata_version integer, p_title text DEFAULT NULL::text, p_properties jsonb DEFAULT NULL::jsonb, p_tags text[] DEFAULT NULL::text[], p_notes text DEFAULT NULL::text) RETURNS api.records
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
DECLARE
  v_row "api"."records";
  v_props jsonb;
  v_title text;
  v_tags text[];
BEGIN
  SELECT * INTO v_row FROM "api"."records" WHERE id = p_record_id FOR UPDATE;
  IF v_row IS NULL THEN
    RAISE EXCEPTION 'record not found in active workspace' USING ERRCODE = '42501';
  END IF;
  IF v_row.kind <> 'sample' THEN
    RAISE EXCEPTION 'record % is not a sample', p_record_id USING ERRCODE = 'SB009';
  END IF;
  IF v_row.archived_at IS NOT NULL THEN
    RAISE EXCEPTION 'cannot edit an archived sample' USING ERRCODE = 'SB004';
  END IF;
  IF v_row.metadata_version <> p_expected_metadata_version THEN
    RAISE EXCEPTION 'metadata version mismatch: expected %, got %',
      p_expected_metadata_version, v_row.metadata_version USING ERRCODE = 'SB001';
  END IF;

  v_props := v_row.properties;
  IF p_properties IS NOT NULL THEN
    -- quantity / quantityUnit / storageLocation are controlled by the
    -- audited receive / consume / transfer RPCs. edit_sample must not let a
    -- caller mutate them directly, or quantity and chain-of-custody changes
    -- would bypass the event log and its integrity checks.
    v_props := v_props || (
      p_properties - 'quantity' - 'quantityUnit' - 'storageLocation'
    );
  END IF;
  v_title := COALESCE(NULLIF(btrim(p_title), ''), v_row.title);
  v_tags := COALESCE(p_tags, v_row.tags);

  UPDATE "api"."records"
    SET title = v_title,
        tags = v_tags,
        properties = v_props,
        metadata_version = v_row.metadata_version + 1,
        updated_by_user_id = "api"."current_user_id"()
    WHERE id = p_record_id
    RETURNING * INTO v_row;

  INSERT INTO "api"."sample_events"
    (workspace_id, record_id, operation, actor_user_id, notes)
  VALUES
    (v_row.workspace_id, v_row.id, 'edit', "api"."current_user_id"(), p_notes);

  RETURN v_row;
END;
$$;
--> statement-breakpoint
ALTER FUNCTION api.edit_sample(p_record_id uuid, p_expected_metadata_version integer, p_title text, p_properties jsonb, p_tags text[], p_notes text) OWNER TO migrator;
--> statement-breakpoint
CREATE FUNCTION api.edit_sample(p_record_id uuid, p_expected_metadata_version integer, p_title text, p_properties jsonb, p_tags text[], p_notes text, p_custom_fields jsonb) RETURNS api.records
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
DECLARE result api.records; merged_properties jsonb;
BEGIN
 SELECT * INTO result FROM api.records WHERE id=p_record_id FOR UPDATE;
 IF result.id IS NULL THEN RAISE EXCEPTION 'record not found in active workspace' USING ERRCODE='42501'; END IF;
 IF result.kind<>'sample' THEN RAISE EXCEPTION 'record % is not a sample',p_record_id USING ERRCODE='SB009'; END IF;
 IF result.archived_at IS NOT NULL THEN RAISE EXCEPTION 'cannot edit an archived sample' USING ERRCODE='SB004'; END IF;
 IF result.metadata_version<>p_expected_metadata_version THEN RAISE EXCEPTION 'metadata version mismatch: expected %, got %',p_expected_metadata_version,result.metadata_version USING ERRCODE='SB001'; END IF;
 merged_properties:=result.properties;
 IF p_properties IS NOT NULL THEN merged_properties:=merged_properties||(p_properties-'quantity'-'quantityUnit'-'storageLocation'); END IF;
 UPDATE api.records SET title=coalesce(nullif(btrim(p_title),''),result.title),tags=coalesce(p_tags,result.tags),properties=merged_properties,
   custom_fields=CASE WHEN p_custom_fields IS NULL THEN result.custom_fields ELSE result.custom_fields||p_custom_fields END,
   metadata_version=result.metadata_version+1,updated_by_user_id=api.current_user_id()
 WHERE id=p_record_id RETURNING * INTO result;
 INSERT INTO api.sample_events(workspace_id,record_id,operation,actor_user_id,notes) VALUES(result.workspace_id,result.id,'edit',api.current_user_id(),p_notes);
 RETURN result;
END $$;
--> statement-breakpoint
ALTER FUNCTION api.edit_sample(p_record_id uuid, p_expected_metadata_version integer, p_title text, p_properties jsonb, p_tags text[], p_notes text, p_custom_fields jsonb) OWNER TO migrator;
