CREATE FUNCTION api.enable_extension(p_workspace_id uuid, p_extension_id uuid) RETURNS api.extensions
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
  v api.extensions;
BEGIN
  IF api.current_workspace_id() IS DISTINCT FROM p_workspace_id THEN
    RAISE EXCEPTION 'wrong workspace' USING ERRCODE = 'SB033';
  END IF;
  PERFORM api.require_capability(p_workspace_id, 'extensions.manage');
  SELECT * INTO v FROM api.extensions
   WHERE id = p_extension_id AND workspace_id = p_workspace_id FOR UPDATE;
  IF v IS NULL THEN
    RAISE EXCEPTION 'extension not found' USING ERRCODE = 'SB036';
  END IF;
  IF v.status = 'enabled' THEN
    RETURN v;
  END IF;
  UPDATE api.extensions SET
    status = 'enabled',
    updated_at = now(),
    updated_by_user_id = api.current_user_id()
  WHERE id = p_extension_id
  RETURNING * INTO v;
  RETURN v;
END $$;
--> statement-breakpoint
ALTER FUNCTION api.enable_extension(p_workspace_id uuid, p_extension_id uuid) OWNER TO migrator;
--> statement-breakpoint
CREATE FUNCTION api.ensure_parser(p_workspace_id uuid, p_key text, p_name text, p_format text, p_version integer, p_signature jsonb, p_mapping jsonb DEFAULT '{}'::jsonb, p_instrument_id uuid DEFAULT NULL::uuid, p_status text DEFAULT 'draft'::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE p api.parsers; v api.parser_versions;
BEGIN
  IF api.current_workspace_id() IS DISTINCT FROM p_workspace_id THEN RAISE EXCEPTION 'wrong workspace' USING ERRCODE = 'SB105'; END IF;
  IF NOT api.is_workspace_writer(p_workspace_id) OR NOT api.has_write_actor() THEN
    RAISE EXCEPTION 'not permitted to register a parser' USING ERRCODE = '42501'; END IF;
  IF p_status IS DISTINCT FROM 'draft' OR p_version IS NULL OR p_version < 1 THEN
    RAISE EXCEPTION 'registration must start with a draft and positive version' USING ERRCODE = '22023'; END IF;
  IF p_instrument_id IS NOT NULL AND NOT EXISTS (SELECT 1 FROM api.instruments WHERE id = p_instrument_id AND workspace_id = p_workspace_id) THEN
    RAISE EXCEPTION 'instrument not found' USING ERRCODE = 'SB106'; END IF;
  INSERT INTO api.parsers (workspace_id, key, name, format, instrument_id, created_by_user_id)
    VALUES (p_workspace_id, btrim(p_key), btrim(p_name), p_format, p_instrument_id, api.current_user_id())
    ON CONFLICT (workspace_id, key) DO UPDATE SET updated_at = api.parsers.updated_at RETURNING * INTO p;
  IF p.format <> p_format THEN RAISE EXCEPTION 'parser format mismatch' USING ERRCODE = 'SB107'; END IF;
  INSERT INTO api.parser_versions (workspace_id, parser_id, version, status, signature, mapping, created_by_user_id)
    VALUES (p_workspace_id, p.id, p_version, 'draft', coalesce(p_signature, '{}'), coalesce(p_mapping, '{}'), api.current_user_id())
    ON CONFLICT (parser_id, version) DO UPDATE SET updated_at = api.parser_versions.updated_at RETURNING * INTO v;
  RETURN jsonb_build_object('parserId', p.id, 'parserVersionId', v.id, 'version', v.version, 'status', v.status);
END $$;
--> statement-breakpoint
ALTER FUNCTION api.ensure_parser(p_workspace_id uuid, p_key text, p_name text, p_format text, p_version integer, p_signature jsonb, p_mapping jsonb, p_instrument_id uuid, p_status text) OWNER TO migrator;
--> statement-breakpoint
CREATE FUNCTION api.establish_connector_run_request(p_workspace_id uuid, p_run_id uuid, p_request_digest text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
  v "api"."connector_runs";
BEGIN
  IF "api"."current_workspace_id"() IS DISTINCT FROM p_workspace_id THEN
    RAISE EXCEPTION 'wrong workspace' USING ERRCODE = 'SB033';
  END IF;
  IF NOT "api"."is_workspace_writer"(p_workspace_id) THEN
    RAISE EXCEPTION 'capability required: workspace write' USING ERRCODE = '42501';
  END IF;
  IF p_request_digest IS NULL OR length(btrim(p_request_digest)) NOT BETWEEN 16 AND 128 THEN
    RAISE EXCEPTION 'invalid request digest' USING ERRCODE = 'SB034';
  END IF;
  SELECT * INTO v FROM "api"."connector_runs"
   WHERE id = p_run_id AND workspace_id = p_workspace_id FOR UPDATE;
  IF v IS NULL THEN
    RAISE EXCEPTION 'run not found' USING ERRCODE = 'SB036';
  END IF;
  IF v.status <> 'running' THEN
    RAISE EXCEPTION 'run already finished' USING ERRCODE = 'SB042';
  END IF;
  -- Identical content was already imported successfully: replay, never
  -- duplicate retained files or Dataset rows.
  IF EXISTS (
    SELECT 1 FROM "api"."connector_runs"
     WHERE connector_id = v.connector_id
       AND request_digest = btrim(p_request_digest)
       AND workspace_id = p_workspace_id
       AND status = 'succeeded'
  ) THEN
    RAISE EXCEPTION 'request already imported' USING ERRCODE = 'SB047';
  END IF;
  IF EXISTS (
    SELECT 1 FROM "api"."connector_runs"
     WHERE connector_id = v.connector_id
       AND request_digest = btrim(p_request_digest)
       AND workspace_id = p_workspace_id
       AND status = 'running'
       AND id <> p_run_id
  ) THEN
    RAISE EXCEPTION 'run already in progress' USING ERRCODE = 'SB044';
  END IF;
  UPDATE "api"."connector_runs"
     SET request_digest = btrim(p_request_digest)
   WHERE id = p_run_id;
END $$;
--> statement-breakpoint
ALTER FUNCTION api.establish_connector_run_request(p_workspace_id uuid, p_run_id uuid, p_request_digest text) OWNER TO migrator;
