    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$ DECLARE v api.instrument_runs; BEGIN
 IF p_run_id IS NOT NULL THEN PERFORM internal.assert_object_access('run',p_run_id,'edit'); END IF; IF api.current_workspace_id() IS DISTINCT FROM p_workspace_id THEN RAISE EXCEPTION 'wrong workspace' USING ERRCODE='SB033'; END IF; SELECT * INTO v FROM api.instrument_runs WHERE id=p_run_id AND workspace_id=p_workspace_id FOR UPDATE; IF v IS NULL THEN RAISE EXCEPTION 'run not found' USING ERRCODE='SB039'; END IF; IF v.status NOT IN ('running','queued') THEN RAISE EXCEPTION 'run cannot be failed' USING ERRCODE='SB042'; END IF; UPDATE api.instrument_runs SET status='failed',completed_at=now(),error_message=p_error_message,updated_at=now(),updated_by_user_id=api.current_user_id() WHERE id=p_run_id RETURNING * INTO v; INSERT INTO api.instrument_observations(workspace_id,run_id,source_id,observation_type,source_timestamp,payload) VALUES(p_workspace_id,p_run_id,'system-run-fail-'||v.id,'run_fail',now(),jsonb_build_object('errorMessage',p_error_message)); RETURN v; END $$;
