CREATE TABLE api.file_objects (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    workspace_id uuid NOT NULL,
    record_id uuid NOT NULL,
    storage_key text NOT NULL,
    display_name text NOT NULL,
    media_type text NOT NULL,
    byte_size bigint NOT NULL,
    checksum text,
    checksum_algorithm text DEFAULT 'sha256'::text NOT NULL,
    status text DEFAULT 'active'::text NOT NULL,
    status_reason text,
    storage_backend text DEFAULT 'local'::text NOT NULL,
    quarantined_at timestamp with time zone,
    deleted_at timestamp with time zone,
    version integer DEFAULT 1 NOT NULL,
    created_by_user_id text,
    updated_by_user_id text,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    extracted_text text,
    extracted_at timestamp with time zone,
    previous_version_id uuid,
    retention_until timestamp with time zone,
    CONSTRAINT chk_file_objects_byte_size CHECK (((byte_size >= 0) AND (byte_size <= 104857600))),
    CONSTRAINT chk_file_objects_checksum_algorithm CHECK ((checksum_algorithm = 'sha256'::text)),
    CONSTRAINT chk_file_objects_deleted_consistency CHECK (((status = 'deleted'::text) = (deleted_at IS NOT NULL))),
    CONSTRAINT chk_file_objects_media_type CHECK ((media_type = ANY (ARRAY['text/csv'::text, 'text/plain'::text, 'application/json'::text, 'application/pdf'::text, 'image/png'::text, 'image/jpeg'::text, 'image/tiff'::text, 'image/webp'::text, 'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet'::text, 'application/vnd.ms-excel'::text, 'application/vnd.openxmlformats-officedocument.wordprocessingml.document'::text, 'application/vnd.openxmlformats-officedocument.presentationml.presentation'::text, 'application/octet-stream'::text]))),
    CONSTRAINT chk_file_objects_quarantined_consistency CHECK (((status = 'quarantined'::text) = (quarantined_at IS NOT NULL))),
    CONSTRAINT chk_file_objects_status CHECK ((status = ANY (ARRAY['active'::text, 'quarantined'::text, 'deleted'::text, 'missing'::text]))),
    CONSTRAINT chk_file_objects_storage_backend CHECK ((storage_backend = ANY (ARRAY['local'::text, 's3'::text]))),
    CONSTRAINT chk_file_objects_storage_key CHECK ((storage_key ~ '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}/[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}/[0-9a-f]{32}$'::text))
);
