CREATE FUNCTION api.finalize_file_upload(p_file_id uuid, p_expected_version integer, p_expected_storage_key text, p_new_storage_key text, p_byte_size bigint, p_checksum text) RETURNS api.file_objects
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $_$
DECLARE
  file_object api.file_objects;
BEGIN
  SELECT * INTO file_object FROM api.file_objects
  WHERE id = p_file_id
    AND workspace_id = api.current_workspace_id()
    AND api.is_workspace_writer(workspace_id)
  FOR UPDATE;

  IF file_object.id IS NULL THEN
    RAISE EXCEPTION 'file object denied' USING ERRCODE = '42501';
  END IF;
  IF file_object.version <> p_expected_version
     OR file_object.storage_key IS DISTINCT FROM p_expected_storage_key THEN
    RAISE EXCEPTION 'file upload changed concurrently' USING ERRCODE = 'SB001';
  END IF;
  IF file_object.status NOT IN ('active', 'missing') THEN
    RAISE EXCEPTION 'file is not uploadable' USING ERRCODE = '42501';
  END IF;
  IF p_new_storage_key = file_object.storage_key
     OR p_new_storage_key !~ (
       '^' || file_object.workspace_id::text || '/' || file_object.id::text || '/[0-9a-f]{32}$'
     )
     OR p_checksum !~ '^[0-9a-f]{64}$'
     OR p_byte_size NOT BETWEEN 0 AND 104857600 THEN
    RAISE EXCEPTION 'invalid finalized file evidence' USING ERRCODE = '22023';
  END IF;

  UPDATE api.file_objects
  SET storage_key = p_new_storage_key,
      byte_size = p_byte_size,
      checksum = p_checksum,
      status = 'active',
      status_reason = NULL,
      quarantined_at = NULL,
      deleted_at = NULL,
      version = file_object.version + 1,
      updated_by_user_id = api.current_user_id(),
      updated_at = clock_timestamp()
  WHERE id = file_object.id
  RETURNING * INTO file_object;

  RETURN file_object;
END;
$_$;
--> statement-breakpoint
ALTER FUNCTION api.finalize_file_upload(p_file_id uuid, p_expected_version integer, p_expected_storage_key text, p_new_storage_key text, p_byte_size bigint, p_checksum text) OWNER TO migrator;
--> statement-breakpoint
CREATE FUNCTION api.flag_dataset_value(p_dataset_id uuid, p_row_id uuid, p_field_id uuid, p_kind text, p_reason text, p_comment text DEFAULT NULL::text) RETURNS api.dataset_value_flags
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
  d api.datasets;
  v api.dataset_value_flags;
BEGIN
 IF p_dataset_id IS NOT NULL THEN PERFORM internal.assert_object_access('dataset',p_dataset_id,'edit'); END IF;
  IF p_kind NOT IN ('out_of_range', 'missing_unit', 'above_curve', 'high_cv') THEN
    RAISE EXCEPTION 'unknown flag kind' USING ERRCODE = '22023';
  END IF;
  IF p_reason IS NULL OR length(btrim(p_reason)) NOT BETWEEN 1 AND 200 THEN
    RAISE EXCEPTION 'a reason is required to flag a value' USING ERRCODE = '22023';
  END IF;
  SELECT * INTO d FROM api.datasets
    WHERE id = p_dataset_id AND workspace_id = api.current_workspace_id()
      AND api.is_workspace_writer(workspace_id) AND api.has_write_actor()
    FOR UPDATE;
  IF d.id IS NULL THEN
    RAISE EXCEPTION 'Dataset denied' USING ERRCODE = '42501';
  END IF;
  IF NOT EXISTS (
    SELECT 1 FROM api.dataset_rows r
    WHERE r.id = p_row_id AND r.dataset_id = d.id
  ) THEN
    RAISE EXCEPTION 'row not found in Dataset' USING ERRCODE = '22023';
  END IF;
  IF NOT EXISTS (
    SELECT 1 FROM api.dataset_schema_version_fields f
    WHERE f.schema_version_id = d.schema_version_id AND f.field_id = p_field_id
  ) THEN
    RAISE EXCEPTION 'field not found in Dataset schema' USING ERRCODE = '22023';
  END IF;

  INSERT INTO api.dataset_value_flags
    (workspace_id, dataset_id, row_id, field_id, kind, source, reason, comment,
     set_by_user_id, set_at)
  VALUES
    (d.workspace_id, d.id, p_row_id, p_field_id, p_kind, 'manual', btrim(p_reason),
     nullif(btrim(coalesce(p_comment, '')), ''), api.current_user_id(), now())
  ON CONFLICT (dataset_id, row_id, field_id, kind, source) WHERE cleared_at IS NULL
  DO UPDATE SET reason = EXCLUDED.reason, comment = EXCLUDED.comment,
                set_by_user_id = EXCLUDED.set_by_user_id, set_at = now()
  RETURNING * INTO v;
  PERFORM internal.emit_change_event(
    d.workspace_id, 'dataset', d.id, 'create', NULL, d.primary_project_id,
    jsonb_build_object('action', 'value-flagged', 'flagId', v.id, 'kind', v.kind));

  RETURN v;
END;
$$;
--> statement-breakpoint
ALTER FUNCTION api.flag_dataset_value(p_dataset_id uuid, p_row_id uuid, p_field_id uuid, p_kind text, p_reason text, p_comment text) OWNER TO migrator;
