CREATE FUNCTION api.freeze_analysis_block(p_block_id uuid, p_expected_version integer) RETURNS api.blocks
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
  b api.blocks; owner api.records; definition jsonb; definition_name text; definition_version int;
  chart jsonb; ref jsonb; pinned api.dataset_versions; schema_version int;
  bound_fields text[]; columns jsonb; rowcount bigint; checksum text; frozen jsonb;
BEGIN
  SELECT * INTO b FROM api.blocks WHERE id=p_block_id FOR UPDATE;
  IF b.id IS NULL THEN RAISE EXCEPTION 'block not found in active workspace' USING ERRCODE='42501'; END IF;
  IF b.type<>'analysis' THEN RAISE EXCEPTION 'block is not an analysis' USING ERRCODE='23514'; END IF;
  IF b.version<>p_expected_version THEN RAISE EXCEPTION 'block version mismatch' USING ERRCODE='SB001'; END IF;
  IF jsonb_typeof(b.payload->'frozen')='object' THEN RAISE EXCEPTION 'analysis is already frozen' USING ERRCODE='23514'; END IF;
  SELECT * INTO owner FROM api.records WHERE id=b.record_id;
  IF owner.id IS NULL OR owner.workspace_id IS DISTINCT FROM api.current_workspace_id()
     OR NOT api.is_workspace_writer(owner.workspace_id) THEN
    RAISE EXCEPTION 'block not found in active workspace' USING ERRCODE='42501';
  END IF;
  SELECT d.definition,d.name,d.version INTO definition,definition_name,definition_version
    FROM api.analysis_definitions d WHERE d.id=(b.payload->>'definitionId')::uuid AND d.workspace_id=owner.workspace_id;
  IF definition IS NULL THEN RAISE EXCEPTION 'invalid analysis definition reference' USING ERRCODE='23514'; END IF;
  IF jsonb_typeof(definition->'datasets') IS DISTINCT FROM 'array' OR jsonb_array_length(definition->'datasets')<>1 THEN
    RAISE EXCEPTION 'definition must reference exactly one dataset' USING ERRCODE='23514';
  END IF;
  ref := definition->'datasets'->0;
  chart := nullif(definition->'chart','null'::jsonb);
  IF definition->>'kind'='chart' AND jsonb_typeof(chart) IS DISTINCT FROM 'object' THEN
    RAISE EXCEPTION 'a chart analysis must carry its chart' USING ERRCODE='23514';
  END IF;
  IF chart IS NOT NULL AND (jsonb_typeof(chart) IS DISTINCT FROM 'object'
    OR jsonb_typeof(chart->'datasets') IS DISTINCT FROM 'array' OR jsonb_array_length(chart->'datasets')<>1
    OR chart#>>'{datasets,0,datasetId}' IS DISTINCT FROM ref->>'datasetId'
    OR chart#>>'{datasets,0,datasetVersionId}' IS DISTINCT FROM ref->>'datasetVersionId') THEN
    RAISE EXCEPTION 'the chart must read the analysis dataset and version' USING ERRCODE='23514';
  END IF;
  pinned := api.analysis_evidence_source(ref,owner.workspace_id,'analysis block ' || b.id::text);
  SELECT sv.version INTO schema_version FROM api.dataset_schema_versions sv WHERE sv.id=pinned.schema_version_id;
  bound_fields := array_remove(ARRAY[definition#>>'{value,fieldId}',definition#>>'{group,fieldId}',
    definition#>>'{outcome,fieldId}',definition#>>'{predictor,fieldId}']::text[],NULL);
  IF chart IS NOT NULL THEN bound_fields := bound_fields || api.chart_spec_referenced_field_ids(chart); END IF;
  SELECT coalesce(jsonb_agg(jsonb_build_object('fieldId',f.field_id,'label',f.label,
    'logicalType',f.logical_type,'unit',f.quantity) ORDER BY f.display_order,f.field_id),'[]'::jsonb)
    INTO columns FROM api.dataset_schema_version_fields f
    WHERE f.schema_version_id=pinned.schema_version_id AND f.lifecycle='active' AND f.field_id::text=ANY(bound_fields);
  SELECT count(*),md5(coalesce(jsonb_agg(row_values ORDER BY row_id)::text,'[]')) INTO rowcount,checksum FROM (
    SELECT vr.row_id,coalesce((SELECT jsonb_object_agg(j.field_id,j.val) FROM (
      SELECT v.field_id,CASE WHEN count(*)=1 THEN
        (jsonb_agg(coalesce(to_jsonb(v.text_value),to_jsonb(v.integer_value),to_jsonb(v.numeric_value),
          to_jsonb(v.boolean_value),to_jsonb(v.date_value),to_jsonb(v.timestamp_value),to_jsonb(v.category_option_id),to_jsonb(v.reference_id)) ORDER BY v.ordinal))->0
        ELSE jsonb_agg(coalesce(to_jsonb(v.text_value),to_jsonb(v.integer_value),to_jsonb(v.numeric_value),
          to_jsonb(v.boolean_value),to_jsonb(v.date_value),to_jsonb(v.timestamp_value),to_jsonb(v.category_option_id),to_jsonb(v.reference_id)) ORDER BY v.ordinal) END AS val
      FROM api.dataset_version_values v WHERE v.dataset_version_id=pinned.id AND v.row_id=vr.row_id
        AND v.field_id::text=ANY(bound_fields) GROUP BY v.field_id
    ) j),'{}'::jsonb) AS row_values FROM api.dataset_version_rows vr WHERE vr.dataset_version_id=pinned.id
  ) per_row;
  IF rowcount=0 THEN RAISE EXCEPTION 'empty dataset' USING ERRCODE='23514'; END IF;
  IF rowcount>100000 THEN RAISE EXCEPTION 'dataset exceeds 100000-row analysis limit' USING ERRCODE='23514'; END IF;
  frozen := jsonb_build_object('revisionId',NULL,'frozenAt',to_char(clock_timestamp() AT TIME ZONE 'UTC','YYYY-MM-DD"T"HH24:MI:SS"Z"'),
    'frozenByUserId',api.current_user_id(),'methodVersion',1,
    'exclusionPolicy',CASE WHEN ref->>'datasetVersionId' IS NULL THEN 'exclude_bound_fields' ELSE 'include_flagged' END,
    'definition',definition,'definitionName',definition_name,'definitionVersion',definition_version,'columns',columns,
    'datasetProvenance',jsonb_build_array(jsonb_build_object('datasetId',pinned.dataset_id,'datasetVersionId',pinned.id,
      'schemaVersionNumber',schema_version,'sourceDatasetRevision',pinned.source_dataset_revision,
      'rowCount',rowcount,'checksum',checksum)));
  UPDATE api.blocks SET payload=jsonb_set(b.payload,ARRAY['frozen'],frozen),version=b.version+1,
    updated_by_user_id=api.current_user_id() WHERE id=p_block_id RETURNING * INTO b;
  RETURN b;
END $$;
--> statement-breakpoint
ALTER FUNCTION api.freeze_analysis_block(p_block_id uuid, p_expected_version integer) OWNER TO migrator;
--> statement-breakpoint
CREATE FUNCTION api.freeze_chart(p_block_id uuid, p_expected_version integer) RETURNS api.blocks
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
  b api.blocks; owner api.records; spec jsonb; ref jsonb; pinned api.dataset_versions;
  schema_version int; columns jsonb; rowcount bigint; checksum text; frozen jsonb;
BEGIN
  SELECT * INTO b FROM api.blocks WHERE id=p_block_id FOR UPDATE;
  IF b.id IS NULL THEN RAISE EXCEPTION 'block not found in active workspace' USING ERRCODE='42501'; END IF;
  IF b.type<>'chart' THEN RAISE EXCEPTION 'block is not a chart' USING ERRCODE='23514'; END IF;
  IF b.version<>p_expected_version THEN RAISE EXCEPTION 'block version mismatch' USING ERRCODE='SB001'; END IF;
  IF jsonb_typeof(b.payload->'frozen')='object' THEN RAISE EXCEPTION 'chart is already frozen' USING ERRCODE='23514'; END IF;
  SELECT * INTO owner FROM api.records WHERE id=b.record_id;
  IF owner.id IS NULL OR owner.workspace_id IS DISTINCT FROM api.current_workspace_id()
     OR NOT api.is_workspace_writer(owner.workspace_id) THEN
    RAISE EXCEPTION 'block not found in active workspace' USING ERRCODE='42501';
  END IF;
  spec := b.payload->'spec';
  IF jsonb_typeof(spec) IS DISTINCT FROM 'object' OR jsonb_array_length(spec->'datasets')<>1 THEN
    RAISE EXCEPTION 'invalid chart spec' USING ERRCODE='23514';
  END IF;
  ref := spec->'datasets'->0;
  pinned := api.analysis_evidence_source(ref,owner.workspace_id,'chart block ' || b.id::text);
  SELECT sv.version INTO schema_version FROM api.dataset_schema_versions sv WHERE sv.id=pinned.schema_version_id;
  SELECT coalesce(jsonb_agg(jsonb_build_object('fieldId',f.field_id,'label',f.label,
    'logicalType',f.logical_type,'unit',f.quantity) ORDER BY f.display_order,f.field_id),'[]'::jsonb)
    INTO columns FROM api.dataset_schema_version_fields f
    WHERE f.schema_version_id=pinned.schema_version_id AND f.lifecycle='active'
      AND f.field_id::text=ANY(api.chart_spec_referenced_field_ids(spec));
  SELECT count(*) INTO rowcount FROM api.dataset_version_rows WHERE dataset_version_id=pinned.id;
  IF rowcount=0 THEN RAISE EXCEPTION 'empty dataset' USING ERRCODE='23514'; END IF;
  IF rowcount>100000 THEN RAISE EXCEPTION 'dataset exceeds 100000-row analysis limit' USING ERRCODE='23514'; END IF;
  SELECT md5(coalesce(string_agg(vr.row_id::text || ':' || coalesce(vv.field_id::text,'') || ':' ||
    coalesce(vv.ordinal::text,'0') || ':' || coalesce(vv.numeric_value::text,vv.integer_value::text,vv.text_value,
      vv.boolean_value::text,vv.date_value::text,vv.timestamp_value::text,vv.category_option_id::text,vv.reference_id::text,''),
    E'\n' ORDER BY vr.row_id,vv.field_id,vv.ordinal),'')) INTO checksum
    FROM api.dataset_version_rows vr LEFT JOIN api.dataset_version_values vv
      ON vv.dataset_version_id=vr.dataset_version_id AND vv.row_id=vr.row_id WHERE vr.dataset_version_id=pinned.id;
  frozen := jsonb_build_object('revisionId',NULL,'frozenAt',to_char(clock_timestamp() AT TIME ZONE 'UTC','YYYY-MM-DD"T"HH24:MI:SS"Z"'),
    'frozenByUserId',api.current_user_id(),
    'exclusionPolicy',CASE WHEN ref->>'datasetVersionId' IS NULL THEN 'exclude_bound_fields' ELSE 'include_flagged' END,
    'datasetProvenance',jsonb_build_array(jsonb_build_object('datasetId',pinned.dataset_id,'datasetVersionId',pinned.id,
      'schemaVersionNumber',schema_version,'rowCount',rowcount,'checksum',checksum)),
    'data',jsonb_build_object('columns',columns,'rows','[]'::jsonb,'series','[]'::jsonb));
  UPDATE api.blocks SET payload=jsonb_set(b.payload,ARRAY['frozen'],frozen),version=b.version+1,
    updated_by_user_id=api.current_user_id() WHERE id=p_block_id RETURNING * INTO b;
  RETURN b;
END $$;
--> statement-breakpoint
ALTER FUNCTION api.freeze_chart(p_block_id uuid, p_expected_version integer) OWNER TO migrator;
--> statement-breakpoint
CREATE TABLE api.report_generations (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    workspace_id uuid NOT NULL,
    report_id uuid NOT NULL,
    report_version integer NOT NULL,
    generation_inputs jsonb NOT NULL,
    output_format text DEFAULT 'html'::text NOT NULL,
    output_checksum text NOT NULL,
    output_size_bytes bigint DEFAULT 0 NOT NULL,
    output_html text,
    actor_user_id text NOT NULL,
    generated_at timestamp with time zone DEFAULT now() NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT report_generations_output_checksum_check CHECK ((output_checksum ~ '^[0-9a-f]{64}$'::text)),
    CONSTRAINT report_generations_output_format_check CHECK ((output_format = ANY (ARRAY['html'::text, 'pdf'::text]))),
    CONSTRAINT report_generations_output_size_bytes_check CHECK ((output_size_bytes >= 0)),
    CONSTRAINT report_generations_report_version_check CHECK ((report_version > 0))
);
--> statement-breakpoint
ALTER TABLE api.report_generations OWNER TO migrator;
--> statement-breakpoint
CREATE FUNCTION api.generate_report(p_workspace_id uuid, p_report_id uuid, p_output_format text DEFAULT 'html'::text) RETURNS api.report_generations
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
  v_report api.report_definitions;
  v_sec api.report_sections;
  v_inputs jsonb;
  v_section_inputs jsonb := '[]'::jsonb;
  v_html text;
  v_section_html text;
  v_pos int := 0;
  v_gen api.report_generations;
BEGIN
 IF p_report_id IS NOT NULL THEN PERFORM internal.assert_object_access('report',p_report_id,'edit'); END IF;
  IF api.current_workspace_id() IS DISTINCT FROM p_workspace_id THEN
    RAISE EXCEPTION 'wrong workspace' USING ERRCODE='SB033';
  END IF;
  IF p_output_format NOT IN ('html','pdf') THEN
    RAISE EXCEPTION 'invalid output format' USING ERRCODE='SB047';
  END IF;
  SELECT * INTO v_report FROM api.report_definitions WHERE id=p_report_id AND workspace_id=p_workspace_id;
  IF v_report IS NULL THEN RAISE EXCEPTION 'report not found' USING ERRCODE='SB046'; END IF;
  -- Deterministic inputs: ordered section identity + frozen payload digest.
  FOR v_sec IN SELECT * FROM api.report_sections WHERE report_id=p_report_id ORDER BY position LOOP
    v_section_inputs := v_section_inputs || jsonb_build_array(jsonb_build_object(
      'position',v_pos,
      'sectionId',v_sec.id,
      'title',v_sec.title,
      'sectionType',v_sec.section_type,
      'sourceType',v_sec.source_type,
      'sourceRevisionId',v_sec.source_revision_id,
      'sourceRef',v_sec.source_ref,
      'frozenPayload',v_sec.frozen_payload
    ));
    v_pos := v_pos + 1;
  END LOOP;
  v_inputs := jsonb_build_object(
    'reportId',v_report.id,
    'reportVersion',v_report.version,
    'documentIdentifier',v_report.document_identifier,
    'title',v_report.title,
    'subtitle',v_report.subtitle,
    'outputFormat',p_output_format,
    'sections',v_section_inputs
  );
  -- Build deterministic HTML.
  v_html := '<!DOCTYPE html>'||chr(10)||'<html lang="en">'||chr(10)||
    '<head>'||chr(10)||'<meta charset="utf-8"/>'||chr(10)||
    '<title>'||v_report.title||'</title>'||chr(10)||
    '<style>body{font-family:system-ui,sans-serif;max-width:820px;margin:2rem auto;padding:0 1rem;color:#111}h1{font-size:1.6rem}.subtitle{color:#555;font-style:italic}section{margin:1.5rem 0;padding-bottom:1rem;border-bottom:1px solid #eee}section h2{font-size:1.15rem}.meta{font-size:.8rem;color:#666}.badge{display:inline-block;font-size:.7rem;padding:.1rem .4rem;border:1px solid #ccc;border-radius:3px}</style>'||chr(10)||
    '</head>'||chr(10)||'<body>'||chr(10)||
    '<h1>'||v_report.title||'</h1>'||chr(10)||
    CASE WHEN v_report.subtitle IS NOT NULL THEN '<p class="subtitle">'||v_report.subtitle||'</p>'||chr(10) ELSE '' END||
    '<p class="meta">'||v_report.document_identifier||' · v'||v_report.version||'</p>'||chr(10);
  FOR v_sec IN SELECT * FROM api.report_sections WHERE report_id=p_report_id ORDER BY position LOOP
    v_section_html := '<section>'||chr(10)||
      '<h2>'||COALESCE(v_sec.position+1,0)::text||'. '||v_sec.title||'</h2>'||chr(10);
    IF v_sec.description IS NOT NULL THEN
      v_section_html := v_section_html||'<p>'||v_sec.description||'</p>'||chr(10);
    END IF;
    v_section_html := v_section_html||
      '<p class="meta">Source: '||v_sec.source_type||
      COALESCE(' · revision '||substring(v_sec.source_revision_id::text,1,8),'')||
      ' · status '||v_sec.validation_status||'</p>'||chr(10);
    IF v_sec.frozen_payload IS NOT NULL AND v_sec.frozen_payload <> '{}'::jsonb THEN
      v_section_html := v_section_html||'<pre>'||regexp_replace(v_sec.frozen_payload::text,'<','&lt;','g')||'</pre>'||chr(10);
    END IF;
    v_section_html := v_section_html||'</section>'||chr(10);
    v_html := v_html||v_section_html;
  END LOOP;
  v_html := v_html||'</body>'||chr(10)||'</html>'||chr(10);
  INSERT INTO api.report_generations(
    workspace_id, report_id, report_version, generation_inputs, output_format,
    output_checksum, output_size_bytes, output_html, actor_user_id
  ) VALUES(
    p_workspace_id, p_report_id, v_report.version, v_inputs, p_output_format,
    encode(sha256(convert_to(v_inputs::text,'UTF8')),'hex'),
    octet_length(v_html), v_html, api.current_user_id()
  ) RETURNING * INTO v_gen;
  RETURN v_gen;
END $$;
--> statement-breakpoint
ALTER FUNCTION api.generate_report(p_workspace_id uuid, p_report_id uuid, p_output_format text) OWNER TO migrator;
--> statement-breakpoint
CREATE FUNCTION api.get_pipeline_run_job(p_workspace_id uuid, p_run_id uuid) RETURNS TABLE(kind text, state text, attempts integer, max_attempts integer, available_at timestamp with time zone, claimed_at timestamp with time zone, lease_expires_at timestamp with time zone, last_error text, enqueued_at timestamp with time zone, finished_at timestamp with time zone)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
BEGIN
  IF api.current_workspace_id() IS DISTINCT FROM p_workspace_id THEN
    RAISE EXCEPTION 'wrong workspace' USING ERRCODE = 'SB033';
  END IF;
  IF NOT api.is_workspace_member(p_workspace_id) THEN
    RAISE EXCEPTION 'capability required: workspace membership' USING ERRCODE = '42501';
  END IF;
  RETURN QUERY
  SELECT j.kind, j.state, j.attempts, j.max_attempts, j.available_at, j.claimed_at,
         j.lease_expires_at, j.last_error, j.enqueued_at, j.finished_at
    FROM internal.pipeline_run_jobs j
   WHERE j.run_id = p_run_id AND j.workspace_id = p_workspace_id
   ORDER BY j.enqueued_at DESC
   LIMIT 1;
END $$;
--> statement-breakpoint
ALTER FUNCTION api.get_pipeline_run_job(p_workspace_id uuid, p_run_id uuid) OWNER TO migrator;
--> statement-breakpoint
CREATE FUNCTION api.get_webhook_endpoint_health(p_workspace_id uuid, p_subscription_id uuid DEFAULT NULL::uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
  v_rows jsonb;
BEGIN
  IF api.current_workspace_id() IS DISTINCT FROM p_workspace_id THEN
    RAISE EXCEPTION 'wrong workspace' USING ERRCODE = 'SB033';
  END IF;
  IF NOT api.is_workspace_writer(p_workspace_id) AND
     coalesce(api.claim_probe()->>'role', '') <> 'api_client' THEN
    IF api.current_user_id() IS NULL AND api.current_credential_id() IS NULL THEN
      RAISE EXCEPTION 'workspace member required' USING ERRCODE = '42501';
    END IF;
  END IF;
  IF p_subscription_id IS NOT NULL THEN
    PERFORM 1 FROM api.webhook_subscriptions
     WHERE id = p_subscription_id AND workspace_id = p_workspace_id;
    IF NOT FOUND THEN
      RAISE EXCEPTION 'webhook subscription not found' USING ERRCODE = 'SB036';
    END IF;
  END IF;

  SELECT coalesce(jsonb_agg(h ORDER BY h.key), '[]'::jsonb)
    INTO v_rows
    FROM (
      SELECT
        s.id AS subscription_id,
        s.key AS key,
        s.url AS url,
        s.status AS status,
        s.consecutive_failures AS consecutive_failures,
        s.failure_threshold AS failure_threshold,
        s.max_retries AS max_retries,
        s.rate_limit_per_minute AS rate_limit_per_minute,
        w.total_24h AS total_24h,
        w.delivered_24h AS delivered_24h,
        w.failed_24h AS failed_24h,
        w.dead_letter_24h AS dead_letter_24h,
        w.retrying_24h AS retrying_24h,
        w.pending_24h AS pending_24h,
        CASE
          WHEN w.total_24h > 0
          THEN round((w.delivered_24h::numeric / w.total_24h::numeric), 4)
          ELSE NULL
        END AS success_rate_24h,
        w.last_delivered_at AS last_delivered_at,
        w.oldest_pending_at AS oldest_pending_at,
        CASE
          WHEN e.delivery_id IS NULL THEN NULL
          ELSE jsonb_build_object(
            'code', e.error_code,
            'message', e.error_message,
            'at', e.error_at,
            'delivery_id', e.delivery_id
          )
        END AS last_error
      FROM api.webhook_subscriptions s
      LEFT JOIN LATERAL (
        SELECT
          count(*) FILTER (WHERE d.created_at > now() - interval '24 hours') AS total_24h,
          count(*) FILTER (WHERE d.status = 'delivered' AND d.created_at > now() - interval '24 hours') AS delivered_24h,
          count(*) FILTER (WHERE d.status = 'failed' AND d.created_at > now() - interval '24 hours') AS failed_24h,
          count(*) FILTER (WHERE d.status = 'dead_letter' AND d.created_at > now() - interval '24 hours') AS dead_letter_24h,
          count(*) FILTER (WHERE d.status = 'retrying') AS retrying_24h,
          count(*) FILTER (WHERE d.status = 'pending') AS pending_24h,
          max(d.delivered_at) AS last_delivered_at,
          min(d.created_at) FILTER (WHERE d.status IN ('pending', 'retrying')) AS oldest_pending_at
        FROM api.webhook_deliveries d
        WHERE d.subscription_id = s.id
      ) w ON true
      LEFT JOIN LATERAL (
        SELECT d.error_code, d.error_message, d.updated_at AS error_at, d.id AS delivery_id
          FROM api.webhook_deliveries d
         WHERE d.subscription_id = s.id
           AND d.error_code IS NOT NULL
         ORDER BY d.updated_at DESC
         LIMIT 1
      ) e ON true
      WHERE s.workspace_id = p_workspace_id
        AND (p_subscription_id IS NULL OR s.id = p_subscription_id)
    ) h;

  RETURN jsonb_build_object('data', v_rows, 'generated_at', now());
END $$;
--> statement-breakpoint
