    CONSTRAINT instrument_observations_observation_type_check CHECK ((observation_type = ANY (ARRAY['telemetry'::text, 'stage_start'::text, 'stage_complete'::text, 'run_start'::text, 'run_complete'::text, 'run_fail'::text, 'plate_snapshot'::text, 'qc_result'::text, 'status_change'::text, 'heartbeat'::text])))
