CREATE FUNCTION api.insert_sheet_block(p_record_id uuid, p_after_block_id uuid DEFAULT NULL::uuid, p_expected_structure_version integer DEFAULT NULL::integer, p_dataset_schema_id uuid DEFAULT NULL::uuid) RETURNS jsonb
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
DECLARE
  inserted jsonb;
  created jsonb;
  table_id uuid;
  canonical api.blocks;
BEGIN
  PERFORM "internal"."require_migrator_legacy_sheet_write"();
  inserted := api.insert_block(
    p_record_id,
    'sheet',
    '{}'::jsonb,
    1,
    p_after_block_id,
    p_expected_structure_version
  );

  IF p_dataset_schema_id IS NOT NULL THEN
    created := api.instantiate_dataset_schema(
      (inserted #>> '{block,id}')::uuid,
      p_dataset_schema_id,
      'Scientific sheet',
      NULL
    );
  ELSE
    created := api.create_scientific_table(
      (inserted #>> '{block,id}')::uuid,
      'Scientific sheet',
      '[]'::jsonb,
      NULL
    );
  END IF;
  table_id := (created #>> '{table,id}')::uuid;

  UPDATE api.blocks
  SET payload = jsonb_build_object('tableId', table_id), updated_at = now()
  WHERE id = (inserted #>> '{block,id}')::uuid
  RETURNING * INTO canonical;

  RETURN jsonb_build_object(
    'block', to_jsonb(canonical),
    'table', created->'table',
    'columns', created->'columns',
    'resourceName', created #>> '{table,resource_name}',
    'structure_version', (inserted->>'structure_version')::int
  );
END $$;
--> statement-breakpoint
ALTER FUNCTION api.insert_sheet_block(p_record_id uuid, p_after_block_id uuid, p_expected_structure_version integer, p_dataset_schema_id uuid) OWNER TO migrator;
