CREATE FUNCTION api.instantiate_dataset_schema(p_block_id uuid, p_schema_id uuid, p_name text DEFAULT NULL::text, p_description text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE b api.blocks; r api.records; s api.dataset_schemas; a jsonb; tid uuid := gen_random_uuid(); rn text; f api.dataset_schema_fields; fn text; ord int := 0; colid uuid; compiled jsonb; spec jsonb; chk text; result jsonb; option_item jsonb; option_ord int;
BEGIN
  PERFORM "internal"."require_migrator_legacy_sheet_write"();
  SELECT * INTO s FROM api.dataset_schemas WHERE id=p_schema_id;
  IF s.id IS NULL THEN RAISE EXCEPTION 'schema not found' USING ERRCODE='P0002'; END IF;
  a := internal.assert_scientific_actor(s.workspace_id);
  IF s.status <> 'published' THEN RAISE EXCEPTION 'can only instantiate a published schema revision' USING ERRCODE='23514'; END IF;
  SELECT * INTO b FROM api.blocks WHERE id=p_block_id;
  IF b.id IS NULL OR b.type<>'sheet' THEN RAISE EXCEPTION 'owning block must be sheet' USING ERRCODE='23514'; END IF;
  SELECT * INTO r FROM api.records WHERE id=b.record_id;
  IF r.workspace_id IS DISTINCT FROM s.workspace_id THEN RAISE EXCEPTION 'block workspace does not match schema workspace' USING ERRCODE='23514'; END IF;
  LOOP rn := internal.scientific_name('sheet_'); EXIT WHEN to_regclass(format('api.%I',rn)) IS NULL AND NOT EXISTS(SELECT 1 FROM api.scientific_tables WHERE resource_name=rn); END LOOP;
  INSERT INTO api.scientific_tables(id,workspace_id,record_id,block_id,resource_name,name,description,created_by_user_id,created_by_credential_id,dataset_schema_id,dataset_schema_revision)
    VALUES(tid,r.workspace_id,r.id,b.id,rn,COALESCE(p_name,s.name),p_description,a->>'user_id',(a->>'credential_id')::uuid,s.id,s.revision);
  EXECUTE format('CREATE TABLE api.%I (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), workspace_id uuid NOT NULL DEFAULT api.current_workspace_id() CHECK (workspace_id=%L::uuid), version bigint NOT NULL DEFAULT 1 CHECK(version>0), created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), formula_column_ids uuid[] NOT NULL DEFAULT ARRAY[]::uuid[], created_by_user_id text, created_by_credential_id uuid, updated_by_user_id text, updated_by_credential_id uuid)',rn,r.workspace_id);
  FOR f IN SELECT * FROM api.dataset_schema_fields WHERE schema_id=s.id AND lifecycle='active' ORDER BY display_order LOOP
    ord := ord+1;
    spec := jsonb_build_object('label',f.label,'logical_type',f.logical_type,'nullable',f.nullable,'validation',coalesce(f.validation,'{}'::jsonb))
      || CASE WHEN f.default_value IS NULL THEN '{}' ELSE jsonb_build_object('default',f.default_value) END
      || CASE WHEN f.unit IS NULL THEN '{}' ELSE jsonb_build_object('unit',f.unit) END;
    compiled := internal.compile_scientific_column(spec);
    LOOP fn := internal.scientific_name('col_'); EXIT WHEN NOT EXISTS(SELECT 1 FROM api.scientific_columns WHERE field_name=fn); END LOOP;
    colid := gen_random_uuid();
    INSERT INTO api.scientific_columns(id,table_id,workspace_id,field_name,label,description,display_order,logical_type,nullable,default_value,unit,validation,created_by_user_id,created_by_credential_id,dataset_schema_field_id)
      VALUES(colid,tid,r.workspace_id,fn,f.label,f.description,ord,f.logical_type,f.nullable,f.default_value,f.unit,coalesce(f.validation,'{}'),a->>'user_id',(a->>'credential_id')::uuid,f.id);
    EXECUTE format('ALTER TABLE api.%I ADD COLUMN %I %s%s%s',rn,fn,compiled->>'storageType',compiled->>'defaultSql',compiled->>'notNullSql');
    FOR chk IN SELECT value#>>'{}' FROM jsonb_array_elements(compiled->'checks') LOOP EXECUTE format('ALTER TABLE api.%I ADD CHECK (%s)',rn,internal.render_scientific_check(chk::jsonb,fn)); END LOOP;
  END LOOP;
  EXECUTE format('ALTER TABLE api.%I ENABLE ROW LEVEL SECURITY',rn);
  EXECUTE format('CREATE POLICY %I ON api.%I FOR ALL TO authenticated USING (workspace_id=api.current_workspace_id() AND api.is_workspace_member(workspace_id)) WITH CHECK (workspace_id=api.current_workspace_id() AND api.is_workspace_member(workspace_id))','scientific_rows_member',rn);
  EXECUTE format('GRANT SELECT ON api.%I TO authenticated',rn);
  IF ord>0 THEN EXECUTE format('GRANT INSERT (%s), UPDATE (%s) ON api.%I TO authenticated',(SELECT string_agg(format('%I',field_name),',') FROM api.scientific_columns WHERE table_id=tid),(SELECT string_agg(format('%I',field_name),',') FROM api.scientific_columns WHERE table_id=tid),rn); END IF;
  EXECUTE format('CREATE TRIGGER scientific_row_before BEFORE INSERT OR UPDATE OR DELETE ON api.%I FOR EACH ROW EXECUTE FUNCTION internal.scientific_row_before()',rn);
  EXECUTE format('CREATE TRIGGER scientific_row_event AFTER INSERT OR UPDATE OR DELETE ON api.%I FOR EACH ROW EXECUTE FUNCTION internal.scientific_row_event()',rn);
  PERFORM internal.emit_change_event(r.workspace_id,'scientific_table',tid,'create',r.id,r.project_id,jsonb_build_object('tableId',tid,'schemaVersion',1,'operation','instantiate','datasetSchemaId',s.id,'datasetSchemaRevision',s.revision,'columnIds',(SELECT coalesce(jsonb_agg(id ORDER BY display_order),'[]') FROM api.scientific_columns WHERE table_id=tid)));
  PERFORM pg_notify('pgrst','reload schema');
  SELECT jsonb_build_object('table',to_jsonb(t),'columns',(SELECT coalesce(jsonb_agg(to_jsonb(c) ORDER BY display_order),'[]') FROM api.scientific_columns c WHERE table_id=tid),'resourceName',rn) INTO result FROM api.scientific_tables t WHERE id=tid;
  RETURN result;
END $$;
--> statement-breakpoint
ALTER FUNCTION api.instantiate_dataset_schema(p_block_id uuid, p_schema_id uuid, p_name text, p_description text) OWNER TO migrator;
--> statement-breakpoint
CREATE FUNCTION api.instantiate_notebook_template_version(p_version_id uuid, p_target_project_id uuid, p_title text, p_parameter_inputs jsonb, p_idempotency_key text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
  workspace uuid := api.current_workspace_id();
  actor text := api.current_user_id();
  version api.notebook_template_versions;
  template api.notebook_templates;
  project api.projects;
  existing api.notebook_template_instantiations;
  rec api.records;
  placement jsonb;
  instance api.sheet_instances;
  inserted jsonb;
  narrated jsonb;
  mapped jsonb;
  title text;
  result jsonb;
  composition jsonb := '[]'::jsonb;
  missing_keys text[];
  duplicate_input text;
  unknown_input text;
  entry jsonb;
BEGIN
 IF p_target_project_id IS NOT NULL THEN PERFORM internal.assert_object_access('project',p_target_project_id,'edit'); END IF;
  IF workspace IS NULL OR actor IS NULL OR NOT api.is_workspace_writer(workspace) THEN
    RAISE EXCEPTION 'workspace member required' USING ERRCODE = '42501';
  END IF;
  IF p_idempotency_key IS NULL OR length(p_idempotency_key) NOT BETWEEN 1 AND 128 THEN
    RAISE EXCEPTION 'valid idempotency key is required' USING ERRCODE = '22023';
  END IF;
  SELECT * INTO existing FROM api.notebook_template_instantiations
    WHERE workspace_id = workspace AND actor_user_id = actor AND idempotency_key = p_idempotency_key;
  IF existing.id IS NOT NULL THEN
    IF existing.template_version_id IS DISTINCT FROM p_version_id THEN
      RAISE EXCEPTION 'idempotency key was used for a different Template Version' USING ERRCODE = '23505';
    END IF;
    RETURN existing.result || jsonb_build_object('idempotent', true);
  END IF;

  SELECT v.* INTO version
    FROM api.notebook_template_versions v
    JOIN api.notebook_templates t ON t.id = v.template_id
    WHERE v.id = p_version_id AND t.workspace_id = workspace;
  IF version.id IS NULL OR version.lifecycle <> 'published' THEN
    RAISE EXCEPTION 'only a published Notebook Template Version can be instantiated' USING ERRCODE = 'SB090';
  END IF;
  SELECT * INTO template FROM api.notebook_templates WHERE id = version.template_id;
  IF template.lifecycle <> 'active' THEN
    RAISE EXCEPTION 'retired Notebook Template cannot be instantiated' USING ERRCODE = 'SB090';
  END IF;
  SELECT * INTO project FROM api.projects WHERE id = p_target_project_id AND workspace_id = workspace;
  IF project.id IS NULL THEN
    RAISE EXCEPTION 'target project not found in active workspace' USING ERRCODE = '42501';
  END IF;
  title := nullif(btrim(coalesce(p_title,'')), '');
  IF title IS NULL THEN title := template.name; END IF;
  IF p_parameter_inputs IS NOT NULL AND jsonb_typeof(p_parameter_inputs) <> 'array' THEN
    RAISE EXCEPTION 'Template parameter inputs must be an array' USING ERRCODE = 'SB091';
  END IF;
  -- Shape gate runs before duplicate/unknown/required checks: input->>'parameterId'
  -- yields SQL NULL for a missing key, an explicit JSON null, or a non-object
  -- entry, so without this gate NULL parameterIds evade both GROUP BY duplicate
  -- detection (INTO a NULL variable the IS NOT NULL guard misses) and the
  -- unknown-input NOT EXISTS check. Every entry must mirror the SheetParameterInput
  -- wire shape: an object with a string parameterId, a known kind, and the
  -- kind-appropriate payload (scalar values stay JSON scalars; reference kinds
  -- carry their UUID as text — deeper resolution stays downstream).
  FOR entry IN SELECT value FROM jsonb_array_elements(coalesce(p_parameter_inputs,'[]'::jsonb)) LOOP
    IF jsonb_typeof(entry) IS DISTINCT FROM 'object'
       OR jsonb_typeof(entry->'parameterId') IS DISTINCT FROM 'string'
       OR coalesce(entry->>'kind','') NOT IN ('scalar','record','dataset','dataset-version')
       OR (entry->>'kind' = 'scalar'
           AND (NOT (entry ? 'value')
                OR coalesce(jsonb_typeof(entry->'value'),'') NOT IN ('string','number','boolean','null')))
       OR (entry->>'kind' = 'record'
           AND jsonb_typeof(entry->'recordId') IS DISTINCT FROM 'string')
       OR (entry->>'kind' = 'dataset'
           AND jsonb_typeof(entry->'datasetId') IS DISTINCT FROM 'string')
       OR (entry->>'kind' = 'dataset-version'
           AND jsonb_typeof(entry->'datasetVersionId') IS DISTINCT FROM 'string')
    THEN
      RAISE EXCEPTION 'malformed Template parameter input' USING ERRCODE = 'SB091';
    END IF;
  END LOOP;
  SELECT input->>'parameterId' INTO duplicate_input
    FROM jsonb_array_elements(coalesce(p_parameter_inputs,'[]'::jsonb)) input
    GROUP BY input->>'parameterId'
    HAVING count(*) > 1
    LIMIT 1;
  IF duplicate_input IS NOT NULL THEN
    RAISE EXCEPTION 'duplicate Template parameter input: %', duplicate_input USING ERRCODE = 'SB091';
  END IF;
  SELECT input->>'parameterId' INTO unknown_input
  -- NOTE: the outer input alias must not be named `value` here. An outer
  -- `value` alias correlated into the NOT EXISTS subquery silently matches
  -- nothing (every input reads as unknown), while the same shape with
  -- `input`/`parameter` behaves. Keep these aliases.
    FROM jsonb_array_elements(coalesce(p_parameter_inputs,'[]'::jsonb)) input
    WHERE NOT EXISTS (
      SELECT 1 FROM jsonb_array_elements(coalesce(version.configuration->'parameters','[]'::jsonb)) parameter
      WHERE parameter->>'id' = input->>'parameterId'
    )
    LIMIT 1;
  IF unknown_input IS NOT NULL THEN
    RAISE EXCEPTION 'unknown Template parameter input: %', unknown_input USING ERRCODE = 'SB091';
  END IF;
  SELECT coalesce(array_agg(parameter->>'key' ORDER BY parameter->>'key'), '{}') INTO missing_keys
    FROM jsonb_array_elements(coalesce(version.configuration->'parameters','[]'::jsonb)) parameter
    WHERE coalesce((parameter->>'required')::boolean, false)
      AND NOT EXISTS (
        SELECT 1 FROM jsonb_array_elements(coalesce(p_parameter_inputs,'[]'::jsonb)) input
        WHERE input->>'parameterId' = parameter->>'id'
      );
  IF array_length(missing_keys, 1) IS NOT NULL THEN
    RAISE EXCEPTION 'required Template parameter(s) not supplied: %', array_to_string(missing_keys, ', ')
      USING ERRCODE = 'SB091';
  END IF;

  rec := api.create_record(p_target_project_id, 'experiment', title, 'draft', '{}'::text[], '{}'::jsonb);
  UPDATE api.records
    SET source_notebook_template_version_id = version.id
    WHERE id = rec.id;

  FOR placement IN
    SELECT value FROM jsonb_array_elements(coalesce(version.configuration->'placements','[]'::jsonb)) value
    ORDER BY (value->>'order')::int, value->>'id'
  LOOP
    IF placement->>'kind' = 'narrative' THEN
      narrated := api.insert_block(
        rec.id,
        placement->>'blockType',
        placement->'payload',
        1,
        NULL,
        NULL
      );
      composition := composition || jsonb_build_array(jsonb_build_object(
        'placementId', placement->>'id',
        'kind', 'narrative',
        'blockType', placement->>'blockType',
        'blockId', narrated->'block'->>'id'
      ));
    ELSIF placement->>'kind' = 'sheet' THEN
      mapped := internal.template_parameter_inputs_for_placement(placement, coalesce(p_parameter_inputs,'[]'::jsonb));
      instance := api.create_sheet_instance_from_definition(
        workspace,
        coalesce(nullif(btrim(placement->>'title'),''), 'Notebook sheet'),
        NULL,
        (placement->>'definitionVersionId')::uuid,
        rec.project_id,
        rec.id,
        internal.definition_derived_instance_state(),
        mapped
      );
      inserted := api.insert_sheet_instance_block(rec.id, NULL, NULL, instance.id);
      PERFORM internal.assign_sheet_block_template_placement(
        (inserted->'block'->>'id')::uuid,
        (placement->>'id')::uuid
      );
      composition := composition || jsonb_build_array(jsonb_build_object(
        'placementId', placement->>'id',
        'kind', 'sheet',
        'definitionVersionId', placement->>'definitionVersionId',
        'instanceId', instance.id,
        'blockId', inserted->'block'->>'id'
      ));
    ELSE
      composition := composition || jsonb_build_array(jsonb_build_object(
        'placementId', placement->>'id',
        'kind', coalesce(placement->>'kind', 'section_placeholder')
      ));
    END IF;
  END LOOP;

  SELECT * INTO rec FROM api.records WHERE id = rec.id;
  result := jsonb_build_object(
    'record', to_jsonb(rec),
    'templateVersionId', version.id,
    'composition', composition,
    'idempotent', false
  );
  INSERT INTO api.notebook_template_instantiations(
    workspace_id, actor_user_id, idempotency_key, template_version_id, record_id, result
  ) VALUES (workspace, actor, p_idempotency_key, version.id, rec.id, result);
  RETURN result;
END
$$;
--> statement-breakpoint
