    AS $$ DECLARE v api.instrument_run_links; r api.records; BEGIN
 IF p_run_id IS NOT NULL THEN PERFORM internal.assert_object_access('run',p_run_id,'edit'); END IF;
 IF p_linked_record_id IS NOT NULL THEN PERFORM internal.assert_object_access('record',p_linked_record_id,'view'); END IF; IF api.current_workspace_id() IS DISTINCT FROM p_workspace_id THEN RAISE EXCEPTION 'wrong workspace' USING ERRCODE='SB033'; END IF; IF NOT EXISTS(SELECT 1 FROM api.instrument_runs WHERE id=p_run_id AND workspace_id=p_workspace_id) THEN RAISE EXCEPTION 'run not found' USING ERRCODE='SB039'; END IF; IF p_link_type NOT IN ('experiment','sample','protocol','file') THEN RAISE EXCEPTION 'invalid link type' USING ERRCODE='SB043'; END IF; SELECT * INTO r FROM api.records WHERE id=p_linked_record_id AND workspace_id=p_workspace_id; IF r IS NULL THEN RAISE EXCEPTION 'record not found' USING ERRCODE='SB043'; END IF; INSERT INTO api.instrument_run_links(workspace_id,run_id,linked_record_id,linked_record_identifier,linked_record_title,link_type) VALUES(p_workspace_id,p_run_id,r.id,r.identifier,r.title,p_link_type) RETURNING * INTO v; RETURN v; END $$;
