CREATE FUNCTION api.link_study_experiment(p_study_record_id uuid, p_experiment_record_id uuid, p_relationship text DEFAULT 'member'::text) RETURNS api.study_experiments
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE study api.studies; result api.study_experiments; project uuid;
BEGIN
 IF p_study_record_id IS NOT NULL THEN PERFORM internal.assert_object_access('record',p_study_record_id,'edit'); END IF;
 IF p_experiment_record_id IS NOT NULL THEN PERFORM internal.assert_object_access('record',p_experiment_record_id,'edit'); END IF;
  SELECT * INTO study FROM api.studies WHERE record_id=p_study_record_id;
  IF study.record_id IS NULL OR api.current_workspace_id() IS DISTINCT FROM study.workspace_id OR NOT api.is_workspace_writer(study.workspace_id) THEN RAISE EXCEPTION 'Study not found in active workspace' USING ERRCODE='42501'; END IF;
  INSERT INTO api.study_experiments(study_record_id,experiment_record_id,relationship,created_by_user_id)
    VALUES(p_study_record_id,p_experiment_record_id,p_relationship,api.current_user_id()) RETURNING * INTO result;
  SELECT project_id INTO project FROM api.records WHERE id=p_experiment_record_id;
  PERFORM internal.emit_change_event(study.workspace_id,'study_experiment',p_study_record_id,'link',p_study_record_id,project,to_jsonb(result));
  RETURN result;
END $$;
