CREATE FUNCTION api.mark_notifications_read(p_ids uuid[] DEFAULT NULL::uuid[]) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
  v_user_id text := api.current_user_id();
  v_count integer;
BEGIN
  IF v_user_id IS NULL THEN
    RAISE EXCEPTION 'mark_notifications_read requires an authenticated user' USING ERRCODE = '42501';
  END IF;
  UPDATE internal.notifications
    SET read_at = now()
    WHERE user_id = v_user_id
      AND read_at IS NULL
      AND (p_ids IS NULL OR id = ANY (p_ids));
  GET DIAGNOSTICS v_count = ROW_COUNT;
  RETURN v_count;
END;
$$;
--> statement-breakpoint
ALTER FUNCTION api.mark_notifications_read(p_ids uuid[]) OWNER TO migrator;
