CREATE FUNCTION api.move_block(p_block_id uuid, p_expected_structure_version integer, p_after_block_id uuid DEFAULT NULL::uuid, p_before_block_id uuid DEFAULT NULL::uuid) RETURNS jsonb
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_moved "api"."blocks";
  v_record_id uuid;
  v_sv int;
  v_after_order real;
  v_before_order real;
  v_new_order real;
  v_gap real;
  v_after "api"."blocks";
  v_before "api"."blocks";
  v_rebalanced boolean := false;
  v_order_list jsonb;
BEGIN
  SELECT * INTO v_moved FROM "api"."blocks" WHERE id = p_block_id FOR UPDATE;
  IF v_moved IS NULL THEN
    RAISE EXCEPTION 'block not found in active workspace' USING ERRCODE = '42501';
  END IF;
  v_record_id := v_moved.record_id;

  -- Lock the record and verify structure_version for optimistic concurrency.
  SELECT structure_version INTO v_sv FROM "api"."records" WHERE id = v_record_id FOR UPDATE;
  IF v_sv IS NULL THEN
    RAISE EXCEPTION 'record not found in active workspace' USING ERRCODE = '42501';
  END IF;
  IF v_sv <> p_expected_structure_version THEN
    RAISE EXCEPTION 'structure version mismatch: expected %, got %',
      p_expected_structure_version, v_sv USING ERRCODE = 'SB001';
  END IF;

  -- Resolve the neighbour orders. Neighbours must be in the same record and
  -- not the moved block itself.
  IF p_after_block_id IS NOT NULL THEN
    SELECT * INTO v_after FROM "api"."blocks"
      WHERE id = p_after_block_id AND record_id = v_record_id AND id <> p_block_id
      FOR UPDATE;
    IF v_after IS NULL THEN
      RAISE EXCEPTION 'after_block is not in the same record' USING ERRCODE = '23503';
    END IF;
    v_after_order := v_after."order";
  END IF;
  IF p_before_block_id IS NOT NULL THEN
    SELECT * INTO v_before FROM "api"."blocks"
      WHERE id = p_before_block_id AND record_id = v_record_id AND id <> p_block_id
      FOR UPDATE;
    IF v_before IS NULL THEN
      RAISE EXCEPTION 'before_block is not in the same record' USING ERRCODE = '23503';
    END IF;
    v_before_order := v_before."order";
  END IF;

  -- Fractional indexing. p_after is the preceding neighbour, p_before the
  -- following one, so after_order < new_order < before_order must hold.
  IF p_after_block_id IS NULL AND p_before_block_id IS NULL THEN
    -- No neighbours given: move to the end of the record.
    SELECT COALESCE(max("order"), 0) + 1 INTO v_new_order
      FROM "api"."blocks" WHERE record_id = v_record_id;
  ELSIF p_after_block_id IS NULL THEN
    -- Move to the start: place before the first neighbour.
    v_new_order := v_before_order / 2.0;
  ELSIF p_before_block_id IS NULL THEN
    -- Move to the end: place after the last neighbour.
    v_new_order := v_after_order + 1.0;
  ELSE
    IF v_after_order >= v_before_order THEN
      RAISE EXCEPTION 'after_block must precede before_block' USING ERRCODE = '23514';
    END IF;
    v_new_order := (v_after_order + v_before_order) / 2.0;
  END IF;

  -- Detect precision exhaustion. 1e-3 keeps ~10 levels of fractional insert
  -- before a rebalance; double precision gives far more in practice.
  v_gap := v_new_order;
  IF p_after_block_id IS NOT NULL AND p_before_block_id IS NOT NULL THEN
    v_gap := v_before_order - v_after_order;
  END IF;

  IF v_gap <= 1e-3 AND NOT (p_after_block_id IS NULL AND p_before_block_id IS NULL) THEN
    -- Rebalance: assign integer positions 1..N in the target order. Build
    -- the target ordering by removing the moved block from its current spot
    -- and inserting it at the (after, before) boundary.
    v_rebalanced := true;
    -- Re-key every block in the record to integers 1..N in the target
    -- order. The moved block is repositioned by giving it a sort key that
    -- lands between its requested neighbours; every other block keeps its
    -- current order as the sort key. row_number() then produces stable
    -- integer positions with no precision exhaustion.
    WITH reordered AS (
      SELECT
        id,
        CASE
          WHEN id = p_block_id THEN
            CASE
              WHEN p_after_block_id IS NULL THEN -1e9::real
              ELSE v_after_order + 0.5
            END
          ELSE "order"
        END AS sort_key,
        CASE WHEN id = p_block_id THEN 1 ELSE 0 END AS moved_flag
      FROM "api"."blocks"
      WHERE record_id = v_record_id
    ),
    ranked AS (
      SELECT id, row_number() OVER (ORDER BY sort_key, moved_flag) AS new_pos
      FROM reordered
    )
    UPDATE "api"."blocks" AS b
      SET "order" = r.new_pos::real,
          updated_by_user_id = "api"."current_user_id"()
      FROM ranked r
      WHERE b.id = r.id;
    SELECT "order" INTO v_new_order
      FROM "api"."blocks" WHERE id = p_block_id;
  ELSE
    UPDATE "api"."blocks"
      SET "order" = v_new_order,
          updated_by_user_id = "api"."current_user_id"()
      WHERE id = p_block_id;
  END IF;

  -- Bump the record structure_version so concurrent moves fail with SB001.
  UPDATE "api"."records"
    SET structure_version = v_sv + 1
    WHERE id = v_record_id;

  SELECT jsonb_agg(jsonb_build_object('id', id, 'order', "order") ORDER BY "order")
    INTO v_order_list
    FROM "api"."blocks" WHERE record_id = v_record_id;

  RETURN jsonb_build_object(
    'block', to_jsonb(v_moved),
    'structure_version', v_sv + 1,
    'rebalanced', v_rebalanced,
    'order', COALESCE(v_order_list, '[]'::jsonb)
  );
END;
$$;
--> statement-breakpoint
ALTER FUNCTION api.move_block(p_block_id uuid, p_expected_structure_version integer, p_after_block_id uuid, p_before_block_id uuid) OWNER TO migrator;
--> statement-breakpoint
CREATE FUNCTION api.move_record_to_project(p_record_id uuid, p_project_id uuid, p_expected_metadata_version bigint) RETURNS api.records
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
  v_record api.records;
  v_from uuid;
BEGIN
  SELECT * INTO v_record FROM api.records
   WHERE id = p_record_id AND deleted_at IS NULL FOR UPDATE;
  IF v_record.id IS NULL THEN
    RAISE EXCEPTION 'record not found' USING ERRCODE = 'SB036';
  END IF;
  IF v_record.kind <> 'experiment' THEN
    RAISE EXCEPTION 'not an experiment' USING ERRCODE = '22023';
  END IF;
  IF NOT api.is_workspace_writer(v_record.workspace_id) THEN
    RAISE EXCEPTION 'capability required: workspace write' USING ERRCODE = '42501';
  END IF;
  IF p_expected_metadata_version IS NULL
     OR p_expected_metadata_version IS DISTINCT FROM v_record.metadata_version THEN
    RAISE EXCEPTION 'stale Record metadata revision' USING ERRCODE = 'SB001';
  END IF;
  IF v_record.status <> 'draft' THEN
    RAISE EXCEPTION 'only a draft experiment can move to another project' USING ERRCODE = 'SB109';
  END IF;
  IF v_record.project_id IS NOT DISTINCT FROM p_project_id THEN
    RAISE EXCEPTION 'experiment is already in that project' USING ERRCODE = '22023';
  END IF;
  IF NOT EXISTS (
    SELECT 1 FROM api.projects
     WHERE id = p_project_id AND workspace_id = v_record.workspace_id
  ) THEN
    RAISE EXCEPTION 'project not found in the active workspace' USING ERRCODE = '42501';
  END IF;
  IF internal.project_is_archived(p_project_id) THEN
    RAISE EXCEPTION 'project is archived' USING ERRCODE = 'SB004';
  END IF;
  IF v_record.project_id IS NULL
     OR NOT internal.can_edit_project(v_record.project_id)
     OR NOT internal.can_edit_project(p_project_id) THEN
    RAISE EXCEPTION 'project edit authority required' USING ERRCODE = '42501';
  END IF;
  IF EXISTS (SELECT 1 FROM api.sheet_instances WHERE notebook_record_id = v_record.id)
     OR EXISTS (
       SELECT 1 FROM api.calendar_bookings WHERE linked_experiment_record_id = v_record.id
     ) THEN
    RAISE EXCEPTION 'a draft with sheets or bookings cannot move to another project'
      USING ERRCODE = 'SB109';
  END IF;

  v_from := v_record.project_id;
  UPDATE api.records
     SET project_id = p_project_id,
         folder_id = NULL,
         metadata_version = metadata_version + 1,
         updated_at = now(),
         updated_by_user_id = api.current_user_id()
   WHERE id = v_record.id
  RETURNING * INTO v_record;
  PERFORM internal.emit_change_event(v_record.workspace_id, 'record', v_record.id, 'update',
    v_record.id, v_record.project_id,
    jsonb_build_object('effect', 'experiment_moved',
      'fromProjectId', v_from, 'toProjectId', p_project_id));
  RETURN v_record;
END $$;
--> statement-breakpoint
ALTER FUNCTION api.move_record_to_project(p_record_id uuid, p_project_id uuid, p_expected_metadata_version bigint) OWNER TO migrator;
--> statement-breakpoint
CREATE FUNCTION api.move_records_to_folder(p_project_id uuid, p_record_ids uuid[], p_folder_id uuid) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
  v_count integer;
BEGIN
 IF p_project_id IS NOT NULL THEN PERFORM internal.assert_object_access('project',p_project_id,'edit'); END IF;
  IF NOT internal.can_edit_project(p_project_id) THEN
    RAISE EXCEPTION 'project editor required' USING ERRCODE = '42501';
  END IF;
  IF p_folder_id IS NOT NULL AND NOT EXISTS (
    SELECT 1 FROM api.folders f
    WHERE f.id = p_folder_id AND f.project_id = p_project_id
  ) THEN
    RAISE EXCEPTION 'folder not in this project' USING ERRCODE = '42501';
  END IF;
  UPDATE api.records r
     SET folder_id = p_folder_id,
         metadata_version = metadata_version + 1,
         updated_at = now(),
         updated_by_user_id = api.current_user_id()
   WHERE r.id = ANY (p_record_ids)
     AND r.project_id = p_project_id
     AND r.deleted_at IS NULL
     AND r.locked_at IS NULL;
  GET DIAGNOSTICS v_count = ROW_COUNT;
  RETURN v_count;
END;
$$;
--> statement-breakpoint
ALTER FUNCTION api.move_records_to_folder(p_project_id uuid, p_record_ids uuid[], p_folder_id uuid) OWNER TO migrator;
--> statement-breakpoint
CREATE FUNCTION api.move_sample_to_position(p_record_id uuid, p_to_position_id uuid, p_expected_metadata_version integer, p_notes text DEFAULT NULL::text) RETURNS api.records
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
  v_row "api"."records";
  v_target "api"."storage_positions";
  v_prev "api"."storage_positions";
  v_to_path text;
  v_from_path text;
  v_props jsonb;
  v_op text;
BEGIN
 IF p_record_id IS NOT NULL THEN PERFORM internal.assert_object_access('record',p_record_id,'edit'); END IF;
  IF NOT api.is_workspace_writer("api"."current_workspace_id"()) THEN
    RAISE EXCEPTION 'no active workspace membership' USING ERRCODE = '42501';
  END IF;

  SELECT * INTO v_target FROM "api"."storage_positions"
    WHERE id = p_to_position_id FOR UPDATE;
  IF v_target IS NULL THEN
    RAISE EXCEPTION 'position not found in active workspace' USING ERRCODE = 'SB011';
  END IF;

  SELECT * INTO v_row FROM "api"."records" WHERE id = p_record_id FOR UPDATE;
  IF v_row IS NULL THEN
    RAISE EXCEPTION 'record not found in active workspace' USING ERRCODE = '42501';
  END IF;
  IF v_row.kind <> 'sample' THEN
    RAISE EXCEPTION 'record % is not a sample', p_record_id USING ERRCODE = 'SB009';
  END IF;
  IF v_row.archived_at IS NOT NULL THEN
    RAISE EXCEPTION 'cannot move an archived sample' USING ERRCODE = 'SB004';
  END IF;
  IF v_row.workspace_id <> "api"."current_workspace_id"() THEN
    RAISE EXCEPTION 'record not found in active workspace' USING ERRCODE = '42501';
  END IF;
  IF v_row.metadata_version <> p_expected_metadata_version THEN
    RAISE EXCEPTION 'metadata version mismatch: expected %, got %',
      p_expected_metadata_version, v_row.metadata_version USING ERRCODE = 'SB001';
  END IF;

  -- Target must belong to the same workspace as the sample.
  IF v_target.workspace_id <> v_row.workspace_id THEN
    RAISE EXCEPTION 'position is in a different workspace' USING ERRCODE = 'SB011';
  END IF;
  IF v_target.status IN ('quarantined','missing') THEN
    RAISE EXCEPTION 'position is not available (status: %)', v_target.status
      USING ERRCODE = 'SB013';
  END IF;
  IF v_target.occupied_record_id IS NOT NULL THEN
    RAISE EXCEPTION 'position is already occupied' USING ERRCODE = 'SB010';
  END IF;
  IF v_target.occupied_record_id = p_record_id THEN
    RAISE EXCEPTION 'sample is already at that position' USING ERRCODE = 'SB012';
  END IF;

  -- Find and clear the sample's previous position (if any). The partial
  -- unique index on occupied_record_id guarantees at most one.
  SELECT * INTO v_prev FROM "api"."storage_positions"
    WHERE occupied_record_id = p_record_id FOR UPDATE;
  IF v_prev IS NOT NULL THEN
    v_from_path := "api"."storage_path"(v_prev.id);
    UPDATE "api"."storage_positions"
      SET occupied_record_id = NULL, status = 'available', updated_at = now()
      WHERE id = v_prev.id;
  END IF;

  v_to_path := "api"."storage_path"(v_target.id);
  v_op := CASE WHEN v_prev IS NULL THEN 'place' ELSE 'move' END;

  -- Occupy the target.
  UPDATE "api"."storage_positions"
    SET occupied_record_id = p_record_id, status = 'occupied', updated_at = now()
    WHERE id = v_target.id;

  -- Update the sample's human-readable storage location.
  v_props := v_row.properties || jsonb_build_object('storageLocation', v_to_path);
  UPDATE "api"."records"
    SET properties = v_props,
        metadata_version = v_row.metadata_version + 1,
        updated_by_user_id = "api"."current_user_id"()
    WHERE id = p_record_id
    RETURNING * INTO v_row;

  -- Append the storage-map movement (structured position ids + paths).
  INSERT INTO "api"."storage_movements"
    (workspace_id, record_id, operation, from_position_id, to_position_id,
     from_path, to_path, actor_user_id, notes)
  VALUES
    (v_row.workspace_id, v_row.id, v_op, v_prev.id, v_target.id,
     v_from_path, v_to_path, "api"."current_user_id"(), p_notes);

  -- Append to the existing chain of custody so the sample inspector and the
  -- storage inspector tell the same story.
  INSERT INTO "api"."sample_events"
    (workspace_id, record_id, operation, from_location, to_location,
     actor_user_id, notes)
  VALUES
    (v_row.workspace_id, v_row.id, 'transfer',
     COALESCE(v_from_path, 'unfiled'),
     v_to_path, "api"."current_user_id"(), p_notes);

  RETURN v_row;
END;
$$;
--> statement-breakpoint
ALTER FUNCTION api.move_sample_to_position(p_record_id uuid, p_to_position_id uuid, p_expected_metadata_version integer, p_notes text) OWNER TO migrator;
--> statement-breakpoint
CREATE FUNCTION api.move_study_task_due(p_task_id uuid, p_expected_metadata_version integer, p_due_at timestamp with time zone, p_reason text, p_notify_client boolean DEFAULT false) RETURNS api.study_tasks
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
  v_ws uuid := api.current_workspace_id();
  v_row api.study_tasks;
BEGIN
 IF p_task_id IS NOT NULL THEN PERFORM internal.assert_object_access('task',p_task_id,'edit'); END IF;
  SELECT * INTO v_row FROM api.study_tasks
    WHERE id = p_task_id AND workspace_id = v_ws FOR UPDATE;
  IF v_row IS NULL THEN
    RAISE EXCEPTION 'task not found in active workspace' USING ERRCODE = 'SB026';
  END IF;
  IF NOT api.is_workspace_writer(v_ws) THEN
    RAISE EXCEPTION 'study task denied' USING ERRCODE = '42501';
  END IF;
  IF p_expected_metadata_version IS NOT NULL
     AND v_row.metadata_version <> p_expected_metadata_version THEN
    RAISE EXCEPTION 'metadata version mismatch' USING ERRCODE = 'SB001';
  END IF;
  IF p_due_at IS NULL THEN
    RAISE EXCEPTION 'a due date is required' USING ERRCODE = '22023';
  END IF;
  IF length(btrim(coalesce(p_reason, ''))) NOT BETWEEN 1 AND 500 THEN
    RAISE EXCEPTION 'a reason is required' USING ERRCODE = '22023';
  END IF;
  INSERT INTO api.study_task_due_changes(
    workspace_id, task_id, from_due_at, to_due_at, reason,
    client_notified, changed_by_user_id
  ) VALUES (
    v_ws, p_task_id, v_row.due_at, p_due_at, btrim(p_reason),
    coalesce(p_notify_client, false), api.current_user_id()
  );
  UPDATE api.study_tasks
    SET due_at = p_due_at,
        metadata_version = metadata_version + 1,
        updated_at = now(),
        updated_by_user_id = api.current_user_id()
    WHERE id = p_task_id
  RETURNING * INTO v_row;
  RETURN v_row;
END $$;
--> statement-breakpoint
ALTER FUNCTION api.move_study_task_due(p_task_id uuid, p_expected_metadata_version integer, p_due_at timestamp with time zone, p_reason text, p_notify_client boolean) OWNER TO migrator;
