CREATE FUNCTION api.my_project_permissions() RETURNS TABLE(project_id uuid, can_view boolean, can_edit boolean, can_review boolean, client_portal boolean, can_manage boolean, access_level text)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
