CREATE FUNCTION api.next_record_identifier(p_workspace_id uuid, p_kind text) RETURNS text
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $_$
DECLARE
  v_prefix text;
  v_width integer;
  v_number bigint;
BEGIN
  IF api.current_workspace_id() IS DISTINCT FROM p_workspace_id THEN
    RAISE EXCEPTION 'not a member of target workspace' USING ERRCODE = 'SB033';
  END IF;
  IF p_kind IS NULL OR p_kind !~ '^[a-z][a-z0-9_]{0,59}$' THEN
    RAISE EXCEPTION 'unknown record kind' USING ERRCODE = '22023';
  END IF;

  SELECT nullif(btrim(id_prefixes ->> p_kind), '')
    INTO v_prefix
    FROM api.workspace_settings WHERE workspace_id = p_workspace_id;
  v_prefix := coalesce(v_prefix, CASE p_kind
    WHEN 'experiment' THEN 'EXP'
    WHEN 'sample' THEN 'SMP'
    WHEN 'dataset' THEN 'DS'
    WHEN 'protocol_template' THEN 'PRT'
    WHEN 'material' THEN 'MAT'
    WHEN 'material' THEN 'MAT'
    WHEN 'analysis' THEN 'AN'
    WHEN 'file' THEN 'FILE'
    WHEN 'notebook_template' THEN 'NBK'
    WHEN 'report' THEN 'RPT'
    WHEN 'study' THEN 'STD'
    ELSE upper(left(p_kind, 3))
  END);
  v_width := CASE p_kind WHEN 'protocol_template' THEN 3 ELSE 4 END;

  INSERT INTO internal.id_sequences (workspace_id, kind, last_number)
  VALUES (p_workspace_id, p_kind, 1)
  ON CONFLICT (workspace_id, kind)
  DO UPDATE SET last_number = internal.id_sequences.last_number + 1
  RETURNING last_number INTO v_number;

  RETURN v_prefix || '-' || lpad(v_number::text, v_width, '0');
END;
$_$;
--> statement-breakpoint
ALTER FUNCTION api.next_record_identifier(p_workspace_id uuid, p_kind text) OWNER TO migrator;
--> statement-breakpoint
CREATE FUNCTION api.next_record_model_identifier(p_model_id uuid) RETURNS text
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
  v_model "api"."record_models";
  v_number bigint;
BEGIN
  SELECT * INTO v_model FROM "api"."record_models" WHERE id = p_model_id;
  IF v_model.id IS NULL THEN
    RAISE EXCEPTION 'model not found' USING ERRCODE = '42501';
  END IF;
  IF "api"."current_workspace_id"() IS DISTINCT FROM v_model.workspace_id THEN
    RAISE EXCEPTION 'not a member of target workspace' USING ERRCODE = 'SB033';
  END IF;

  INSERT INTO "internal"."id_sequences" (workspace_id, kind, last_number)
  VALUES (v_model.workspace_id, 'model:' || lower(v_model.identifier_prefix), 1)
  ON CONFLICT (workspace_id, kind)
  DO UPDATE SET last_number = "internal"."id_sequences".last_number + 1
  RETURNING last_number INTO v_number;

  RETURN v_model.identifier_prefix || '-' || lpad(v_number::text, 4, '0');
END;
$$;
--> statement-breakpoint
ALTER FUNCTION api.next_record_model_identifier(p_model_id uuid) OWNER TO migrator;
