    scheduled_at timestamp with time zone,
    planned_key text,
    CONSTRAINT chk_dataset_rows_planned_key CHECK (((planned_key IS NULL) OR ((length(planned_key) >= 1) AND (length(planned_key) <= 200)))),
    CONSTRAINT chk_dataset_rows_revision CHECK ((revision > 0)),
    CONSTRAINT chk_dataset_rows_status CHECK ((status = ANY (ARRAY['planned'::text, 'recorded'::text])))
);
