CREATE FUNCTION api.preview_dataset_import_rows(p_dataset_id uuid, p_rows jsonb, p_control_field_id uuid DEFAULT NULL::uuid, p_control_pattern text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $_$
#variable_conflict use_variable
DECLARE
  dataset api.datasets;
  item jsonb;
  row_index integer := 0;
  keys text[] := '{}';
  planned_map jsonb := '{}'::jsonb;
  out_rows jsonb := '[]'::jsonb;
  field api.dataset_schema_version_fields;
  effective jsonb;
  v_num numeric;
  lo numeric;
  hi numeric;
  rule jsonb;
  violated boolean;
  v_reason text;
  has_value boolean;
  unit_text text;
  v_planned_id uuid;
  v_outcome text;
  control_value text;
  hc_field api.dataset_schema_version_fields;
  hc jsonb;
  group_field_id uuid;
  max_cv numeric;
  min_reps integer;
  group_rec record;
  idx integer;
  flag jsonb;
BEGIN
 IF p_dataset_id IS NOT NULL THEN PERFORM internal.assert_object_access('dataset',p_dataset_id,'view'); END IF;
  SELECT * INTO dataset FROM api.datasets d
   WHERE d.id = p_dataset_id AND d.workspace_id = api.current_workspace_id()
     AND api.is_workspace_member(d.workspace_id);
  IF dataset.id IS NULL THEN
    RAISE EXCEPTION 'dataset denied' USING ERRCODE = '42501';
  END IF;
  IF jsonb_typeof(p_rows) IS DISTINCT FROM 'array' THEN
    RAISE EXCEPTION 'rows must be an array' USING ERRCODE = '22023';
  END IF;

  FOR item IN SELECT value FROM jsonb_array_elements(p_rows) LOOP
    IF jsonb_typeof(item -> 'plannedKey') = 'string' THEN
      keys := array_append(keys, item ->> 'plannedKey');
    END IF;
  END LOOP;
  IF array_length(keys, 1) IS NOT NULL THEN
    SELECT coalesce(jsonb_object_agg(r.planned_key, r.id), '{}'::jsonb) INTO planned_map
      FROM api.dataset_rows r
     WHERE r.dataset_id = dataset.id AND r.status = 'planned'
       AND r.planned_key = ANY(keys);
  END IF;

  FOR item IN SELECT value FROM jsonb_array_elements(p_rows) LOOP
    row_index := row_index + 1;
    v_planned_id := NULL;
    v_outcome := 'new';
    control_value := NULL;
    IF jsonb_typeof(item -> 'plannedKey') = 'string' THEN
      v_planned_id := nullif(planned_map ->> (item ->> 'plannedKey'), '')::uuid;
    END IF;
    IF v_planned_id IS NOT NULL THEN v_outcome := 'planned'; END IF;

    IF p_control_field_id IS NOT NULL AND p_control_pattern IS NOT NULL
       AND item -> 'values' ? p_control_field_id::text THEN
      control_value := item -> 'values' ->> p_control_field_id::text;
      IF control_value IS NOT NULL AND control_value ~* p_control_pattern THEN
        v_outcome := 'skipped';
      END IF;
    END IF;

    out_rows := out_rows || jsonb_build_array(jsonb_build_object(
      'index', row_index,
      'outcome', v_outcome,
      'plannedKey', item ->> 'plannedKey',
      'plannedRowId', v_planned_id,
      'flags', '[]'::jsonb));

    FOR field IN
      SELECT * FROM api.dataset_schema_version_fields f
       WHERE f.schema_version_id = dataset.schema_version_id AND f.lifecycle = 'active'
       ORDER BY f.display_order
    LOOP
      effective := item -> 'values' -> field.field_id::text;

      rule := field.validation #> '{extensions,systemFlags,out_of_range}';
      violated := false;
      v_reason := NULL;
      v_num := NULL;
      IF rule IS NOT NULL AND jsonb_typeof(rule) = 'object'
         AND field.logical_type IN ('integer', 'decimal')
         AND effective IS NOT NULL AND jsonb_typeof(effective) = 'number' THEN
        v_num := (effective #>> '{}')::numeric;
        IF rule ? 'min' THEN
          lo := (rule ->> 'min')::numeric;
          IF v_num < lo THEN
            violated := true;
            v_reason := format('Value %s is below the minimum %s', v_num, lo);
          END IF;
        END IF;
        IF NOT violated AND rule ? 'max' THEN
          hi := (rule ->> 'max')::numeric;
          IF v_num > hi THEN
            violated := true;
            v_reason := format('Value %s is above the maximum %s', v_num, hi);
          END IF;
        END IF;
      END IF;
      IF violated THEN
        flag := jsonb_build_object('fieldId', field.field_id, 'kind', 'out_of_range', 'reason', v_reason);
        out_rows := jsonb_set(out_rows, ARRAY[(row_index - 1)::text, 'flags'],
          (out_rows -> (row_index - 1) -> 'flags') || jsonb_build_array(flag));
      END IF;

      rule := field.validation #> '{extensions,systemFlags,missing_unit}';
      violated := false;
      v_reason := NULL;
      has_value := effective IS NOT NULL AND effective <> 'null'::jsonb;
      unit_text := nullif(btrim(coalesce(field.quantity ->> 'storageUnit', field.quantity ->> 'symbol')), '');
      IF rule IS NOT NULL AND jsonb_typeof(rule) = 'object'
         AND coalesce((rule ->> 'requiresUnit')::boolean, false) IS TRUE
         AND field.logical_type IN ('integer', 'decimal')
         AND has_value AND unit_text IS NULL THEN
        violated := true;
        v_reason := format('No unit is recorded for %s', field.label);
      END IF;
      IF violated THEN
        flag := jsonb_build_object('fieldId', field.field_id, 'kind', 'missing_unit', 'reason', v_reason);
        out_rows := jsonb_set(out_rows, ARRAY[(row_index - 1)::text, 'flags'],
          (out_rows -> (row_index - 1) -> 'flags') || jsonb_build_array(flag));
      END IF;
    END LOOP;
  END LOOP;

  -- high_cv across the batch's replicate groups.
  FOR hc_field IN
    SELECT * FROM api.dataset_schema_version_fields f
     WHERE f.schema_version_id = dataset.schema_version_id AND f.lifecycle = 'active'
       AND f.logical_type IN ('integer', 'decimal')
       AND jsonb_typeof(f.validation #> '{extensions,systemFlags,high_cv}') = 'object'
     ORDER BY f.display_order
  LOOP
    hc := hc_field.validation #> '{extensions,systemFlags,high_cv}';
    IF hc ->> 'groupByFieldId' IS NULL OR hc ->> 'maxCvPercent' IS NULL
       OR hc ->> 'groupByFieldId' !~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
       OR hc ->> 'maxCvPercent' !~ '^-?[0-9]+(\.[0-9]+)?$' THEN
      CONTINUE;
    END IF;
    group_field_id := (hc ->> 'groupByFieldId')::uuid;
    max_cv := (hc ->> 'maxCvPercent')::numeric;
    min_reps := greatest(coalesce((hc ->> 'minReplicates')::integer, 3), 2);
    FOR group_rec IN
      SELECT g.group_key, count(*) AS n, avg(g.val) AS mean, stddev_samp(g.val) AS sd,
             array_agg(g.idx) AS idxs
        FROM (
          SELECT (e.ord - 1) AS idx,
                 e.item -> 'values' ->> group_field_id::text AS group_key,
                 nullif(e.item -> 'values' ->> hc_field.field_id::text, '')::numeric AS val
            FROM jsonb_array_elements(p_rows) WITH ORDINALITY AS e(item, ord)
        ) g
       WHERE g.group_key IS NOT NULL AND g.group_key <> '' AND g.val IS NOT NULL
       GROUP BY g.group_key
      HAVING count(*) >= min_reps
    LOOP
      IF group_rec.mean IS NOT NULL AND group_rec.mean <> 0 AND group_rec.sd IS NOT NULL
         AND abs(group_rec.sd / group_rec.mean) * 100 > max_cv THEN
        FOR idx IN SELECT unnest(group_rec.idxs) LOOP
          flag := jsonb_build_object(
            'fieldId', hc_field.field_id, 'kind', 'high_cv',
            'reason', format('Replicate CV %s%% exceeds %s%%', round(abs(group_rec.sd / group_rec.mean) * 100, 2), max_cv));
          out_rows := jsonb_set(out_rows, ARRAY[idx::text, 'flags'],
            (out_rows -> idx -> 'flags') || jsonb_build_array(flag));
        END LOOP;
      END IF;
    END LOOP;
  END LOOP;

  -- Any row with a flag is classified flagged (skipped wins over flagged).
  FOR idx IN SELECT generate_series(0, jsonb_array_length(out_rows) - 1) LOOP
    IF (out_rows -> idx ->> 'outcome') <> 'skipped'
       AND jsonb_array_length(out_rows -> idx -> 'flags') > 0 THEN
      out_rows := jsonb_set(out_rows, ARRAY[idx::text, 'outcome'], '"flagged"'::jsonb);
    END IF;
  END LOOP;

  RETURN jsonb_build_object(
    'ok', true,
    'rows', out_rows,
    'summary', jsonb_build_object(
      'total', jsonb_array_length(out_rows),
      'added', (SELECT count(*) FROM jsonb_array_elements(out_rows) x
                 WHERE x ->> 'outcome' <> 'skipped'),
      'planned', (SELECT count(*) FROM jsonb_array_elements(out_rows) x WHERE x ->> 'outcome' = 'planned'),
      'new', (SELECT count(*) FROM jsonb_array_elements(out_rows) x WHERE x ->> 'outcome' = 'new'),
      'flagged', (SELECT count(*) FROM jsonb_array_elements(out_rows) x WHERE x ->> 'outcome' = 'flagged'),
      'skipped', (SELECT count(*) FROM jsonb_array_elements(out_rows) x WHERE x ->> 'outcome' = 'skipped')));
END $_$;
--> statement-breakpoint
ALTER FUNCTION api.preview_dataset_import_rows(p_dataset_id uuid, p_rows jsonb, p_control_field_id uuid, p_control_pattern text) OWNER TO migrator;
--> statement-breakpoint
CREATE FUNCTION api.preview_dataset_model_upgrade(p_dataset_id uuid, p_target_version_id uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
  v_dataset api.datasets;
  v_current api.dataset_schema_versions;
  v_target api.dataset_schema_versions;
  v_added jsonb;
  v_removed jsonb;
  v_retyped jsonb;
  v_required jsonb;
  v_semantic jsonb;
  v_reason text;
  v_rows bigint;
BEGIN
  SELECT * INTO v_dataset FROM api.datasets WHERE id = p_dataset_id;
  IF v_dataset.id IS NULL OR NOT api.is_workspace_member(v_dataset.workspace_id)
    OR NOT internal.can_access_object('dataset', v_dataset.id, 'view') THEN
    RAISE EXCEPTION 'dataset not found' USING ERRCODE = '42501';
  END IF;
  SELECT * INTO v_current FROM api.dataset_schema_versions WHERE id = v_dataset.schema_version_id;
  SELECT v.* INTO v_target FROM api.dataset_schema_versions v
    JOIN api.dataset_schema_definitions d ON d.id = v.schema_id
    WHERE v.id = p_target_version_id AND d.workspace_id = v_dataset.workspace_id;
  IF v_target.id IS NULL THEN
    RAISE EXCEPTION 'model version not found' USING ERRCODE = '22023';
  END IF;

  SELECT coalesce(jsonb_agg(jsonb_build_object('key', t.key, 'label', t.label, 'type', t.logical_type)
    ORDER BY t.display_order), '[]'::jsonb) INTO v_added
    FROM api.dataset_schema_version_fields t
    WHERE t.schema_version_id = v_target.id AND t.lifecycle = 'active'
      AND NOT EXISTS (SELECT 1 FROM api.dataset_schema_version_fields c
        WHERE c.schema_version_id = v_current.id AND c.field_id = t.field_id AND c.lifecycle = 'active');
  SELECT coalesce(jsonb_agg(jsonb_build_object('key', c.key, 'label', c.label)
    ORDER BY c.display_order), '[]'::jsonb) INTO v_removed
    FROM api.dataset_schema_version_fields c
    WHERE c.schema_version_id = v_current.id AND c.lifecycle = 'active'
      AND NOT EXISTS (SELECT 1 FROM api.dataset_schema_version_fields t
        WHERE t.schema_version_id = v_target.id AND t.field_id = c.field_id AND t.lifecycle = 'active');
  SELECT coalesce(jsonb_agg(jsonb_build_object('key', c.key, 'label', c.label,
    'from', c.logical_type, 'to', t.logical_type) ORDER BY c.display_order), '[]'::jsonb) INTO v_retyped
    FROM api.dataset_schema_version_fields c
    JOIN api.dataset_schema_version_fields t ON t.schema_version_id = v_target.id AND t.field_id = c.field_id
    WHERE c.schema_version_id = v_current.id AND t.logical_type <> c.logical_type;
  SELECT coalesce(jsonb_agg(jsonb_build_object('key', t.key, 'label', t.label)
    ORDER BY t.display_order), '[]'::jsonb) INTO v_required
    FROM api.dataset_schema_version_fields t
    WHERE t.schema_version_id = v_target.id AND t.lifecycle = 'active' AND NOT t.nullable
      AND nullif(t.default_value, 'null'::jsonb) IS NULL
      AND NOT EXISTS (SELECT 1 FROM api.dataset_schema_version_fields c
        WHERE c.schema_version_id = v_current.id AND c.field_id = t.field_id AND c.lifecycle = 'active');

  SELECT coalesce(jsonb_agg(jsonb_build_object('key', t.key, 'label', t.label)
    ORDER BY t.display_order), '[]'::jsonb) INTO v_semantic
    FROM api.dataset_schema_version_fields t
    LEFT JOIN api.dataset_schema_version_fields c
      ON c.schema_version_id = v_current.id AND c.field_id = t.field_id
    WHERE t.schema_version_id = v_target.id AND t.lifecycle = 'active' AND (
      -- This operation does not backfill defaults. A default-bearing addition
      -- needs an explicit migration rather than pretending old rows received it.
      (c.field_id IS NULL AND nullif(t.default_value, 'null'::jsonb) IS NOT NULL)
      OR (c.field_id IS NOT NULL AND (
        c.quantity IS DISTINCT FROM t.quantity
        OR c.validation IS DISTINCT FROM t.validation
        OR c.category IS DISTINCT FROM t.category
        OR c.relationship IS DISTINCT FROM t.relationship
        OR c.cardinality IS DISTINCT FROM t.cardinality
        OR c.lifecycle IS DISTINCT FROM t.lifecycle
        OR c.nullable IS DISTINCT FROM t.nullable
        OR nullif(c.default_value, 'null'::jsonb) IS DISTINCT FROM nullif(t.default_value, 'null'::jsonb)
      )));
  SELECT count(*) INTO v_rows FROM api.dataset_rows WHERE dataset_id = v_dataset.id;
  v_reason := CASE
    WHEN v_target.id = v_current.id THEN 'This dataset is already on that version.'
    WHEN v_target.schema_id <> v_current.schema_id THEN 'That version belongs to a different model. A dataset can only follow its own model.'
    WHEN v_target.lifecycle <> 'active' THEN 'That version is not published. A steward publishes it before datasets can move to it.'
    WHEN v_target.version < v_current.version THEN 'That version is older than the one the dataset is on.'
    WHEN jsonb_array_length(v_removed) > 0 THEN 'The newer version drops fields this dataset holds values for. A steward can publish a version that keeps them.'
    WHEN jsonb_array_length(v_retyped) > 0 THEN 'The newer version changes the type of fields this dataset already holds. Migrate those values first, or ask a steward for a compatible version.'
    WHEN jsonb_array_length(v_required) > 0 AND v_rows > 0 THEN 'The newer version adds required fields. Existing rows need an explicit validated backfill before moving, even when a default is defined.'
    WHEN jsonb_array_length(v_semantic) > 0 THEN 'The newer version changes units, constraints, categories, reference targets, cardinality, nullability or defaults. This move does not transform values. An explicit validated migration is required.'
    ELSE NULL
  END;
  RETURN jsonb_build_object(
    'ok', v_reason IS NULL, 'blocked', v_reason IS NOT NULL, 'reason', v_reason,
    'datasetId', v_dataset.id, 'fromVersionId', v_current.id, 'fromVersion', v_current.version,
    'toVersionId', v_target.id, 'toVersion', v_target.version,
    'added', v_added, 'removed', v_removed, 'retyped', v_retyped,
    'requiredWithoutDefault', v_required, 'semanticChanges', v_semantic,
    'rowCount', v_rows, 'datasetRevision', v_dataset.revision);
END $$;
--> statement-breakpoint
ALTER FUNCTION api.preview_dataset_model_upgrade(p_dataset_id uuid, p_target_version_id uuid) OWNER TO migrator;
--> statement-breakpoint
CREATE FUNCTION api.preview_dataset_schema_evolution(p_schema_version_id uuid, p_fields jsonb) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
  version api.dataset_schema_versions;
  workspace uuid;
  classified jsonb;
  impact jsonb;
BEGIN
  SELECT * INTO version FROM api.dataset_schema_versions WHERE id = p_schema_version_id;
  SELECT s.workspace_id INTO workspace FROM api.dataset_schema_definitions s WHERE s.id = version.schema_id;
  IF version.id IS NULL THEN RAISE EXCEPTION 'Dataset Schema Version not found' USING ERRCODE = '42501'; END IF;
  PERFORM api.require_capability(workspace, 'schema.edit');
  classified := internal.classify_dataset_schema_fields(version.id, p_fields);
  impact := api.discover_object_dependencies('dataset_schema_version', version.id);
  RETURN classified || jsonb_build_object(
    'baseSchemaVersionId', version.id,
    'impact', impact->'dependencies',
    'advancesLiveDatasets', false,
    'note', 'Live Datasets remain bound to the previous Schema Version until explicitly rebound.'
  );
END;
$$;
