CREATE FUNCTION api.preview_hard_delete(p_kind text, p_object_id uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
  discovered jsonb;
  blocking jsonb;
BEGIN
 IF p_kind IN ('record','notebook_record','dataset','sheet_instance') THEN PERFORM internal.assert_object_access(CASE p_kind WHEN 'sheet_instance' THEN 'instance' WHEN 'notebook_record' THEN 'record' ELSE p_kind END,p_object_id,'view'); END IF;
  discovered := api.discover_object_dependencies(p_kind, p_object_id);
  SELECT coalesce(jsonb_agg(value), '[]'::jsonb) INTO blocking
    FROM jsonb_array_elements(discovered->'dependencies') value
   WHERE value->>'effect' = 'blocks_deletion';
  RETURN jsonb_build_object(
    'kind', p_kind,
    'id', p_object_id,
    'allowed', jsonb_array_length(blocking) = 0,
    'blocking', blocking,
    'dependencies', discovered->'dependencies'
  );
END;
$$;
