CREATE FUNCTION api.preview_model_field_evolution(p_definition_id uuid, p_action text, p_patch jsonb DEFAULT '{}'::jsonb) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
  field api.record_field_definitions;
  classification text := 'compatible';
  reason text := 'metadata';
  impact jsonb;
  usage bigint := 0;
  guidance text[] := '{}';
BEGIN
  SELECT * INTO field FROM api.record_field_definitions WHERE id = p_definition_id;
  IF field.id IS NULL THEN RAISE EXCEPTION 'Model field not found' USING ERRCODE = '42501'; END IF;
  PERFORM api.require_capability(field.workspace_id, 'schema.edit');
  usage := coalesce(api.model_field_usage(field.id), 0);
  IF p_action = 'retire' THEN
    classification := 'migration-requiring';
    reason := 'retire_field';
    IF usage > 0 THEN
      guidance := array[
        usage::text || ' record(s) of model "' || field.kind
          || '" carry a value for "' || field.label
          || '". Retiring locks the field for new and edited records; stored values stay readable in history and evidence and are never deleted.',
        'Review downstream consumers of model "' || field.kind
          || '" — Sheet record bindings, template record parameters and relationship rules — before confirming. Local Sheet working state is never auto-migrated.'
      ];
    ELSE
      guidance := array[
        'No records carry a value for "' || field.label
          || '". Retiring locks the field for new and edited records; there is nothing to migrate.'
      ];
    END IF;
  ELSIF p_action = 'update' THEN
    IF p_patch ?| ARRAY['logicalType','logical_type','key','field_name'] THEN
      classification := 'breaking';
      reason := 'identity_change_blocked';
      guidance := array[
        'The stable key and logical type are immutable once set. Create a new field and migrate consumers explicitly instead of reinterpreting this one.'
      ];
    ELSIF field.lifecycle IN ('active','retired') AND p_patch ?| ARRAY['nullable','defaultValue','validation'] THEN
      classification := 'breaking';
      reason := 'active_contract_immutable';
      guidance := array[
        'Nullable, default and validation rules are immutable while the field is ' || field.lifecycle
          || '. Retire and replace the field rather than silently reinterpreting stored values.'
      ];
    ELSE
      classification := 'compatible';
      reason := 'metadata';
      guidance := array[
        'Metadata-only change (label, description, display order). Stored values, frozen evidence and local working state are unaffected; no downstream migration is required.'
      ];
    END IF;
  ELSE
    RAISE EXCEPTION 'unsupported Model field action' USING ERRCODE = '22023';
  END IF;
  impact := api.discover_object_dependencies('model_field', field.id);
  RETURN jsonb_build_object(
    'classification', classification,
    'reason', reason,
    'blocked', classification = 'breaking',
    'impact', impact->'dependencies',
    'guidance', to_jsonb(guidance)
  );
END;
$$;
--> statement-breakpoint
ALTER FUNCTION api.preview_model_field_evolution(p_definition_id uuid, p_action text, p_patch jsonb) OWNER TO migrator;
--> statement-breakpoint
CREATE FUNCTION api.preview_notebook_template_upgrade(p_record_id uuid, p_target_version_id uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
  workspace uuid := api.current_workspace_id();
  rec api.records;
  source api.notebook_template_versions;
  target api.notebook_template_versions;
  source_tmpl api.notebook_templates;
  target_tmpl api.notebook_templates;
  placement jsonb;
  target_placement jsonb;
  block api.blocks;
  conflicts jsonb := '[]'::jsonb;
  automatic jsonb := '[]'::jsonb;
  instance_preview jsonb;
BEGIN
 IF p_record_id IS NOT NULL THEN PERFORM internal.assert_object_access('record',p_record_id,'view'); END IF;
  IF workspace IS NULL OR NOT api.is_workspace_member(workspace) THEN
    RAISE EXCEPTION 'workspace member required' USING ERRCODE = '42501';
  END IF;
  SELECT * INTO rec FROM api.records WHERE id = p_record_id AND workspace_id = workspace;
  IF rec.id IS NULL OR rec.source_notebook_template_version_id IS NULL THEN
    RAISE EXCEPTION 'Notebook is not based on a Template Version' USING ERRCODE = 'SB090';
  END IF;
  SELECT * INTO source FROM api.notebook_template_versions WHERE id = rec.source_notebook_template_version_id;
  SELECT * INTO target FROM api.notebook_template_versions WHERE id = p_target_version_id;
  SELECT * INTO source_tmpl FROM api.notebook_templates WHERE id = source.template_id;
  SELECT * INTO target_tmpl FROM api.notebook_templates WHERE id = target.template_id;
  IF target.id IS NULL OR target.lifecycle <> 'published'
     OR source_tmpl.id IS DISTINCT FROM target_tmpl.id
     OR target.version <= source.version
     OR source_tmpl.workspace_id IS DISTINCT FROM workspace THEN
    RAISE EXCEPTION 'target must be a newer published Version of the same Template' USING ERRCODE = 'SB090';
  END IF;

  FOR placement IN SELECT value FROM jsonb_array_elements(coalesce(source.configuration->'placements','[]'::jsonb)) LOOP
    SELECT value INTO target_placement
      FROM jsonb_array_elements(coalesce(target.configuration->'placements','[]'::jsonb)) value
      WHERE value->>'id' = placement->>'id';
    IF target_placement IS NULL THEN
      automatic := automatic || jsonb_build_array(jsonb_build_object(
        'kind','placement-removed','placementId',placement->>'id'
      ));
    ELSIF placement->>'kind' = 'sheet' AND target_placement->>'kind' = 'sheet'
       AND placement->>'definitionVersionId' IS DISTINCT FROM target_placement->>'definitionVersionId' THEN
      block := internal.notebook_sheet_block_for_template_placement(
        rec.id, source.configuration, placement->>'id'
      );
      IF block.id IS NULL THEN
        conflicts := conflicts || jsonb_build_array(jsonb_build_object(
          'id','placement:'||(placement->>'id'),
          'kind','sheet-placement-unresolved',
          'placementId',placement->>'id',
          'allowedOutcomes', jsonb_build_array('keep')
        ));
      ELSE
        instance_preview := api.preview_sheet_instance_definition_upgrade(
          (block.payload->>'instanceId')::uuid,
          (SELECT revision FROM api.sheet_instances WHERE id = (block.payload->>'instanceId')::uuid),
          (target_placement->>'definitionVersionId')::uuid
        );
        IF jsonb_array_length(coalesce(instance_preview->'conflicts','[]'::jsonb)) = 0 THEN
          automatic := automatic || jsonb_build_array(jsonb_build_object(
            'kind','sheet-definition-compatible',
            'placementId',placement->>'id',
            'blockId',block.id,
            'instanceId',block.payload->>'instanceId',
            'targetDefinitionVersionId',target_placement->>'definitionVersionId'
          ));
        ELSE
          conflicts := conflicts || jsonb_build_array(jsonb_build_object(
            'id','placement:'||(placement->>'id'),
            'kind','sheet-definition-conflict',
            'placementId',placement->>'id',
            'blockId',block.id,
            'instanceId',block.payload->>'instanceId',
            'allowedOutcomes', jsonb_build_array('keep','retarget'),
            'instancePreview', instance_preview
          ));
        END IF;
      END IF;
    END IF;
    target_placement := NULL;
  END LOOP;

  FOR target_placement IN SELECT value FROM jsonb_array_elements(coalesce(target.configuration->'placements','[]'::jsonb)) LOOP
    IF NOT EXISTS (
      SELECT 1 FROM jsonb_array_elements(coalesce(source.configuration->'placements','[]'::jsonb)) value
      WHERE value->>'id' = target_placement->>'id'
    ) THEN
      automatic := automatic || jsonb_build_array(jsonb_build_object(
        'kind','placement-added','placementId',target_placement->>'id'
      ));
    END IF;
  END LOOP;

  RETURN jsonb_build_object(
    'recordId', rec.id,
    'sourceVersionId', source.id,
    'targetVersionId', target.id,
    'automatic', automatic,
    'conflicts', conflicts
  );
END
$$;
--> statement-breakpoint
ALTER FUNCTION api.preview_notebook_template_upgrade(p_record_id uuid, p_target_version_id uuid) OWNER TO migrator;
--> statement-breakpoint
CREATE FUNCTION api.preview_sheet_definition_extraction(p_instance_id uuid, p_expected_instance_revision bigint, p_selection jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE instance api.sheet_instances;
BEGIN
 IF p_instance_id IS NOT NULL THEN PERFORM internal.assert_object_access('instance',p_instance_id,'view'); END IF;
  SELECT * INTO instance FROM api.sheet_instances WHERE id=p_instance_id FOR SHARE;
  IF instance.id IS NULL OR NOT api.is_workspace_member(instance.workspace_id)
  THEN RAISE EXCEPTION 'workspace member required' USING ERRCODE='42501'; END IF;
  IF instance.lifecycle<>'active' OR instance.revision<>p_expected_instance_revision
  THEN RAISE EXCEPTION 'Sheet Instance revision conflict or archive' USING ERRCODE='SB073'; END IF;
  RETURN internal.build_sheet_definition_extraction_preview(instance,p_selection);
END $$;
