BEGIN
 IF p_instance_id IS NOT NULL THEN PERFORM internal.assert_object_access('instance',p_instance_id,'view'); END IF;
  SELECT * INTO instance FROM api.sheet_instances WHERE id=p_instance_id FOR SHARE;
