CREATE FUNCTION api.promote_calculation(p_instance_id uuid, p_calculation_id uuid, p_target text, p_schema_definition_id uuid, p_idempotency_key text, p_schema_version_id uuid DEFAULT NULL::uuid, p_expected_revision bigint DEFAULT NULL::bigint) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
  instance api.sheet_instances;
  preview jsonb;
  calculation jsonb;
  digest text;
  replay jsonb;
  actor text := api.current_user_id();
  definition api.sheet_definitions;
  version api.sheet_definition_versions;
  config jsonb;
  column_id uuid;
  write_version api.dataset_schema_versions;
  source_id uuid;
  result jsonb;
BEGIN
 IF p_instance_id IS NOT NULL THEN PERFORM internal.assert_object_access('instance',p_instance_id,'edit'); END IF;
  SELECT * INTO instance FROM api.sheet_instances WHERE id = p_instance_id FOR UPDATE;
  IF instance.id IS NULL THEN RAISE EXCEPTION 'workspace member required' USING ERRCODE = '42501'; END IF;
  PERFORM api.require_capability(instance.workspace_id, 'schema.edit');
  preview := api.preview_calculation_promotion(p_instance_id, p_calculation_id, p_target);
  IF (preview->>'ok')::boolean IS NOT TRUE THEN
    RAISE EXCEPTION 'calculation cannot be promoted: %', preview->>'reason' USING ERRCODE = 'SB071';
  END IF;
  calculation := preview->'calculation';
  digest := encode(sha256(convert_to(jsonb_build_object(
    'instance', p_instance_id,
    'calculation', p_calculation_id,
    'target', p_target,
    'schema', p_schema_definition_id,
    'schemaVersion', p_schema_version_id
  )::text, 'UTF8')), 'hex');
  replay := internal.replay_configuration_change(
    instance.workspace_id, actor, 'calculation_promotion', p_idempotency_key, digest
  );
  IF replay IS NOT NULL THEN RETURN replay; END IF;
  IF p_target = 'sheet_definition' THEN
    IF instance.source_definition_version_id IS NULL THEN
      RAISE EXCEPTION 'Instance has no pinned Sheet Definition to receive the calculation' USING ERRCODE = 'SB071';
    END IF;
    SELECT * INTO version FROM api.sheet_definition_versions WHERE id = instance.source_definition_version_id;
    SELECT * INTO definition FROM api.sheet_definitions WHERE id = version.definition_id;
    config := version.configuration;
    column_id := p_calculation_id;
    config := jsonb_set(config, '{columns}', coalesce(config->'columns','[]'::jsonb) || jsonb_build_array(jsonb_build_object(
      'id', column_id,
      'field', coalesce(calculation->'outputField', jsonb_build_object(
        'fieldId', column_id,
        'key', calculation->>'key',
        'label', calculation->>'label',
        'description', null,
        'logicalType', 'decimal',
        'nullable', true,
        'defaultValue', null,
        'cardinality', 'one',
        'quantity', null,
        'validation', '{}'::jsonb,
        'category', null,
        'relationship', null,
        'computation', jsonb_build_object('mode', 'computed', 'expressionId', column_id),
        'lifecycle', 'active'
      )),
      'source', jsonb_build_object('kind', 'calculated', 'calculationId', column_id)
    )));
    IF config #> '{presentation,columnOrder}' IS NOT NULL THEN
      config := jsonb_set(
        config,
        '{presentation,columnOrder}',
        coalesce(config->'presentation'->'columnOrder', '[]'::jsonb) || jsonb_build_array(column_id)
      );
    END IF;
    config := jsonb_set(config, '{calculations}', coalesce(config->'calculations','[]'::jsonb) || jsonb_build_array(jsonb_build_object(
      'id', calculation->>'id',
      'key', calculation->>'key',
      'label', calculation->>'label',
      'outputColumnId', column_id,
      'inputColumnIds', coalesce((
        SELECT jsonb_agg(dep->>'id') FROM jsonb_array_elements(calculation->'dependencies') dep
         WHERE dep->>'kind' = 'column'
      ), '[]'::jsonb),
      'expression', calculation->'expression'
    )));
    IF version.lifecycle = 'draft' THEN
      version := api.update_sheet_definition_draft(version.id, version.revision, config);
    ELSE
      version := api.create_sheet_definition_version(definition.id, definition.revision, config);
    END IF;
    result := preview || jsonb_build_object(
      'ok', true, 'targetKind', 'sheet_definition_version', 'targetId', version.id, 'idempotent', false
    );
  ELSIF p_target = 'dataset_schema' THEN
    IF p_schema_definition_id IS NULL THEN RAISE EXCEPTION 'Dataset Schema Definition is required' USING ERRCODE = '22023'; END IF;
    IF p_schema_version_id IS NOT NULL THEN
      SELECT * INTO write_version FROM api.dataset_schema_versions WHERE id = p_schema_version_id;
      IF write_version.schema_id IS DISTINCT FROM p_schema_definition_id THEN
        RAISE EXCEPTION 'Dataset Schema Version does not belong to the Definition' USING ERRCODE = '22023';
      END IF;
      write_version := internal.lock_dataset_schema_write_version(p_schema_version_id, p_expected_revision);
    ELSE
      IF EXISTS (
        SELECT 1 FROM api.dataset_schema_versions
         WHERE schema_id = p_schema_definition_id AND lifecycle = 'draft'
      ) THEN
        RAISE EXCEPTION 'a draft Dataset Schema Version already exists' USING ERRCODE = 'SB072';
      END IF;
      SELECT id INTO source_id
        FROM api.dataset_schema_versions
       WHERE schema_id = p_schema_definition_id
       ORDER BY version DESC
       LIMIT 1;
      write_version := internal.fork_dataset_schema_version(source_id);
    END IF;
    PERFORM api.replace_dataset_schema_version_fields(
      write_version.id,
      coalesce((
        SELECT jsonb_agg(jsonb_build_object(
          'field_id', field_id, 'key', key, 'label', label, 'logical_type', logical_type,
          'nullable', nullable, 'validation', validation, 'cardinality', cardinality,
          'display_order', display_order
        ) ORDER BY display_order)
        FROM api.dataset_schema_version_fields
        WHERE schema_version_id = write_version.id
      ), '[]'::jsonb) || jsonb_build_array(jsonb_build_object(
        'field_id', p_calculation_id,
        'key', calculation->>'key',
        'label', calculation->>'label',
        'logical_type', coalesce(calculation->'outputField'->>'logicalType','decimal'),
        'nullable', true
      ))
    );
    result := preview || jsonb_build_object(
      'ok', true,
      'targetKind', 'dataset_schema_field',
      'targetId', p_calculation_id,
      'schemaVersionId', write_version.id,
      'storesFormula', false,
      'idempotent', false
    );
  ELSE
    RAISE EXCEPTION 'unsupported calculation promotion target' USING ERRCODE = '22023';
  END IF;
  PERFORM internal.record_configuration_change(
    instance.workspace_id, actor, 'calculation_promotion', p_idempotency_key, digest, result
  );
  RETURN result;
END;
$$;
--> statement-breakpoint
ALTER FUNCTION api.promote_calculation(p_instance_id uuid, p_calculation_id uuid, p_target text, p_schema_definition_id uuid, p_idempotency_key text, p_schema_version_id uuid, p_expected_revision bigint) OWNER TO migrator;
--> statement-breakpoint
CREATE FUNCTION api.promote_local_field(p_instance_id uuid, p_field_id uuid, p_target text, p_schema_definition_id uuid, p_idempotency_key text, p_model_key text DEFAULT NULL::text, p_schema_version_id uuid DEFAULT NULL::uuid, p_expected_revision bigint DEFAULT NULL::bigint) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
  instance api.sheet_instances;
  preview jsonb;
  local_field jsonb;
  digest text;
  replay jsonb;
  actor text := api.current_user_id();
  write_version api.dataset_schema_versions;
  source_id uuid;
  created api.record_field_definitions;
  result jsonb;
  fields jsonb;
BEGIN
 IF p_instance_id IS NOT NULL THEN PERFORM internal.assert_object_access('instance',p_instance_id,'edit'); END IF;
  SELECT * INTO instance FROM api.sheet_instances WHERE id = p_instance_id FOR UPDATE;
  IF instance.id IS NULL THEN RAISE EXCEPTION 'workspace member required' USING ERRCODE = '42501'; END IF;
  PERFORM api.require_capability(instance.workspace_id, 'schema.edit');
  preview := api.preview_local_field_promotion(
    p_instance_id, p_field_id, p_target, p_schema_definition_id, p_model_key
  );
  IF (preview->>'ok')::boolean IS NOT TRUE THEN
    RAISE EXCEPTION 'local field values are incompatible with promotion' USING ERRCODE = 'SB071';
  END IF;
  local_field := preview->'field';
  digest := encode(sha256(convert_to(jsonb_build_object(
    'instance', p_instance_id,
    'field', p_field_id,
    'target', p_target,
    'schema', p_schema_definition_id,
    'modelKey', p_model_key,
    'schemaVersion', p_schema_version_id
  )::text, 'UTF8')), 'hex');
  replay := internal.replay_configuration_change(
    instance.workspace_id, actor, 'local_field_promotion', p_idempotency_key, digest
  );
  IF replay IS NOT NULL THEN RETURN replay; END IF;
  IF p_target = 'model_field' THEN
    created := api.create_model_field(
      instance.workspace_id,
      p_model_key,
      local_field->>'key',
      local_field->>'label',
      local_field->>'logicalType',
      coalesce((local_field->>'nullable')::boolean, true),
      local_field->'defaultValue',
      coalesce(local_field->'validation','{}'::jsonb)
    );
    result := preview || jsonb_build_object(
      'ok', true,
      'targetKind', 'model_field',
      'targetId', created.id,
      'modelKey', p_model_key,
      'idempotent', false
    );
    PERFORM internal.record_configuration_change(
      instance.workspace_id, actor, 'local_field_promotion', p_idempotency_key, digest, result
    );
    RETURN result;
  END IF;
  IF p_target <> 'dataset_schema' THEN
    RAISE EXCEPTION 'unsupported promotion target' USING ERRCODE = '22023';
  END IF;
  IF p_schema_definition_id IS NULL THEN
    RAISE EXCEPTION 'Dataset Schema Definition is required' USING ERRCODE = '22023';
  END IF;
  IF p_schema_version_id IS NOT NULL THEN
    SELECT * INTO write_version FROM api.dataset_schema_versions WHERE id = p_schema_version_id;
    IF write_version.schema_id IS DISTINCT FROM p_schema_definition_id THEN
      RAISE EXCEPTION 'Dataset Schema Version does not belong to the Definition' USING ERRCODE = '22023';
    END IF;
    write_version := internal.lock_dataset_schema_write_version(p_schema_version_id, p_expected_revision);
  ELSE
    IF EXISTS (
      SELECT 1 FROM api.dataset_schema_versions
       WHERE schema_id = p_schema_definition_id AND lifecycle = 'draft'
    ) THEN
      RAISE EXCEPTION 'a draft Dataset Schema Version already exists' USING ERRCODE = 'SB072';
    END IF;
    SELECT id INTO source_id
      FROM api.dataset_schema_versions
     WHERE schema_id = p_schema_definition_id
     ORDER BY version DESC
     LIMIT 1;
    write_version := internal.fork_dataset_schema_version(source_id);
  END IF;
  SELECT coalesce(jsonb_agg(jsonb_build_object(
    'field_id', field_id, 'key', key, 'label', label, 'description', description,
    'logical_type', logical_type, 'nullable', nullable, 'default_value', default_value,
    'quantity', quantity, 'validation', validation, 'category', category,
    'relationship', relationship, 'cardinality', cardinality, 'display_order', display_order
  ) ORDER BY display_order), '[]'::jsonb) INTO fields
    FROM api.dataset_schema_version_fields
   WHERE schema_version_id = write_version.id;
  fields := fields || jsonb_build_array(jsonb_build_object(
    'field_id', p_field_id,
    'key', local_field->>'key',
    'label', local_field->>'label',
    'description', local_field->>'description',
    'logical_type', local_field->>'logicalType',
    'nullable', (local_field->>'nullable')::boolean,
    'default_value', local_field->'defaultValue',
    'quantity', local_field->'quantity',
    'validation', coalesce(local_field->'validation','{}'::jsonb),
    'category', local_field->'category',
    'relationship', local_field->'relationship',
    'cardinality', coalesce(local_field->>'cardinality','one')
  ));
  PERFORM api.replace_dataset_schema_version_fields(write_version.id, fields);
  result := preview || jsonb_build_object(
    'ok', true,
    'targetKind', 'dataset_schema_field',
    'targetId', p_field_id,
    'schemaVersionId', write_version.id,
    'idempotent', false
  );
  PERFORM internal.record_configuration_change(
    instance.workspace_id, actor, 'local_field_promotion', p_idempotency_key, digest, result
  );
  RETURN result;
END;
$$;
--> statement-breakpoint
ALTER FUNCTION api.promote_local_field(p_instance_id uuid, p_field_id uuid, p_target text, p_schema_definition_id uuid, p_idempotency_key text, p_model_key text, p_schema_version_id uuid, p_expected_revision bigint) OWNER TO migrator;
--> statement-breakpoint
CREATE FUNCTION api.propose_agent_operation(p_workspace_id uuid, p_title text, p_summary text, p_operation jsonb, p_provenance jsonb, p_idempotency_key text) RETURNS api.agent_operation_proposals
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
  v_actor_user text := api.current_user_id();
  v_actor_credential uuid := api.current_credential_id();
  v_contract jsonb;
  v_evaluation jsonb;
  v_digest text;
  v_existing api.agent_operation_proposals;
  v_result api.agent_operation_proposals;
BEGIN
  IF api.current_workspace_id() IS DISTINCT FROM p_workspace_id
     OR NOT api.has_write_actor() THEN
    RAISE EXCEPTION 'workspace write actor required' USING ERRCODE = '42501';
  END IF;
  IF length(btrim(coalesce(p_title,''))) NOT BETWEEN 1 AND 200
     OR length(btrim(coalesce(p_summary,''))) NOT BETWEEN 1 AND 2000
     OR length(coalesce(p_idempotency_key,'')) NOT BETWEEN 1 AND 128 THEN
    RAISE EXCEPTION 'invalid proposal metadata' USING ERRCODE = '22023';
  END IF;
  IF coalesce(p_provenance->>'kind','') <> 'pipeline' AND (jsonb_typeof(p_provenance) IS DISTINCT FROM 'object'
     OR p_provenance - ARRAY['agentId','agentName','tool','model','invocationId'] <> '{}'::jsonb
     OR length(btrim(p_provenance->>'agentId')) NOT BETWEEN 1 AND 200
     OR length(btrim(p_provenance->>'invocationId')) NOT BETWEEN 1 AND 200
     OR jsonb_typeof(p_provenance->'tool') IS DISTINCT FROM 'object'
     OR length(btrim(p_provenance->'tool'->>'name')) NOT BETWEEN 1 AND 200
     OR jsonb_typeof(p_provenance->'model') IS DISTINCT FROM 'object'
     OR length(btrim(p_provenance->'model'->>'provider')) NOT BETWEEN 1 AND 100
     OR length(btrim(p_provenance->'model'->>'name')) NOT BETWEEN 1 AND 200) THEN
    RAISE EXCEPTION 'agent, tool, model, and invocation provenance are required' USING ERRCODE = '22023';
  END IF;
  IF p_provenance->>'kind' = 'pipeline' AND (
       p_provenance - ARRAY['kind','pipelineId','pipelineName','definitionVersionId','runId','invocationId'] <> '{}'::jsonb
       OR length(btrim(coalesce(p_provenance->>'pipelineId',''))) NOT BETWEEN 1 AND 200
       OR length(btrim(coalesce(p_provenance->>'pipelineName',''))) NOT BETWEEN 1 AND 200
       OR length(btrim(coalesce(p_provenance->>'runId',''))) NOT BETWEEN 1 AND 200
       OR length(btrim(coalesce(p_provenance->>'invocationId',''))) NOT BETWEEN 1 AND 200) THEN
    RAISE EXCEPTION 'pipeline provenance is incomplete' USING ERRCODE = '22023';
  END IF;

  IF p_operation->>'kind' IN (
       'sheet_definition.update_draft',
       'pipeline_definition.create_version',
       'pipeline_definition.update_draft',
       'dataset_rows.commit'
     )
     AND (
       (
         p_operation->>'kind' = 'pipeline_definition.create_version'
         AND p_operation->>'expectedDefinitionRevision' IS NULL
       )
       OR (
         p_operation->>'kind' <> 'pipeline_definition.create_version'
         AND p_operation->>'expectedRevision' IS NULL
       )
     ) THEN
    RAISE EXCEPTION 'optimistic concurrency revision is required' USING ERRCODE = '22023';
  END IF;

  v_contract := internal.agent_operation_contract(p_workspace_id, p_operation);
  v_evaluation := internal.agent_operation_policy_evaluate(
    p_workspace_id, p_operation, v_contract
  );
  v_digest := encode(sha256(convert_to(jsonb_build_object(
    'workspaceId',p_workspace_id,'title',btrim(p_title),'summary',btrim(p_summary),
    'operation',p_operation,'provenance',p_provenance
  )::text,'UTF8')),'hex');

  SELECT * INTO v_existing
    FROM api.agent_operation_proposals
   WHERE workspace_id = p_workspace_id AND idempotency_key = p_idempotency_key;
  IF v_existing.id IS NOT NULL THEN
    IF v_existing.request_digest <> v_digest
       OR v_existing.proposed_by_user_id IS DISTINCT FROM v_actor_user
       OR v_existing.proposed_by_credential_id IS DISTINCT FROM v_actor_credential THEN
      RAISE EXCEPTION 'idempotency key was used for a different proposal' USING ERRCODE = '23505';
    END IF;
    RETURN v_existing;
  END IF;

  -- Supersede the older pending proposals for the same change.
  UPDATE api.agent_operation_proposals
     SET status = 'cancelled',
         revision = revision + 1,
         rejection_reason = 'Superseded by a newer proposal for the same change.',
         updated_at = now()
   WHERE workspace_id = p_workspace_id
     AND status = 'pending'
     AND operation_kind = p_operation->>'kind'
     AND operation = p_operation
     AND policy_target IS NOT DISTINCT FROM v_contract->'preview'->'target';

  INSERT INTO api.agent_operation_proposals(
    workspace_id,title,summary,operation_kind,operation,preview,impact,
    risk_class,approval_policy,policy_id,policy_reason,policy_limits,
    policy_target,policy_evidence,idempotency_key,request_digest,provenance,
    proposed_by_user_id,proposed_by_credential_id
  ) VALUES (
    p_workspace_id,btrim(p_title),btrim(p_summary),p_operation->>'kind',
    p_operation,v_contract->'preview',v_contract->'impact',
    v_evaluation->>'riskClass',v_evaluation->>'approvalPolicy',
    nullif(v_evaluation->>'policyId','')::uuid,
    v_evaluation->>'policyReason',v_evaluation->'policyLimits',
    v_evaluation->'policyTarget',v_evaluation->'policyEvidence',
    p_idempotency_key,v_digest,p_provenance,v_actor_user,v_actor_credential
  ) RETURNING * INTO v_result;
  PERFORM internal.agent_operation_append_event(v_result,'proposed',
    jsonb_build_object(
      'operationKind',v_result.operation_kind,
      'requestDigest',v_digest,
      'riskClass',v_result.risk_class,
      'approvalPolicy',v_result.approval_policy,
      'policyId',v_result.policy_id,
      'reason',v_result.policy_reason,
      'limits',v_result.policy_limits,
      'target',v_result.policy_target,
      'evaluation',v_result.policy_evidence
    ));
  PERFORM internal.emit_change_event(
    v_result.workspace_id,'agent_operation_proposal',v_result.id,'create',
    NULL,NULL,jsonb_build_object(
      'status',v_result.status,
      'operationKind',v_result.operation_kind,
      'riskClass',v_result.risk_class,
      'approvalPolicy',v_result.approval_policy
    )
  );
  IF v_result.approval_policy IN ('automatic', 'delegated') THEN
    PERFORM internal.agent_operation_execute(v_result.id);
    SELECT * INTO v_result
      FROM api.agent_operation_proposals
     WHERE id = v_result.id AND workspace_id = p_workspace_id;
  END IF;
  RETURN v_result;
END;
$$;
--> statement-breakpoint
ALTER FUNCTION api.propose_agent_operation(p_workspace_id uuid, p_title text, p_summary text, p_operation jsonb, p_provenance jsonb, p_idempotency_key text) OWNER TO migrator;
