CREATE FUNCTION api.prune_dataset_versions(p_limit integer DEFAULT 100) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
  r record;
  seq bigint;
  pruned jsonb := '[]'::jsonb;
BEGIN
  IF p_limit IS NULL OR p_limit NOT BETWEEN 1 AND 1000 THEN
    RAISE EXCEPTION 'invalid prune limit' USING ERRCODE = '22023';
  END IF;

  PERFORM set_config('sheetbase.dataset_prune', 'on', true);

  FOR r IN
    SELECT v.id, v.workspace_id,
      (SELECT count(*) FROM api.dataset_version_rows vr
        WHERE vr.dataset_version_id = v.id) AS row_count
    FROM api.dataset_versions v
    JOIN api.datasets d ON d.id = v.dataset_id
    LEFT JOIN api.workspace_settings ws ON ws.workspace_id = v.workspace_id
    LEFT JOIN api.dataset_version_keeps k ON k.dataset_version_id = v.id
    WHERE NOT EXISTS (
        SELECT 1 FROM api.dataset_version_prunes p
        WHERE p.dataset_version_id = v.id
      )
      AND d.archived_at IS NOT NULL
 AND NOT internal.import_block_references('datasetVersionId',v.id)
      AND (k.kept_until IS NULL OR k.kept_until <= now())
      AND d.archived_at + make_interval(years => coalesce(ws.snapshot_uncited_retention_years, 2)) <= now()
      AND NOT EXISTS (
        SELECT 1 FROM api.revision_sheet_evidence e
        JOIN api.signatures s ON s.revision_id = e.revision_id
        WHERE s.signature_meaning = 'approve-for-record'
          AND e.dataset_versions ? v.id::text
      )
    ORDER BY d.archived_at, v.id
    LIMIT p_limit
    FOR UPDATE OF v SKIP LOCKED
  LOOP
    DELETE FROM api.dataset_version_values WHERE dataset_version_id = r.id;
    DELETE FROM api.dataset_version_rows WHERE dataset_version_id = r.id;
    INSERT INTO api.dataset_version_prunes
      (dataset_version_id, rows_removed_at, pruned_row_count)
    VALUES (r.id, now(), r.row_count);
    INSERT INTO api.workspace_change_seq (workspace_id, last_seq)
    VALUES (r.workspace_id, 1)
    ON CONFLICT (workspace_id) DO UPDATE
      SET last_seq = api.workspace_change_seq.last_seq + 1, updated_at = now()
    RETURNING last_seq INTO seq;
    INSERT INTO api.change_events
      (id, workspace_id, sequence, entity_type, entity_uuid, operation, payload)
    VALUES (gen_random_uuid(), r.workspace_id, seq, 'dataset_version', r.id, 'delete',
            jsonb_build_object('rowsRemoved', r.row_count));
    pruned := pruned || jsonb_build_object(
      'datasetVersionId', r.id,
      'rowsRemoved', r.row_count
    );
  END LOOP;

  PERFORM set_config('sheetbase.dataset_prune', '', true);

  RETURN jsonb_build_object(
    'prunedCount', jsonb_array_length(pruned),
    'pruned', pruned
  );
END;
$$;
--> statement-breakpoint
ALTER FUNCTION api.prune_dataset_versions(p_limit integer) OWNER TO migrator;
--> statement-breakpoint
CREATE FUNCTION api.publish_dataset_schema(p_schema_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE s api.dataset_schemas; a jsonb; prior api.dataset_schemas;
BEGIN
  PERFORM "internal"."require_migrator_legacy_sheet_write"();
  SELECT * INTO s FROM api.dataset_schemas WHERE id=p_schema_id FOR UPDATE;
  IF s.id IS NULL THEN RAISE EXCEPTION 'schema not found' USING ERRCODE='P0002'; END IF;
  a := internal.assert_scientific_actor(s.workspace_id);
  IF NOT api.is_workspace_member(s.workspace_id,'owner') THEN RAISE EXCEPTION 'only a workspace owner may publish a schema' USING ERRCODE='42501'; END IF;
  IF s.status <> 'draft' THEN RAISE EXCEPTION 'only a draft revision can be published' USING ERRCODE='23514'; END IF;
  IF NOT EXISTS (SELECT 1 FROM api.dataset_schema_fields WHERE schema_id=s.id AND lifecycle='active') THEN RAISE EXCEPTION 'cannot publish a schema with no active fields' USING ERRCODE='23514'; END IF;
  -- Retire any previously-published revision of the same slug and repoint
  -- relationships to the newly published revision.
  FOR prior IN SELECT * FROM api.dataset_schemas WHERE workspace_id=s.workspace_id AND slug=s.slug AND status='published' AND id<>s.id LOOP
    UPDATE api.dataset_schemas SET status='retired' WHERE id=prior.id;
    -- Repoint relationships where the retired revision was the source.
    UPDATE api.dataset_schema_relationships
      SET source_schema_id = s.id,
          source_field_id = CASE WHEN source_field_id IS NOT NULL THEN (
            SELECT nf.id FROM api.dataset_schema_fields nf
            WHERE nf.schema_id = s.id AND nf.slug = (
              SELECT of.slug FROM api.dataset_schema_fields of WHERE of.id = dataset_schema_relationships.source_field_id
            ) LIMIT 1
          ) END,
          updated_at = now()
      WHERE source_schema_id = prior.id AND lifecycle = 'active';
    -- Repoint relationships where the retired revision was the target.
    UPDATE api.dataset_schema_relationships
      SET target_schema_id = s.id,
          target_field_id = CASE WHEN target_field_id IS NOT NULL THEN (
            SELECT nf.id FROM api.dataset_schema_fields nf
            WHERE nf.schema_id = s.id AND nf.slug = (
              SELECT of.slug FROM api.dataset_schema_fields of WHERE of.id = dataset_schema_relationships.target_field_id
            ) LIMIT 1
          ) END,
          updated_at = now()
      WHERE target_schema_id = prior.id AND lifecycle = 'active';
    PERFORM internal.emit_change_event(s.workspace_id,'dataset_schema',prior.id,'update',NULL,NULL,jsonb_build_object('schemaId',prior.id,'slug',prior.slug,'status','retired','supersededBy',s.id));
  END LOOP;
  UPDATE api.dataset_schemas SET status='published' WHERE id=s.id;
  PERFORM internal.emit_change_event(s.workspace_id,'dataset_schema',s.id,'update',NULL,NULL,jsonb_build_object('schemaId',s.id,'slug',s.slug,'revision',s.revision,'status','published'));
  RETURN jsonb_build_object('published',true,'schemaId',s.id,'revision',s.revision);
END $$;
--> statement-breakpoint
ALTER FUNCTION api.publish_dataset_schema(p_schema_id uuid) OWNER TO migrator;
--> statement-breakpoint
CREATE TABLE api.dataset_schema_versions (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    schema_id uuid NOT NULL,
    version integer NOT NULL,
    lifecycle text DEFAULT 'draft'::text NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    published_at timestamp with time zone,
    created_by_user_id text,
    revision bigint DEFAULT 1 NOT NULL,
    CONSTRAINT chk_dataset_schema_versions_lifecycle CHECK ((lifecycle = ANY (ARRAY['draft'::text, 'active'::text, 'retired'::text]))),
    CONSTRAINT chk_dataset_schema_versions_revision CHECK ((revision > 0)),
    CONSTRAINT chk_dataset_schema_versions_version CHECK ((version > 0))
);
