CREATE FUNCTION api.publish_notebook_template_version(p_version_id uuid, p_expected_revision bigint, p_reason text) RETURNS api.notebook_template_versions
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
  result api.notebook_template_versions;
  template api.notebook_templates;
  actor text := api.current_user_id();
BEGIN
  SELECT * INTO result FROM api.notebook_template_versions WHERE id = p_version_id FOR UPDATE;
  IF result.id IS NULL THEN RAISE EXCEPTION 'capability required: schema.publish' USING ERRCODE = '42501'; END IF;
  SELECT * INTO template FROM api.notebook_templates WHERE id = result.template_id FOR UPDATE;
  PERFORM api.require_capability(template.workspace_id, 'schema.publish');
  IF p_reason IS NULL OR length(btrim(p_reason)) NOT BETWEEN 1 AND 500 THEN
    RAISE EXCEPTION 'a reason is required' USING ERRCODE = '22023';
  END IF;
  IF result.lifecycle <> 'draft' THEN
    RAISE EXCEPTION 'only draft Notebook Template Versions can be published' USING ERRCODE = 'SB090';
  END IF;
  IF result.revision <> p_expected_revision THEN
    RAISE EXCEPTION 'stale Notebook Template Version revision' USING ERRCODE = 'SB001';
  END IF;
  UPDATE api.notebook_template_versions
    SET lifecycle = 'published', published_at = now(), published_by_user_id = actor,
        reason = btrim(p_reason), updated_at = now(), updated_by_user_id = actor
    WHERE id = result.id
  RETURNING * INTO result;
  RETURN result;
END $$;
--> statement-breakpoint
ALTER FUNCTION api.publish_notebook_template_version(p_version_id uuid, p_expected_revision bigint, p_reason text) OWNER TO migrator;
--> statement-breakpoint
CREATE FUNCTION api.publish_pipeline_definition_version(p_workspace_id uuid, p_version_id uuid) RETURNS api.pipeline_definition_versions
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
  v_version api.pipeline_definition_versions;
  v_definition api.pipeline_definitions;
  v_errors jsonb;
BEGIN
  IF api.current_workspace_id() IS DISTINCT FROM p_workspace_id THEN
    RAISE EXCEPTION 'wrong workspace' USING ERRCODE = 'SB033';
  END IF;
  PERFORM api.require_capability(p_workspace_id, 'pipelines.manage');
  SELECT * INTO v_version FROM api.pipeline_definition_versions
   WHERE id = p_version_id AND workspace_id = p_workspace_id FOR UPDATE;
  IF v_version IS NULL THEN
    RAISE EXCEPTION 'pipeline definition version not found' USING ERRCODE = 'SB036';
  END IF;
  SELECT * INTO v_definition FROM api.pipeline_definitions
   WHERE id = v_version.definition_id FOR UPDATE;
  IF v_definition.lifecycle <> 'active' OR v_version.lifecycle <> 'draft' THEN
    RAISE EXCEPTION 'only active Definition drafts may be published' USING ERRCODE = 'SB072';
  END IF;
  v_errors := api.pipeline_config_errors(v_version.configuration);
  IF jsonb_array_length(v_errors) > 0 THEN
    RAISE EXCEPTION 'invalid pipeline configuration: %', (v_errors #>> '{}')
      USING ERRCODE = 'SB070';
  END IF;
  UPDATE api.pipeline_definition_versions SET
    lifecycle = 'published',
    revision = revision + 1,
    published_at = now(),
    published_by_user_id = api.current_user_id(),
    updated_at = now(),
    updated_by_user_id = api.current_user_id()
  WHERE id = v_version.id
  RETURNING * INTO v_version;
  RETURN v_version;
END $$;
--> statement-breakpoint
ALTER FUNCTION api.publish_pipeline_definition_version(p_workspace_id uuid, p_version_id uuid) OWNER TO migrator;
--> statement-breakpoint
CREATE FUNCTION api.publish_record_model_version(p_version_id uuid) RETURNS api.record_model_versions
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
  v_version "api"."record_model_versions";
  v_block text;
  v_model api.record_models;
  v_field jsonb;
  v_present uuid[] := '{}';
  p_definition jsonb;
BEGIN
  SELECT * INTO v_version FROM api.record_model_versions WHERE id = p_version_id FOR UPDATE;
  IF v_version.id IS NULL OR v_version.workspace_id IS DISTINCT FROM api.current_workspace_id() THEN
    RAISE EXCEPTION 'Record Model version not found' USING ERRCODE = '42501';
  END IF;
  PERFORM api.require_capability(v_version.workspace_id, 'schema.publish');
  IF v_version.lifecycle <> 'draft' THEN
    RAISE EXCEPTION 'only draft Record Model versions may be published' USING ERRCODE = 'SB072';
  END IF;
  v_block := internal.approval_publish_blocker('record_model_version', v_version.id);
  IF v_block IS NOT NULL THEN
    RAISE EXCEPTION 'Record Model version cannot be published: %', v_block USING ERRCODE = 'SB084';
  END IF;
  p_definition := v_version.definition;
  SELECT * INTO v_model FROM api.record_models WHERE id = v_version.model_id FOR UPDATE;
  IF v_model.lifecycle='published' AND v_version.version<=v_model.current_version THEN
    RAISE EXCEPTION 'a newer Record Model version is already published' USING ERRCODE='SB072';
  END IF;
  -- Serialize the short publication projection, including direct field writes.
  -- Ownership can have changed since this proposal was saved.
  LOCK TABLE api.record_field_definitions IN SHARE ROW EXCLUSIVE MODE;
  IF EXISTS(SELECT 1 FROM jsonb_array_elements(p_definition->'fields') f
    JOIN api.record_field_definitions d ON d.id=(f->>'id')::uuid
    WHERE d.workspace_id<>v_model.workspace_id OR d.kind<>v_model.key) THEN
    RAISE EXCEPTION 'field identity belongs to another model' USING ERRCODE='SB070';
  END IF;
  FOR v_field IN SELECT * FROM jsonb_array_elements(p_definition->'fields') LOOP
    v_present := v_present || (v_field->>'id')::uuid;
    INSERT INTO api.record_field_definitions(
      id, workspace_id, kind, field_name, label, description, display_order,
      logical_type, nullable, default_value, quantity, cardinality,
      category_source, relationship, validation, lifecycle, created_by_user_id
    ) VALUES (
      (v_field->>'id')::uuid, v_model.workspace_id, v_model.key, v_field->>'field_name',
      coalesce(nullif(v_field->>'label',''), v_field->>'field_name'), v_field->>'description',
      coalesce((v_field->>'display_order')::integer, 0),
      coalesce(nullif(v_field->>'logical_type',''), 'text'),
      coalesce((v_field->>'nullable')::boolean, true), v_field->'default_value',
      v_field->'quantity', coalesce(nullif(v_field->>'cardinality',''), 'one'),
      v_field->'category_source', v_field->'relationship',
      coalesce(v_field->'validation', '{}'::jsonb),
      coalesce(nullif(v_field->>'lifecycle',''), 'active'), api.current_user_id()
    )
    ON CONFLICT (id) DO UPDATE SET
      label = excluded.label, description = excluded.description,
      display_order = excluded.display_order, logical_type = excluded.logical_type,
      nullable = excluded.nullable, default_value = excluded.default_value,
      quantity = excluded.quantity, cardinality = excluded.cardinality,
      category_source = excluded.category_source, relationship = excluded.relationship,
      validation = excluded.validation, lifecycle = excluded.lifecycle,
      updated_at = now();
  END LOOP;
  UPDATE api.record_field_definitions
     SET lifecycle = 'retired', updated_at = now()
   WHERE workspace_id = v_model.workspace_id AND kind = v_model.key
     AND lifecycle = 'active' AND NOT (id = ANY(v_present));
  UPDATE api.record_model_versions
     SET lifecycle = 'published', published_at = now(), updated_by_user_id = api.current_user_id(), updated_at = now()
   WHERE id = v_version.id
  RETURNING * INTO v_version;
  UPDATE api.record_models
     SET current_version = v_version.version, lifecycle = 'published',
         updated_by_user_id = api.current_user_id(), updated_at = now()
   WHERE id = v_version.model_id;
  PERFORM internal.emit_change_event(v_version.workspace_id, 'record_model_version', v_version.id, 'update', NULL, NULL,
    jsonb_build_object('modelId', v_version.model_id, 'version', v_version.version, 'effect', 'published'));
  IF v_version.definition->>'migrationScope' = 'also-migrate-open-experiments' THEN
    PERFORM api.migrate_open_experiments_to_model_version(v_version.model_id, v_version.id, v_version.reason);
  END IF;
  RETURN v_version;
END $$;
--> statement-breakpoint
ALTER FUNCTION api.publish_record_model_version(p_version_id uuid) OWNER TO migrator;
--> statement-breakpoint
CREATE FUNCTION api.publish_sheet_definition_version(p_version_id uuid, p_expected_revision bigint) RETURNS api.sheet_definition_versions
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE version api.sheet_definition_versions; definition api.sheet_definitions; actor text:=api.current_user_id();
BEGIN
 SELECT * INTO version FROM api.sheet_definition_versions WHERE id=p_version_id FOR UPDATE; SELECT * INTO definition FROM api.sheet_definitions WHERE id=version.definition_id FOR UPDATE;
 IF version.id IS NULL THEN RAISE EXCEPTION 'capability required: schema.publish' USING ERRCODE='42501'; END IF;
 PERFORM api.require_capability(definition.workspace_id, 'schema.publish');
 IF version.revision<>p_expected_revision THEN RAISE EXCEPTION 'stale Sheet Definition Version revision' USING ERRCODE='SB001'; END IF;
 IF definition.lifecycle<>'active' OR version.lifecycle<>'draft' THEN RAISE EXCEPTION 'only active Definition drafts may be published' USING ERRCODE='SB072'; END IF;
 PERFORM internal.validate_sheet_definition_configuration(version.configuration);
 UPDATE api.sheet_definition_versions SET lifecycle='published',revision=revision+1,published_at=now(),published_by_user_id=actor,updated_at=now(),updated_by_user_id=actor WHERE id=version.id RETURNING * INTO version; RETURN version;
END $$;
--> statement-breakpoint
ALTER FUNCTION api.publish_sheet_definition_version(p_version_id uuid, p_expected_revision bigint) OWNER TO migrator;
--> statement-breakpoint
CREATE FUNCTION api.quarantine_sample(p_record_id uuid, p_expected_metadata_version integer, p_reason text, p_notes text DEFAULT NULL::text) RETURNS api.records
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
DECLARE
  v_row "api"."records";
  v_reason text;
BEGIN
  PERFORM "api"."require_capability"("api"."current_workspace_id"(), 'sample.quarantine');
  v_reason := btrim(coalesce(p_reason, ''));
  IF v_reason = '' THEN
    RAISE EXCEPTION 'a quarantine reason is required' USING ERRCODE = 'SB093';
  END IF;
  IF length(v_reason) > 2000 THEN
    RAISE EXCEPTION 'quarantine reason is too long' USING ERRCODE = '22023';
  END IF;

  SELECT * INTO v_row FROM "api"."records" WHERE id = p_record_id FOR UPDATE;
  IF v_row IS NULL THEN
    RAISE EXCEPTION 'record not found in active workspace' USING ERRCODE = '42501';
  END IF;
  IF v_row.kind <> 'sample' THEN
    RAISE EXCEPTION 'record % is not a sample', p_record_id USING ERRCODE = 'SB009';
  END IF;
  IF v_row.archived_at IS NOT NULL THEN
    RAISE EXCEPTION 'cannot quarantine an archived sample' USING ERRCODE = 'SB004';
  END IF;
  IF v_row.status NOT IN ('available', 'reserved', 'hold_exceeded') THEN
    RAISE EXCEPTION 'cannot quarantine a % sample', v_row.status USING ERRCODE = 'SB004';
  END IF;
  IF v_row.metadata_version <> p_expected_metadata_version THEN
    RAISE EXCEPTION 'metadata version mismatch: expected %, got %',
      p_expected_metadata_version, v_row.metadata_version USING ERRCODE = 'SB001';
  END IF;

  UPDATE "api"."records"
     SET status = 'quarantined',
         properties = properties || jsonb_build_object(
           'quarantineReason', v_reason,
           'quarantinedAt', now()
         ),
         metadata_version = v_row.metadata_version + 1,
         updated_by_user_id = "api"."current_user_id"()
   WHERE id = p_record_id
   RETURNING * INTO v_row;

  INSERT INTO "api"."sample_events"
    (workspace_id, record_id, operation, actor_user_id, notes)
  VALUES
    (v_row.workspace_id, v_row.id, 'quarantine', "api"."current_user_id"(), v_reason);

  RETURN v_row;
END;
$$;
