CREATE TABLE api.sheet_cell_conflicts (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    workspace_id uuid NOT NULL,
    sheet_instance_id uuid NOT NULL,
    row_key text NOT NULL,
    field_id uuid NOT NULL,
    local_value jsonb,
    local_author_user_id text NOT NULL,
    local_at timestamp with time zone NOT NULL,
    remote_value jsonb,
    remote_author_user_id text,
    remote_at timestamp with time zone,
    state text DEFAULT 'open'::text NOT NULL,
    resolved_value jsonb,
    resolved_by_user_id text,
    resolved_at timestamp with time zone,
    reason text,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT chk_sheet_cell_conflicts_remote CHECK (((remote_author_user_id IS NULL) = (remote_at IS NULL))),
    CONSTRAINT chk_sheet_cell_conflicts_resolution CHECK (((state = 'resolved'::text) = ((resolved_by_user_id IS NOT NULL) AND (resolved_at IS NOT NULL) AND (reason IS NOT NULL) AND ((length(btrim(reason)) >= 1) AND (length(btrim(reason)) <= 2000))))),
    CONSTRAINT chk_sheet_cell_conflicts_row_key CHECK (((length(btrim(row_key)) >= 1) AND (length(btrim(row_key)) <= 128))),
    CONSTRAINT chk_sheet_cell_conflicts_state CHECK ((state = ANY (ARRAY['open'::text, 'resolved'::text])))
);
--> statement-breakpoint
ALTER TABLE api.sheet_cell_conflicts OWNER TO migrator;
--> statement-breakpoint
CREATE FUNCTION api.record_cell_conflict(p_instance_id uuid, p_row_key text, p_field_id uuid, p_local_value jsonb, p_local_author_user_id text, p_local_at timestamp with time zone, p_remote_value jsonb DEFAULT NULL::jsonb, p_remote_author_user_id text DEFAULT NULL::text, p_remote_at timestamp with time zone DEFAULT NULL::timestamp with time zone) RETURNS api.sheet_cell_conflicts
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
  v_instance api.sheet_instances;
  v_existing api.sheet_cell_conflicts;
  v_row api.sheet_cell_conflicts;
  v_actor text := api.current_user_id();
BEGIN
  SELECT * INTO v_instance FROM api.sheet_instances WHERE id = p_instance_id;
  IF v_instance.id IS NULL
     OR v_instance.workspace_id IS DISTINCT FROM api.current_workspace_id() THEN
    RAISE EXCEPTION 'Unknown Sheet Instance' USING ERRCODE = '22023';
  END IF;
  PERFORM internal.assert_object_access('instance', p_instance_id, 'edit');

  IF p_local_author_user_id IS DISTINCT FROM v_actor THEN
    RAISE EXCEPTION 'A conflict must be raised by the person whose edit it is'
      USING ERRCODE = '42501';
  END IF;
  IF p_row_key IS NULL OR length(btrim(p_row_key)) NOT BETWEEN 1 AND 128 THEN
    RAISE EXCEPTION 'a row key is required' USING ERRCODE = '22023';
  END IF;

  -- Idempotent: a second replay finds the conflict it already raised.
  SELECT * INTO v_existing
    FROM api.sheet_cell_conflicts
   WHERE sheet_instance_id = p_instance_id
     AND row_key = btrim(p_row_key)
     AND field_id = p_field_id
     AND state = 'open';
  IF v_existing.id IS NOT NULL THEN
    RETURN v_existing;
  END IF;

  INSERT INTO api.sheet_cell_conflicts(
    workspace_id, sheet_instance_id, row_key, field_id,
    local_value, local_author_user_id, local_at,
    remote_value, remote_author_user_id, remote_at
  ) VALUES (
    v_instance.workspace_id, p_instance_id, btrim(p_row_key), p_field_id,
    p_local_value, v_actor, coalesce(p_local_at, now()),
    p_remote_value, p_remote_author_user_id, p_remote_at
  ) RETURNING * INTO v_row;

  -- Somebody has to decide; the work item is derived from the open row, so the person
  -- whose edit conflicted sees it without the sheet being open.
  PERFORM internal.emit_change_event(
    v_instance.workspace_id,
    'scientific_row',
    p_instance_id,
    'create',
    NULL,
    NULL,
    jsonb_build_object(
      'conflict', 'cell',
      'conflictId', v_row.id,
      'fieldId', p_field_id,
      'rowKey', v_row.row_key,
      'raisedBy', v_actor
    )
  );

  RETURN v_row;
END $$;
--> statement-breakpoint
