CREATE TABLE api.comments (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    workspace_id uuid NOT NULL,
    revision_id uuid,
    record_id uuid,
    root_id uuid NOT NULL,
    parent_id uuid,
    target_kind text NOT NULL,
    target jsonb DEFAULT '{}'::jsonb NOT NULL,
    body text NOT NULL,
    mentions text[] DEFAULT '{}'::text[] NOT NULL,
    state text DEFAULT 'open'::text NOT NULL,
    resolved_at timestamp with time zone,
    resolved_by_user_id text,
    author_user_id text,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    search_vector tsvector GENERATED ALWAYS AS (to_tsvector('english'::regconfig, COALESCE(body, ''::text))) STORED,
    sheet_instance_id uuid,
    CONSTRAINT chk_comments_anchor_owner CHECK (((((target_kind = ANY (ARRAY['sheet_cell'::text, 'sheet_row'::text, 'sheet_range'::text])) AND (sheet_instance_id IS NOT NULL)) OR ((target_kind = ANY (ARRAY['revision'::text, 'block'::text, 'table_region'::text, 'diff'::text, 'record'::text])) AND (sheet_instance_id IS NULL))) AND ((revision_id IS NOT NULL) OR (sheet_instance_id IS NOT NULL) OR ((target_kind = ANY (ARRAY['record'::text, 'block'::text])) AND (record_id IS NOT NULL))) AND ((revision_id IS NULL) OR (record_id IS NOT NULL)))),
    CONSTRAINT chk_comments_body CHECK (((length(body) >= 1) AND (length(body) <= 8000))),
    CONSTRAINT chk_comments_resolved_consistency CHECK (((state = 'resolved'::text) = (resolved_at IS NOT NULL))),
    CONSTRAINT chk_comments_root_parent CHECK (((parent_id IS NULL) = (root_id = id))),
    CONSTRAINT chk_comments_state CHECK ((state = ANY (ARRAY['open'::text, 'resolved'::text]))),
    CONSTRAINT chk_comments_target_kind CHECK ((target_kind = ANY (ARRAY['revision'::text, 'block'::text, 'table_region'::text, 'diff'::text, 'record'::text, 'sheet_cell'::text, 'sheet_row'::text, 'sheet_range'::text])))
);
