CREATE FUNCTION api.record_recent_view(p_object_kind text, p_object_id uuid) RETURNS timestamp with time zone
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
  v_user_id text;
  v_workspace_id uuid;
  v_viewed_at timestamptz;
BEGIN
  v_user_id := "api"."current_user_id"();
  IF v_user_id IS NULL THEN
    RAISE EXCEPTION 'record_recent_view requires an authenticated user' USING ERRCODE = '42501';
  END IF;
  IF p_object_kind NOT IN ('record', 'dataset', 'sheet', 'project', 'notebook_template') THEN
    RAISE EXCEPTION 'unknown recent-object kind' USING ERRCODE = '22023';
  END IF;

  IF p_object_kind<>'notebook_template' AND NOT internal.can_access_object(CASE p_object_kind WHEN 'sheet' THEN 'instance' ELSE p_object_kind END,p_object_id,'view') THEN RETURN NULL; END IF;
 v_workspace_id := CASE p_object_kind
    WHEN 'record' THEN (
      SELECT r.workspace_id FROM api.records r
      WHERE r.id = p_object_id AND r.deleted_at IS NULL
    )
    WHEN 'dataset' THEN (
      SELECT d.workspace_id FROM api.datasets d WHERE d.id = p_object_id
    )
    WHEN 'sheet' THEN (
      SELECT s.workspace_id FROM api.sheet_instances s WHERE s.id = p_object_id
    )
    WHEN 'project' THEN (
      SELECT p.workspace_id FROM api.projects p WHERE p.id = p_object_id
    )
    WHEN 'notebook_template' THEN (
      SELECT t.workspace_id FROM api.notebook_templates t WHERE t.id = p_object_id
    )
  END;

  -- Unknown objects and objects whose workspace the caller can no longer see
  -- are ignored rather than erroring: view tracking is best-effort.
  IF v_workspace_id IS NULL OR NOT "api"."is_workspace_member"(v_workspace_id) THEN
    RETURN NULL;
  END IF;

  INSERT INTO "api"."recently_viewed"
    (workspace_id, user_id, object_kind, object_id, viewed_at)
  VALUES
    (v_workspace_id, v_user_id, p_object_kind, p_object_id, now())
  ON CONFLICT (user_id, object_kind, object_id)
  DO UPDATE SET viewed_at = EXCLUDED.viewed_at, workspace_id = EXCLUDED.workspace_id
  RETURNING viewed_at INTO v_viewed_at;

  -- Keep the table thin: retain only the most recent 200 objects per user.
  DELETE FROM "api"."recently_viewed"
  WHERE user_id = v_user_id
    AND (object_kind, object_id) NOT IN (
      SELECT object_kind, object_id
      FROM api.recently_viewed
      WHERE user_id = v_user_id
      ORDER BY viewed_at DESC, object_kind ASC, object_id ASC
      LIMIT 200
    );

  RETURN v_viewed_at;
END;
$$;
--> statement-breakpoint
ALTER FUNCTION api.record_recent_view(p_object_kind text, p_object_id uuid) OWNER TO migrator;
--> statement-breakpoint
CREATE FUNCTION api.record_sample_label_print(p_record_id uuid, p_expected_metadata_version bigint, p_note text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
  v_record api.records;
  v_event api.sample_events;
BEGIN
  SELECT * INTO v_record FROM api.records WHERE id = p_record_id FOR UPDATE;
  IF v_record.id IS NULL OR v_record.kind <> 'sample' THEN
    RAISE EXCEPTION 'Unknown sample' USING ERRCODE = '22023';
  END IF;
  IF NOT api.is_workspace_writer(v_record.workspace_id) THEN
    RAISE EXCEPTION 'workspace writer required' USING ERRCODE = '42501';
  END IF;
  IF p_expected_metadata_version IS NOT NULL
     AND v_record.metadata_version IS DISTINCT FROM p_expected_metadata_version THEN
    RAISE EXCEPTION 'the sample changed since you loaded it' USING ERRCODE = '40001';
  END IF;

  INSERT INTO api.sample_events(
    workspace_id, record_id, operation, actor_user_id, notes
  ) VALUES (
    v_record.workspace_id, p_record_id, 'print', api.current_user_id(),
    nullif(btrim(coalesce(p_note, '')), '')
  ) RETURNING * INTO v_event;

  PERFORM internal.emit_change_event(
    v_record.workspace_id, 'sample_event', v_event.id, 'create',
    v_record.id, v_record.project_id,
    jsonb_build_object('operation', 'print', 'note', v_event.notes)
  );

  RETURN to_jsonb(v_event);
END $$;
