    id uuid DEFAULT gen_random_uuid() NOT NULL,
    workspace_id uuid NOT NULL,
    subscription_id uuid NOT NULL,
    change_event_id uuid NOT NULL,
    event_type text NOT NULL,
    payload jsonb NOT NULL,
    body text NOT NULL,
    signature text NOT NULL,
    attempt integer DEFAULT 0 NOT NULL,
    status text DEFAULT 'pending'::text NOT NULL,
    response_status integer,
    response_body text,
    error_code text,
    error_message text,
    replay_of_delivery_id uuid,
    next_attempt_at timestamp with time zone,
    delivered_at timestamp with time zone,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT chk_webhook_deliveries_attempt CHECK ((attempt >= 0)),
    CONSTRAINT chk_webhook_deliveries_response CHECK (((response_status IS NULL) OR ((response_status >= 100) AND (response_status < 600)))),
    CONSTRAINT chk_webhook_deliveries_status CHECK ((status = ANY (ARRAY['pending'::text, 'delivered'::text, 'failed'::text, 'retrying'::text, 'dead_letter'::text])))
);
