    CONSTRAINT chk_connectors_parser CHECK (((parser_id IS NULL) OR (((length(btrim(parser_id)) >= 1) AND (length(btrim(parser_id)) <= 100)) AND (connector_type = 'instrument'::text)))),
    CONSTRAINT chk_connectors_status CHECK ((status = ANY (ARRAY['active'::text, 'paused'::text, 'archived'::text]))),
    CONSTRAINT chk_connectors_type CHECK ((connector_type = ANY (ARRAY['instrument'::text, 'storage'::text, 'webhook'::text, 'database'::text, 'custom'::text])))
