CREATE FUNCTION api.register_replacement_lot(p_reagent_record_id uuid, p_lot text, p_expiry date, p_quantity numeric, p_unit text DEFAULT NULL::text, p_reason text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
  v_source api.records;
  v_properties jsonb;
  v_unit text;
  v_replacement api.records;
BEGIN
  SELECT * INTO v_source FROM api.records
   WHERE id = p_reagent_record_id AND deleted_at IS NULL
   FOR UPDATE;
  IF v_source.id IS NULL THEN
    RAISE EXCEPTION 'record not found' USING ERRCODE = 'SB036';
  END IF;
  IF v_source.kind <> 'material' THEN
    RAISE EXCEPTION 'not a material' USING ERRCODE = '22023';
  END IF;
  IF NOT api.is_workspace_writer(v_source.workspace_id) THEN
    RAISE EXCEPTION 'capability required: workspace write' USING ERRCODE = '42501';
  END IF;
  PERFORM internal.assert_object_access('record', p_reagent_record_id, 'edit');

  IF p_lot IS NULL OR length(btrim(p_lot)) NOT BETWEEN 1 AND 64 THEN
    RAISE EXCEPTION 'a lot number is required' USING ERRCODE = '22023';
  END IF;
  IF p_lot IS NOT DISTINCT FROM v_source.properties->>'lot' THEN
    RAISE EXCEPTION 'the replacement needs a new lot number' USING ERRCODE = '22023';
  END IF;
  IF p_expiry IS NULL THEN
    RAISE EXCEPTION 'an expiry date is required' USING ERRCODE = '22023';
  END IF;
  IF p_quantity IS NULL OR p_quantity <= 0 THEN
    RAISE EXCEPTION 'a positive quantity is required' USING ERRCODE = '22023';
  END IF;

  v_unit := nullif(btrim(coalesce(p_unit, '')), '');
  IF v_unit IS NULL THEN
    v_unit := v_source.properties->>'unit';
  END IF;

  -- Inherit the material identity, replace the lot facts.
  v_properties := (v_source.properties - 'lot' - 'expiry' - 'quantity' - 'unit')
    || jsonb_build_object(
         'lot', btrim(p_lot),
         'expiry', to_char(p_expiry, 'YYYY-MM-DD'),
         'quantity', p_quantity)
    || CASE WHEN v_unit IS NULL THEN '{}'::jsonb
            ELSE jsonb_build_object('unit', v_unit) END;

  v_replacement := api.create_record(
    v_source.project_id, 'material', v_source.title, 'available', v_source.tags,
    v_properties);

  INSERT INTO api.record_links
    (source_record_id, target_record_id, target_kind, target_identifier, link_type,
     link_metadata, created_by_user_id)
  VALUES (v_source.id, v_replacement.id, 'material', v_replacement.identifier, 'material',
          jsonb_build_object(
            'relation', 'replacement',
            'reason', nullif(btrim(coalesce(p_reason, '')), '')),
          api.current_user_id())
  ON CONFLICT (source_record_id, target_identifier, link_type) DO NOTHING;

  RETURN jsonb_build_object(
    'id', v_replacement.id,
    'identifier', v_replacement.identifier,
    'title', v_replacement.title,
    'projectId', v_replacement.project_id,
    'metadataVersion', v_replacement.metadata_version,
    'lot', btrim(p_lot),
    'expiry', to_char(p_expiry, 'YYYY-MM-DD'),
    'quantity', p_quantity,
    'unit', v_unit);
END $$;
--> statement-breakpoint
ALTER FUNCTION api.register_replacement_lot(p_reagent_record_id uuid, p_lot text, p_expiry date, p_quantity numeric, p_unit text, p_reason text) OWNER TO migrator;
--> statement-breakpoint
CREATE FUNCTION api.register_samples(p_project_id uuid, p_samples jsonb) RETURNS SETOF api.records
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
DECLARE
  v_item jsonb;
  v_row "api"."records";
  v_props jsonb;
BEGIN
  IF p_samples IS NULL OR jsonb_typeof(p_samples) <> 'array' THEN
    RAISE EXCEPTION 'samples must be a JSON array' USING ERRCODE = '22023';
  END IF;
  IF jsonb_array_length(p_samples) = 0 THEN
    RAISE EXCEPTION 'at least one sample is required' USING ERRCODE = '22023';
  END IF;
  IF jsonb_array_length(p_samples) > 500 THEN
    RAISE EXCEPTION 'at most 500 samples can be registered at once' USING ERRCODE = '22023';
  END IF;

  FOR v_item IN SELECT value FROM jsonb_array_elements(p_samples) LOOP
    IF jsonb_typeof(v_item) <> 'object' THEN
      RAISE EXCEPTION 'each sample must be an object' USING ERRCODE = '22023';
    END IF;
    IF nullif(btrim(coalesce(v_item ->> 'title', '')), '') IS NULL THEN
      RAISE EXCEPTION 'each sample needs a name' USING ERRCODE = '22023';
    END IF;
    v_props := jsonb_strip_nulls(jsonb_build_object(
      'sampleType', nullif(btrim(coalesce(v_item ->> 'sampleType', '')), ''),
      'quantity', CASE WHEN nullif(btrim(coalesce(v_item ->> 'quantity', '')), '') IS NULL
                       THEN NULL ELSE (v_item ->> 'quantity')::numeric END,
      'quantityUnit', nullif(btrim(coalesce(v_item ->> 'quantityUnit', '')), ''),
      'storageLocation', nullif(btrim(coalesce(v_item ->> 'storageLocation', '')), ''),
      'barcode', nullif(btrim(coalesce(v_item ->> 'barcode', '')), '')
    ));
    SELECT * INTO v_row FROM "api"."create_model_record"(
      p_project_id => p_project_id,
      p_kind => 'sample',
      p_title => btrim(v_item ->> 'title'),
      p_status => 'available',
      p_tags => ARRAY[]::text[],
      p_properties => v_props,
      p_custom_fields => '{}'::jsonb
    );
    RETURN NEXT v_row;
  END LOOP;
  RETURN;
END;
$$;
--> statement-breakpoint
ALTER FUNCTION api.register_samples(p_project_id uuid, p_samples jsonb) OWNER TO migrator;
--> statement-breakpoint
COMMENT ON FUNCTION api.register_samples(p_project_id uuid, p_samples jsonb) IS 'Phase 6: register up to 500 samples in one transaction through api.create_model_record. Each item: title (required), sampleType, quantity, quantityUnit, storageLocation, barcode. Returns the new records in input order.';
