CREATE FUNCTION api.replace_dataset_schema_version_fields(p_schema_version_id uuid, p_fields jsonb, p_expected_revision bigint DEFAULT NULL::bigint) RETURNS api.dataset_schema_versions
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
  version api.dataset_schema_versions;
  workspace uuid;
BEGIN
  SELECT * INTO version FROM api.dataset_schema_versions WHERE id = p_schema_version_id FOR UPDATE;
  IF version.id IS NULL THEN
    RAISE EXCEPTION 'Dataset Schema Version not found' USING ERRCODE = '42501';
  END IF;
  SELECT s.workspace_id INTO workspace
    FROM api.dataset_schema_definitions s WHERE s.id = version.schema_id;
  PERFORM api.require_capability(workspace, 'schema.edit');
  IF version.lifecycle <> 'draft' THEN
    RAISE EXCEPTION 'only draft Dataset Schema Versions may be updated' USING ERRCODE = 'SB072';
  END IF;
  IF EXISTS(SELECT 1 FROM api.approval_requests r WHERE r.workspace_id=workspace
    AND r.object_kind='dataset_schema_version' AND r.object_id=version.id AND r.state='pending') THEN
    RAISE EXCEPTION 'draft is locked while approval is pending' USING ERRCODE = 'SB085';
  END IF;
  IF p_expected_revision IS NOT NULL AND p_expected_revision IS DISTINCT FROM version.revision THEN
    RAISE EXCEPTION 'stale Dataset Schema Version revision' USING ERRCODE = 'SB001';
  END IF;
  PERFORM internal.replace_dataset_schema_version_fields(version.id, p_fields);
  UPDATE api.dataset_schema_versions
     SET revision = revision + 1, updated_at = now()
   WHERE id = version.id
  RETURNING * INTO version;
  RETURN version;
END $$;
--> statement-breakpoint
ALTER FUNCTION api.replace_dataset_schema_version_fields(p_schema_version_id uuid, p_fields jsonb, p_expected_revision bigint) OWNER TO migrator;
--> statement-breakpoint
CREATE FUNCTION api.replace_record_model_version_definition(p_version_id uuid, p_expected_revision bigint, p_definition jsonb, p_reason text) RETURNS api.record_model_versions
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
  v_version "api"."record_model_versions";
  v_model "api"."record_models";
  v_row "api"."record_model_versions";
  v_field jsonb;
  v_present uuid[] := '{}';
BEGIN
  SELECT * INTO v_version FROM api.record_model_versions WHERE id = p_version_id FOR UPDATE;
  IF v_version.id IS NULL OR v_version.workspace_id IS DISTINCT FROM api.current_workspace_id() THEN
    RAISE EXCEPTION 'Record Model version not found' USING ERRCODE = '42501';
  END IF;
  PERFORM api.require_capability(v_version.workspace_id, 'schema.edit');
  IF v_version.lifecycle <> 'draft' THEN
    RAISE EXCEPTION 'only draft Record Model versions may be updated' USING ERRCODE = 'SB072';
  END IF;
  IF EXISTS (SELECT 1 FROM api.approval_requests r
    WHERE r.object_kind = 'record_model_version' AND r.object_id = v_version.id AND r.state = 'pending') THEN
    RAISE EXCEPTION 'draft is locked while approval is pending' USING ERRCODE = 'SB085';
  END IF;
  IF p_expected_revision IS NULL OR p_expected_revision IS DISTINCT FROM v_version.revision THEN
    RAISE EXCEPTION 'stale Record Model version revision' USING ERRCODE = 'SB001';
  END IF;
  IF p_definition IS NULL OR jsonb_typeof(p_definition) <> 'object'
    OR jsonb_typeof(coalesce(p_definition->'fields', 'null'::jsonb)) <> 'array' THEN
    RAISE EXCEPTION 'definition must be an object with a fields array' USING ERRCODE = '22023';
  END IF;
  IF p_reason IS NULL OR length(btrim(p_reason)) NOT BETWEEN 1 AND 2000 THEN
    RAISE EXCEPTION 'a change reason is required' USING ERRCODE = '22023';
  END IF;
  UPDATE api.record_model_versions
     SET definition = p_definition, revision = v_version.revision + 1,
         reason = btrim(p_reason), updated_by_user_id = api.current_user_id(), updated_at = now()
   WHERE id = v_version.id
  RETURNING * INTO v_row;
  RETURN v_row;
END $$;
