CREATE FUNCTION api.replay_webhook_deliveries(p_workspace_id uuid, p_subscription_id uuid DEFAULT NULL::uuid, p_since timestamp with time zone DEFAULT NULL::timestamp with time zone, p_until timestamp with time zone DEFAULT NULL::timestamp with time zone, p_status text DEFAULT 'dead_letter'::text, p_limit integer DEFAULT 50) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
  v_count bigint;
  v_ids uuid[];
  v_limit integer := LEAST(GREATEST(COALESCE(p_limit, 50), 1), 500);
BEGIN
  IF api.current_workspace_id() IS DISTINCT FROM p_workspace_id THEN
    RAISE EXCEPTION 'wrong workspace' USING ERRCODE = 'SB033';
  END IF;
  PERFORM api.require_capability(p_workspace_id, 'integrations.manage');
  IF NOT api.has_write_actor() THEN
    RAISE EXCEPTION 'workspace member required' USING ERRCODE = '42501';
  END IF;
  IF p_status NOT IN ('dead_letter', 'failed', 'delivered') THEN
    RAISE EXCEPTION 'replay status must be dead_letter, failed, or delivered' USING ERRCODE = 'SB034';
  END IF;
  IF p_subscription_id IS NOT NULL THEN
    PERFORM 1 FROM api.webhook_subscriptions
     WHERE id = p_subscription_id AND workspace_id = p_workspace_id;
    IF NOT FOUND THEN
      RAISE EXCEPTION 'webhook subscription not found' USING ERRCODE = 'SB036';
    END IF;
  END IF;

  WITH candidates AS (
    SELECT d.*
      FROM api.webhook_deliveries d
     WHERE d.workspace_id = p_workspace_id
       AND (p_subscription_id IS NULL OR d.subscription_id = p_subscription_id)
       AND d.status = p_status
       AND d.replay_of_delivery_id IS NULL
       AND (p_since IS NULL OR d.created_at >= p_since)
       AND (p_until IS NULL OR d.created_at <= p_until)
       AND NOT EXISTS (
         SELECT 1 FROM api.webhook_deliveries r
          WHERE r.replay_of_delivery_id = d.id
            AND r.status IN ('pending', 'retrying')
       )
     ORDER BY d.created_at ASC
     LIMIT v_limit
  ),
  inserted AS (
    INSERT INTO api.webhook_deliveries(
      workspace_id, subscription_id, change_event_id, event_type,
      payload, body, signature, attempt, status, next_attempt_at,
      replay_of_delivery_id
    )
    SELECT p_workspace_id, c.subscription_id, c.change_event_id,
      c.event_type, c.payload, c.body, c.signature,
      0, 'pending', now(), c.id
    FROM candidates c
    RETURNING id, replay_of_delivery_id
  )
  SELECT count(*), coalesce(array_agg(i.replay_of_delivery_id), ARRAY[]::uuid[])
    INTO v_count, v_ids
    FROM inserted i;

  PERFORM internal.emit_change_event(
    p_workspace_id, 'webhook_delivery', gen_random_uuid(), 'create', NULL, NULL,
    jsonb_build_object(
      'bulk_replay', true,
      'replayed_count', v_count,
      'status', p_status,
      'subscription_id', p_subscription_id,
      'since', p_since,
      'until', p_until
    )
  );
  RETURN jsonb_build_object('replayed_count', v_count, 'delivery_ids', to_jsonb(v_ids));
END $$;
--> statement-breakpoint
ALTER FUNCTION api.replay_webhook_deliveries(p_workspace_id uuid, p_subscription_id uuid, p_since timestamp with time zone, p_until timestamp with time zone, p_status text, p_limit integer) OWNER TO migrator;
--> statement-breakpoint
CREATE FUNCTION api.replay_webhook_delivery(p_workspace_id uuid, p_delivery_id uuid) RETURNS api.webhook_deliveries
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
  v_original api.webhook_deliveries;
  v_new api.webhook_deliveries;
BEGIN
  IF api.current_workspace_id() IS DISTINCT FROM p_workspace_id THEN
    RAISE EXCEPTION 'wrong workspace' USING ERRCODE = 'SB033';
  END IF;
  PERFORM api.require_capability(p_workspace_id, 'integrations.manage');
  IF NOT api.has_write_actor() THEN
    RAISE EXCEPTION 'workspace member required' USING ERRCODE = '42501';
  END IF;
  SELECT * INTO v_original FROM api.webhook_deliveries
   WHERE id = p_delivery_id AND workspace_id = p_workspace_id;
  IF v_original.id IS NULL THEN
    RAISE EXCEPTION 'delivery not found' USING ERRCODE = 'SB036';
  END IF;
  -- Only terminal deliveries may be replayed. pending/retrying rows are
  -- owned by the retry sweep; replaying them would double-deliver.
  IF v_original.status NOT IN ('delivered', 'failed', 'dead_letter') THEN
    RAISE EXCEPTION 'only terminal deliveries can be replayed' USING ERRCODE = 'SB034';
  END IF;

  INSERT INTO api.webhook_deliveries(
    workspace_id, subscription_id, change_event_id, event_type,
    payload, body, signature, attempt, status, next_attempt_at,
    replay_of_delivery_id
  ) VALUES (
    p_workspace_id, v_original.subscription_id, v_original.change_event_id,
    v_original.event_type, v_original.payload, v_original.body, v_original.signature,
    0, 'pending', now(), p_delivery_id
  ) RETURNING * INTO v_new;
  PERFORM internal.emit_change_event(
    p_workspace_id, 'webhook_delivery', v_new.id, 'create', NULL, NULL,
    jsonb_build_object(
      'replay_of', p_delivery_id,
      'subscription_id', v_new.subscription_id,
      'event_type', v_new.event_type
    )
  );
  RETURN v_new;
END $$;
--> statement-breakpoint
ALTER FUNCTION api.replay_webhook_delivery(p_workspace_id uuid, p_delivery_id uuid) OWNER TO migrator;
--> statement-breakpoint
CREATE FUNCTION api.reply_to_comment(p_parent_id uuid, p_body text, p_mentions text[] DEFAULT ARRAY[]::text[]) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
  v_claims jsonb;
  v_workspace uuid;
  v_actor text;
  v_parent api.comments;
  v_record_project uuid;
  v_id uuid;
  v_mentions text[];
  v_row api.comments;
BEGIN
 IF p_parent_id IS NOT NULL THEN PERFORM internal.assert_object_access('comment',p_parent_id,'view'); END IF;
  v_claims := api.claim_probe();
  IF v_claims IS NULL THEN
    RAISE EXCEPTION 'record denied' USING ERRCODE = '42501';
  END IF;
  v_workspace := nullif(v_claims->>'workspace_id', '')::uuid;
  v_actor := nullif(v_claims->>'sub', '');
  IF v_workspace IS NULL OR v_actor IS NULL
     OR (v_claims->>'role') <> 'authenticated'
     OR NOT api.is_workspace_writer(v_workspace) THEN
    RAISE EXCEPTION 'record denied' USING ERRCODE = '42501';
  END IF;
  IF p_body IS NULL OR length(p_body) NOT BETWEEN 1 AND 8000 THEN
    RAISE EXCEPTION 'comment body is required' USING ERRCODE = '22023';
  END IF;

  SELECT * INTO v_parent FROM api.comments
  WHERE id = p_parent_id AND workspace_id = v_workspace;
  IF v_parent.id IS NULL THEN
    RAISE EXCEPTION 'record denied' USING ERRCODE = '42501';
  END IF;

  SELECT project_id INTO v_record_project FROM api.records
  WHERE id = v_parent.record_id; IF v_parent.revision_id IS NULL THEN SELECT project_id INTO v_record_project FROM api.sheet_instances WHERE id=v_parent.sheet_instance_id; END IF;

  v_mentions := internal.normalise_mentions(v_workspace, p_mentions);
  v_id := gen_random_uuid();
  INSERT INTO api.comments (
    id, workspace_id, revision_id, record_id, sheet_instance_id, root_id, parent_id,
    target_kind, target, body, mentions, state, author_user_id
  ) VALUES (
    v_id, v_workspace, v_parent.revision_id, v_parent.record_id, v_parent.sheet_instance_id,
    v_parent.root_id, v_parent.id, v_parent.target_kind, v_parent.target,
    p_body, v_mentions, 'open', v_actor
  ) RETURNING * INTO v_row;

  PERFORM internal.emit_change_event(
    v_workspace, 'comment', v_row.id, 'create', v_parent.record_id,
    v_record_project,
    jsonb_build_object(
      'sheetInstanceId', v_row.sheet_instance_id, 'commentId', v_row.id, 'revisionId', v_parent.revision_id,
      'threadRootId', v_row.root_id, 'parentId', v_parent.id,
      'targetKind', v_parent.target_kind, 'state', 'open'
    )
  );

  RETURN jsonb_build_object(
    'sheetInstanceId', v_row.sheet_instance_id, 'id', v_row.id, 'revisionId', v_parent.revision_id, 'rootId', v_row.root_id,
    'parentId', v_parent.id, 'targetKind', v_parent.target_kind,
    'target', v_row.target, 'body', v_row.body, 'mentions', v_row.mentions,
    'state', v_row.state, 'authorUserId', v_row.author_user_id,
    'createdAt', v_row.created_at
  );
END;
$$;
--> statement-breakpoint
ALTER FUNCTION api.reply_to_comment(p_parent_id uuid, p_body text, p_mentions text[]) OWNER TO migrator;
--> statement-breakpoint
CREATE FUNCTION api.report_agent_workflow_usage(p_workflow_id uuid, p_expected_revision bigint, p_tokens bigint, p_cost_microusd bigint) RETURNS api.agent_workflows
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
  v_workflow api.agent_workflows;
  v_step api.agent_workflow_steps;
  v_proposal api.agent_operation_proposals;
BEGIN
  IF p_tokens < 0 OR p_cost_microusd < 0
     OR (p_tokens = 0 AND p_cost_microusd = 0) THEN
    RAISE EXCEPTION 'usage increments must be positive' USING ERRCODE = '22023';
  END IF;
  SELECT * INTO v_workflow
    FROM api.agent_workflows
   WHERE id = p_workflow_id
     AND workspace_id = api.current_workspace_id()
   FOR UPDATE;
  IF v_workflow.id IS NULL THEN
    RAISE EXCEPTION 'workflow not found' USING ERRCODE = '42501';
  END IF;
  PERFORM internal.require_agent_workflow_control(v_workflow);
  IF v_workflow.revision <> p_expected_revision
     OR v_workflow.status IN ('succeeded','cancelled','budget_exhausted') THEN
    RAISE EXCEPTION 'workflow cannot accept usage at this revision'
      USING ERRCODE = 'SB001';
  END IF;

  UPDATE api.agent_workflows
     SET used_tokens = used_tokens + p_tokens,
         used_cost_microusd = used_cost_microusd + p_cost_microusd,
         revision = revision + 1, updated_at = now()
   WHERE id = v_workflow.id
   RETURNING * INTO v_workflow;
  PERFORM internal.agent_workflow_append_event(
    v_workflow,'usage_reported',
    jsonb_build_object(
      'tokens',p_tokens,'costMicrousd',p_cost_microusd,
      'usedTokens',v_workflow.used_tokens,
      'usedCostMicrousd',v_workflow.used_cost_microusd
    )
  );

  IF v_workflow.used_tokens > v_workflow.max_tokens
     OR v_workflow.used_cost_microusd > v_workflow.max_cost_microusd THEN
    SELECT * INTO v_step
      FROM api.agent_workflow_steps
     WHERE workflow_id = v_workflow.id
       AND position = v_workflow.current_step
     FOR UPDATE;
    SELECT * INTO v_proposal
      FROM api.agent_operation_proposals
     WHERE id = v_step.proposal_id
     FOR UPDATE;
    IF v_proposal.status IN ('pending','approved') THEN
      UPDATE api.agent_operation_proposals
         SET status = 'cancelled', revision = revision + 1, updated_at = now(),
             error_code = 'budget_exhausted',
             error_message = 'Parent workflow exceeded its token or cost budget.'
       WHERE id = v_proposal.id
       RETURNING * INTO v_proposal;
      PERFORM internal.agent_operation_append_event(
        v_proposal,'cancelled',
        jsonb_build_object('reason','parent workflow budget exhausted')
      );
      UPDATE api.agent_workflow_steps
         SET status = 'cancelled', updated_at = now()
       WHERE id = v_step.id;
    END IF;
    UPDATE api.agent_workflows
       SET status = 'budget_exhausted', revision = revision + 1,
           updated_at = now()
     WHERE id = v_workflow.id
     RETURNING * INTO v_workflow;
    PERFORM internal.agent_workflow_append_event(
      v_workflow,'budget_exhausted',
      jsonb_build_object(
        'usedTokens',v_workflow.used_tokens,'maxTokens',v_workflow.max_tokens,
        'usedCostMicrousd',v_workflow.used_cost_microusd,
        'maxCostMicrousd',v_workflow.max_cost_microusd
      )
    );
  END IF;
  RETURN v_workflow;
END;
$$;
--> statement-breakpoint
