CREATE FUNCTION api.request_repeat(p_source_record_id uuid, p_dataset_id uuid, p_scheduled_at timestamp with time zone DEFAULT NULL::timestamp with time zone, p_planned_row_count integer DEFAULT 1, p_source_row_id uuid DEFAULT NULL::uuid, p_source_field_id uuid DEFAULT NULL::uuid, p_title text DEFAULT NULL::text, p_properties jsonb DEFAULT '{}'::jsonb, p_planned_key text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
  v_workspace uuid := api.current_workspace_id();
  v_source api.records;
  v_dataset api.datasets;
  v_sample api.records;
  v_row api.dataset_rows;
  v_identifier text;
  v_project uuid;
  v_title text;
  v_metadata jsonb;
  v_row_key text;
  v_row_ids uuid[] := '{}';
  i integer;
BEGIN
 IF p_source_record_id IS NOT NULL THEN PERFORM internal.assert_object_access('record',p_source_record_id,'edit'); END IF;
 IF p_dataset_id IS NOT NULL THEN PERFORM internal.assert_object_access('dataset',p_dataset_id,'edit'); END IF;
  IF v_workspace IS NULL THEN
    RAISE EXCEPTION 'repeat denied' USING ERRCODE = '42501';
  END IF;
  IF NOT (api.is_workspace_writer(v_workspace) AND api.has_write_actor()) THEN
    RAISE EXCEPTION 'repeat denied' USING ERRCODE = '42501';
  END IF;

  IF p_planned_row_count IS NULL
     OR p_planned_row_count < 1 OR p_planned_row_count > 96 THEN
    RAISE EXCEPTION 'planned row count must be between 1 and 96'
      USING ERRCODE = '22023';
  END IF;
  IF p_planned_key IS NOT NULL THEN
    p_planned_key := btrim(p_planned_key);
    IF length(p_planned_key) NOT BETWEEN 1 AND 200 THEN
      RAISE EXCEPTION 'planned key must be 1 to 200 characters'
        USING ERRCODE = '22023';
    END IF;
  END IF;

  SELECT * INTO v_source FROM api.records
    WHERE id = p_source_record_id AND workspace_id = v_workspace
      AND kind = 'sample'
    FOR UPDATE;
  IF v_source.id IS NULL THEN
    RAISE EXCEPTION 'source sample not found' USING ERRCODE = '42501';
  END IF;
  IF v_source.archived_at IS NOT NULL OR v_source.deleted_at IS NOT NULL THEN
    RAISE EXCEPTION 'cannot repeat an archived sample' USING ERRCODE = 'SB004';
  END IF;

  SELECT * INTO v_dataset FROM api.datasets
    WHERE id = p_dataset_id AND workspace_id = v_workspace
      AND api.is_workspace_writer(workspace_id) AND api.has_write_actor()
    FOR UPDATE;
  IF v_dataset.id IS NULL THEN
    RAISE EXCEPTION 'Dataset denied' USING ERRCODE = '42501';
  END IF;
  IF v_dataset.lifecycle <> 'active' THEN
    RAISE EXCEPTION 'cannot request a repeat into an archived Dataset'
      USING ERRCODE = '22023';
  END IF;

  IF p_source_row_id IS NOT NULL AND NOT EXISTS (
    SELECT 1 FROM api.dataset_rows r
    WHERE r.id = p_source_row_id AND r.dataset_id = v_dataset.id
  ) THEN
    RAISE EXCEPTION 'source measurement row not found in Dataset'
      USING ERRCODE = '22023';
  END IF;
  IF p_source_field_id IS NOT NULL AND NOT EXISTS (
    SELECT 1 FROM api.dataset_schema_version_fields f
    WHERE f.schema_version_id = v_dataset.schema_version_id
      AND f.field_id = p_source_field_id AND f.lifecycle = 'active'
  ) THEN
    RAISE EXCEPTION 'source measurement field not found in Dataset schema'
      USING ERRCODE = '22023';
  END IF;

  -- Existing lineage model: an outgoing 'sample' link from the source sample.
  -- Metadata identifies the exact measurement + schedule this repeat answers.
  v_metadata := jsonb_build_object(
    'origin', 'request_repeat',
    'sourceDatasetId', v_dataset.id,
    'sourceRowId', p_source_row_id,
    'sourceFieldId', p_source_field_id,
    'scheduledAt', p_scheduled_at
  );

  IF EXISTS (
    SELECT 1 FROM api.record_links l
    WHERE l.source_record_id = v_source.id
      AND l.link_type = 'sample'
      AND l.link_metadata->>'origin' = 'request_repeat'
      AND l.link_metadata->>'sourceDatasetId' = v_dataset.id::text
      AND l.link_metadata->>'sourceRowId'
        IS NOT DISTINCT FROM p_source_row_id::text
      AND l.link_metadata->>'sourceFieldId'
        IS NOT DISTINCT FROM p_source_field_id::text
      AND (l.link_metadata->>'scheduledAt')::timestamptz
        IS NOT DISTINCT FROM p_scheduled_at
  ) THEN
    RAISE EXCEPTION 'a repeat has already been requested for this measurement and schedule'
      USING ERRCODE = 'SB075';
  END IF;

  v_project := coalesce(v_source.project_id, v_dataset.primary_project_id);
  v_identifier := api.next_record_identifier(v_workspace, 'sample');
  v_title := nullif(btrim(coalesce(p_title, '')), '');
  IF v_title IS NULL THEN
    v_title := coalesce(v_source.title, v_source.identifier) || ' repeat';
  END IF;

  -- Derived dilution sample: the canonical sample row. `properties` carries the
  -- caller's quantity/unit/location (validated by the existing sample property
  -- guard); provenance lives on the lineage link instead.
  INSERT INTO api.records
    (workspace_id, project_id, kind, identifier, title, status, properties,
     created_by_user_id)
  VALUES
    (v_workspace, v_project, 'sample', v_identifier, v_title, 'available',
     coalesce(p_properties, '{}'::jsonb), api.current_user_id())
  RETURNING * INTO v_sample;

  INSERT INTO api.sample_events
    (workspace_id, record_id, operation, actor_user_id, notes)
  VALUES
    (v_workspace, v_sample.id, 'create', api.current_user_id(),
     'Repeat requested from ' || v_source.identifier);

  INSERT INTO api.record_links
    (source_record_id, target_record_id, target_kind, target_identifier,
     link_type, link_metadata, created_by_user_id)
  VALUES
    (v_source.id, v_sample.id, 'sample', v_sample.identifier, 'sample',
     v_metadata, api.current_user_id());

  -- Planned rows reuse the canonical planned-row RPC (status 'planned',
  -- scheduled time, no values). Any failure rolls the whole repeat back.
  FOR i IN 1..p_planned_row_count LOOP
    v_row_key := CASE
      WHEN p_planned_key IS NULL THEN 'repeat:' || v_sample.id::text || ':' || i
      WHEN p_planned_row_count = 1 THEN p_planned_key
      ELSE p_planned_key || ':' || i
    END;
    SELECT * INTO v_row FROM api.plan_dataset_row(v_dataset.id, p_scheduled_at, v_row_key);
    v_row_ids := array_append(v_row_ids, v_row.id);
  END LOOP;

  UPDATE api.record_links SET link_metadata = link_metadata || jsonb_build_object('plannedRowIds', to_jsonb(v_row_ids))
      WHERE source_record_id = v_source.id AND target_record_id = v_sample.id
        AND link_metadata->>'origin' = 'request_repeat';
  RETURN jsonb_build_object(
    'datasetId', v_dataset.id,
    'plannedRows', (SELECT jsonb_agg(jsonb_build_object('id', r.id, 'plannedKey', r.planned_key) ORDER BY r.planned_key)
      FROM api.dataset_rows r WHERE r.id = ANY(v_row_ids)),
    'sample', to_jsonb(v_sample),
    'plannedRowIds', to_jsonb(v_row_ids),
    'idempotent', false
  );
END;
$$;
--> statement-breakpoint
ALTER FUNCTION api.request_repeat(p_source_record_id uuid, p_dataset_id uuid, p_scheduled_at timestamp with time zone, p_planned_row_count integer, p_source_row_id uuid, p_source_field_id uuid, p_title text, p_properties jsonb, p_planned_key text) OWNER TO migrator;
--> statement-breakpoint
COMMENT ON FUNCTION api.request_repeat(p_source_record_id uuid, p_dataset_id uuid, p_scheduled_at timestamp with time zone, p_planned_row_count integer, p_source_row_id uuid, p_source_field_id uuid, p_title text, p_properties jsonb, p_planned_key text) IS 'DSET-01.4: atomic request repeat — derive a dilution sample (LAB-01) and plan Dataset rows (DSET-01.3), linked to the source measurement. Optional p_planned_key keys the rows for later import matching.';
--> statement-breakpoint
CREATE FUNCTION api.request_signature_identity_verification() RETURNS api.user_signature_certifications
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE w uuid:=api.current_workspace_id(); a text:=api.current_user_id();
  s text:=api.claim_probe()->>'session_id'; c api.user_signature_certifications;
BEGIN
  -- Own-row operation: membership is checked directly, never a writer shortcut.
  IF api.claim_probe()->>'role' IS DISTINCT FROM 'authenticated'
    OR NOT EXISTS (SELECT 1 FROM api.workspace_memberships
      WHERE workspace_id=w AND user_id=a AND suspended_at IS NULL)
    OR NOT EXISTS (SELECT 1 FROM internal.session
      WHERE id=s AND "userId"=a AND "expiresAt">clock_timestamp()) THEN
    RAISE EXCEPTION 'valid workspace session required' USING ERRCODE='42501';
  END IF;
  INSERT INTO api.user_signature_certifications(workspace_id,user_id,credential_session_id,revoked_at)
    VALUES(w,a,s,clock_timestamp())
    ON CONFLICT(workspace_id,user_id) DO UPDATE SET credential_session_id=s,
      identity_verified_by=NULL,identity_verified_at=NULL,verified_email=NULL,
      credential_authorization_id=NULL,credential_authorization_consumed_at=NULL,
      revoked_at=clock_timestamp()
    RETURNING * INTO c;
  UPDATE internal.signature_grants SET consumed_at=clock_timestamp()
    WHERE user_id=a AND consumed_at IS NULL;
  INSERT INTO internal.signature_authentication_events(workspace_id,user_id,session_id,event)
    VALUES(w,a,s,'identity-verification-requested');
  RETURN c;
END $$;
--> statement-breakpoint
ALTER FUNCTION api.request_signature_identity_verification() OWNER TO migrator;
--> statement-breakpoint
CREATE FUNCTION api.request_signature_witness(p_submission_id uuid, p_witness_user_id text, p_expected_revision_digest text, p_due_at timestamp with time zone DEFAULT NULL::timestamp with time zone) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE s api.review_submissions; r api.revisions; q api.signature_witness_requests;
  w uuid:=api.current_workspace_id(); a text:=api.current_user_id(); session_id text:=api.claim_probe()->>'session_id';
BEGIN
  IF api.claim_probe()->>'role' IS DISTINCT FROM 'authenticated' OR NOT api.is_workspace_writer(w)
    OR NOT EXISTS(SELECT 1 FROM internal.session WHERE id=session_id AND "userId"=a AND "expiresAt">clock_timestamp()) THEN
    RAISE EXCEPTION 'human witness request denied' USING ERRCODE='42501';
  END IF;
  SELECT * INTO s FROM api.review_submissions WHERE id=p_submission_id AND workspace_id=w FOR UPDATE;
  IF s.id IS NULL OR s.state NOT IN('submitted','approved') OR (a<>s.submitted_by_user_id AND NOT(a=ANY(s.assigned_reviewer_user_ids))) THEN
    RAISE EXCEPTION 'only author or assigned reviewer may request a witness' USING ERRCODE='42501';
  END IF;
  SELECT * INTO r FROM api.revisions WHERE id=s.revision_id AND workspace_id=w;
  IF r.superseded_by_revision_id IS NOT NULL OR p_expected_revision_digest IS DISTINCT FROM r.integrity_digest THEN
    RAISE EXCEPTION 'witness request digest mismatch' USING ERRCODE='SB001';
  END IF;
  IF p_witness_user_id=s.submitted_by_user_id OR p_witness_user_id=a OR NOT EXISTS(
    SELECT 1 FROM api.workspace_memberships m WHERE m.workspace_id=w AND m.user_id=p_witness_user_id
      AND m.suspended_at IS NULL AND m.role IN('owner','admin','member','editor','reviewer','steward')) THEN
    RAISE EXCEPTION 'witness must be another permitted human member' USING ERRCODE='42501';
  END IF;
  IF NOT internal.can_access_object('record',s.record_id,'view') OR NOT (SELECT permissions.can_view FROM api.records record CROSS JOIN LATERAL internal.project_permissions_for(record.project_id,p_witness_user_id) permissions WHERE record.id=s.record_id) THEN RAISE EXCEPTION 'Witness requires current project View' USING ERRCODE='42501'; END IF;
  IF NOT internal.record_readable_by(s.record_id,p_witness_user_id) THEN
    RAISE EXCEPTION 'witness cannot read this record' USING ERRCODE='42501';
  END IF;
  SELECT * INTO q FROM api.signature_witness_requests WHERE submission_id=s.id AND witness_user_id=p_witness_user_id;
  IF q.id IS NOT NULL THEN
    IF q.revision_digest IS DISTINCT FROM p_expected_revision_digest OR q.due_at IS DISTINCT FROM p_due_at THEN
      RAISE EXCEPTION 'witness request already has different arguments' USING ERRCODE='23505';
    END IF;
  ELSE
    INSERT INTO api.signature_witness_requests(workspace_id,submission_id,revision_digest,witness_user_id,
      requested_by_user_id,requested_session_id,due_at) VALUES(w,s.id,r.integrity_digest,p_witness_user_id,a,session_id,p_due_at) RETURNING * INTO q;
    PERFORM internal.emit_change_event(w,'review_submission',s.id,'update',s.record_id,
      (SELECT project_id FROM api.records WHERE id=s.record_id),jsonb_build_object('action','witness-requested','requestId',q.id,'witnessUserId',p_witness_user_id,'submissionId',s.id,'revisionId',r.id));
  END IF;
  RETURN jsonb_build_object('id',q.id,'submissionId',s.id,'revisionId',r.id,'witnessUserId',p_witness_user_id);
END $$;
--> statement-breakpoint
