CREATE FUNCTION api.resolve_analysis_view_sources(p_view_id uuid, p_expected_version integer, p_resolution text, p_justification text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
  v api.analysis_views;
  stale_count integer;
  removed_count integer;
  cited_count integer;
  moved jsonb;
  revisions jsonb;
BEGIN
  SELECT * INTO v FROM api.analysis_views
    WHERE id = p_view_id AND workspace_id = api.current_workspace_id();
  -- The same authority the `analysis_views_update` policy requires: workspace
  -- membership is implied by writer, so this narrows nothing for a legitimate
  -- owner and closes the demoted-viewer path.
  IF v.id IS NULL OR NOT api.is_workspace_writer(v.workspace_id) THEN
    RAISE EXCEPTION 'Analysis denied' USING ERRCODE = '42501';
  END IF;
  IF v.owner_user_id IS DISTINCT FROM api.current_user_id() THEN
    RAISE EXCEPTION 'Only the owner can resolve an analysis source' USING ERRCODE = '42501';
  END IF;
  IF p_resolution NOT IN ('keep', 'update') THEN
    RAISE EXCEPTION 'resolution must be keep or update' USING ERRCODE = '23514';
  END IF;
  -- Optimistic concurrency: the caller resolves the version it read, exactly
  -- as the version bump trigger requires for any other update.
  IF v.version <> p_expected_version THEN
    RAISE EXCEPTION 'analysis view version conflict: expected %, found %', p_expected_version, v.version
      USING ERRCODE = 'SB077';
  END IF;

  SELECT count(*) FILTER (WHERE s.status = 'stale'),
         count(*) FILTER (WHERE s.status = 'removed')
    INTO stale_count, removed_count
    FROM internal.analysis_view_source_rows(v) s;

  IF stale_count + removed_count = 0 THEN
    RAISE EXCEPTION 'analysis sources are current; nothing to resolve' USING ERRCODE = 'SB079';
  END IF;

  SELECT count(*) INTO cited_count
    FROM internal.analysis_view_citations(v.workspace_id, v.display_id);

  IF p_resolution = 'keep' THEN
    PERFORM internal.emit_change_event(
      v.workspace_id, 'analysis_view', v.id, 'resolve', NULL, NULL,
      jsonb_build_object(
        'resolution', 'keep',
        'viewVersion', v.version,
        'pinnedRevisions', v.source_revisions,
        'staleSourceIds', coalesce((
          SELECT jsonb_agg(s.dataset_id ORDER BY s.pin_position)
            FROM internal.analysis_view_source_rows(v) s
           WHERE s.status <> 'current'), '[]'::jsonb),
        'citedByCount', cited_count,
        'justification', left(p_justification, 500)));
    RETURN jsonb_build_object(
      'resolution', 'keep',
      'state', 'stale',
      'acknowledged', true,
      'version', v.version,
      'revisions', v.source_revisions);
  END IF;

  -- update
  IF removed_count > 0 THEN
    RAISE EXCEPTION 'a source dataset is no longer available; keep the pinned version or re-author the analysis'
      USING ERRCODE = 'SB079';
  END IF;
  IF cited_count > 0 THEN
    RAISE EXCEPTION 'analysis is cited by % record(s); a cited analysis keeps the sources it cited', cited_count
      USING ERRCODE = 'SB078';
  END IF;

  SELECT coalesce(jsonb_agg(jsonb_build_object(
           'datasetId', s.dataset_id,
           'schemaVersionNumber', s.live_schema_version_number,
           'revision', s.live_revision) ORDER BY s.pin_position), '[]'::jsonb),
         jsonb_agg(s.dataset_id ORDER BY s.pin_position)
    INTO revisions, moved
    FROM internal.analysis_view_source_rows(v) s;

  UPDATE api.analysis_views SET source_revisions = revisions
   WHERE id = v.id
  RETURNING * INTO v;

  PERFORM internal.emit_change_event(
    v.workspace_id, 'analysis_view', v.id, 'resolve', NULL, NULL,
    jsonb_build_object(
      'resolution', 'update',
      'viewVersion', v.version,
      'pinnedRevisions', v.source_revisions,
      'updatedSourceIds', moved,
      'citedByCount', 0,
      'justification', left(p_justification, 500)));

  RETURN jsonb_build_object(
    'resolution', 'update',
    'state', 'current',
    'acknowledged', false,
    'version', v.version,
    'revisions', v.source_revisions);
END $$;
--> statement-breakpoint
ALTER FUNCTION api.resolve_analysis_view_sources(p_view_id uuid, p_expected_version integer, p_resolution text, p_justification text) OWNER TO migrator;
--> statement-breakpoint
CREATE FUNCTION api.resolve_cell_conflict(p_conflict_id uuid, p_value jsonb, p_reason text) RETURNS api.sheet_cell_conflicts
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
  v_row api.sheet_cell_conflicts;
  v_actor text := api.current_user_id();
BEGIN
  SELECT * INTO v_row FROM api.sheet_cell_conflicts WHERE id = p_conflict_id FOR UPDATE;
  IF v_row.id IS NULL OR v_row.workspace_id IS DISTINCT FROM api.current_workspace_id() THEN
    RAISE EXCEPTION 'Unknown conflict' USING ERRCODE = '22023';
  END IF;
  PERFORM internal.assert_object_access('instance', v_row.sheet_instance_id, 'edit');
  IF v_row.state <> 'open' THEN
    RAISE EXCEPTION 'This conflict is already resolved' USING ERRCODE = '22023';
  END IF;
  IF p_reason IS NULL OR length(btrim(p_reason)) NOT BETWEEN 1 AND 2000 THEN
    RAISE EXCEPTION 'a reason is required to resolve a conflict' USING ERRCODE = '22023';
  END IF;

  UPDATE api.sheet_cell_conflicts
     SET state = 'resolved',
         resolved_value = p_value,
         resolved_by_user_id = v_actor,
         resolved_at = now(),
         reason = btrim(p_reason),
         updated_at = now()
   WHERE id = v_row.id
  RETURNING * INTO v_row;

  -- The decision belongs in the record's history, attributed to the person who made it.
  PERFORM internal.emit_change_event(
    v_row.workspace_id,
    'scientific_row',
    v_row.sheet_instance_id,
    'resolve',
    NULL,
    NULL,
    jsonb_build_object(
      'conflict', 'cell',
      'conflictId', v_row.id,
      'fieldId', v_row.field_id,
      'rowKey', v_row.row_key,
      'resolvedBy', v_actor,
      'reason', v_row.reason
    )
  );

  RETURN v_row;
END $$;
--> statement-breakpoint
ALTER FUNCTION api.resolve_cell_conflict(p_conflict_id uuid, p_value jsonb, p_reason text) OWNER TO migrator;
--> statement-breakpoint
CREATE FUNCTION api.resolve_comment_thread(p_comment_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
  v_claims jsonb;
  v_workspace uuid;
  v_actor text;
  v_root api.comments;
  v_record_project uuid;
BEGIN
 IF p_comment_id IS NOT NULL THEN PERFORM internal.assert_object_access('comment',p_comment_id,'view'); END IF;
  v_claims := api.claim_probe();
  IF v_claims IS NULL THEN
    RAISE EXCEPTION 'record denied' USING ERRCODE = '42501';
  END IF;
  v_workspace := nullif(v_claims->>'workspace_id', '')::uuid;
  v_actor := nullif(v_claims->>'sub', '');
  IF v_workspace IS NULL OR v_actor IS NULL
     OR (v_claims->>'role') <> 'authenticated'
     OR NOT api.is_workspace_writer(v_workspace) THEN
    RAISE EXCEPTION 'record denied' USING ERRCODE = '42501';
  END IF;

  SELECT * INTO v_root FROM api.comments
  WHERE id = p_comment_id AND workspace_id = v_workspace;
  IF v_root.id IS NULL THEN
    RAISE EXCEPTION 'record denied' USING ERRCODE = '42501';
  END IF;
  -- Resolve at the thread root.
  IF v_root.root_id <> v_root.id THEN
    SELECT * INTO v_root FROM api.comments
    WHERE id = v_root.root_id AND workspace_id = v_workspace;
  END IF;
  IF v_root.state = 'resolved' THEN
    RAISE EXCEPTION 'thread is already resolved' USING ERRCODE = 'SB003';
  END IF;

  SELECT project_id INTO v_record_project FROM api.records
  WHERE id = v_root.record_id; IF v_root.revision_id IS NULL THEN SELECT project_id INTO v_record_project FROM api.sheet_instances WHERE id=v_root.sheet_instance_id; END IF;

  UPDATE api.comments
  SET state = 'resolved', resolved_at = clock_timestamp(),
      resolved_by_user_id = v_actor, updated_at = clock_timestamp()
  WHERE id = v_root.id;

  PERFORM internal.emit_change_event(
    v_workspace, 'comment', v_root.id, 'resolve', v_root.record_id,
    v_record_project,
    jsonb_build_object(
      'sheetInstanceId', v_root.sheet_instance_id, 'commentId', v_root.id, 'revisionId', v_root.revision_id,
      'threadRootId', v_root.id, 'resolvedByUserId', v_actor,
      'state', 'resolved'
    )
  );

  RETURN jsonb_build_object(
    'id', v_root.id, 'state', 'resolved', 'resolvedByUserId', v_actor,
    'resolvedAt', clock_timestamp()
  );
END;
$$;
--> statement-breakpoint
ALTER FUNCTION api.resolve_comment_thread(p_comment_id uuid) OWNER TO migrator;
--> statement-breakpoint
CREATE FUNCTION api.resolve_sheet_instance_row_identity(p_instance_id uuid, p_expected_revision bigint) RETURNS api.sheet_instances
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE result api.sheet_instances; config jsonb; identity jsonb; column_item jsonb; actor text:=api.current_user_id();
BEGIN
 IF p_instance_id IS NOT NULL THEN PERFORM internal.assert_object_access('instance',p_instance_id,'edit'); END IF;
  SELECT * INTO result FROM api.sheet_instances WHERE id=p_instance_id FOR UPDATE;
  IF result.id IS NULL OR NOT api.is_workspace_writer(result.workspace_id) THEN RAISE EXCEPTION 'workspace member required' USING ERRCODE='42501'; END IF;
  IF result.lifecycle<>'active' OR result.revision<>p_expected_revision THEN RAISE EXCEPTION 'Sheet Instance revision conflict or archive' USING ERRCODE='SB073'; END IF;
  IF result.source_definition_version_id IS NULL THEN RAISE EXCEPTION 'row identity requires a pinned Definition Version' USING ERRCODE='SB073'; END IF;
  SELECT configuration INTO config FROM api.sheet_definition_versions WHERE id=result.source_definition_version_id;
  identity:=config->'rowIdentity';
  SELECT value INTO column_item FROM jsonb_array_elements(config->'columns') WHERE value->>'id'=identity->'columnIds'->>0;
  identity:=identity||jsonb_build_object('formatVersion',1,'logicalTypes',(SELECT jsonb_agg(column_value->'field'->>'logicalType' ORDER BY ids.ordinality) FROM jsonb_array_elements(identity->'columnIds') WITH ORDINALITY ids JOIN LATERAL jsonb_array_elements(config->'columns') column_value ON column_value->>'id'=ids.value#>>'{}'),'sourceBindingId',CASE WHEN identity->>'kind'='source' THEN column_item->'source'->>'bindingId' ELSE NULL END,'sourceFieldId',CASE WHEN identity->>'kind'='source' THEN column_item->'source'->>'sourceFieldId' ELSE NULL END);
  IF result.state ? 'resolvedRowIdentity' AND result.state->'resolvedRowIdentity'<>identity THEN RAISE EXCEPTION 'resolved row identity is immutable' USING ERRCODE='SB073'; END IF;
  IF result.state->'resolvedRowIdentity'=identity THEN RETURN result; END IF;
  PERFORM set_config('sheetbase.sheet_instance_write','rpc-v1',true);
  UPDATE api.sheet_instances SET state=jsonb_set(result.state,'{resolvedRowIdentity}',identity,true),revision=revision+1,updated_at=now(),updated_by_user_id=actor WHERE id=result.id RETURNING * INTO result;
  RETURN result;
END $$;
--> statement-breakpoint
ALTER FUNCTION api.resolve_sheet_instance_row_identity(p_instance_id uuid, p_expected_revision bigint) OWNER TO migrator;
--> statement-breakpoint
CREATE FUNCTION api.restore_dataset(p_dataset_id uuid, p_expected_revision bigint) RETURNS api.datasets
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE dataset api.datasets;
BEGIN
 IF p_dataset_id IS NOT NULL THEN PERFORM internal.assert_object_access('dataset',p_dataset_id,'edit'); END IF;
  SELECT * INTO dataset FROM api.datasets WHERE id = p_dataset_id FOR UPDATE;
  IF dataset.id IS NULL OR NOT api.is_workspace_writer(dataset.workspace_id) THEN
    RAISE EXCEPTION 'workspace writer required' USING ERRCODE = '42501';
  END IF;
  IF dataset.revision <> p_expected_revision THEN RAISE EXCEPTION 'stale Dataset revision' USING ERRCODE = 'SB001'; END IF;
  IF dataset.lifecycle <> 'archived' THEN RAISE EXCEPTION 'Dataset is not archived' USING ERRCODE = 'SB072'; END IF;
  UPDATE api.datasets
     SET lifecycle = 'active', archived_at = NULL, revision = revision + 1, updated_at = now()
   WHERE id = dataset.id RETURNING * INTO dataset;
  RETURN dataset;
END $$;
