CREATE FUNCTION api.return_approval_request(p_request_id uuid, p_reason text) RETURNS api.approval_requests
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
  v_row api.approval_requests;
  v_actor text := api.current_user_id();
  v_role text;
BEGIN
  SELECT * INTO v_row FROM api.approval_requests WHERE id = p_request_id FOR UPDATE;
  IF v_row.id IS NULL
     OR v_actor IS NULL
     OR NOT api.is_workspace_writer(v_row.workspace_id) THEN
    RAISE EXCEPTION 'approval denied' USING ERRCODE = '42501';
  END IF;
  IF v_row.state <> 'pending' THEN
    RAISE EXCEPTION 'only pending approvals may be returned' USING ERRCODE = 'SB086';
  END IF;
  IF p_reason IS NULL OR length(btrim(p_reason)) NOT BETWEEN 1 AND 500 THEN
    RAISE EXCEPTION 'a return reason is required' USING ERRCODE = '22023';
  END IF;
  SELECT m.role INTO v_role
    FROM api.workspace_memberships m
   WHERE m.workspace_id = v_row.workspace_id
     AND m.user_id = v_actor
     AND m.suspended_at IS NULL;
  IF v_role IS NULL OR NOT (v_role = ANY(v_row.required_approver_roles)) THEN
    RAISE EXCEPTION 'approval denied' USING ERRCODE = '42501';
  END IF;
  IF v_row.require_independence
     AND v_row.submitted_by_user_id IS NOT DISTINCT FROM v_actor THEN
    RAISE EXCEPTION 'an approver cannot return their own submission' USING ERRCODE = '42501';
  END IF;
  INSERT INTO api.approval_request_decisions(
    request_id, workspace_id, user_id, role, decision, reason
  ) VALUES (
    v_row.id, v_row.workspace_id, v_actor, v_role, 'returned', btrim(p_reason)
  );
  UPDATE api.approval_requests
     SET state = 'returned',
         decision_reason = btrim(p_reason),
         decided_by_user_id = v_actor,
         decided_at = now(),
         updated_at = now()
   WHERE id = v_row.id
  RETURNING * INTO v_row;
  RETURN v_row;
END $$;
--> statement-breakpoint
ALTER FUNCTION api.return_approval_request(p_request_id uuid, p_reason text) OWNER TO migrator;
--> statement-breakpoint
CREATE FUNCTION api.return_revision_with_comments(p_submission_id uuid, p_note text, p_expected_state text, p_expected_revision_digest text, p_comments jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
  v_revision uuid;
  v_decision jsonb;
  v_comment jsonb;
  v_ids jsonb := '[]'::jsonb;
  v_created jsonb;
BEGIN
  IF p_comments IS NULL OR jsonb_typeof(p_comments) <> 'array' THEN
    RAISE EXCEPTION 'Comments must be an array' USING ERRCODE='22023';
  END IF;

  SELECT revision_id INTO v_revision
    FROM api.review_submissions
   WHERE id = p_submission_id;
  IF v_revision IS NULL THEN
    RAISE EXCEPTION 'Unknown review submission' USING ERRCODE='22023';
  END IF;

  -- The decision first: if the return is refused (stale digest, wrong state, no
  -- review permission), the drafts must not be published.
  v_decision := api.request_changes_on_review(
    p_submission_id,
    p_note,
    coalesce(p_expected_state, 'submitted'),
    p_expected_revision_digest
  );

  FOR v_comment IN SELECT * FROM jsonb_array_elements(p_comments) LOOP
    IF coalesce(v_comment->>'body', '') = '' THEN
      RAISE EXCEPTION 'A draft comment has no body' USING ERRCODE='22023';
    END IF;
    v_created := api.create_comment(
      v_revision,
      v_comment->>'targetKind',
      v_comment->'target',
      v_comment->>'body',
      coalesce(
        (SELECT array_agg(value) FROM jsonb_array_elements_text(v_comment->'mentions')),
        ARRAY[]::text[]
      )
    );
    v_ids := v_ids || to_jsonb(v_created->>'id');
  END LOOP;

  RETURN jsonb_build_object('decision', v_decision, 'commentIds', v_ids);
END $$;
--> statement-breakpoint
ALTER FUNCTION api.return_revision_with_comments(p_submission_id uuid, p_note text, p_expected_state text, p_expected_revision_digest text, p_comments jsonb) OWNER TO migrator;
--> statement-breakpoint
CREATE FUNCTION api.revision_drift(p_revision_id uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
  v_revision api.revisions;
  v_record api.records;
  v_signed_title text;
  v_datasets jsonb := '[]'::jsonb;
  v_instruments jsonb := '[]'::jsonb;
  v_captured jsonb;
  v_current api.instruments;
  v_cited jsonb;
  v_latest api.dataset_versions;
  v_comments integer := 0;
BEGIN
  SELECT * INTO v_revision FROM api.revisions WHERE id = p_revision_id;
  IF v_revision.id IS NULL THEN
    RAISE EXCEPTION 'revision not found' USING ERRCODE = 'SB036';
  END IF;
  PERFORM internal.assert_object_access('record', v_revision.record_id, 'view');

  SELECT * INTO v_record FROM api.records WHERE id = v_revision.record_id;
  v_signed_title := v_revision.metadata_snapshot->>'title';

  -- Cited dataset versions, each against the dataset's latest version.
  FOR v_cited IN
    SELECT DISTINCT value
      FROM api.revision_sheet_evidence e,
           jsonb_array_elements(coalesce(e.dataset_versions, '[]'::jsonb))
     WHERE e.revision_id = p_revision_id
  LOOP
    CONTINUE WHEN nullif(v_cited->>'id', '') IS NULL;
    SELECT * INTO v_latest FROM api.dataset_versions
     WHERE dataset_id = (v_cited->>'datasetId')::uuid
     ORDER BY source_dataset_revision DESC, created_at DESC
     LIMIT 1;
    v_datasets := v_datasets || jsonb_build_array(jsonb_build_object(
      'datasetId', v_cited->>'datasetId',
      'citedVersionId', v_cited->>'id',
      'citedLabel', v_cited->>'label',
      'citedDatasetRevision', v_cited->>'sourceDatasetRevision',
      'latestVersionId', v_latest.id,
      'latestLabel', v_latest.label,
      'latestDatasetRevision', v_latest.source_dataset_revision,
      'changed', v_latest.id IS DISTINCT FROM (v_cited->>'id')::uuid));
  END LOOP;

  -- LAB-06.4: instrument names as captured when the revision was frozen, each against the
  -- name the instrument has now. A revision signed before the capture existed has no
  -- instruments section and reports none rather than guessing.
  FOR v_captured IN
    SELECT value
      FROM jsonb_array_elements(
        coalesce(v_revision.canonical_snapshot->'instruments', '[]'::jsonb))
  LOOP
    CONTINUE WHEN nullif(v_captured->>'instrumentId', '') IS NULL;
    SELECT * INTO v_current FROM api.instruments
     WHERE id = (v_captured->>'instrumentId')::uuid;
    v_instruments := v_instruments || jsonb_build_array(jsonb_build_object(
      'instrumentId', v_captured->>'instrumentId',
      'displayId', v_captured->>'displayId',
      'signedName', v_captured->>'name',
      'currentName', v_current.name,
      'renamed', v_captured->>'name' IS DISTINCT FROM v_current.name));
  END LOOP;

  -- Comments added after the revision was frozen.
  SELECT count(*) INTO v_comments
    FROM api.comments c
   WHERE c.record_id = v_revision.record_id
     AND c.created_at > v_revision.created_at;

  RETURN jsonb_build_object(
    'revisionId', v_revision.id,
    'recordId', v_revision.record_id,
    'signedAt', v_revision.created_at,
    'record', jsonb_build_object(
      'recordId', v_record.id,
      'identifier', v_record.identifier,
      'signedTitle', v_signed_title,
      'currentTitle', v_record.title,
      'renamed', v_signed_title IS DISTINCT FROM v_record.title),
    'datasets', v_datasets,
    'instruments', v_instruments,
    'commentsAfterSigning', v_comments,
    'drifted', (v_signed_title IS DISTINCT FROM v_record.title)
               OR v_comments > 0
               OR EXISTS (
                    SELECT 1 FROM jsonb_array_elements(v_datasets) d
                     WHERE (d->>'changed')::boolean)
               OR EXISTS (
                    SELECT 1 FROM jsonb_array_elements(v_instruments) i
                     WHERE (i->>'renamed')::boolean));
END $$;
--> statement-breakpoint
ALTER FUNCTION api.revision_drift(p_revision_id uuid) OWNER TO migrator;
--> statement-breakpoint
CREATE FUNCTION api.revision_evidence_package(p_revision_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
  v_revision api.revisions;
  v_package jsonb;
  v_record_snapshot jsonb;
BEGIN
 IF p_revision_id IS NOT NULL THEN PERFORM internal.assert_object_access('revision',p_revision_id,'view'); END IF;
  SELECT * INTO v_revision FROM api.revisions WHERE id = p_revision_id;
  IF v_revision.id IS NULL THEN
    RAISE EXCEPTION 'revision not found' USING ERRCODE = '22023';
  END IF;
  IF v_revision.workspace_id IS NULL
     OR v_revision.workspace_id <> api.current_workspace_id()
     OR NOT api.is_workspace_member(v_revision.workspace_id) THEN
    RAISE EXCEPTION 'revision denied' USING ERRCODE = '42501';
  END IF;

  SELECT coalesce(v_revision.metadata_snapshot->'record', v_revision.metadata_snapshot)
    INTO v_record_snapshot;


  SELECT jsonb_build_object(
    'revision', jsonb_build_object(
      'id', v_revision.id,
      'recordId', v_revision.record_id,
      'workspaceId', v_revision.workspace_id,
      'reason', v_revision.reason,
      'structureVersion', v_revision.structure_version,
      'metadataVersion', v_revision.metadata_version,
      'integrityAlgorithm', v_revision.integrity_algorithm,
      'integrityDigest', v_revision.integrity_digest,
      'supersededByRevisionId', v_revision.superseded_by_revision_id,
      'createdAt', v_revision.created_at
    ),
    -- Convenience record metadata comes strictly from the submitted
    -- snapshot (metadata_snapshot = envelope->'record'), never from the
    -- live row, so the package cannot drift after submission.
    'record', CASE
      WHEN v_record_snapshot ? 'identifier' THEN jsonb_build_object(
        'identifier', v_record_snapshot->'identifier',
        'title', v_record_snapshot->'title',
        'kind', v_record_snapshot->'kind',
        'status', v_record_snapshot->'status'
      )
      ELSE NULL
    END,
    'metadataSnapshot', v_revision.metadata_snapshot,
    'blockSnapshot', v_revision.block_snapshot,
    'canonicalSnapshot', v_revision.canonical_snapshot,
    'sheetEvidence', (
      SELECT coalesce(jsonb_agg(jsonb_build_object(
        'blockId', e.block_id,
        'instanceId', e.instance_id,
        'sourceDefinitionVersionId', e.source_definition_version_id,
        'instanceRevision', e.instance_revision,
        'instanceState', e.instance_state,
        'composedGrid', e.composed_grid,
        'datasetVersions', e.dataset_versions,
        'createdAt', e.created_at
      ) ORDER BY e.block_id), '[]'::jsonb)
      FROM api.revision_sheet_evidence e WHERE e.revision_id = v_revision.id
    ),
    'files', (
      SELECT coalesce(jsonb_agg(jsonb_build_object(
        'fileObjectId', f.file_object_id,
        'fileRecordId', f.file_record_id,
        'storageKey', f.storage_key,
        'storageBackend', f.storage_backend,
        'checksumAlgorithm', f.checksum_algorithm,
        'checksum', f.checksum,
        'byteSize', f.byte_size
      ) ORDER BY f.file_object_id), '[]'::jsonb)
      FROM internal.revision_file_objects f WHERE f.revision_id = v_revision.id
    ),
    'submission', (
      SELECT to_jsonb(s) FROM api.review_submissions s
      WHERE s.revision_id = v_revision.id AND s.workspace_id = v_revision.workspace_id
      LIMIT 1
    ),
    'decisions', (
      SELECT coalesce(jsonb_agg(to_jsonb(d) ORDER BY d.created_at), '[]'::jsonb)
      FROM api.review_decisions d
      WHERE d.revision_id = v_revision.id AND d.workspace_id = v_revision.workspace_id
    ),
    'checkResults', (
      SELECT coalesce(jsonb_agg(to_jsonb(c) ORDER BY c.run_at), '[]'::jsonb)
      FROM api.review_check_results c
      WHERE c.revision_id = v_revision.id AND c.workspace_id = v_revision.workspace_id
    ),
    'signatures', (
      SELECT coalesce(jsonb_agg(to_jsonb(sg) ORDER BY sg.signed_at), '[]'::jsonb)
      FROM api.signatures sg
      WHERE sg.revision_id = v_revision.id AND sg.workspace_id = v_revision.workspace_id
    ),
    'comments', (
      SELECT coalesce(jsonb_agg(to_jsonb(cm) ORDER BY cm.created_at), '[]'::jsonb)
      FROM api.comments cm
      WHERE cm.revision_id = v_revision.id AND cm.workspace_id = v_revision.workspace_id
    )
  ) INTO v_package;

  RETURN v_package;
END;
$$;
--> statement-breakpoint
ALTER FUNCTION api.revision_evidence_package(p_revision_id uuid) OWNER TO migrator;
--> statement-breakpoint
CREATE FUNCTION api.revoke_instrument_qualification(p_instrument_id uuid, p_user_id text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE v_instrument api.instruments;
BEGIN
  SELECT * INTO v_instrument FROM api.instruments
   WHERE id = p_instrument_id AND workspace_id = api.current_workspace_id();
  IF v_instrument.id IS NULL THEN
    RAISE EXCEPTION 'instrument not found in active workspace' USING ERRCODE = '42501';
  END IF;
  IF NOT api.has_capability(v_instrument.workspace_id, 'workspace.admin') THEN
    RAISE EXCEPTION 'admin access required' USING ERRCODE = '42501';
  END IF;
  DELETE FROM api.instrument_qualifications
   WHERE instrument_id = v_instrument.id AND user_id = p_user_id;
  PERFORM internal.emit_change_event(v_instrument.workspace_id, 'instrument', v_instrument.id, 'update',
    NULL, NULL,
    jsonb_build_object('effect', 'qualification_revoked', 'userId', p_user_id));
END $$;
--> statement-breakpoint
ALTER FUNCTION api.revoke_instrument_qualification(p_instrument_id uuid, p_user_id text) OWNER TO migrator;
