CREATE FUNCTION api.run_audit_verification(p_workspace_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
  v_chain record;
  v_signed record;
  v_result jsonb;
  v_sequence bigint;
BEGIN
  -- User-facing callers must be an admin of the workspace they verify. The
  -- scheduled runner has no claim probe at all and is accepted only because it
  -- connects as this function's owner (the migrator role that applied it).
  IF api.claim_probe() IS NOT NULL THEN
    IF p_workspace_id IS DISTINCT FROM api.current_workspace_id()
       OR NOT api.has_capability(p_workspace_id, 'workspace.admin') THEN
      RAISE EXCEPTION 'admin access required' USING ERRCODE = '42501';
    END IF;
  ELSIF NOT pg_has_role(
      current_user,
      (SELECT proowner FROM pg_proc
        WHERE oid = 'api.run_audit_verification(uuid)'::regprocedure),
      'USAGE') THEN
    RAISE EXCEPTION 'admin access required' USING ERRCODE = '42501';
  END IF;

  SELECT * INTO v_chain FROM internal.verify_audit_chain(p_workspace_id);
  SELECT * INTO v_signed FROM internal.verify_signed_revisions(p_workspace_id);

  v_result := jsonb_build_object(
    'ok', v_chain.ok AND v_signed.ok,
    'verifiedAt', now(),
    'chain', jsonb_build_object(
      'ok', v_chain.ok,
      'entriesChecked', v_chain.checked,
      'firstBadSequence', v_chain.first_bad_sequence,
      'firstBadId', v_chain.first_bad_id),
    'signedRevisions', jsonb_build_object(
      'ok', v_signed.ok,
      'checked', v_signed.checked,
      'firstBadSignatureId', v_signed.first_bad_signature_id,
      'firstBadRevisionId', v_signed.first_bad_revision_id));

  -- A System entry: no actor, subject 'system', the result as the payload. It is
  -- written directly because internal.emit_change_event is a no-op without a
  -- claim probe, and the job deliberately runs without a user session.
  INSERT INTO api.workspace_change_seq(workspace_id,last_seq) VALUES(p_workspace_id,1)
    ON CONFLICT(workspace_id) DO UPDATE
      SET last_seq=api.workspace_change_seq.last_seq+1, updated_at=now()
    RETURNING last_seq INTO v_sequence;
  INSERT INTO api.change_events(id,workspace_id,sequence,entity_type,entity_uuid,operation,payload)
    VALUES(gen_random_uuid(), p_workspace_id, v_sequence, 'system', gen_random_uuid(), 'create', v_result);

  RETURN v_result;
END $$;
--> statement-breakpoint
ALTER FUNCTION api.run_audit_verification(p_workspace_id uuid) OWNER TO migrator;
--> statement-breakpoint
CREATE FUNCTION api.run_revision_checks(p_revision_id uuid, p_check_definition_key text, p_check_definition_version integer, p_confirmed boolean, p_idempotency_key text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $_$
DECLARE
  claimed_workspace uuid;
  actor text;
  session_id text;
  actor_role text;
  revision_row api.revisions;
  definition_row internal.review_check_definitions;
  check_item jsonb;
  item_result jsonb;
  results jsonb := '[]';
  envelope jsonb;
  sheets jsonb;
  overall_status text := 'pass';
  pass_count int := 0;
  blocking_failures int := 0;
  warning_failures int := 0;
  info_failures int := 0;
  input_digest text;
  definition_digest text;
  existing_result api.review_check_results;
  run_at timestamptz := clock_timestamp();
  result_row api.review_check_results;
BEGIN
 IF p_revision_id IS NOT NULL THEN PERFORM internal.assert_object_access('revision',p_revision_id,'view'); END IF;
  BEGIN
    claimed_workspace := nullif (api.claim_probe () ->> 'workspace_id', '')::uuid;
    actor := nullif (api.claim_probe () ->> 'sub', '');
    session_id := nullif (api.claim_probe () ->> 'session_id', '');
    actor_role := nullif (api.claim_probe () ->> 'role', '');
  EXCEPTION
    WHEN OTHERS THEN
      RAISE EXCEPTION 'record denied' USING ERRCODE = '42501';
  END;
  IF claimed_workspace IS NULL OR actor IS NULL OR session_id IS NULL OR actor_role <> 'authenticated' OR p_confirmed IS DISTINCT FROM TRUE OR NOT api.is_workspace_member (claimed_workspace) THEN
    RAISE EXCEPTION 'record denied' USING ERRCODE = '42501';
    END IF;
    IF p_check_definition_key IS NULL OR p_check_definition_key !~ '^[a-z0-9][a-z0-9_-]{0,127}$' OR coalesce(p_check_definition_version, 0) < 1 THEN
      RAISE EXCEPTION 'versioned check definition is required' USING ERRCODE = '22023';
      END IF;
      IF p_idempotency_key IS NULL OR length(p_idempotency_key)
        NOT BETWEEN 1 AND 128 THEN
        RAISE EXCEPTION 'valid idempotency key is required' USING ERRCODE = '22023';
        END IF;
        SELECT
          *
        INTO
          definition_row
        FROM
          internal.review_check_definitions
        WHERE
          definition_key = p_check_definition_key
          AND version = p_check_definition_version;
          IF definition_row.definition_key IS NULL THEN
            RAISE EXCEPTION 'unknown check definition version' USING ERRCODE = '22023';
            END IF;
            SELECT
              *
            INTO
              revision_row
            FROM
              api.revisions
            WHERE
              id = p_revision_id
              AND workspace_id = claimed_workspace;
              IF revision_row.id IS NULL THEN
                RAISE EXCEPTION 'record denied' USING ERRCODE = '42501';
                END IF;
                -- Verify the signed envelope before supplementing it, including replay.
                input_digest := internal.revision_integrity_digest (revision_row.canonical_snapshot);
                IF input_digest <> revision_row.integrity_digest THEN
                  RAISE EXCEPTION 'revision integrity digest mismatch' USING ERRCODE = 'SB001';
                  END IF;
                  definition_digest := encode(sha256 (convert_to(definition_row.definition::text, 'UTF8')), 'hex');
                  SELECT
                    *
                  INTO
                    existing_result
                  FROM
                    api.review_check_results
                  WHERE
                    workspace_id = claimed_workspace
                    AND run_by_user_id = actor
                    AND idempotency_key = p_idempotency_key;
                    IF existing_result.id IS NOT NULL THEN
                      IF existing_result.revision_id <> p_revision_id OR existing_result.check_definition_key <> p_check_definition_key OR existing_result.check_definition_version <> p_check_definition_version THEN
                        RAISE EXCEPTION 'idempotency key was used for a different check run' USING ERRCODE = '23505';
                        END IF;
                        RETURN jsonb_build_object('id', existing_result.id, 'overallStatus', existing_result.overall_status, 'passCount', existing_result.pass_count, 'blockingFailureCount', existing_result.blocking_failure_count, 'warningFailureCount', existing_result.warning_failure_count, 'infoFailureCount', existing_result.info_failure_count, 'idempotent', TRUE);
                      END IF;
                      envelope := revision_row.canonical_snapshot;
                      SELECT
                        jsonb_agg(jsonb_build_object('blockId', e.block_id, 'instanceId', e.instance_id, 'instanceRevision', e.instance_revision, 'sourceDefinitionVersionId', e.source_definition_version_id, 'instanceState', e.instance_state, 'datasetBindings', e.dataset_versions, 'composedGrid', e.composed_grid)
                        ORDER BY e.block_id)
                      INTO
                        sheets
                      FROM
                        api.revision_sheet_evidence e
                      WHERE
                        e.revision_id = revision_row.id
                        AND e.workspace_id = claimed_workspace;
                        IF sheets IS NOT NULL THEN
                          envelope := envelope || jsonb_build_object('sheetEvidence', sheets);
                          END IF;
                          FOR check_item IN
                          SELECT
                            t.value
                          FROM
                            jsonb_array_elements(definition_row.definition -> 'checks')
  WITH ORDINALITY t (value, ord)
ORDER BY
  t.ord LOOP
    item_result := internal.evaluate_check_item (envelope, check_item);
    results := results || jsonb_build_array(item_result);
    IF item_result ->> 'status' = 'pass' THEN
      pass_count := pass_count + 1;
    ELSIF item_result ->> 'severity' = 'blocking' THEN
      blocking_failures := blocking_failures + 1;
    ELSIF item_result ->> 'severity' = 'warning' THEN
      warning_failures := warning_failures + 1;
    ELSIF item_result ->> 'severity' = 'informational' THEN
      info_failures := info_failures + 1;
      END IF;
    END LOOP;
    IF blocking_failures > 0 THEN
      overall_status := 'fail';
    ELSIF warning_failures > 0 THEN
      overall_status := 'warning';
      END IF;
    INSERT INTO api.review_check_results (workspace_id, record_id, revision_id, check_definition_key, check_definition_version, revision_integrity_digest, check_definition_digest, input_digest, overall_status, pass_count, blocking_failure_count, warning_failure_count, info_failure_count, results, run_by_user_id, run_session_id, run_role, run_at, idempotency_key, created_at)
      VALUES (claimed_workspace, revision_row.record_id, revision_row.id, p_check_definition_key, p_check_definition_version, revision_row.integrity_digest, definition_digest, input_digest, overall_status, pass_count, blocking_failures, warning_failures, info_failures, results, actor, session_id, actor_role, run_at, p_idempotency_key, run_at)
    RETURNING
      *
    INTO
      result_row;
      RETURN jsonb_build_object('id', result_row.id, 'revisionId', result_row.revision_id, 'checkDefinitionKey', result_row.check_definition_key, 'checkDefinitionVersion', result_row.check_definition_version, 'revisionIntegrityDigest', result_row.revision_integrity_digest, 'checkDefinitionDigest', result_row.check_definition_digest, 'inputDigest', result_row.input_digest, 'overallStatus', result_row.overall_status, 'passCount', result_row.pass_count, 'blockingFailureCount', result_row.blocking_failure_count, 'warningFailureCount', result_row.warning_failure_count, 'infoFailureCount', result_row.info_failure_count, 'results', result_row.results, 'runAt', result_row.run_at, 'idempotent', FALSE);
EXCEPTION
  WHEN unique_violation THEN
    SELECT
      *
    INTO
      existing_result
    FROM
      api.review_check_results
    WHERE
      workspace_id = claimed_workspace
      AND run_by_user_id = actor
      AND idempotency_key = p_idempotency_key;
      IF existing_result.id IS NOT NULL AND existing_result.revision_id = p_revision_id AND existing_result.check_definition_key = p_check_definition_key AND existing_result.check_definition_version = p_check_definition_version THEN
        RETURN jsonb_build_object('id', existing_result.id, 'overallStatus', existing_result.overall_status, 'passCount', existing_result.pass_count, 'blockingFailureCount', existing_result.blocking_failure_count, 'warningFailureCount', existing_result.warning_failure_count, 'infoFailureCount', existing_result.info_failure_count, 'idempotent', TRUE);
        END IF;
        RAISE;
END
$_$;
--> statement-breakpoint
ALTER FUNCTION api.run_revision_checks(p_revision_id uuid, p_check_definition_key text, p_check_definition_version integer, p_confirmed boolean, p_idempotency_key text) OWNER TO migrator;
--> statement-breakpoint
CREATE FUNCTION api.sample_measurement_provenance(p_sample_record_id uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $_$
DECLARE
  v_sample api.records;
  v_workspace uuid;
  v_result jsonb;
BEGIN
 IF p_sample_record_id IS NOT NULL THEN PERFORM internal.assert_object_access('record',p_sample_record_id,'view'); END IF;
  v_workspace := api.current_workspace_id();
  IF v_workspace IS NULL THEN
    RAISE EXCEPTION 'sample denied' USING ERRCODE = '42501';
  END IF;

  SELECT * INTO v_sample FROM api.records
    WHERE id = p_sample_record_id
      AND workspace_id = v_workspace
      AND api.is_workspace_member(workspace_id)
      AND kind = 'sample'
      AND deleted_at IS NULL;
  IF v_sample.id IS NULL THEN
    RAISE EXCEPTION 'sample denied' USING ERRCODE = '42501';
  END IF;

  WITH linked_rows AS (
    -- Direct reference: a reference-typed field whose Model target is sample
    -- and whose value is this sample record id.
    SELECT DISTINCT r.id AS row_id
      FROM api.dataset_rows r
      JOIN api.datasets d
        ON d.id = r.dataset_id
       AND d.workspace_id = v_sample.workspace_id
       AND d.lifecycle = 'active'
      JOIN api.dataset_schema_version_fields lf
        ON lf.schema_version_id = d.schema_version_id
       AND lf.lifecycle = 'active'
       AND lf.logical_type = 'reference'
       AND coalesce(
             lf.relationship->'target'->>'modelKey',
             lf.validation->>'targetModelKey'
           ) = 'sample'
      JOIN api.dataset_row_values lv
        ON lv.row_id = r.id
       AND lv.field_id = lf.field_id
       AND lv.reference_id = v_sample.id
    UNION
    -- Sample-keyed value: a text field named/labelled "sample" holding the
    -- sample's stable identifier.
    SELECT DISTINCT r.id
      FROM api.dataset_rows r
      JOIN api.datasets d
        ON d.id = r.dataset_id
       AND d.workspace_id = v_sample.workspace_id
       AND d.lifecycle = 'active'
      JOIN api.dataset_schema_version_fields lf
        ON lf.schema_version_id = d.schema_version_id
       AND lf.lifecycle = 'active'
       AND lf.logical_type = 'text'
       AND (lf.key ~* 'sample' OR lf.label ~* 'sample')
      JOIN api.dataset_row_values lv
        ON lv.row_id = r.id
       AND lv.field_id = lf.field_id
       AND btrim(lv.text_value) = btrim(v_sample.identifier)
  ),
  dataset_measures AS (
    SELECT
      'dataset:' || m.row_id::text || ':' || m.field_id::text || ':' ||
        m.ordinal::text AS id,
      m.label AS measurement,
      m.value_num AS value,
      m.value_num::text AS value_text,
      coalesce(m.quantity->>'symbol', m.quantity->>'storageUnit') AS unit,
      (SELECT mv.text_value
         FROM api.dataset_schema_version_fields mf
         JOIN api.dataset_row_values mv
           ON mv.row_id = m.row_id AND mv.field_id = mf.field_id
        WHERE mf.schema_version_id = m.schema_version_id
          AND mf.lifecycle = 'active'
          AND mf.logical_type = 'text'
          AND (mf.key ~* 'method' OR mf.label ~* 'method')
        ORDER BY mf.display_order
        LIMIT 1) AS method,
      coalesce(m.display_id, m.dataset_name) AS source,
      NULL::text AS result,
      coalesce(
        (SELECT tv.timestamp_value
           FROM api.dataset_schema_version_fields tf
           JOIN api.dataset_row_values tv
             ON tv.row_id = m.row_id AND tv.field_id = tf.field_id
          WHERE tf.schema_version_id = m.schema_version_id
            AND tf.lifecycle = 'active'
            AND tf.logical_type = 'timestamp'
            AND (
              tf.key ~* 'measur|time|date' OR tf.label ~* 'measur|time|date'
            )
          ORDER BY tf.display_order
          LIMIT 1),
        m.row_updated_at
      ) AS measured_at,
      jsonb_build_object(
        'kind', 'dataset',
        'datasetId', m.dataset_id,
        'datasetDisplayId', m.display_id,
        'datasetName', m.dataset_name,
        'rowId', m.row_id,
        'fieldId', m.field_id,
        'fieldKey', m.field_key,
        'sourceId', NULL,
        'runId', NULL,
        'runIdentifier', NULL,
        'instrumentId', NULL,
        'instrumentName', NULL
      ) AS provenance
    FROM (
      SELECT
        lr.row_id,
        r.updated_at AS row_updated_at,
        d.id AS dataset_id,
        d.display_id,
        d.name AS dataset_name,
        d.schema_version_id,
        f.field_id,
        f.key AS field_key,
        f.label,
        f.quantity,
        v.ordinal,
        coalesce(v.numeric_value, v.integer_value) AS value_num
      FROM linked_rows lr
      JOIN api.dataset_rows r ON r.id = lr.row_id
      JOIN api.datasets d
        ON d.id = r.dataset_id
       AND d.workspace_id = v_sample.workspace_id
      JOIN api.dataset_schema_version_fields f
        ON f.schema_version_id = d.schema_version_id
       AND f.lifecycle = 'active'
       AND f.logical_type IN ('integer', 'decimal')
      JOIN api.dataset_row_values v
        ON v.row_id = r.id
       AND v.field_id = f.field_id
       AND (v.numeric_value IS NOT NULL OR v.integer_value IS NOT NULL)
    ) m
  ),
  integration_measures AS (
    SELECT
      'integration:' || qc.id::text AS id,
      qc.check_name AS measurement,
      CASE
        WHEN jsonb_typeof(qc.detail->'value') = 'number'
          THEN (qc.detail->>'value')::numeric
        WHEN qc.detail->>'value'
          ~ '^-?[0-9]+(\.[0-9]+)?([eE][-+]?[0-9]+)?$'
          THEN (qc.detail->>'value')::numeric
        ELSE NULL
      END AS value,
      qc.detail->>'value' AS value_text,
      qc.detail->>'unit' AS unit,
      coalesce(ins.name, qc.detail->>'method') AS method,
      'QC · ' || ir.run_identifier AS source,
      qc.check_type AS result,
      qc.checked_at AS measured_at,
      jsonb_build_object(
        'kind', 'integration',
        'datasetId', NULL,
        'datasetDisplayId', NULL,
        'datasetName', NULL,
        'rowId', NULL,
        'fieldId', NULL,
        'fieldKey', NULL,
        'sourceId', qc.id,
        'runId', ir.id,
        'runIdentifier', ir.run_identifier,
        'instrumentId', ir.instrument_id,
        'instrumentName', ins.name
      ) AS provenance
    FROM api.instrument_run_links irl
    JOIN api.instrument_runs ir
      ON ir.id = irl.run_id
     AND ir.workspace_id = v_sample.workspace_id
    JOIN api.instrument_qc_checks qc
      ON qc.run_id = irl.run_id
     AND qc.workspace_id = v_sample.workspace_id
    LEFT JOIN api.instruments ins
      ON ins.id = ir.instrument_id
     AND ins.workspace_id = v_sample.workspace_id
    WHERE irl.linked_record_id = v_sample.id
      AND irl.link_type = 'sample'
      AND irl.workspace_id = v_sample.workspace_id
  ),
  all_measures AS (
    SELECT * FROM dataset_measures
    UNION ALL
    SELECT * FROM integration_measures
  )
  SELECT coalesce(
           jsonb_agg(
             jsonb_build_object(
               'id', am.id,
               'measurement', am.measurement,
               'value', am.value,
               'valueText', am.value_text,
               'unit', am.unit,
               'method', am.method,
               'source', am.source,
               'result', am.result,
               'measuredAt', am.measured_at,
               'provenance', am.provenance
             )
             ORDER BY am.measured_at DESC NULLS LAST, am.id
           ),
           '[]'::jsonb
         )
    INTO v_result
    FROM all_measures am;

  RETURN v_result;
END;
$_$;
--> statement-breakpoint
