CREATE FUNCTION api.sample_quantity_balances(p_record_id uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
  v_workspace uuid;
  v_sample api.records;
  v_current numeric;
  v_used numeric;
  v_reserved numeric;
  v_unit text;
BEGIN
 IF p_record_id IS NOT NULL THEN PERFORM internal.assert_object_access('record',p_record_id,'view'); END IF;
  v_workspace := "api"."current_workspace_id"();
  IF v_workspace IS NULL THEN
    RAISE EXCEPTION 'sample denied' USING ERRCODE = '42501';
  END IF;

  SELECT * INTO v_sample FROM api.records
   WHERE id = p_record_id
     AND workspace_id = v_workspace
     AND "api"."is_workspace_member"(workspace_id)
     AND kind = 'sample'
     AND deleted_at IS NULL;
  IF v_sample.id IS NULL THEN
    RAISE EXCEPTION 'sample denied' USING ERRCODE = '42501';
  END IF;

  v_current := COALESCE(NULLIF(v_sample.properties ->> 'quantity', '')::numeric, 0);
  v_unit := v_sample.properties ->> 'quantityUnit';
  v_used := COALESCE((
    SELECT SUM(-e.quantity_delta)
      FROM api.sample_events e
     WHERE e.record_id = p_record_id
       AND e.operation = 'consume'
  ), 0);
  v_reserved := COALESCE((
    SELECT SUM(r.quantity)
      FROM api.sample_reservations r
     WHERE r.sample_record_id = p_record_id
       AND r.state = 'active'
  ), 0);

  RETURN jsonb_build_object(
    'sampleRecordId', p_record_id,
    'unit', v_unit,
    'current', v_current,
    'used', v_used,
    'reserved', v_reserved,
    'free', v_current - v_reserved
  );
END;
$$;
--> statement-breakpoint
ALTER FUNCTION api.sample_quantity_balances(p_record_id uuid) OWNER TO migrator;
--> statement-breakpoint
COMMENT ON FUNCTION api.sample_quantity_balances(p_record_id uuid) IS 'LAB-01 step 2: read-only used/reserved/free balances for a sample. used is the cumulative consumed volume from api.sample_events; reserved is the sum of active api.sample_reservations; free is the current quantity minus reserved.';
--> statement-breakpoint
CREATE FUNCTION api.sample_release_check_status(p_record_id uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE
    SET search_path TO ''
    AS $$
DECLARE
  v_row "api"."records";
  v_eval jsonb;
BEGIN
  SELECT * INTO v_row FROM "api"."records" WHERE id = p_record_id;
  IF v_row.id IS NULL THEN
    RAISE EXCEPTION 'record not found in active workspace' USING ERRCODE = '42501';
  END IF;
  IF v_row.kind <> 'sample' THEN
    RAISE EXCEPTION 'record % is not a sample', p_record_id USING ERRCODE = 'SB009';
  END IF;

  v_eval := "internal"."evaluate_sample_release_rules"(
    "internal"."sample_release_rules"(v_row.workspace_id, v_row.properties ->> 'sampleType'),
    "api"."sample_measurement_provenance"(p_record_id)
  );
  RETURN v_eval || jsonb_build_object(
    'sampleId', v_row.id,
    'sampleType', v_row.properties ->> 'sampleType'
  );
END;
$$;
--> statement-breakpoint
ALTER FUNCTION api.sample_release_check_status(p_record_id uuid) OWNER TO migrator;
--> statement-breakpoint
COMMENT ON FUNCTION api.sample_release_check_status(p_record_id uuid) IS 'Phase 6: the release checks a sample has to pass, evaluated now against api.sample_measurement_provenance with the effective per-sample-type rule set. Read-only; api.release_sample enforces the same evaluation.';
