    CONSTRAINT chk_notification_preferences_event CHECK ((event_type = ANY (ARRAY['review_requested'::text, 'review_returned_or_signed'::text, 'signature_requested'::text, 'validation_error'::text, 'comment_or_mention'::text, 'instrument_booking'::text, 'material_expiring'::text, 'protocol_new_version'::text])))
);
