ALTER FUNCTION api.search(p_query text, p_project_id uuid, p_kind text, p_status text, p_owner_id text, p_date_from timestamp with time zone, p_date_to timestamp with time zone, p_limit integer, p_offset integer, p_result_type text, p_include_archived boolean) OWNER TO migrator;
--> statement-breakpoint
CREATE FUNCTION api.search_cells(p_query text, p_limit integer DEFAULT 20) RETURNS TABLE(dataset_id uuid, dataset_version_id uuid, dataset_name text, row_id uuid, field_label text, value_text text, snippet text, rank real)
    LANGUAGE sql STABLE
    SET search_path TO 'pg_catalog', 'api'
    AS $$
  SELECT cs.dataset_id, cs.dataset_version_id, d.name, cs.row_id, cs.field_label,
         cs.value_text,
         ts_headline('english', cs.value_text, plainto_tsquery('english', p_query)) AS snippet,
         ts_rank(cs.search_vector, plainto_tsquery('english', p_query)) AS rank
  FROM api.dataset_cell_search cs
  JOIN api.datasets d ON d.id = cs.dataset_id
  WHERE coalesce(btrim(p_query), '') <> ''
    AND cs.search_vector @@ plainto_tsquery('english', p_query)
  ORDER BY rank DESC, cs.value_text ASC
  LIMIT greatest(1, least(coalesce(p_limit, 20), 100))
$$;
