CREATE FUNCTION api.search_comments(p_query text, p_limit integer DEFAULT 20) RETURNS TABLE(comment_id uuid, record_id uuid, identifier text, target_kind text, anchor jsonb, body text, author_user_id text, created_at timestamp with time zone, rank real)
    LANGUAGE sql STABLE
