CREATE FUNCTION api.search_sheet_records(p_model_key text, p_query text DEFAULT ''::text, p_limit integer DEFAULT 25, p_include_archived boolean DEFAULT false) RETURNS jsonb
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
DECLARE
  v_kind text;
  v_limit integer;
  v_q text;
  v_pattern text;
BEGIN
  PERFORM api.require_capability(api.current_workspace_id(), 'record.link');
  IF p_model_key IS NULL OR length(btrim(p_model_key)) = 0 THEN
    RAISE EXCEPTION 'model key is required' USING ERRCODE = '22023';
  END IF;
  SELECT record_kind INTO v_kind
    FROM api.model_kinds
   WHERE key = p_model_key AND identity_table = 'api.records' AND record_kind IS NOT NULL;
  IF v_kind IS NULL THEN
    RAISE EXCEPTION 'model does not support Sheet Record search' USING ERRCODE = '22023';
  END IF;
  v_limit := least(greatest(coalesce(p_limit, 25), 1), 50);
  v_q := btrim(coalesce(p_query, ''));
  v_pattern := '%' || replace(replace(replace(v_q, '\', '\\'), '%', '\%'), '_', '\_') || '%';
  RETURN coalesce((
    SELECT jsonb_agg(row_to_json(s)::jsonb)
    FROM (
      SELECT
        r.id,
        r.kind,
        r.identifier,
        r.title,
        r.status,
        (r.archived_at IS NOT NULL) AS archived
      FROM api.records r
      WHERE r.kind = v_kind
        AND r.deleted_at IS NULL
        AND (p_include_archived OR r.archived_at IS NULL)
        AND (
          v_q = ''
          OR r.identifier ILIKE v_pattern ESCAPE '\'
          OR r.title ILIKE v_pattern ESCAPE '\'
          OR EXISTS (
            SELECT 1
            FROM jsonb_each_text(coalesce(r.custom_fields, '{}'::jsonb)) e
            WHERE e.value ILIKE v_pattern ESCAPE '\'
          )
        )
      ORDER BY
        CASE WHEN r.identifier = v_q THEN 0 ELSE 1 END,
        r.identifier
      LIMIT v_limit
    ) s
  ), '[]'::jsonb);
END
$$;
--> statement-breakpoint
ALTER FUNCTION api.search_sheet_records(p_model_key text, p_query text, p_limit integer, p_include_archived boolean) OWNER TO migrator;
--> statement-breakpoint
CREATE FUNCTION api.set_active_workspace(p_workspace_id uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
  v_user_id text;
BEGIN
  v_user_id := api.current_user_id();
  IF v_user_id IS NULL THEN
    RAISE EXCEPTION 'set_active_workspace requires an authenticated user' USING ERRCODE = '42501';
  END IF;
  IF p_workspace_id IS NULL OR NOT api.is_workspace_member(p_workspace_id) THEN
    RAISE EXCEPTION 'not a member of that workspace' USING ERRCODE = '42501';
  END IF;

  INSERT INTO api.user_preferences
    (user_id, active_workspace_id, created_at, updated_at)
  VALUES
    (v_user_id, p_workspace_id, now(), now())
  ON CONFLICT (user_id)
  DO UPDATE SET active_workspace_id = EXCLUDED.active_workspace_id, updated_at = now();
END;
$$;
