CREATE FUNCTION api.set_experiment_decision(p_record_id uuid, p_decision text, p_notes text DEFAULT NULL::text) RETURNS api.records
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
  v api.records;
BEGIN
 IF p_record_id IS NOT NULL THEN PERFORM internal.assert_object_access('record',p_record_id,'edit'); END IF;
  SELECT * INTO v FROM api.records
   WHERE id = p_record_id AND deleted_at IS NULL FOR UPDATE;
  IF v IS NULL THEN
    RAISE EXCEPTION 'record not found' USING ERRCODE = 'SB036';
  END IF;
  IF v.kind <> 'experiment' THEN
    RAISE EXCEPTION 'not an experiment' USING ERRCODE = '22023';
  END IF;
  IF api.current_workspace_id() IS DISTINCT FROM v.workspace_id
     OR NOT api.is_workspace_writer(v.workspace_id) THEN
    RAISE EXCEPTION 'capability required: workspace write' USING ERRCODE = '42501';
  END IF;
  IF p_decision IS NOT NULL
     AND p_decision NOT IN ('supported', 'refuted', 'inconclusive') THEN
    RAISE EXCEPTION 'invalid decision' USING ERRCODE = '22023';
  END IF;
  UPDATE api.records
     SET decision = p_decision,
         decision_notes = p_notes,
         metadata_version = metadata_version + 1,
         updated_at = now(),
         updated_by_user_id = api.current_user_id()
   WHERE id = p_record_id
   RETURNING * INTO v;
  RETURN v;
END $$;
--> statement-breakpoint
ALTER FUNCTION api.set_experiment_decision(p_record_id uuid, p_decision text, p_notes text) OWNER TO migrator;
--> statement-breakpoint
CREATE FUNCTION api.set_experiment_fields(p_record_id uuid, p_reviewer_user_id text DEFAULT NULL::text, p_planned_end date DEFAULT NULL::date) RETURNS api.records
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
  v api.records;
BEGIN
 IF p_record_id IS NOT NULL THEN PERFORM internal.assert_object_access('record',p_record_id,'edit'); END IF;
  SELECT * INTO v FROM api.records
   WHERE id = p_record_id AND deleted_at IS NULL FOR UPDATE;
  IF v IS NULL THEN
    RAISE EXCEPTION 'record not found' USING ERRCODE = 'SB036';
  END IF;
  IF v.kind <> 'experiment' THEN
    RAISE EXCEPTION 'not an experiment' USING ERRCODE = '22023';
  END IF;
  IF NOT api.is_workspace_writer(v.workspace_id) THEN
    RAISE EXCEPTION 'capability required: workspace write' USING ERRCODE = '42501';
  END IF;
  IF p_reviewer_user_id IS NOT NULL
     AND NOT EXISTS (
       SELECT 1 FROM api.workspace_memberships m
        WHERE m.workspace_id = v.workspace_id
          AND m.user_id = p_reviewer_user_id
     ) THEN
    RAISE EXCEPTION 'reviewer is not a workspace member' USING ERRCODE = '22023';
  END IF;

  UPDATE api.records
     SET reviewer_user_id = p_reviewer_user_id,
         planned_end = p_planned_end,
         metadata_version = metadata_version + 1,
         updated_at = now(),
         updated_by_user_id = api.current_user_id()
   WHERE id = p_record_id
   RETURNING * INTO v;
  RETURN v;
END $$;
