    status text DEFAULT 'available'::text NOT NULL,
    occupied_record_id uuid,
    metadata jsonb DEFAULT '{}'::jsonb NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT chk_storage_positions_col CHECK ((col_index >= 0)),
    CONSTRAINT chk_storage_positions_label CHECK (((length(btrim(label)) >= 1) AND (length(btrim(label)) <= 8))),
    CONSTRAINT chk_storage_positions_occupancy CHECK (((status = 'occupied'::text) = (occupied_record_id IS NOT NULL))),
    CONSTRAINT chk_storage_positions_row CHECK ((row_index >= 0)),
    CONSTRAINT chk_storage_positions_status CHECK ((status = ANY (ARRAY['available'::text, 'occupied'::text, 'quarantined'::text, 'missing'::text])))
);
