CREATE FUNCTION api.set_protocol_version_status(p_version_id uuid, p_status text, p_reason text DEFAULT NULL::text, p_effective_at timestamp with time zone DEFAULT NULL::timestamp with time zone) RETURNS api.protocol_versions
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
  v_version api.protocol_versions;
  v_block text;
  v_effective timestamptz;
BEGIN
  SELECT * INTO v_version FROM api.protocol_versions WHERE id = p_version_id FOR UPDATE;
  IF v_version.id IS NULL OR v_version.workspace_id IS DISTINCT FROM api.current_workspace_id() THEN
    RAISE EXCEPTION 'protocol version not found' USING ERRCODE = '42501';
  END IF;
  PERFORM api.require_capability(v_version.workspace_id, 'record.create');
  IF p_status IS NULL OR p_status NOT IN ('draft','in_review','effective','superseded','retired') THEN
    RAISE EXCEPTION 'invalid protocol version status' USING ERRCODE = '22023';
  END IF;
  IF p_status = 'effective' THEN
    v_block := internal.approval_publish_blocker('protocol_revision', v_version.id);
    IF v_block IS NOT NULL THEN
      RAISE EXCEPTION 'protocol version cannot become effective: %', v_block USING ERRCODE = 'SB084';
    END IF;
    v_effective := coalesce(p_effective_at, now());
    UPDATE api.protocol_versions
       SET status = 'superseded', updated_at = now(), updated_by_user_id = api.current_user_id()
     WHERE protocol_record_id = v_version.protocol_record_id AND status = 'effective' AND id <> v_version.id;
  ELSE
    v_effective := v_version.effective_at;
  END IF;
  UPDATE api.protocol_versions
     SET status = p_status, effective_at = v_effective,
         reason = coalesce(nullif(btrim(coalesce(p_reason, '')), ''), reason),
         updated_at = now(), updated_by_user_id = api.current_user_id()
   WHERE id = v_version.id
  RETURNING * INTO v_version;
  PERFORM internal.emit_change_event(v_version.workspace_id, 'protocol_version', v_version.id, 'update', v_version.protocol_record_id, NULL,
    jsonb_build_object('protocolRecordId', v_version.protocol_record_id, 'status', p_status));
  RETURN v_version;
END $$;
--> statement-breakpoint
ALTER FUNCTION api.set_protocol_version_status(p_version_id uuid, p_status text, p_reason text, p_effective_at timestamp with time zone) OWNER TO migrator;
--> statement-breakpoint
CREATE FUNCTION api.set_record_favourite(p_object_kind text, p_object_id uuid, p_favourite boolean) RETURNS timestamp with time zone
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
  v_user_id text;
  v_workspace_id uuid;
  v_created_at timestamptz;
BEGIN
  v_user_id := "api"."current_user_id"();
  IF v_user_id IS NULL THEN
    RAISE EXCEPTION 'set_record_favourite requires an authenticated user' USING ERRCODE = '42501';
  END IF;
  IF p_object_kind NOT IN ('record', 'dataset', 'sheet', 'project', 'notebook_template') THEN
    RAISE EXCEPTION 'unknown favourite-object kind' USING ERRCODE = '22023';
  END IF;

  -- Unfavouriting (p_favourite = false) removes the CALLER-OWNED pin before
  -- any object-resolution or membership check: an object that has since been
  -- deleted (no canonical row) or whose workspace the caller left must still
  -- be unfavouritable. The user_id predicate makes this caller-scoped only;
  -- no other user's favourite can be touched.
  IF NOT p_favourite THEN
    DELETE FROM "api"."user_favourites"
    WHERE user_id = v_user_id
      AND object_kind = p_object_kind
      AND object_id = p_object_id;
    RETURN NULL;
  END IF;

  IF p_object_kind<>'notebook_template' AND NOT internal.can_access_object(CASE p_object_kind WHEN 'sheet' THEN 'instance' ELSE p_object_kind END,p_object_id,'view') THEN RETURN NULL; END IF;
 v_workspace_id := CASE p_object_kind
    WHEN 'record' THEN (
      SELECT r.workspace_id FROM api.records r
      WHERE r.id = p_object_id AND r.deleted_at IS NULL
    )
    WHEN 'dataset' THEN (
      SELECT d.workspace_id FROM api.datasets d WHERE d.id = p_object_id
    )
    WHEN 'sheet' THEN (
      SELECT s.workspace_id FROM api.sheet_instances s WHERE s.id = p_object_id
    )
    WHEN 'project' THEN (
      SELECT p.workspace_id FROM api.projects p WHERE p.id = p_object_id
    )
    WHEN 'notebook_template' THEN (
      SELECT t.workspace_id FROM api.notebook_templates t WHERE t.id = p_object_id
    )
  END;

  -- Unknown objects and objects whose workspace the caller can no longer see
  -- are ignored rather than erroring: favourites must never disturb the page.
  IF v_workspace_id IS NULL OR NOT "api"."is_workspace_member"(v_workspace_id) THEN
    RETURN NULL;
  END IF;

  IF p_favourite THEN
    INSERT INTO "api"."user_favourites"
      (workspace_id, user_id, object_kind, object_id, created_at)
    VALUES
      (v_workspace_id, v_user_id, p_object_kind, p_object_id, now())
    -- created_at is preserved on conflict: re-starring an existing favourite
    -- must not move it to the top of the home surface.
    ON CONFLICT (user_id, object_kind, object_id)
    DO UPDATE SET workspace_id = EXCLUDED.workspace_id
    RETURNING created_at INTO v_created_at;
    RETURN v_created_at;
  END IF;

  RETURN NULL;
END;
$$;
--> statement-breakpoint
ALTER FUNCTION api.set_record_favourite(p_object_kind text, p_object_id uuid, p_favourite boolean) OWNER TO migrator;
--> statement-breakpoint
