CREATE FUNCTION api.start_connector_run(p_workspace_id uuid, p_connector_id uuid, p_trigger_kind text DEFAULT 'manual'::text, p_request_digest text DEFAULT NULL::text, p_retry_of_run_id uuid DEFAULT NULL::uuid, p_selector_digest text DEFAULT NULL::text) RETURNS api.connector_runs
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
  -- Authoritative staleness threshold (seconds). Fixed server/database
  -- policy: callers cannot lower, raise, or bypass it.
  v_stale_threshold_seconds CONSTANT integer := 900;
  v_connector "api"."connectors";
  v_retry_of "api"."connector_runs";
  v_existing "api"."connector_runs";
  v_running uuid;
  v "api"."connector_runs";
BEGIN
  IF "api"."current_workspace_id"() IS DISTINCT FROM p_workspace_id THEN
    RAISE EXCEPTION 'wrong workspace' USING ERRCODE = 'SB033';
  END IF;
  IF NOT "api"."is_workspace_writer"(p_workspace_id) THEN
    RAISE EXCEPTION 'capability required: workspace write' USING ERRCODE = '42501';
  END IF;
  IF p_trigger_kind NOT IN ('manual', 'scheduled', 'event') THEN
    RAISE EXCEPTION 'invalid run trigger' USING ERRCODE = 'SB034';
  END IF;
  SELECT * INTO v_connector FROM "api"."connectors"
   WHERE id = p_connector_id AND workspace_id = p_workspace_id FOR UPDATE;
  IF v_connector IS NULL THEN
    RAISE EXCEPTION 'connector not found' USING ERRCODE = 'SB036';
  END IF;
  IF v_connector.status <> 'active' THEN
    RAISE EXCEPTION 'connector is not active' USING ERRCODE = 'SB042';
  END IF;

  IF p_request_digest IS NOT NULL THEN
    IF length(btrim(p_request_digest)) NOT BETWEEN 16 AND 128 THEN
      RAISE EXCEPTION 'invalid request digest' USING ERRCODE = 'SB034';
    END IF;
    SELECT * INTO v_existing FROM "api"."connector_runs"
     WHERE connector_id = p_connector_id
       AND request_digest = btrim(p_request_digest)
       AND workspace_id = p_workspace_id
     ORDER BY started_at DESC
     LIMIT 1;
    IF v_existing.id IS NOT NULL THEN
      IF v_existing.status = 'running' THEN
        IF v_existing.started_at < clock_timestamp() - make_interval(secs => v_stale_threshold_seconds) THEN
          UPDATE "api"."connector_runs"
             SET status = 'failed',
                 error_code = 'stale_run_reconciled',
                 error_message = 'run exceeded the staleness threshold and was reconciled',
                 finished_at = clock_timestamp()
           WHERE id = v_existing.id;
          PERFORM "api"."append_connector_run_log"(
            p_workspace_id,
            v_existing.id,
            'warning',
            'reconcile',
            'Stale running attempt reconciled by a newer start.',
            '{"reason": "stale_run_reconciled"}'::jsonb
          );
          -- The reconciled attempt becomes the retry lineage of this start.
          v_retry_of := v_existing;
        ELSE
          RAISE EXCEPTION 'run already in progress' USING ERRCODE = 'SB044';
        END IF;
      END IF;
      IF v_existing.status = 'succeeded' THEN
        RETURN v_existing;
      END IF;
      -- Failed prior attempt: retrying the same request identity is normally
      -- an explicit new attempt linked to that failed run. An auto-reconciled
      -- stale run already set v_retry_of above; only an untouched failed run
      -- still requires the explicit linkage.
      IF v_retry_of.id IS NULL
        AND (p_retry_of_run_id IS NULL OR p_retry_of_run_id <> v_existing.id) THEN
        RAISE EXCEPTION 'request previously failed; retry with retry_of_run_id'
          USING ERRCODE = 'SB045';
      END IF;
    END IF;
  END IF;

  -- INT-03: provisional selector identity — conflict only with a run that is
  -- still running; failed runs are retried as linked attempts via the
  -- product flow, and prior successes are decided on content identity later.
  IF p_selector_digest IS NOT NULL THEN
    IF length(btrim(p_selector_digest)) NOT BETWEEN 16 AND 128 THEN
      RAISE EXCEPTION 'invalid selector digest' USING ERRCODE = 'SB034';
    END IF;
    SELECT id INTO v_running FROM "api"."connector_runs"
     WHERE connector_id = p_connector_id
       AND selector_digest = btrim(p_selector_digest)
       AND workspace_id = p_workspace_id
       AND status = 'running'
     LIMIT 1;
    IF v_running IS NOT NULL THEN
      IF (
        SELECT started_at FROM "api"."connector_runs" WHERE id = v_running
      ) < clock_timestamp() - make_interval(secs => v_stale_threshold_seconds) THEN
        UPDATE "api"."connector_runs"
           SET status = 'failed',
               error_code = 'stale_run_reconciled',
               error_message = 'run exceeded the staleness threshold and was reconciled',
               finished_at = clock_timestamp()
         WHERE id = v_running;
        PERFORM "api"."append_connector_run_log"(
          p_workspace_id,
          v_running,
          'warning',
          'reconcile',
          'Stale running attempt reconciled by a newer start.',
          '{"reason": "stale_run_reconciled"}'::jsonb
        );
        IF v_retry_of.id IS NULL THEN
          SELECT * INTO v_retry_of FROM "api"."connector_runs" WHERE id = v_running;
        END IF;
      ELSE
        RAISE EXCEPTION 'run already in progress' USING ERRCODE = 'SB044';
      END IF;
    END IF;
  END IF;

  IF p_retry_of_run_id IS NOT NULL THEN
    IF v_retry_of.id IS DISTINCT FROM p_retry_of_run_id THEN
      SELECT * INTO v_retry_of FROM "api"."connector_runs"
       WHERE id = p_retry_of_run_id AND workspace_id = p_workspace_id;
      IF v_retry_of IS NULL THEN
        RAISE EXCEPTION 'retry target not found' USING ERRCODE = 'SB036';
      END IF;
    END IF;
  END IF;

  INSERT INTO "api"."connector_runs"(
    workspace_id, connector_id, trigger_kind, status, attempt, retry_of_run_id,
    request_digest, selector_digest, actor_user_id, actor_credential_id
  ) VALUES (
    p_workspace_id, p_connector_id, p_trigger_kind, 'running',
    CASE WHEN v_retry_of.id IS NOT NULL THEN v_retry_of.attempt + 1 ELSE 1 END,
    COALESCE(v_retry_of.id, p_retry_of_run_id),
    CASE WHEN p_request_digest IS NULL THEN NULL ELSE btrim(p_request_digest) END,
    CASE WHEN p_selector_digest IS NULL THEN NULL ELSE btrim(p_selector_digest) END,
    "api"."current_user_id"(), "api"."current_credential_id"()
  ) RETURNING * INTO v;
  RETURN v;
END $$;
--> statement-breakpoint
ALTER FUNCTION api.start_connector_run(p_workspace_id uuid, p_connector_id uuid, p_trigger_kind text, p_request_digest text, p_retry_of_run_id uuid, p_selector_digest text) OWNER TO migrator;
--> statement-breakpoint
CREATE FUNCTION api.start_experiment(p_record_id uuid, p_expected_metadata_version bigint, p_protocol_version_id uuid DEFAULT NULL::uuid, p_reason text DEFAULT NULL::text) RETURNS api.records
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
  v_record api.records;
  v_project api.projects;
  v_version api.protocol_versions;
  v_missing text[];
BEGIN
  SELECT * INTO v_record FROM api.records
   WHERE id = p_record_id AND deleted_at IS NULL FOR UPDATE;
  IF v_record.id IS NULL THEN
    RAISE EXCEPTION 'record not found' USING ERRCODE = 'SB036';
  END IF;
  IF v_record.kind <> 'experiment' THEN
    RAISE EXCEPTION 'not an experiment' USING ERRCODE = '22023';
  END IF;
  IF NOT api.is_workspace_writer(v_record.workspace_id) THEN
    RAISE EXCEPTION 'capability required: workspace write' USING ERRCODE = '42501';
  END IF;
  IF v_record.status <> 'draft' THEN
    RAISE EXCEPTION 'only a draft experiment can start' USING ERRCODE = 'SB109';
  END IF;
  IF p_expected_metadata_version IS NULL
     OR p_expected_metadata_version IS DISTINCT FROM v_record.metadata_version THEN
    RAISE EXCEPTION 'stale Record metadata revision' USING ERRCODE = 'SB001';
  END IF;
  IF v_record.project_id IS NULL THEN
    RAISE EXCEPTION 'an experiment needs a project' USING ERRCODE = '22023';
  END IF;
  IF NOT internal.can_edit_project(v_record.project_id) THEN
    RAISE EXCEPTION 'project edit authority required' USING ERRCODE = '42501';
  END IF;
  SELECT * INTO v_project FROM api.projects
   WHERE id = v_record.project_id AND workspace_id = v_record.workspace_id;

  -- An explicit version wins; otherwise a project that requires an effective
  -- protocol starts on its current pin.
  IF p_protocol_version_id IS NOT NULL THEN
    SELECT * INTO v_version FROM api.protocol_versions
     WHERE id = p_protocol_version_id AND workspace_id = v_record.workspace_id;
    IF v_version.id IS NULL THEN
      RAISE EXCEPTION 'protocol version not found in the active workspace' USING ERRCODE = '42501';
    END IF;
  ELSIF v_project.require_effective_protocol THEN
    SELECT pv.* INTO v_version FROM api.project_protocols pp
      JOIN api.protocol_versions pv ON pv.id = pp.protocol_version_id
     WHERE pp.project_id = v_record.project_id
       AND pp.workspace_id = v_record.workspace_id;
  END IF;

  IF v_version.id IS NULL THEN
    IF v_project.require_effective_protocol THEN
      RAISE EXCEPTION 'project requires an effective protocol version' USING ERRCODE = 'SB110';
    END IF;
  ELSE
    -- Lifecycle eligibility, exact-version acknowledgement (LAB-07 training) and
    -- the project's exact pin where it requires one.
    PERFORM internal.assert_protocol_start_eligible(
      v_version.id, api.current_user_id(), v_record.project_id);
  END IF;

  -- EXP-03.3: a required template parameter with no resolved value is a start checklist item
  -- that is still missing. The refusal names them, so the user knows what to supply rather than
  -- being told the experiment cannot start.
  v_missing := internal.missing_required_template_parameters(v_record.id);
  IF array_length(v_missing, 1) IS NOT NULL THEN
    RAISE EXCEPTION 'required items are still missing: %', array_to_string(v_missing, ', ')
      USING ERRCODE = 'SB111';
  END IF;

  UPDATE api.records
     SET status = 'in_progress',
         protocol_version_id = v_version.id,
         metadata_version = metadata_version + 1,
         updated_at = now(),
         updated_by_user_id = api.current_user_id()
   WHERE id = v_record.id
  RETURNING * INTO v_record;
  PERFORM internal.emit_change_event(v_record.workspace_id, 'record', v_record.id, 'update',
    v_record.id, v_record.project_id,
    jsonb_build_object('effect', 'experiment_started',
      'protocolVersionId', v_version.id, 'reason', nullif(btrim(coalesce(p_reason, '')), '')));
  RETURN v_record;
END $$;
--> statement-breakpoint
ALTER FUNCTION api.start_experiment(p_record_id uuid, p_expected_metadata_version bigint, p_protocol_version_id uuid, p_reason text) OWNER TO migrator;
--> statement-breakpoint
CREATE FUNCTION api.start_instrument_run(p_workspace_id uuid, p_run_id uuid) RETURNS api.instrument_runs
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$ DECLARE v api.instrument_runs; BEGIN
 IF p_run_id IS NOT NULL THEN PERFORM internal.assert_object_access('run',p_run_id,'edit'); END IF; IF api.current_workspace_id() IS DISTINCT FROM p_workspace_id THEN RAISE EXCEPTION 'wrong workspace' USING ERRCODE='SB033'; END IF; SELECT * INTO v FROM api.instrument_runs WHERE id=p_run_id AND workspace_id=p_workspace_id FOR UPDATE; IF v IS NULL THEN RAISE EXCEPTION 'run not found' USING ERRCODE='SB039'; END IF; IF v.status<>'queued' THEN RAISE EXCEPTION 'run is not queued' USING ERRCODE='SB042'; END IF; UPDATE api.instrument_runs SET status='running',started_at=now(),updated_at=now(),updated_by_user_id=api.current_user_id() WHERE id=p_run_id RETURNING * INTO v; INSERT INTO api.instrument_observations(workspace_id,run_id,source_id,observation_type,source_timestamp) VALUES(p_workspace_id,p_run_id,'system-run-start-'||v.id,'run_start',now()); RETURN v; END $$;
--> statement-breakpoint
ALTER FUNCTION api.start_instrument_run(p_workspace_id uuid, p_run_id uuid) OWNER TO migrator;
--> statement-breakpoint
CREATE FUNCTION api.start_pipeline_run(p_workspace_id uuid, p_definition_version_id uuid, p_trigger_kind text DEFAULT 'manual'::text, p_parameters jsonb DEFAULT '{}'::jsonb, p_input_versions jsonb DEFAULT '{}'::jsonb, p_retry_of_run_id uuid DEFAULT NULL::uuid, p_trigger_occurrence_id text DEFAULT NULL::text, p_schedule_id uuid DEFAULT NULL::uuid) RETURNS api.pipeline_runs
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $_$
DECLARE
  v_stale_threshold_seconds CONSTANT integer := 900;
  v_version api.pipeline_definition_versions;
  v_definition api.pipeline_definitions;
  v_retry_of api.pipeline_runs;
  v_existing api.pipeline_runs;
  v_errors jsonb;
  v_digest text;
  v_occurrence_run boolean;
  v api.pipeline_runs;
BEGIN
  IF api.current_workspace_id() IS DISTINCT FROM p_workspace_id THEN
    RAISE EXCEPTION 'wrong workspace' USING ERRCODE = 'SB033';
  END IF;
  IF NOT api.is_workspace_writer(p_workspace_id) THEN
    RAISE EXCEPTION 'capability required: workspace write' USING ERRCODE = '42501';
  END IF;
  IF p_trigger_kind NOT IN ('manual', 'scheduled', 'event') THEN
    RAISE EXCEPTION 'invalid run trigger' USING ERRCODE = 'SB034';
  END IF;
  -- Scheduled/event runs always carry a stable trigger occurrence identity;
  -- manual runs never do.
  IF p_trigger_occurrence_id IS NOT NULL AND p_trigger_kind = 'manual' AND p_trigger_occurrence_id !~ '^manual:[0-9a-f-]{36}$' THEN
    RAISE EXCEPTION 'invalid manual invocation identity' USING ERRCODE = 'SB034';
  END IF;
  IF p_trigger_occurrence_id IS NOT NULL AND (
    length(p_trigger_occurrence_id) NOT BETWEEN 8 AND 128
    OR p_trigger_occurrence_id !~ '^[a-z]+:[A-Za-z0-9:_+-]+$'
  ) THEN
    RAISE EXCEPTION 'invalid trigger occurrence identity' USING ERRCODE = 'SB034';
  END IF;
  IF p_schedule_id IS NOT NULL AND p_trigger_kind = 'manual' THEN
    RAISE EXCEPTION 'manual runs cannot carry a schedule identity' USING ERRCODE = 'SB034';
  END IF;
  IF p_schedule_id IS NOT NULL AND NOT EXISTS (
    SELECT 1 FROM api.pipeline_schedules
     WHERE id = p_schedule_id AND workspace_id = p_workspace_id
  ) THEN
    RAISE EXCEPTION 'schedule not found' USING ERRCODE = 'SB036';
  END IF;
  SELECT * INTO v_version FROM api.pipeline_definition_versions
   WHERE id = p_definition_version_id AND workspace_id = p_workspace_id FOR UPDATE;
  IF v_version IS NULL THEN
    RAISE EXCEPTION 'pipeline definition version not found' USING ERRCODE = 'SB036';
  END IF;
  IF v_version.lifecycle <> 'published' THEN
    -- Reproducibility: a retry pins the EXACT version the failed/crashed
    -- attempt used, even if that version has since been retired. Only
    -- genuinely new runs must use a currently-published version.
    IF p_retry_of_run_id IS NULL OR NOT EXISTS (
      SELECT 1 FROM api.pipeline_runs
       WHERE id = p_retry_of_run_id
         AND definition_version_id = v_version.id
         AND workspace_id = p_workspace_id
    ) THEN
      RAISE EXCEPTION 'only published Pipeline versions can be run' USING ERRCODE = 'SB072';
    END IF;
  END IF;
  SELECT * INTO v_definition FROM api.pipeline_definitions
   WHERE id = v_version.definition_id;
  IF v_definition.lifecycle <> 'active' THEN
    RAISE EXCEPTION 'retired Pipeline cannot be run' USING ERRCODE = 'SB072';
  END IF;
  v_errors := api.pipeline_run_request_errors(
    v_version.configuration, p_parameters, p_input_versions
  );
  IF jsonb_array_length(v_errors) > 0 THEN
    RAISE EXCEPTION 'invalid pipeline run request: %', (v_errors #>> '{}')
      USING ERRCODE = 'SB070';
  END IF;

  -- The canonical run identity is computed here, from the request the
  -- database already holds: definition version + parameters + input Dataset
  -- Versions (all canonical jsonb). The caller can never choose or forge
  -- the digest, so replay/concurrency/retry decisions are authoritative.
  v_digest := encode(sha256(convert_to(
    jsonb_build_object(
      'definitionVersionId', p_definition_version_id::text,
      'parameters', COALESCE(p_parameters, '{}'::jsonb),
      'inputVersions', COALESCE(p_input_versions, '{}'::jsonb)
    )::text, 'UTF8')), 'hex');

  -- Manual runs dedupe by canonical digest; scheduled/event occurrences
  -- dedupe by their stable trigger occurrence identity.
  v_occurrence_run := p_trigger_occurrence_id IS NOT NULL;
  IF v_occurrence_run THEN
    SELECT * INTO v_existing FROM api.pipeline_runs
     WHERE workspace_id = p_workspace_id
       AND trigger_occurrence_id = p_trigger_occurrence_id
     ORDER BY started_at DESC
     LIMIT 1;
  ELSE
    SELECT * INTO v_existing FROM api.pipeline_runs
     WHERE definition_version_id = p_definition_version_id
       AND input_digest = v_digest
       AND trigger_occurrence_id IS NULL
       AND workspace_id = p_workspace_id
     ORDER BY started_at DESC
     LIMIT 1;
  END IF;
  IF v_existing.id IS NOT NULL THEN
    IF v_existing.definition_version_id IS DISTINCT FROM p_definition_version_id OR v_existing.input_digest IS DISTINCT FROM v_digest THEN
      RAISE EXCEPTION 'invocation already used with different inputs or version' USING ERRCODE = 'SB034';
    END IF;
    IF v_existing.status = 'running' THEN
      IF v_existing.started_at < clock_timestamp() - make_interval(secs => v_stale_threshold_seconds)
         AND NOT internal.pipeline_run_job_is_live(v_existing.id) THEN
        -- Log the reconciliation while the run is still 'running', then
        -- fail it (append_pipeline_run_log only accepts running runs).
        PERFORM api.append_pipeline_run_log(
          p_workspace_id, v_existing.id, 'warning', 'reconcile',
          'Stale running attempt reconciled by a newer start.',
          '{"reason": "stale_run_reconciled"}'::jsonb
        );
        UPDATE api.pipeline_runs SET
          status = 'failed',
          error_code = 'stale_run_reconciled',
          error_message = 'run exceeded the staleness threshold and was reconciled',
          finished_at = clock_timestamp()
        WHERE id = v_existing.id;
        v_retry_of := v_existing;
      ELSE
        RAISE EXCEPTION 'run already in progress' USING ERRCODE = 'SB044';
      END IF;
    END IF;
    IF v_existing.status = 'succeeded' THEN
      RETURN v_existing;
    END IF;
    IF v_retry_of.id IS NULL
      AND (p_retry_of_run_id IS NULL OR p_retry_of_run_id <> v_existing.id) THEN
      RAISE EXCEPTION 'inputs previously failed; retry with retry_of_run_id'
        USING ERRCODE = 'SB045';
    END IF;
  END IF;

  IF p_retry_of_run_id IS NOT NULL THEN
    IF v_retry_of.id IS DISTINCT FROM p_retry_of_run_id THEN
      SELECT * INTO v_retry_of FROM api.pipeline_runs
       WHERE id = p_retry_of_run_id AND workspace_id = p_workspace_id;
      IF v_retry_of IS NULL THEN
        RAISE EXCEPTION 'retry target not found' USING ERRCODE = 'SB036';
      END IF;
    END IF;
    -- Retry lineage must be reproducible: the retry executes the exact
    -- version the failed/crashed attempt used.
    IF v_retry_of.definition_version_id IS DISTINCT FROM p_definition_version_id THEN
      RAISE EXCEPTION 'retry target uses a different Pipeline version' USING ERRCODE = 'SB034';
    END IF;
    IF v_retry_of.trigger_occurrence_id IS DISTINCT FROM p_trigger_occurrence_id THEN
      RAISE EXCEPTION 'retry target does not match the trigger occurrence' USING ERRCODE = 'SB034';
    END IF;
  END IF;

  INSERT INTO api.pipeline_runs(
    workspace_id, definition_version_id, trigger_kind, status, attempt,
    retry_of_run_id, trigger_occurrence_id, schedule_id, input_digest,
    parameters, input_versions, actor_user_id, actor_credential_id
  ) VALUES (
    p_workspace_id, p_definition_version_id, p_trigger_kind, 'running',
    CASE WHEN v_retry_of.id IS NOT NULL THEN v_retry_of.attempt + 1 ELSE 1 END,
    COALESCE(v_retry_of.id, p_retry_of_run_id),
    p_trigger_occurrence_id,
    p_schedule_id,
    v_digest,
    COALESCE(p_parameters, '{}'::jsonb),
    COALESCE(p_input_versions, '{}'::jsonb),
    api.current_user_id(), api.current_credential_id()
  ) RETURNING * INTO v;
  RETURN v;
END $_$;
--> statement-breakpoint
ALTER FUNCTION api.start_pipeline_run(p_workspace_id uuid, p_definition_version_id uuid, p_trigger_kind text, p_parameters jsonb, p_input_versions jsonb, p_retry_of_run_id uuid, p_trigger_occurrence_id text, p_schedule_id uuid) OWNER TO migrator;
--> statement-breakpoint
