CREATE FUNCTION api.storage_path(p_position_id uuid) RETURNS text
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
DECLARE
  v_pos "api"."storage_positions";
  v_box "api"."storage_boxes";
  v_rack "api"."storage_racks";
  v_shelf "api"."storage_shelves";
  v_unit "api"."storage_units";
  v_room "api"."storage_rooms";
  v_site "api"."storage_sites";
BEGIN
  SELECT * INTO v_pos FROM "api"."storage_positions" WHERE id = p_position_id;
  IF v_pos IS NULL THEN RETURN NULL; END IF;
  SELECT * INTO v_box FROM "api"."storage_boxes" WHERE id = v_pos.box_id;
  SELECT * INTO v_rack FROM "api"."storage_racks" WHERE id = v_box.rack_id;
  SELECT * INTO v_shelf FROM "api"."storage_shelves" WHERE id = v_rack.shelf_id;
  SELECT * INTO v_unit FROM "api"."storage_units" WHERE id = v_shelf.unit_id;
  SELECT * INTO v_room FROM "api"."storage_rooms" WHERE id = v_unit.room_id;
  SELECT * INTO v_site FROM "api"."storage_sites" WHERE id = v_room.site_id;
  RETURN concat_ws(' > ',
    v_site.name, v_room.name, v_unit.name, v_shelf.name,
    v_rack.name, v_box.name, v_pos.label);
END;
$$;
--> statement-breakpoint
ALTER FUNCTION api.storage_path(p_position_id uuid) OWNER TO migrator;
--> statement-breakpoint
CREATE FUNCTION api.submit_approval_request(p_workspace_id uuid, p_object_kind text, p_object_id uuid, p_required_approver_roles text[], p_reason text, p_require_independence boolean DEFAULT true, p_required_approvals integer DEFAULT 1, p_object_revision bigint DEFAULT NULL::bigint) RETURNS api.approval_requests
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $_$
DECLARE
  v_actor text := api.current_user_id();
  v_roles text[];
  v_row api.approval_requests;
  v_version api.dataset_schema_versions;
  v_model_version api.record_model_versions;
  v_protocol_version api.protocol_versions;
  v_workspace uuid;
BEGIN
  IF v_actor IS NULL OR api.current_workspace_id() IS DISTINCT FROM p_workspace_id
    OR NOT api.is_workspace_writer(p_workspace_id) THEN
    RAISE EXCEPTION 'approval denied' USING ERRCODE = '42501';
  END IF;
  IF p_object_kind IS NULL OR p_object_kind !~ '^[a-z][a-z0-9_]{0,63}$' OR p_object_id IS NULL THEN
    RAISE EXCEPTION 'invalid approval object' USING ERRCODE = '22023';
  END IF;
  IF p_reason IS NULL OR length(btrim(p_reason)) NOT BETWEEN 1 AND 500 THEN
    RAISE EXCEPTION 'an approval reason is required' USING ERRCODE = '22023';
  END IF;
  SELECT array_agg(role ORDER BY role) INTO v_roles FROM (
    SELECT DISTINCT unnest(coalesce(p_required_approver_roles, '{}'::text[])) AS role
  ) roles WHERE role IS NOT NULL AND role <> '';
  IF coalesce(cardinality(v_roles), 0) = 0 OR NOT (v_roles <@ ARRAY['owner','admin','member','steward','scientist','analyst','reviewer','viewer']::text[]) THEN
    RAISE EXCEPTION 'invalid approver roles' USING ERRCODE = '22023';
  END IF;
  IF p_required_approvals IS NULL OR p_required_approvals < 1 OR p_required_approvals > 10 THEN
    RAISE EXCEPTION 'invalid required approval count' USING ERRCODE = '22023';
  END IF;
  IF p_object_kind = 'dataset_schema_version' THEN
    SELECT * INTO v_version FROM api.dataset_schema_versions WHERE id = p_object_id FOR UPDATE;
    SELECT workspace_id INTO v_workspace FROM api.dataset_schema_definitions WHERE id = v_version.schema_id;
    IF v_version.id IS NULL OR v_workspace IS DISTINCT FROM p_workspace_id THEN
      RAISE EXCEPTION 'approval object not found' USING ERRCODE = '42501';
    END IF;
    PERFORM api.require_capability(v_workspace, 'schema.edit');
    IF v_version.lifecycle <> 'draft' THEN
      RAISE EXCEPTION 'only draft versions may be submitted' USING ERRCODE = 'SB072';
    END IF;
    IF p_object_revision IS NOT NULL AND p_object_revision IS DISTINCT FROM v_version.revision THEN
      RAISE EXCEPTION 'stale Dataset Schema Version revision' USING ERRCODE = 'SB001';
    END IF;
    p_object_revision := v_version.revision;
  ELSIF p_object_kind = 'record_model_version' THEN
    SELECT * INTO v_model_version FROM api.record_model_versions WHERE id = p_object_id FOR UPDATE;
    IF v_model_version.id IS NULL OR v_model_version.workspace_id IS DISTINCT FROM p_workspace_id THEN
      RAISE EXCEPTION 'approval object not found' USING ERRCODE = '42501';
    END IF;
    PERFORM api.require_capability(v_model_version.workspace_id, 'schema.edit');
    IF v_model_version.lifecycle <> 'draft' THEN
      RAISE EXCEPTION 'only draft versions may be submitted' USING ERRCODE = 'SB072';
    END IF;
    IF NOT coalesce(p_require_independence, true) OR p_required_approvals < cardinality(v_roles) THEN
      RAISE EXCEPTION 'Record Model approval requires independence and coverage of every named role' USING ERRCODE = '22023';
    END IF;
    p_object_revision := v_model_version.revision;
  ELSIF p_object_kind = 'protocol_revision' THEN
    SELECT * INTO v_protocol_version FROM api.protocol_versions WHERE id = p_object_id FOR UPDATE;
    IF v_protocol_version.id IS NULL OR v_protocol_version.workspace_id IS DISTINCT FROM p_workspace_id THEN
      RAISE EXCEPTION 'approval object not found' USING ERRCODE = '42501';
    END IF;
    PERFORM api.require_capability(v_protocol_version.workspace_id, 'record.create');
    IF v_protocol_version.status <> 'in_review' THEN
      RAISE EXCEPTION 'only in-review protocol versions may be submitted' USING ERRCODE = 'SB072';
    END IF;
    -- The approval chain is fixed: author, technical review, QA. Callers cannot
    -- weaken the roles, the independence rule or the required count.
    IF v_roles IS DISTINCT FROM ARRAY['admin','owner','reviewer','scientist','steward']::text[]
      OR NOT coalesce(p_require_independence, true) OR p_required_approvals < 2 THEN
      RAISE EXCEPTION 'protocol approval requires the canonical chain' USING ERRCODE = '22023';
    END IF;
    p_object_revision := NULL;
  END IF;
  INSERT INTO api.approval_requests(workspace_id, object_kind, object_id, object_revision,
    required_approver_roles, required_approvals, require_independence, state, reason, submitted_by_user_id, submitted_at)
  VALUES (p_workspace_id, p_object_kind, p_object_id, p_object_revision, v_roles, p_required_approvals,
    coalesce(p_require_independence, true), 'pending', btrim(p_reason), v_actor, clock_timestamp()) RETURNING * INTO v_row;
  RETURN v_row;
END $_$;
--> statement-breakpoint
ALTER FUNCTION api.submit_approval_request(p_workspace_id uuid, p_object_kind text, p_object_id uuid, p_required_approver_roles text[], p_reason text, p_require_independence boolean, p_required_approvals integer, p_object_revision bigint) OWNER TO migrator;
--> statement-breakpoint
CREATE FUNCTION api.submit_record_revision(p_record_id uuid, p_expected_source_digest text, p_workflow_definition_key text, p_workflow_definition_version integer, p_reviewer_user_ids text[], p_confirmed boolean, p_idempotency_key text, p_due_at timestamp with time zone DEFAULT NULL::timestamp with time zone, p_author_signing_token text DEFAULT NULL::text, p_author_confirmation_phrase text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $_$
DECLARE
  claimed_workspace uuid;
  actor text;
  session_id text;
  actor_role text;
  record_row api.records;
  envelope jsonb;
  actual_digest text;
  snapshot_digest text;
  normalized_reviewers text[];
  revision_row api.revisions;
  submission_row api.review_submissions;
  existing_submission api.review_submissions;
  existing_revision api.revisions;
  submitted_at timestamptz := clock_timestamp();
  v_revision_id uuid;
  requires_author boolean;
  signing_args jsonb;
  author_grant internal.signature_grants;
  author_signature api.signatures;
  signature_result jsonb;
BEGIN
 IF p_record_id IS NOT NULL THEN PERFORM internal.assert_object_access('record',p_record_id,'edit'); END IF;
  BEGIN
    claimed_workspace := nullif(api.claim_probe()->>'workspace_id', '')::uuid;
    actor := nullif(api.claim_probe()->>'sub', '');
    session_id := nullif(api.claim_probe()->>'session_id', '');
    actor_role := nullif(api.claim_probe()->>'role', '');
  EXCEPTION WHEN others THEN
    RAISE EXCEPTION 'record denied' USING ERRCODE = '42501';
  END;
  IF claimed_workspace IS NULL OR actor IS NULL OR session_id IS NULL
     OR actor_role <> 'authenticated' OR p_confirmed IS DISTINCT FROM true
     OR NOT api.is_workspace_writer(claimed_workspace) THEN
    RAISE EXCEPTION 'record denied' USING ERRCODE = '42501';
  END IF;
  IF p_expected_source_digest IS NULL
     OR p_expected_source_digest !~ '^[0-9a-f]{64}$' THEN
    RAISE EXCEPTION 'expected source digest is required' USING ERRCODE = '22023';
  END IF;
  IF p_workflow_definition_key IS NULL
     OR p_workflow_definition_key !~ '^[a-z0-9][a-z0-9_-]{0,127}$'
     OR coalesce(p_workflow_definition_version, 0) < 1 THEN
    RAISE EXCEPTION 'versioned workflow definition is required' USING ERRCODE = '22023';
  END IF;
  IF NOT EXISTS (
    SELECT 1 FROM internal.review_workflow_definitions definition
    WHERE definition.definition_key = p_workflow_definition_key
      AND definition.version = p_workflow_definition_version
  ) THEN
    RAISE EXCEPTION 'unknown workflow definition version' USING ERRCODE = '22023';
  END IF;
  IF p_idempotency_key IS NULL OR length(p_idempotency_key) NOT BETWEEN 1 AND 128 THEN
    RAISE EXCEPTION 'valid idempotency key is required' USING ERRCODE = '22023';
  END IF;

  SELECT array_agg(reviewer ORDER BY reviewer) INTO normalized_reviewers
  FROM (SELECT DISTINCT unnest(p_reviewer_user_ids) reviewer) reviewers
    WHERE reviewer IS NOT NULL AND reviewer <> '';
  IF coalesce(cardinality(normalized_reviewers), 0) = 0 THEN
    RAISE EXCEPTION 'at least one assigned reviewer is required' USING ERRCODE = '22023';
  END IF;
  IF EXISTS (
    SELECT 1 FROM unnest(normalized_reviewers) reviewer
    WHERE NOT EXISTS (
      SELECT 1 FROM api.workspace_memberships membership
      WHERE membership.workspace_id = claimed_workspace
        AND membership.user_id = reviewer
    )
  ) THEN
    RAISE EXCEPTION 'assigned reviewer is not a workspace member' USING ERRCODE = '42501';
  END IF;


  IF NOT EXISTS(SELECT 1 FROM internal.session WHERE id=session_id AND "userId"=actor AND "expiresAt">clock_timestamp()) THEN
    RAISE EXCEPTION 'valid submission session required' USING ERRCODE='SB002';
  END IF;
  SELECT coalesce((definition->>'requiresSignature')::boolean,false) INTO requires_author
    FROM internal.review_workflow_definitions WHERE definition_key=p_workflow_definition_key AND version=p_workflow_definition_version;
  signing_args:=internal.signature_submission_arguments(p_record_id,p_expected_source_digest,
    p_workflow_definition_key,p_workflow_definition_version,normalized_reviewers,p_confirmed,p_idempotency_key,p_due_at);
  -- Serialize identical submissions before examining idempotency, including
  -- two concurrent requests that would otherwise both observe absence.
  PERFORM pg_advisory_xact_lock(hashtextextended(claimed_workspace::text||':'||actor||':'||p_idempotency_key,0));
  SELECT * INTO existing_submission
  FROM api.review_submissions
  WHERE workspace_id = claimed_workspace
    AND submitted_by_user_id = actor
    AND idempotency_key = p_idempotency_key;
  IF existing_submission.id IS NOT NULL THEN
    SELECT * INTO existing_revision FROM api.revisions
    WHERE id = existing_submission.revision_id;
    IF existing_submission.record_id <> p_record_id
       OR existing_submission.workflow_definition_key <> p_workflow_definition_key
       OR existing_submission.workflow_definition_version <> p_workflow_definition_version
       OR existing_submission.assigned_reviewer_user_ids <> normalized_reviewers
       OR internal.revision_integrity_digest(internal.envelope_for_digest(existing_revision.canonical_snapshot)) IS DISTINCT FROM p_expected_source_digest
       OR existing_revision.integrity_digest IS DISTINCT FROM internal.revision_integrity_digest(existing_revision.canonical_snapshot) OR (p_due_at IS NOT NULL AND existing_submission.due_at IS DISTINCT FROM p_due_at) THEN
      RAISE EXCEPTION 'idempotency key was used for a different submission' USING ERRCODE = '23505';
    END IF;

    IF requires_author THEN
      SELECT * INTO author_signature FROM api.signatures WHERE submission_id=existing_submission.id
        AND signer_user_id=actor AND signature_meaning='authored';
      IF author_signature.id IS NULL OR author_signature.revision_integrity_digest IS DISTINCT FROM existing_revision.integrity_digest THEN
        RAISE EXCEPTION 'existing submission has no authored signature' USING ERRCODE='SB002';
      END IF;
      IF author_signature.signer_session_id IS DISTINCT FROM session_id
        OR author_signature.confirmation_phrase IS DISTINCT FROM p_author_confirmation_phrase THEN
        RAISE EXCEPTION 'authored retry identity mismatch' USING ERRCODE='SB002';
      END IF;
      signature_result:=jsonb_build_object('signatureId',author_signature.id,'submissionId',existing_submission.id,
        'revisionId',existing_revision.id,'signatureMeaning','authored','assuranceLevel','standard','signedAt',author_signature.signed_at);
    END IF;
    RETURN jsonb_build_object(
      'revision', jsonb_build_object('id', existing_revision.id, 'integrityDigest', existing_revision.integrity_digest),
      'submission', jsonb_build_object('id', existing_submission.id, 'state', existing_submission.state),
      'signature',signature_result,'idempotent', true
    );
  END IF;

  -- GOV-04: archived records fail closed exactly like deleted ones.
  SELECT * INTO record_row FROM api.records
  WHERE id = p_record_id
    AND workspace_id = claimed_workspace
    AND deleted_at IS NULL
    AND archived_at IS NULL
  FOR UPDATE;
  IF record_row.id IS NULL THEN
    RAISE EXCEPTION 'record denied' USING ERRCODE = '42501';
  END IF;

  -- MDL-02 step 2: model rules can block submission (`flag_block_submit` or
  -- `block`). Submission is the canonical gate for a record the write path
  -- accepted but flagged.
  PERFORM internal.assert_model_rules_allow_submit(
    record_row.workspace_id,
    internal.model_key_for('api.records', record_row.kind),
    record_row.custom_fields
  );

  -- Evidence boundary: allocate the revision UUID, bind unbound frozen
  -- evidence to it, and only then capture the envelope (snapshot) and digest.
  v_revision_id := gen_random_uuid();
  PERFORM "internal"."bind_frozen_evidence_for_submission"(
    record_row.id, v_revision_id
  );

  envelope := internal.build_revision_envelope(record_row.id);
  snapshot_digest := internal.revision_integrity_digest(envelope);
  actual_digest := internal.revision_integrity_digest(
    internal.envelope_for_digest(envelope)
  );
  IF actual_digest <> p_expected_source_digest THEN
    RAISE EXCEPTION 'submission source changed' USING ERRCODE = 'SB001';
  END IF;

  -- EXP-02.1: the readiness list and the submit block read the same function, so
  -- they cannot disagree. Only experiments are gated - the submit RPC serves every
  -- record kind. The digest above pins the source this list describes.
  IF record_row.kind = 'experiment'
     AND NOT (api.experiment_readiness(record_row.id)->>'ready')::boolean THEN
    RAISE EXCEPTION 'record is not ready for submission' USING ERRCODE = 'SB123',
      DETAIL = (api.experiment_readiness(record_row.id))::text;
  END IF;

  INSERT INTO api.revisions (
    id, record_id, workspace_id, structure_version, metadata_version,
    metadata_snapshot, block_snapshot, canonical_snapshot,
    integrity_algorithm, integrity_digest, reason, created_at, updated_at,
    created_by_user_id
  ) VALUES (
    v_revision_id, record_row.id, record_row.workspace_id,
    record_row.structure_version, record_row.metadata_version,
    envelope->'record', envelope->'blocks', envelope,
    'sha256', snapshot_digest, 'submit', submitted_at, submitted_at, actor
  ) RETURNING * INTO revision_row;

  INSERT INTO api.review_submissions (
    workspace_id, record_id, revision_id, state,
    workflow_definition_key, workflow_definition_version,
    assigned_reviewer_user_ids, submitted_by_user_id, submitted_at,
    submitted_session_id, submitted_role, idempotency_key, due_at,
    created_at, updated_at
  ) VALUES (
    claimed_workspace, record_row.id, revision_row.id, 'submitted',
    p_workflow_definition_key, p_workflow_definition_version,
    normalized_reviewers, actor, submitted_at, session_id, actor_role, p_idempotency_key,
    p_due_at,
    submitted_at, submitted_at
  ) RETURNING * INTO submission_row;


  PERFORM "internal"."persist_revision_sheet_evidence"(revision_row.id);
  IF requires_author THEN
    IF p_author_signing_token IS NULL THEN RAISE EXCEPTION 'fresh author password token required' USING ERRCODE='SB002'; END IF;
    author_grant:=internal.consume_signature_grant(p_author_signing_token,'author-submit',claimed_workspace,actor,session_id,NULL,actual_digest);
    IF author_grant.record_id IS DISTINCT FROM p_record_id OR author_grant.signature_meaning IS DISTINCT FROM 'authored'
      OR author_grant.submission_arguments IS DISTINCT FROM signing_args THEN
      RAISE EXCEPTION 'author token submission arguments mismatch' USING ERRCODE='SB002';
    END IF;
    signature_result:=internal.record_revision_signature(submission_row.id,actor,session_id,'authored',p_author_confirmation_phrase);
  END IF;

  RETURN jsonb_build_object(
    'revision', jsonb_build_object('id', revision_row.id, 'integrityDigest', revision_row.integrity_digest),
    'submission', jsonb_build_object('id', submission_row.id, 'state', submission_row.state),
    'signature',signature_result,'idempotent', false
  );
EXCEPTION WHEN unique_violation THEN
  SELECT * INTO existing_submission FROM api.review_submissions
   WHERE workspace_id = claimed_workspace
     AND submitted_by_user_id = actor
     AND idempotency_key = p_idempotency_key;
  SELECT * INTO existing_revision FROM api.revisions WHERE id = existing_submission.revision_id;
  IF existing_submission.id IS NULL
     OR existing_submission.record_id <> p_record_id
     OR existing_submission.workflow_definition_key <> p_workflow_definition_key
     OR existing_submission.workflow_definition_version <> p_workflow_definition_version
     OR (p_due_at IS NOT NULL AND existing_submission.due_at IS DISTINCT FROM p_due_at)
     OR existing_submission.assigned_reviewer_user_ids <> normalized_reviewers
     OR existing_revision.id IS NULL
     OR internal.revision_integrity_digest(internal.envelope_for_digest(existing_revision.canonical_snapshot)) IS DISTINCT FROM p_expected_source_digest
       OR existing_revision.integrity_digest IS DISTINCT FROM internal.revision_integrity_digest(existing_revision.canonical_snapshot) THEN
    RAISE EXCEPTION 'idempotency key was used for a different submission' USING ERRCODE = '23505';
  END IF;
  IF requires_author THEN
      SELECT * INTO author_signature FROM api.signatures WHERE submission_id=existing_submission.id
        AND signer_user_id=actor AND signature_meaning='authored';
      IF author_signature.id IS NULL OR author_signature.revision_integrity_digest IS DISTINCT FROM existing_revision.integrity_digest THEN
        RAISE EXCEPTION 'existing submission has no authored signature' USING ERRCODE='SB002';
      END IF;
      IF author_signature.signer_session_id IS DISTINCT FROM session_id
        OR author_signature.confirmation_phrase IS DISTINCT FROM p_author_confirmation_phrase THEN
        RAISE EXCEPTION 'authored retry identity mismatch' USING ERRCODE='SB002';
      END IF;
      signature_result:=jsonb_build_object('signatureId',author_signature.id,'submissionId',existing_submission.id,
        'revisionId',existing_revision.id,'signatureMeaning','authored','assuranceLevel','standard','signedAt',author_signature.signed_at);
    END IF;
  RETURN jsonb_build_object(
    'revision', jsonb_build_object('id', existing_revision.id, 'integrityDigest', existing_revision.integrity_digest),
    'submission', jsonb_build_object('id', existing_submission.id, 'state', existing_submission.state),
    'signature',signature_result,'idempotent', true
  );
END;
$_$;
--> statement-breakpoint
ALTER FUNCTION api.submit_record_revision(p_record_id uuid, p_expected_source_digest text, p_workflow_definition_key text, p_workflow_definition_version integer, p_reviewer_user_ids text[], p_confirmed boolean, p_idempotency_key text, p_due_at timestamp with time zone, p_author_signing_token text, p_author_confirmation_phrase text) OWNER TO migrator;
--> statement-breakpoint
CREATE FUNCTION api.submit_record_revision_core067(p_record_id uuid, p_expected_source_digest text, p_workflow_definition_key text, p_workflow_definition_version integer, p_reviewer_user_ids text[], p_confirmed boolean, p_idempotency_key text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $_$
DECLARE
  claimed_workspace uuid;
  actor text;
  session_id text;
  actor_role text;
  record_row api.records;
  envelope jsonb;
  actual_digest text;
  normalized_reviewers text[];
  revision_row api.revisions;
  submission_row api.review_submissions;
  existing_submission api.review_submissions;
  existing_revision api.revisions;
  submitted_at timestamptz := clock_timestamp();
BEGIN
  BEGIN
    claimed_workspace := nullif(api.claim_probe()->>'workspace_id', '')::uuid;
    actor := nullif(api.claim_probe()->>'sub', '');
    session_id := nullif(api.claim_probe()->>'session_id', '');
    actor_role := nullif(api.claim_probe()->>'role', '');
  EXCEPTION WHEN others THEN
    RAISE EXCEPTION 'record denied' USING ERRCODE = '42501';
  END;
  IF claimed_workspace IS NULL OR actor IS NULL OR session_id IS NULL
     OR actor_role <> 'authenticated' OR p_confirmed IS DISTINCT FROM true
     OR NOT api.is_workspace_member(claimed_workspace) THEN
    RAISE EXCEPTION 'record denied' USING ERRCODE = '42501';
  END IF;
  IF p_expected_source_digest IS NULL
     OR p_expected_source_digest !~ '^[0-9a-f]{64}$' THEN
    RAISE EXCEPTION 'expected source digest is required' USING ERRCODE = '22023';
  END IF;
  IF p_workflow_definition_key IS NULL
     OR p_workflow_definition_key !~ '^[a-z0-9][a-z0-9_-]{0,127}$'
     OR coalesce(p_workflow_definition_version, 0) < 1 THEN
    RAISE EXCEPTION 'versioned workflow definition is required' USING ERRCODE = '22023';
  END IF;
  IF NOT EXISTS (
    SELECT 1 FROM internal.review_workflow_definitions definition
    WHERE definition.definition_key = p_workflow_definition_key
      AND definition.version = p_workflow_definition_version
  ) THEN
    RAISE EXCEPTION 'unknown workflow definition version' USING ERRCODE = '22023';
  END IF;
  IF p_idempotency_key IS NULL OR length(p_idempotency_key) NOT BETWEEN 1 AND 128 THEN
    RAISE EXCEPTION 'valid idempotency key is required' USING ERRCODE = '22023';
  END IF;

  SELECT array_agg(reviewer ORDER BY reviewer) INTO normalized_reviewers
  FROM (SELECT DISTINCT unnest(p_reviewer_user_ids) reviewer) reviewers
  WHERE reviewer IS NOT NULL AND reviewer <> '';
  IF coalesce(cardinality(normalized_reviewers), 0) = 0 THEN
    RAISE EXCEPTION 'at least one assigned reviewer is required' USING ERRCODE = '22023';
  END IF;
  IF EXISTS (
    SELECT 1 FROM unnest(normalized_reviewers) reviewer
    WHERE NOT EXISTS (
      SELECT 1 FROM api.workspace_memberships membership
      WHERE membership.workspace_id = claimed_workspace
        AND membership.user_id = reviewer
    )
  ) THEN
    RAISE EXCEPTION 'assigned reviewer is not a workspace member' USING ERRCODE = '42501';
  END IF;

  SELECT * INTO existing_submission
  FROM api.review_submissions
  WHERE workspace_id = claimed_workspace
    AND submitted_by_user_id = actor
    AND idempotency_key = p_idempotency_key;
  IF existing_submission.id IS NOT NULL THEN
    SELECT * INTO existing_revision FROM api.revisions
    WHERE id = existing_submission.revision_id;
    IF existing_submission.record_id <> p_record_id
       OR existing_submission.workflow_definition_key <> p_workflow_definition_key
       OR existing_submission.workflow_definition_version <> p_workflow_definition_version
       OR existing_submission.assigned_reviewer_user_ids <> normalized_reviewers
       OR existing_revision.integrity_digest <> p_expected_source_digest THEN
      RAISE EXCEPTION 'idempotency key was used for a different submission' USING ERRCODE = '23505';
    END IF;
    RETURN jsonb_build_object(
      'revision', jsonb_build_object('id', existing_revision.id, 'integrityDigest', existing_revision.integrity_digest),
      'submission', jsonb_build_object('id', existing_submission.id, 'state', existing_submission.state),
      'idempotent', true
    );
  END IF;

  SELECT * INTO record_row FROM api.records
  WHERE id = p_record_id
    AND workspace_id = claimed_workspace
    AND deleted_at IS NULL
  FOR UPDATE;
  IF record_row.id IS NULL THEN
    RAISE EXCEPTION 'record denied' USING ERRCODE = '42501';
  END IF;

  envelope := internal.build_revision_envelope(record_row.id);
  actual_digest := internal.revision_integrity_digest(envelope);
  IF actual_digest <> p_expected_source_digest THEN
    RAISE EXCEPTION 'submission source changed' USING ERRCODE = 'SB001';
  END IF;

  INSERT INTO api.revisions (
    record_id, workspace_id, structure_version, metadata_version,
    metadata_snapshot, block_snapshot, canonical_snapshot,
    integrity_algorithm, integrity_digest, reason, created_at, updated_at,
    created_by_user_id
  ) VALUES (
    record_row.id, record_row.workspace_id, record_row.structure_version,
    record_row.metadata_version, envelope->'record', envelope->'blocks', envelope,
    'sha256', actual_digest, 'submit', submitted_at, submitted_at, actor
  ) RETURNING * INTO revision_row;

  INSERT INTO api.review_submissions (
    workspace_id, record_id, revision_id, state,
    workflow_definition_key, workflow_definition_version,
    assigned_reviewer_user_ids, submitted_by_user_id, submitted_at,
    submitted_session_id, submitted_role, idempotency_key, created_at, updated_at
  ) VALUES (
    claimed_workspace, record_row.id, revision_row.id, 'submitted',
    p_workflow_definition_key, p_workflow_definition_version,
    normalized_reviewers, actor, submitted_at, session_id, actor_role, p_idempotency_key,
    submitted_at, submitted_at
  ) RETURNING * INTO submission_row;

  RETURN jsonb_build_object(
    'revision', jsonb_build_object('id', revision_row.id, 'integrityDigest', revision_row.integrity_digest),
    'submission', jsonb_build_object('id', submission_row.id, 'state', submission_row.state),
    'idempotent', false
  );
EXCEPTION WHEN unique_violation THEN
  -- A concurrent retry may win the unique idempotency race. Re-read it and
  -- return the same result only when it describes this exact command.
  SELECT * INTO existing_submission
  FROM api.review_submissions
  WHERE workspace_id = claimed_workspace
    AND submitted_by_user_id = actor
    AND idempotency_key = p_idempotency_key;
  SELECT * INTO existing_revision FROM api.revisions
  WHERE id = existing_submission.revision_id;
  IF existing_submission.id IS NOT NULL
     AND existing_submission.record_id = p_record_id
     AND existing_submission.workflow_definition_key = p_workflow_definition_key
     AND existing_submission.workflow_definition_version = p_workflow_definition_version
     AND existing_submission.assigned_reviewer_user_ids = normalized_reviewers
     AND existing_revision.integrity_digest = p_expected_source_digest THEN
    RETURN jsonb_build_object(
      'revision', jsonb_build_object('id', existing_revision.id, 'integrityDigest', existing_revision.integrity_digest),
      'submission', jsonb_build_object('id', existing_submission.id, 'state', existing_submission.state),
      'idempotent', true
    );
  END IF;
  RAISE;
END;
$_$;
