CREATE FUNCTION api.transfer_sample(p_record_id uuid, p_to_location text, p_expected_metadata_version integer, p_notes text DEFAULT NULL::text) RETURNS api.records
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
DECLARE
  v_row "api"."records";
  v_from text;
  v_to text;
  v_props jsonb;
BEGIN
  v_to := btrim(COALESCE(p_to_location, ''));
  IF v_to = '' THEN
    RAISE EXCEPTION 'a destination location is required for transfer'
      USING ERRCODE = 'SB008';
  END IF;

  SELECT * INTO v_row FROM "api"."records" WHERE id = p_record_id FOR UPDATE;
  IF v_row IS NULL THEN
    RAISE EXCEPTION 'record not found in active workspace' USING ERRCODE = '42501';
  END IF;
  IF v_row.kind <> 'sample' THEN
    RAISE EXCEPTION 'record % is not a sample', p_record_id USING ERRCODE = 'SB009';
  END IF;
  IF v_row.archived_at IS NOT NULL THEN
    RAISE EXCEPTION 'cannot transfer an archived sample' USING ERRCODE = 'SB004';
  END IF;
  IF v_row.metadata_version <> p_expected_metadata_version THEN
    RAISE EXCEPTION 'metadata version mismatch: expected %, got %',
      p_expected_metadata_version, v_row.metadata_version USING ERRCODE = 'SB001';
  END IF;

  v_from := v_row.properties ->> 'storageLocation';
  IF v_from IS NOT NULL AND v_from = v_to THEN
    RAISE EXCEPTION 'sample is already at %', v_to USING ERRCODE = 'SB007';
  END IF;
  -- An untraceable move (no current location) is allowed only the first time:
  -- receiving establishes the location. A transfer must move FROM a known
  -- location TO a different one, so the chain of custody stays traceable.
  IF v_from IS NULL THEN
    RAISE EXCEPTION 'sample has no current location to transfer from; receive it first'
      USING ERRCODE = 'SB008';
  END IF;

  v_props := v_row.properties || jsonb_build_object('storageLocation', v_to);

  UPDATE "api"."records"
    SET properties = v_props,
        metadata_version = v_row.metadata_version + 1,
        updated_by_user_id = "api"."current_user_id"()
    WHERE id = p_record_id
    RETURNING * INTO v_row;

  INSERT INTO "api"."sample_events"
    (workspace_id, record_id, operation, from_location, to_location,
     actor_user_id, notes)
  VALUES
    (v_row.workspace_id, v_row.id, 'transfer', v_from, v_to,
     "api"."current_user_id"(), p_notes);

  RETURN v_row;
END;
$$;
--> statement-breakpoint
ALTER FUNCTION api.transfer_sample(p_record_id uuid, p_to_location text, p_expected_metadata_version integer, p_notes text) OWNER TO migrator;
--> statement-breakpoint
CREATE FUNCTION api.transition_file_status(p_file_id uuid, p_target_status text, p_expected_version integer, p_reason text DEFAULT NULL::text) RETURNS api.file_objects
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_row "api"."file_objects";
  v_transition_key text;
  v_allowed text[];
BEGIN
  SELECT * INTO v_row FROM "api"."file_objects" WHERE id = p_file_id FOR UPDATE;
  IF v_row IS NULL THEN
    RAISE EXCEPTION 'file object not found in active workspace' USING ERRCODE = '42501';
  END IF;
  IF v_row.version <> p_expected_version THEN
    RAISE EXCEPTION 'file version mismatch: expected %, got %',
      p_expected_version, v_row.version USING ERRCODE = 'SB001';
  END IF;

  v_transition_key := v_row.status || '->' || p_target_status;
  v_allowed := ARRAY[
    'active->quarantined',
    'quarantined->active',
    'active->deleted',
    'quarantined->deleted',
    'deleted->active',
    'active->missing',
    'quarantined->missing',
    'missing->active',
    'missing->quarantined',
    'missing->deleted'
  ];

  IF NOT (v_transition_key = ANY(v_allowed)) THEN
    RAISE EXCEPTION 'invalid file status transition: % -> %',
      v_row.status, p_target_status USING ERRCODE = 'SB004';
  END IF;

  UPDATE "api"."file_objects"
    SET
      status = p_target_status,
      status_reason = CASE
        WHEN p_target_status IN ('quarantined','missing') THEN p_reason
        ELSE NULL
      END,
      quarantined_at = CASE
        WHEN p_target_status = 'quarantined' THEN clock_timestamp()
        ELSE NULL
      END,
      deleted_at = CASE
        WHEN p_target_status = 'deleted' THEN clock_timestamp()
        ELSE NULL
      END,
      version = v_row.version + 1,
      updated_by_user_id = "api"."current_user_id"(),
      updated_at = clock_timestamp()
    WHERE id = p_file_id
    RETURNING * INTO v_row;

  RETURN v_row;
END;
$$;
--> statement-breakpoint
ALTER FUNCTION api.transition_file_status(p_file_id uuid, p_target_status text, p_expected_version integer, p_reason text) OWNER TO migrator;
--> statement-breakpoint
CREATE FUNCTION api.transition_record_status(p_record_id uuid, p_target_status text, p_expected_metadata_version integer) RETURNS api.records
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_row "api"."records";
  v_allowed text[];
  v_transition_key text;
BEGIN
  SELECT * INTO v_row FROM "api"."records" WHERE id = p_record_id FOR UPDATE;
  IF v_row IS NULL THEN
    RAISE EXCEPTION 'record not found in active workspace' USING ERRCODE = '42501';
  END IF;
  IF v_row.metadata_version <> p_expected_metadata_version THEN
    RAISE EXCEPTION 'metadata version mismatch: expected %, got %',
      p_expected_metadata_version, v_row.metadata_version USING ERRCODE = 'SB001';
  END IF;
  IF v_row.archived_at IS NOT NULL THEN
    RAISE EXCEPTION 'archived records are frozen; restore before transitioning'
      USING ERRCODE = 'SB004';
  END IF;

  v_transition_key := v_row.kind || ':' || v_row.status || '->' || p_target_status;
  v_allowed := ARRAY[
    'sample:available->reserved',
    'sample:available->consumed',
    'sample:available->quarantined',
    'sample:reserved->available',
    'sample:reserved->consumed',
    'sample:quarantined->available',
    'reagent:available->reserved',
    'reagent:available->consumed',
    'reagent:available->quarantined',
    'reagent:available->expired',
    'reagent:reserved->available',
    'reagent:reserved->consumed',
    'reagent:quarantined->available',
    'protocol_template:draft->active',
    'protocol_template:draft->under_review',
    'protocol_template:under_review->active',
    'protocol_template:under_review->draft',
    'protocol_template:active->draft',
    'notebook_template:draft->validated',
    'notebook_template:validated->draft'
  ];

  IF NOT (v_transition_key = ANY(v_allowed)) THEN
    RAISE EXCEPTION 'invalid status transition for kind %: % -> %',
      v_row.kind, v_row.status, p_target_status USING ERRCODE = 'SB004';
  END IF;

  UPDATE "api"."records"
    SET status = p_target_status,
        metadata_version = v_row.metadata_version + 1,
        updated_by_user_id = "api"."current_user_id"()
    WHERE id = p_record_id
    RETURNING * INTO v_row;

  RETURN v_row;
END;
$$;
--> statement-breakpoint
