CREATE FUNCTION api.unarchive_project(p_project_id uuid) RETURNS api.projects
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
  v api.projects;
BEGIN
 IF p_project_id IS NOT NULL THEN PERFORM internal.assert_object_access('project',p_project_id,'manage'); END IF;
  SELECT * INTO v FROM api.projects
    WHERE id = p_project_id AND workspace_id = api.current_workspace_id()
    FOR UPDATE;
  IF v.id IS NULL THEN
    RAISE EXCEPTION 'project not found in active workspace' USING ERRCODE = '42501';
  END IF;
  IF NOT EXISTS (
    SELECT 1 FROM api.workspace_memberships m
    WHERE m.workspace_id = v.workspace_id
      AND m.user_id = api.current_user_id()
      AND m.suspended_at IS NULL
      AND m.role IN ('owner', 'admin')
  ) THEN
    RAISE EXCEPTION 'admin role required' USING ERRCODE = '42501';
  END IF;
  IF v.archived_at IS NULL THEN
    RETURN v;
  END IF;
  UPDATE api.projects
    SET archived_at = NULL
    WHERE id = v.id
    RETURNING * INTO v;
  RETURN v;
END;
$$;
--> statement-breakpoint
ALTER FUNCTION api.unarchive_project(p_project_id uuid) OWNER TO migrator;
