CREATE FUNCTION api.unfreeze_analysis_block(p_block_id uuid, p_expected_version integer) RETURNS api.blocks
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
  v_block "api"."blocks";
  v_owner "api"."records";
  v_payload jsonb;
  v_frozen jsonb;
BEGIN
 IF p_block_id IS NOT NULL THEN PERFORM internal.assert_object_access('block',p_block_id,'edit'); END IF;
  SELECT * INTO v_block FROM "api"."blocks" WHERE id = p_block_id FOR UPDATE;
  IF v_block.id IS NULL THEN
    RAISE EXCEPTION 'block not found in active workspace' USING ERRCODE = '42501';
  END IF;
  IF v_block.type <> 'analysis' THEN
    RAISE EXCEPTION 'block is not an analysis' USING ERRCODE = '23514';
  END IF;
  IF v_block.version <> p_expected_version THEN
    RAISE EXCEPTION 'block version mismatch: expected %, got %',
      p_expected_version, v_block.version USING ERRCODE = 'SB001';
  END IF;
  IF jsonb_typeof(v_block.payload->'frozen') IS DISTINCT FROM 'object' THEN
    RAISE EXCEPTION 'analysis is not frozen' USING ERRCODE = '23514';
  END IF;

  SELECT * INTO v_owner FROM "api"."records" WHERE id = v_block.record_id;
  IF v_owner.id IS NULL THEN RAISE EXCEPTION 'block owner not found' USING ERRCODE = '23503'; END IF;
  IF v_owner.workspace_id IS DISTINCT FROM "api"."current_workspace_id"()
     OR NOT "api"."is_workspace_writer"(v_owner.workspace_id) THEN
    RAISE EXCEPTION 'block not found in active workspace' USING ERRCODE = '42501';
  END IF;

  v_frozen := v_block.payload->'frozen';
  IF v_frozen->>'revisionId' IS NOT NULL THEN
    RAISE EXCEPTION 'frozen analysis is locked into a submitted revision'
      USING ERRCODE = '23514';
  END IF;

  v_payload := v_block.payload #- ARRAY['frozen']::text[];

  UPDATE "api"."blocks"
    SET payload = v_payload,
        version = v_block.version + 1,
        updated_by_user_id = "api"."current_user_id"()
    WHERE id = p_block_id
    RETURNING * INTO v_block;

  RETURN v_block;
END;
$$;
--> statement-breakpoint
ALTER FUNCTION api.unfreeze_analysis_block(p_block_id uuid, p_expected_version integer) OWNER TO migrator;
--> statement-breakpoint
CREATE FUNCTION api.unfreeze_chart(p_block_id uuid, p_expected_version integer) RETURNS api.blocks
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
  v_block "api"."blocks";
  v_owner "api"."records";
  v_frozen jsonb;
  v_payload jsonb;
BEGIN
 IF p_block_id IS NOT NULL THEN PERFORM internal.assert_object_access('block',p_block_id,'edit'); END IF;
  SELECT * INTO v_block FROM "api"."blocks" WHERE id = p_block_id FOR UPDATE;
  IF v_block.id IS NULL THEN
    RAISE EXCEPTION 'block not found in active workspace' USING ERRCODE = '42501';
  END IF;
  IF v_block.type <> 'chart' THEN
    RAISE EXCEPTION 'block is not a chart' USING ERRCODE = '23514';
  END IF;
  IF v_block.version <> p_expected_version THEN
    RAISE EXCEPTION 'block version mismatch: expected %, got %',
      p_expected_version, v_block.version USING ERRCODE = 'SB001';
  END IF;
  SELECT * INTO v_owner FROM "api"."records" WHERE id = v_block.record_id;
  IF v_owner.id IS NULL
     OR v_owner.workspace_id IS DISTINCT FROM "api"."current_workspace_id"()
     OR NOT api.is_workspace_writer(v_owner.workspace_id) THEN
    RAISE EXCEPTION 'block not found in active workspace' USING ERRCODE = '42501';
  END IF;
  v_frozen := v_block.payload->'frozen';
  IF jsonb_typeof(v_frozen) IS DISTINCT FROM 'object' THEN
    RAISE EXCEPTION 'chart is not frozen' USING ERRCODE = '23514';
  END IF;
  -- A freeze tied to a revision is evidence and must not be undone.
  IF v_frozen->>'revisionId' IS NOT NULL THEN
    RAISE EXCEPTION 'frozen chart is tied to a revision' USING ERRCODE = '23514';
  END IF;
  -- Remove the frozen key entirely so validate_scientific_block sees
  -- payload->'frozen' IS NULL (a missing key, not a JSON null scalar).
  v_payload := v_block.payload - 'frozen';
  UPDATE "api"."blocks"
    SET payload = v_payload,
        version = v_block.version + 1,
        updated_by_user_id = "api"."current_user_id"()
    WHERE id = p_block_id
    RETURNING * INTO v_block;
  RETURN v_block;
END;
$$;
--> statement-breakpoint
ALTER FUNCTION api.unfreeze_chart(p_block_id uuid, p_expected_version integer) OWNER TO migrator;
--> statement-breakpoint
