CREATE FUNCTION api.update_block_payload(p_block_id uuid, p_payload jsonb, p_expected_version integer, p_payload_schema_version integer DEFAULT 1) RETURNS api.blocks
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_row "api"."blocks";
BEGIN
  -- Lock under RLS: a block in another workspace is invisible, so the row
  -- is null and we fail closed as permission_denied (no existence leak).
  SELECT * INTO v_row FROM "api"."blocks" WHERE id = p_block_id FOR UPDATE;
  IF v_row IS NULL THEN
    RAISE EXCEPTION 'block not found in active workspace' USING ERRCODE = '42501';
  END IF;
  IF v_row.version <> p_expected_version THEN
    RAISE EXCEPTION 'block version mismatch: expected %, got %',
      p_expected_version, v_row.version USING ERRCODE = 'SB001';
  END IF;

  IF v_row.type = 'sheet'
     AND (
       (v_row.payload ? 'templatePlacementId') <> (p_payload ? 'templatePlacementId')
       OR (
         p_payload ? 'templatePlacementId'
         AND v_row.payload->>'templatePlacementId' IS DISTINCT FROM p_payload->>'templatePlacementId'
       )
     ) THEN
    RAISE EXCEPTION 'templatePlacementId is system-managed and cannot be changed via update_block_payload'
      USING ERRCODE = '23514';
  END IF;

  UPDATE "api"."blocks"
    SET payload = p_payload,
        payload_schema_version = p_payload_schema_version,
        version = v_row.version + 1,
        updated_by_user_id = "api"."current_user_id"()
    WHERE id = p_block_id
    RETURNING * INTO v_row;

  RETURN v_row;
END;
$$;
--> statement-breakpoint
ALTER FUNCTION api.update_block_payload(p_block_id uuid, p_payload jsonb, p_expected_version integer, p_payload_schema_version integer) OWNER TO migrator;
--> statement-breakpoint
CREATE FUNCTION api.update_connector(p_workspace_id uuid, p_connector_id uuid, p_name text DEFAULT NULL::text, p_status text DEFAULT NULL::text, p_config jsonb DEFAULT NULL::jsonb) RETURNS api.connectors
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
  v api.connectors;
BEGIN
  IF api.current_workspace_id() IS DISTINCT FROM p_workspace_id THEN
    RAISE EXCEPTION 'wrong workspace' USING ERRCODE = 'SB033';
  END IF;
  PERFORM api.require_capability(p_workspace_id, 'integrations.manage');
  SELECT * INTO v FROM api.connectors
   WHERE id = p_connector_id AND workspace_id = p_workspace_id FOR UPDATE;
  IF v IS NULL THEN
    RAISE EXCEPTION 'connector not found' USING ERRCODE = 'SB036';
  END IF;
  IF p_status IS NOT NULL AND p_status NOT IN ('active', 'paused', 'archived') THEN
    RAISE EXCEPTION 'invalid connector status' USING ERRCODE = 'SB034';
  END IF;
  UPDATE api.connectors SET
    name = COALESCE(NULLIF(btrim(p_name), ''), name),
    status = COALESCE(p_status, status),
    config = COALESCE(p_config, config),
    updated_at = now(),
    updated_by_user_id = api.current_user_id()
  WHERE id = p_connector_id
  RETURNING * INTO v;
  RETURN v;
END $$;
