CREATE FUNCTION api.update_pipeline_schedule(p_workspace_id uuid, p_schedule_id uuid, p_kind text DEFAULT NULL::text, p_spec jsonb DEFAULT NULL::jsonb, p_enabled boolean DEFAULT NULL::boolean) RETURNS api.pipeline_schedules
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
  v api.pipeline_schedules;
  v_kind text;
  v_spec jsonb;
  v_resuming boolean;
  v_fast_forward boolean;
BEGIN
  IF api.current_workspace_id() IS DISTINCT FROM p_workspace_id THEN
    RAISE EXCEPTION 'wrong workspace' USING ERRCODE = 'SB033';
  END IF;
  PERFORM api.require_capability(p_workspace_id, 'pipelines.manage');
  SELECT * INTO v FROM api.pipeline_schedules
   WHERE id = p_schedule_id AND workspace_id = p_workspace_id FOR UPDATE;
  IF v IS NULL THEN
    RAISE EXCEPTION 'pipeline schedule not found' USING ERRCODE = 'SB036';
  END IF;
  v_kind := COALESCE(p_kind, v.kind);
  IF v_kind NOT IN ('interval', 'daily', 'cron', 'event') THEN
    RAISE EXCEPTION 'invalid schedule kind' USING ERRCODE = 'SB034';
  END IF;
  v_spec := api.validate_pipeline_schedule_spec(
    p_workspace_id, v_kind, COALESCE(p_spec, v.spec)
  );
  v_resuming := p_enabled IS TRUE AND NOT v.enabled;
  -- An event trigger resumed (or switched to events) under the skip policy
  -- ignores what happened while it was off; under run_once the waiting events
  -- are processed.
  v_fast_forward := v_kind = 'event' AND (
    v.kind <> 'event'
    OR (v_resuming AND COALESCE(v_spec->>'missedRunPolicy', 'run_once') = 'skip')
  );
  UPDATE api.pipeline_schedules SET
    kind = v_kind,
    spec = v_spec,
    enabled = COALESCE(p_enabled, enabled),
    next_run_at = api.pipeline_schedule_next_run(v_kind, v_spec, now()),
    last_evaluated_sequence = CASE
      WHEN v_fast_forward THEN COALESCE((
        SELECT max(sequence) FROM api.change_events WHERE workspace_id = p_workspace_id
      ), 0)
      ELSE last_evaluated_sequence
    END,
    updated_at = now()
  WHERE id = p_schedule_id
  RETURNING * INTO v;
  RETURN v;
END $$;
--> statement-breakpoint
ALTER FUNCTION api.update_pipeline_schedule(p_workspace_id uuid, p_schedule_id uuid, p_kind text, p_spec jsonb, p_enabled boolean) OWNER TO migrator;
--> statement-breakpoint
CREATE FUNCTION api.update_project_details(p_project_id uuid, p_expected_revision bigint, p_title text DEFAULT NULL::text, p_client_id uuid DEFAULT NULL::uuid, p_modality text DEFAULT NULL::text, p_stage text DEFAULT NULL::text, p_lead_user_id text DEFAULT NULL::text, p_default_reviewer_user_id text DEFAULT NULL::text, p_agreement_reference text DEFAULT NULL::text, p_started_on date DEFAULT NULL::date) RETURNS api.projects
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
  v_row api.projects;
BEGIN
 IF p_project_id IS NOT NULL THEN PERFORM internal.assert_object_access('project',p_project_id,'manage'); END IF;
  SELECT * INTO v_row FROM api.projects WHERE id = p_project_id FOR UPDATE;
  IF v_row.id IS NULL
     OR v_row.workspace_id IS DISTINCT FROM api.current_workspace_id()
     OR NOT api.is_workspace_writer(v_row.workspace_id) THEN
    RAISE EXCEPTION 'project not found in active workspace' USING ERRCODE = '42501';
  END IF;
  IF v_row.revision <> p_expected_revision THEN
    RAISE EXCEPTION 'stale project revision' USING ERRCODE = 'SB001';
  END IF;
  IF p_client_id IS NOT NULL AND NOT EXISTS (
    SELECT 1 FROM api.clients c WHERE c.id = p_client_id AND c.workspace_id = v_row.workspace_id
  ) THEN
    RAISE EXCEPTION 'client not found in active workspace' USING ERRCODE = '42501';
  END IF;
  IF p_lead_user_id IS NOT NULL AND NOT EXISTS (
    SELECT 1 FROM api.workspace_memberships m
    WHERE m.workspace_id = v_row.workspace_id AND m.user_id = p_lead_user_id
  ) THEN
    RAISE EXCEPTION 'lead is not a workspace member' USING ERRCODE = '42501';
  END IF;
  IF length(btrim(coalesce(p_title, ''))) NOT BETWEEN 1 AND 300 THEN
    RAISE EXCEPTION 'project title must be 1–300 characters' USING ERRCODE = '22023';
  END IF;

  UPDATE api.projects SET
    title = btrim(p_title),
    client_id = p_client_id,
    modality = p_modality,
    stage = p_stage,
    lead_user_id = p_lead_user_id,
    default_reviewer_user_id = p_default_reviewer_user_id,
    agreement_reference = p_agreement_reference,
    started_on = p_started_on,
    revision = revision + 1,
    updated_at = now()
  WHERE id = p_project_id
  RETURNING * INTO v_row;
  RETURN v_row;
END;
$$;
--> statement-breakpoint
