CREATE FUNCTION api.update_project_settings(p_project_id uuid, p_require_effective_protocol boolean DEFAULT NULL::boolean, p_require_independent_reviewer boolean DEFAULT NULL::boolean, p_auto_share_to_client boolean DEFAULT NULL::boolean) RETURNS api.projects
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
  v api.projects;
BEGIN
 IF p_project_id IS NOT NULL THEN PERFORM internal.assert_object_access('project',p_project_id,'manage'); END IF;
  SELECT * INTO v FROM api.projects
    WHERE id = p_project_id AND workspace_id = api.current_workspace_id()
    FOR UPDATE;
  IF v.id IS NULL THEN
    RAISE EXCEPTION 'project not found in active workspace' USING ERRCODE = '42501';
  END IF;
  IF NOT EXISTS (
    SELECT 1 FROM api.workspace_memberships m
    WHERE m.workspace_id = v.workspace_id
      AND m.user_id = api.current_user_id()
      AND m.suspended_at IS NULL
      AND m.role IN ('owner', 'admin')
  ) THEN
    RAISE EXCEPTION 'admin role required' USING ERRCODE = '42501';
  END IF;
  UPDATE api.projects
    SET require_effective_protocol = coalesce(p_require_effective_protocol, require_effective_protocol),
        require_independent_reviewer = coalesce(p_require_independent_reviewer, require_independent_reviewer),
        auto_share_to_client = coalesce(p_auto_share_to_client, auto_share_to_client)
    WHERE id = v.id
    RETURNING * INTO v;
  IF p_auto_share_to_client IS TRUE AND v.client_id IS NOT NULL THEN
    INSERT INTO api.project_access(workspace_id, project_id, user_id, can_view, can_edit, can_review, client_portal, can_manage, granted_by_user_id)
    SELECT v.workspace_id, v.id, m.user_id, false, false, false, true, false, api.current_user_id()
      FROM api.workspace_memberships m
     WHERE m.workspace_id = v.workspace_id
       AND m.suspended_at IS NULL
       AND m.role = 'client_viewer'
       AND m.client_id = v.client_id
    ON CONFLICT (workspace_id, project_id, user_id)
    DO UPDATE SET client_portal = true, updated_at = now();
  END IF;
  RETURN v;
END;
$$;
