  WHERE id=p_section_id AND workspace_id=p_workspace_id RETURNING * INTO v;
  IF v IS NULL THEN RAISE EXCEPTION 'section not found' USING ERRCODE='SB048'; END IF;
  RETURN v;
END $$;
