CREATE FUNCTION api.upgrade_record_model_record(p_record_id uuid, p_version_id uuid, p_expected_metadata_version bigint, p_reason text) RETURNS api.records
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
  v_record "api"."records";
  v_version "api"."record_model_versions";
  v_model "api"."record_models";
  v_row "api"."records";
BEGIN
  SELECT * INTO v_record FROM api.records WHERE id = p_record_id FOR UPDATE;
  IF v_record.id IS NULL OR v_record.workspace_id IS DISTINCT FROM api.current_workspace_id() THEN
    RAISE EXCEPTION 'Record not found' USING ERRCODE = '42501';
  END IF;
  PERFORM api.require_capability(v_record.workspace_id, 'schema.edit');
  IF p_expected_metadata_version IS NULL OR p_expected_metadata_version IS DISTINCT FROM v_record.metadata_version THEN
    RAISE EXCEPTION 'stale Record metadata revision' USING ERRCODE = 'SB001';
  END IF;
  SELECT * INTO v_version FROM api.record_model_versions WHERE id = p_version_id;
  IF v_version.id IS NULL OR v_version.workspace_id IS DISTINCT FROM v_record.workspace_id OR v_version.lifecycle <> 'published' THEN
    RAISE EXCEPTION 'published Record Model version not found' USING ERRCODE = '42501';
  END IF;
  SELECT * INTO v_model FROM api.record_models WHERE id = v_version.model_id;
  IF v_model.key IS DISTINCT FROM v_record.kind THEN
    RAISE EXCEPTION 'version does not belong to the Record model' USING ERRCODE = '22023';
  END IF;
  IF p_reason IS NULL OR length(btrim(p_reason)) NOT BETWEEN 1 AND 2000 THEN
    RAISE EXCEPTION 'an upgrade reason is required' USING ERRCODE = '22023';
  END IF;
  IF v_record.model_version_id=v_version.id THEN RETURN v_record; END IF;
  IF EXISTS(SELECT 1 FROM api.record_model_versions old_version WHERE old_version.id=v_record.model_version_id AND old_version.version>=v_version.version) THEN
    RAISE EXCEPTION 'Record Model versions cannot move backwards' USING ERRCODE='SB071';
  END IF;
  IF EXISTS (
    SELECT 1 FROM api.record_model_versions old_version
    CROSS JOIN LATERAL jsonb_array_elements(old_version.definition->'fields') old_field
    LEFT JOIN LATERAL (SELECT f FROM jsonb_array_elements(v_version.definition->'fields') f
      WHERE f->>'id'=old_field->>'id') target ON true
    WHERE old_version.id=v_record.model_version_id AND v_record.custom_fields ? (old_field->>'field_name')
      AND (target.f IS NULL OR old_field->>'field_name' IS DISTINCT FROM target.f->>'field_name'
        OR old_field->>'logical_type' IS DISTINCT FROM target.f->>'logical_type'
        OR old_field->'quantity' IS DISTINCT FROM target.f->'quantity'
        OR old_field->'relationship' IS DISTINCT FROM target.f->'relationship'
        OR (old_field->>'logical_type'='category' AND EXISTS (
          SELECT 1 FROM jsonb_array_elements(coalesce(old_field->'options','[]'::jsonb)) old_option
          WHERE old_option->>'key'=v_record.custom_fields->>(old_field->>'field_name')
            AND NOT EXISTS (
              SELECT 1 FROM jsonb_array_elements(coalesce(target.f->'options','[]'::jsonb)) new_option
              WHERE new_option->>'key'=old_option->>'key'
                AND new_option->>'id' IS NOT DISTINCT FROM old_option->>'id'
                AND new_option->>'label' IS NOT DISTINCT FROM old_option->>'label'
            )
        )))
  ) THEN RAISE EXCEPTION 'upgrade changes stored field meaning; explicit value migration required' USING ERRCODE='SB071'; END IF;
  PERFORM set_config('sheetbase.record_model_upgrade',v_record.id::text,true);
  UPDATE api.records
     SET model_version_id = v_version.id, metadata_version = v_record.metadata_version + 1,
         updated_at = now(), updated_by_user_id = api.current_user_id()
   WHERE id = v_record.id
  RETURNING * INTO v_row;
  PERFORM set_config('sheetbase.record_model_upgrade','',true);
  INSERT INTO api.record_model_version_upgrades(workspace_id, record_id, from_version_id, to_version_id, reason, upgraded_by_user_id)
  VALUES (v_record.workspace_id, v_record.id, v_record.model_version_id, v_version.id, btrim(p_reason), api.current_user_id());
  PERFORM internal.emit_change_event(v_record.workspace_id, 'record', v_record.id, 'update', v_record.id, v_record.project_id,
    jsonb_build_object('effect', 'model_version_upgrade', 'modelVersionId', v_version.id, 'reason', btrim(p_reason)));
  RETURN v_row;
END $$;
--> statement-breakpoint
ALTER FUNCTION api.upgrade_record_model_record(p_record_id uuid, p_version_id uuid, p_expected_metadata_version bigint, p_reason text) OWNER TO migrator;
--> statement-breakpoint
CREATE FUNCTION api.upgrade_scientific_schema(p_table_id uuid, p_target_revision integer) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE t api.scientific_tables; a jsonb; s_cur api.dataset_schemas; s_tgt api.dataset_schemas; f_cur api.dataset_schema_fields; f_tgt api.dataset_schema_fields; missing text; type_mismatch text; fn text; colid uuid; compiled jsonb; spec jsonb; chk text; added uuid[];
BEGIN
  PERFORM "internal"."require_migrator_legacy_sheet_write"();
  SELECT * INTO t FROM api.scientific_tables WHERE id=p_table_id FOR UPDATE;
  IF t.id IS NULL THEN RAISE EXCEPTION 'table not found' USING ERRCODE='P0002'; END IF;
  IF t.dataset_schema_id IS NULL THEN RAISE EXCEPTION 'table is not bound to a dataset schema' USING ERRCODE='23514'; END IF;
  a := internal.assert_scientific_actor(t.workspace_id);
  -- The table is bound to a specific revision row (t.dataset_schema_id). The
  -- target is a different published row of the same slug + workspace.
  SELECT * INTO s_cur FROM api.dataset_schemas WHERE id=t.dataset_schema_id;
  SELECT * INTO s_tgt FROM api.dataset_schemas WHERE workspace_id=s_cur.workspace_id AND slug=s_cur.slug AND revision=p_target_revision AND status='published';
  IF s_tgt.id IS NULL THEN RAISE EXCEPTION 'target revision is not a published revision of this schema' USING ERRCODE='23514'; END IF;
  IF s_tgt.revision = t.dataset_schema_revision THEN RAISE EXCEPTION 'table is already bound to the target revision' USING ERRCODE='23514'; END IF;
  -- Additive check: every active field in the current revision must exist in
  -- the target with the same logical_type. Each revision is a separate
  -- dataset_schemas row, so fields are matched by slug across the two rows.
  SELECT string_agg(c.slug,', ') INTO missing
    FROM api.dataset_schema_fields c
    WHERE c.schema_id=s_cur.id AND c.lifecycle='active'
      AND NOT EXISTS (SELECT 1 FROM api.dataset_schema_fields g WHERE g.schema_id=s_tgt.id AND g.slug=c.slug AND g.lifecycle='active');
  IF missing IS NOT NULL THEN RAISE EXCEPTION 'target revision is missing active field(s): %', missing USING ERRCODE='23514'; END IF;
  SELECT string_agg(c.slug,', ') INTO type_mismatch
    FROM api.dataset_schema_fields c
    JOIN api.dataset_schema_fields g ON g.schema_id=s_tgt.id AND g.slug=c.slug
    WHERE c.schema_id=s_cur.id AND c.lifecycle='active'
      AND c.logical_type<>g.logical_type;
  IF type_mismatch IS NOT NULL THEN RAISE EXCEPTION 'target revision changes type of field(s): %; create a new sheet or use per-column conversion', type_mismatch USING ERRCODE='23514'; END IF;
  -- Re-bind existing columns to the target revision's field identities (matched
  -- by slug across the two revision rows) and add new physical columns for
  -- target fields that have no current-revision counterpart. Each revision is
  -- a separate dataset_schemas row with its own dataset_schema_fields rows, so
  -- the stable cross-revision key is the slug, not the field id.
  FOR f_tgt IN SELECT * FROM api.dataset_schema_fields WHERE schema_id=s_tgt.id AND lifecycle='active' ORDER BY display_order LOOP
    SELECT sc.id INTO colid FROM api.scientific_columns sc
      JOIN api.dataset_schema_fields cf ON cf.id=sc.dataset_schema_field_id AND cf.schema_id=s_cur.id
      WHERE sc.table_id=t.id AND cf.slug=f_tgt.slug AND sc.lifecycle='active';
    IF colid IS NOT NULL THEN
      UPDATE api.scientific_columns SET dataset_schema_field_id=f_tgt.id, updated_at=now() WHERE id=colid;
    ELSE
      spec := jsonb_build_object('label',f_tgt.label,'logical_type',f_tgt.logical_type,'nullable',f_tgt.nullable,'validation',coalesce(f_tgt.validation,'{}'::jsonb))
        || CASE WHEN f_tgt.default_value IS NULL THEN '{}' ELSE jsonb_build_object('default',f_tgt.default_value) END
        || CASE WHEN f_tgt.unit IS NULL THEN '{}' ELSE jsonb_build_object('unit',f_tgt.unit) END;
      compiled := internal.compile_scientific_column(spec);
      LOOP fn := internal.scientific_name('col_'); EXIT WHEN NOT EXISTS(SELECT 1 FROM api.scientific_columns WHERE field_name=fn); END LOOP;
      colid := gen_random_uuid();
      INSERT INTO api.scientific_columns(id,table_id,workspace_id,field_name,label,description,display_order,logical_type,nullable,default_value,unit,validation,created_by_user_id,created_by_credential_id,dataset_schema_field_id)
        VALUES(colid,t.id,t.workspace_id,fn,f_tgt.label,f_tgt.description,f_tgt.display_order,f_tgt.logical_type,f_tgt.nullable,f_tgt.default_value,f_tgt.unit,coalesce(f_tgt.validation,'{}'),a->>'user_id',(a->>'credential_id')::uuid,f_tgt.id);
      EXECUTE format('ALTER TABLE api.%I ADD COLUMN %I %s%s%s',t.resource_name,fn,compiled->>'storageType',compiled->>'defaultSql',compiled->>'notNullSql');
      FOR chk IN SELECT value#>>'{}' FROM jsonb_array_elements(compiled->'checks') LOOP EXECUTE format('ALTER TABLE api.%I ADD CHECK (%s)',t.resource_name,internal.render_scientific_check(chk::jsonb,fn)); END LOOP;
      EXECUTE format('GRANT INSERT (%I), UPDATE (%I) ON api.%I TO authenticated',fn,fn,t.resource_name);
      added := array_append(added,colid);
    END IF;
  END LOOP;
  UPDATE api.scientific_tables SET dataset_schema_id=s_tgt.id, dataset_schema_revision=p_target_revision, schema_version=schema_version+1, updated_at=now(), updated_by_user_id=a->>'user_id' WHERE id=t.id;
  PERFORM internal.emit_change_event(t.workspace_id,'scientific_table',t.id,'update',t.record_id,NULL,jsonb_build_object('operation','upgrade_schema','datasetSchemaId',s_tgt.id,'fromRevision',t.dataset_schema_revision,'toRevision',p_target_revision,'addedColumnIds',COALESCE(to_jsonb(added),'[]'::jsonb),'schemaVersion',t.schema_version+1));
  PERFORM pg_notify('pgrst','reload schema');
  RETURN jsonb_build_object('upgraded',true,'tableId',t.id,'fromRevision',t.dataset_schema_revision,'toRevision',p_target_revision,'addedColumnIds',COALESCE(to_jsonb(added),'[]'::jsonb));
END $$;
--> statement-breakpoint
ALTER FUNCTION api.upgrade_scientific_schema(p_table_id uuid, p_target_revision integer) OWNER TO migrator;
--> statement-breakpoint
CREATE FUNCTION api.validate_chart_spec_maturity(p_spec jsonb) RETURNS void
    LANGUAGE plpgsql IMMUTABLE PARALLEL SAFE
    SET search_path TO ''
    AS $$
DECLARE
  ctype text := p_spec->>'type';
  fit jsonb := p_spec#>'{overlays,fit}';
  refs jsonb := p_spec#>'{overlays,references}';
  eb jsonb := p_spec#>'{overlays,errorBars}';
  params jsonb := COALESCE(p_spec->'typeParams', '{}'::jsonb);
  item jsonb;
  degree numeric;
  jitter float8;
  multiplier float8;
BEGIN
  IF jsonb_typeof(fit) = 'object' THEN
    IF fit->>'method' IS DISTINCT FROM 'ols' THEN
      RAISE EXCEPTION 'overlays.fit must be OLS with degree 1–4' USING ERRCODE='23514';
    END IF;
    IF fit ? 'degree' THEN
      IF jsonb_typeof(fit->'degree') IS DISTINCT FROM 'number' THEN
        RAISE EXCEPTION 'overlays.fit must be OLS with degree 1–4' USING ERRCODE='23514';
      END IF;
      degree := (fit->>'degree')::numeric;
      IF degree IS NULL OR degree <> trunc(degree) OR degree < 1 OR degree > 4 THEN
        RAISE EXCEPTION 'overlays.fit must be OLS with degree 1–4' USING ERRCODE='23514';
      END IF;
    END IF;
  END IF;

  IF jsonb_typeof(eb) = 'object' THEN
    IF (jsonb_typeof(eb->'lowerFieldId') = 'string')
         IS DISTINCT FROM (jsonb_typeof(eb->'upperFieldId') = 'string') THEN
      RAISE EXCEPTION 'errorBars.lowerFieldId and errorBars.upperFieldId must be provided together'
        USING ERRCODE='23514';
    END IF;
    IF jsonb_typeof(eb->'lowerFieldId') = 'string' THEN
      BEGIN
        PERFORM (eb->>'lowerFieldId')::uuid;
        PERFORM (eb->>'upperFieldId')::uuid;
      EXCEPTION WHEN invalid_text_representation THEN
        RAISE EXCEPTION 'errorBars.lowerFieldId and errorBars.upperFieldId must be UUIDs'
          USING ERRCODE='23514';
      END;
    END IF;
    IF eb ? 'multiplier' THEN
      IF jsonb_typeof(eb->'multiplier') IS DISTINCT FROM 'number' THEN
        RAISE EXCEPTION 'errorBars.multiplier must be a positive finite number' USING ERRCODE='23514';
      END IF;
      multiplier := (eb->>'multiplier')::float8;
      IF multiplier IS NULL OR multiplier <= 0 OR multiplier = 'NaN'::float8
         OR multiplier = 'Infinity'::float8 OR multiplier = '-Infinity'::float8 THEN
        RAISE EXCEPTION 'errorBars.multiplier must be a positive finite number' USING ERRCODE='23514';
      END IF;
    END IF;
  END IF;

  IF refs IS NOT NULL AND refs <> 'null'::jsonb THEN
    IF jsonb_typeof(refs) IS DISTINCT FROM 'array' THEN
      RAISE EXCEPTION 'overlays.references must be an array when present' USING ERRCODE='23514';
    END IF;
    IF jsonb_array_length(refs) > 12 THEN
      RAISE EXCEPTION 'overlays.references supports at most 12 entries' USING ERRCODE='23514';
    END IF;
    FOR item IN SELECT value FROM jsonb_array_elements(refs) LOOP
      IF jsonb_typeof(item) IS DISTINCT FROM 'object' OR item->>'kind' IS NULL THEN
        RAISE EXCEPTION 'invalid reference overlay' USING ERRCODE='23514';
      END IF;
      IF item->>'kind' IN ('hline','vline') THEN
        IF jsonb_typeof(item->'value') IS DISTINCT FROM 'number'
           OR (item->>'value')::float8 IS NULL
           OR jsonb_typeof(item->'label') IS DISTINCT FROM 'string'
           OR btrim(item->>'label')='' THEN
          RAISE EXCEPTION 'invalid reference overlay' USING ERRCODE='23514';
        END IF;
      ELSIF item->>'kind' = 'band' THEN
        IF item->>'axis' NOT IN ('x','y')
           OR jsonb_typeof(item->'lo') IS DISTINCT FROM 'number'
           OR jsonb_typeof(item->'hi') IS DISTINCT FROM 'number'
           OR (item->>'lo')::float8 IS NULL
           OR (item->>'hi')::float8 IS NULL
           OR jsonb_typeof(item->'label') IS DISTINCT FROM 'string'
           OR btrim(item->>'label')='' THEN
          RAISE EXCEPTION 'invalid reference overlay' USING ERRCODE='23514';
        END IF;
      ELSIF item->>'kind' = 'identity' THEN
        IF item ? 'label' AND jsonb_typeof(item->'label') IS DISTINCT FROM 'string' THEN
          RAISE EXCEPTION 'invalid reference overlay' USING ERRCODE='23514';
        END IF;
      ELSE
        RAISE EXCEPTION 'invalid reference overlay' USING ERRCODE='23514';
      END IF;
    END LOOP;
  END IF;

  IF params ? 'bar' AND ctype NOT IN ('bar','grouped_bar','stacked_bar') THEN
    RAISE EXCEPTION 'typeParams.bar only applies to bar charts' USING ERRCODE='23514';
  END IF;
  IF params ? 'strip' AND ctype <> 'strip' THEN
    RAISE EXCEPTION 'typeParams.strip only applies to strip charts' USING ERRCODE='23514';
  END IF;
  IF params ? 'summary' AND ctype <> 'summary' THEN
    RAISE EXCEPTION 'typeParams.summary only applies to summary charts' USING ERRCODE='23514';
  END IF;

  IF jsonb_typeof(params->'bar') = 'object'
     AND params->'bar' ? 'stacking'
     AND (params->'bar')->>'stacking' NOT IN ('grouped','stacked') THEN
    RAISE EXCEPTION 'invalid bar stacking' USING ERRCODE='23514';
  END IF;

  IF jsonb_typeof(params->'strip') = 'object' AND params->'strip' ? 'jitter' THEN
    IF jsonb_typeof(params#>'{strip,jitter}') IS DISTINCT FROM 'number' THEN
      RAISE EXCEPTION 'strip jitter must be between 0 and 1' USING ERRCODE='23514';
    END IF;
    jitter := (params#>>'{strip,jitter}')::float8;
    IF jitter IS NULL OR jitter < 0 OR jitter > 1
       OR jitter = 'NaN'::float8 OR jitter = 'Infinity'::float8
       OR jitter = '-Infinity'::float8 THEN
      RAISE EXCEPTION 'strip jitter must be between 0 and 1' USING ERRCODE='23514';
    END IF;
  END IF;

  IF jsonb_typeof(params->'summary') = 'object'
     AND params->'summary' ? 'statistic'
     AND (params->'summary')->>'statistic' NOT IN ('mean','median') THEN
    RAISE EXCEPTION 'invalid summary statistic' USING ERRCODE='23514';
  END IF;
END;
$$;
--> statement-breakpoint
ALTER FUNCTION api.validate_chart_spec_maturity(p_spec jsonb) OWNER TO migrator;
--> statement-breakpoint
CREATE FUNCTION api.validate_dataset_row_batch(p_dataset_id uuid, p_expected_dataset_revision bigint, p_rows jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $_$
#variable_conflict use_variable
DECLARE dataset api.datasets; item jsonb; cell jsonb; field api.dataset_schema_version_fields; v_field_id uuid; key text; row_id uuid; existing_row api.dataset_rows; row_index integer:=0; errors jsonb:='[]'::jsonb; error_code text; effective jsonb; seen uuid[] := '{}';
BEGIN
 IF p_dataset_id IS NOT NULL THEN PERFORM internal.assert_object_access('dataset',p_dataset_id,'view'); END IF;
 SELECT * INTO dataset FROM api.datasets WHERE id=p_dataset_id AND workspace_id=api.current_workspace_id() AND api.is_workspace_member(workspace_id);
 IF dataset.id IS NULL THEN RAISE EXCEPTION 'dataset denied' USING ERRCODE='42501'; END IF;
 IF p_expected_dataset_revision IS NULL OR jsonb_typeof(p_rows) IS DISTINCT FROM 'array' OR jsonb_array_length(p_rows) NOT BETWEEN 1 AND 1000 THEN RAISE EXCEPTION 'expected Dataset revision and 1 to 1000 batch rows are required' USING ERRCODE='22023'; END IF;
 IF dataset.lifecycle<>'active' THEN RETURN jsonb_build_object('ok',false,'errors',jsonb_build_array(jsonb_build_object('code','dataset_archived'))); END IF;
 IF dataset.revision<>p_expected_dataset_revision THEN RETURN jsonb_build_object('ok',false,'errors',jsonb_build_array(jsonb_build_object('code','stale_dataset_revision','expectedRevision',p_expected_dataset_revision,'actualRevision',dataset.revision))); END IF;
 FOR item IN SELECT value FROM jsonb_array_elements(p_rows) LOOP
  row_index:=row_index+1;
  IF jsonb_typeof(item)<>'object' OR (item-ARRAY['operation','rowId','expectedRevision','values','plannedKey','reason'])<>'{}'::jsonb OR item->>'operation' NOT IN ('create','update') OR jsonb_typeof(item->'rowId')<>'string' OR jsonb_typeof(item->'values')<>'object' THEN RAISE EXCEPTION 'invalid Dataset batch row shape' USING ERRCODE='22023'; END IF;
  
    IF item ? 'reason' AND (jsonb_typeof(item->'reason')<>'string' OR length(btrim(item->>'reason')) NOT BETWEEN 1 AND 2000) THEN
      RAISE EXCEPTION 'Dataset change reason must contain 1 to 2000 characters' USING ERRCODE='22023';
    END IF;
    IF item ? 'plannedKey' AND (jsonb_typeof(item->'plannedKey')<>'string' OR length(item->>'plannedKey') NOT BETWEEN 1 AND 200) THEN RAISE EXCEPTION 'invalid Dataset row planned key' USING ERRCODE='22023'; END IF;
  
    IF item ? 'reason' AND (jsonb_typeof(item->'reason')<>'string' OR length(btrim(item->>'reason')) NOT BETWEEN 1 AND 2000) THEN
      RAISE EXCEPTION 'Dataset change reason must contain 1 to 2000 characters' USING ERRCODE='22023';
    END IF;
    IF item ? 'plannedKey' AND item->>'operation'<>'create' THEN RAISE EXCEPTION 'Dataset planned keys apply only to creates' USING ERRCODE='22023'; END IF;
  BEGIN row_id:=(item->>'rowId')::uuid; EXCEPTION WHEN invalid_text_representation THEN RAISE EXCEPTION 'invalid Dataset row id' USING ERRCODE='22023'; END;
  IF row_id=ANY(seen) THEN RAISE EXCEPTION 'duplicate Dataset row id in batch' USING ERRCODE='22023'; END IF;
  seen:=array_append(seen,row_id);
  IF item->>'operation'='create' AND item ? 'expectedRevision' THEN RAISE EXCEPTION 'Dataset creates cannot include an expected row revision' USING ERRCODE='22023'; END IF;
  IF item->>'operation'='update' AND (jsonb_typeof(item->'expectedRevision')<>'number' OR coalesce((item->>'expectedRevision') ~ '^[1-9][0-9]*$',false) IS NOT TRUE) THEN RAISE EXCEPTION 'Dataset updates require a positive expected row revision' USING ERRCODE='22023'; END IF;
  SELECT * INTO existing_row FROM api.dataset_rows WHERE id=row_id AND dataset_id=dataset.id;
  IF item->>'operation'='create' AND EXISTS (SELECT 1 FROM api.dataset_rows WHERE id=row_id) THEN errors:=errors||jsonb_build_array(jsonb_build_object('rowIndex',row_index,'rowId',row_id,'code','row_id_exists'));
  ELSIF item->>'operation'='update' AND (existing_row.id IS NULL OR jsonb_typeof(item->'expectedRevision')<>'number' OR existing_row.revision<>(item->>'expectedRevision')::bigint) THEN errors:=errors||jsonb_build_array(jsonb_build_object('rowIndex',row_index,'rowId',row_id,'code',CASE WHEN existing_row.id IS NULL THEN 'row_missing' ELSE 'stale_row_revision' END)); END IF;
  FOR key,cell IN SELECT entry.key,entry.value FROM jsonb_each(item->'values') entry LOOP
   BEGIN v_field_id:=key::uuid; EXCEPTION WHEN invalid_text_representation THEN errors:=errors||jsonb_build_array(jsonb_build_object('rowIndex',row_index,'rowId',row_id,'fieldId',key,'code','invalid_field_id')); CONTINUE; END;
   SELECT * INTO field FROM api.dataset_schema_version_fields WHERE schema_version_id=dataset.schema_version_id AND field_id=v_field_id AND lifecycle='active';
   IF field.id IS NULL THEN errors:=errors||jsonb_build_array(jsonb_build_object('rowIndex',row_index,'rowId',row_id,'fieldId',key,'code','unknown_field')); CONTINUE; END IF;
   IF cell<>'null'::jsonb THEN
     error_code:=internal.dataset_batch_cell_error(dataset.workspace_id,field,cell);
     IF error_code IS NOT NULL THEN errors:=errors||jsonb_build_array(jsonb_build_object('rowIndex',row_index,'rowId',row_id,'fieldId',v_field_id,'code',error_code)); END IF;
   END IF;
  END LOOP;
  FOR field IN SELECT * FROM api.dataset_schema_version_fields WHERE schema_version_id=dataset.schema_version_id AND lifecycle='active' AND NOT nullable LOOP
   effective:=item->'values'->field.field_id::text;
   IF item->'values' ? field.field_id::text AND effective<>'null'::jsonb THEN CONTINUE; END IF;
   IF (effective IS NULL OR effective='null'::jsonb) AND item->>'operation'='update' AND effective IS NULL THEN
     SELECT CASE WHEN count(*)=0 THEN NULL WHEN field.cardinality='many' THEN jsonb_agg(coalesce(to_jsonb(text_value),to_jsonb(integer_value),to_jsonb(numeric_value),to_jsonb(boolean_value),to_jsonb(date_value),to_jsonb(timestamp_value),to_jsonb(category_option_id),to_jsonb(reference_id)) ORDER BY ordinal) ELSE (jsonb_agg(coalesce(to_jsonb(text_value),to_jsonb(integer_value),to_jsonb(numeric_value),to_jsonb(boolean_value),to_jsonb(date_value),to_jsonb(timestamp_value),to_jsonb(category_option_id),to_jsonb(reference_id)) ORDER BY ordinal))->0 END INTO effective FROM api.dataset_row_values v WHERE v.row_id=row_id AND v.field_id=field.field_id;
   END IF;
   IF effective IS NULL OR effective='null'::jsonb THEN effective:=field.default_value; END IF;
   IF effective IS NULL OR effective='null'::jsonb THEN errors:=errors||jsonb_build_array(jsonb_build_object('rowIndex',row_index,'rowId',row_id,'fieldId',field.field_id,'code','required_value'));
   ELSE
     error_code:=internal.dataset_batch_cell_error(dataset.workspace_id,field,effective);
     IF error_code IS NOT NULL THEN errors:=errors||jsonb_build_array(jsonb_build_object('rowIndex',row_index,'rowId',row_id,'fieldId',field.field_id,'code',CASE WHEN effective=field.default_value THEN 'invalid_default' ELSE error_code END)); END IF;
   END IF;
  END LOOP;
  IF existing_row.id IS NOT NULL THEN
    PERFORM internal.sync_dataset_value_system_flags(dataset.id,row_id,dataset.schema_version_id,item->'values');
  END IF;
 END LOOP;
 RETURN jsonb_build_object('ok',jsonb_array_length(errors)=0,'errors',errors);
END $_$;
--> statement-breakpoint
ALTER FUNCTION api.validate_dataset_row_batch(p_dataset_id uuid, p_expected_dataset_revision bigint, p_rows jsonb) OWNER TO migrator;
--> statement-breakpoint
CREATE FUNCTION api.validate_notebook_sheet_block() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
DECLARE
  owner api.records;
  instance api.sheet_instances;
  table_row api.scientific_tables;
  instance_id uuid;
  table_id uuid;
  placement_id uuid;
  converting boolean;
  assigning_placement boolean;
BEGIN
  IF NEW.type <> 'sheet' THEN RETURN NEW; END IF;
  IF TG_OP = 'UPDATE'
     AND NEW.payload IS NOT DISTINCT FROM OLD.payload
     AND NEW.payload_schema_version IS NOT DISTINCT FROM OLD.payload_schema_version THEN
    RETURN NEW;
  END IF;
  IF NEW.payload_schema_version <> 1 OR jsonb_typeof(NEW.payload) <> 'object' THEN
    RAISE EXCEPTION 'invalid sheet block payload' USING ERRCODE = '23514';
  END IF;
  IF EXISTS (
    SELECT 1 FROM jsonb_object_keys(NEW.payload) key
    WHERE key NOT IN ('instanceId', 'tableId', 'presentation', 'templatePlacementId')
  ) THEN
    RAISE EXCEPTION 'sheet payload may only contain instanceId, tableId, presentation and templatePlacementId'
      USING ERRCODE = '23514';
  END IF;
  IF NEW.payload ? 'presentation' AND jsonb_typeof(NEW.payload->'presentation') <> 'object' THEN
    RAISE EXCEPTION 'sheet presentation must be an object' USING ERRCODE = '23514';
  END IF;

  -- Legacy insert_sheet_block writes `{}` then replaces it with tableId.
  IF NEW.payload = '{}'::jsonb THEN
    RETURN NEW;
  END IF;

  IF NEW.payload ? 'instanceId' AND NEW.payload ? 'tableId' THEN
    RAISE EXCEPTION 'sheet block cannot reference both a Sheet Instance and a scientific table'
      USING ERRCODE = '23514';
  END IF;

  SELECT * INTO owner FROM api.records WHERE id = NEW.record_id;
  IF owner.id IS NULL THEN
    RAISE EXCEPTION 'block owner not found' USING ERRCODE = '23503';
  END IF;

  converting := coalesce(current_setting('sheetbase.sheet_block_convert', true), '') = 'v1';
  assigning_placement := false;

  IF TG_OP = 'UPDATE'
     AND OLD.payload ? 'templatePlacementId'
     AND (
       NOT (NEW.payload ? 'templatePlacementId')
       OR OLD.payload->>'templatePlacementId' IS DISTINCT FROM NEW.payload->>'templatePlacementId'
     ) THEN
    RAISE EXCEPTION 'Template placement reference is immutable' USING ERRCODE = '23514';
  END IF;

  IF NEW.payload ? 'templatePlacementId' THEN
    BEGIN
      placement_id := (NEW.payload->>'templatePlacementId')::uuid;
    EXCEPTION WHEN invalid_text_representation THEN
      RAISE EXCEPTION 'templatePlacementId must be a UUID' USING ERRCODE = '23514';
    END;
    assigning_placement := internal.template_placement_assignment_is_trusted(NEW.id, placement_id);
  END IF;

  IF NEW.payload ? 'templatePlacementId' AND NOT assigning_placement THEN
    IF TG_OP = 'INSERT'
       OR NOT (OLD.payload ? 'templatePlacementId') THEN
      RAISE EXCEPTION 'templatePlacementId is system-managed and cannot be set directly'
        USING ERRCODE = '23514';
    END IF;
  END IF;

  IF NEW.payload ? 'instanceId' THEN
    BEGIN
      instance_id := (NEW.payload->>'instanceId')::uuid;
    EXCEPTION WHEN invalid_text_representation THEN
      RAISE EXCEPTION 'instanceId must be a UUID' USING ERRCODE = '23514';
    END;
    IF TG_OP = 'UPDATE'
       AND OLD.payload ? 'instanceId'
       AND OLD.payload->>'instanceId' IS DISTINCT FROM NEW.payload->>'instanceId' THEN
      RAISE EXCEPTION 'Sheet Instance reference is immutable' USING ERRCODE = '23514';
    END IF;
    IF TG_OP = 'UPDATE'
       AND OLD.payload ? 'tableId'
       AND NOT converting THEN
      RAISE EXCEPTION 'legacy sheet blocks require convert_legacy_sheet_block' USING ERRCODE = '23514';
    END IF;
    SELECT * INTO instance FROM api.sheet_instances WHERE id = instance_id;
    IF instance.id IS NULL OR instance.workspace_id IS DISTINCT FROM owner.workspace_id THEN
      RAISE EXCEPTION 'Sheet Instance must belong to the Notebook workspace' USING ERRCODE = '42501';
    END IF;
    RETURN NEW;
  END IF;

  IF NEW.payload ? 'tableId' THEN
    BEGIN
      table_id := (NEW.payload->>'tableId')::uuid;
    EXCEPTION WHEN invalid_text_representation THEN
      RAISE EXCEPTION 'tableId must be a UUID' USING ERRCODE = '23514';
    END;
    IF TG_OP = 'UPDATE'
       AND OLD.payload ? 'instanceId' THEN
      RAISE EXCEPTION 'canonical sheet blocks cannot revert to scientific tables'
        USING ERRCODE = '23514';
    END IF;
    SELECT * INTO table_row FROM api.scientific_tables WHERE id = table_id;
    IF table_row.id IS NULL OR table_row.workspace_id IS DISTINCT FROM owner.workspace_id THEN
      RAISE EXCEPTION 'scientific table must belong to the Notebook workspace'
        USING ERRCODE = '42501';
    END IF;
    RETURN NEW;
  END IF;

  RAISE EXCEPTION 'sheet block must reference instanceId or tableId' USING ERRCODE = '23514';
END
$$;
--> statement-breakpoint
ALTER FUNCTION api.validate_notebook_sheet_block() OWNER TO migrator;
--> statement-breakpoint
CREATE FUNCTION api.validate_pipeline_event_spec(p_spec jsonb) RETURNS jsonb
    LANGUAGE plpgsql IMMUTABLE
    SET search_path TO ''
    AS $_$
DECLARE
  v_spec jsonb := p_spec;
  v_event text;
  v_dataset jsonb;
  v_instrument jsonb;
  v_input jsonb;
BEGIN
  v_event := api.normalize_pipeline_event_type(v_spec->>'eventType');
  v_spec := jsonb_set(v_spec, '{eventType}', to_jsonb(v_event));
  v_dataset := v_spec->'datasetId';
  IF v_dataset IS NOT NULL AND v_dataset <> 'null'::jsonb THEN
    IF jsonb_typeof(v_dataset) <> 'string' THEN
      RAISE EXCEPTION 'invalid event dataset filter' USING ERRCODE = 'SB034';
    END IF;
    BEGIN
      PERFORM (v_spec->>'datasetId')::uuid;
    EXCEPTION WHEN others THEN
      RAISE EXCEPTION 'invalid event dataset filter' USING ERRCODE = 'SB034';
    END;
  END IF;
  v_instrument := v_spec->'instrumentId';
  IF v_instrument IS NOT NULL AND v_instrument <> 'null'::jsonb THEN
    IF jsonb_typeof(v_instrument) <> 'string' THEN
      RAISE EXCEPTION 'invalid event instrument filter' USING ERRCODE = 'SB034';
    END IF;
    BEGIN
      PERFORM (v_spec->>'instrumentId')::uuid;
    EXCEPTION WHEN others THEN
      RAISE EXCEPTION 'invalid event instrument filter' USING ERRCODE = 'SB034';
    END;
  END IF;
  v_input := v_spec->'inputName';
  IF v_input IS NOT NULL AND v_input <> 'null'::jsonb THEN
    IF jsonb_typeof(v_input) <> 'string'
       OR (v_spec->>'inputName') !~ '^[a-z][a-z0-9_]{0,47}$' THEN
      RAISE EXCEPTION 'invalid event input binding' USING ERRCODE = 'SB034';
    END IF;
  END IF;
  RETURN v_spec;
END $_$;
--> statement-breakpoint
ALTER FUNCTION api.validate_pipeline_event_spec(p_spec jsonb) OWNER TO migrator;
--> statement-breakpoint
CREATE FUNCTION api.validate_pipeline_schedule_spec(p_workspace_id uuid, p_kind text, p_spec jsonb) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $_$
DECLARE
  v_spec jsonb := p_spec;
  v_policy jsonb;
  v_name text;
  v_binding jsonb;
BEGIN
  IF v_spec IS NULL OR jsonb_typeof(v_spec) <> 'object' THEN
    RAISE EXCEPTION 'schedule spec must be an object' USING ERRCODE = 'SB034';
  END IF;
  v_policy := v_spec->'missedRunPolicy';
  IF v_policy IS NOT NULL AND v_policy <> 'null'::jsonb
     AND (jsonb_typeof(v_policy) <> 'string'
          OR (v_spec->>'missedRunPolicy') NOT IN ('run_once', 'skip')) THEN
    RAISE EXCEPTION 'invalid missed-run policy' USING ERRCODE = 'SB034';
  END IF;
  IF v_spec->'parameters' IS NOT NULL
     AND v_spec->'parameters' <> 'null'::jsonb
     AND jsonb_typeof(v_spec->'parameters') <> 'object' THEN
    RAISE EXCEPTION 'schedule parameters must be an object' USING ERRCODE = 'SB034';
  END IF;
  IF v_spec->'inputs' IS NOT NULL AND v_spec->'inputs' <> 'null'::jsonb THEN
    IF jsonb_typeof(v_spec->'inputs') <> 'object' THEN
      RAISE EXCEPTION 'schedule inputs must be an object' USING ERRCODE = 'SB034';
    END IF;
    FOR v_name, v_binding IN SELECT entry.key, entry.value FROM jsonb_each(v_spec->'inputs') entry LOOP
      IF v_name !~ '^[a-z][a-z0-9_]{0,47}$' THEN
        RAISE EXCEPTION 'invalid input name: %', v_name USING ERRCODE = 'SB034';
      END IF;
      IF jsonb_typeof(v_binding) <> 'object' THEN
        RAISE EXCEPTION 'input % needs a binding', v_name USING ERRCODE = 'SB034';
      END IF;
      IF v_binding->>'mode' = 'pinned' THEN
        IF jsonb_typeof(v_binding->'versionId') <> 'string'
           OR (v_binding->>'versionId') !~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
           OR NOT EXISTS (
             SELECT 1 FROM api.dataset_versions
              WHERE id = (v_binding->>'versionId')::uuid
                AND workspace_id = p_workspace_id
           ) THEN
          RAISE EXCEPTION 'input % must pin an existing Dataset Version', v_name
            USING ERRCODE = 'SB034';
        END IF;
      ELSIF v_binding->>'mode' IN ('latest', 'incremental') THEN
        IF jsonb_typeof(v_binding->'datasetId') <> 'string'
           OR (v_binding->>'datasetId') !~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
           OR NOT EXISTS (
             SELECT 1 FROM api.datasets
              WHERE id = (v_binding->>'datasetId')::uuid
                AND workspace_id = p_workspace_id
           ) THEN
          RAISE EXCEPTION 'input % must name an existing Dataset', v_name
            USING ERRCODE = 'SB034';
        END IF;
        IF v_binding->>'mode' = 'incremental' AND p_kind = 'event' THEN
          RAISE EXCEPTION 'input %: an event trigger already runs only on new data', v_name
            USING ERRCODE = 'SB034';
        END IF;
      ELSE
        RAISE EXCEPTION 'input % has an unknown mode', v_name USING ERRCODE = 'SB034';
      END IF;
    END LOOP;
  END IF;
  IF p_kind = 'event' THEN
    v_spec := api.validate_pipeline_event_spec(v_spec);
  END IF;
  RETURN v_spec;
END $_$;
--> statement-breakpoint
ALTER FUNCTION api.validate_pipeline_schedule_spec(p_workspace_id uuid, p_kind text, p_spec jsonb) OWNER TO migrator;
--> statement-breakpoint
CREATE FUNCTION api.validate_report(p_workspace_id uuid, p_report_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
  v_summary jsonb;
  v_sec api.report_sections;
  v_rev api.revisions;
  v_status text;
  v_detail jsonb;
  v_valid int := 0;
  v_missing int := 0;
  v_stale int := 0;
  v_locked int := 0;
BEGIN
 IF p_report_id IS NOT NULL THEN PERFORM internal.assert_object_access('report',p_report_id,'view'); END IF;
  IF api.current_workspace_id() IS DISTINCT FROM p_workspace_id THEN
    RAISE EXCEPTION 'wrong workspace' USING ERRCODE='SB033';
  END IF;
  IF NOT EXISTS(SELECT 1 FROM api.report_definitions WHERE id=p_report_id AND workspace_id=p_workspace_id) THEN
    RAISE EXCEPTION 'report not found' USING ERRCODE='SB046';
  END IF;
  FOR v_sec IN SELECT * FROM api.report_sections WHERE report_id=p_report_id ORDER BY position LOOP
    v_status := 'valid';
    v_detail := '{}'::jsonb;
    IF v_sec.source_revision_id IS NULL AND v_sec.source_type <> 'free_text' THEN
      v_status := 'stale';
      v_detail := jsonb_build_object('reason','section references live data instead of a frozen revision');
    ELSIF v_sec.source_revision_id IS NOT NULL THEN
      SELECT * INTO v_rev FROM api.revisions WHERE id=v_sec.source_revision_id AND workspace_id=p_workspace_id;
      IF v_rev IS NULL THEN
        v_status := 'missing_source';
        v_detail := jsonb_build_object('reason','source revision no longer exists');
      ELSIF (v_sec.source_ref->>'blockId') IS NOT NULL
            AND (v_sec.frozen_payload = '{}'::jsonb) THEN
        v_status := 'missing_source';
        v_detail := jsonb_build_object('blockId',v_sec.source_ref->>'blockId','reason','frozen payload empty');
      END IF;
      IF v_status='valid' AND EXISTS(SELECT 1 FROM api.records WHERE id=v_rev.record_id AND locked_at IS NOT NULL) THEN
        v_status := 'locked';
        v_detail := jsonb_build_object('lockedAt',(SELECT locked_at FROM api.records WHERE id=v_rev.record_id));
      END IF;
    END IF;
    UPDATE api.report_sections SET validation_status=v_status, validation_detail=v_detail, updated_at=now()
      WHERE id=v_sec.id;
    v_valid := v_valid + (v_status='valid')::int;
    v_missing := v_missing + (v_status='missing_source')::int;
    v_stale := v_stale + (v_status='stale')::int;
    v_locked := v_locked + (v_status='locked')::int;
  END LOOP;
  v_summary := jsonb_build_object(
    'reportId',p_report_id,
    'sections',(SELECT count(*) FROM api.report_sections WHERE report_id=p_report_id),
    'valid',v_valid,
    'missingSource',v_missing,
    'stale',v_stale,
    'locked',v_locked,
    'ready',(v_missing=0 AND v_stale=0)
  );
  RETURN v_summary;
END $$;
--> statement-breakpoint
ALTER FUNCTION api.validate_report(p_workspace_id uuid, p_report_id uuid) OWNER TO migrator;
--> statement-breakpoint
CREATE FUNCTION api.validate_scientific_block() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $_$
DECLARE
  owner api.records; target api.records; rev api.revisions; item jsonb; old_item jsonb;
  actor text; item_id text; cparam_key text; analysis_definition_id uuid;
  -- plate_map locals
  pm_spec jsonb; pm_wells jsonb; pm_well jsonb; pm_code text; pm_row int; pm_col int;
  pm_seen jsonb; pm_sref jsonb; pm_vol jsonb;
  pm_target api.records;
BEGIN
  IF NEW.type NOT IN ('protocol_reference','procedure_step','materials','file','chart','analysis','plate_map') THEN RETURN NEW; END IF;
  IF TG_OP='UPDATE' AND NEW.type IS NOT DISTINCT FROM OLD.type
    AND NEW.payload_schema_version IS NOT DISTINCT FROM OLD.payload_schema_version
    AND NEW.payload IS NOT DISTINCT FROM OLD.payload THEN RETURN NEW; END IF;
  IF NEW.payload_schema_version <> 1 OR jsonb_typeof(NEW.payload) <> 'object' THEN
    RAISE EXCEPTION 'invalid SCI-002 payload schema' USING ERRCODE='23514';
  END IF;
  SELECT * INTO owner FROM api.records WHERE id=NEW.record_id;
  IF owner.id IS NULL THEN RAISE EXCEPTION 'block owner not found' USING ERRCODE='23503'; END IF;

  IF NEW.type='protocol_reference' THEN
    IF NEW.payload='{}'::jsonb THEN
      IF owner.kind <> 'experiment' THEN RAISE EXCEPTION 'protocol draft requires experiment' USING ERRCODE='23514'; END IF;
      RETURN NEW;
    END IF;
    IF current_user IN ('authenticated','api_client') THEN
      RAISE EXCEPTION 'populated protocol references require pin_protocol_reference' USING ERRCODE='42501';
    END IF;
    BEGIN
      SELECT * INTO target FROM api.records WHERE id=(NEW.payload->>'protocolRecordId')::uuid;
      SELECT * INTO rev FROM api.revisions WHERE id=(NEW.payload->>'protocolRevisionId')::uuid;
    EXCEPTION WHEN invalid_text_representation THEN RAISE EXCEPTION 'invalid protocol UUID' USING ERRCODE='23514'; END;
    IF TG_OP='UPDATE' AND OLD.payload <> '{}'::jsonb AND NEW.payload IS DISTINCT FROM OLD.payload THEN
      RAISE EXCEPTION 'pinned protocol reference is immutable' USING ERRCODE='23514';
    END IF;
    IF owner.kind<>'experiment' OR target.id IS NULL OR rev.id IS NULL OR target.deleted_at IS NOT NULL
       OR target.kind<>'protocol_template' OR target.workspace_id<>owner.workspace_id OR rev.record_id<>target.id
       OR NEW.payload->>'protocolIdentifier' IS DISTINCT FROM rev.metadata_snapshot->>'identifier'
       OR NEW.payload->>'protocolTitle' IS DISTINCT FROM rev.metadata_snapshot->>'title'
       OR NEW.payload->>'version' IS DISTINCT FROM COALESCE(rev.metadata_snapshot#>>'{properties,version}',rev.metadata_version::text)
       OR NEW.payload->>'approvalStatus' IS DISTINCT FROM rev.metadata_snapshot->>'status'
       OR (NEW.payload->>'pinnedAt')::timestamptz IS DISTINCT FROM rev.created_at
       OR NEW.payload->>'pinnedByUserId' IS DISTINCT FROM rev.created_by_user_id THEN
      RAISE EXCEPTION 'invalid pinned protocol reference' USING ERRCODE='23514';
    END IF;
  ELSIF NEW.type='procedure_step' THEN
    IF jsonb_typeof(NEW.payload->'text') IS DISTINCT FROM 'string'
      OR jsonb_typeof(NEW.payload->'stepNumber') IS DISTINCT FROM 'number'
      OR (NEW.payload->>'stepNumber')::numeric <> trunc((NEW.payload->>'stepNumber')::numeric) THEN
      RAISE EXCEPTION 'invalid procedure definition' USING ERRCODE='23514';
    END IF;
    IF owner.kind='protocol_template' THEN
      IF NEW.payload ?| ARRAY['sourceProtocolRevisionId','sourceStepBlockId','completed','note','completedAt','completedByUserId'] THEN
        RAISE EXCEPTION 'protocol definition cannot carry execution state' USING ERRCODE='23514';
      END IF;
    ELSIF owner.kind='experiment' THEN
      actor := api.current_user_id();
      IF TG_OP='INSERT' AND current_user IN ('authenticated','api_client') THEN
        RAISE EXCEPTION 'execution steps are created by pin_protocol_reference' USING ERRCODE='42501';
      END IF;
      BEGIN
        SELECT * INTO rev FROM api.revisions WHERE id=(NEW.payload->>'sourceProtocolRevisionId')::uuid;
        IF NOT EXISTS (SELECT 1 FROM jsonb_array_elements(rev.block_snapshot) x
          WHERE x->>'id'=NEW.payload->>'sourceStepBlockId' AND x->>'type'='procedure_step') THEN
          RAISE EXCEPTION 'source step is not in revision' USING ERRCODE='23514';
        END IF;
      EXCEPTION WHEN invalid_text_representation THEN RAISE EXCEPTION 'invalid step provenance' USING ERRCODE='23514'; END;
      IF rev.id IS NULL OR NOT EXISTS (SELECT 1 FROM api.records rr WHERE rr.id=rev.record_id AND rr.workspace_id=owner.workspace_id AND rr.kind='protocol_template')
        OR jsonb_typeof(NEW.payload->'completed') IS DISTINCT FROM 'boolean'
        OR jsonb_typeof(NEW.payload->'note') IS DISTINCT FROM 'string' THEN
        RAISE EXCEPTION 'invalid execution step' USING ERRCODE='23514';
      END IF;
      IF NEW.payload->'stepNumber' IS DISTINCT FROM (
          SELECT x->'payload'->'stepNumber' FROM jsonb_array_elements(rev.block_snapshot) x
          WHERE x->>'id'=NEW.payload->>'sourceStepBlockId' AND x->>'type'='procedure_step'
        ) THEN RAISE EXCEPTION 'execution step differs from pinned revision' USING ERRCODE='23514'; END IF;
      IF TG_OP='UPDATE' AND (NEW.payload->'stepNumber' IS DISTINCT FROM OLD.payload->'stepNumber'
        OR NEW.payload->'sourceProtocolRevisionId' IS DISTINCT FROM OLD.payload->'sourceProtocolRevisionId'
        OR NEW.payload->'sourceStepBlockId' IS DISTINCT FROM OLD.payload->'sourceStepBlockId') THEN
        RAISE EXCEPTION 'execution step definition is immutable' USING ERRCODE='23514';
      END IF;
      IF TG_OP='INSERT' OR (OLD.payload->>'completed')::boolean IS DISTINCT FROM (NEW.payload->>'completed')::boolean THEN
        IF (NEW.payload->>'completed')::boolean THEN
          NEW.payload := jsonb_set(jsonb_set(NEW.payload,'{completedAt}',to_jsonb(clock_timestamp())),
            '{completedByUserId}',to_jsonb(actor));
        ELSE NEW.payload := jsonb_set(jsonb_set(NEW.payload,'{completedAt}','null'),'{completedByUserId}','null'); END IF;
      ELSE
        NEW.payload := jsonb_set(jsonb_set(NEW.payload,'{completedAt}',OLD.payload->'completedAt'),'{completedByUserId}',OLD.payload->'completedByUserId');
      END IF;
    ELSE RAISE EXCEPTION 'procedure step owner is invalid' USING ERRCODE='23514'; END IF;
  ELSIF NEW.type='file' THEN
    -- A draft file block (empty payload) is allowed; the upload flow populates
    -- it with a fileRecordId referencing a file record in this workspace.
    IF NEW.payload='{}'::jsonb THEN
      RETURN NEW;
    END IF;
    IF jsonb_typeof(NEW.payload->'fileRecordId') IS DISTINCT FROM 'string'
      OR jsonb_typeof(NEW.payload->'fileIdentifier') IS DISTINCT FROM 'string'
      OR jsonb_typeof(NEW.payload->'displayName') IS DISTINCT FROM 'string'
      OR jsonb_typeof(NEW.payload->'mediaType') IS DISTINCT FROM 'string'
      OR jsonb_typeof(NEW.payload->'byteSize') IS DISTINCT FROM 'number'
      OR (NEW.payload->>'byteSize')::numeric < 0 THEN
      RAISE EXCEPTION 'invalid file block payload' USING ERRCODE='23514';
    END IF;
    BEGIN
      SELECT * INTO target FROM api.records WHERE id=(NEW.payload->>'fileRecordId')::uuid;
    EXCEPTION WHEN invalid_text_representation THEN RAISE EXCEPTION 'invalid file record UUID' USING ERRCODE='23514'; END;
    IF target.id IS NULL OR target.deleted_at IS NOT NULL OR target.kind<>'file'
       OR target.workspace_id<>owner.workspace_id
       OR NEW.payload->>'fileIdentifier' IS DISTINCT FROM target.identifier THEN
      RAISE EXCEPTION 'invalid file block target' USING ERRCODE='23514';
    END IF;
    -- The cached display metadata must match the live storage object so the
    -- block cannot lie about name, type or size at write time. The live status
    -- is fetched by the UI; it is not cached in the block payload.
    IF NOT EXISTS (
      SELECT 1 FROM api.file_objects fo
      WHERE fo.record_id=target.id AND fo.workspace_id=owner.workspace_id
        AND fo.display_name = NEW.payload->>'displayName'
        AND fo.media_type = NEW.payload->>'mediaType'
        AND fo.byte_size = (NEW.payload->>'byteSize')::bigint
    ) THEN
      RAISE EXCEPTION 'file block metadata does not match storage object' USING ERRCODE='23514';
    END IF;
  ELSIF NEW.type='chart' THEN
    -- SCI-004 (decision 0029): chart block payload. A draft `{}` is allowed.
    IF NEW.payload='{}'::jsonb THEN
      RETURN NEW;
    END IF;
    IF current_user='api_client' THEN
      RAISE EXCEPTION 'credential-authored chart writes are not supported' USING ERRCODE='42501';
    END IF;
    -- Frozen authority (decision 0029 §6): a chart is frozen only when
    -- payload->'frozen' is a JSON object. The frozen object is only ever
    -- written by the SECURITY DEFINER freeze_chart / unfreeze_chart /
    -- bind_chart_revision RPCs, which run as their owner (migrator), never as
    -- authenticated/api_client. Direct CRUD on api.blocks therefore cannot
    -- fabricate, remove or revision-bind a frozen payload, and a frozen
    -- chart's spec/title/provenance cannot drift. A live chart (frozen missing
    -- or JSON null) may still edit its spec/title/provenance freely.
    IF TG_OP='UPDATE' AND NEW.type='chart'
       AND jsonb_typeof(OLD.payload->'frozen')='object' THEN
      IF (OLD.payload->'frozen') IS DISTINCT FROM (NEW.payload->'frozen') THEN
        -- The frozen object itself changed (removed, content changed, or
        -- revisionId bound). Only the SECURITY DEFINER RPCs may do this.
        IF current_user IN ('authenticated','api_client') THEN
          RAISE EXCEPTION 'frozen chart mutations require freeze_chart/unfreeze_chart/bind_chart_revision'
            USING ERRCODE='42501';
        END IF;
        -- unfreeze: frozen object -> no/null frozen, rest byte-identical.
        IF jsonb_typeof(NEW.payload->'frozen') IS DISTINCT FROM 'object'
           AND (NEW.payload #- ARRAY['frozen']::text[]) IS NOT DISTINCT FROM (OLD.payload #- ARRAY['frozen']::text[]) THEN
          RETURN NEW;
        END IF;
        -- revision binding: frozen object stays a frozen object, frozen.revisionId
        -- null -> uuid, rest of payload and frozen object byte-identical.
        IF jsonb_typeof(NEW.payload->'frozen')='object'
           AND OLD.payload->'frozen'->>'revisionId' IS NULL
           AND NEW.payload->'frozen'->>'revisionId' IS NOT NULL
           AND (NEW.payload #- ARRAY['frozen']::text[]) IS NOT DISTINCT FROM (OLD.payload #- ARRAY['frozen']::text[])
           AND (NEW.payload->'frozen' #- ARRAY['revisionId']::text[]) IS NOT DISTINCT FROM (OLD.payload->'frozen' #- ARRAY['revisionId']::text[]) THEN
          RETURN NEW;
        END IF;
        RAISE EXCEPTION 'frozen chart is immutable' USING ERRCODE='23514';
      ELSIF NEW.payload IS DISTINCT FROM OLD.payload THEN
        -- Frozen object unchanged but the spec/title/provenance drifted.
        RAISE EXCEPTION 'frozen chart is immutable' USING ERRCODE='23514';
      END IF;
    END IF;
    -- freeze transition: live (no/null frozen) -> frozen object. Only the
    -- SECURITY DEFINER freeze_chart RPC may add a frozen object; direct CRUD
    -- is rejected. The rest of the payload must be byte-identical.
    IF TG_OP='UPDATE' AND NEW.type='chart'
       AND jsonb_typeof(OLD.payload->'frozen') IS DISTINCT FROM 'object'
       AND jsonb_typeof(NEW.payload->'frozen')='object' THEN
      IF current_user IN ('authenticated','api_client') THEN
        RAISE EXCEPTION 'frozen chart mutations require freeze_chart/unfreeze_chart/bind_chart_revision'
          USING ERRCODE='42501';
      END IF;
      IF (NEW.payload #- ARRAY['frozen']::text[]) IS NOT DISTINCT FROM (OLD.payload #- ARRAY['frozen']::text[]) THEN
        RETURN NEW;
      END IF;
      RAISE EXCEPTION 'frozen chart is immutable' USING ERRCODE='23514';
    END IF;
    IF jsonb_typeof(NEW.payload->'title') IS DISTINCT FROM 'string'
       OR btrim(NEW.payload->>'title')='' THEN
      RAISE EXCEPTION 'chart title is required' USING ERRCODE='23514';
    END IF;
    IF jsonb_typeof(NEW.payload->'spec') IS DISTINCT FROM 'object' THEN
      RAISE EXCEPTION 'invalid chart spec' USING ERRCODE='23514';
    END IF;
    <<chart_spec>>
    DECLARE
      spec jsonb := NEW.payload->'spec';
      ctype text := spec->>'type';
      cspecver int;
      cdatasets jsonb;
      cfields jsonb;
      cseries jsonb;
      ceb jsonb;
      cds api.datasets;
      citem jsonb;
      cbinding jsonb;
    BEGIN
      cspecver := NULLIF(spec->>'specVersion','')::int;
      IF cspecver IS NULL OR cspecver <> 1 THEN
        RAISE EXCEPTION 'unsupported chart spec version' USING ERRCODE='23514';
      END IF;
      IF ctype IS NULL OR ctype NOT IN ('line','scatter','scatter_line','connected_scatter','bar','grouped_bar','stacked_bar','histogram','box','violin','strip','summary','heatmap') THEN
        RAISE EXCEPTION 'unsupported chart type' USING ERRCODE='23514';
      END IF;
      cdatasets := spec->'datasets';
      IF jsonb_typeof(cdatasets) IS DISTINCT FROM 'array' OR jsonb_array_length(cdatasets)=0 THEN
        RAISE EXCEPTION 'chart datasets must be a non-empty array' USING ERRCODE='23514';
      END IF;
      cfields := spec->'fields';
      IF jsonb_typeof(cfields) IS DISTINCT FROM 'object'
         OR jsonb_typeof(cfields->'y') IS DISTINCT FROM 'object'
         OR (cfields->'y')->>'fieldId' IS NULL THEN
        RAISE EXCEPTION 'chart fields.y is required' USING ERRCODE='23514';
      END IF;
      IF ctype IN ('line','bar','grouped_bar','stacked_bar','connected_scatter','scatter_line','heatmap','summary') THEN
        cbinding := cfields->'x';
        IF jsonb_typeof(cbinding) IS DISTINCT FROM 'object'
           OR cbinding->>'fieldId' IS NULL THEN
          RAISE EXCEPTION 'chart fields.x is required for this chart type' USING ERRCODE='23514';
        END IF;
      END IF;

      -- SCI-01 type rules -------------------------------------------------
      -- Histograms and box plots measure fields.y directly; an x mapping
      -- would suggest a dependency that does not exist.
      IF ctype IN ('histogram','box')
         AND jsonb_typeof(cfields->'x') = 'object' THEN
        RAISE EXCEPTION 'chart fields.x must be null for histogram and box'
          USING ERRCODE='23514';
      END IF;
      -- Heatmaps plot an aggregated value grid, not series: grouping,
      -- colour/size mappings and error overlays are rejected so the cell
      -- aggregation stays unambiguous.
      IF ctype='heatmap' THEN
        cbinding := cfields->'x';
        IF jsonb_typeof(cbinding) IS DISTINCT FROM 'object'
           OR cbinding->>'fieldId' IS NULL THEN
          RAISE EXCEPTION 'chart fields.x is required for heatmap' USING ERRCODE='23514';
        END IF;
        FOREACH cbinding IN ARRAY ARRAY[cfields->'series', cfields->'color', cfields->'size']::jsonb[] LOOP
          IF jsonb_typeof(cbinding) = 'object' THEN
            RAISE EXCEPTION 'chart series/color/size must be null for heatmap'
              USING ERRCODE='23514';
          END IF;
        END LOOP;
        IF jsonb_typeof(spec->'overlays'->'errorBars') = 'object' THEN
          RAISE EXCEPTION 'chart overlays.errorBars must be null for heatmap'
            USING ERRCODE='23514';
        END IF;
      END IF;
      -- Facet mapping is allowed on live charts (shape check only); the
      -- freeze RPC refuses to snapshot faceted charts for now.
      cbinding := cfields->'facet';
      IF jsonb_typeof(cbinding) = 'object'
         AND cbinding->>'fieldId' IS NULL THEN
        RAISE EXCEPTION 'invalid facet binding' USING ERRCODE='23514';
      END IF;
      FOREACH citem IN ARRAY ARRAY[cfields->'facetRow', cfields->'facetCol', cfields->'group', cfields->'shape', cfields->'label']::jsonb[] LOOP
        IF jsonb_typeof(citem) = 'object' AND citem->>'fieldId' IS NULL THEN
          RAISE EXCEPTION 'invalid chart field binding' USING ERRCODE='23514';
        END IF;
      END LOOP;
      ceb := spec->'overlays'->'fit';
      IF jsonb_typeof(ceb) = 'object' AND COALESCE(ceb->>'method','ols') <> 'ols' THEN
        RAISE EXCEPTION 'unsupported chart fit method' USING ERRCODE='23514';
      END IF;
      -- Type parameters must belong to the spec's own type and stay within
      -- documented ranges. Absent params mean the documented defaults.
      IF jsonb_typeof(spec->'typeParams') NOT IN ('object','null')
         AND spec ? 'typeParams' THEN
        RAISE EXCEPTION 'invalid chart typeParams' USING ERRCODE='23514';
      END IF;
      DECLARE
        cparams jsonb := COALESCE(spec->'typeParams', '{}'::jsonb);
      BEGIN
        IF cparams ? 'histogram' AND ctype <> 'histogram' THEN
          RAISE EXCEPTION 'typeParams.histogram only applies to histogram charts'
            USING ERRCODE='23514';
        END IF;
        IF cparams ? 'box' AND ctype <> 'box' THEN
          RAISE EXCEPTION 'typeParams.box only applies to box charts'
            USING ERRCODE='23514';
        END IF;
        IF cparams ? 'heatmap' AND ctype <> 'heatmap' THEN
          RAISE EXCEPTION 'typeParams.heatmap only applies to heatmap charts'
            USING ERRCODE='23514';
        END IF;
        IF jsonb_typeof(cparams->'histogram') = 'object' THEN
          IF (cparams->'histogram' ? 'bins')
             AND ((cparams#>>'{histogram,bins}')::int IS NULL
                  OR (cparams#>>'{histogram,bins}')::int < 1
                  OR (cparams#>>'{histogram,bins}')::int > 200) THEN
            RAISE EXCEPTION 'histogram bins must be between 1 and 200' USING ERRCODE='23514';
          END IF;
          IF (cparams->'histogram' ? 'binWidth')
             AND (COALESCE((cparams#>>'{histogram,binWidth}')::float8, 0) <= 0
                  OR (cparams#>>'{histogram,binWidth}')::float8 IS NULL) THEN
            RAISE EXCEPTION 'histogram binWidth must be positive' USING ERRCODE='23514';
          END IF;
          IF (cparams->'histogram' ? 'bins')
             AND (cparams->'histogram' ? 'binWidth') THEN
            RAISE EXCEPTION 'histogram accepts bins or binWidth, not both'
              USING ERRCODE='23514';
          END IF;
        END IF;
        IF jsonb_typeof(cparams->'box') = 'object'
           AND (cparams->'box' ? 'showOutliers')
           AND jsonb_typeof(cparams#>'{box,showOutliers}') IS DISTINCT FROM 'boolean' THEN
          RAISE EXCEPTION 'box showOutliers must be boolean' USING ERRCODE='23514';
        END IF;
        IF jsonb_typeof(cparams->'heatmap') = 'object' THEN
          FOREACH cparam_key IN ARRAY ARRAY['xBins','yBins']::text[] LOOP
            IF cparams#>ARRAY['heatmap', cparam_key] IS NOT NULL
               AND ((cparams#>>ARRAY['heatmap', cparam_key])::int IS NULL
                    OR (cparams#>>ARRAY['heatmap', cparam_key])::int < 2
                    OR (cparams#>>ARRAY['heatmap', cparam_key])::int > 100) THEN
              RAISE EXCEPTION 'heatmap % must be between 2 and 100', cparam_key
                USING ERRCODE='23514';
            END IF;
          END LOOP;
          IF cparams->'heatmap' ? 'aggregate'
             AND (cparams->'heatmap')->>'aggregate'
                 NOT IN ('count','mean','median','min','max') THEN
            RAISE EXCEPTION 'invalid heatmap aggregate' USING ERRCODE='23514';
          END IF;
          IF COALESCE((cparams->'heatmap')->>'aggregate','count') <> 'count' THEN
            cbinding := cparams#>'{heatmap,valueField}';
            IF jsonb_typeof(cbinding) IS DISTINCT FROM 'object'
               OR cbinding->>'fieldId' IS NULL THEN
              RAISE EXCEPTION 'heatmap valueField is required when aggregating anything but counts'
                USING ERRCODE='23514';
            END IF;
          END IF;
        END IF;
      END;
      -- Series colours must come from the approved palette (DESIGN.md).
      cseries := spec->'display'->'series';
      IF jsonb_typeof(cseries)='array' THEN
        FOR citem IN SELECT value FROM jsonb_array_elements(cseries) LOOP
          IF lower(citem->>'color') NOT IN
             ('#006edc','#00a659','#9b61ea','#00a3bb','#e8a200') THEN
            RAISE EXCEPTION 'chart series color must be from the approved palette' USING ERRCODE='23514';
          END IF;
        END LOOP;
      END IF;
      -- Dataset reference integrity: every datasetId must be an active
      -- canonical Dataset in the SAME workspace as the owning record.
      FOR citem IN SELECT value FROM jsonb_array_elements(cdatasets) LOOP
        BEGIN
          SELECT * INTO cds FROM api.datasets WHERE id=(citem->>'datasetId')::uuid;
        EXCEPTION WHEN invalid_text_representation THEN
          RAISE EXCEPTION 'invalid chart dataset UUID' USING ERRCODE='23514';
        END;
        IF cds.id IS NULL OR cds.lifecycle<>'active'
           OR cds.workspace_id<>owner.workspace_id THEN
          RAISE EXCEPTION 'invalid dataset reference' USING ERRCODE='23514';
        END IF;
      END LOOP;
      -- Error-bar overlay must name a column and a basis when present.
      ceb := spec->'overlays'->'errorBars';
      IF ceb IS NOT NULL AND jsonb_typeof(ceb)='object' THEN
        IF ceb->>'basis' IS NULL
           OR ceb->>'basis' NOT IN ('sd','se','sem','ci','range','custom') THEN
          RAISE EXCEPTION 'invalid error bar overlay' USING ERRCODE='23514';
        END IF;
        IF COALESCE(ceb->>'source','field') = 'field'
           AND ceb->>'fieldId' IS NULL
           AND ceb->>'lowerFieldId' IS NULL THEN
          RAISE EXCEPTION 'invalid error bar overlay' USING ERRCODE='23514';
        END IF;
      END IF;
      -- SCI-01: data-coordinate annotations are Cartesian-only, capped at
      -- twelve entries, each with finite numeric x/y and a non-empty label.
      ceb := spec->'display'->'annotations';
      IF ceb IS NOT NULL THEN
        IF jsonb_typeof(ceb) IS DISTINCT FROM 'array' THEN
          RAISE EXCEPTION 'annotations must be an array when present' USING ERRCODE='23514';
        END IF;
        IF jsonb_array_length(ceb) > 12 THEN
          RAISE EXCEPTION 'at most 12 annotations are supported' USING ERRCODE='23514';
        END IF;
        IF jsonb_array_length(ceb) > 0
           AND ctype NOT IN ('line','scatter','scatter_line','connected_scatter','bar','grouped_bar','stacked_bar','summary') THEN
          RAISE EXCEPTION 'annotations are not supported for % charts', ctype
            USING ERRCODE='23514';
        END IF;
        FOR citem IN SELECT value FROM jsonb_array_elements(ceb) LOOP
          IF jsonb_typeof(citem) IS DISTINCT FROM 'object'
             OR jsonb_typeof(citem->'x') IS DISTINCT FROM 'number'
             OR jsonb_typeof(citem->'y') IS DISTINCT FROM 'number'
             OR jsonb_typeof(citem->'label') IS DISTINCT FROM 'string'
             OR btrim(citem->>'label')=''
             OR (citem->>'x')::float8 IS NULL OR (citem->>'y')::float8 IS NULL THEN
            RAISE EXCEPTION 'invalid annotation entry' USING ERRCODE='23514';
          END IF;
        END LOOP;
      END IF;
      PERFORM "api"."validate_chart_spec_maturity"(spec);
    END chart_spec;
  ELSIF NEW.type='analysis' THEN
    -- SCI-03: an analysis block references a saved analysis definition by
    -- stable UUID (decision 0040). A draft `{}` is allowed.
    IF NEW.payload='{}'::jsonb THEN
      RETURN NEW;
    END IF;
    IF current_user='api_client' THEN
      RAISE EXCEPTION 'credential-authored analysis writes are not supported' USING ERRCODE='42501';
    END IF;
    IF jsonb_typeof(NEW.payload->'title') IS DISTINCT FROM 'string'
       OR btrim(NEW.payload->>'title')='' THEN
      RAISE EXCEPTION 'analysis title is required' USING ERRCODE='23514';
    END IF;
    BEGIN
      analysis_definition_id := (NEW.payload->>'definitionId')::uuid;
    EXCEPTION WHEN invalid_text_representation THEN
      RAISE EXCEPTION 'invalid analysis definition UUID' USING ERRCODE='23514';
    END;
    IF NOT EXISTS (
      SELECT 1 FROM api.analysis_definitions d
      WHERE d.id=(NEW.payload->>'definitionId')::uuid
        AND d.workspace_id=owner.workspace_id
    ) THEN
      RAISE EXCEPTION 'invalid analysis definition reference' USING ERRCODE='23514';
    END IF;
    -- Provenance is optional prose.
    IF jsonb_typeof(NEW.payload->'provenance') NOT IN ('string','null')
       AND NEW.payload ? 'provenance' THEN
      RAISE EXCEPTION 'invalid analysis provenance' USING ERRCODE='23514';
    END IF;
    -- Frozen authority (mirrors charts): the frozen object is only ever
    -- written by the SECURITY DEFINER freeze_analysis_block /
    -- unfreeze_analysis_block RPCs. Direct CRUD cannot fabricate, remove or
    -- drift a frozen payload.
    IF TG_OP='UPDATE'
       AND jsonb_typeof(OLD.payload->'frozen')='object' THEN
      IF (OLD.payload->'frozen') IS DISTINCT FROM (NEW.payload->'frozen') THEN
        IF current_user IN ('authenticated','api_client') THEN
          RAISE EXCEPTION 'frozen analysis mutations require freeze_analysis_block/unfreeze_analysis_block'
            USING ERRCODE='42501';
        END IF;
        IF jsonb_typeof(NEW.payload->'frozen') IS DISTINCT FROM 'object'
           AND (NEW.payload #- ARRAY['frozen']::text[]) IS NOT DISTINCT FROM (OLD.payload #- ARRAY['frozen']::text[]) THEN
          RETURN NEW;
        END IF;
        -- Revision binding at submission: frozen object stays a frozen
        -- object, frozen.revisionId null -> uuid, rest byte-identical.
        IF jsonb_typeof(NEW.payload->'frozen')='object'
           AND OLD.payload->'frozen'->>'revisionId' IS NULL
           AND NEW.payload->'frozen'->>'revisionId' IS NOT NULL
           AND (NEW.payload #- ARRAY['frozen']::text[]) IS NOT DISTINCT FROM (OLD.payload #- ARRAY['frozen']::text[])
           AND (NEW.payload->'frozen' #- ARRAY['revisionId']::text[]) IS NOT DISTINCT FROM (OLD.payload->'frozen' #- ARRAY['revisionId']::text[]) THEN
          RETURN NEW;
        END IF;
        RAISE EXCEPTION 'frozen analysis is immutable' USING ERRCODE='23514';
      ELSIF NEW.payload IS DISTINCT FROM OLD.payload THEN
        RAISE EXCEPTION 'frozen analysis is immutable' USING ERRCODE='23514';
      END IF;
    END IF;
    IF TG_OP='UPDATE'
       AND jsonb_typeof(OLD.payload->'frozen') IS DISTINCT FROM 'object'
       AND jsonb_typeof(NEW.payload->'frozen')='object' THEN
      IF current_user IN ('authenticated','api_client') THEN
        RAISE EXCEPTION 'frozen analysis mutations require freeze_analysis_block/unfreeze_analysis_block'
          USING ERRCODE='42501';
      END IF;
      IF (NEW.payload #- ARRAY['frozen']::text[]) IS NOT DISTINCT FROM (OLD.payload #- ARRAY['frozen']::text[]) THEN
        RETURN NEW;
      END IF;
      RAISE EXCEPTION 'frozen analysis is immutable' USING ERRCODE='23514';
    END IF;
  ELSIF NEW.type='plate_map' THEN
    -- SCI-005 (decision 0030): plate map block payload. A draft `{}` is
    -- allowed. Structural validation, well-code/dimension checks, duplicate
    -- detection, and sample reference integrity are enforced here. Sample
    -- links reuse the existing record_links table through deduplicated
    -- upserts — same pattern as materials blocks.
    IF NEW.payload='{}'::jsonb THEN
      RETURN NEW;
    END IF;
    IF owner.kind<>'experiment' THEN
      RAISE EXCEPTION 'plate map blocks require an experiment owner' USING ERRCODE='23514';
    END IF;
    IF jsonb_typeof(NEW.payload->'title') IS DISTINCT FROM 'string'
       OR btrim(NEW.payload->>'title')='' THEN
      RAISE EXCEPTION 'plate map title is required' USING ERRCODE='23514';
    END IF;
    IF jsonb_typeof(NEW.payload->'spec') IS DISTINCT FROM 'object' THEN
      RAISE EXCEPTION 'invalid plate map spec' USING ERRCODE='23514';
    END IF;
    <<plate_map_spec>>
    DECLARE
      pm_spec jsonb := NEW.payload->'spec';
      pm_format text := pm_spec->>'format';
      pm_specver int;
      pm_rows int;
      pm_cols int;
      pm_well_count int;
      pm_well_item jsonb;
      pm_well_code text;
      pm_well_row int;
      pm_well_col int;
      pm_expected_code text;
      pm_role text;
      pm_sample_ref jsonb;
      pm_vol_obj jsonb;
      pm_replicate int;
      pm_seen_codes text[] := ARRAY[]::text[];
      pm_actor text;
      pm_sample_target api.records;
    BEGIN
      pm_specver := NULLIF(pm_spec->>'specVersion','')::int;
      IF pm_specver IS NULL OR pm_specver <> 1 THEN
        RAISE EXCEPTION 'unsupported plate map spec version' USING ERRCODE='23514';
      END IF;
      -- Format and dimensions: 96_well = 8×12 initially.
      IF pm_format IS NULL OR pm_format NOT IN ('96_well') THEN
        RAISE EXCEPTION 'unsupported plate format' USING ERRCODE='23514';
      END IF;
      pm_rows := NULLIF(pm_spec->>'rows','')::int;
      pm_cols := NULLIF(pm_spec->>'cols','')::int;
      IF pm_format='96_well' AND (pm_rows IS NULL OR pm_rows<>8 OR pm_cols IS NULL OR pm_cols<>12) THEN
        RAISE EXCEPTION 'invalid plate dimensions for 96_well (expected 8×12)' USING ERRCODE='23514';
      END IF;
      -- wells array
      pm_wells := pm_spec->'wells';
      IF jsonb_typeof(pm_wells) IS DISTINCT FROM 'array' THEN
        RAISE EXCEPTION 'plate map wells must be an array' USING ERRCODE='23514';
      END IF;
      pm_well_count := jsonb_array_length(pm_wells);
      IF pm_well_count > pm_rows * pm_cols THEN
        RAISE EXCEPTION 'plate map well count exceeds plate capacity' USING ERRCODE='23514';
      END IF;
      -- validation config must be an object
      IF jsonb_typeof(pm_spec->'validation') IS DISTINCT FROM 'object' THEN
        RAISE EXCEPTION 'plate map validation config is required' USING ERRCODE='23514';
      END IF;
      pm_actor := CASE WHEN current_user='authenticated' THEN api.current_user_id() ELSE NULL END;
      -- Iterate wells
      FOR pm_well_item IN SELECT value FROM jsonb_array_elements(pm_wells) LOOP
        -- wellCode
        pm_well_code := pm_well_item->>'wellCode';
        IF pm_well_code IS NULL OR pm_well_code !~ '^[A-H][1-9][0-9]?$' THEN
          RAISE EXCEPTION 'invalid well code: %', pm_well_code USING ERRCODE='23514';
        END IF;
        -- row
        pm_well_row := NULLIF(pm_well_item->>'row','')::int;
        IF pm_well_row IS NULL OR pm_well_row < 0 OR pm_well_row >= pm_rows THEN
          RAISE EXCEPTION 'well row out of bounds: %', pm_well_row USING ERRCODE='23514';
        END IF;
        -- col
        pm_well_col := NULLIF(pm_well_item->>'col','')::int;
        IF pm_well_col IS NULL OR pm_well_col < 0 OR pm_well_col >= pm_cols THEN
          RAISE EXCEPTION 'well col out of bounds: %', pm_well_col USING ERRCODE='23514';
        END IF;
        -- Cross-check wellCode ↔ row/col
        pm_expected_code := chr(65 + pm_well_row) || (pm_well_col + 1)::text;
        IF pm_well_code IS DISTINCT FROM pm_expected_code THEN
          RAISE EXCEPTION 'well code % does not match row %, col %', pm_well_code, pm_well_row, pm_well_col USING ERRCODE='23514';
        END IF;
        -- Duplicate well codes
        IF pm_well_code = ANY(pm_seen_codes) THEN
          RAISE EXCEPTION 'duplicate well code: %', pm_well_code USING ERRCODE='23514';
        END IF;
        pm_seen_codes := array_append(pm_seen_codes, pm_well_code);
        -- role
        pm_role := pm_well_item->>'role';
        IF pm_role IS NULL OR pm_role NOT IN ('sample','positive_control','negative_control','blank','empty') THEN
          RAISE EXCEPTION 'unsupported assignment role: %', pm_role USING ERRCODE='23514';
        END IF;
        -- sampleRef (optional)
        pm_sample_ref := pm_well_item->'sampleRef';
        IF pm_sample_ref IS NOT NULL AND jsonb_typeof(pm_sample_ref)='object' THEN
          IF pm_sample_ref->>'recordId' IS NULL
             OR pm_sample_ref->>'identifier' IS NULL
             OR pm_sample_ref->>'title' IS NULL THEN
            RAISE EXCEPTION 'invalid sample reference in well %', pm_well_code USING ERRCODE='23514';
          END IF;
          -- Validate same-workspace sample record
          BEGIN
            SELECT * INTO pm_sample_target FROM api.records WHERE id=(pm_sample_ref->>'recordId')::uuid;
          EXCEPTION WHEN invalid_text_representation THEN
            RAISE EXCEPTION 'invalid sample reference UUID in well %', pm_well_code USING ERRCODE='23514';
          END;
          IF pm_sample_target.id IS NULL
             OR pm_sample_target.deleted_at IS NOT NULL
             OR pm_sample_target.workspace_id <> owner.workspace_id
             OR pm_sample_target.kind <> 'sample'
             OR pm_sample_ref->>'identifier' IS DISTINCT FROM pm_sample_target.identifier
             OR pm_sample_ref->>'title' IS DISTINCT FROM pm_sample_target.title THEN
            RAISE EXCEPTION 'invalid sample reference target in well %', pm_well_code USING ERRCODE='23514';
          END IF;
          -- Create/update deduplicated record_link (same pattern as materials)
          INSERT INTO api.record_links(source_record_id,target_record_id,target_kind,target_identifier,link_type,created_by_user_id)
          VALUES(owner.id, pm_sample_target.id, 'sample', pm_sample_target.identifier, 'sample', COALESCE(pm_actor, NEW.created_by_user_id))
          ON CONFLICT (source_record_id,target_identifier,link_type) DO UPDATE SET
            target_record_id = EXCLUDED.target_record_id,
            target_kind = EXCLUDED.target_kind;
        END IF;
        -- replicate (optional, must be positive integer)
        IF pm_well_item ? 'replicate' AND jsonb_typeof(pm_well_item->'replicate')='number' THEN
          pm_replicate := (pm_well_item->>'replicate')::int;
          IF pm_replicate < 1 OR pm_replicate <> trunc(pm_replicate::numeric) THEN
            RAISE EXCEPTION 'invalid replicate in well %', pm_well_code USING ERRCODE='23514';
          END IF;
        END IF;
        -- volume (optional, value must be positive)
        pm_vol_obj := pm_well_item->'volume';
        IF pm_vol_obj IS NOT NULL AND jsonb_typeof(pm_vol_obj)='object' THEN
          IF jsonb_typeof(pm_vol_obj->'value') IS DISTINCT FROM 'number'
             OR (pm_vol_obj->>'value')::numeric <= 0
             OR pm_vol_obj->>'unit' IS NULL
             OR btrim(pm_vol_obj->>'unit')='' THEN
            RAISE EXCEPTION 'invalid volume in well %', pm_well_code USING ERRCODE='23514';
          END IF;
        END IF;
      END LOOP;
    END plate_map_spec;
  ELSE
    IF current_user='api_client' THEN
      RAISE EXCEPTION 'credential-authored scientific block writes are not supported' USING ERRCODE='42501';
    END IF;
    actor := CASE WHEN current_user='authenticated' THEN api.current_user_id() ELSE NULL END;
    IF owner.kind<>'experiment' OR jsonb_typeof(NEW.payload->'items') IS DISTINCT FROM 'array' THEN RAISE EXCEPTION 'invalid materials payload' USING ERRCODE='23514'; END IF;
    IF EXISTS (SELECT 1 FROM jsonb_array_elements(NEW.payload->'items') i GROUP BY i->>'id' HAVING count(*)>1) THEN
      RAISE EXCEPTION 'duplicate material item id' USING ERRCODE='23514';
    END IF;
    FOR item IN SELECT value FROM jsonb_array_elements(NEW.payload->'items') LOOP
      item_id:=item->>'id';
      IF item_id IS NULL OR item_id='' OR jsonb_typeof(item->'materialRecordId') IS DISTINCT FROM 'string'
        OR jsonb_typeof(item->'kind') IS DISTINCT FROM 'string'
        OR jsonb_typeof(item->'identifier') IS DISTINCT FROM 'string'
        OR jsonb_typeof(item->'title') IS DISTINCT FROM 'string'
        OR jsonb_typeof(item->'quantity') IS DISTINCT FROM 'number' OR (item->>'quantity')::numeric<=0
        OR jsonb_typeof(item->'unit') IS DISTINCT FROM 'object' OR jsonb_typeof(item#>'{unit,code}') IS DISTINCT FROM 'string'
        OR jsonb_typeof(item#>'{unit,symbol}') IS DISTINCT FROM 'string' OR btrim(item#>>'{unit,code}')='' OR btrim(item#>>'{unit,symbol}')=''
        OR item->>'observedAt' IS NULL THEN RAISE EXCEPTION 'invalid material item' USING ERRCODE='23514'; END IF;
      BEGIN PERFORM (item->>'observedAt')::timestamptz;
      EXCEPTION WHEN invalid_datetime_format OR datetime_field_overflow THEN RAISE EXCEPTION 'invalid material observation timestamp' USING ERRCODE='23514'; END;
      IF TG_OP='UPDATE' THEN
        SELECT value INTO old_item FROM jsonb_array_elements(OLD.payload->'items') WHERE value->>'id'=item_id;
        IF old_item IS NOT NULL AND (item->'materialRecordId' IS DISTINCT FROM old_item->'materialRecordId'
          OR item->'kind' IS DISTINCT FROM old_item->'kind' OR item->'identifier' IS DISTINCT FROM old_item->'identifier'
          OR item->'title' IS DISTINCT FROM old_item->'title' OR item->'observedAt' IS DISTINCT FROM old_item->'observedAt') THEN
          RAISE EXCEPTION 'material observation identity is immutable' USING ERRCODE='23514'; END IF;
      END IF;
      IF old_item IS NULL THEN
        BEGIN SELECT * INTO target FROM api.records WHERE id=(item->>'materialRecordId')::uuid;
        EXCEPTION WHEN invalid_text_representation THEN RAISE EXCEPTION 'invalid material UUID' USING ERRCODE='23514'; END;
        IF target.id IS NULL OR target.deleted_at IS NOT NULL OR target.workspace_id<>owner.workspace_id
          OR target.kind NOT IN ('sample','material') OR item->>'kind' IS DISTINCT FROM target.kind
          OR item->>'identifier' IS DISTINCT FROM target.identifier OR item->>'title' IS DISTINCT FROM target.title THEN
          RAISE EXCEPTION 'invalid material target' USING ERRCODE='23514'; END IF;
        IF target.status = 'expired' THEN
          RAISE EXCEPTION 'material % has expired and cannot be referenced', target.identifier
            USING ERRCODE = 'SB124';
        END IF;
        IF target.status = 'quarantined' THEN
          RAISE EXCEPTION 'material % is quarantined and cannot be referenced', target.identifier
            USING ERRCODE = 'SB120';
        END IF;
        INSERT INTO api.record_links(source_record_id,target_record_id,target_kind,target_identifier,link_type,created_by_user_id)
        VALUES(owner.id,target.id,target.kind,target.identifier,target.kind,COALESCE(actor,NEW.created_by_user_id))
        ON CONFLICT (source_record_id,target_identifier,link_type) DO UPDATE SET target_record_id=EXCLUDED.target_record_id,target_kind=EXCLUDED.target_kind;
      END IF;
    END LOOP;
  END IF;
  RETURN NEW;
END $_$;
--> statement-breakpoint
ALTER FUNCTION api.validate_scientific_block() OWNER TO migrator;
--> statement-breakpoint
CREATE FUNCTION api.validate_sheet_record_batch(p_project_id uuid, p_model_key text, p_rows jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
  workspace uuid := api.current_workspace_id();
  v_kind text;
  item jsonb;
  row_index integer := 0;
  results jsonb := '[]'::jsonb;
  errors jsonb;
  classification text;
  match_id uuid;
  existing api.records;
  custom jsonb;
  v_title text;
  v_row_key text;
  v_operation text;
  seen_keys text[] := '{}';
  seen_matches text[] := '{}';
  identifier_key text;
  duplicate_matches text[] := '{}';
BEGIN
 IF p_project_id IS NOT NULL THEN PERFORM internal.assert_object_access('project',p_project_id,'view'); END IF;
  IF workspace IS NULL THEN
    RAISE EXCEPTION 'capability required: record.link' USING ERRCODE = '42501';
  END IF;
  PERFORM api.assert_record_batch_capabilities(workspace, p_rows);
  IF NOT EXISTS (
    SELECT 1 FROM api.projects
     WHERE id = p_project_id AND workspace_id = workspace
  ) THEN
    RAISE EXCEPTION 'project not found in active workspace' USING ERRCODE = '42501';
  END IF;
  SELECT record_kind INTO v_kind
    FROM api.model_kinds
   WHERE key = p_model_key AND identity_table = 'api.records' AND record_kind IS NOT NULL;
  IF v_kind IS NULL THEN
    RAISE EXCEPTION 'model does not support Sheet Record batches' USING ERRCODE = '22023';
  END IF;
  IF jsonb_typeof(p_rows) <> 'array'
     OR jsonb_array_length(p_rows) = 0
     OR jsonb_array_length(p_rows) > 1000 THEN
    RAISE EXCEPTION '1 to 1000 batch rows are required' USING ERRCODE = '22023';
  END IF;

  SELECT coalesce(array_agg(identifier), '{}')
    INTO duplicate_matches
    FROM (
      SELECT value->>'matchIdentifier' AS identifier
      FROM jsonb_array_elements(p_rows) value
      WHERE value->>'operation' = 'create'
        AND nullif(btrim(coalesce(value->>'matchIdentifier', '')), '') IS NOT NULL
      GROUP BY value->>'matchIdentifier'
      HAVING count(*) > 1
    ) d;

  FOR item IN SELECT value FROM jsonb_array_elements(p_rows) LOOP
    row_index := row_index + 1;
    errors := '[]'::jsonb;
    classification := NULL;
    match_id := NULL;
    IF jsonb_typeof(item) <> 'object'
       OR jsonb_typeof(item->'rowKey') <> 'string'
       OR length(btrim(item->>'rowKey')) = 0
       OR item->>'operation' NOT IN ('create', 'link') THEN
      RAISE EXCEPTION 'invalid Sheet Record batch row shape' USING ERRCODE = '22023';
    END IF;
    v_row_key := item->>'rowKey';
    v_operation := item->>'operation';
    IF v_row_key = ANY (seen_keys) THEN
      RAISE EXCEPTION 'duplicate Sheet row key in batch' USING ERRCODE = '22023';
    END IF;
    seen_keys := array_append(seen_keys, v_row_key);

    IF v_operation = 'link' THEN
      BEGIN
        match_id := (item->>'recordId')::uuid;
      EXCEPTION WHEN invalid_text_representation THEN
        errors := errors || jsonb_build_array(jsonb_build_object(
          'code', 'not-uuid',
          'message', 'Record reference identity is the Record UUID, not the Record ID or Name.'
        ));
        match_id := NULL;
      END;
      IF match_id IS NULL AND jsonb_array_length(errors) = 0 THEN
        errors := errors || jsonb_build_array(jsonb_build_object(
          'code', 'required',
          'message', 'Record reference is required.'
        ));
      ELSIF match_id IS NOT NULL THEN
        SELECT * INTO existing
          FROM api.records r
         WHERE r.id = match_id
           AND r.workspace_id = workspace
           AND r.kind = v_kind
           AND r.deleted_at IS NULL;
        IF existing.id IS NULL THEN
          errors := errors || jsonb_build_array(jsonb_build_object(
            'code', 'missing',
            'message', 'Record is not visible in this workspace and Model.'
          ));
        ELSIF existing.archived_at IS NOT NULL THEN
          errors := errors || jsonb_build_array(jsonb_build_object(
            'code', 'archived_target',
            'fieldName', 'recordId',
            'message', 'Archived Records cannot be newly linked from a Sheet.'
          ));
        ELSE
          classification := 'link';
        END IF;
      END IF;
    ELSE
      IF item ? 'identifier' THEN
        errors := errors || jsonb_build_array(jsonb_build_object(
          'code', 'record_id_policy',
          'fieldName', 'identifier',
          'message', 'Sheet creation uses Model-generated PREFIX-YYYY-NNNN identifiers.'
        ));
      END IF;
      v_title := nullif(btrim(coalesce(item->>'title', '')), '');
      custom := coalesce(item->'values', '{}'::jsonb);
      IF jsonb_typeof(custom) <> 'object' THEN
        RAISE EXCEPTION 'invalid Sheet Record batch row shape' USING ERRCODE = '22023';
      END IF;
      identifier_key := nullif(btrim(coalesce(item->>'matchIdentifier', '')), '');
      IF identifier_key IS NOT NULL AND identifier_key = ANY (duplicate_matches) THEN
        errors := errors || jsonb_build_array(jsonb_build_object(
          'code', 'duplicate_input_row',
          'fieldName', 'matchIdentifier',
          'message', 'Duplicate match identifier in this batch.'
        ));
      ELSIF identifier_key IS NOT NULL THEN
        seen_matches := array_append(seen_matches, identifier_key);
        SELECT * INTO existing
          FROM api.records r
         WHERE r.project_id = p_project_id
           AND r.kind = v_kind
           AND r.identifier = identifier_key
           AND r.deleted_at IS NULL;
        IF existing.id IS NOT NULL THEN
          IF existing.archived_at IS NOT NULL THEN
            errors := errors || jsonb_build_array(jsonb_build_object(
              'code', 'archived_target',
              'fieldName', 'matchIdentifier',
              'message', 'Matched Record is archived.'
            ));
          ELSE
            classification := 'existing';
            match_id := existing.id;
          END IF;
        END IF;
      END IF;
      IF classification IS NULL AND jsonb_array_length(errors) = 0 THEN
        IF v_title IS NULL THEN
          errors := errors || jsonb_build_array(jsonb_build_object(
            'code', 'required_value',
            'fieldName', 'title',
            'message', 'Record Name is required.'
          ));
        ELSE
          BEGIN
            PERFORM internal.validate_model_fields(workspace, p_model_key, custom, '{}'::jsonb);
            classification := 'create';
          EXCEPTION WHEN OTHERS THEN
            errors := errors || jsonb_build_array(jsonb_build_object(
              'code', SQLSTATE,
              'message', SQLERRM
            ));
          END;
        END IF;
      END IF;
    END IF;

    IF jsonb_array_length(errors) > 0 THEN
      classification := 'invalid';
      match_id := NULL;
    END IF;

    results := results || jsonb_build_array(jsonb_build_object(
      'rowIndex', row_index,
      'rowKey', v_row_key,
      'classification', classification,
      'recordId', match_id,
      'errors', errors
    ));
  END LOOP;

  RETURN jsonb_build_object(
    'ok', NOT EXISTS (
      SELECT 1 FROM jsonb_array_elements(results) value
      WHERE value->>'classification' = 'invalid'
    ),
    'mutated', false,
    'rows', results
  );
END
$$;
--> statement-breakpoint
ALTER FUNCTION api.validate_sheet_record_batch(p_project_id uuid, p_model_key text, p_rows jsonb) OWNER TO migrator;
--> statement-breakpoint
CREATE FUNCTION api.verify_audit_chain(p_workspace_id uuid) RETURNS TABLE(ok boolean, checked integer, first_bad_sequence bigint, first_bad_id uuid)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
BEGIN
  IF p_workspace_id IS DISTINCT FROM api.current_workspace_id()
     OR NOT api.has_capability(p_workspace_id, 'workspace.admin') THEN
    RAISE EXCEPTION 'admin access required' USING ERRCODE = '42501';
  END IF;
  RETURN QUERY SELECT * FROM internal.verify_audit_chain(p_workspace_id);
END $$;
