    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  SELECT r.* FROM api.projects p CROSS JOIN LATERAL api.project_access_rules(p.id) r WHERE p.workspace_id=api.current_workspace_id()
