CREATE FUNCTION internal.ad_hoc_sheet_instance_state() RETURNS jsonb
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
DECLARE
  field_id uuid := gen_random_uuid();
BEGIN
  RETURN jsonb_build_object(
    'bindings', '[]'::jsonb,
    'localFields', jsonb_build_array(
      jsonb_build_object(
        'fieldId', field_id,
        'key', 'column_1',
        'label', 'Column 1',
        'description', NULL,
        'logicalType', 'text',
        'nullable', true,
        'defaultValue', NULL,
        'cardinality', 'one',
        'quantity', NULL,
        'validation', '{}'::jsonb,
        'category', NULL,
        'relationship', NULL,
        'computation', jsonb_build_object('mode', 'stored'),
        'lifecycle', 'active'
      )
    ),
    'localValues', '{}'::jsonb,
    'calculationOverrides', '{}'::jsonb,
    'presentation', jsonb_build_object(
      'columnOrder', jsonb_build_array(field_id),
      'hiddenColumnIds', '[]'::jsonb,
      'columnWidths', '{}'::jsonb,
      'frozenColumnCount', 0,
      'density', 'standard',
      'filters', '[]'::jsonb,
      'sorts', '[]'::jsonb
    ),
    'provenance', jsonb_build_object('createdFrom', 'ad_hoc')
  );
END
$$;
