CREATE FUNCTION internal.add_scientific_column_impl(p_table_id uuid, p_expected_schema_version integer, p_label text, p_logical_type text, p_nullable boolean DEFAULT true, p_default jsonb DEFAULT NULL::jsonb, p_unit jsonb DEFAULT NULL::jsonb, p_validation jsonb DEFAULT '{}'::jsonb, p_options jsonb DEFAULT NULL::jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE t api.scientific_tables; a jsonb; fn text; cid uuid:=gen_random_uuid(); n int; compiled jsonb; spec jsonb; chk text; rows_exist boolean; option_item jsonb; option_ord int:=0;
BEGIN SELECT * INTO t FROM api.scientific_tables WHERE id=p_table_id FOR UPDATE; IF t.id IS NULL OR t.lifecycle<>'active' THEN RAISE EXCEPTION 'active table required' USING ERRCODE='22023'; END IF; IF t.schema_version<>p_expected_schema_version THEN RAISE EXCEPTION 'schema version mismatch' USING ERRCODE='SB001'; END IF; a:=internal.assert_scientific_actor(t.workspace_id); spec:=jsonb_build_object('label',p_label,'logical_type',p_logical_type,'nullable',p_nullable,'validation',coalesce(p_validation,'{}'::jsonb)) || CASE WHEN p_default IS NULL THEN '{}' ELSE jsonb_build_object('default',p_default) END || CASE WHEN p_unit IS NULL THEN '{}' ELSE jsonb_build_object('unit',p_unit) END || CASE WHEN p_options IS NULL THEN '{}' ELSE jsonb_build_object('options',p_options) END; compiled:=internal.compile_scientific_column(spec); IF p_options IS NOT NULL AND jsonb_typeof(p_options)<>'array' THEN RAISE EXCEPTION 'options must be an array' USING ERRCODE='22023'; END IF; EXECUTE format('SELECT EXISTS(SELECT 1 FROM api.%I)',t.resource_name) INTO rows_exist; IF NOT p_nullable AND rows_exist AND p_default IS NULL THEN RAISE EXCEPTION 'required column on populated table requires typed default/backfill' USING ERRCODE='23514'; END IF; SELECT coalesce(max(display_order),0)+1 INTO n FROM api.scientific_columns WHERE table_id=t.id; LOOP fn:=internal.scientific_name('col_'); EXIT WHEN NOT EXISTS(SELECT 1 FROM api.scientific_columns WHERE field_name=fn); END LOOP; INSERT INTO api.scientific_columns(id,table_id,workspace_id,field_name,label,display_order,logical_type,nullable,default_value,unit,validation,created_by_user_id,created_by_credential_id) VALUES(cid,t.id,t.workspace_id,fn,p_label,n,p_logical_type,p_nullable,p_default,p_unit,coalesce(p_validation,'{}'),a->>'user_id',(a->>'credential_id')::uuid); IF p_logical_type='category' THEN FOR option_item IN SELECT value FROM jsonb_array_elements(coalesce(p_options,'[]')) LOOP option_ord:=option_ord+1; IF jsonb_typeof(option_item)<>'object' OR option_item-ARRAY['id','label']<>'{}' OR jsonb_typeof(option_item->'label')<>'string' OR (option_item ? 'id' AND jsonb_typeof(option_item->'id')<>'string') OR NULLIF(option_item->>'label','') IS NULL THEN RAISE EXCEPTION 'invalid category option' USING ERRCODE='22023'; END IF; INSERT INTO api.scientific_category_options(id,column_id,workspace_id,label,display_order) VALUES(coalesce((option_item->>'id')::uuid,gen_random_uuid()),cid,t.workspace_id,option_item->>'label',option_ord); END LOOP; IF p_default IS NOT NULL AND NOT EXISTS(SELECT 1 FROM api.scientific_category_options WHERE column_id=cid AND id=(p_default#>>'{}')::uuid AND lifecycle='active') THEN RAISE EXCEPTION 'category default must be an active option of the exact column' USING ERRCODE='23514'; END IF; END IF; EXECUTE format('ALTER TABLE api.%I ADD COLUMN %I %s%s%s',t.resource_name,fn,compiled->>'storageType',compiled->>'defaultSql',compiled->>'notNullSql'); FOR chk IN SELECT value#>>'{}' FROM jsonb_array_elements(compiled->'checks') LOOP EXECUTE format('ALTER TABLE api.%I ADD CHECK (%s)',t.resource_name,internal.render_scientific_check(chk::jsonb,fn)); END LOOP; EXECUTE format('GRANT INSERT (%I), UPDATE (%I) ON api.%I TO authenticated',fn,fn,t.resource_name); UPDATE api.scientific_tables SET schema_version=schema_version+1,updated_at=now(),updated_by_user_id=a->>'user_id' WHERE id=t.id; PERFORM internal.emit_change_event(t.workspace_id,'scientific_table',t.id,'update',t.record_id,NULL,jsonb_build_object('operation','add_column','columnIds',jsonb_build_array(cid),'schemaVersion',t.schema_version+1)); PERFORM pg_notify('pgrst','reload schema'); RETURN (SELECT to_jsonb(c) FROM api.scientific_columns c WHERE id=cid); END $$;
--> statement-breakpoint
ALTER FUNCTION internal.add_scientific_column_impl(p_table_id uuid, p_expected_schema_version integer, p_label text, p_logical_type text, p_nullable boolean, p_default jsonb, p_unit jsonb, p_validation jsonb, p_options jsonb) OWNER TO migrator;
--> statement-breakpoint
CREATE FUNCTION internal.agent_operation_append_event(p_proposal api.agent_operation_proposals, p_event_type text, p_detail jsonb DEFAULT '{}'::jsonb) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
BEGIN
  INSERT INTO api.agent_operation_events(
    workspace_id, proposal_id, sequence, event_type,
    actor_user_id, actor_credential_id, detail
  ) VALUES (
    p_proposal.workspace_id,
    p_proposal.id,
    coalesce((
      SELECT max(sequence) + 1
      FROM api.agent_operation_events
      WHERE proposal_id = p_proposal.id
    ), 1),
    p_event_type,
    api.current_user_id(),
    api.current_credential_id(),
    coalesce(p_detail, '{}'::jsonb)
  );
END;
$$;
--> statement-breakpoint
ALTER FUNCTION internal.agent_operation_append_event(p_proposal api.agent_operation_proposals, p_event_type text, p_detail jsonb) OWNER TO migrator;
--> statement-breakpoint
CREATE FUNCTION internal.agent_operation_contract(p_workspace_id uuid, p_operation jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $_$
DECLARE
  v_kind text;
  v_target jsonb;
  v_validation jsonb;
  v_workspace uuid;
  v_revision bigint;
  v_lifecycle text;
  v_errors jsonb;
BEGIN
  IF jsonb_typeof(p_operation) IS DISTINCT FROM 'object' THEN
    RAISE EXCEPTION 'operation must be an object' USING ERRCODE = '22023';
  END IF;
  v_kind := p_operation->>'kind';

  IF v_kind = 'dataset_schema.create' THEN
    PERFORM internal.require_agent_proposal_permission(p_workspace_id, 'schema.edit');
    IF p_operation - ARRAY['kind','workspaceId','key','name','description','fields'] <> '{}'::jsonb
       OR (p_operation->>'workspaceId')::uuid IS DISTINCT FROM p_workspace_id
       OR p_operation->>'key' !~ '^[a-z][a-z0-9_]{0,59}$'
       OR length(btrim(p_operation->>'name')) NOT BETWEEN 1 AND 200
       OR jsonb_typeof(p_operation->'fields') IS DISTINCT FROM 'array'
       OR jsonb_array_length(p_operation->'fields') > 200 THEN
      RAISE EXCEPTION 'invalid Dataset Schema create operation' USING ERRCODE = '22023';
    END IF;
    v_target := jsonb_build_object('type','dataset_schema','id',NULL,'label',p_operation->>'name');
    RETURN jsonb_build_object(
      'preview', jsonb_build_object(
        'formatVersion',1,
        'kind',v_kind,
        'target',v_target,
        'changes',jsonb_build_array(
          jsonb_build_object('path','definition','before',NULL,'after',
            jsonb_build_object('key',p_operation->>'key','name',p_operation->>'name')),
          jsonb_build_object('path','fields','before',0,'after',jsonb_array_length(p_operation->'fields'))
        )
      ),
      'impact', jsonb_build_object(
        'formatVersion',1,'mutationClass','configuration','target',v_target,
        'createsDraft',true,'affectedRows',0,'destructive',false
      )
    );

  ELSIF v_kind = 'sheet_definition.create' THEN
    PERFORM internal.require_agent_proposal_permission(p_workspace_id, 'schema.edit');
    IF p_operation - ARRAY['kind','workspaceId','key','name','description','configuration'] <> '{}'::jsonb
       OR (p_operation->>'workspaceId')::uuid IS DISTINCT FROM p_workspace_id THEN
      RAISE EXCEPTION 'invalid Sheet Definition create operation' USING ERRCODE = '22023';
    END IF;
    PERFORM internal.validate_sheet_definition_configuration(p_operation->'configuration');
    v_target := jsonb_build_object('type','sheet_definition','id',NULL,'label',p_operation->>'name');

  ELSIF v_kind = 'sheet_definition.update_draft' THEN
    PERFORM internal.require_agent_proposal_permission(p_workspace_id, 'schema.edit');
    SELECT d.workspace_id, v.revision, v.lifecycle
      INTO v_workspace, v_revision, v_lifecycle
      FROM api.sheet_definition_versions v
      JOIN api.sheet_definitions d ON d.id = v.definition_id
     WHERE v.id = (p_operation->>'versionId')::uuid;
    IF p_operation - ARRAY['kind','versionId','expectedRevision','configuration'] <> '{}'::jsonb
       OR v_workspace IS DISTINCT FROM p_workspace_id
       OR v_lifecycle IS DISTINCT FROM 'draft' THEN
      RAISE EXCEPTION 'Sheet Definition draft unavailable' USING ERRCODE = '42501';
    END IF;
    PERFORM internal.validate_sheet_definition_configuration(p_operation->'configuration');
    v_target := jsonb_build_object('type','sheet_definition_version','id',p_operation->>'versionId','label','Draft version');
    RETURN jsonb_build_object(
      'preview', jsonb_build_object(
        'formatVersion',1,'kind',v_kind,'target',v_target,
        'expectedRevision',(p_operation->>'expectedRevision')::bigint,
        'currentRevision',v_revision,
        'changes',jsonb_build_array(jsonb_build_object(
          'path','configuration',
          'before',(SELECT configuration FROM api.sheet_definition_versions WHERE id=(p_operation->>'versionId')::uuid),
          'after',p_operation->'configuration'
        ))
      ),
      'impact', jsonb_build_object(
        'formatVersion',1,'mutationClass','configuration','target',v_target,
        'createsDraft',false,'affectedRows',0,'destructive',false
      )
    );

  ELSIF v_kind = 'pipeline_definition.create' THEN
    PERFORM internal.require_agent_proposal_permission(p_workspace_id, 'pipelines.manage');
    IF p_operation - ARRAY['kind','workspaceId','key','name','description'] <> '{}'::jsonb
       OR (p_operation->>'workspaceId')::uuid IS DISTINCT FROM p_workspace_id THEN
      RAISE EXCEPTION 'invalid Pipeline Definition create operation' USING ERRCODE = '22023';
    END IF;
    v_target := jsonb_build_object('type','pipeline_definition','id',NULL,'label',p_operation->>'name');

  ELSIF v_kind = 'pipeline_definition.create_version' THEN
    PERFORM internal.require_agent_proposal_permission(p_workspace_id, 'pipelines.manage');
    SELECT workspace_id, revision, lifecycle
      INTO v_workspace, v_revision, v_lifecycle
      FROM api.pipeline_definitions
     WHERE id = (p_operation->>'definitionId')::uuid;
    v_errors := api.pipeline_config_errors(p_operation->'configuration');
    IF p_operation - ARRAY['kind','workspaceId','definitionId','expectedDefinitionRevision','configuration'] <> '{}'::jsonb
       OR (p_operation->>'workspaceId')::uuid IS DISTINCT FROM p_workspace_id
       OR v_workspace IS DISTINCT FROM p_workspace_id
       OR v_lifecycle IS DISTINCT FROM 'active'
       OR jsonb_array_length(v_errors) > 0 THEN
      RAISE EXCEPTION 'invalid Pipeline Definition version operation: %', v_errors USING ERRCODE = '22023';
    END IF;
    v_target := jsonb_build_object('type','pipeline_definition','id',p_operation->>'definitionId','label','New draft version');
    RETURN jsonb_build_object(
      'preview', jsonb_build_object(
        'formatVersion',1,'kind',v_kind,'target',v_target,
        'expectedRevision',(p_operation->>'expectedDefinitionRevision')::bigint,
        'currentRevision',v_revision,
        'changes',jsonb_build_array(jsonb_build_object('path','configuration','before',NULL,'after',p_operation->'configuration'))
      ),
      'impact', jsonb_build_object(
        'formatVersion',1,'mutationClass','configuration','target',v_target,
        'createsDraft',true,'affectedRows',0,'destructive',false
      )
    );

  ELSIF v_kind = 'pipeline_definition.update_draft' THEN
    PERFORM internal.require_agent_proposal_permission(p_workspace_id, 'pipelines.manage');
    SELECT workspace_id, revision, lifecycle
      INTO v_workspace, v_revision, v_lifecycle
      FROM api.pipeline_definition_versions
     WHERE id = (p_operation->>'versionId')::uuid;
    v_errors := api.pipeline_config_errors(p_operation->'configuration');
    IF p_operation - ARRAY['kind','workspaceId','versionId','expectedRevision','configuration'] <> '{}'::jsonb
       OR (p_operation->>'workspaceId')::uuid IS DISTINCT FROM p_workspace_id
       OR v_workspace IS DISTINCT FROM p_workspace_id
       OR v_lifecycle IS DISTINCT FROM 'draft'
       OR jsonb_array_length(v_errors) > 0 THEN
      RAISE EXCEPTION 'invalid Pipeline draft operation: %', v_errors USING ERRCODE = '22023';
    END IF;
    v_target := jsonb_build_object('type','pipeline_definition_version','id',p_operation->>'versionId','label','Draft version');
    RETURN jsonb_build_object(
      'preview', jsonb_build_object(
        'formatVersion',1,'kind',v_kind,'target',v_target,
        'expectedRevision',(p_operation->>'expectedRevision')::bigint,
        'currentRevision',v_revision,
        'changes',jsonb_build_array(jsonb_build_object(
          'path','configuration',
          'before',(SELECT configuration FROM api.pipeline_definition_versions WHERE id=(p_operation->>'versionId')::uuid),
          'after',p_operation->'configuration'
        ))
      ),
      'impact', jsonb_build_object(
        'formatVersion',1,'mutationClass','configuration','target',v_target,
        'createsDraft',false,'affectedRows',0,'destructive',false
      )
    );

  ELSIF v_kind = 'dataset_rows.commit' THEN
    PERFORM internal.require_agent_proposal_permission(p_workspace_id, 'record.create');
    SELECT workspace_id, revision, lifecycle
      INTO v_workspace, v_revision, v_lifecycle
      FROM api.datasets
     WHERE id = (p_operation->>'datasetId')::uuid;
    IF p_operation - ARRAY['kind','datasetId','expectedRevision','rows'] <> '{}'::jsonb
       OR v_workspace IS DISTINCT FROM p_workspace_id
       OR v_lifecycle IS DISTINCT FROM 'active'
       OR jsonb_typeof(p_operation->'rows') IS DISTINCT FROM 'array'
       OR jsonb_array_length(p_operation->'rows') NOT BETWEEN 1 AND 1000 THEN
      RAISE EXCEPTION 'invalid Dataset row operation' USING ERRCODE = '22023';
    END IF;
    v_validation := api.validate_dataset_row_batch(
      (p_operation->>'datasetId')::uuid,
      (p_operation->>'expectedRevision')::bigint,
      p_operation->'rows'
    );
    IF (v_validation->>'ok')::boolean IS NOT TRUE THEN
      RAISE EXCEPTION 'Dataset row operation failed validation: %', v_validation USING ERRCODE = 'SB073';
    END IF;
    v_target := jsonb_build_object('type','dataset','id',p_operation->>'datasetId','label','Dataset rows');
    RETURN jsonb_build_object(
      'preview', jsonb_build_object(
        'formatVersion',1,'kind',v_kind,'target',v_target,
        'expectedRevision',(p_operation->>'expectedRevision')::bigint,
        'currentRevision',v_revision,
        'changes',(SELECT coalesce(jsonb_agg(jsonb_build_object(
          'path','rows.' || (item->>'rowId'),
          'before',NULL,
          'after',item
        ) ORDER BY ordinality),'[]'::jsonb) FROM jsonb_array_elements(p_operation->'rows') WITH ORDINALITY AS rows(item,ordinality))
      ),
      'impact', jsonb_build_object(
        'formatVersion',1,'mutationClass','data','target',v_target,
        'createsDraft',false,'affectedRows',jsonb_array_length(p_operation->'rows'),
        'destructive',false,'validation',v_validation
      )
    );
  ELSIF v_kind = 'notebook_block.insert' THEN
    PERFORM internal.require_agent_proposal_permission(p_workspace_id, 'record.create');
    SELECT workspace_id, structure_version INTO v_workspace, v_revision
      FROM api.records WHERE id = (p_operation->>'recordId')::uuid;
    IF p_operation - ARRAY['kind','recordId','afterBlockId','block','expectedRevision'] <> '{}'::jsonb
       OR v_workspace IS DISTINCT FROM p_workspace_id
       OR p_operation->>'expectedRevision' IS NULL
       OR jsonb_typeof(p_operation->'block') IS DISTINCT FROM 'object'
       OR length(btrim(coalesce(p_operation->'block'->>'type',''))) NOT BETWEEN 1 AND 48
       OR jsonb_typeof(p_operation->'block'->'payload') IS DISTINCT FROM 'object' THEN
      RAISE EXCEPTION 'invalid notebook block operation' USING ERRCODE = '22023';
    END IF;
    v_target := jsonb_build_object('type','record','id',p_operation->>'recordId','label','Notebook block');
    RETURN jsonb_build_object(
      'preview', jsonb_build_object(
        'formatVersion',1,'kind',v_kind,'target',v_target,
        'expectedRevision',(p_operation->>'expectedRevision')::bigint,
        'currentRevision',v_revision,
        'changes', jsonb_build_array(jsonb_build_object(
          'path','blocks','before',NULL,
          'after', jsonb_build_object(
            'afterBlockId',p_operation->'afterBlockId',
            'type',p_operation->'block'->>'type',
            'payload',p_operation->'block'->'payload'
          )
        ))
      ),
      'impact', jsonb_build_object(
        'formatVersion',1,'mutationClass','content','target',v_target,
        'createsDraft',false,'affectedRows',1,'destructive',false
      )
    );
  ELSE
    RAISE EXCEPTION 'unsupported or human-only operation kind' USING ERRCODE = '22023';
  END IF;

  RETURN jsonb_build_object(
    'preview', jsonb_build_object(
      'formatVersion',1,'kind',v_kind,'target',v_target,
      'changes',jsonb_build_array(jsonb_build_object('path','definition','before',NULL,'after',p_operation - 'kind'))
    ),
    'impact', jsonb_build_object(
      'formatVersion',1,'mutationClass','configuration','target',v_target,
      'createsDraft',v_kind = 'sheet_definition.create',
      'affectedRows',0,'destructive',false
    )
  );
END;
$_$;
--> statement-breakpoint
ALTER FUNCTION internal.agent_operation_contract(p_workspace_id uuid, p_operation jsonb) OWNER TO migrator;
--> statement-breakpoint
CREATE FUNCTION internal.agent_operation_execute(p_proposal_id uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
  v_result api.agent_operation_proposals;
  v_operation jsonb;
  v_execution jsonb;
  v_pipeline_revision bigint;
  v_code text;
  v_message text;
BEGIN
  SELECT * INTO v_result
    FROM api.agent_operation_proposals
   WHERE id = p_proposal_id AND workspace_id = api.current_workspace_id()
   FOR UPDATE;
  IF v_result.id IS NULL
     OR v_result.status NOT IN ('pending', 'approved')
     OR (v_result.status = 'pending' AND v_result.approval_policy = 'human_required') THEN
    RAISE EXCEPTION 'proposal is not executable' USING ERRCODE = 'SB001';
  END IF;
  UPDATE api.agent_operation_proposals
     SET status = 'executing',
         revision = revision + 1,
         executed_by_user_id = api.current_user_id(),
         executed_by_credential_id = api.current_credential_id(),
         executed_at = now(),
         updated_at = now()
   WHERE id = v_result.id
  RETURNING * INTO v_result;
  PERFORM internal.agent_operation_append_event(v_result,'execution_started','{}'::jsonb);
  v_operation := v_result.operation;

  BEGIN
    IF v_result.operation_kind = 'dataset_schema.create' THEN
      v_execution := api.create_dataset_schema_definition(
        v_result.workspace_id,v_operation->>'key',v_operation->>'name',
        v_operation->>'description',v_operation->'fields'
      );
    ELSIF v_result.operation_kind = 'sheet_definition.create' THEN
      v_execution := api.create_sheet_definition(
        v_result.workspace_id,v_operation->>'key',v_operation->>'name',
        v_operation->>'description',v_operation->'configuration'
      );
    ELSIF v_result.operation_kind = 'sheet_definition.update_draft' THEN
      v_execution := to_jsonb(api.update_sheet_definition_draft(
        (v_operation->>'versionId')::uuid,
        (v_operation->>'expectedRevision')::bigint,
        v_operation->'configuration'
      ));
    ELSIF v_result.operation_kind = 'pipeline_definition.create' THEN
      v_execution := to_jsonb(api.create_pipeline_definition(
        v_result.workspace_id,v_operation->>'key',v_operation->>'name',
        v_operation->>'description'
      ));
    ELSIF v_result.operation_kind = 'pipeline_definition.create_version' THEN
      SELECT revision INTO v_pipeline_revision
        FROM api.pipeline_definitions
       WHERE id = (v_operation->>'definitionId')::uuid
         AND workspace_id = v_result.workspace_id
       FOR UPDATE;
      IF v_pipeline_revision IS DISTINCT FROM
         (v_operation->>'expectedDefinitionRevision')::bigint THEN
        RAISE EXCEPTION 'stale Pipeline Definition revision' USING ERRCODE = 'SB001';
      END IF;
      v_execution := to_jsonb(api.create_pipeline_definition_version(
        v_result.workspace_id,(v_operation->>'definitionId')::uuid,
        v_operation->'configuration'
      ));
    ELSIF v_result.operation_kind = 'pipeline_definition.update_draft' THEN
      v_execution := to_jsonb(api.update_pipeline_definition_version_draft(
        v_result.workspace_id,(v_operation->>'versionId')::uuid,
        (v_operation->>'expectedRevision')::bigint,v_operation->'configuration'
      ));
    ELSIF v_result.operation_kind = 'dataset_rows.commit' THEN
      v_execution := api.commit_dataset_row_batch(
        (v_operation->>'datasetId')::uuid,
        (v_operation->>'expectedRevision')::bigint,
        v_operation->'rows','agent-proposal:' || v_result.id::text
      );
      IF (v_execution->>'ok')::boolean IS NOT TRUE THEN
        RAISE EXCEPTION 'canonical Dataset commit rejected: %', v_execution USING ERRCODE = 'SB073';
      END IF;
    ELSIF v_result.operation_kind = 'notebook_block.insert' THEN
      v_execution := api.insert_block(
        (v_operation->>'recordId')::uuid,
        v_operation->'block'->>'type',
        v_operation->'block'->'payload',
        coalesce((v_operation->'block'->>'payloadSchemaVersion')::integer, 1),
        nullif(v_operation->>'afterBlockId','')::uuid,
        (v_operation->>'expectedRevision')::integer,
        NULL
      );
    ELSE
      RAISE EXCEPTION 'unsupported or human-only operation kind' USING ERRCODE = '22023';
    END IF;

    UPDATE api.agent_operation_proposals
       SET status = 'succeeded',
           revision = revision + 1,
           result = v_execution,
           error_code = NULL,
           error_message = NULL,
           updated_at = now()
     WHERE id = v_result.id
    RETURNING * INTO v_result;
    PERFORM internal.agent_operation_append_event(v_result,'execution_succeeded',
      jsonb_build_object('result',v_execution));
  EXCEPTION WHEN OTHERS THEN
    GET STACKED DIAGNOSTICS v_code = RETURNED_SQLSTATE, v_message = MESSAGE_TEXT;
    UPDATE api.agent_operation_proposals
       SET status = 'failed',
           revision = revision + 1,
           error_code = v_code,
           error_message = left(v_message,2000),
           updated_at = now()
     WHERE id = v_result.id
    RETURNING * INTO v_result;
    PERFORM internal.agent_operation_append_event(v_result,'execution_failed',
      jsonb_build_object('errorCode',v_code,'message',left(v_message,2000)));
  END;
  PERFORM internal.emit_change_event(
    v_result.workspace_id,'agent_operation_proposal',v_result.id,'update',
    NULL,NULL,jsonb_build_object(
      'status',v_result.status,
      'operationKind',v_result.operation_kind,
      'canonicalResult',v_result.result,
      'policyId',v_result.policy_id,
      'approvalPolicy',v_result.approval_policy
    )
  );
END;
$$;
--> statement-breakpoint
ALTER FUNCTION internal.agent_operation_execute(p_proposal_id uuid) OWNER TO migrator;
--> statement-breakpoint
CREATE FUNCTION internal.agent_operation_policy_evaluate(p_workspace_id uuid, p_operation jsonb, p_contract jsonb) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
  v_kind text := p_operation->>'kind';
  v_target jsonb := p_contract->'preview'->'target';
  v_risk text;
  v_required_scope text;
  v_actor_kind text;
  v_scope_ok boolean := true;
  v_policy api.agent_operation_policies;
  v_affected_rows integer := coalesce((p_contract->'impact'->>'affectedRows')::integer, 0);
  v_max_rows integer;
  v_approval_policy text;
  v_reason text;
  v_policy_limits jsonb := '{}'::jsonb;
  v_policy_id uuid;
  v_target_matched boolean := false;
  v_limit_satisfied boolean := true;
  v_create_only boolean := true;
BEGIN
  v_risk := CASE
    WHEN v_kind IN (
      'dataset_schema.create', 'sheet_definition.create',
      'sheet_definition.update_draft', 'pipeline_definition.create',
      'pipeline_definition.create_version', 'pipeline_definition.update_draft'
    ) THEN 'safe_draft'
    ELSE 'consequential_write'
  END;
  v_required_scope := CASE
    WHEN v_kind = 'dataset_rows.commit' THEN 'datasets:write'
    ELSE 'schema:write'
  END;
  v_actor_kind := CASE
    WHEN api.current_credential_id() IS NOT NULL THEN 'credential'
    WHEN api.current_user_id() IS NOT NULL THEN 'user'
    ELSE 'unknown'
  END;
  IF v_actor_kind = 'credential' THEN
    v_scope_ok := coalesce(api.claim_probe()->'scopes','[]'::jsonb) ? v_required_scope;
  END IF;
  IF v_kind = 'dataset_rows.commit' THEN
    v_create_only := NOT EXISTS (
      SELECT 1
      FROM jsonb_array_elements(coalesce(p_operation->'rows', '[]'::jsonb)) row_item
      WHERE coalesce(row_item->>'operation', '') IS DISTINCT FROM 'create'
    );
  END IF;

  IF v_risk = 'consequential_write' THEN
    SELECT policy.*
      INTO v_policy
      FROM api.agent_operation_policies policy
     WHERE policy.workspace_id = p_workspace_id
       AND policy.operation_kind = v_kind
       AND internal.agent_operation_policy_matches(
         policy, p_workspace_id, p_operation, v_target
       )
     ORDER BY CASE policy.target_type
       WHEN 'dataset' THEN 0
       WHEN 'project' THEN 1
       WHEN 'workspace' THEN 2
       ELSE 3
     END, policy.created_at DESC
     LIMIT 1;
    v_target_matched := v_policy.id IS NOT NULL;
    IF v_target_matched THEN
      v_policy_id := v_policy.id;
      v_policy_limits := v_policy.limits;
      IF v_policy.limits ? 'maxAffectedRows' THEN
        v_max_rows := (v_policy.limits->>'maxAffectedRows')::integer;
        v_limit_satisfied := v_affected_rows <= v_max_rows;
      END IF;
    END IF;
  END IF;

  IF NOT v_scope_ok THEN
    v_approval_policy := 'human_required';
    v_reason := format('External credential lacks required scope %s.', v_required_scope);
  ELSIF v_risk = 'safe_draft' THEN
    v_approval_policy := 'automatic';
    v_reason := 'Safe draft creation or update is reversible and executes automatically by default.';
  ELSIF NOT v_target_matched THEN
    v_approval_policy := 'human_required';
    v_reason := 'Consequential Dataset writes require human approval unless a matching credential-bound delegation policy applies.';
  ELSIF NOT v_create_only THEN
    v_approval_policy := 'human_required';
    v_reason := 'Automatic Dataset writes are limited to create and append rows. Updates and overwrites remain human-required.';
  ELSIF NOT v_limit_satisfied THEN
    v_approval_policy := 'human_required';
    v_reason := 'The matching delegation policy limit would be exceeded.';
  ELSE
    v_approval_policy := 'delegated';
    v_reason := 'The matching owner or steward delegation policy permits this bounded create or append.';
  END IF;

  RETURN jsonb_build_object(
    'riskClass', v_risk,
    'approvalPolicy', v_approval_policy,
    'policyId', v_policy_id,
    'policyReason', v_reason,
    'policyLimits', v_policy_limits,
    'policyTarget', coalesce(v_target, '{}'::jsonb),
    'policyEvidence', jsonb_build_object(
      'actorKind', v_actor_kind,
      'credentialId', api.current_credential_id(),
      'requiredScope', v_required_scope,
      'scopeSatisfied', v_scope_ok,
      'targetMatched', v_target_matched,
      'createOnly', v_create_only,
      'affectedRows', v_affected_rows,
      'maxAffectedRows', v_max_rows,
      'limitSatisfied', v_limit_satisfied,
      'riskClass', v_risk,
      'evaluatedAt', to_char(clock_timestamp() AT TIME ZONE 'UTC', 'YYYY-MM-DD"T"HH24:MI:SS.MS"Z"')
    )
  );
END;
$$;
--> statement-breakpoint
ALTER FUNCTION internal.agent_operation_policy_evaluate(p_workspace_id uuid, p_operation jsonb, p_contract jsonb) OWNER TO migrator;
--> statement-breakpoint
CREATE FUNCTION internal.agent_operation_policy_matches(p_policy api.agent_operation_policies, p_workspace_id uuid, p_operation jsonb, p_target jsonb) RETURNS boolean
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
  v_target_id uuid;
  v_project_id uuid;
BEGIN
  IF p_policy.workspace_id IS DISTINCT FROM p_workspace_id
     OR p_policy.operation_kind IS DISTINCT FROM p_operation->>'kind'
     OR NOT p_policy.enabled
     OR p_policy.credential_id IS DISTINCT FROM api.current_credential_id()
     OR NOT EXISTS (
       SELECT 1
       FROM internal.api_credentials credential
       WHERE credential.id = p_policy.credential_id
         AND credential.workspace_id = p_workspace_id
         AND credential.kind = 'service'
         AND credential.revoked_at IS NULL
         AND (credential.expires_at IS NULL OR credential.expires_at > now())
     ) THEN
    RETURN false;
  END IF;
  IF p_policy.target_type = 'workspace' THEN
    RETURN true;
  END IF;
  BEGIN
    v_target_id := nullif(p_target->>'id', '')::uuid;
  EXCEPTION WHEN invalid_text_representation THEN
    RETURN false;
  END;
  IF p_policy.target_type = p_target->>'type'
     AND p_policy.target_id = v_target_id THEN
    RETURN true;
  END IF;
  IF p_policy.target_type = 'project'
     AND p_operation->>'kind' = 'dataset_rows.commit'
     AND p_target->>'type' = 'dataset' THEN
    SELECT primary_project_id INTO v_project_id
      FROM api.datasets
     WHERE id = v_target_id AND workspace_id = p_workspace_id;
    RETURN p_policy.target_id = v_project_id;
  END IF;
  RETURN false;
END;
$$;
--> statement-breakpoint
ALTER FUNCTION internal.agent_operation_policy_matches(p_policy api.agent_operation_policies, p_workspace_id uuid, p_operation jsonb, p_target jsonb) OWNER TO migrator;
--> statement-breakpoint
CREATE FUNCTION internal.agent_workflow_append_event(p_workflow api.agent_workflows, p_event_type text, p_detail jsonb DEFAULT '{}'::jsonb) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
BEGIN
  INSERT INTO api.agent_workflow_events(
    workspace_id, workflow_id, sequence, event_type,
    actor_user_id, actor_credential_id, detail
  ) VALUES (
    p_workflow.workspace_id,
    p_workflow.id,
    coalesce((
      SELECT max(sequence) + 1
      FROM api.agent_workflow_events
      WHERE workflow_id = p_workflow.id
    ), 1),
    p_event_type,
    api.current_user_id(),
    api.current_credential_id(),
    coalesce(p_detail, '{}'::jsonb)
  );
END;
$$;
--> statement-breakpoint
ALTER FUNCTION internal.agent_workflow_append_event(p_workflow api.agent_workflows, p_event_type text, p_detail jsonb) OWNER TO migrator;
--> statement-breakpoint
CREATE FUNCTION internal.agent_workflow_propose_step(p_workflow_id uuid, p_position integer) RETURNS api.agent_workflows
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
  v_workflow api.agent_workflows;
  v_step api.agent_workflow_steps;
  v_proposal api.agent_operation_proposals;
  v_code text;
  v_message text;
  v_step_count integer;
BEGIN
  SELECT * INTO v_workflow
    FROM api.agent_workflows
   WHERE id = p_workflow_id
     AND workspace_id = api.current_workspace_id()
   FOR UPDATE;
  SELECT * INTO v_step
    FROM api.agent_workflow_steps
   WHERE workflow_id = p_workflow_id
     AND position = p_position
   FOR UPDATE;

  IF v_workflow.id IS NULL OR v_step.id IS NULL THEN
    RAISE EXCEPTION 'workflow step not found' USING ERRCODE = '42501';
  END IF;
  IF v_workflow.status IN ('succeeded','cancelled','budget_exhausted') THEN
    RAISE EXCEPTION 'workflow is terminal' USING ERRCODE = 'SB001';
  END IF;
  IF v_workflow.used_operations >= v_workflow.max_operations THEN
    UPDATE api.agent_workflow_steps
       SET status = 'cancelled', updated_at = now()
     WHERE id = v_step.id;
    UPDATE api.agent_workflows
       SET status = 'budget_exhausted', revision = revision + 1,
           updated_at = now()
     WHERE id = v_workflow.id
     RETURNING * INTO v_workflow;
    PERFORM internal.agent_workflow_append_event(
      v_workflow, 'budget_exhausted',
      jsonb_build_object('budget','operations','limit',v_workflow.max_operations)
    );
    RETURN v_workflow;
  END IF;

  BEGIN
    v_proposal := api.propose_agent_operation(
      v_workflow.workspace_id,
      v_step.title,
      v_step.summary,
      v_step.operation,
      v_workflow.provenance,
      'workflow:' || v_workflow.id::text || ':' || v_step.step_key || ':' || (v_step.attempt + 1)::text
    );
  EXCEPTION WHEN OTHERS THEN
    GET STACKED DIAGNOSTICS v_code = RETURNED_SQLSTATE, v_message = MESSAGE_TEXT;
    UPDATE api.agent_workflow_steps
       SET status = 'failed', updated_at = now()
     WHERE id = v_step.id;
    UPDATE api.agent_workflows
       SET status = 'paused', current_step = p_position,
           revision = revision + 1, updated_at = now()
     WHERE id = v_workflow.id
     RETURNING * INTO v_workflow;
    PERFORM internal.agent_workflow_append_event(
      v_workflow, 'paused',
      jsonb_build_object(
        'stepKey',v_step.step_key,'position',p_position,
        'errorCode',v_code,'message',left(v_message,2000)
      )
    );
    RETURN v_workflow;
  END;

  UPDATE api.agent_workflow_steps
     SET proposal_id = v_proposal.id,
         status = CASE
           WHEN v_proposal.status = 'succeeded' THEN 'succeeded'
           WHEN v_proposal.status IN ('failed','rejected','cancelled') THEN v_proposal.status
           ELSE 'waiting_approval'
         END,
         attempt = attempt + 1,
         completed_at = CASE
           WHEN v_proposal.status = 'succeeded' THEN now()
           ELSE NULL
         END,
         updated_at = now()
   WHERE id = v_step.id;
  UPDATE api.agent_workflows
     SET current_step = p_position,
         used_operations = used_operations + 1,
         revision = revision + 1,
         updated_at = now()
   WHERE id = v_workflow.id
   RETURNING * INTO v_workflow;
  PERFORM internal.agent_workflow_append_event(
    v_workflow, 'step_proposed',
    jsonb_build_object(
      'stepKey',v_step.step_key,'position',p_position,
      'attempt',v_step.attempt + 1,'proposalId',v_proposal.id,
      'tool',v_step.tool_name,
      'approvalPolicy',v_proposal.approval_policy,
      'proposalStatus',v_proposal.status
    )
  );

  IF v_proposal.status IN ('failed','rejected','cancelled') THEN
    UPDATE api.agent_workflows
       SET status = 'paused', revision = revision + 1, updated_at = now()
     WHERE id = v_workflow.id
     RETURNING * INTO v_workflow;
    PERFORM internal.agent_workflow_append_event(
      v_workflow, 'paused',
      jsonb_build_object(
        'stepKey',v_step.step_key,'position',p_position,
        'proposalId',v_proposal.id,
        'proposalStatus',v_proposal.status,
        'errorCode',v_proposal.error_code
      )
    );
    RETURN v_workflow;
  END IF;

  IF v_proposal.status <> 'succeeded' THEN
    UPDATE api.agent_workflows
       SET status = 'waiting_approval'
     WHERE id = v_workflow.id
     RETURNING * INTO v_workflow;
    RETURN v_workflow;
  END IF;

  PERFORM internal.agent_workflow_append_event(
    v_workflow, 'step_succeeded',
    jsonb_build_object(
      'stepKey',v_step.step_key,'proposalId',v_proposal.id,
      'canonicalResult',v_proposal.result,
      'approvalPolicy',v_proposal.approval_policy
    )
  );
  SELECT count(*)::integer INTO v_step_count
    FROM api.agent_workflow_steps
   WHERE workflow_id = v_workflow.id;
  IF p_position + 1 >= v_step_count THEN
    UPDATE api.agent_workflows
       SET status = 'succeeded', completed_at = now(),
           revision = revision + 1, updated_at = now()
     WHERE id = v_workflow.id
     RETURNING * INTO v_workflow;
    PERFORM internal.agent_workflow_append_event(
      v_workflow,'succeeded',
      jsonb_build_object('planDigest',v_workflow.plan_digest)
    );
    RETURN v_workflow;
  END IF;
  RETURN internal.agent_workflow_propose_step(v_workflow.id, p_position + 1);
END;
$$;
--> statement-breakpoint
ALTER FUNCTION internal.agent_workflow_propose_step(p_workflow_id uuid, p_position integer) OWNER TO migrator;
--> statement-breakpoint
CREATE FUNCTION internal.analysis_view_citations(p_workspace_id uuid, p_display_id text) RETURNS TABLE(link_id uuid, source_record_id uuid, record_identifier text, record_title text, record_status text, linked_at timestamp with time zone, locked boolean, locked_at timestamp with time zone, signed boolean, signed_at timestamp with time zone, signer_user_id text)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  SELECT
    l.id,
    r.id,
    r.identifier,
    r.title,
    r.status,
    l.created_at,
    r.locked_at IS NOT NULL,
    r.locked_at,
    sig.id IS NOT NULL,
    sig.signed_at,
    sig.signer_user_id
  FROM api.record_links l
  JOIN api.records r ON r.id = l.source_record_id
  LEFT JOIN LATERAL (
    SELECT s.id, s.signed_at, s.signer_user_id
      FROM api.signatures s
     WHERE s.record_id = r.id
       AND (r.locked_by_revision_id IS NULL OR s.revision_id = r.locked_by_revision_id)
     ORDER BY s.signed_at DESC
     LIMIT 1
  ) sig ON true
  WHERE l.link_type = 'analysis'
    AND l.target_kind = 'analysis'
    AND l.target_identifier = p_display_id
    AND r.workspace_id = p_workspace_id
    AND r.deleted_at IS NULL
  ORDER BY l.created_at, l.id
$$;
