    workspace_id uuid NOT NULL,
    owner_user_id text NOT NULL,
    name text NOT NULL,
    version integer DEFAULT 1 NOT NULL,
    spec jsonb NOT NULL,
    source_revisions jsonb DEFAULT '[]'::jsonb NOT NULL,
    export_settings jsonb,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    display_id text,
    CONSTRAINT chk_analysis_views_name CHECK ((name ~ '^[[:alpha:][:digit:]][[:alpha:][:digit:] _.-]{0,98}[[:alpha:][:digit:]]$'::text)),
    CONSTRAINT chk_analysis_views_version CHECK ((version > 0))
);
