CREATE FUNCTION internal.analysis_view_source_rows(p_view api.analysis_views) RETURNS TABLE(pin_position integer, dataset_id uuid, dataset_name text, dataset_display_id text, pinned_schema_version_number integer, pinned_revision bigint, live_schema_version_number integer, live_revision bigint, status text)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $_$
  SELECT
    (pinned.ordinality)::integer,
    internal.try_uuid(pinned.value->>'datasetId'),
    d.name,
    d.display_id,
    CASE WHEN pinned.value->>'schemaVersionNumber' ~ '^[0-9]+$'
      THEN (pinned.value->>'schemaVersionNumber')::integer ELSE 0 END,
    CASE WHEN pinned.value->>'revision' ~ '^[0-9]+$'
      THEN (pinned.value->>'revision')::bigint ELSE 0 END,
    sv.version,
    d.revision,
    CASE
      WHEN d.id IS NULL THEN 'removed'
      WHEN sv.version IS DISTINCT FROM
             CASE WHEN pinned.value->>'schemaVersionNumber' ~ '^[0-9]+$'
               THEN (pinned.value->>'schemaVersionNumber')::integer ELSE 0 END
        OR d.revision IS DISTINCT FROM
             CASE WHEN pinned.value->>'revision' ~ '^[0-9]+$'
               THEN (pinned.value->>'revision')::bigint ELSE 0 END
      THEN 'stale'
      ELSE 'current'
    END
  FROM jsonb_array_elements(p_view.source_revisions) WITH ORDINALITY AS pinned(value, ordinality)
  LEFT JOIN api.datasets d
    ON d.id = internal.try_uuid(pinned.value->>'datasetId')
   AND d.workspace_id = p_view.workspace_id
  LEFT JOIN api.dataset_schema_versions sv ON sv.id = d.schema_version_id
$_$;
--> statement-breakpoint
ALTER FUNCTION internal.analysis_view_source_rows(p_view api.analysis_views) OWNER TO migrator;
--> statement-breakpoint
CREATE FUNCTION internal.apply_project_qa_view_default() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
  v_group uuid;
  v_actor text;
BEGIN
  -- The rule records who granted it: the person creating the project, or its
  -- lead when no one is signed in (an import). Without either, nothing is
  -- granted rather than inventing an author.
  v_actor := coalesce(api.current_user_id(), NEW.lead_user_id);
  SELECT g.id INTO v_group
    FROM api.workspace_settings s
    JOIN api.workspace_groups g
      ON g.workspace_id = s.workspace_id
     AND g.id::text = s.integration_settings->'projectAccessDefaults'->>'qaViewGroupId'
   WHERE s.workspace_id = NEW.workspace_id
     AND NOT EXISTS (
       SELECT 1
         FROM api.workspace_group_memberships gm
         JOIN api.workspace_memberships m
           ON m.workspace_id = gm.workspace_id AND m.user_id = gm.user_id
        WHERE gm.group_id = g.id AND m.role = 'client_viewer'
     );
  IF v_group IS NOT NULL AND v_actor IS NOT NULL THEN
    INSERT INTO api.project_access(
      workspace_id, project_id, group_id,
      can_view, can_edit, can_review, client_portal, can_manage,
      granted_by_user_id
    ) VALUES (
      NEW.workspace_id, NEW.id, v_group,
      true, false, false, false, false,
      v_actor
    )
    ON CONFLICT (workspace_id, project_id, group_id) DO NOTHING;
  END IF;
  RETURN NEW;
END $$;
--> statement-breakpoint
ALTER FUNCTION internal.apply_project_qa_view_default() OWNER TO migrator;
--> statement-breakpoint
CREATE FUNCTION internal.apply_review_decision(p_submission_id uuid, p_decision text, p_next_state text, p_note text, p_expected_state text, p_expected_revision_digest text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
  v_lock jsonb;
  v_submission api.review_submissions;
  v_revision api.revisions;
  v_workspace uuid;
  v_actor text;
  v_session text;
  v_role text;
  v_record_project uuid;
  v_decision_id uuid;
  v_decided_at timestamptz := clock_timestamp();
BEGIN
  v_lock := internal.lock_review_for_decision(
    p_submission_id, p_expected_state, p_expected_revision_digest, p_decision
  );
  v_workspace := (v_lock->>'workspace_id')::uuid;
  v_actor := v_lock->>'actor';
  v_session := v_lock->>'session';
  v_role := v_lock->>'role';
  SELECT * INTO v_submission FROM jsonb_populate_record(NULL::api.review_submissions, v_lock->'submission');
  SELECT * INTO v_revision FROM jsonb_populate_record(NULL::api.revisions, v_lock->'revision');
  v_record_project := nullif(v_lock->>'record_project', '')::uuid;

  v_decision_id := gen_random_uuid();
  INSERT INTO api.review_decisions (
    id, workspace_id, submission_id, revision_id, record_id,
    decision, note, revision_integrity_digest,
    actor_user_id, actor_session_id, actor_role, created_at
  ) VALUES (
    v_decision_id, v_workspace, v_submission.id, v_revision.id, v_submission.record_id,
    p_decision, p_note, v_revision.integrity_digest,
    v_actor, v_session, v_role, v_decided_at
  );

  UPDATE api.review_submissions
  SET state = p_next_state, updated_at = v_decided_at
  WHERE id = v_submission.id;

  PERFORM internal.emit_change_event(
    v_workspace, 'review_submission', v_submission.id, 'update',
    v_submission.record_id, v_record_project,
    jsonb_build_object(
      'submissionId', v_submission.id, 'revisionId', v_revision.id,
      'decision', p_decision, 'nextState', p_next_state,
      'decisionId', v_decision_id, 'actorUserId', v_actor
    )
  );

  RETURN jsonb_build_object(
    'submissionId', v_submission.id,
    'revisionId', v_revision.id,
    'decision', p_decision,
    'state', p_next_state,
    'decisionId', v_decision_id,
    'createdAt', v_decided_at
  );
END;
$$;
