CREATE FUNCTION internal.assert_scientific_record_writable(p_table_id uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
  writable boolean;
  v_locked timestamptz;
  v_record_id uuid;
BEGIN
 IF session_user<>'migrator' AND NOT EXISTS(SELECT 1 FROM internal.formula_row_capability capability JOIN api.scientific_tables scientific ON scientific.id=capability.table_id JOIN api.records record ON record.id=scientific.record_id CROSS JOIN LATERAL internal.project_permissions_for(record.project_id,capability.actor_user_id) permissions WHERE capability.tx=txid_current() AND capability.table_id=p_table_id AND permissions.can_edit) THEN PERFORM internal.assert_object_access('table',p_table_id,'edit'); END IF;
  SELECT true, r.locked_at, r.id INTO writable, v_locked, v_record_id
  FROM api.scientific_tables t JOIN api.records r ON r.id = t.record_id
  WHERE t.id = p_table_id AND r.archived_at IS NULL AND r.deleted_at IS NULL
  FOR UPDATE OF r;
  IF writable IS NOT TRUE THEN
    RAISE EXCEPTION 'owning record is not writable' USING ERRCODE = '42501';
  END IF;
  IF v_locked IS NOT NULL AND session_user <> 'migrator' THEN
    RAISE EXCEPTION 'record is locked' USING ERRCODE = 'SB011';
  END IF;
END;
$$;
