    due_at timestamp with time zone,
    CONSTRAINT chk_review_submissions_idempotency_key CHECK (((length(idempotency_key) >= 1) AND (length(idempotency_key) <= 128))),
    CONSTRAINT chk_review_submissions_reviewers CHECK ((cardinality(assigned_reviewer_user_ids) > 0)),
    CONSTRAINT chk_review_submissions_state CHECK ((state = ANY (ARRAY['submitted'::text, 'returned'::text, 'rejected'::text, 'approved'::text, 'withdrawn'::text]))),
    CONSTRAINT chk_review_submissions_workflow_key CHECK ((workflow_definition_key ~ '^[a-z0-9][a-z0-9_-]{0,127}$'::text)),
    CONSTRAINT chk_review_submissions_workflow_version CHECK ((workflow_definition_version > 0))
);
