CREATE FUNCTION internal.audit_entry_hash(p_previous_hash text, p_workspace_id uuid, p_sequence bigint, p_entity_type text, p_entity_uuid uuid, p_operation text, p_record_id uuid, p_project_id uuid, p_client_id text, p_payload jsonb, p_created_at timestamp with time zone) RETURNS text
    LANGUAGE sql IMMUTABLE
    SET search_path TO ''
    AS $$
  SELECT encode(sha256(convert_to(
    coalesce(p_previous_hash, 'genesis') || '|' ||
    p_workspace_id::text || '|' || p_sequence::text || '|' ||
    p_entity_type || '|' || p_entity_uuid::text || '|' || p_operation || '|' ||
    coalesce(p_record_id::text, '') || '|' || coalesce(p_project_id::text, '') || '|' ||
    coalesce(p_client_id, '') || '|' || coalesce(p_payload, '{}'::jsonb)::text || '|' ||
    to_char(p_created_at AT TIME ZONE 'UTC', 'YYYY-MM-DD"T"HH24:MI:SS.US"Z"'),
    'UTF8')), 'hex')
$$;
--> statement-breakpoint
