CREATE FUNCTION internal.can_read_change_event(p_event api.change_events) RETURNS boolean
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE kind text;
BEGIN
  IF p_event.workspace_id IS DISTINCT FROM api.current_workspace_id() OR NOT api.is_workspace_member(p_event.workspace_id) THEN RETURN false; END IF;
  IF p_event.project_id IS NOT NULL AND NOT internal.can_view_project(p_event.project_id) THEN RETURN false; END IF;
  IF p_event.record_id IS NOT NULL AND NOT internal.can_access_object('record',p_event.record_id,'view') THEN RETURN false; END IF;
  kind:=CASE p_event.entity_type WHEN 'project' THEN 'project' WHEN 'record' THEN 'record' WHEN 'dataset' THEN 'dataset' WHEN 'analysis_view' THEN 'analysis_view' WHEN 'dataset_version' THEN 'dataset_version' WHEN 'sheet_instance' THEN 'instance' WHEN 'file' THEN 'file' WHEN 'report_definition' THEN 'report' WHEN 'report_section' THEN 'section' WHEN 'instrument_run' THEN 'run' WHEN 'calendar_booking' THEN 'booking' WHEN 'study_task' THEN 'task' WHEN 'comment' THEN 'comment' WHEN 'block' THEN 'block' WHEN 'scientific_table' THEN 'table' WHEN 'dataset_import_file' THEN 'import_file' END;
  -- Deleted objects retain their immutable project/record ownership hints.
  IF kind IS NOT NULL AND p_event.operation<>'delete' AND NOT internal.can_access_object(kind,p_event.entity_uuid,'view') THEN RETURN false; END IF;
  
    IF p_event.entity_type='record_link' AND NOT internal.can_read_record_link_target(
      p_event.record_id,p_event.payload->>'targetKind',p_event.payload->>'targetIdentifier',NULL) THEN RETURN false; END IF;
    RETURN internal.sources_readable(p_event.payload);
END $$;
--> statement-breakpoint
ALTER FUNCTION internal.can_read_change_event(p_event api.change_events) OWNER TO migrator;
--> statement-breakpoint
CREATE FUNCTION internal.can_read_record_link_target(p_source_record_id uuid, p_target_kind text, p_target_identifier text, p_target_record_id uuid) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  SELECT CASE WHEN p_target_kind='dataset' THEN
    p_target_record_id IS NULL AND EXISTS(
      SELECT 1 FROM api.datasets d JOIN api.records s ON s.workspace_id=d.workspace_id
      WHERE s.id=p_source_record_id AND d.display_id=p_target_identifier
        AND internal.can_access_object('dataset',d.id,'view'))
  WHEN p_target_kind='analysis' THEN
    p_target_record_id IS NULL AND EXISTS(
      SELECT 1 FROM api.analysis_views a JOIN api.records s ON s.workspace_id=a.workspace_id
      WHERE s.id=p_source_record_id AND a.display_id=p_target_identifier
        AND a.workspace_id=api.current_workspace_id()
        AND (api.claim_probe()->>'role'='api_client' OR
          (api.claim_probe()->>'role'='authenticated' AND api.is_workspace_member(a.workspace_id)))
        AND internal.sources_readable(a.spec) AND internal.sources_readable(a.source_revisions))
  ELSE EXISTS(
    SELECT 1 FROM api.records t JOIN api.records s ON s.workspace_id=t.workspace_id
    WHERE s.id=p_source_record_id AND t.kind=p_target_kind AND t.identifier=p_target_identifier
      AND (p_target_record_id IS NULL OR t.id=p_target_record_id)
      AND internal.can_access_object('record',t.id,'view')) END
$$;
--> statement-breakpoint
