CREATE FUNCTION internal.canonical_model_field_value(p_field api.record_field_definitions) RETURNS api.record_field_definitions
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
DECLARE target_key text;
BEGIN
  IF p_field.cardinality <> 'one' THEN
    RAISE EXCEPTION 'many-valued Model fields are not supported yet' USING ERRCODE='SB071';
  END IF;
  IF p_field.quantity IS NOT NULL AND p_field.logical_type NOT IN ('integer', 'decimal') THEN
    RAISE EXCEPTION 'quantity semantics require an integer or decimal field' USING ERRCODE='SB071';
  END IF;
  IF p_field.quantity IS NOT NULL AND (
    coalesce(nullif(btrim(p_field.quantity->>'kind'), ''), '') = '' OR
    coalesce(nullif(btrim(p_field.quantity->>'dimension'), ''), '') = '' OR
    coalesce(nullif(btrim(p_field.quantity->>'storageUnit'), ''), '') = ''
  ) THEN
    RAISE EXCEPTION 'quantity requires kind, dimension and storageUnit' USING ERRCODE='SB071';
  END IF;
  IF p_field.logical_type = 'category' THEN
    p_field.category_source := coalesce(p_field.category_source, jsonb_build_object('kind', 'embedded'));
    IF p_field.category_source->>'kind' NOT IN ('embedded', 'vocabulary') OR
       (p_field.category_source->>'kind' = 'vocabulary' AND coalesce(nullif(btrim(p_field.category_source->>'vocabularyId'), ''), '') = '') THEN
      RAISE EXCEPTION 'invalid category source' USING ERRCODE='SB071';
    END IF;
  ELSIF p_field.category_source IS NOT NULL THEN
    RAISE EXCEPTION 'category source is only valid for category fields' USING ERRCODE='SB071';
  END IF;
  IF p_field.logical_type = 'reference' THEN
    target_key := p_field.validation->>'targetModelKey';
    IF p_field.relationship IS NULL AND target_key IS NOT NULL THEN
      p_field.relationship := jsonb_build_object('target', jsonb_build_object('kind', 'model', 'modelKey', target_key), 'cardinality', p_field.cardinality);
    END IF;
    IF p_field.relationship IS NOT NULL THEN
      IF p_field.relationship->'target'->>'kind' <> 'model' OR
         coalesce(nullif(btrim(p_field.relationship->'target'->>'modelKey'), ''), '') = '' OR
         p_field.relationship->>'cardinality' <> p_field.cardinality THEN
        RAISE EXCEPTION 'invalid Model reference relationship' USING ERRCODE='SB071';
      END IF;
      target_key := p_field.relationship->'target'->>'modelKey';
      IF p_field.validation ? 'targetModelKey' AND p_field.validation->>'targetModelKey' <> target_key THEN
        RAISE EXCEPTION 'reference relationship conflicts with targetModelKey' USING ERRCODE='SB071';
      END IF;
      p_field.validation := p_field.validation || jsonb_build_object('targetModelKey', target_key);
    END IF;
  ELSIF p_field.relationship IS NOT NULL THEN
    RAISE EXCEPTION 'relationship is only valid for reference fields' USING ERRCODE='SB071';
  END IF;
  RETURN p_field;
END $$;
--> statement-breakpoint
ALTER FUNCTION internal.canonical_model_field_value(p_field api.record_field_definitions) OWNER TO migrator;
