CREATE TABLE internal.signature_grants (
    token_hash text NOT NULL,
    user_id text NOT NULL,
    session_id text NOT NULL,
    workspace_id uuid NOT NULL,
    purpose text NOT NULL,
    submission_id uuid,
    revision_digest text,
    authorization_id uuid,
    auth_method text NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    expires_at timestamp with time zone NOT NULL,
    consumed_at timestamp with time zone,
    record_id uuid,
    signature_meaning text,
    submission_arguments jsonb,
    CONSTRAINT chk_signature_grants_auth_method CHECK ((auth_method = 'password'::text)),
    CONSTRAINT chk_signature_grants_binding CHECK ((((purpose = 'sign'::text) AND (submission_id IS NOT NULL) AND (revision_digest ~ '^[0-9a-f]{64}$'::text) AND (record_id IS NULL) AND (submission_arguments IS NULL)) OR ((purpose = 'author-submit'::text) AND (submission_id IS NULL) AND (revision_digest ~ '^[0-9a-f]{64}$'::text) AND (record_id IS NOT NULL) AND (signature_meaning = 'authored'::text) AND (jsonb_typeof(submission_arguments) = 'object'::text)) OR ((purpose <> ALL (ARRAY['sign'::text, 'author-submit'::text])) AND (submission_id IS NULL) AND (revision_digest IS NULL) AND (record_id IS NULL) AND (signature_meaning IS NULL) AND (submission_arguments IS NULL)))),
    CONSTRAINT chk_signature_grants_purpose CHECK ((purpose = ANY (ARRAY['sign'::text, 'author-submit'::text, 'certify'::text, 'practice'::text, 'enroll'::text, 'recover'::text])))
);
