CREATE TABLE api.dataset_schema_version_fields (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    schema_version_id uuid NOT NULL,
    field_id uuid NOT NULL,
    key text NOT NULL,
    label text NOT NULL,
    description text,
    logical_type text NOT NULL,
    nullable boolean DEFAULT true NOT NULL,
    default_value jsonb,
    quantity jsonb,
    validation jsonb DEFAULT '{}'::jsonb NOT NULL,
    category jsonb,
    relationship jsonb,
    cardinality text DEFAULT 'one'::text NOT NULL,
    lifecycle text DEFAULT 'active'::text NOT NULL,
    display_order integer NOT NULL,
    CONSTRAINT chk_dataset_schema_version_fields_cardinality CHECK ((cardinality = ANY (ARRAY['one'::text, 'many'::text]))),
    CONSTRAINT chk_dataset_schema_version_fields_lifecycle CHECK ((lifecycle = ANY (ARRAY['active'::text, 'retired'::text]))),
    CONSTRAINT chk_dataset_schema_version_fields_type CHECK ((logical_type = ANY (ARRAY['text'::text, 'integer'::text, 'decimal'::text, 'boolean'::text, 'date'::text, 'timestamp'::text, 'category'::text, 'reference'::text])))
);
