CREATE FUNCTION internal.dataset_row_field_numeric(p_row_id uuid, p_field_id uuid) RETURNS numeric
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
  v numeric;
BEGIN
  SELECT coalesce(v.numeric_value, v.integer_value::numeric)
    INTO v
    FROM api.dataset_row_values v
   WHERE v.row_id = p_row_id AND v.field_id = p_field_id
   ORDER BY v.ordinal
   LIMIT 1;
  RETURN v;
END $$;
--> statement-breakpoint
