CREATE FUNCTION internal.dataset_version_content_hash(p_version_id uuid) RETURNS text
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  WITH entries AS (
    SELECT 'row|' || r.row_id::text || '|' || r.revision::text AS entry
      FROM api.dataset_version_rows r
     WHERE r.dataset_version_id = p_version_id
    UNION ALL
    SELECT 'value|' || v.row_id::text || '|' || v.field_id::text || '|' ||
           v.ordinal::text || '|' ||
           (to_jsonb(v) - 'dataset_version_id' - 'row_id' - 'field_id' - 'ordinal')::text
      FROM api.dataset_version_values v
     WHERE v.dataset_version_id = p_version_id
    UNION ALL
    SELECT 'flag|' || f.row_id::text || '|' || f.field_id::text || '|' ||
           f.kind || '|' || f.source || '|' || coalesce(f.reason, '') || '|' ||
           coalesce(f.comment, '') || '|' || coalesce(f.set_by_user_id, '') || '|' ||
           coalesce(f.set_at::text, '')
      FROM api.dataset_version_flags f
     WHERE f.dataset_version_id = p_version_id
  )
  SELECT 'sha256:' || encode(
    sha256(convert_to(coalesce(string_agg(entry, E'\n' ORDER BY entry), ''), 'UTF8')),
    'hex'
  )
  FROM entries;
$$;
--> statement-breakpoint
ALTER FUNCTION internal.dataset_version_content_hash(p_version_id uuid) OWNER TO migrator;
--> statement-breakpoint
CREATE FUNCTION internal.dataset_version_flag_delta(p_from jsonb, p_to jsonb) RETURNS jsonb
    LANGUAGE sql IMMUTABLE
    SET search_path TO ''
    AS $$
  SELECT coalesce(
      jsonb_agg(entry ORDER BY entry->>'fieldId', entry->>'kind', entry->>'source'),
      '[]'::jsonb
    )
  FROM (
    SELECT jsonb_build_object(
        'fieldId', t.value->>'fieldId',
        'kind', t.value->>'kind',
        'source', t.value->>'source',
        'change', 'added',
        'to', t.value
      ) AS entry
    FROM jsonb_each(coalesce(p_to, '{}'::jsonb)) t
    WHERE NOT coalesce(p_from, '{}'::jsonb) ? t.key
    UNION ALL
    SELECT jsonb_build_object(
        'fieldId', f.value->>'fieldId',
        'kind', f.value->>'kind',
        'source', f.value->>'source',
        'change', 'removed',
        'from', f.value
      )
    FROM jsonb_each(coalesce(p_from, '{}'::jsonb)) f
    WHERE NOT coalesce(p_to, '{}'::jsonb) ? f.key
    UNION ALL
    SELECT jsonb_build_object(
        'fieldId', t.value->>'fieldId',
        'kind', t.value->>'kind',
        'source', t.value->>'source',
        'change', 'changed',
        'from', f.value,
        'to', t.value
      )
    FROM jsonb_each(coalesce(p_from, '{}'::jsonb)) f
    JOIN jsonb_each(coalesce(p_to, '{}'::jsonb)) t ON t.key = f.key
    WHERE f.value IS DISTINCT FROM t.value
  ) d
$$;
--> statement-breakpoint
