CREATE FUNCTION internal.emit_change_event(p_workspace_id uuid, p_entity_type text, p_entity_uuid uuid, p_operation text, p_record_id uuid DEFAULT NULL::uuid, p_project_id uuid DEFAULT NULL::uuid, p_payload jsonb DEFAULT '{}'::jsonb) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE c jsonb; uid text; cid uuid; seq bigint; eid uuid:=gen_random_uuid();
BEGIN c:=api.claim_probe(); IF c IS NULL THEN RETURN; END IF; uid:=c->>'sub'; cid:=NULLIF(c->>'credential_id','')::uuid; IF uid IS NULL AND cid IS NULL THEN RETURN; END IF; 
    p_payload:=coalesce(p_payload,'{}'::jsonb)-'sessionId';
    IF c->>'role'='authenticated' AND cid IS NULL THEN
      p_payload:=p_payload||coalesce((SELECT jsonb_build_object('sessionId',s.id)
        FROM internal.session s WHERE s.id=c->>'session_id'
          AND s."userId"=uid AND s."expiresAt">now()),'{}'::jsonb);
    END IF;
    INSERT INTO api.workspace_change_seq
  (workspace_id,last_seq) VALUES(p_workspace_id,1) ON CONFLICT(workspace_id) DO UPDATE SET last_seq=api.workspace_change_seq.last_seq+1,updated_at=now() RETURNING last_seq INTO seq; INSERT INTO api.change_events(id,workspace_id,sequence,entity_type,entity_uuid,operation,record_id,project_id,actor_user_id,actor_credential_id,client_id,payload) VALUES(eid,p_workspace_id,seq,p_entity_type,p_entity_uuid,p_operation,p_record_id,p_project_id,uid,cid,c->>'client_id',coalesce(p_payload,'{}')); PERFORM pg_notify('sheetbase_change',jsonb_build_object('workspace_id',p_workspace_id,'sequence',seq,'id',eid,'entity_type',p_entity_type,'operation',p_operation)::text); END $$;
--> statement-breakpoint
ALTER FUNCTION internal.emit_change_event(p_workspace_id uuid, p_entity_type text, p_entity_uuid uuid, p_operation text, p_record_id uuid, p_project_id uuid, p_payload jsonb) OWNER TO migrator;
--> statement-breakpoint
CREATE FUNCTION internal.emit_change_event_as_actor(p_actor_user_id text, p_workspace_id uuid, p_entity_type text, p_entity_uuid uuid, p_operation text, p_record_id uuid, p_project_id uuid, p_payload jsonb) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE seq bigint; eid uuid:=gen_random_uuid();
BEGIN
 IF NOT EXISTS (SELECT 1 FROM internal."user" WHERE id=p_actor_user_id) THEN RAISE EXCEPTION 'validated actor required' USING ERRCODE='42501'; END IF;
 INSERT INTO api.workspace_change_seq(workspace_id,last_seq) VALUES(p_workspace_id,1) ON CONFLICT(workspace_id) DO UPDATE SET last_seq=api.workspace_change_seq.last_seq+1,updated_at=now() RETURNING last_seq INTO seq;
 INSERT INTO api.change_events(id,workspace_id,sequence,entity_type,entity_uuid,operation,record_id,project_id,actor_user_id,payload) VALUES(eid,p_workspace_id,seq,p_entity_type,p_entity_uuid,p_operation,p_record_id,p_project_id,p_actor_user_id,coalesce(p_payload,'{}'));
 PERFORM pg_notify('sheetbase_change',jsonb_build_object('workspace_id',p_workspace_id,'sequence',seq,'id',eid,'entity_type',p_entity_type,'operation',p_operation)::text);
END $$;
