CREATE FUNCTION internal.emit_dataset_analysis_staleness(p_dataset api.datasets, p_previous_revision bigint, p_sources jsonb) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE analysis record; owner record; ids jsonb;
BEGIN
  FOR analysis IN
    SELECT id,name,source_revisions FROM api.analysis_definitions WHERE workspace_id=p_dataset.workspace_id
    UNION ALL SELECT id,name,source_revisions FROM api.analysis_views WHERE workspace_id=p_dataset.workspace_id
  LOOP
    IF NOT EXISTS(SELECT 1 FROM jsonb_array_elements(analysis.source_revisions) source
      WHERE source->>'datasetId'=p_dataset.id::text AND source->'revision'=to_jsonb(p_previous_revision))
      OR EXISTS(SELECT 1 FROM jsonb_array_elements(analysis.source_revisions) source WHERE NOT EXISTS(
        SELECT 1 FROM api.datasets d JOIN api.dataset_schema_versions version ON version.id=d.schema_version_id
        WHERE d.id::text=source->>'datasetId' AND d.workspace_id=p_dataset.workspace_id
          AND source->'schemaVersionNumber'=to_jsonb(version.version)
          AND source->'revision'=to_jsonb(CASE WHEN d.id=p_dataset.id THEN p_previous_revision ELSE d.revision END)))
    THEN CONTINUE; END IF;
    FOR owner IN SELECT DISTINCT value->>'recordId' AS record_id FROM jsonb_array_elements(p_sources) LOOP
      SELECT jsonb_agg(value->'sourceEventId') INTO ids FROM jsonb_array_elements(p_sources)
        WHERE value->>'recordId' IS NOT DISTINCT FROM owner.record_id;
      PERFORM internal.emit_change_event(p_dataset.workspace_id,'dataset',p_dataset.id,'update',
        owner.record_id::uuid,p_dataset.primary_project_id,jsonb_build_object(
          'datasetId',p_dataset.id,'analysisId',analysis.id,'name',analysis.name,
          'sourceRevisions',analysis.source_revisions,
          'effect','stale_analysis','sourceEventIds',ids,
          'sourceEventId',CASE WHEN jsonb_array_length(ids)=1 THEN ids->0 ELSE 'null'::jsonb END,
          'changes',jsonb_build_object('status',jsonb_build_object('from','current','to','stale'))));
    END LOOP;
  END LOOP;
END $$;
--> statement-breakpoint
ALTER FUNCTION internal.emit_dataset_analysis_staleness(p_dataset api.datasets, p_previous_revision bigint, p_sources jsonb) OWNER TO migrator;
--> statement-breakpoint
CREATE FUNCTION internal.emit_dataset_row_audit(p_dataset api.datasets, p_row_id uuid, p_changes jsonb, p_reason text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE owner record; marker uuid:=gen_random_uuid(); event_id uuid; result jsonb:='[]'; payload jsonb;
BEGIN
  payload:=jsonb_build_object('datasetId',p_dataset.id,'name',p_dataset.name,
    'rowId',p_row_id,'rowRevision',(SELECT revision FROM api.dataset_rows WHERE id=p_row_id),
    'datasetRevision',p_dataset.revision+1,'auditMutationId',marker,
    'changes',p_changes,'reason',p_reason);
  FOR owner IN
    SELECT DISTINCT r.id AS record_id,r.project_id FROM api.records r
    WHERE r.workspace_id=p_dataset.workspace_id AND (
      EXISTS(SELECT 1 FROM api.sheet_instances i,jsonb_array_elements(i.state->'bindings') binding
        WHERE i.notebook_record_id=r.id AND i.lifecycle='active'
          AND binding->>'datasetId'=p_dataset.id::text AND binding->'policy'->>'mode'='live')
      OR EXISTS(SELECT 1 FROM api.record_links link WHERE link.source_record_id=r.id
        AND link.target_kind='dataset' AND link.target_identifier=p_dataset.display_id))
    UNION ALL SELECT NULL::uuid,p_dataset.primary_project_id
  LOOP
    PERFORM internal.emit_change_event(p_dataset.workspace_id,'dataset',p_dataset.id,'update',
      owner.record_id,owner.project_id,payload);
    SELECT e.id INTO event_id FROM api.change_events e WHERE e.workspace_id=p_dataset.workspace_id
      AND e.payload->>'auditMutationId'=marker::text AND e.record_id IS NOT DISTINCT FROM owner.record_id;
    IF event_id IS NOT NULL AND (owner.record_id IS NULL OR internal.can_access_object('record',owner.record_id,'view')) THEN result:=result||jsonb_build_array(jsonb_build_object(
      'recordId',owner.record_id,'sourceEventId',event_id)); END IF;
  END LOOP;
  RETURN result;
END $$;
--> statement-breakpoint
ALTER FUNCTION internal.emit_dataset_row_audit(p_dataset api.datasets, p_row_id uuid, p_changes jsonb, p_reason text) OWNER TO migrator;
--> statement-breakpoint
CREATE FUNCTION internal.emit_reagent_expiry_events(p_window_days integer DEFAULT 7) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $_$
DECLARE
  r record;
  v_emitted integer := 0;
  v_sequence bigint;
BEGIN
  FOR r IN
    SELECT rec.id, rec.workspace_id, rec.project_id, rec.identifier, rec.title,
           rec.properties->>'expiry' AS expiry
      FROM api.records rec
     WHERE rec.kind = 'material'
       AND rec.deleted_at IS NULL
       AND rec.archived_at IS NULL
       AND rec.status = 'available'
       AND rec.properties->>'expiry' ~ '^\d{4}-\d{2}-\d{2}$'
       AND (rec.properties->>'expiry')::date
             BETWEEN current_date AND current_date + (p_window_days || ' days')::interval
       AND NOT EXISTS (
             SELECT 1 FROM api.change_events e
              WHERE e.entity_type = 'material' AND e.entity_uuid = rec.id
                AND e.payload->>'action' = 'expiring')
     ORDER BY (rec.properties->>'expiry')::date, rec.id
  LOOP
    -- A scheduled sweep has no user claims, and internal.emit_change_event is a
    -- no-op without a claim probe, so the system event is written directly with no
    -- actor (the same shape the nightly audit job uses). The chain trigger fills the
    -- hashes.
    INSERT INTO api.workspace_change_seq(workspace_id, last_seq) VALUES(r.workspace_id, 1)
      ON CONFLICT (workspace_id) DO UPDATE
        SET last_seq = api.workspace_change_seq.last_seq + 1, updated_at = now()
      RETURNING last_seq INTO v_sequence;
    INSERT INTO api.change_events
      (id, workspace_id, sequence, entity_type, entity_uuid, operation, project_id, payload)
    VALUES (gen_random_uuid(), r.workspace_id, v_sequence, 'material', r.id, 'update',
            r.project_id,
            jsonb_build_object('action', 'expiring', 'identifier', r.identifier,
                               'title', r.title, 'expiry', r.expiry));
    v_emitted := v_emitted + 1;
  END LOOP;
  RETURN v_emitted;
END $_$;
--> statement-breakpoint
ALTER FUNCTION internal.emit_reagent_expiry_events(p_window_days integer) OWNER TO migrator;
--> statement-breakpoint
CREATE FUNCTION internal.enforce_change_reason() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
  v_workspace uuid;
  v_requires boolean;
  v_reason text := internal.change_reason_from_request();
BEGIN
  -- Resolved per table: plpgsql binds NEW fields per row type, so the branches
  -- must not share one expression.
  IF TG_TABLE_NAME = 'blocks' THEN
    SELECT r.workspace_id INTO v_workspace FROM api.records r WHERE r.id = NEW.record_id;
  ELSE
    v_workspace := NEW.workspace_id;
  END IF;
  IF v_workspace IS NULL THEN RETURN NEW; END IF;
  SELECT s.require_change_reason INTO v_requires FROM api.workspace_settings s WHERE s.workspace_id = v_workspace;
  IF NOT coalesce(v_requires, false) THEN RETURN NEW; END IF;
  IF v_reason IS NULL THEN
    RAISE EXCEPTION 'a reason is required to change a saved value' USING ERRCODE = 'SB114';
  END IF;
  IF length(v_reason) > 2000 THEN
    RAISE EXCEPTION 'the change reason is too long' USING ERRCODE = '22023';
  END IF;
  RETURN NEW;
END $$;
--> statement-breakpoint
ALTER FUNCTION internal.enforce_change_reason() OWNER TO migrator;
--> statement-breakpoint
CREATE FUNCTION internal.enforce_credential_expiry() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
BEGIN
  -- Only the 90-day window is a database rule: "not in the past" is the app's
  -- create-time validation, and a stored row must be able to age into expiry.
  IF NEW.expires_at IS NOT NULL THEN
    IF NEW.expires_at > coalesce(NEW.created_at, now()) + interval '90 days' THEN
      RAISE EXCEPTION 'a token may not live longer than 90 days' USING ERRCODE = 'SB117';
    END IF;
  END IF;
  RETURN NEW;
END $$;
--> statement-breakpoint
ALTER FUNCTION internal.enforce_credential_expiry() OWNER TO migrator;
--> statement-breakpoint
CREATE FUNCTION internal.enforce_storage_capacity() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $_$
DECLARE
  v_new jsonb := to_jsonb(NEW);
  v_parent_id uuid;
  v_parent_capacity integer;
  v_child_count integer;
  v_parent_table text;
  v_parent_col text;
  v_child_col text;
BEGIN
  CASE TG_TABLE_NAME
    WHEN 'storage_rooms' THEN
      v_parent_table := 'api.storage_sites'; v_parent_col := 'site_id';
      v_child_col := 'site_id';
    WHEN 'storage_units' THEN
      v_parent_table := 'api.storage_rooms'; v_parent_col := 'room_id';
      v_child_col := 'room_id';
    WHEN 'storage_shelves' THEN
      v_parent_table := 'api.storage_units'; v_parent_col := 'unit_id';
      v_child_col := 'unit_id';
    WHEN 'storage_racks' THEN
      v_parent_table := 'api.storage_shelves'; v_parent_col := 'shelf_id';
      v_child_col := 'shelf_id';
    ELSE
      RETURN NEW;
  END CASE;

  -- Read the parent id from the new row via jsonb so the function does not
  -- reference NEW.<col> directly (PL/pgSQL validates every NEW.<field> against
  -- the trigger table's rowtype at compile time, which would fail for the
  -- tables that do not have that column).
  v_parent_id := (v_new ->> v_child_col)::uuid;

  EXECUTE format('SELECT capacity FROM %s WHERE id = $1', v_parent_table)
    INTO v_parent_capacity USING v_parent_id;

  -- capacity = 0 means unlimited (modelled but not enforced).
  IF v_parent_capacity IS NULL OR v_parent_capacity = 0 THEN
    RETURN NEW;
  END IF;

  EXECUTE format(
    'SELECT count(*) FROM %I.%I WHERE workspace_id = $1 AND %I = $2',
    TG_TABLE_SCHEMA, TG_TABLE_NAME, v_child_col
  ) INTO v_child_count USING NEW.workspace_id, v_parent_id;

  IF v_child_count >= v_parent_capacity THEN
    RAISE EXCEPTION 'parent % capacity reached (% of %)',
      v_parent_table, v_child_count, v_parent_capacity
      USING ERRCODE = 'SB014';
  END IF;

  RETURN NEW;
END;
$_$;
--> statement-breakpoint
ALTER FUNCTION internal.enforce_storage_capacity() OWNER TO migrator;
--> statement-breakpoint
CREATE FUNCTION internal.enqueue_daily_digests() RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
  u record;
  v_titles text;
  v_workspace uuid;
  v_sent integer := 0;
BEGIN
  FOR u IN
    SELECT p.user_id, p.digest_time
      FROM api.user_preferences p
     WHERE p.digest_time IS NOT NULL
       AND p.digest_time = to_char(now() AT TIME ZONE 'UTC', 'HH24:MI')
       AND (p.digest_last_sent_on IS NULL OR p.digest_last_sent_on < current_date)
  LOOP
    SELECT string_agg(n.title, E'\n'), (array_agg(n.workspace_id))[1]
      INTO v_titles, v_workspace
      FROM internal.notifications n
     WHERE n.user_id = u.user_id
       AND n.read_at IS NULL
       AND n.created_at >= now() - interval '1 day';
    CONTINUE WHEN v_titles IS NULL OR v_workspace IS NULL;
    PERFORM internal.enqueue_email_delivery(
      v_workspace, u.user_id, 'digest', 'Daily digest', v_titles
    );
    UPDATE api.user_preferences
       SET digest_last_sent_on = current_date, updated_at = now()
     WHERE user_id = u.user_id;
    v_sent := v_sent + 1;
  END LOOP;
  RETURN v_sent;
END;
$$;
--> statement-breakpoint
ALTER FUNCTION internal.enqueue_daily_digests() OWNER TO migrator;
--> statement-breakpoint
CREATE FUNCTION internal.enqueue_email_delivery(p_workspace_id uuid, p_user_id text, p_event_type text, p_subject text, p_body text) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
  v_email text;
  v_id uuid;
BEGIN
  SELECT email INTO v_email FROM internal."user" WHERE id = p_user_id;
  IF v_email IS NULL THEN
    RAISE EXCEPTION 'unknown recipient' USING ERRCODE = '42501';
  END IF;
  INSERT INTO internal.email_deliveries
    (workspace_id, user_id, to_email, event_type, subject, body)
  VALUES (p_workspace_id, p_user_id, v_email, p_event_type, p_subject, p_body)
  RETURNING id INTO v_id;
  RETURN v_id;
END;
$$;
--> statement-breakpoint
