CREATE FUNCTION internal.enqueue_pipeline_run_job() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
BEGIN
  IF NEW.status = 'running' AND NEW.actor_user_id IS NOT NULL THEN
    INSERT INTO internal.pipeline_run_jobs(run_id, workspace_id, kind, actor_user_id)
    VALUES (NEW.id, NEW.workspace_id, 'execute', NEW.actor_user_id)
    ON CONFLICT DO NOTHING;
  END IF;
  RETURN NEW;
END $$;
