CREATE FUNCTION internal.evaluate_check_item(p_envelope jsonb, p_check_item jsonb) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
  rule_type text := p_check_item -> 'rule' ->> 'type';
  item_status text := 'pass';
  evidence jsonb := '{}';
  field_text text;
  field_value jsonb;
  array_len int;
  min_count int;
  path_text text;
  table_item jsonb;
  column_item jsonb;
  logical_type text;
  total_columns int := 0;
  invalid_columns jsonb := '[]';
  formula_item jsonb;
  calc_item jsonb;
  sheet jsonb;
  artifact jsonb;
  total_formulas int := 0;
  unsupported_formulas jsonb := '[]';
  stale_formulas jsonb := '[]';
  missing_results jsonb := '[]';
  formula_version_text text;
  calc_version_text text;
  tables jsonb := coalesce(p_envelope -> 'scientificTables', '[]');
  formulas jsonb := coalesce(p_envelope -> 'formulas', '[]');
  result_status text;
  link_item jsonb;
  link_type text;
  found_link_types text[] := '{}';
  required_link_types text[] := '{}';
  missing_link_types text[] := '{}';
  required_type text;
BEGIN
  -- Normalize frozen canonical evidence into the existing check vocabulary.
  -- No Dataset, Instance or calculation cache reads occur during review.
  FOR sheet IN
  SELECT
    value
  FROM
    jsonb_array_elements(coalesce(p_envelope -> 'sheetEvidence', '[]'))
    LOOP
      tables := tables || jsonb_build_array(jsonb_build_object('id', sheet ->> 'blockId', 'columns', coalesce(sheet -> 'composedGrid' -> 'fields', sheet -> 'instanceState' -> 'localFields', '[]')));
      FOR artifact IN
      SELECT
        value
      FROM
        jsonb_array_elements(coalesce(sheet -> 'composedGrid' -> 'calculations', sheet -> 'instanceState' -> 'instanceCalculations', '[]'))
        LOOP
          IF artifact ->> 'lifecycle' = 'retired' THEN
            CONTINUE;
          END IF;
          result_status := 'completed';
          IF artifact -> 'results' IS NULL OR jsonb_array_length(artifact -> 'results') = 0 OR EXISTS (
            SELECT
              1
            FROM
              jsonb_array_elements_text(coalesce(artifact -> 'expectedRowKeys', '[]')) k
            WHERE
              NOT EXISTS (
              SELECT
                1
              FROM
                jsonb_array_elements(coalesce(artifact -> 'results', '[]')) r
              WHERE
                r ->> 'row_key' = k.value)) THEN
            result_status := 'missing';
          ELSIF EXISTS (
              SELECT
                1
              FROM
                jsonb_array_elements(artifact -> 'results') r
              WHERE
                r ->> 'calculationStatus' IS DISTINCT FROM 'current') THEN
            result_status := 'stale';
          ELSIF EXISTS (
              SELECT
                1
              FROM
                jsonb_array_elements(artifact -> 'results') r
              WHERE
                r ->> 'result_kind' IS DISTINCT FROM 'value') THEN
            result_status := 'error';
          END IF;
          formulas := formulas || jsonb_build_array(jsonb_build_object('id', (sheet ->> 'blockId') || ':' || (artifact ->> 'id'), 'status', CASE WHEN artifact -> 'expression' ->> 'language' = 'sheetbase-formula-v1'
                AND NOT EXISTS (
                  SELECT
                    1
                  FROM jsonb_array_elements(coalesce(artifact -> 'results', '[]')) r
                WHERE
                  r ->> 'result_kind' = 'error') THEN
                'supported'
              ELSE
                'unsupported'
              END, 'version', sheet -> 'instanceRevision', 'calculation', CASE WHEN result_status = 'missing' THEN
                NULL
              ELSE
                jsonb_build_object('formula_version', sheet -> 'instanceRevision', 'status', result_status)
              END));
        END LOOP;
    END LOOP;
  IF rule_type = 'completeness-title' THEN
    field_text := p_envelope -> 'record' ->> 'title';
    IF field_text IS NULL OR btrim(field_text) = '' THEN
      item_status := 'fail';
    END IF;
    evidence := jsonb_build_object('title', to_jsonb (field_text));
  ELSIF rule_type = 'min-count' THEN
    path_text := p_check_item -> 'rule' ->> 'path';
    field_value := p_envelope -> path_text;
    array_len := CASE WHEN jsonb_typeof(field_value) = 'array' THEN
      jsonb_array_length(field_value)
    ELSE
      0
    END;
    min_count := coalesce((p_check_item -> 'rule' ->> 'minCount')::int, 0);
    IF array_len < min_count THEN
      item_status := 'fail';
    END IF;
    evidence := jsonb_build_object('path', path_text, 'count', array_len, 'minCount', min_count);
  ELSIF rule_type = 'schema-valid-columns' THEN
    FOR table_item IN
    SELECT
      value
    FROM
      jsonb_array_elements(tables)
      LOOP
        FOR column_item IN
        SELECT
          value
        FROM
          jsonb_array_elements(coalesce(table_item -> 'columns', '[]'))
          LOOP
            total_columns := total_columns + 1;
            logical_type := coalesce(column_item ->> 'logicalType', column_item ->> 'logical_type');
            IF logical_type IS NULL OR logical_type NOT IN ('text', 'integer', 'decimal', 'boolean', 'date', 'timestamp', 'category', 'reference') THEN
              item_status := 'fail';
              invalid_columns := invalid_columns || jsonb_build_array(jsonb_build_object('tableId', table_item ->> 'id', 'columnId', coalesce(column_item ->> 'id', column_item ->> 'fieldId'), 'fieldName', coalesce(column_item ->> 'fieldName', column_item ->> 'field_name', column_item ->> 'key'), 'logicalType', to_jsonb (logical_type)));
            END IF;
          END LOOP;
      END LOOP;
    evidence := jsonb_build_object('totalColumns', total_columns, 'invalidColumns', invalid_columns);
  ELSIF rule_type = 'formula-supported' THEN
    FOR formula_item IN
    SELECT
      value
    FROM
      jsonb_array_elements(formulas)
      LOOP
        total_formulas := total_formulas + 1;
        IF formula_item ->> 'status' IS DISTINCT FROM 'supported' THEN
          item_status := 'fail';
          unsupported_formulas := unsupported_formulas || jsonb_build_array(jsonb_build_object('id', formula_item ->> 'id', 'status', formula_item ->> 'status'));
        END IF;
      END LOOP;
    evidence := jsonb_build_object('totalFormulas', total_formulas, 'unsupportedFormulas', unsupported_formulas);
  ELSIF rule_type = 'formula-no-stale' THEN
    FOR formula_item IN
    SELECT
      value
    FROM
      jsonb_array_elements(formulas)
      LOOP
        total_formulas := total_formulas + 1;
        calc_item := formula_item -> 'calculation';
        formula_version_text := formula_item ->> 'version';
        IF calc_item IS NULL OR jsonb_typeof(calc_item) = 'null' THEN
          item_status := 'fail';
          missing_results := missing_results || jsonb_build_array(jsonb_build_object('id', formula_item ->> 'id', 'reason', 'no_cached_result'));
        ELSE
          calc_version_text := calc_item ->> 'formula_version';
          IF calc_version_text IS DISTINCT FROM formula_version_text THEN
            item_status := 'fail';
            stale_formulas := stale_formulas || jsonb_build_array(jsonb_build_object('id', formula_item ->> 'id', 'formulaVersion', formula_version_text, 'cachedVersion', calc_version_text, 'reason', 'version_mismatch'));
          ELSIF calc_item ->> 'status' IS DISTINCT FROM 'completed' THEN
            item_status := 'fail';
            stale_formulas := stale_formulas || jsonb_build_array(jsonb_build_object('id', formula_item ->> 'id', 'calculationStatus', calc_item ->> 'status', 'reason', 'incomplete'));
          END IF;
        END IF;
      END LOOP;
    evidence := jsonb_build_object('totalFormulas', total_formulas, 'staleFormulas', stale_formulas, 'missingResults', missing_results);
  ELSIF rule_type = 'required-links' THEN
    FOR required_type IN
    SELECT
      value
    FROM
      jsonb_array_elements_text(coalesce(p_check_item -> 'rule' -> 'linkTypes', '[]'))
      LOOP
        required_link_types := array_append(required_link_types, required_type);
      END LOOP;
    FOR link_item IN
    SELECT
      value
    FROM
      jsonb_array_elements(coalesce(p_envelope -> 'links', '[]'))
      LOOP
        link_type := coalesce(link_item ->> 'linkType', link_item ->> 'link_type');
        IF link_type IS NOT NULL AND NOT (link_type = ANY (found_link_types)) THEN
          found_link_types := array_append(found_link_types, link_type);
        END IF;
      END LOOP;
    FOREACH required_type IN ARRAY required_link_types LOOP
      IF NOT (required_type = ANY (found_link_types)) THEN
        item_status := 'fail';
        missing_link_types := array_append(missing_link_types, required_type);
      END IF;
    END LOOP;
    evidence := jsonb_build_object('requiredLinkTypes', to_jsonb (required_link_types), 'foundLinkTypes', to_jsonb (found_link_types), 'missingLinkTypes', to_jsonb (missing_link_types));
  ELSE
    item_status := 'fail';
    evidence := jsonb_build_object('error', 'unknown rule type', 'ruleType', rule_type);
  END IF;
  RETURN jsonb_build_object('key', p_check_item ->> 'key', 'category', p_check_item ->> 'category', 'severity', p_check_item ->> 'severity', 'label', p_check_item ->> 'label', 'status', item_status, 'evidence', evidence);
END
$$;
--> statement-breakpoint
ALTER FUNCTION internal.evaluate_check_item(p_envelope jsonb, p_check_item jsonb) OWNER TO migrator;
--> statement-breakpoint
CREATE FUNCTION internal.evaluate_model_rules(p_workspace uuid, p_model text, p_values jsonb) RETURNS jsonb
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  SELECT jsonb_build_object(
    'blocked', coalesce(bool_or(effect = 'block'), false),
    'blockSubmit', coalesce(bool_or(effect IN ('block','flag_block_submit')), false),
    'warnings', coalesce(jsonb_agg(
      jsonb_build_object('ruleId', id, 'effect', effect, 'message', message)
      ORDER BY created_at, id) FILTER (WHERE effect = 'warn'), '[]'::jsonb),
    'blocks', coalesce(jsonb_agg(
      jsonb_build_object('ruleId', id, 'effect', effect, 'message', message)
      ORDER BY created_at, id) FILTER (WHERE effect = 'block'), '[]'::jsonb),
    'submitBlocks', coalesce(jsonb_agg(
      jsonb_build_object('ruleId', id, 'effect', effect, 'message', message)
      ORDER BY created_at, id) FILTER (WHERE effect = 'flag_block_submit'), '[]'::jsonb)
  )
  FROM api.model_rules
  WHERE workspace_id = p_workspace
    AND model_key = p_model
    AND internal.model_rule_condition_matches(condition, coalesce(p_values, '{}'::jsonb));
$$;
--> statement-breakpoint
ALTER FUNCTION internal.evaluate_model_rules(p_workspace uuid, p_model text, p_values jsonb) OWNER TO migrator;
--> statement-breakpoint
CREATE FUNCTION internal.evaluate_sample_release_rules(p_rules jsonb, p_measurements jsonb) RETURNS jsonb
    LANGUAGE plpgsql STABLE
    SET search_path TO ''
    AS $$
DECLARE
  v_rules jsonb := CASE WHEN jsonb_typeof(coalesce(p_rules, '[]'::jsonb)) = 'array'
                        THEN coalesce(p_rules, '[]'::jsonb) ELSE '[]'::jsonb END;
  v_measurements jsonb := CASE WHEN jsonb_typeof(coalesce(p_measurements, '[]'::jsonb)) = 'array'
                               THEN coalesce(p_measurements, '[]'::jsonb) ELSE '[]'::jsonb END;
  v_rule jsonb;
  v_checks jsonb := '[]'::jsonb;
  v_failed jsonb := '[]'::jsonb;
  v_key text;
  v_label text;
  v_kind text;
  v_passed boolean;
  v_detail text;
  v_count integer;
  v_total integer;
  v_out_of_range integer;
  v_min numeric;
  v_max numeric;
  v_result text;
BEGIN
  FOR v_rule IN SELECT value FROM jsonb_array_elements(v_rules) LOOP
    v_kind := v_rule ->> 'kind';
    v_key := coalesce(
      nullif(v_rule ->> 'key', ''),
      v_kind || ':' || coalesce(v_rule ->> 'measurement', v_rule ->> 'result', '')
    );
    v_label := coalesce(nullif(v_rule ->> 'label', ''), v_key);
    v_passed := false;
    v_detail := NULL;

    IF v_kind = 'no_result' THEN
      v_result := nullif(btrim(coalesce(v_rule ->> 'result', '')), '');
      IF v_result IS NULL THEN
        v_detail := 'rule is missing a result';
      ELSE
        SELECT count(*) INTO v_out_of_range
          FROM jsonb_array_elements(v_measurements) m
         WHERE lower(coalesce(m ->> 'result', '')) = lower(v_result);
        v_passed := v_out_of_range = 0;
        IF NOT v_passed THEN
          v_detail := format('%s measurement(s) with result %s', v_out_of_range, v_result);
        END IF;
      END IF;

    ELSIF v_kind = 'min_measurements' THEN
      v_count := coalesce(nullif(v_rule ->> 'count', '')::integer, 1);
      v_total := jsonb_array_length(v_measurements);
      v_passed := v_total >= v_count;
      IF NOT v_passed THEN
        v_detail := format('requires %s measurement(s), found %s', v_count, v_total);
      END IF;

    ELSIF v_kind = 'measurement_required' THEN
      SELECT count(*) INTO v_total
        FROM jsonb_array_elements(v_measurements) m
       WHERE lower(coalesce(m ->> 'measurement', '')) = lower(coalesce(v_rule ->> 'measurement', ''));
      v_passed := v_total > 0;
      IF NOT v_passed THEN
        v_detail := format('measurement %s not found', coalesce(v_rule ->> 'measurement', ''));
      END IF;

    ELSIF v_kind = 'measurement_range' THEN
      v_min := NULLIF(v_rule ->> 'min', '')::numeric;
      v_max := NULLIF(v_rule ->> 'max', '')::numeric;
      SELECT count(*),
             count(*) FILTER (WHERE
               (m ->> 'value') IS NULL
               OR (v_min IS NOT NULL AND coalesce((m ->> 'value')::numeric, 'NaN'::numeric) < v_min)
               OR (v_max IS NOT NULL AND coalesce((m ->> 'value')::numeric, 'NaN'::numeric) > v_max)
             )
        INTO v_total, v_out_of_range
        FROM jsonb_array_elements(v_measurements) m
       WHERE lower(coalesce(m ->> 'measurement', '')) = lower(coalesce(v_rule ->> 'measurement', ''));
      v_passed := v_total > 0 AND v_out_of_range = 0;
      IF NOT v_passed THEN
        v_detail := format('measurement %s is missing or outside the required range', coalesce(v_rule ->> 'measurement', ''));
      END IF;

    ELSE
      v_detail := format('unknown release rule kind %s', coalesce(v_kind, '<null>'));
      v_passed := false;
    END IF;

    v_checks := v_checks || jsonb_build_array(jsonb_build_object(
      'key', v_key,
      'label', v_label,
      'kind', v_kind,
      'passed', v_passed,
      'detail', v_detail
    ));
    IF NOT v_passed THEN
      v_failed := v_failed || jsonb_build_array(v_label);
    END IF;
  END LOOP;

  RETURN jsonb_build_object(
    'passed', jsonb_array_length(v_failed) = 0,
    'ruleCount', jsonb_array_length(v_rules),
    'failedCount', jsonb_array_length(v_failed),
    'failedLabels', v_failed,
    'checks', v_checks
  );
END;
$$;
--> statement-breakpoint
ALTER FUNCTION internal.evaluate_sample_release_rules(p_rules jsonb, p_measurements jsonb) OWNER TO migrator;
--> statement-breakpoint
CREATE FUNCTION internal.expand_reference_fields(p_schema_id uuid, p_field_values jsonb, p_expand jsonb) RETURNS jsonb
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
DECLARE
  v_slug text; v_opts jsonb; v_depth int;
  field api.dataset_schema_fields; rel api.dataset_schema_relationships;
  target api.dataset_schemas; ref_id uuid; ref_val text;
  t api.scientific_tables; proj text; row_json jsonb;
  nested_expand jsonb; expanded_val jsonb;
BEGIN
  IF p_expand IS NULL OR jsonb_typeof(p_expand) <> 'object' OR p_expand = '{}'::jsonb THEN
    RETURN p_field_values;
  END IF;
  FOR v_slug, v_opts IN SELECT key, value FROM jsonb_each(p_expand) LOOP
    SELECT * INTO field FROM api.dataset_schema_fields AS f
      WHERE f.schema_id = p_schema_id AND f.slug = v_slug AND f.logical_type = 'reference' AND f.lifecycle = 'active';
    IF field.id IS NULL THEN CONTINUE; END IF;
    v_depth := LEAST(2, GREATEST(1, COALESCE((v_opts->>'depth')::int, 1)));
    ref_val := p_field_values ->> v_slug;
    IF ref_val IS NULL THEN CONTINUE; END IF;
    BEGIN ref_id := ref_val::uuid; EXCEPTION WHEN others THEN CONTINUE; END;
    SELECT * INTO rel FROM api.dataset_schema_relationships AS r
      WHERE r.source_schema_id = p_schema_id AND r.source_field_id = field.id
        AND r.relationship_type = 'references' AND r.lifecycle = 'active'
      LIMIT 1;
    IF rel.target_schema_id IS NULL THEN CONTINUE; END IF;
    SELECT * INTO target FROM api.dataset_schemas AS ds WHERE ds.id = rel.target_schema_id;
    IF target.id IS NULL THEN CONTINUE; END IF;
    row_json := NULL;
    FOR t IN SELECT * FROM api.scientific_tables AS st
               WHERE st.dataset_schema_id = target.id
                 AND st.dataset_schema_revision = target.revision
                 AND st.lifecycle = 'active' LOOP
      SELECT string_agg(format('%L,%I', f.slug, c.field_name), ', ') INTO proj
        FROM api.scientific_columns c
        JOIN api.dataset_schema_fields f ON f.id = c.dataset_schema_field_id AND f.lifecycle = 'active'
        WHERE c.table_id = t.id AND c.lifecycle = 'active';
      IF proj IS NULL THEN CONTINUE; END IF;
      BEGIN
        EXECUTE format('SELECT jsonb_build_object(%s) FROM api.%I WHERE id = %L', proj, t.resource_name, ref_id) INTO row_json;
      EXCEPTION WHEN others THEN row_json := NULL; END;
      IF row_json IS NOT NULL THEN
        EXIT;
      END IF;
    END LOOP;
    IF row_json IS NULL THEN CONTINUE; END IF;
    IF v_depth > 1 THEN
      SELECT COALESCE(jsonb_object_agg(f.slug, jsonb_build_object('depth', v_depth - 1)), '{}'::jsonb) INTO nested_expand
        FROM api.dataset_schema_fields f
        WHERE f.schema_id = target.id AND f.logical_type = 'reference' AND f.lifecycle = 'active';
      row_json := internal.expand_reference_fields(target.id, row_json, nested_expand);
    END IF;
    expanded_val := jsonb_build_object('referenced_table_id', t.id, 'referenced_record_id', t.record_id, 'referenced_fields', row_json);
    p_field_values := jsonb_set(p_field_values, ARRAY[v_slug], expanded_val);
  END LOOP;
  RETURN p_field_values;
END $$;
--> statement-breakpoint
ALTER FUNCTION internal.expand_reference_fields(p_schema_id uuid, p_field_values jsonb, p_expand jsonb) OWNER TO migrator;
--> statement-breakpoint
CREATE FUNCTION internal.explain_sheet_block_dependency() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE table_id uuid; affected bigint;
BEGIN
 IF OLD.type<>'sheet' THEN RETURN OLD; END IF;
 SELECT id INTO table_id FROM api.scientific_tables WHERE block_id=OLD.id;
 SELECT count(DISTINCT formula_id) INTO affected FROM (
   SELECT f.id formula_id FROM api.formula_definitions f WHERE f.target_table_id=table_id
   UNION ALL SELECT d.formula_id FROM api.formula_dependencies d WHERE d.source_table_id=table_id
 ) x;
 IF affected>0 THEN RAISE EXCEPTION 'sheet is used by % persisted formula(s); inspect dependencies and remove those formulas first',affected USING ERRCODE='23514'; END IF;
 RETURN OLD;
END $$;
--> statement-breakpoint
ALTER FUNCTION internal.explain_sheet_block_dependency() OWNER TO migrator;
