CREATE FUNCTION internal.extract_jsonb_text(v jsonb) RETURNS text
    LANGUAGE plpgsql IMMUTABLE
    AS $$
DECLARE
  parts text[] := ARRAY[]::text[];
  elem jsonb;
  key text;
  val jsonb;
BEGIN
  IF v IS NULL THEN RETURN ''; END IF;
  CASE jsonb_typeof(v)
    WHEN 'string' THEN
      RETURN v #>> '{}';
    WHEN 'object' THEN
      FOR key, val IN SELECT * FROM jsonb_each(v) LOOP
        IF jsonb_typeof(val) IN ('string', 'object', 'array') THEN
          parts := array_append(parts, internal.extract_jsonb_text(val));
        END IF;
      END LOOP;
    WHEN 'array' THEN
      FOR elem IN SELECT * FROM jsonb_array_elements(v) LOOP
        parts := array_append(parts, internal.extract_jsonb_text(elem));
      END LOOP;
    ELSE
      RETURN '';
  END CASE;
  RETURN array_to_string(parts, ' ');
END;
$$;
--> statement-breakpoint
ALTER FUNCTION internal.extract_jsonb_text(v jsonb) OWNER TO migrator;
--> statement-breakpoint
CREATE FUNCTION internal.finish_email_delivery(p_id uuid, p_sent boolean, p_error text DEFAULT NULL::text) RETURNS internal.email_deliveries
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
  v internal.email_deliveries;
  v_delay_ms bigint;
BEGIN
  IF p_sent THEN
    UPDATE internal.email_deliveries
       SET status = 'sent', sent_at = now(), last_error = NULL, updated_at = now()
     WHERE id = p_id RETURNING * INTO v;
    RETURN v;
  END IF;
  SELECT * INTO v FROM internal.email_deliveries WHERE id = p_id FOR UPDATE;
  IF v.id IS NULL THEN
    RAISE EXCEPTION 'delivery not found' USING ERRCODE = '42501';
  END IF;
  IF v.attempt >= 5 THEN
    UPDATE internal.email_deliveries
       SET status = 'dead', last_error = p_error, updated_at = now()
     WHERE id = v.id RETURNING * INTO v;
    RETURN v;
  END IF;
  -- Exponential backoff: 30s, 60s, 120s, 240s (capped), with jitter.
  v_delay_ms := least((30000::bigint * (1 << (v.attempt - 1))), 6 * 3600 * 1000);
  v_delay_ms := v_delay_ms + (random() * v_delay_ms * 0.1)::bigint;
  UPDATE internal.email_deliveries
     SET status = 'pending',
         next_attempt_at = now() + make_interval(secs => v_delay_ms / 1000.0),
         last_error = p_error,
         updated_at = now()
   WHERE id = v.id RETURNING * INTO v;
  RETURN v;
END;
$$;
--> statement-breakpoint
ALTER FUNCTION internal.finish_email_delivery(p_id uuid, p_sent boolean, p_error text) OWNER TO migrator;
--> statement-breakpoint
