CREATE FUNCTION internal.gov01_write_predicate(expr text, relname text) RETURNS text
    LANGUAGE plpgsql IMMUTABLE
    SET search_path TO ''
    AS $$
BEGIN
  IF expr IS NULL OR btrim(expr) = '' THEN
    RETURN expr;
  END IF;
  expr := regexp_replace(
    expr,
    'api\.storage_member_using\(([A-Za-z0-9_.]+)\)',
    'api.is_workspace_writer(\1)',
    'g'
  );
  IF relname = 'record_links' THEN
    expr := regexp_replace(
      expr,
      'api\.is_workspace_member\(([A-Za-z0-9_.]+)\)',
      'api.has_capability(\1, ''record.link'')',
      'g'
    );
  ELSE
    expr := regexp_replace(
      expr,
      'api\.is_workspace_member\(([A-Za-z0-9_.]+)\)',
      'api.is_workspace_writer(\1)',
      'g'
    );
  END IF;
  RETURN expr;
END;
$$;
