         OR NEW.slug IS DISTINCT FROM OLD.slug
         OR NEW.logical_type IS DISTINCT FROM OLD.logical_type THEN
        RAISE EXCEPTION 'dataset schema field identity (workspace_id, schema_id, slug, logical_type) is immutable'
          USING ERRCODE = '23514';
      END IF;
    END IF;
  END IF;
  RETURN NEW;
END;
$$;
