CREATE FUNCTION internal.lock_dataset_schema_write_version(p_schema_version_id uuid, p_expected_revision bigint) RETURNS api.dataset_schema_versions
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
  version api.dataset_schema_versions;
  definition api.dataset_schema_definitions;
BEGIN
  SELECT * INTO version FROM api.dataset_schema_versions WHERE id = p_schema_version_id FOR UPDATE;
  IF version.id IS NULL THEN
    RAISE EXCEPTION 'Dataset Schema Version not found' USING ERRCODE = '42501';
  END IF;
  SELECT * INTO definition FROM api.dataset_schema_definitions WHERE id = version.schema_id FOR UPDATE;
  IF version.lifecycle = 'draft' THEN
    IF p_expected_revision IS NULL THEN
      RAISE EXCEPTION 'expected revision is required to update a draft Dataset Schema Version'
        USING ERRCODE = 'SB001';
    END IF;
    IF p_expected_revision IS DISTINCT FROM version.revision THEN
      RAISE EXCEPTION 'stale Dataset Schema Version revision' USING ERRCODE = 'SB001';
    END IF;
    RETURN version;
  END IF;
  IF version.lifecycle <> 'active' THEN
    RAISE EXCEPTION 'Dataset Schema Version cannot be evolved' USING ERRCODE = 'SB072';
  END IF;
  RETURN internal.fork_dataset_schema_version(version.id);
END;
$$;
--> statement-breakpoint
ALTER FUNCTION internal.lock_dataset_schema_write_version(p_schema_version_id uuid, p_expected_revision bigint) OWNER TO migrator;
--> statement-breakpoint
CREATE FUNCTION internal.lock_record(p_record_id uuid, p_revision_id uuid, p_locked_at timestamp with time zone) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
  v_workspace uuid;
  v_project uuid;
  v_already_locked_by uuid;
BEGIN
  SELECT workspace_id, locked_by_revision_id INTO v_workspace, v_already_locked_by
  FROM api.records WHERE id = p_record_id FOR UPDATE;
  IF v_workspace IS NULL THEN
    RETURN;
  END IF;
  -- Idempotent: a witness signature after the approve-for-record signature
  -- must not error or overwrite the lock.
  IF v_already_locked_by IS NOT NULL THEN
    RETURN;
  END IF;
  UPDATE api.records
    SET locked_at = p_locked_at,
        locked_by_revision_id = p_revision_id,
        updated_at = now()
    WHERE id = p_record_id;
  SELECT project_id INTO v_project FROM api.records WHERE id = p_record_id;
  PERFORM internal.emit_change_event(
    v_workspace, 'record', p_record_id, 'lock', p_record_id, v_project,
    jsonb_build_object(
      'revisionId', p_revision_id,
      'lockedAt', p_locked_at
    )
  );
END;
$$;
--> statement-breakpoint
ALTER FUNCTION internal.lock_record(p_record_id uuid, p_revision_id uuid, p_locked_at timestamp with time zone) OWNER TO migrator;
--> statement-breakpoint
