    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
BEGIN
  IF NEW.signature_meaning='reviewed-and-approved' THEN
    PERFORM internal.lock_record(NEW.record_id,NEW.revision_id,NEW.signed_at);
  END IF;
  RETURN NEW;
END $$;
