CREATE FUNCTION internal.notebook_sheet_block_for_template_placement(p_record_id uuid, p_source_configuration jsonb, p_placement_id text) RETURNS api.blocks
    LANGUAGE plpgsql STABLE
    SET search_path TO ''
    AS $$
DECLARE
  block api.blocks;
  sheet_ordinal int;
BEGIN
  SELECT b.* INTO block
    FROM api.blocks b
    WHERE b.record_id = p_record_id
      AND b.type = 'sheet'
      AND b.payload->>'templatePlacementId' = p_placement_id
    LIMIT 1;
  IF block.id IS NOT NULL THEN
    RETURN block;
  END IF;

  -- Legacy Notebooks: sheet blocks were inserted in Template placement order.
  SELECT ranked.ord INTO sheet_ordinal
    FROM (
      SELECT value->>'id' AS pid,
             row_number() OVER (ORDER BY (value->>'order')::int, value->>'id') AS ord
        FROM jsonb_array_elements(coalesce(p_source_configuration->'placements','[]'::jsonb)) value
       WHERE value->>'kind' = 'sheet'
    ) ranked
   WHERE ranked.pid = p_placement_id;
  IF sheet_ordinal IS NULL THEN
    RETURN NULL;
  END IF;

  SELECT ranked.* INTO block
    FROM (
      SELECT b.*,
             row_number() OVER (ORDER BY b."order", b.id) AS ord
        FROM api.blocks b
       WHERE b.record_id = p_record_id
         AND b.type = 'sheet'
    ) ranked
   WHERE ranked.ord = sheet_ordinal;

  RETURN block;
END
$$;
--> statement-breakpoint
ALTER FUNCTION internal.notebook_sheet_block_for_template_placement(p_record_id uuid, p_source_configuration jsonb, p_placement_id text) OWNER TO migrator;
--> statement-breakpoint
CREATE FUNCTION internal.notebook_sheet_evidence(p_record_id uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
  rec api.records;
  block api.blocks;
  instance api.sheet_instances;
  definition_config jsonb;
  binding jsonb;
  dataset_row api.datasets;
  items jsonb := '[]'::jsonb;
  bindings jsonb;
BEGIN
  SELECT * INTO rec FROM api.records WHERE id = p_record_id;
  IF rec.id IS NULL THEN
    RETURN '[]'::jsonb;
  END IF;
  FOR block IN
    SELECT * FROM api.blocks
      WHERE record_id = rec.id AND type = 'sheet' AND payload ? 'instanceId'
      ORDER BY "order", id
  LOOP
    SELECT * INTO instance FROM api.sheet_instances
      WHERE id = (block.payload->>'instanceId')::uuid;
    IF instance.id IS NULL THEN
      RAISE EXCEPTION 'Sheet Instance for submitted block is missing' USING ERRCODE = 'SB092';
    END IF;
    definition_config := NULL;
    IF instance.source_definition_version_id IS NOT NULL THEN
      SELECT configuration INTO definition_config
        FROM api.sheet_definition_versions definition_version
        WHERE definition_version.id = instance.source_definition_version_id;
    END IF;
    bindings := '[]'::jsonb;
    FOR binding IN SELECT value FROM jsonb_array_elements(coalesce(instance.state->'bindings','[]'::jsonb)) LOOP
      IF binding->>'kind' = 'dataset' THEN
        SELECT * INTO dataset_row FROM api.datasets WHERE id = (binding->>'datasetId')::uuid;
        bindings := bindings || jsonb_build_array(jsonb_build_object(
          'bindingId', binding->>'bindingId',
          'parameterId', binding->>'parameterId',
          'datasetId', binding->>'datasetId',
          'policyMode', coalesce(binding->'policy'->>'mode','live'),
          'datasetVersionId', binding->'policy'->>'datasetVersionId',
          'datasetRevision', dataset_row.revision,
          'schemaVersionId', dataset_row.schema_version_id
        ));
      ELSE
        bindings := bindings || jsonb_build_array(binding);
      END IF;
    END LOOP;
    items := items || jsonb_build_array(jsonb_build_object(
      'blockId', block.id,
      'instanceId', instance.id,
      'instanceRevision', instance.revision,
      'sourceDefinitionVersionId', instance.source_definition_version_id,
      'definitionConfiguration', definition_config,
      'instanceState', instance.state,
      'datasetBindings', bindings
    ));
  END LOOP;
  RETURN items;
END
$$;
--> statement-breakpoint
ALTER FUNCTION internal.notebook_sheet_evidence(p_record_id uuid) OWNER TO migrator;
