CREATE FUNCTION internal.notify_project_protocol_training() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
BEGIN
  PERFORM internal.notify_protocol_training(NEW.protocol_version_id, NEW.project_id,
    api.current_user_id());
  RETURN NULL;
END $$;
