CREATE FUNCTION internal.notify_protocol_training(p_version_id uuid, p_project_id uuid, p_actor_user_id text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
  v_version api.protocol_versions;
  v_identifier text;
  v_title text;
BEGIN
  SELECT * INTO v_version FROM api.protocol_versions WHERE id = p_version_id;
  IF v_version.id IS NULL OR v_version.status <> 'effective' THEN
    RETURN;
  END IF;
  IF NOT internal.protocol_version_is_eligible(v_version.id, false) THEN
    RETURN;
  END IF;
  SELECT r.identifier INTO v_identifier FROM api.records r WHERE r.id = v_version.protocol_record_id;
  v_title := 'Read and acknowledge ' || coalesce(v_identifier, 'the protocol')
    || ' v' || v_version.version::text;
  INSERT INTO internal.notifications
    (workspace_id, user_id, event_type, title, body, record_id, project_id)
  SELECT v_version.workspace_id, m.user_id, 'protocol_training_required',
         v_title, NULL, v_version.protocol_record_id, p_project_id
    FROM api.workspace_memberships m
   WHERE m.workspace_id = v_version.workspace_id
     AND m.suspended_at IS NULL
     AND m.role <> 'client_viewer'
     AND m.user_id IS DISTINCT FROM p_actor_user_id
     AND NOT EXISTS (SELECT 1 FROM api.protocol_acknowledgements a
                      WHERE a.protocol_version_id = v_version.id AND a.user_id = m.user_id)
     AND (p_project_id IS NULL OR EXISTS (
           SELECT 1 FROM api.project_access pa
            WHERE pa.workspace_id = v_version.workspace_id
              AND pa.project_id = p_project_id
              AND (pa.user_id = m.user_id
                   OR EXISTS (SELECT 1 FROM api.workspace_group_memberships g
                               WHERE g.workspace_id = pa.workspace_id
                                 AND g.group_id = pa.group_id AND g.user_id = m.user_id))
              AND coalesce(pa.can_view OR pa.can_edit OR pa.can_review OR pa.can_manage, false)))
     AND NOT EXISTS (SELECT 1 FROM internal.notifications n
                      WHERE n.user_id = m.user_id
                        AND n.event_type = 'protocol_training_required'
                        AND n.record_id = v_version.protocol_record_id
                        AND n.project_id IS NOT DISTINCT FROM p_project_id
                        AND n.title = v_title);
END $$;
--> statement-breakpoint
ALTER FUNCTION internal.notify_protocol_training(p_version_id uuid, p_project_id uuid, p_actor_user_id text) OWNER TO migrator;
--> statement-breakpoint
CREATE FUNCTION internal.persist_revision_sheet_evidence(p_revision_id uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
  revision api.revisions;
  item jsonb;
  binding jsonb;
  frozen jsonb;
  SNAPSHOT api.dataset_versions;
  dataset_row api.datasets;
  version_id uuid;
  seen jsonb := '{}';
  grid jsonb;
  config jsonb;
  calculation jsonb;
  calculations jsonb;
  artifacts jsonb;
  expected_expression jsonb;
  expected_scope text;
  results jsonb;
  fields jsonb;
  output_id text;
  column_position int;
  row_position int;
  result_item jsonb;
BEGIN
  SELECT
    *
  INTO
    revision
  FROM
    api.revisions
  WHERE
    id = p_revision_id;
  IF revision.id IS NULL THEN
    RAISE EXCEPTION 'revision not found'
      USING ERRCODE = '22023';
  END IF;
  FOR item IN
  SELECT
    value
  FROM
    jsonb_array_elements(coalesce(revision.canonical_snapshot -> 'sheetEvidence', '[]'))
    LOOP
      IF EXISTS (
        SELECT
          1
        FROM
          api.revision_sheet_evidence
        WHERE
          revision_id = revision.id
          AND block_id = (item ->> 'blockId')::uuid) THEN
      CONTINUE;
    END IF;
  frozen := '[]';
  FOR binding IN
  SELECT
    value
  FROM
    jsonb_array_elements(coalesce(item -> 'datasetBindings', '[]'))
    LOOP
      IF binding ->> 'datasetId' IS NULL THEN
        CONTINUE;
      END IF;
      version_id := NULL;
      IF binding ->> 'policyMode' = 'version' AND binding ->> 'datasetVersionId' IS NOT NULL THEN
        version_id := (binding ->> 'datasetVersionId')::uuid;
      ELSIF seen ? (binding ->> 'datasetId') THEN
        version_id := (seen ->> (binding ->> 'datasetId'))::uuid;
      ELSE
        SELECT
          *
        INTO
          dataset_row
        FROM
          api.datasets
        WHERE
          id = (binding ->> 'datasetId')::uuid
          AND workspace_id = revision.workspace_id;
        IF dataset_row.id IS NULL THEN
          RAISE EXCEPTION 'Dataset for Sheet evidence is missing'
            USING ERRCODE = 'SB092';
        END IF;
        SNAPSHOT := api.snapshot_dataset (dataset_row.id, (binding ->> 'datasetRevision')::bigint, 'Notebook revision sheet evidence');
        version_id := snapshot.id;
        seen := seen || jsonb_build_object(binding ->> 'datasetId', version_id);
      END IF;
      frozen := frozen || jsonb_build_array(jsonb_build_object('bindingId', binding ->> 'bindingId', 'datasetId', binding ->> 'datasetId', 'datasetVersionId', version_id, 'policyMode', binding ->> 'policyMode'));
    END LOOP;
  grid := internal.build_frozen_composed_sheet_grid (item -> 'instanceState', nullif (item ->> 'sourceDefinitionVersionId', '')::uuid, frozen);
  config := NULL;
  SELECT
    v.configuration
  INTO
    config
  FROM
    api.sheet_definition_versions v
    JOIN api.sheet_definitions d ON d.id = v.definition_id
  WHERE
    v.id = nullif (item ->> 'sourceDefinitionVersionId', '')::uuid
    AND d.workspace_id = revision.workspace_id;
  fields := coalesce((
    SELECT
      jsonb_agg(value -> 'field')
    FROM jsonb_array_elements(coalesce(config -> 'columns', '[]'))), '[]') || coalesce(item -> 'instanceState' -> 'localFields', '[]') || coalesce((
    SELECT
      jsonb_agg(value -> 'outputField')
    FROM jsonb_array_elements(coalesce(item -> 'instanceState' -> 'instanceCalculations', '[]'))
    WHERE
      value ->> 'lifecycle' = 'active'), '[]');
  artifacts := '[]';
  calculations := coalesce(config -> 'calculations', '[]') || coalesce(item -> 'instanceState' -> 'instanceCalculations', '[]');
  FOR calculation IN
  SELECT
    value
  FROM
    jsonb_array_elements(calculations)
    LOOP
      IF calculation ? 'outputColumnId' THEN
        IF coalesce(item -> 'instanceState' -> 'calculationOverrides' -> (calculation ->> 'id') ->> 'enabled', 'true') <> 'true' THEN
          CONTINUE;
        END IF;
        expected_scope := 'definition';
        expected_expression := coalesce(item -> 'instanceState' -> 'calculationOverrides' -> (calculation ->> 'id') -> 'expression', calculation -> 'expression');
      ELSE
        IF calculation ->> 'lifecycle' <> 'active' THEN
          CONTINUE;
        END IF;
        expected_scope := 'instance';
        expected_expression := calculation -> 'expression';
      END IF;
      SELECT
        coalesce(jsonb_agg(to_jsonb (r) || jsonb_build_object('calculationStatus', CASE WHEN internal.sheet_calculation_result_current ((item ->> 'instanceRevision')::bigint, r.instance_revision, r.source_revisions)
            AND r.expression = expected_expression
            AND r.scope = expected_scope
            AND (expected_scope <> 'definition'
                OR r.definition_version_id = nullif (item ->> 'sourceDefinitionVersionId', '')::uuid) THEN
                'current'
              ELSE
                'stale'
              END)
          ORDER BY r.row_key), '[]')
      INTO
        results
      FROM
        internal.sheet_instance_calculation_results r
      WHERE
        r.instance_id = (item ->> 'instanceId')::uuid
        AND r.workspace_id = revision.workspace_id
        AND r.calculation_id = (calculation ->> 'id')::uuid
        AND r.row_key IN (
          SELECT
            value
          FROM
            jsonb_array_elements_text(grid -> 'rowKeys'));
      artifacts := artifacts || jsonb_build_array(calculation || jsonb_build_object('scope', expected_scope, 'expression', expected_expression, 'results', results, 'expectedRowKeys', grid -> 'rowKeys'));
      output_id := coalesce(calculation ->> 'outputColumnId', calculation ->> 'id');
      SELECT
        ORDINALITY::int -1
      INTO
        column_position
      FROM
        jsonb_array_elements(grid -> 'columns')
  WITH ORDINALITY
WHERE
  value ->> 'id' = output_id;
      IF column_position IS NOT NULL THEN
        FOR result_item IN
        SELECT
          value
        FROM
          jsonb_array_elements(results)
        WHERE
          value ->> 'calculationStatus' = 'current'
          AND value ->> 'result_kind' = 'value' LOOP
            SELECT
              ORDINALITY::int -1
            INTO
              row_position
            FROM
              jsonb_array_elements_text(grid -> 'rowKeys')
  WITH ORDINALITY
WHERE
  value = result_item ->> 'row_key';
            grid := jsonb_set(grid, ARRAY['rows', row_position::text, column_position::text], result_item -> 'value');
          END LOOP;
      END IF;
    END LOOP;
  grid := grid || jsonb_build_object('fields', fields, 'calculations', artifacts);
  INSERT INTO api.revision_sheet_evidence (workspace_id, revision_id, block_id, instance_id, source_definition_version_id, instance_revision, instance_state, dataset_versions, composed_grid)
    VALUES (revision.workspace_id, revision.id, (item ->> 'blockId')::uuid, (item ->> 'instanceId')::uuid, nullif (item ->> 'sourceDefinitionVersionId', '')::uuid, (item ->> 'instanceRevision')::bigint, item -> 'instanceState', frozen, grid)
  ON CONFLICT (revision_id, block_id)
    DO NOTHING;
END LOOP;
END
$$;
--> statement-breakpoint
ALTER FUNCTION internal.persist_revision_sheet_evidence(p_revision_id uuid) OWNER TO migrator;
--> statement-breakpoint
CREATE FUNCTION internal.pipeline_action_errors(p_actions jsonb) RETURNS jsonb
    LANGUAGE plpgsql IMMUTABLE
    SET search_path TO ''
    AS $_$
DECLARE
  v_catalogue constant jsonb := $catalogue$[{"operation":"insert_block","rpc":"insert_block","label":"Insert a notebook block","description":"Insert a block into a notebook record, after a named block. A step may propose this instead of doing it.","proposalKind":"notebook_block.insert","arguments":[{"name":"p_record_id","type":"uuid","required":true,"nullable":false},{"name":"p_type","type":"text","required":true,"nullable":false},{"name":"p_payload","type":"jsonb","required":true,"nullable":false},{"name":"p_payload_schema_version","type":"integer","required":false,"nullable":false},{"name":"p_after_block_id","type":"uuid","required":false,"nullable":true},{"name":"p_expected_structure_version","type":"integer","required":false,"nullable":false},{"name":"p_before_block_id","type":"uuid","required":false,"nullable":true}]},{"operation":"create_project","rpc":"create_project","label":"Create project","description":"Create a project in the run workspace.","arguments":[{"name":"p_title","type":"text","required":true,"nullable":false}]},{"operation":"create_model_record","rpc":"create_model_record","label":"Create record","description":"Create an experiment, sample, reagent, report or supported model record in a project.","arguments":[{"name":"p_project_id","type":"uuid","required":true,"nullable":false},{"name":"p_kind","type":"text","required":true,"nullable":false},{"name":"p_title","type":"text","required":true,"nullable":false},{"name":"p_status","type":"text","required":false,"nullable":false},{"name":"p_tags","type":"text[]","required":false,"nullable":false},{"name":"p_properties","type":"jsonb","required":false,"nullable":false},{"name":"p_custom_fields","type":"jsonb","required":false,"nullable":false}]},{"operation":"update_record_custom_fields","rpc":"update_record_custom_fields","label":"Update record properties","description":"Update workspace properties using the current record metadata version.","arguments":[{"name":"p_record_id","type":"uuid","required":true,"nullable":false},{"name":"p_expected_metadata_version","type":"integer","required":true,"nullable":false},{"name":"p_values","type":"jsonb","required":true,"nullable":false}]},{"operation":"archive_record","rpc":"archive_record","label":"Archive record","description":"Archive a record using the current metadata version.","arguments":[{"name":"p_record_id","type":"uuid","required":true,"nullable":false},{"name":"p_expected_metadata_version","type":"integer","required":true,"nullable":false}]},{"operation":"restore_record","rpc":"restore_record","label":"Restore record","description":"Restore an archived record using the current metadata version.","arguments":[{"name":"p_record_id","type":"uuid","required":true,"nullable":false},{"name":"p_expected_metadata_version","type":"integer","required":true,"nullable":false}]},{"operation":"create_record_link","rpc":"create_record_link","label":"Link records","description":"Create a link from a source record to a target record in the workspace.","arguments":[{"name":"p_source_record_id","type":"uuid","required":true,"nullable":false},{"name":"p_target_kind","type":"text","required":true,"nullable":false},{"name":"p_target_identifier","type":"text","required":true,"nullable":false},{"name":"p_link_type","type":"text","required":true,"nullable":false},{"name":"p_target_record_id","type":"uuid","required":false,"nullable":true},{"name":"p_label","type":"text","required":false,"nullable":true}]},{"operation":"transfer_sample","rpc":"transfer_sample","label":"Move sample","description":"Record a sample storage transfer with chain-of-custody evidence.","arguments":[{"name":"p_record_id","type":"uuid","required":true,"nullable":false},{"name":"p_expected_metadata_version","type":"integer","required":true,"nullable":false},{"name":"p_to_location","type":"text","required":true,"nullable":false},{"name":"p_notes","type":"text","required":false,"nullable":true}]},{"operation":"receive_sample","rpc":"receive_sample","label":"Receive sample stock","description":"Add sample stock and record the receipt.","arguments":[{"name":"p_record_id","type":"uuid","required":true,"nullable":false},{"name":"p_expected_metadata_version","type":"integer","required":true,"nullable":false},{"name":"p_quantity","type":"numeric","required":true,"nullable":false},{"name":"p_unit","type":"text","required":false,"nullable":true},{"name":"p_location","type":"text","required":false,"nullable":true},{"name":"p_notes","type":"text","required":false,"nullable":true}]},{"operation":"consume_sample","rpc":"consume_sample","label":"Consume sample stock","description":"Reduce sample stock and record its use.","arguments":[{"name":"p_record_id","type":"uuid","required":true,"nullable":false},{"name":"p_expected_metadata_version","type":"integer","required":true,"nullable":false},{"name":"p_quantity","type":"numeric","required":true,"nullable":false},{"name":"p_notes","type":"text","required":false,"nullable":true}]},{"operation":"edit_sample","rpc":"edit_sample","label":"Update sample details","description":"Update sample metadata without bypassing custody operations.","arguments":[{"name":"p_record_id","type":"uuid","required":true,"nullable":false},{"name":"p_expected_metadata_version","type":"integer","required":true,"nullable":false},{"name":"p_title","type":"text","required":true,"nullable":true},{"name":"p_properties","type":"jsonb","required":true,"nullable":true},{"name":"p_tags","type":"text[]","required":true,"nullable":true},{"name":"p_notes","type":"text","required":true,"nullable":true},{"name":"p_custom_fields","type":"jsonb","required":true,"nullable":true}]},{"operation":"archive_sample","rpc":"archive_sample","label":"Archive sample","description":"Archive a sample with custody evidence.","arguments":[{"name":"p_record_id","type":"uuid","required":true,"nullable":false},{"name":"p_expected_metadata_version","type":"integer","required":true,"nullable":false},{"name":"p_notes","type":"text","required":false,"nullable":true}]},{"operation":"restore_sample","rpc":"restore_sample","label":"Restore sample","description":"Restore an archived sample with custody evidence.","arguments":[{"name":"p_record_id","type":"uuid","required":true,"nullable":false},{"name":"p_expected_metadata_version","type":"integer","required":true,"nullable":false},{"name":"p_notes","type":"text","required":false,"nullable":true}]},{"operation":"record_reagent_movement","rpc":"record_reagent_movement","label":"Record reagent movement","description":"Receive, consume or adjust reagent stock through its governed movement operation.","arguments":[{"name":"p_reagent_record_id","type":"uuid","required":true,"nullable":false},{"name":"p_expected_metadata_version","type":"integer","required":true,"nullable":false},{"name":"p_operation","type":"text","required":true,"nullable":false},{"name":"p_quantity_delta","type":"numeric","required":false,"nullable":false},{"name":"p_reason","type":"text","required":false,"nullable":true}]},{"operation":"commit_dataset_row_batch","rpc":"commit_dataset_row_batch","label":"Commit dataset rows","description":"Commit a validated row batch at the expected dataset revision.","arguments":[{"name":"p_dataset_id","type":"uuid","required":true,"nullable":false},{"name":"p_expected_dataset_revision","type":"bigint","required":true,"nullable":false},{"name":"p_rows","type":"jsonb","required":true,"nullable":false},{"name":"p_idempotency_key","type":"text","required":true,"nullable":false,"server":"idempotency"}]},{"operation":"snapshot_dataset","rpc":"snapshot_dataset","label":"Snapshot dataset","description":"Create an immutable dataset version with a label.","arguments":[{"name":"p_dataset_id","type":"uuid","required":true,"nullable":false},{"name":"p_expected_dataset_revision","type":"bigint","required":true,"nullable":false},{"name":"p_label","type":"text","required":true,"nullable":false}]},{"operation":"archive_dataset","rpc":"archive_dataset","label":"Archive dataset","description":"Archive a dataset through dependency and revision checks.","arguments":[{"name":"p_dataset_id","type":"uuid","required":true,"nullable":false},{"name":"p_expected_revision","type":"bigint","required":true,"nullable":false}]},{"operation":"restore_dataset","rpc":"restore_dataset","label":"Restore dataset","description":"Restore an archived dataset at the expected revision.","arguments":[{"name":"p_dataset_id","type":"uuid","required":true,"nullable":false},{"name":"p_expected_revision","type":"bigint","required":true,"nullable":false}]}]$catalogue$::jsonb;
  v_errors jsonb := '[]'::jsonb;
  v_action jsonb; v_definition jsonb; v_argument jsonb; v_key text;
  v_names text[] := '{}';
BEGIN
  IF jsonb_typeof(p_actions) IS DISTINCT FROM 'array' THEN
    RETURN '[{"code":"invalid_shape","field":"actions","message":"actions must be an array"}]'::jsonb;
  END IF;
  IF jsonb_array_length(p_actions) > 20 THEN
    RETURN '[{"code":"too_many","field":"actions","message":"At most twenty ELN actions are allowed."}]'::jsonb;
  END IF;
  FOR v_action IN SELECT value FROM jsonb_array_elements(p_actions) LOOP
    IF jsonb_typeof(v_action) IS DISTINCT FROM 'object'
      OR coalesce(v_action->>'name','') !~ '^[a-z][a-z0-9_]{0,47}$'
      OR v_action->>'name' = ANY(v_names)
      OR v_action->>'name' IN ('constructor','prototype') THEN
      v_errors := v_errors || '[{"code":"invalid_value","field":"actions","message":"Each action needs a unique lowercase name."}]'::jsonb;
      CONTINUE;
    END IF;
    v_names := array_append(v_names, v_action->>'name');
    SELECT value INTO v_definition FROM jsonb_array_elements(v_catalogue) WHERE value->>'operation' = v_action->>'operation';
    IF v_definition IS NULL THEN
      v_errors := v_errors || '[{"code":"invalid_value","field":"actions","message":"Unsupported ELN action."}]'::jsonb;
      CONTINUE;
    END IF;
    IF v_action ? 'mode' AND v_action->>'mode' NOT IN ('execute','propose') THEN
      v_errors := v_errors || '[{"code":"invalid_value","field":"actions","message":"unknown action mode"}]'::jsonb;
      CONTINUE;
    END IF;
    IF jsonb_typeof(v_action->'arguments') IS DISTINCT FROM 'object' THEN
      v_errors := v_errors || '[{"code":"invalid_shape","field":"actions","message":"Action inputs must be an object."}]'::jsonb;
      CONTINUE;
    END IF;
    FOR v_key IN SELECT jsonb_object_keys(v_action->'arguments') LOOP
      IF NOT EXISTS (SELECT 1 FROM jsonb_array_elements(v_definition->'arguments') arg WHERE arg->>'name' = v_key AND NOT arg ? 'server') THEN
        v_errors := v_errors || jsonb_build_array(jsonb_build_object('code','invalid_value','field','actions','message','This action input is not editable: ' || v_key));
      END IF;
    END LOOP;
    FOR v_argument IN SELECT value FROM jsonb_array_elements(v_definition->'arguments') LOOP
      IF v_argument->'required' = 'true'::jsonb AND NOT v_argument ? 'server' AND NOT (v_action->'arguments') ? (v_argument->>'name') THEN
        v_errors := v_errors || jsonb_build_array(jsonb_build_object('code','missing_required','field','actions','message','Required action input: ' || (v_argument->>'name')));
      END IF;
    END LOOP;
  END LOOP;
  RETURN v_errors;
END $_$;
