CREATE FUNCTION internal.pipeline_run_job_is_live(p_run_id uuid) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  SELECT EXISTS (
    SELECT 1 FROM internal.pipeline_run_jobs j
     WHERE j.run_id = p_run_id
       AND (
         (j.state = 'queued' AND j.enqueued_at > clock_timestamp() - interval '1 hour')
         OR (j.state = 'claimed' AND j.lease_expires_at > clock_timestamp())
       )
  )
$$;
