CREATE FUNCTION internal.render_scientific_check(p_check jsonb, p_field text) RETURNS text
    LANGUAGE plpgsql IMMUTABLE
    SET search_path TO ''
    AS $$
BEGIN
 RETURN CASE p_check->>'kind'
  WHEN 'finite' THEN format('%I <> %L::numeric AND %I <> %L::numeric AND %I <> %L::numeric',p_field,'NaN',p_field,'Infinity',p_field,'-Infinity')
  WHEN 'minLength' THEN format('length(%I) >= %L::integer',p_field,p_check->>'value')
  WHEN 'maxLength' THEN format('length(%I) <= %L::integer',p_field,p_check->>'value')
  WHEN 'regex' THEN format('%I ~ %L',p_field,p_check->>'value')
  WHEN 'min' THEN format('%I >= %L::numeric',p_field,p_check->>'value')
  WHEN 'max' THEN format('%I <= %L::numeric',p_field,p_check->>'value')
  WHEN 'exclusiveMin' THEN format('%I > %L::numeric',p_field,p_check->>'value')
  WHEN 'exclusiveMax' THEN format('%I < %L::numeric',p_field,p_check->>'value')
  WHEN 'earliest' THEN format('%I >= %L::%s',p_field,p_check->>'value',CASE p_check->>'type' WHEN 'date' THEN 'date' ELSE 'timestamptz' END)
  WHEN 'latest' THEN format('%I <= %L::%s',p_field,p_check->>'value',CASE p_check->>'type' WHEN 'date' THEN 'date' ELSE 'timestamptz' END)
  ELSE NULL END;
END $$;
--> statement-breakpoint
ALTER FUNCTION internal.render_scientific_check(p_check jsonb, p_field text) OWNER TO migrator;
--> statement-breakpoint
CREATE FUNCTION internal.replace_dataset_schema_version_fields(p_schema_version_id uuid, p_fields jsonb) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $_$
DECLARE
  item jsonb;
  ordinal integer := 0;
  field_key text;
  field_label text;
  logical_type text;
  field_id uuid;
  display_order integer;
BEGIN
  IF jsonb_typeof(p_fields) IS DISTINCT FROM 'array' THEN
    RAISE EXCEPTION 'Dataset Schema fields must be an array' USING ERRCODE = '22023';
  END IF;
  DELETE FROM api.dataset_schema_version_fields WHERE schema_version_id = p_schema_version_id;
  FOR item IN SELECT value FROM jsonb_array_elements(p_fields) LOOP
    ordinal := ordinal + 1;
    IF jsonb_typeof(item) IS DISTINCT FROM 'object' THEN
      RAISE EXCEPTION 'invalid Dataset Schema field' USING ERRCODE = '22023';
    END IF;
    field_key := coalesce(item->>'key', item->>'field_key');
    field_label := coalesce(item->>'label', item->>'name');
    logical_type := coalesce(item->>'logical_type', item->>'logicalType');
    IF field_key IS NULL OR field_key !~ '^[a-z][a-z0-9_]{0,59}$'
      OR field_label IS NULL OR length(btrim(field_label)) NOT BETWEEN 1 AND 200
      OR logical_type IS NULL THEN
      RAISE EXCEPTION 'invalid Dataset Schema field metadata' USING ERRCODE = 'SB071';
    END IF;
    BEGIN
      field_id := coalesce(nullif(item->>'field_id','')::uuid, nullif(item->>'fieldId','')::uuid, gen_random_uuid());
    EXCEPTION WHEN invalid_text_representation THEN
      RAISE EXCEPTION 'invalid Dataset Schema field id' USING ERRCODE = '22023';
    END;
    display_order := coalesce((item->>'display_order')::integer, (item->>'displayOrder')::integer, ordinal);
    INSERT INTO api.dataset_schema_version_fields(
      schema_version_id, field_id, key, label, description, logical_type, nullable,
      default_value, quantity, validation, category, relationship, cardinality, lifecycle, display_order
    ) VALUES (
      p_schema_version_id, field_id, field_key, btrim(field_label),
      nullif(btrim(coalesce(item->>'description','')), ''), logical_type,
      coalesce((item->>'nullable')::boolean, true),
      nullif(CASE WHEN item ? 'default_value' THEN item->'default_value' ELSE item->'defaultValue' END, 'null'::jsonb),
      nullif(item->'quantity', 'null'::jsonb),
      coalesce(nullif(item->'validation', 'null'::jsonb), '{}'::jsonb),
      nullif(item->'category', 'null'::jsonb), nullif(item->'relationship', 'null'::jsonb),
      coalesce(item->>'cardinality', 'one'), coalesce(item->>'lifecycle', 'active'), display_order
    );
  END LOOP;
END $_$;
--> statement-breakpoint
ALTER FUNCTION internal.replace_dataset_schema_version_fields(p_schema_version_id uuid, p_fields jsonb) OWNER TO migrator;
--> statement-breakpoint
CREATE FUNCTION internal.replay_configuration_change(p_workspace_id uuid, p_actor_user_id text, p_kind text, p_idempotency_key text, p_request_digest text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
  existing api.configuration_change_log;
BEGIN
  IF p_idempotency_key IS NULL OR length(p_idempotency_key) NOT BETWEEN 1 AND 128 THEN
    RAISE EXCEPTION 'valid idempotency key is required' USING ERRCODE = '22023';
  END IF;
  SELECT * INTO existing
    FROM api.configuration_change_log
   WHERE workspace_id = p_workspace_id
     AND actor_user_id = p_actor_user_id
     AND kind = p_kind
     AND idempotency_key = p_idempotency_key;
  IF existing.id IS NULL THEN
    RETURN NULL;
  END IF;
  IF existing.request_digest IS DISTINCT FROM p_request_digest THEN
    RAISE EXCEPTION 'idempotency key was used for a different configuration request'
      USING ERRCODE = '23505';
  END IF;
  RETURN existing.result || jsonb_build_object('idempotent', true);
END;
$$;
