CREATE FUNCTION internal.require_schema_publish_for_lifecycle() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
  workspace uuid;
  v_mask text;
BEGIN
  IF session_user = 'migrator' THEN
    v_mask := nullif(btrim(current_setting('sheetbase.capability_mask', true)), '');
    IF v_mask IS NULL THEN
      RETURN NEW;
    END IF;
  END IF;
  IF TG_TABLE_NAME = 'dataset_schema_versions' THEN
    SELECT s.workspace_id INTO workspace
      FROM api.dataset_schema_definitions s WHERE s.id = NEW.schema_id;
    IF TG_OP = 'INSERT' AND NEW.lifecycle IS DISTINCT FROM 'draft' THEN
      IF NOT api.has_capability(workspace, 'schema.publish') THEN
        RAISE EXCEPTION 'capability required: schema.publish' USING ERRCODE = '42501';
      END IF;
    ELSIF TG_OP = 'UPDATE'
          AND OLD.lifecycle = 'draft'
          AND NEW.lifecycle IS DISTINCT FROM OLD.lifecycle THEN
      IF NOT api.has_capability(workspace, 'schema.publish') THEN
        RAISE EXCEPTION 'capability required: schema.publish' USING ERRCODE = '42501';
      END IF;
    END IF;
  ELSIF TG_TABLE_NAME = 'dataset_schema_definitions' THEN
    workspace := NEW.workspace_id;
    IF TG_OP = 'INSERT' AND NEW.lifecycle IS DISTINCT FROM 'draft' THEN
      IF NOT api.has_capability(workspace, 'schema.publish') THEN
        RAISE EXCEPTION 'capability required: schema.publish' USING ERRCODE = '42501';
      END IF;
    ELSIF TG_OP = 'UPDATE'
          AND OLD.lifecycle = 'draft'
          AND NEW.lifecycle = 'active' THEN
      IF NOT api.has_capability(workspace, 'schema.publish') THEN
        RAISE EXCEPTION 'capability required: schema.publish' USING ERRCODE = '42501';
      END IF;
    END IF;
  END IF;
  RETURN NEW;
END;
$$;
--> statement-breakpoint
ALTER FUNCTION internal.require_schema_publish_for_lifecycle() OWNER TO migrator;
--> statement-breakpoint
CREATE FUNCTION internal.resolve_approved_parser_failure() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
BEGIN
  IF NEW.status = 'approved' AND OLD.status IS DISTINCT FROM NEW.status AND NEW.test_result->>'ok' = 'true' THEN
    UPDATE api.dataset_import_files f SET parser_failure = NULL, updated_at = now()
      WHERE f.id::text = NEW.test_result->>'fileId' AND f.workspace_id = NEW.workspace_id
        AND f.checksum = NEW.test_result->>'checksum' AND f.parser_failure IS NOT NULL
        AND (f.parser_failure->>'parserVersionId' IS NULL OR EXISTS (SELECT 1 FROM api.parser_versions previous
          WHERE previous.id::text = f.parser_failure->>'parserVersionId' AND previous.parser_id = NEW.parser_id
            AND previous.workspace_id = NEW.workspace_id));
  END IF;
  RETURN NEW;
END $$;
