CREATE FUNCTION internal.retain_revision_files() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $_$
DECLARE
  evidence jsonb;
  evidence_file_id uuid;
  evidence_record_id uuid;
  file_object api.file_objects;
BEGIN
  IF jsonb_typeof(NEW.canonical_snapshot->'files') IS DISTINCT FROM 'array' THEN
    RAISE EXCEPTION 'revision files must be a canonical array'
      USING ERRCODE = '22023';
  END IF;

  FOR evidence IN
    SELECT value FROM jsonb_array_elements(NEW.canonical_snapshot->'files')
  LOOP
    BEGIN
      evidence_file_id := (evidence->>'id')::uuid;
      evidence_record_id := (evidence->>'recordId')::uuid;
    EXCEPTION WHEN invalid_text_representation THEN
      RAISE EXCEPTION 'revision file identity is invalid' USING ERRCODE = '22023';
    END;

    SELECT * INTO file_object FROM api.file_objects
    WHERE id = evidence_file_id
    FOR UPDATE;

    IF file_object.id IS NULL
       OR file_object.workspace_id <> NEW.workspace_id
       OR file_object.record_id <> evidence_record_id
       OR file_object.storage_key IS DISTINCT FROM evidence->>'storageKey'
       OR file_object.storage_backend IS DISTINCT FROM evidence->>'storageBackend'
       OR file_object.checksum_algorithm IS DISTINCT FROM evidence->>'checksumAlgorithm'
       OR file_object.checksum IS NULL
       OR file_object.checksum !~ '^[0-9a-f]{64}$'
       OR file_object.checksum IS DISTINCT FROM evidence->>'checksum'
       OR file_object.byte_size IS DISTINCT FROM (evidence->>'byteSize')::bigint
       OR file_object.display_name IS DISTINCT FROM evidence->>'displayName'
       OR file_object.media_type IS DISTINCT FROM evidence->>'mediaType'
       OR file_object.status IS DISTINCT FROM evidence->>'status'
       OR file_object.status NOT IN ('active', 'quarantined') THEN
      RAISE EXCEPTION 'submitted file changed or has no retained bytes'
        USING ERRCODE = 'SB001';
    END IF;

    INSERT INTO internal.revision_file_objects (
      revision_id, file_object_id, workspace_id, file_record_id, storage_key,
      storage_backend, checksum_algorithm, checksum, byte_size, created_at
    ) VALUES (
      NEW.id, file_object.id, NEW.workspace_id, file_object.record_id,
      file_object.storage_key, file_object.storage_backend,
      file_object.checksum_algorithm, file_object.checksum,
      file_object.byte_size, NEW.created_at
    );
  END LOOP;
  RETURN NEW;
END;
$_$;
--> statement-breakpoint
ALTER FUNCTION internal.retain_revision_files() OWNER TO migrator;
--> statement-breakpoint
CREATE FUNCTION internal.retire_scientific_column_impl(p_column_id uuid, p_expected_schema_version integer, p_confirmation_hash text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$ DECLARE c api.scientific_columns; t api.scientific_tables; n bigint; formulas bigint; fingerprint text; h text; evidence jsonb; BEGIN SELECT * INTO t FROM api.scientific_tables WHERE id=(SELECT table_id FROM api.scientific_columns WHERE id=p_column_id) FOR UPDATE; IF t.id IS NULL THEN RAISE EXCEPTION 'column not found' USING ERRCODE='P0002'; END IF; SELECT * INTO c FROM api.scientific_columns WHERE id=p_column_id FOR UPDATE; IF c.id IS NULL OR c.lifecycle<>'active' OR t.lifecycle<>'active' THEN RAISE EXCEPTION 'active column required' USING ERRCODE='22023'; END IF; PERFORM internal.assert_scientific_actor(t.workspace_id); IF t.schema_version<>p_expected_schema_version THEN RAISE EXCEPTION 'schema version mismatch' USING ERRCODE='SB001'; END IF; EXECUTE format('LOCK TABLE api.%I IN ACCESS EXCLUSIVE MODE',t.resource_name); EXECUTE format('SELECT count(*) FILTER (WHERE %I IS NOT NULL),count(*) FILTER (WHERE %L::uuid=ANY(formula_column_ids)),md5(coalesce(jsonb_agg(to_jsonb(%I) ORDER BY id)::text,%L)) FROM api.%I',c.field_name,c.id,c.field_name,'[]',t.resource_name) INTO n,formulas,fingerprint; evidence:=jsonb_build_object('tableId',t.id,'columnId',c.id,'schemaVersion',t.schema_version,'nonNullRows',n,'formulaMarkers',formulas); h:=md5(evidence::text||fingerprint); IF p_confirmation_hash IS NULL THEN RETURN evidence||jsonb_build_object('requiresConfirmation',true,'hash',h); END IF; IF p_confirmation_hash IS DISTINCT FROM h THEN RAISE EXCEPTION 'retirement evidence changed' USING ERRCODE='23514'; END IF; UPDATE api.scientific_columns SET lifecycle='retired',updated_at=now() WHERE id=c.id; EXECUTE format('REVOKE INSERT (%I), UPDATE (%I) ON api.%I FROM authenticated',c.field_name,c.field_name,t.resource_name); UPDATE api.scientific_tables SET schema_version=schema_version+1,updated_at=now() WHERE id=t.id; PERFORM internal.emit_change_event(t.workspace_id,'scientific_table',t.id,'update',t.record_id,NULL,jsonb_build_object('operation','retire_column','columnIds',jsonb_build_array(c.id),'schemaVersion',t.schema_version+1)); PERFORM pg_notify('pgrst','reload schema'); RETURN jsonb_build_object('retired',true,'schemaVersion',t.schema_version+1); END $$;
