CREATE FUNCTION internal.revoke_extension_credential(p_workspace_id uuid, p_extension_id uuid, p_extension_key text, p_credential_id uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
BEGIN
  IF p_credential_id IS NULL THEN
    RETURN;
  END IF;
  UPDATE internal.api_credentials SET revoked_at = now()
   WHERE id = p_credential_id AND revoked_at IS NULL;
  IF FOUND THEN
    PERFORM internal.emit_change_event_as_actor(
      api.current_user_id(),
      p_workspace_id,
      'api_credential',
      p_credential_id,
      'revoke',
      NULL,
      NULL,
      jsonb_build_object(
        'extension_id', p_extension_id::text,
        'extensionKey', p_extension_key
      )
    );
  END IF;
END;
$$;
