CREATE FUNCTION internal.sample_hold_deadline(p_properties jsonb, p_created_at timestamp with time zone) RETURNS timestamp with time zone
    LANGUAGE sql IMMUTABLE
    SET search_path TO ''
    AS $$
  SELECT CASE
    WHEN NULLIF(p_properties ->> 'holdUntil', '') IS NOT NULL
      THEN (p_properties ->> 'holdUntil')::timestamptz
    ELSE COALESCE(
           NULLIF(p_properties ->> 'holdStartedAt', '')::timestamptz,
           p_created_at
         ) + (
           COALESCE(NULLIF(p_properties ->> 'holdDurationDays', ''), '0')
           || ' days'
         )::interval
  END
$$;
