CREATE FUNCTION internal.scientific_row_event() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE t api.scientific_tables; rid uuid; ver bigint; changed jsonb; actor text;
BEGIN
 SELECT * INTO t FROM api.scientific_tables WHERE resource_name=TG_TABLE_NAME;
 rid:=CASE WHEN TG_OP='DELETE' THEN OLD.id ELSE NEW.id END; ver:=CASE WHEN TG_OP='DELETE' THEN OLD.version ELSE NEW.version END;
 IF TG_OP='UPDATE' THEN SELECT COALESCE(jsonb_agg(c.id),'[]') INTO changed FROM api.scientific_columns c WHERE c.table_id=t.id AND to_jsonb(OLD)->c.field_name IS DISTINCT FROM to_jsonb(NEW)->c.field_name; ELSE SELECT COALESCE(jsonb_agg(c.id),'[]') INTO changed FROM api.scientific_columns c WHERE c.table_id=t.id AND (CASE WHEN TG_OP='DELETE' THEN to_jsonb(OLD) ELSE to_jsonb(NEW) END)->c.field_name <> 'null'::jsonb; END IF;
 SELECT x.actor_user_id INTO actor FROM internal.formula_row_capability x WHERE x.tx=txid_current() AND x.table_id=t.id AND x.row_id=rid;
 IF actor IS NULL THEN
   PERFORM internal.emit_change_event(t.workspace_id,'scientific_row',rid,CASE TG_OP WHEN 'INSERT' THEN 'create' WHEN 'UPDATE' THEN 'update' ELSE 'delete' END,t.record_id,NULL,jsonb_build_object(
    'tableId',t.id,'rowId',rid,'version',ver,'changedColumnIds',changed,
    'inputRevision',(SELECT calculation_input_revision FROM api.records WHERE id=t.record_id),
    'changes',coalesce((SELECT jsonb_object_agg(c.id,jsonb_build_object('label',c.label,'columnId',c.id,
      'from',CASE WHEN TG_OP<>'INSERT' THEN to_jsonb(OLD)->c.field_name ELSE 'null'::jsonb END,
      'to',CASE WHEN TG_OP<>'DELETE' THEN to_jsonb(NEW)->c.field_name ELSE 'null'::jsonb END))
      FROM api.scientific_columns c WHERE c.table_id=t.id AND c.id IN
        (SELECT value::text::uuid FROM jsonb_array_elements_text(changed))),'{}'::jsonb)));
 ELSE
   PERFORM internal.emit_change_event_as_actor(actor,t.workspace_id,'scientific_row',rid,CASE TG_OP WHEN 'INSERT' THEN 'create' WHEN 'UPDATE' THEN 'update' ELSE 'delete' END,t.record_id,NULL,jsonb_build_object(
    'tableId',t.id,'rowId',rid,'version',ver,'changedColumnIds',changed,
    'inputRevision',(SELECT calculation_input_revision FROM api.records WHERE id=t.record_id),
    'changes',coalesce((SELECT jsonb_object_agg(c.id,jsonb_build_object('label',c.label,'columnId',c.id,
      'from',CASE WHEN TG_OP<>'INSERT' THEN to_jsonb(OLD)->c.field_name ELSE 'null'::jsonb END,
      'to',CASE WHEN TG_OP<>'DELETE' THEN to_jsonb(NEW)->c.field_name ELSE 'null'::jsonb END))
      FROM api.scientific_columns c WHERE c.table_id=t.id AND c.id IN
        (SELECT value::text::uuid FROM jsonb_array_elements_text(changed))),'{}'::jsonb)));
 END IF;
 RETURN NULL;
END $$;
