 IF TG_OP='INSERT' OR NEW.schema_version IS DISTINCT FROM OLD.schema_version THEN
   UPDATE api.records SET calculation_input_revision=calculation_input_revision+1 WHERE id=NEW.record_id;
 END IF;
 RETURN NEW;
END $$;
