CREATE FUNCTION internal.set_updated_at() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
BEGIN
  IF to_jsonb(OLD) ? 'search_tsv'
     AND (to_jsonb(OLD) - 'search_tsv') IS NOT DISTINCT FROM (to_jsonb(NEW) - 'search_tsv') THEN
    NEW."updated_at" := OLD."updated_at";
  ELSE
    NEW."updated_at" := now();
  END IF;
  RETURN NEW;
END;
$$;
