CREATE FUNCTION internal.sheet_definition_date_matches(p_value text) RETURNS boolean
    LANGUAGE plpgsql IMMUTABLE
    SET search_path TO ''
    AS $_$
DECLARE parts text[]; year integer; month integer; day integer; max_day integer;
BEGIN
  parts:=regexp_match(p_value,'^([0-9]{4})-([0-9]{2})-([0-9]{2})$');
  IF parts IS NULL THEN RETURN false; END IF;
  year:=parts[1]::integer; month:=parts[2]::integer; day:=parts[3]::integer;
  IF year<1 OR month NOT BETWEEN 1 AND 12 OR day<1 THEN RETURN false; END IF;
  max_day:=CASE month WHEN 2 THEN CASE WHEN year%4=0 AND (year%100<>0 OR year%400=0) THEN 29 ELSE 28 END WHEN 4 THEN 30 WHEN 6 THEN 30 WHEN 9 THEN 30 WHEN 11 THEN 30 ELSE 31 END;
  RETURN day<=max_day;
END $_$;
--> statement-breakpoint
ALTER FUNCTION internal.sheet_definition_date_matches(p_value text) OWNER TO migrator;
--> statement-breakpoint
CREATE FUNCTION internal.sheet_definition_scalar_matches(p_type text, p_value jsonb) RETURNS boolean
    LANGUAGE plpgsql IMMUTABLE
    SET search_path TO ''
    AS $$
DECLARE value_text text;
BEGIN
  IF p_value IS NULL THEN RETURN false; END IF;
  value_text:=p_value#>>'{}';
  IF p_type='text' THEN RETURN jsonb_typeof(p_value)='string';
  ELSIF p_type='integer' THEN
    RETURN jsonb_typeof(p_value)='number' AND value_text::numeric=trunc(value_text::numeric)
      AND value_text::numeric BETWEEN -9007199254740991 AND 9007199254740991;
  ELSIF p_type='decimal' THEN
    IF jsonb_typeof(p_value)<>'number' THEN RETURN false; END IF;
    PERFORM value_text::double precision; RETURN true;
  ELSIF p_type='boolean' THEN RETURN jsonb_typeof(p_value)='boolean';
  ELSIF p_type='date' THEN
    RETURN jsonb_typeof(p_value)='string' AND internal.sheet_definition_date_matches(value_text);
  ELSIF p_type='timestamp' THEN
    RETURN jsonb_typeof(p_value)='string' AND internal.sheet_definition_timestamp_matches(value_text);
  ELSIF p_type IN ('category','reference') THEN
    IF jsonb_typeof(p_value)<>'string' THEN RETURN false; END IF;
    PERFORM internal.sheet_definition_uuid(value_text,'scalar'); RETURN true;
  END IF;
  RETURN false;
EXCEPTION WHEN others THEN RETURN false;
END $$;
--> statement-breakpoint
ALTER FUNCTION internal.sheet_definition_scalar_matches(p_type text, p_value jsonb) OWNER TO migrator;
--> statement-breakpoint
CREATE FUNCTION internal.sheet_definition_timestamp_matches(p_value text) RETURNS boolean
    LANGUAGE plpgsql IMMUTABLE
    SET search_path TO ''
    AS $_$
DECLARE parts text[];
BEGIN
  parts:=regexp_match(p_value,'^([0-9]{4})-([0-9]{2})-([0-9]{2})T([0-9]{2}):([0-9]{2}):([0-9]{2})(\.[0-9]+)?(Z|[+-]([0-9]{2}):([0-9]{2}))$');
  IF parts IS NULL OR NOT internal.sheet_definition_date_matches(parts[1]||'-'||parts[2]||'-'||parts[3]) THEN RETURN false; END IF;
  RETURN parts[4]::integer<=23 AND parts[5]::integer<=59 AND parts[6]::integer<=59
    AND (parts[8]='Z' OR (parts[9]::integer<=23 AND parts[10]::integer<=59));
END $_$;
--> statement-breakpoint
ALTER FUNCTION internal.sheet_definition_timestamp_matches(p_value text) OWNER TO migrator;
--> statement-breakpoint
CREATE FUNCTION internal.sheet_definition_upgrade_columns_compatible(p_source jsonb, p_target jsonb) RETURNS boolean
    LANGUAGE sql IMMUTABLE
    SET search_path TO ''
    AS $$
  SELECT p_source->'source'->>'kind'=p_target->'source'->>'kind'
    AND ((p_source->'field')-ARRAY['fieldId','key','label','description']::text[])
      IS NOT DISTINCT FROM ((p_target->'field')-ARRAY['fieldId','key','label','description']::text[])
    AND CASE p_source->'source'->>'kind'
      WHEN 'bound' THEN p_source->'source'->>'bindingId'=p_target->'source'->>'bindingId'
        AND p_source->'source'->>'sourceFieldId'=p_target->'source'->>'sourceFieldId'
      WHEN 'calculated' THEN p_source->'source'->>'calculationId'=p_target->'source'->>'calculationId'
      ELSE true
    END
$$;
