CREATE FUNCTION internal.sources_readable(p_payload jsonb) RETURNS boolean
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $_$
DECLARE reference jsonb; kind text; id uuid;
BEGIN
  IF p_payload IS NULL THEN RETURN true; END IF;
  FOR reference IN SELECT value FROM jsonb_path_query(p_payload,'strict $.** ? (@.type() == "object").keyvalue() ? (@.key == "datasetId" || @.key == "dataset_id" || @.key == "recordId" || @.key == "record_id" || @.key == "datasetVersionId" || @.key == "dataset_version_id")') value LOOP
    IF reference->'value'='null'::jsonb THEN CONTINUE; END IF;
    IF reference->>'value' !~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' THEN RETURN false; END IF;
    id:=(reference->>'value')::uuid;
    kind:=CASE WHEN reference->>'key' IN ('datasetId','dataset_id') THEN 'dataset' WHEN reference->>'key' IN ('recordId','record_id') THEN 'record' ELSE 'dataset_version' END;
    IF NOT internal.can_access_object(kind,id,'view') THEN RETURN false; END IF;
  END LOOP;
  RETURN true;
END $_$;
--> statement-breakpoint
ALTER FUNCTION internal.sources_readable(p_payload jsonb) OWNER TO migrator;
--> statement-breakpoint
CREATE FUNCTION internal.sync_booking_record_link() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
  v_experiment api.records;
  v_identifier text;
  v_actor text;
  v_live boolean;
BEGIN
  -- Remove the link this booking held on the experiment it no longer names.
  IF TG_OP IN ('UPDATE', 'DELETE')
     AND OLD.linked_experiment_record_id IS NOT NULL
     AND (TG_OP = 'DELETE'
          OR OLD.linked_experiment_record_id IS DISTINCT FROM NEW.linked_experiment_record_id
          OR (OLD.cancelled_at IS NULL AND NEW.cancelled_at IS NOT NULL)) THEN
    DELETE FROM api.record_links l
     USING api.records x
     WHERE x.id = OLD.linked_experiment_record_id
       AND x.locked_at IS NULL
       AND l.source_record_id = x.id
       AND l.link_type = 'booking'
       AND l.link_metadata ->> 'bookingId' = OLD.id::text;
  END IF;

  IF TG_OP = 'DELETE' THEN RETURN OLD; END IF;

  v_live := NEW.cancelled_at IS NULL AND NEW.linked_experiment_record_id IS NOT NULL;
  IF NOT v_live THEN RETURN NEW; END IF;

  SELECT * INTO v_experiment FROM api.records
   WHERE id = NEW.linked_experiment_record_id
     AND kind = 'experiment' AND deleted_at IS NULL
     AND workspace_id = NEW.workspace_id;
  IF v_experiment.id IS NULL OR v_experiment.locked_at IS NOT NULL THEN
    RETURN NEW;
  END IF;

  v_identifier := coalesce(NEW.display_id, NEW.id::text);
  v_actor := coalesce(NEW.updated_by_user_id, NEW.created_by_user_id, api.current_user_id());
  IF v_actor IS NULL OR NOT EXISTS (SELECT 1 FROM internal."user" u WHERE u.id = v_actor) THEN
    RETURN NEW;
  END IF;

  BEGIN
    INSERT INTO api.record_links
      (source_record_id, target_record_id, target_kind, target_identifier, link_type,
       link_metadata, created_by_user_id)
    VALUES (v_experiment.id, NULL, 'booking', v_identifier, 'booking',
            jsonb_build_object('origin', 'calendar_bookings', 'bookingId', NEW.id,
                               'resourceId', NEW.resource_id, 'title', NEW.title,
                               'startsAt', NEW.starts_at, 'endsAt', NEW.ends_at),
            v_actor)
    ON CONFLICT (source_record_id, target_identifier, link_type)
    DO UPDATE SET link_metadata = EXCLUDED.link_metadata;
  EXCEPTION WHEN SQLSTATE 'SB080' OR SQLSTATE 'SB081' THEN
    RAISE WARNING 'booking % not linked to experiment %: %', v_identifier, v_experiment.identifier, SQLERRM;
  END;
  RETURN NEW;
END;
$$;
--> statement-breakpoint
ALTER FUNCTION internal.sync_booking_record_link() OWNER TO migrator;
--> statement-breakpoint
CREATE FUNCTION internal.sync_dataset_cell_search() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
  v_dataset_id uuid;
  v_workspace_id uuid;
  v_label text;
  v_category jsonb;
  v_text text;
BEGIN
  IF TG_OP = 'DELETE' THEN
    DELETE FROM api.dataset_cell_search
    WHERE dataset_version_id = OLD.dataset_version_id
      AND row_id = OLD.row_id
      AND field_id = OLD.field_id
      AND ordinal = OLD.ordinal;
    RETURN OLD;
  END IF;

  SELECT dv.dataset_id, dv.workspace_id, f.label, f.category
    INTO v_dataset_id, v_workspace_id, v_label, v_category
  FROM api.dataset_versions dv
  JOIN api.dataset_schema_version_fields f
    ON f.schema_version_id = dv.schema_version_id
   AND f.field_id = NEW.field_id
  WHERE dv.id = NEW.dataset_version_id;

  v_text := CASE
    WHEN NEW.text_value IS NOT NULL THEN NEW.text_value
    WHEN NEW.integer_value IS NOT NULL THEN NEW.integer_value::text
    WHEN NEW.numeric_value IS NOT NULL THEN NEW.numeric_value::text
    WHEN NEW.boolean_value IS NOT NULL THEN NEW.boolean_value::text
    WHEN NEW.date_value IS NOT NULL THEN NEW.date_value::text
    WHEN NEW.timestamp_value IS NOT NULL THEN NEW.timestamp_value::text
    WHEN NEW.category_option_id IS NOT NULL THEN coalesce(
      (SELECT opt->>'label'
         FROM jsonb_array_elements(coalesce(v_category, '[]'::jsonb)) opt
        WHERE opt->>'id' = NEW.category_option_id::text
        LIMIT 1),
      NEW.category_option_id::text)
    WHEN NEW.reference_id IS NOT NULL THEN coalesce(
      (SELECT r.identifier FROM api.records r WHERE r.id = NEW.reference_id),
      NEW.reference_id::text)
    ELSE ''
  END;

  IF TG_OP = 'UPDATE' THEN
    DELETE FROM api.dataset_cell_search
    WHERE dataset_version_id = OLD.dataset_version_id
      AND row_id = OLD.row_id
      AND field_id = OLD.field_id
      AND ordinal = OLD.ordinal;
  END IF;

  INSERT INTO api.dataset_cell_search(
    dataset_version_id, row_id, field_id, ordinal,
    dataset_id, workspace_id, field_label, value_text
  )
  VALUES (
    NEW.dataset_version_id, NEW.row_id, NEW.field_id, NEW.ordinal,
    v_dataset_id, v_workspace_id, coalesce(v_label, ''), coalesce(v_text, '')
  )
  ON CONFLICT (dataset_version_id, row_id, field_id, ordinal) DO UPDATE
    SET field_label = EXCLUDED.field_label,
        value_text = EXCLUDED.value_text,
        dataset_id = EXCLUDED.dataset_id,
        workspace_id = EXCLUDED.workspace_id;
  RETURN NEW;
END $$;
--> statement-breakpoint
ALTER FUNCTION internal.sync_dataset_cell_search() OWNER TO migrator;
--> statement-breakpoint
CREATE FUNCTION internal.sync_dataset_value_system_flags(p_dataset_id uuid, p_row_id uuid, p_schema_version_id uuid, p_provided jsonb) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
  field api.dataset_schema_version_fields;
  rule jsonb;
  effective jsonb;
  v_num numeric;
  lo numeric;
  hi numeric;
  violated boolean;
  v_reason text;
  workspace uuid;
  has_value boolean;
  unit_text text;
BEGIN
  SELECT d.workspace_id INTO workspace FROM api.datasets d
    WHERE d.id = p_dataset_id AND d.workspace_id = api.current_workspace_id()
      AND api.is_workspace_writer(d.workspace_id) AND api.has_write_actor();
  IF workspace IS NULL THEN RETURN; END IF;
  FOR field IN
    SELECT * FROM api.dataset_schema_version_fields f
    WHERE f.schema_version_id = p_schema_version_id AND f.lifecycle = 'active'
    ORDER BY f.display_order
  LOOP
    -- out_of_range: exactly the existing soft min/max rule, now with provenance.
    rule := field.validation #> '{extensions,systemFlags,out_of_range}';
    violated := false;
    v_reason := NULL;
    v_num := NULL;
    effective := NULL;
    IF p_provided ? field.field_id::text THEN
      effective := p_provided -> field.field_id::text;
    ELSE
      SELECT coalesce(to_jsonb(v.numeric_value), to_jsonb(v.integer_value))
        INTO effective
        FROM api.dataset_row_values v
        WHERE v.row_id = p_row_id AND v.field_id = field.field_id
        ORDER BY v.ordinal LIMIT 1;
      IF effective IS NULL THEN effective := field.default_value; END IF;
    END IF;
    IF rule IS NOT NULL AND jsonb_typeof(rule) = 'object'
       AND field.logical_type IN ('integer','decimal')
       AND effective IS NOT NULL AND jsonb_typeof(effective) = 'number' THEN
      v_num := (effective #>> '{}')::numeric;
      IF rule ? 'min' THEN
        lo := (rule ->> 'min')::numeric;
        IF v_num < lo THEN
          violated := true;
          v_reason := format('Value %s is below the minimum %s', v_num, lo);
        END IF;
      END IF;
      IF NOT violated AND rule ? 'max' THEN
        hi := (rule ->> 'max')::numeric;
        IF v_num > hi THEN
          violated := true;
          v_reason := format('Value %s is above the maximum %s', v_num, hi);
        END IF;
      END IF;
    END IF;
    PERFORM internal.apply_system_flag(
      workspace, p_dataset_id, p_row_id, field.field_id, 'out_of_range',
      coalesce(v_reason, 'Out of range rule now passes'),
      to_jsonb(v_num),
      jsonb_strip_nulls(jsonb_build_object('min', rule -> 'min', 'max', rule -> 'max')),
      violated);

    -- missing_unit: opt-in per field, numeric fields only, and pinned to the
    -- Schema's unit metadata rather than the value.
    rule := field.validation #> '{extensions,systemFlags,missing_unit}';
    violated := false;
    v_reason := NULL;
    has_value := (p_provided ? field.field_id::text
                  AND p_provided -> field.field_id::text <> 'null'::jsonb)
                 OR internal.dataset_row_field_value_text(p_row_id, field.field_id) IS NOT NULL;
    unit_text := nullif(btrim(coalesce(field.quantity ->> 'storageUnit', field.quantity ->> 'symbol')), '');
    IF rule IS NOT NULL AND jsonb_typeof(rule) = 'object'
       AND coalesce((rule ->> 'requiresUnit')::boolean, false) IS TRUE
       AND field.logical_type IN ('integer','decimal')
       AND has_value AND unit_text IS NULL THEN
      violated := true;
      v_reason := format('No unit is recorded for %s', field.label);
    END IF;
    PERFORM internal.apply_system_flag(
      workspace, p_dataset_id, p_row_id, field.field_id, 'missing_unit',
      coalesce(v_reason, 'Unit now recorded'),
      to_jsonb(unit_text),
      jsonb_build_object('requiresUnit', true),
      violated);
  END LOOP;
END $$;
--> statement-breakpoint
ALTER FUNCTION internal.sync_dataset_value_system_flags(p_dataset_id uuid, p_row_id uuid, p_schema_version_id uuid, p_provided jsonb) OWNER TO migrator;
--> statement-breakpoint
CREATE FUNCTION internal.sync_instrument_resource() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
BEGIN
  IF TG_OP = 'DELETE' THEN
    DELETE FROM "api"."calendar_resources"
     WHERE id = OLD.id AND resource_type = 'instrument';
    RETURN NULL;
  END IF;

  INSERT INTO "api"."calendar_resources"
    (id, workspace_id, name, code, resource_type, location, capacity, timezone,
     status, metadata, created_by_user_id, updated_by_user_id)
  VALUES
    (NEW.id, NEW.workspace_id, NEW.name,
     coalesce(nullif(btrim(NEW.display_id), ''), 'INS-' || substr(NEW.id::text, 1, 8)),
     'instrument', NEW.location, 1, 'UTC',
     CASE WHEN NEW.retired_at IS NULL THEN 'active' ELSE 'inactive' END,
     jsonb_build_object('instrumentId', NEW.id),
     NEW.created_by_user_id, NEW.updated_by_user_id)
  ON CONFLICT (id) DO UPDATE
    SET name = excluded.name,
        code = excluded.code,
        location = excluded.location,
        status = excluded.status,
        metadata = excluded.metadata,
        updated_by_user_id = excluded.updated_by_user_id,
        updated_at = now()
    WHERE "api"."calendar_resources"."name" IS DISTINCT FROM excluded.name
       OR "api"."calendar_resources"."code" IS DISTINCT FROM excluded.code
       OR "api"."calendar_resources"."location" IS DISTINCT FROM excluded.location
       OR "api"."calendar_resources"."status" IS DISTINCT FROM excluded.status;
  RETURN NULL;
END $$;
