CREATE FUNCTION internal.sync_sheet_cell_search() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
BEGIN
  IF TG_OP = 'DELETE' THEN
    DELETE FROM api.sheet_cell_search WHERE instance_id = OLD.id;
    RETURN OLD;
  END IF;
  -- Rebuild this instance's rows: a state change can add, edit or clear cells.
  DELETE FROM api.sheet_cell_search WHERE instance_id = NEW.id;
  IF NEW.state IS NULL THEN
    RETURN NEW;
  END IF;
  -- One row per (row identity, field) that actually holds a value.
  INSERT INTO api.sheet_cell_search(
    instance_id, row_key, field_id, workspace_id, project_id, field_label, value_text)
  SELECT NEW.id, cell.key, field.element->>'fieldId', NEW.workspace_id, NEW.project_id,
         coalesce(nullif(field.element->>'label', ''), field.element->>'key', field.element->>'fieldId'),
         internal.sheet_cell_text(cell.value->(field.element->>'fieldId'))
    FROM jsonb_each(NEW.state->'localValues') cell
    CROSS JOIN LATERAL jsonb_array_elements(coalesce(NEW.state->'localFields', '[]'::jsonb)) field(element)
   WHERE coalesce(field.element->>'lifecycle', 'active') = 'active'
     AND cell.value ? (field.element->>'fieldId')
     AND internal.sheet_cell_text(cell.value->(field.element->>'fieldId')) IS NOT NULL
     AND btrim(internal.sheet_cell_text(cell.value->(field.element->>'fieldId'))) <> '';
  RETURN NEW;
END $$;
--> statement-breakpoint
ALTER FUNCTION internal.sync_sheet_cell_search() OWNER TO migrator;
--> statement-breakpoint
CREATE FUNCTION internal.template_parameter_inputs_for_placement(p_placement jsonb, p_template_inputs jsonb) RETURNS jsonb
    LANGUAGE plpgsql IMMUTABLE
    SET search_path TO ''
    AS $$
DECLARE
  mapping jsonb;
  input jsonb;
  mapped jsonb := '[]'::jsonb;
  found jsonb;
BEGIN
  FOR mapping IN SELECT value FROM jsonb_array_elements(coalesce(p_placement->'parameterMappings','[]'::jsonb)) LOOP
    found := NULL;
    SELECT value INTO found
      FROM jsonb_array_elements(coalesce(p_template_inputs,'[]'::jsonb)) value
      WHERE value->>'parameterId' = mapping->>'templateParameterId';
    IF found IS NULL THEN
      CONTINUE;
    END IF;
    input := found || jsonb_build_object('parameterId', mapping->>'definitionParameterId');
    mapped := mapped || jsonb_build_array(input);
  END LOOP;
  RETURN mapped;
END
$$;
--> statement-breakpoint
ALTER FUNCTION internal.template_parameter_inputs_for_placement(p_placement jsonb, p_template_inputs jsonb) OWNER TO migrator;
