CREATE FUNCTION internal.trg_change_event_admin() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE v_row jsonb; v_payload jsonb; v_entity text:=TG_ARGV[0]; v_op text; v_integration_keys jsonb;
BEGIN
  v_row:=CASE WHEN TG_OP='DELETE' THEN to_jsonb(OLD) ELSE to_jsonb(NEW) END;
  v_op:=CASE WHEN TG_OP='INSERT' THEN 'create' WHEN TG_OP='DELETE' THEN 'delete' ELSE 'update' END;
  IF v_entity='workspace_invitation' THEN v_payload:=jsonb_build_object('id',v_row->'id','email',v_row->'email','role',v_row->'role','status',v_row->'status','expires_at',v_row->'expires_at');
  ELSIF v_entity='workspace_settings' THEN
    SELECT COALESCE(jsonb_agg(k ORDER BY k),'[]'::jsonb) INTO v_integration_keys FROM jsonb_object_keys(COALESCE(v_row->'integration_settings','{}'::jsonb)) k;
    v_payload:=jsonb_build_object('registration_mode',v_row->'registration_mode','review_workflow_enabled',v_row->'review_workflow_enabled','review_workflow_config',v_row->'review_workflow_config','signature_policy',v_row->'signature_policy','audit_retention_days',v_row->'audit_retention_days','integration_setting_keys',v_integration_keys);
  ELSE v_payload:=jsonb_build_object('id',v_row->'id','project_id',v_row->'project_id','user_id',v_row->'user_id','access_level',v_row->'access_level'); END IF;
  PERFORM internal.emit_change_event((v_row->>'workspace_id')::uuid,v_entity,(v_row->>'id')::uuid,v_op,NULL,CASE WHEN v_entity='project_access' THEN (v_row->>'project_id')::uuid ELSE NULL END,v_payload);
  RETURN NULL;
END $$;
--> statement-breakpoint
ALTER FUNCTION internal.trg_change_event_admin() OWNER TO migrator;
--> statement-breakpoint
CREATE FUNCTION internal.trg_change_event_blocks() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
  v_op text;
  v_record_id uuid;
  v_workspace_id uuid;
  v_project_id uuid;
  v_payload jsonb;
BEGIN
  IF (TG_OP = 'DELETE') THEN
    v_record_id := OLD.record_id;
    SELECT workspace_id, project_id INTO v_workspace_id, v_project_id
      FROM "api"."records" WHERE id = v_record_id;
    -- The parent record may already be gone (cascade). If so, the cascade
    -- already emitted a record 'delete' event; skip the per-block echo.
    IF v_workspace_id IS NULL THEN
      RETURN NULL;
    END IF;
    PERFORM "internal"."emit_change_event"(
      v_workspace_id, 'block', OLD.id, 'delete', v_record_id, v_project_id,
      jsonb_build_object('blockId', OLD.id, 'type', OLD.type, 'order', OLD."order")
    );
    RETURN NULL;
  END IF;

  v_record_id := NEW.record_id;
  SELECT workspace_id, project_id INTO v_workspace_id, v_project_id
    FROM "api"."records" WHERE id = v_record_id;
  IF v_workspace_id IS NULL THEN
    RETURN NULL;
  END IF;

  IF (TG_OP = 'INSERT') THEN
    v_op := 'create';
    v_payload := jsonb_build_object('blockId', NEW.id, 'type', NEW.type, 'order', NEW."order");
  ELSIF (TG_OP = 'UPDATE') THEN
    -- A move changes order; a content edit changes payload/version. Order
    -- change wins as the semantic operation so LIVE-003 can refetch order.
    IF OLD."order" IS DISTINCT FROM NEW."order" THEN
      v_op := 'move';
    ELSE
      v_op := 'update';
    END IF;
    v_payload := jsonb_build_object(
      'blockId', NEW.id, 'type', NEW.type, 'order', NEW."order",
      'version', NEW.version, 'moved', (OLD."order" IS DISTINCT FROM NEW."order")
    );
  END IF;

  
  IF TG_OP='UPDATE' AND OLD.payload IS DISTINCT FROM NEW.payload THEN
    v_payload:=v_payload||jsonb_build_object('changes',jsonb_build_object(
      'payload',jsonb_build_object('from',OLD.payload,'to',NEW.payload)));
  END IF;
  PERFORM "internal"."emit_change_event"(
    v_workspace_id, 'block', NEW.id, v_op, v_record_id, v_project_id, v_payload
  );
  RETURN NULL;
END;
$$;
--> statement-breakpoint
ALTER FUNCTION internal.trg_change_event_blocks() OWNER TO migrator;
--> statement-breakpoint
CREATE FUNCTION internal.trg_change_event_calendar() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
  v_entity text;
  v_op text;
  v_payload jsonb;
BEGIN
  v_entity := TG_ARGV[0];
  CASE TG_OP
    WHEN 'INSERT' THEN v_op := 'create'; v_payload := to_jsonb(NEW) - 'metadata';
    WHEN 'UPDATE' THEN v_op := 'update'; v_payload := to_jsonb(NEW) - 'metadata';
    WHEN 'DELETE' THEN v_op := 'delete'; v_payload := to_jsonb(OLD) - 'metadata';
  END CASE;
  PERFORM "internal"."emit_change_event"(
    COALESCE(NEW.workspace_id, OLD.workspace_id),
    v_entity,
    COALESCE(NEW.id, OLD.id),
    v_op,
    NULL,
    NULL,
    v_payload
  );
  RETURN NULL;
END;
$$;
