CREATE FUNCTION internal.validate_comment_target(p_revision_id uuid, p_target_kind text, p_target jsonb) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE revision api.revisions; evidence api.revision_sheet_evidence; v_instance_id uuid; identity text;
BEGIN
  SELECT * INTO revision FROM api.revisions WHERE id=p_revision_id;
  IF revision.id IS NULL THEN RAISE EXCEPTION 'revision not found' USING ERRCODE='22023'; END IF;
  IF internal.revision_integrity_digest(revision.canonical_snapshot) IS DISTINCT FROM revision.integrity_digest THEN
    RAISE EXCEPTION 'revision integrity mismatch' USING ERRCODE='SB092';
  END IF;
  IF p_target_kind NOT IN ('sheet_cell','sheet_row','sheet_range') THEN
    PERFORM internal.validate_comment_target_legacy(p_revision_id,p_target_kind,p_target);
    RETURN;
  END IF;
  v_instance_id:=internal.validate_sheet_comment_shape(p_target_kind,p_target);
  SELECT e.* INTO evidence FROM api.revision_sheet_evidence e
    WHERE e.revision_id=p_revision_id AND e.instance_id=v_instance_id
      AND e.workspace_id=revision.workspace_id;
  IF evidence.id IS NULL OR jsonb_typeof(evidence.composed_grid->'rowKeys') IS DISTINCT FROM 'array' THEN
    RAISE EXCEPTION 'canonical Sheet identities unavailable in frozen evidence' USING ERRCODE='SB002';
  END IF;
  IF NOT EXISTS(SELECT 1 FROM jsonb_array_elements(coalesce(revision.canonical_snapshot->'sheetEvidence','[]')) s
    WHERE s->>'blockId'=evidence.block_id::text AND s->>'instanceId'=evidence.instance_id::text
      AND s->'instanceState'=evidence.instance_state AND (s->>'instanceRevision')::bigint=evidence.instance_revision) THEN
    RAISE EXCEPTION 'frozen Sheet evidence does not match verified revision' USING ERRCODE='SB092';
  END IF;
  FOR identity IN SELECT value FROM jsonb_array_elements_text(p_target->'rowKeys') LOOP
    IF NOT evidence.composed_grid->'rowKeys' ? identity THEN
      RAISE EXCEPTION 'row absent from frozen Sheet evidence' USING ERRCODE='SB002';
    END IF;
  END LOOP;
  FOR identity IN SELECT value FROM jsonb_array_elements_text(p_target->'fieldIds') LOOP
    IF NOT EXISTS(SELECT 1 FROM jsonb_array_elements(evidence.composed_grid->'columns') c WHERE c->>'id'=identity) THEN
      RAISE EXCEPTION 'field absent from frozen Sheet evidence' USING ERRCODE='SB002';
    END IF;
  END LOOP;
END $$;
--> statement-breakpoint
ALTER FUNCTION internal.validate_comment_target(p_revision_id uuid, p_target_kind text, p_target jsonb) OWNER TO migrator;
--> statement-breakpoint
CREATE FUNCTION internal.validate_comment_target_legacy(p_revision_id uuid, p_target_kind text, p_target jsonb) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
  v_revision api.revisions;
  v_snapshot jsonb;
  v_block_id text;
  v_table_id text;
  v_row_id text;
  v_column_id text;
  v_comparison_revision_id text;
  v_comparison_record_id uuid;
BEGIN
  SELECT * INTO v_revision FROM api.revisions WHERE id = p_revision_id;
  IF v_revision.id IS NULL THEN
    RAISE EXCEPTION 'revision not found' USING ERRCODE = '22023';
  END IF;
  v_snapshot := v_revision.canonical_snapshot;

  IF p_target_kind = 'revision' THEN
    RETURN;
  ELSIF p_target_kind = 'block' THEN
    v_block_id := p_target->>'blockId';
    IF v_block_id IS NULL OR v_block_id = '' THEN
      RAISE EXCEPTION 'block target requires blockId' USING ERRCODE = '22023';
    END IF;
    IF NOT EXISTS (
      SELECT 1 FROM jsonb_array_elements(
        CASE WHEN jsonb_typeof(v_snapshot->'blocks') = 'array'
          THEN v_snapshot->'blocks' ELSE '[]'::jsonb END
      ) block WHERE block->>'id' = v_block_id
    ) THEN
      RAISE EXCEPTION 'block target is not present in the revision snapshot'
        USING ERRCODE = 'SB002';
    END IF;
  ELSIF p_target_kind = 'table_region' THEN
    v_table_id := p_target->>'tableId';
    IF v_table_id IS NULL OR v_table_id = '' THEN
      RAISE EXCEPTION 'table_region target requires tableId'
        USING ERRCODE = '22023';
    END IF;
    IF NOT EXISTS (
      SELECT 1 FROM jsonb_array_elements(
        CASE WHEN jsonb_typeof(v_snapshot->'scientificTables') = 'array'
          THEN v_snapshot->'scientificTables' ELSE '[]'::jsonb END
      ) tbl WHERE tbl->>'id' = v_table_id
    ) THEN
      RAISE EXCEPTION 'table target is not present in the revision snapshot'
        USING ERRCODE = 'SB002';
    END IF;
    -- rowId/columnId are optional (a region may target the whole table). When
    -- supplied, validate them against the snapshot's rows/columns.
    v_row_id := p_target->>'rowId';
    v_column_id := p_target->>'columnId';
    IF v_column_id IS NOT NULL AND v_column_id <> '' THEN
      IF NOT EXISTS (
        SELECT 1 FROM jsonb_array_elements(
          CASE WHEN jsonb_typeof(v_snapshot->'scientificTables') = 'array'
            THEN v_snapshot->'scientificTables' ELSE '[]'::jsonb END
        ) tbl,
        jsonb_array_elements(
          CASE WHEN jsonb_typeof(tbl->'columns') = 'array'
            THEN tbl->'columns' ELSE '[]'::jsonb END
        ) col
        WHERE tbl->>'id' = v_table_id AND col->>'id' = v_column_id
      ) THEN
        RAISE EXCEPTION 'column target is not present in the revision snapshot'
          USING ERRCODE = 'SB002';
      END IF;
    END IF;
    IF v_row_id IS NOT NULL AND v_row_id <> '' THEN
      IF NOT EXISTS (
        SELECT 1 FROM jsonb_array_elements(
          CASE WHEN jsonb_typeof(v_snapshot->'scientificTables') = 'array'
            THEN v_snapshot->'scientificTables' ELSE '[]'::jsonb END
        ) tbl,
        jsonb_array_elements(
          CASE WHEN jsonb_typeof(tbl->'rows') = 'array'
            THEN tbl->'rows' ELSE '[]'::jsonb END
        ) row
        WHERE tbl->>'id' = v_table_id AND row->>'id' = v_row_id
      ) THEN
        RAISE EXCEPTION 'row target is not present in the revision snapshot'
          USING ERRCODE = 'SB002';
      END IF;
    END IF;
  ELSIF p_target_kind = 'diff' THEN
    v_comparison_revision_id := p_target->>'comparisonRevisionId';
    IF v_comparison_revision_id IS NULL OR v_comparison_revision_id = '' THEN
      RAISE EXCEPTION 'diff target requires comparisonRevisionId'
        USING ERRCODE = '22023';
    END IF;
    IF (p_target->>'changeId') IS NULL OR (p_target->>'changeId') = '' THEN
      RAISE EXCEPTION 'diff target requires changeId' USING ERRCODE = '22023';
    END IF;
    -- The comparison revision must exist and belong to the same workspace
    -- and record, so the diff (and its deterministic change ids) is stable.
    SELECT record_id INTO v_comparison_record_id FROM api.revisions
    WHERE id = v_comparison_revision_id::uuid
      AND workspace_id = v_revision.workspace_id
      AND record_id = v_revision.record_id;
    IF v_comparison_record_id IS NULL THEN
      RAISE EXCEPTION 'diff comparison revision is not in this workspace/record'
        USING ERRCODE = 'SB002';
    END IF;
  ELSE
    RAISE EXCEPTION 'unknown comment target kind' USING ERRCODE = '22023';
  END IF;
END;
$$;
--> statement-breakpoint
ALTER FUNCTION internal.validate_comment_target_legacy(p_revision_id uuid, p_target_kind text, p_target jsonb) OWNER TO migrator;
--> statement-breakpoint
CREATE FUNCTION internal.validate_dataset_field_spec(p_spec jsonb) RETURNS jsonb
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $_$
DECLARE v_slug text; v_compiled jsonb; v_compile_spec jsonb;
BEGIN
  IF jsonb_typeof(p_spec)<>'object' THEN RAISE EXCEPTION 'field spec must be an object' USING ERRCODE='22023'; END IF;
  v_slug := p_spec->>'slug';
  IF v_slug IS NULL OR v_slug !~ '^[a-z][a-z0-9_]{0,59}$' THEN RAISE EXCEPTION 'field slug must match ^[a-z][a-z0-9_]{0,59}$' USING ERRCODE='22023'; END IF;
  -- compile_scientific_column rejects unknown members, so strip the registry-
  -- only keys (slug, display_order) before delegating to the 0019 validator.
  v_compile_spec := p_spec - ARRAY['slug','display_order'];
  v_compiled := internal.compile_scientific_column(v_compile_spec);
  RETURN jsonb_build_object('slug',v_slug,'compiled',v_compiled);
END $_$;
--> statement-breakpoint
ALTER FUNCTION internal.validate_dataset_field_spec(p_spec jsonb) OWNER TO migrator;
--> statement-breakpoint
CREATE FUNCTION internal.validate_dataset_import_block(p_payload jsonb, p_workspace uuid, p_complete boolean DEFAULT false) RETURNS void
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $_$
DECLARE key text; uploaded boolean; committed boolean; file api.dataset_import_files;
  receipt api.dataset_imports; version api.dataset_versions;
BEGIN
  IF jsonb_typeof(p_payload) IS DISTINCT FROM 'object' THEN
    RAISE EXCEPTION 'import payload must be an object' USING ERRCODE='23514';
  END IF;
  uploaded := p_payload ?| ARRAY['fileId','datasetId'];
  committed := p_payload ?| ARRAY['importId','datasetVersionId'];
  IF p_complete AND NOT committed THEN
    RAISE EXCEPTION 'Complete or remove the pending import before submission' USING ERRCODE='23514';
  END IF;
  FOREACH key IN ARRAY ARRAY['fileId','datasetId','importId','datasetVersionId'] LOOP
    IF (key IN ('fileId','datasetId') AND (uploaded OR committed)) OR
       (key IN ('importId','datasetVersionId') AND committed) THEN
      IF jsonb_typeof(p_payload->key) IS DISTINCT FROM 'string' OR
         coalesce(p_payload->>key,'') !~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' THEN
        RAISE EXCEPTION 'import % must be a UUID', key USING ERRCODE='23514';
      END IF;
    END IF;
  END LOOP;
  IF p_payload ? 'sheetName' AND (NOT uploaded OR jsonb_typeof(p_payload->'sheetName') IS DISTINCT FROM 'string') THEN
    RAISE EXCEPTION 'sheetName requires upload pins and must be a string' USING ERRCODE='23514';
  END IF;
  IF p_payload ? 'search' THEN
    IF committed OR jsonb_typeof(p_payload->'search') IS DISTINCT FROM 'object' THEN
      RAISE EXCEPTION 'search is draft import state only' USING ERRCODE='23514';
    END IF;
    IF EXISTS (SELECT 1 FROM jsonb_each(p_payload->'search') s
      WHERE s.key NOT IN ('step','parser','map','sheet','units','instrument') OR jsonb_typeof(s.value)<>'string'
        OR (s.key='step' AND s.value #>> '{}' NOT IN ('map','check'))) THEN
      RAISE EXCEPTION 'invalid draft import search options' USING ERRCODE='23514';
    END IF;
  END IF;
  IF NOT uploaded AND NOT committed THEN RETURN; END IF;
  IF p_workspace IS DISTINCT FROM api.current_workspace_id() OR NOT api.is_workspace_member(p_workspace) THEN
    RAISE EXCEPTION 'import workspace denied' USING ERRCODE='42501';
  END IF;
  PERFORM internal.assert_object_access('dataset',(p_payload->>'datasetId')::uuid,'view');
  PERFORM internal.assert_object_access('import_file',(p_payload->>'fileId')::uuid,'view');
  SELECT * INTO file FROM api.dataset_import_files WHERE id=(p_payload->>'fileId')::uuid;
  IF file.workspace_id IS DISTINCT FROM p_workspace OR NOT EXISTS (
    SELECT 1 FROM api.datasets WHERE id=(p_payload->>'datasetId')::uuid AND workspace_id=p_workspace
  ) OR (NOT committed AND file.dataset_id IS NOT NULL AND file.dataset_id<>(p_payload->>'datasetId')::uuid) THEN
    RAISE EXCEPTION 'import upload does not match Dataset' USING ERRCODE='23514';
  END IF;
  IF NOT committed THEN RETURN; END IF;
  SELECT * INTO receipt FROM api.dataset_imports WHERE id=(p_payload->>'importId')::uuid;
  SELECT * INTO version FROM api.dataset_versions WHERE id=(p_payload->>'datasetVersionId')::uuid;
  IF receipt.workspace_id IS DISTINCT FROM p_workspace OR receipt.status IS DISTINCT FROM 'committed'
    OR receipt.file_id IS DISTINCT FROM file.id
    OR receipt.dataset_id IS DISTINCT FROM (p_payload->>'datasetId')::uuid
    OR receipt.snapshot_version_id IS DISTINCT FROM version.id
    OR version.dataset_id IS DISTINCT FROM receipt.dataset_id
    OR version.workspace_id IS DISTINCT FROM p_workspace
    OR EXISTS (SELECT 1 FROM api.dataset_version_prunes WHERE dataset_version_id=version.id)
    OR (p_payload ? 'sheetName' AND p_payload->>'sheetName' IS DISTINCT FROM receipt.mapping->>'sheetName') THEN
    RAISE EXCEPTION 'import receipt does not match file, Dataset, worksheet and snapshot' USING ERRCODE='23514';
  END IF;
  PERFORM internal.assert_object_access('dataset_version',version.id,'view');
END $_$;
--> statement-breakpoint
ALTER FUNCTION internal.validate_dataset_import_block(p_payload jsonb, p_workspace uuid, p_complete boolean) OWNER TO migrator;
--> statement-breakpoint
CREATE FUNCTION internal.validate_dataset_row_value() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE field api.dataset_schema_version_fields; slots integer; target_model text;
BEGIN
 SELECT f.* INTO field FROM api.dataset_rows r JOIN api.datasets d ON d.id=r.dataset_id JOIN api.dataset_schema_version_fields f ON f.schema_version_id=d.schema_version_id AND f.field_id=NEW.field_id WHERE r.id=NEW.row_id;
 IF field.id IS NULL OR field.lifecycle <> 'active' THEN RAISE EXCEPTION 'unknown active Dataset field' USING ERRCODE='22023'; END IF;
 IF field.cardinality='one' AND NEW.ordinal<>0 THEN RAISE EXCEPTION 'scalar Dataset fields require ordinal zero' USING ERRCODE='22023'; END IF;
 slots := (NEW.text_value IS NOT NULL)::int+(NEW.integer_value IS NOT NULL)::int+(NEW.numeric_value IS NOT NULL)::int+(NEW.boolean_value IS NOT NULL)::int+(NEW.date_value IS NOT NULL)::int+(NEW.timestamp_value IS NOT NULL)::int+(NEW.category_option_id IS NOT NULL)::int+(NEW.reference_id IS NOT NULL)::int;
 IF slots <> 1 THEN RAISE EXCEPTION 'exactly one typed Dataset value is required' USING ERRCODE='22023'; END IF;
 IF (field.logical_type='text' AND NEW.text_value IS NULL) OR (field.logical_type='integer' AND NEW.integer_value IS NULL) OR (field.logical_type='decimal' AND NEW.numeric_value IS NULL) OR (field.logical_type='boolean' AND NEW.boolean_value IS NULL) OR (field.logical_type='date' AND NEW.date_value IS NULL) OR (field.logical_type='timestamp' AND NEW.timestamp_value IS NULL) OR (field.logical_type='category' AND NEW.category_option_id IS NULL) OR (field.logical_type='reference' AND NEW.reference_id IS NULL) THEN RAISE EXCEPTION 'Dataset value does not match field logical type' USING ERRCODE='22023'; END IF;
 IF field.logical_type='text' AND ((field.validation ? 'minLength' AND length(NEW.text_value)<(field.validation->>'minLength')::integer) OR (field.validation ? 'maxLength' AND length(NEW.text_value)>(field.validation->>'maxLength')::integer) OR (field.validation ? 'pattern' AND NEW.text_value !~ (field.validation->>'pattern'))) THEN RAISE EXCEPTION 'text validation failed' USING ERRCODE='SB071'; END IF;
 IF field.logical_type IN ('integer','decimal') AND ((field.validation ? 'min' AND coalesce(NEW.numeric_value,NEW.integer_value::numeric)<(field.validation->>'min')::numeric) OR (field.validation ? 'max' AND coalesce(NEW.numeric_value,NEW.integer_value::numeric)>(field.validation->>'max')::numeric)) THEN RAISE EXCEPTION 'numeric validation failed' USING ERRCODE='SB071'; END IF;
 IF field.logical_type='category' AND NOT EXISTS (SELECT 1 FROM jsonb_array_elements(coalesce(field.category->'options','[]'::jsonb)) o WHERE o->>'id'=NEW.category_option_id::text AND o->>'lifecycle'='active') THEN RAISE EXCEPTION 'category option is not active for this field' USING ERRCODE='SB071'; END IF;
 IF field.logical_type='reference' THEN
   target_model := coalesce(field.relationship->'target'->>'modelKey',field.validation->>'targetModelKey');
   IF target_model IS NULL OR NOT EXISTS (SELECT 1 FROM api.dataset_rows r JOIN api.records record ON record.id=NEW.reference_id AND record.workspace_id=r.workspace_id JOIN api.model_kinds m ON m.record_kind=record.kind WHERE r.id=NEW.row_id AND m.key=target_model AND record.deleted_at IS NULL) THEN RAISE EXCEPTION 'reference does not target an active compatible Record' USING ERRCODE='SB071'; END IF;
 END IF;
 RETURN NEW;
END $$;
--> statement-breakpoint
ALTER FUNCTION internal.validate_dataset_row_value() OWNER TO migrator;
--> statement-breakpoint
CREATE FUNCTION internal.validate_extension_compat(p_manifest jsonb) RETURNS void
    LANGUAGE plpgsql IMMUTABLE
    SET search_path TO ''
    AS $_$
DECLARE
  v_range text;
  v_token text;
BEGIN
  IF (p_manifest ? 'compatibleWith') IS DISTINCT FROM true THEN
    RETURN;
  END IF;
  v_range := btrim(p_manifest->>'compatibleWith');
  IF v_range IS NULL OR v_range = '' OR length(v_range) > 200 THEN
    RAISE EXCEPTION 'invalid extension compatibleWith' USING ERRCODE = 'SB034';
  END IF;
  FOR v_token IN SELECT * FROM regexp_split_to_table(v_range, '\s+') LOOP
    IF v_token = '*' THEN
      CONTINUE;
    END IF;
    IF v_token !~ '^((>=|<=|>|<|=)?(0|[1-9][0-9]*)\.(0|[1-9][0-9]*)\.(0|[1-9][0-9]*)(-[0-9A-Za-z.-]+)?)$' THEN
      RAISE EXCEPTION 'invalid extension compatibleWith comparator: %', v_token
        USING ERRCODE = 'SB034';
    END IF;
  END LOOP;
END;
$_$;
--> statement-breakpoint
ALTER FUNCTION internal.validate_extension_compat(p_manifest jsonb) OWNER TO migrator;
--> statement-breakpoint
CREATE FUNCTION internal.validate_extension_manifest(p_manifest jsonb) RETURNS void
    LANGUAGE plpgsql IMMUTABLE
    SET search_path TO ''
    AS $_$
DECLARE
  v_point text;
  v_entry jsonb;
  v_value text;
  v_seen text[];
BEGIN
  IF p_manifest IS NULL OR jsonb_typeof(p_manifest) <> 'object' THEN
    RAISE EXCEPTION 'invalid extension manifest' USING ERRCODE = 'SB034';
  END IF;
  IF p_manifest->>'id' IS NULL
     OR (p_manifest->>'id') !~ '^[a-z][a-z0-9-]*(\.[a-z][a-z0-9-]*)+$' THEN
    RAISE EXCEPTION 'invalid extension id' USING ERRCODE = 'SB034';
  END IF;
  IF p_manifest->>'name' IS NULL
     OR length(btrim(p_manifest->>'name')) NOT BETWEEN 1 AND 200 THEN
    RAISE EXCEPTION 'invalid extension name' USING ERRCODE = 'SB034';
  END IF;
  IF p_manifest->>'version' IS NULL
     OR (p_manifest->>'version') !~ '^(0|[1-9][0-9]*)\.(0|[1-9][0-9]*)\.(0|[1-9][0-9]*)(-[0-9A-Za-z.-]+)?(\+[0-9A-Za-z.-]+)?$' THEN
    RAISE EXCEPTION 'invalid extension version' USING ERRCODE = 'SB034';
  END IF;
  IF p_manifest->>'source' IS NULL
     OR length(p_manifest->>'source') NOT BETWEEN 1 AND 500
     OR (
       left(p_manifest->>'source', 8) <> 'https://'
       AND (p_manifest->>'source') !~ '^[a-z][a-z0-9-]*:[^/][a-zA-Z0-9._/~?#%@!$&''()*+,;=-]+$'
     ) THEN
    RAISE EXCEPTION 'invalid extension source' USING ERRCODE = 'SB034';
  END IF;
  IF (p_manifest ? 'capabilities') IS DISTINCT FROM true
     OR jsonb_typeof(p_manifest->'capabilities') <> 'array' THEN
    RAISE EXCEPTION 'invalid extension capabilities' USING ERRCODE = 'SB034';
  END IF;
  FOR v_entry IN SELECT * FROM jsonb_array_elements(p_manifest->'capabilities') LOOP
    IF jsonb_typeof(v_entry) <> 'string' THEN
      RAISE EXCEPTION 'unknown capability' USING ERRCODE = 'SB034';
    END IF;
    v_value := v_entry #>> '{}';
    IF v_value NOT IN (
      'workspace.admin', 'schema.edit', 'schema.publish', 'schema.retire',
      'record.link', 'record.create', 'instance.upgrade',
      'integrations.manage', 'pipelines.manage', 'extensions.manage'
    ) THEN
      RAISE EXCEPTION 'unknown capability: %', v_value USING ERRCODE = 'SB034';
    END IF;
  END LOOP;
  IF (p_manifest ? 'scopes') IS DISTINCT FROM true
     OR jsonb_typeof(p_manifest->'scopes') <> 'array' THEN
    RAISE EXCEPTION 'invalid extension scopes' USING ERRCODE = 'SB034';
  END IF;
  FOR v_entry IN SELECT * FROM jsonb_array_elements(p_manifest->'scopes') LOOP
    IF jsonb_typeof(v_entry) <> 'string' THEN
      RAISE EXCEPTION 'unknown scope' USING ERRCODE = 'SB034';
    END IF;
    v_value := v_entry #>> '{}';
    IF v_value NOT IN (
      'projects:read', 'projects:write',
      'datasets:read', 'datasets:write',
      'schema:read', 'schema:write', 'schema:publish',
      'sheets:read', 'sheets:write',
      'models:read', 'models:write',
      'templates:read', 'templates:write',
      'reviews:read', 'reviews:write',
      'files:read', 'files:write',
      'webhooks:read', 'webhooks:write',
      'agent_operations:read', 'agent_operations:write'
    ) THEN
      RAISE EXCEPTION 'unknown scope: %', v_value USING ERRCODE = 'SB034';
    END IF;
  END LOOP;
  IF jsonb_array_length(p_manifest->'capabilities')
     + jsonb_array_length(p_manifest->'scopes') = 0 THEN
    RAISE EXCEPTION 'extension must declare at least one capability or scope'
      USING ERRCODE = 'SB034';
  END IF;
  IF (p_manifest ? 'contributions') IS DISTINCT FROM true
     OR jsonb_typeof(p_manifest->'contributions') <> 'object' THEN
    RAISE EXCEPTION 'invalid extension contributions' USING ERRCODE = 'SB034';
  END IF;
  -- Fail closed: a misspelled point never silently disables a declaration.
  SELECT k INTO v_point FROM jsonb_object_keys(p_manifest->'contributions') AS k
   WHERE k NOT IN ('object-actions', 'panels', 'commands', 'event-subscriptions')
   LIMIT 1;
  IF v_point IS NOT NULL THEN
    RAISE EXCEPTION 'unknown contribution point: %', v_point USING ERRCODE = 'SB034';
  END IF;
  FOR v_point IN
    SELECT * FROM unnest(ARRAY['object-actions', 'panels', 'commands'])
  LOOP
    IF (p_manifest->'contributions' ? v_point) IS DISTINCT FROM true THEN
      CONTINUE;
    END IF;
    IF jsonb_typeof(p_manifest->'contributions'->v_point) <> 'array' THEN
      RAISE EXCEPTION 'invalid extension contributions' USING ERRCODE = 'SB034';
    END IF;
    v_seen := '{}';
    FOR v_entry IN
      SELECT * FROM jsonb_array_elements(p_manifest->'contributions'->v_point)
    LOOP
      IF jsonb_typeof(v_entry) <> 'object'
         OR (v_entry->>'id') IS NULL
         OR (v_entry->>'id') !~ '^[a-z][a-z0-9-]{0,48}$'
         OR (v_entry->>'title') IS NULL
         OR length(btrim(v_entry->>'title')) NOT BETWEEN 1 AND 120 THEN
        RAISE EXCEPTION 'invalid extension contributions' USING ERRCODE = 'SB034';
      END IF;
      IF (v_entry->>'id') = ANY (v_seen) THEN
        RAISE EXCEPTION 'duplicate extension contribution id' USING ERRCODE = 'SB034';
      END IF;
      v_seen := v_seen || (v_entry->>'id');
    END LOOP;
  END LOOP;
  IF (p_manifest->'contributions' ? 'event-subscriptions') IS DISTINCT FROM true THEN
    RETURN;
  END IF;
  IF jsonb_typeof(p_manifest->'contributions'->'event-subscriptions') <> 'array' THEN
    RAISE EXCEPTION 'invalid extension contributions' USING ERRCODE = 'SB034';
  END IF;
  v_seen := '{}';
  FOR v_entry IN
    SELECT * FROM jsonb_array_elements(p_manifest->'contributions'->'event-subscriptions')
  LOOP
    IF jsonb_typeof(v_entry) <> 'object'
       OR (v_entry->>'eventType') IS NULL THEN
      RAISE EXCEPTION 'invalid event subscription' USING ERRCODE = 'SB034';
    END IF;
    v_value := v_entry->>'eventType';
    IF v_value NOT IN (
      'project.created', 'project.updated', 'project.deleted',
      'project.archived', 'project.restored',
      'record.created', 'record.updated', 'record.moved', 'record.deleted',
      'record.archived', 'record.restored', 'record.amended',
      'dataset.created', 'dataset.updated', 'dataset.archived',
      'dataset.restored', 'dataset.versioned',
      'sheet.created', 'sheet.updated', 'sheet.archived', 'sheet.restored',
      'sheet.definition.created', 'sheet.definition.updated',
      'sheet.definition.versioned',
      'notebook.submitted', 'notebook.amended',
      'review.decided', 'notebook.signed',
      'notebook.template.created', 'notebook.template.updated',
      'notebook.template.versioned',
      'pipeline.created', 'pipeline.updated', 'pipeline.deleted',
      'pipeline.version.created', 'pipeline.version.updated',
      'pipeline.run.created', 'pipeline.run.updated',
      'pipeline.schedule.created', 'pipeline.schedule.updated',
      'workspace.invitation.created', 'workspace.invitation.updated',
      'workspace.invitation.deleted',
      'workspace.settings.created', 'workspace.settings.updated',
      'project.access.granted', 'project.access.updated',
      'project.access.revoked',
      'workspace.credential.created', 'workspace.credential.revoked'
    ) THEN
      RAISE EXCEPTION 'unknown event subscription: %', v_value USING ERRCODE = 'SB034';
    END IF;
    IF v_value = ANY (v_seen) THEN
      RAISE EXCEPTION 'duplicate event subscription' USING ERRCODE = 'SB034';
    END IF;
    v_seen := v_seen || v_value;
  END LOOP;
END;
$_$;
--> statement-breakpoint
ALTER FUNCTION internal.validate_extension_manifest(p_manifest jsonb) OWNER TO migrator;
--> statement-breakpoint
CREATE FUNCTION internal.validate_model_fields(p_workspace uuid, p_model text, p_new jsonb, p_old jsonb DEFAULT '{}'::jsonb) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $_$
DECLARE d record; k text; v jsonb; out jsonb:=coalesce(p_new,'{}'); target api.records;
BEGIN
 IF jsonb_typeof(out)<>'object' THEN RAISE EXCEPTION 'custom_fields must be an object' USING ERRCODE='22023'; END IF;
 FOR d IN SELECT * FROM api.record_field_definitions
   WHERE workspace_id=p_workspace AND kind=p_model AND lifecycle='retired' AND coalesce(p_old,'{}') ? field_name
 LOOP
   IF NOT out ? d.field_name OR out->d.field_name IS DISTINCT FROM p_old->d.field_name THEN
     RAISE EXCEPTION 'retired custom field % is immutable',d.field_name USING ERRCODE='SB070';
   END IF;
 END LOOP;
 FOR k IN SELECT jsonb_object_keys(out) LOOP
   IF EXISTS(SELECT 1 FROM api.model_base_fields WHERE model_key=p_model AND field_key=k) THEN RAISE EXCEPTION 'protected custom field: %',k USING ERRCODE='SB070'; END IF;
   SELECT * INTO d FROM api.record_field_definitions WHERE workspace_id=p_workspace AND kind=p_model AND field_name=k;
   IF NOT FOUND THEN RAISE EXCEPTION 'unknown custom field: %',k USING ERRCODE='SB070'; END IF;
   IF d.lifecycle NOT IN ('active','backfilling') THEN
     IF NOT coalesce(p_old,'{}') ? k OR p_old->k IS DISTINCT FROM out->k THEN RAISE EXCEPTION 'retired custom field: %',k USING ERRCODE='SB070'; END IF;
     CONTINUE;
   END IF;
   v:=out->k;
   IF v='null' AND NOT d.nullable THEN RAISE EXCEPTION 'field % may not be null',k USING ERRCODE='SB071'; END IF;
   IF v='null' THEN CONTINUE; END IF;
   IF (d.logical_type='text' AND jsonb_typeof(v)<>'string') OR
      (d.logical_type='integer' AND (jsonb_typeof(v)<>'number' OR (v#>>'{}') !~ '^-?[0-9]+$')) OR
      (d.logical_type='decimal' AND jsonb_typeof(v)<>'number') OR
      (d.logical_type='boolean' AND jsonb_typeof(v)<>'boolean') OR
      (d.logical_type IN ('date','timestamp','category','reference') AND jsonb_typeof(v)<>'string') THEN
      RAISE EXCEPTION 'invalid % value for %',d.logical_type,k USING ERRCODE='SB071'; END IF;
   IF d.logical_type='date' THEN BEGIN PERFORM (v#>>'{}')::date; EXCEPTION WHEN others THEN RAISE EXCEPTION 'invalid date' USING ERRCODE='SB071'; END; END IF;
   IF d.logical_type='timestamp' THEN BEGIN PERFORM (v#>>'{}')::timestamptz; EXCEPTION WHEN others THEN RAISE EXCEPTION 'invalid timestamp' USING ERRCODE='SB071'; END; END IF;
   IF d.logical_type='text' AND ((d.validation ? 'minLength' AND length(v#>>'{}')<(d.validation->>'minLength')::integer) OR (d.validation ? 'maxLength' AND length(v#>>'{}')>(d.validation->>'maxLength')::integer) OR (d.validation ? 'regex' AND NOT (v#>>'{}' ~ (d.validation->>'regex')))) THEN RAISE EXCEPTION 'text validation failed for %',k USING ERRCODE='SB071'; END IF;
   IF d.logical_type IN ('integer','decimal') AND ((d.validation ? 'min' AND (v#>>'{}')::numeric<(d.validation->>'min')::numeric) OR (d.validation ? 'max' AND (v#>>'{}')::numeric>(d.validation->>'max')::numeric)) THEN RAISE EXCEPTION 'numeric validation failed for %',k USING ERRCODE='SB071'; END IF;
   IF d.logical_type='category' AND NOT EXISTS(SELECT 1 FROM api.model_field_options o WHERE o.definition_id=d.id AND o.key=v#>>'{}' AND (o.lifecycle='active' OR p_old->k IS NOT DISTINCT FROM v)) THEN RAISE EXCEPTION 'inactive category option' USING ERRCODE='SB071'; END IF;
   IF d.logical_type='reference' THEN
     IF d.validation->>'targetModelKey' IS NULL THEN RAISE EXCEPTION 'reference targetModelKey required' USING ERRCODE='SB071'; END IF;
     BEGIN
       SELECT r.* INTO target FROM api.records r JOIN api.model_kinds m ON m.record_kind=r.kind
        WHERE r.id=(v#>>'{}')::uuid AND r.workspace_id=p_workspace AND m.key=d.validation->>'targetModelKey'
          AND (r.deleted_at IS NULL OR p_old->k IS NOT DISTINCT FROM v);
     EXCEPTION WHEN invalid_text_representation THEN RAISE EXCEPTION 'invalid reference' USING ERRCODE='SB071'; END;
     IF NOT FOUND THEN RAISE EXCEPTION 'invalid reference' USING ERRCODE='SB071'; END IF;
   END IF;
 END LOOP;
 FOR d IN SELECT * FROM api.record_field_definitions WHERE workspace_id=p_workspace AND kind=p_model AND lifecycle='active' LOOP
   IF NOT out ? d.field_name AND d.default_value IS NOT NULL THEN out:=out||jsonb_build_object(d.field_name,d.default_value); END IF;
   IF NOT d.nullable AND (NOT out ? d.field_name OR out->d.field_name='null') THEN RAISE EXCEPTION 'required field % missing',d.field_name USING ERRCODE='SB071'; END IF;
 END LOOP;
 RETURN out;
END $_$;
--> statement-breakpoint
ALTER FUNCTION internal.validate_model_fields(p_workspace uuid, p_model text, p_new jsonb, p_old jsonb) OWNER TO migrator;
