CREATE FUNCTION internal.validate_notebook_template_configuration(p_workspace_id uuid, p_config jsonb) RETURNS void
    LANGUAGE plpgsql STABLE
    SET search_path TO ''
    AS $_$
DECLARE
  item jsonb;
  mapping jsonb;
  parameter jsonb;
  def_param jsonb;
  version_row api.sheet_definition_versions;
  definition api.sheet_definitions;
  parameter_ids text[] := '{}';
  parameter_keys text[] := '{}';
  placement_ids text[] := '{}';
  id text;
  order_seen numeric[] := '{}';
  mapped boolean;
BEGIN
  IF octet_length(p_config::text) > 1048576 THEN
    RAISE EXCEPTION 'Notebook Template configuration exceeds 1 MiB' USING ERRCODE = 'SB091';
  END IF;
  PERFORM internal.assert_sheet_definition_object(
    p_config,
    ARRAY['formatVersion','parameters','placements'],
    ARRAY['formatVersion','parameters','placements'],
    'configuration'
  );
  IF p_config->'formatVersion' <> '1'::jsonb THEN
    RAISE EXCEPTION 'unsupported Notebook Template configuration format' USING ERRCODE = 'SB091';
  END IF;
  IF jsonb_typeof(p_config->'parameters') <> 'array'
     OR jsonb_array_length(p_config->'parameters') > 64
     OR jsonb_typeof(p_config->'placements') <> 'array'
     OR jsonb_array_length(p_config->'placements') > 256 THEN
    RAISE EXCEPTION 'invalid Notebook Template sections' USING ERRCODE = 'SB091';
  END IF;

  FOR item IN SELECT value FROM jsonb_array_elements(p_config->'parameters') LOOP
    BEGIN
      PERFORM internal.validate_parameter(item);
    EXCEPTION WHEN SQLSTATE 'SB071' THEN
      RAISE EXCEPTION 'invalid Notebook Template parameter: %', SQLERRM USING ERRCODE = 'SB091';
    END;
    id := item->>'id';
    IF id = ANY(parameter_ids) OR item->>'key' = ANY(parameter_keys) THEN
      RAISE EXCEPTION 'duplicate Notebook Template parameter identity' USING ERRCODE = 'SB091';
    END IF;
    parameter_ids := array_append(parameter_ids, id);
    parameter_keys := array_append(parameter_keys, item->>'key');
  END LOOP;

  FOR item IN SELECT value FROM jsonb_array_elements(p_config->'placements') LOOP
    IF jsonb_typeof(item) <> 'object' OR item->>'kind' NOT IN ('narrative','sheet','section_placeholder') THEN
      RAISE EXCEPTION 'invalid Template placement kind' USING ERRCODE = 'SB091';
    END IF;
    id := internal.sheet_definition_uuid(item->>'id','placements.id')::text;
    IF id = ANY(placement_ids) THEN
      RAISE EXCEPTION 'duplicate Template placement id' USING ERRCODE = 'SB091';
    END IF;
    placement_ids := array_append(placement_ids, id);
    IF jsonb_typeof(item->'order') <> 'number'
       OR (item->>'order')::numeric <> trunc((item->>'order')::numeric)
       OR (item->>'order')::numeric < 1
       OR (item->>'order')::numeric = ANY(order_seen) THEN
      RAISE EXCEPTION 'Template placements require unique positive integer order' USING ERRCODE = 'SB091';
    END IF;
    order_seen := array_append(order_seen, (item->>'order')::numeric);

    IF item->>'kind' = 'narrative' THEN
      PERFORM internal.assert_sheet_definition_object(
        item,
        ARRAY['id','kind','order','blockType','payload'],
        ARRAY['id','kind','order','blockType','payload'],
        'placements.narrative'
      );
      IF item->>'blockType' NOT IN (
        'rich_text','checklist','linked_record','callout','table','chart',
        'plate_map','file','metric','procedure_step','protocol_reference','materials'
      ) THEN
        RAISE EXCEPTION 'narrative placement cannot be a Sheet block' USING ERRCODE = 'SB091';
      END IF;
      IF jsonb_typeof(item->'payload') <> 'object' THEN
        RAISE EXCEPTION 'narrative placement payload must be an object' USING ERRCODE = 'SB091';
      END IF;
    ELSIF item->>'kind' = 'section_placeholder' THEN
      -- CORE-06.11: reserved reference shape so future versioned Sections
      -- can be named without Template inheritance.
      PERFORM internal.assert_sheet_definition_object(
        item,
        ARRAY['id','kind','order','key','label'],
        ARRAY['id','kind','order','key','label'],
        'placements.section'
      );
      IF item->>'key' !~ '^[a-z][a-z0-9_]{0,59}$'
         OR length(btrim(item->>'label')) NOT BETWEEN 1 AND 200 THEN
        RAISE EXCEPTION 'invalid Template section placeholder' USING ERRCODE = 'SB091';
      END IF;
    ELSE
      PERFORM internal.assert_sheet_definition_object(
        item,
        ARRAY['id','kind','order','definitionVersionId','parameterMappings'],
        ARRAY['id','kind','order','definitionVersionId','parameterMappings','title'],
        'placements.sheet'
      );
      IF item ? 'title' AND (jsonb_typeof(item->'title') <> 'string' OR length(btrim(item->>'title')) > 200) THEN
        RAISE EXCEPTION 'invalid Sheet placement title' USING ERRCODE = 'SB091';
      END IF;
      SELECT * INTO version_row
        FROM api.sheet_definition_versions definition_version
        WHERE definition_version.id = internal.sheet_definition_uuid(
          item->>'definitionVersionId','placements.definitionVersionId'
        );
      IF version_row.id IS NULL OR version_row.lifecycle <> 'published' THEN
        RAISE EXCEPTION 'Sheet placement must pin a published Sheet Definition Version' USING ERRCODE = 'SB091';
      END IF;
      SELECT * INTO definition FROM api.sheet_definitions sheet_def
        WHERE sheet_def.id = version_row.definition_id;
      IF definition.workspace_id IS DISTINCT FROM p_workspace_id OR definition.lifecycle <> 'active' THEN
        RAISE EXCEPTION 'Sheet Definition Version must belong to this workspace' USING ERRCODE = 'SB091';
      END IF;
      IF jsonb_typeof(item->'parameterMappings') <> 'array'
         OR jsonb_array_length(item->'parameterMappings') > 64 THEN
        RAISE EXCEPTION 'invalid parameterMappings' USING ERRCODE = 'SB091';
      END IF;
      FOR mapping IN SELECT value FROM jsonb_array_elements(item->'parameterMappings') LOOP
        PERFORM internal.assert_sheet_definition_object(
          mapping,
          ARRAY['templateParameterId','definitionParameterId'],
          ARRAY['templateParameterId','definitionParameterId'],
          'parameterMappings'
        );
        IF (mapping->>'templateParameterId') <> ALL(parameter_ids) THEN
          RAISE EXCEPTION 'parameter mapping names an unknown Template parameter' USING ERRCODE = 'SB091';
        END IF;
        SELECT value INTO parameter
          FROM jsonb_array_elements(p_config->'parameters') value
          WHERE value->>'id' = mapping->>'templateParameterId';
        SELECT value INTO def_param
          FROM jsonb_array_elements(coalesce(version_row.configuration->'parameters','[]'::jsonb)) value
          WHERE value->>'id' = mapping->>'definitionParameterId';
        IF def_param IS NULL THEN
          RAISE EXCEPTION 'parameter mapping names an unknown Sheet Definition parameter' USING ERRCODE = 'SB091';
        END IF;
        IF parameter->'type' IS DISTINCT FROM def_param->'type' THEN
          RAISE EXCEPTION 'Template parameter type must match the mapped Definition parameter' USING ERRCODE = 'SB091';
        END IF;
      END LOOP;
      FOR def_param IN SELECT value FROM jsonb_array_elements(coalesce(version_row.configuration->'parameters','[]'::jsonb)) LOOP
        IF def_param->>'required' = 'true' THEN
          mapped := EXISTS (
            SELECT 1 FROM jsonb_array_elements(item->'parameterMappings') map_row
            WHERE map_row->>'definitionParameterId' = def_param->>'id'
          );
          IF NOT mapped THEN
            RAISE EXCEPTION 'required Sheet Definition parameter % is unmapped', def_param->>'id'
              USING ERRCODE = 'SB091';
          END IF;
        END IF;
      END LOOP;
    END IF;
  END LOOP;
END
$_$;
--> statement-breakpoint
ALTER FUNCTION internal.validate_notebook_template_configuration(p_workspace_id uuid, p_config jsonb) OWNER TO migrator;
--> statement-breakpoint
CREATE FUNCTION internal.validate_parameter(p_parameter jsonb) RETURNS void
    LANGUAGE plpgsql IMMUTABLE
    SET search_path TO ''
    AS $_$
DECLARE type_spec jsonb; contract jsonb; constraints jsonb; value_type text; item jsonb;
BEGIN
  PERFORM internal.assert_sheet_definition_object(
    p_parameter,ARRAY['id','key','label','required','type','constraints'],
    ARRAY['id','key','label','required','type','defaultValue','constraints'],'parameter');
  PERFORM internal.sheet_definition_uuid(p_parameter->>'id','parameter.id');
  IF p_parameter->>'key' !~ '^[a-z][a-z0-9_]{0,59}$'
     OR length(btrim(p_parameter->>'label')) NOT BETWEEN 1 AND 200
     OR jsonb_typeof(p_parameter->'required') IS DISTINCT FROM 'boolean'
     OR jsonb_typeof(p_parameter->'constraints') IS DISTINCT FROM 'object'
  THEN RAISE EXCEPTION 'invalid Parameter identity or metadata' USING ERRCODE='SB071'; END IF;
  type_spec:=p_parameter->'type'; constraints:=p_parameter->'constraints';
  IF jsonb_typeof(type_spec) IS DISTINCT FROM 'object' OR type_spec->>'kind' NOT IN ('scalar','record','dataset','dataset-version')
  THEN RAISE EXCEPTION 'invalid Parameter type' USING ERRCODE='SB071'; END IF;
  IF type_spec->>'kind'='scalar' THEN
    PERFORM internal.assert_sheet_definition_object(type_spec,ARRAY['kind','valueType'],ARRAY['kind','valueType'],'parameter.type');
    value_type:=type_spec->>'valueType';
    IF value_type NOT IN ('text','integer','decimal','boolean','date','timestamp','category','reference')
    THEN RAISE EXCEPTION 'invalid scalar Parameter type' USING ERRCODE='SB071'; END IF;
    PERFORM internal.assert_sheet_definition_object(constraints,'{}',ARRAY['min','max','minLength','maxLength','pattern','allowedValues'],'parameter.constraints');
    IF (constraints?'min' AND NOT internal.sheet_definition_scalar_matches('decimal',constraints->'min')) OR (constraints?'max' AND NOT internal.sheet_definition_scalar_matches('decimal',constraints->'max'))
       OR (constraints?'minLength' AND (jsonb_typeof(constraints->'minLength')<>'number' OR (constraints->>'minLength')::numeric<>trunc((constraints->>'minLength')::numeric) OR (constraints->>'minLength')::numeric NOT BETWEEN 0 AND 100000))
       OR (constraints?'maxLength' AND (jsonb_typeof(constraints->'maxLength')<>'number' OR (constraints->>'maxLength')::numeric<>trunc((constraints->>'maxLength')::numeric) OR (constraints->>'maxLength')::numeric NOT BETWEEN 0 AND 100000))
       OR (constraints?'pattern' AND (jsonb_typeof(constraints->'pattern')<>'string' OR length(constraints->>'pattern')>1000))
       OR (constraints?'allowedValues' AND (jsonb_typeof(constraints->'allowedValues')<>'array' OR jsonb_array_length(constraints->'allowedValues')>256))
    THEN RAISE EXCEPTION 'invalid scalar Parameter constraints' USING ERRCODE='SB071'; END IF;
    IF value_type NOT IN ('integer','decimal') AND (constraints?'min' OR constraints?'max')
       OR value_type<>'text' AND (constraints?'minLength' OR constraints?'maxLength' OR constraints?'pattern')
    THEN RAISE EXCEPTION 'scalar Parameter constraint does not apply to its type' USING ERRCODE='SB071'; END IF;
    IF constraints?'min' AND constraints?'max' AND (constraints->>'min')::numeric>(constraints->>'max')::numeric
       OR constraints?'minLength' AND constraints?'maxLength' AND (constraints->>'minLength')::integer>(constraints->>'maxLength')::integer
    THEN RAISE EXCEPTION 'invalid scalar Parameter constraint bounds' USING ERRCODE='SB071'; END IF;
    IF constraints?'pattern' THEN
      BEGIN
        PERFORM '' ~ (constraints->>'pattern');
      EXCEPTION WHEN invalid_regular_expression THEN
        RAISE EXCEPTION 'invalid scalar Parameter regular expression' USING ERRCODE='SB071';
      END;
    END IF;
    IF p_parameter?'defaultValue' AND NOT internal.sheet_definition_scalar_matches(value_type,p_parameter->'defaultValue')
    THEN RAISE EXCEPTION 'scalar Parameter default does not match its type' USING ERRCODE='SB071'; END IF;
    IF constraints?'allowedValues' THEN
      FOR item IN SELECT value FROM jsonb_array_elements(constraints->'allowedValues') LOOP
        IF NOT internal.sheet_definition_scalar_matches(value_type,item) THEN RAISE EXCEPTION 'allowed scalar value does not match its type' USING ERRCODE='SB071'; END IF;
      END LOOP;
    END IF;
    IF p_parameter?'defaultValue' AND NOT internal.scalar_parameter_satisfies(value_type,p_parameter->'defaultValue',constraints)
    THEN RAISE EXCEPTION 'scalar Parameter default violates its constraints' USING ERRCODE='SB071'; END IF;
  ELSIF type_spec->>'kind'='record' THEN
    PERFORM internal.assert_sheet_definition_object(type_spec,ARRAY['kind','modelKey'],ARRAY['kind','modelKey'],'parameter.type');
    IF type_spec->>'modelKey' !~ '^[a-z][a-z0-9_]{0,59}$' THEN RAISE EXCEPTION 'invalid Record Model contract' USING ERRCODE='SB071'; END IF;
    IF p_parameter?'defaultValue' OR constraints<>'{}'::jsonb THEN RAISE EXCEPTION 'object Parameters cannot have defaults or scalar constraints' USING ERRCODE='SB071'; END IF;
  ELSE
    PERFORM internal.assert_sheet_definition_object(type_spec,ARRAY['kind','contract'],ARRAY['kind','contract'],'parameter.type');
    contract:=type_spec->'contract';
    IF contract->>'mode'='exact' THEN
      PERFORM internal.assert_sheet_definition_object(contract,ARRAY['mode','schemaVersionId'],ARRAY['mode','schemaVersionId'],'parameter.type.contract');
      PERFORM internal.sheet_definition_uuid(contract->>'schemaVersionId','parameter.type.contract.schemaVersionId');
    ELSIF contract->>'mode'='lineage' THEN
      PERFORM internal.assert_sheet_definition_object(contract,ARRAY['mode','baselineSchemaVersionId'],ARRAY['mode','baselineSchemaVersionId'],'parameter.type.contract');
      PERFORM internal.sheet_definition_uuid(contract->>'baselineSchemaVersionId','parameter.type.contract.baselineSchemaVersionId');
    ELSIF contract->>'mode'='semantic' THEN
      PERFORM internal.assert_sheet_definition_object(contract,ARRAY['mode','requiredFieldIds'],ARRAY['mode','baselineSchemaVersionId','requiredFieldIds'],'parameter.type.contract');
      IF contract?'baselineSchemaVersionId' THEN PERFORM internal.sheet_definition_uuid(contract->>'baselineSchemaVersionId','parameter.type.contract.baselineSchemaVersionId'); END IF;
      IF jsonb_typeof(contract->'requiredFieldIds')<>'array' OR jsonb_array_length(contract->'requiredFieldIds') NOT BETWEEN 1 AND 64
         OR EXISTS(SELECT 1 FROM jsonb_array_elements_text(contract->'requiredFieldIds') x GROUP BY x HAVING count(*)>1)
      THEN RAISE EXCEPTION 'invalid semantic Dataset contract' USING ERRCODE='SB071'; END IF;
      FOR item IN SELECT value FROM jsonb_array_elements(contract->'requiredFieldIds') LOOP PERFORM internal.sheet_definition_uuid(item#>>'{}','parameter.type.contract.requiredFieldIds'); END LOOP;
    ELSE RAISE EXCEPTION 'invalid Dataset Parameter contract' USING ERRCODE='SB071'; END IF;
    IF p_parameter?'defaultValue' OR constraints<>'{}'::jsonb THEN RAISE EXCEPTION 'object Parameters cannot have defaults or scalar constraints' USING ERRCODE='SB071'; END IF;
  END IF;
END $_$;
--> statement-breakpoint
ALTER FUNCTION internal.validate_parameter(p_parameter jsonb) OWNER TO migrator;
--> statement-breakpoint
CREATE FUNCTION internal.validate_record_properties() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $_$
DECLARE
  v_def record;
  v_value jsonb;
  v_raw text;
  v_enum text[];
BEGIN
  -- Only kinds that use configurable properties have definitions.
  IF NEW.kind NOT IN ('sample', 'material', 'protocol_template') THEN
    RETURN NEW;
  END IF;
  IF NEW.properties IS NULL THEN
    NEW.properties := '{}'::jsonb;
  END IF;

  FOR v_def IN
    SELECT field_name, logical_type, nullable, validation
      FROM "api"."record_field_definitions"
      WHERE workspace_id = NEW.workspace_id
        AND kind = NEW.kind
        AND lifecycle = 'active'
  LOOP
    v_value := NEW.properties -> v_def.field_name;
    -- A missing key is null for validation purposes.
    IF jsonb_typeof(v_value) = 'null' OR v_value IS NULL THEN
      IF NOT v_def.nullable THEN
        RAISE EXCEPTION 'property "%" is required for kind %',
          v_def.field_name, NEW.kind USING ERRCODE = 'SB005';
      END IF;
      CONTINUE;
    END IF;

    -- Type-check the value against the logical_type.
    v_raw := v_value #>> '{}';
    CASE v_def.logical_type
      WHEN 'text' THEN
        IF jsonb_typeof(v_value) <> 'string' THEN
          RAISE EXCEPTION 'property "%" must be text', v_def.field_name
            USING ERRCODE = 'SB005';
        END IF;
      WHEN 'integer' THEN
        IF jsonb_typeof(v_value) <> 'number'
           OR v_raw !~ '^-?[0-9]+$' THEN
          RAISE EXCEPTION 'property "%" must be an integer', v_def.field_name
            USING ERRCODE = 'SB005';
        END IF;
      WHEN 'decimal' THEN
        IF jsonb_typeof(v_value) <> 'number'
           OR v_raw !~ '^-?[0-9]+(\.[0-9]+)?$' THEN
          RAISE EXCEPTION 'property "%" must be a decimal number', v_def.field_name
            USING ERRCODE = 'SB005';
        END IF;
      WHEN 'boolean' THEN
        IF jsonb_typeof(v_value) <> 'boolean' THEN
          RAISE EXCEPTION 'property "%" must be a boolean', v_def.field_name
            USING ERRCODE = 'SB005';
        END IF;
      WHEN 'date' THEN
        IF jsonb_typeof(v_value) <> 'string'
           OR v_raw !~ '^[0-9]{4}-[0-9]{2}-[0-9]{2}$'
           OR v_raw::date IS NULL THEN
          RAISE EXCEPTION 'property "%" must be a date (YYYY-MM-DD)', v_def.field_name
            USING ERRCODE = 'SB005';
        END IF;
      WHEN 'timestamp' THEN
        IF jsonb_typeof(v_value) <> 'string' THEN
          RAISE EXCEPTION 'property "%" must be a timestamp', v_def.field_name
            USING ERRCODE = 'SB005';
        END IF;
      WHEN 'category' THEN
        IF jsonb_typeof(v_value) <> 'string' THEN
          RAISE EXCEPTION 'property "%" must be a category string', v_def.field_name
            USING ERRCODE = 'SB005';
        END IF;
        v_enum := COALESCE(
          ARRAY(SELECT jsonb_array_elements_text(v_def.validation -> 'enum')),
          ARRAY[]::text[]
        );
        IF array_length(v_enum, 1) IS NOT NULL AND NOT (v_raw = ANY(v_enum)) THEN
          RAISE EXCEPTION 'property "%" must be one of: %',
            v_def.field_name, array_to_string(v_enum, ', ')
            USING ERRCODE = 'SB005';
        END IF;
      ELSE
        RAISE EXCEPTION 'unknown logical_type "%" for field "%"',
          v_def.logical_type, v_def.field_name USING ERRCODE = 'SB005';
    END CASE;
  END LOOP;

  RETURN NEW;
END;
$_$;
--> statement-breakpoint
ALTER FUNCTION internal.validate_record_properties() OWNER TO migrator;
--> statement-breakpoint
CREATE FUNCTION internal.validate_sample_release_rules(p_rules jsonb) RETURNS void
    LANGUAGE plpgsql IMMUTABLE
    SET search_path TO ''
    AS $$
DECLARE
  v_rule jsonb;
  v_kind text;
BEGIN
  IF p_rules IS NULL OR jsonb_typeof(p_rules) <> 'array' THEN
    RAISE EXCEPTION 'release rules must be a JSON array' USING ERRCODE = '22023';
  END IF;
  IF jsonb_array_length(p_rules) > 64 THEN
    RAISE EXCEPTION 'release rules must contain at most 64 checks' USING ERRCODE = '22023';
  END IF;
  FOR v_rule IN SELECT value FROM jsonb_array_elements(p_rules) LOOP
    IF jsonb_typeof(v_rule) <> 'object' THEN
      RAISE EXCEPTION 'each release rule must be an object' USING ERRCODE = '22023';
    END IF;
    v_kind := v_rule ->> 'kind';
    IF v_kind NOT IN ('no_result','min_measurements','measurement_required','measurement_range') THEN
      RAISE EXCEPTION 'unknown release rule kind %', coalesce(v_kind, '<null>') USING ERRCODE = '22023';
    END IF;
    IF v_kind = 'no_result' AND nullif(btrim(coalesce(v_rule ->> 'result','')), '') IS NULL THEN
      RAISE EXCEPTION 'no_result rule requires a result' USING ERRCODE = '22023';
    END IF;
    IF v_kind IN ('measurement_required','measurement_range')
       AND nullif(btrim(coalesce(v_rule ->> 'measurement','')), '') IS NULL THEN
      RAISE EXCEPTION '% rule requires a measurement', v_kind USING ERRCODE = '22023';
    END IF;
    IF v_kind = 'min_measurements'
       AND coalesce(nullif(v_rule ->> 'count','')::integer, 0) < 1 THEN
      RAISE EXCEPTION 'min_measurements rule requires a positive count' USING ERRCODE = '22023';
    END IF;
    IF v_kind = 'measurement_range'
       AND NOT (v_rule ? 'min' OR v_rule ? 'max') THEN
      RAISE EXCEPTION 'measurement_range rule requires a min or max' USING ERRCODE = '22023';
    END IF;
  END LOOP;
END;
$$;
--> statement-breakpoint
ALTER FUNCTION internal.validate_sample_release_rules(p_rules jsonb) OWNER TO migrator;
--> statement-breakpoint
CREATE FUNCTION internal.validate_sheet_comment_shape(p_kind text, p_target jsonb) RETURNS uuid
    LANGUAGE plpgsql IMMUTABLE
    SET search_path TO ''
    AS $_$
DECLARE instance_id uuid; n_rows integer; n_fields integer; identity text;
BEGIN
  IF p_kind NOT IN ('sheet_cell','sheet_row','sheet_range')
     OR jsonb_typeof(p_target) IS DISTINCT FROM 'object'
     OR p_target-ARRAY['instanceId','rowKeys','fieldIds'] <> '{}'::jsonb
     OR jsonb_typeof(p_target->'rowKeys') IS DISTINCT FROM 'array'
     OR jsonb_typeof(p_target->'fieldIds') IS DISTINCT FROM 'array' THEN
    RAISE EXCEPTION 'invalid Sheet comment anchor' USING ERRCODE='22023';
  END IF;
  IF EXISTS(SELECT 1 FROM jsonb_array_elements((p_target->'rowKeys')||(p_target->'fieldIds')) v WHERE jsonb_typeof(v) IS DISTINCT FROM 'string') THEN
    RAISE EXCEPTION 'Sheet comment identities must be strings' USING ERRCODE='22023';
  END IF;
  instance_id:=internal.sheet_definition_uuid(p_target->>'instanceId','comment instance');
  n_rows:=jsonb_array_length(p_target->'rowKeys');
  n_fields:=jsonb_array_length(p_target->'fieldIds');
  IF n_rows NOT BETWEEN 1 AND 500 OR n_fields>256
     OR (p_kind='sheet_cell' AND (n_rows<>1 OR n_fields<>1))
     OR (p_kind='sheet_row' AND (n_rows<>1 OR n_fields<>0))
     OR (p_kind='sheet_range' AND n_fields=0)
     OR n_rows<>(SELECT count(DISTINCT value) FROM jsonb_array_elements(p_target->'rowKeys'))
     OR n_fields<>(SELECT count(DISTINCT value) FROM jsonb_array_elements(p_target->'fieldIds')) THEN
    RAISE EXCEPTION 'invalid Sheet comment cardinality' USING ERRCODE='22023';
  END IF;
  FOR identity IN SELECT value FROM jsonb_array_elements_text(p_target->'rowKeys') LOOP
    IF identity !~* '^[0-9a-f]{8}-[0-9a-f]{4}-[1-8][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$'
       AND identity !~ '^sb-row-v1:[0-9a-f]{64}$' THEN
      RAISE EXCEPTION 'Sheet comment requires stable row identities' USING ERRCODE='22023';
    END IF;
  END LOOP;
  FOR identity IN SELECT value FROM jsonb_array_elements_text(p_target->'fieldIds') LOOP
    PERFORM internal.sheet_definition_uuid(identity,'comment field');
  END LOOP;
  RETURN instance_id;
END $_$;
--> statement-breakpoint
ALTER FUNCTION internal.validate_sheet_comment_shape(p_kind text, p_target jsonb) OWNER TO migrator;
