CREATE FUNCTION internal.validate_sheet_instance_state_core037(p_state jsonb) RETURNS void
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
DECLARE identity jsonb:=p_state->'resolvedRowIdentity'; identity_column text; logical_type text;
BEGIN
  PERFORM internal.validate_sheet_instance_state_core034(p_state-'resolvedRowIdentity');
  IF identity IS NOT NULL THEN
    PERFORM internal.assert_sheet_definition_object(identity,ARRAY['formatVersion','kind','columnIds','logicalTypes','sourceBindingId','sourceFieldId'],ARRAY['formatVersion','kind','columnIds','logicalTypes','sourceBindingId','sourceFieldId'],'resolvedRowIdentity');
    IF identity->>'formatVersion'<>'1' OR identity->>'kind' NOT IN ('source','composite','local') OR jsonb_typeof(identity->'columnIds')<>'array' OR jsonb_typeof(identity->'logicalTypes')<>'array' OR jsonb_array_length(identity->'columnIds')<>jsonb_array_length(identity->'logicalTypes') OR jsonb_array_length(identity->'columnIds') NOT BETWEEN 1 AND 8 OR EXISTS(SELECT 1 FROM jsonb_array_elements_text(identity->'columnIds') x GROUP BY x HAVING count(*)>1) OR jsonb_typeof(identity->'sourceBindingId') NOT IN ('string','null') OR jsonb_typeof(identity->'sourceFieldId') NOT IN ('string','null') THEN RAISE EXCEPTION 'invalid resolved row identity' USING ERRCODE='SB073'; END IF;
    FOR identity_column IN SELECT value FROM jsonb_array_elements_text(identity->'columnIds') LOOP PERFORM internal.sheet_definition_uuid(identity_column,'resolvedRowIdentity.columnIds'); END LOOP;
    FOR logical_type IN SELECT value FROM jsonb_array_elements_text(identity->'logicalTypes') LOOP IF logical_type NOT IN ('text','integer','decimal','boolean','date','timestamp','category','reference') THEN RAISE EXCEPTION 'invalid resolved row identity logical type' USING ERRCODE='SB073'; END IF; END LOOP;
    IF (identity->>'kind'='source' AND (jsonb_array_length(identity->'columnIds')<>1 OR jsonb_typeof(identity->'sourceBindingId')<>'string' OR jsonb_typeof(identity->'sourceFieldId')<>'string')) OR (identity->>'kind' IN ('composite','local') AND (identity->'sourceBindingId' IS DISTINCT FROM 'null'::jsonb OR identity->'sourceFieldId' IS DISTINCT FROM 'null'::jsonb)) OR (identity->>'kind'='local' AND identity->'logicalTypes'->>0<>'reference') THEN RAISE EXCEPTION 'invalid row identity provenance' USING ERRCODE='SB073'; END IF;
    IF identity->>'kind'='source' THEN PERFORM internal.sheet_definition_uuid(identity->>'sourceBindingId','resolvedRowIdentity.sourceBindingId'); PERFORM internal.sheet_definition_uuid(identity->>'sourceFieldId','resolvedRowIdentity.sourceFieldId'); END IF;
  END IF;
END $$;
--> statement-breakpoint
ALTER FUNCTION internal.validate_sheet_instance_state_core037(p_state jsonb) OWNER TO migrator;
--> statement-breakpoint
CREATE FUNCTION internal.validate_sheet_instance_state_core038(p_state jsonb) RETURNS void
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $_$
DECLARE row_key text; row_value jsonb; field_id text; field jsonb; value jsonb;
BEGIN
  PERFORM internal.validate_sheet_instance_state_core037(jsonb_set(p_state,'{localValues}','{}'::jsonb));
  FOR row_key,row_value IN SELECT * FROM jsonb_each(p_state->'localValues') LOOP
    IF row_key !~ '^sb-row-v1:[0-9a-f]{64}$' AND row_key !~* '^[0-9a-f]{8}-[0-9a-f]{4}-[1-8][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$' THEN RAISE EXCEPTION 'invalid local row key' USING ERRCODE='SB073'; END IF;
    IF jsonb_typeof(row_value)<>'object' OR (SELECT count(*) FROM jsonb_object_keys(row_value))>256 THEN RAISE EXCEPTION 'invalid local value row' USING ERRCODE='SB073'; END IF;
    FOR field_id,value IN SELECT * FROM jsonb_each(row_value) LOOP
      SELECT item INTO field FROM jsonb_array_elements(p_state->'localFields') item WHERE item->>'fieldId'=field_id;
      IF field IS NULL OR internal.sheet_local_cell_error(NULL,field,value) IS NOT NULL AND field->>'logicalType'<>'reference' THEN RAISE EXCEPTION 'invalid or unknown local value' USING ERRCODE='SB073'; END IF;
    END LOOP;
  END LOOP;
END $_$;
--> statement-breakpoint
ALTER FUNCTION internal.validate_sheet_instance_state_core038(p_state jsonb) OWNER TO migrator;
--> statement-breakpoint
CREATE FUNCTION internal.validate_sheet_presentation_queries(p_presentation jsonb, p_column_ids text[], p_code text) RETURNS void
    LANGUAGE plpgsql IMMUTABLE
    SET search_path TO ''
    AS $$
DECLARE item jsonb; column_id text;
BEGIN
  IF p_presentation ? 'filters' THEN
    IF jsonb_typeof(p_presentation->'filters')<>'array' OR jsonb_array_length(p_presentation->'filters')>32 THEN RAISE EXCEPTION 'invalid bounded presentation filters' USING ERRCODE=p_code; END IF;
    FOR item IN SELECT value FROM jsonb_array_elements(p_presentation->'filters') LOOP
      PERFORM internal.assert_sheet_definition_object(item,ARRAY['columnId','operator'],ARRAY['columnId','operator','value'],'presentation.filters');
      column_id:=internal.sheet_definition_uuid(item->>'columnId','presentation filter column')::text;
      IF (p_column_ids IS NOT NULL AND column_id<>ALL(p_column_ids)) OR item->>'operator' NOT IN ('equals','not-equals','is-empty','is-not-empty')
         OR ((item->>'operator' IN ('is-empty','is-not-empty')) <> NOT (item ? 'value'))
         OR (item ? 'value' AND jsonb_typeof(item->'value') NOT IN ('string','number','boolean','null')) THEN RAISE EXCEPTION 'invalid presentation filter' USING ERRCODE=p_code; END IF;
    END LOOP;
  END IF;
  IF p_presentation ? 'sorts' THEN
    IF jsonb_typeof(p_presentation->'sorts')<>'array' OR jsonb_array_length(p_presentation->'sorts')>8 THEN RAISE EXCEPTION 'invalid bounded presentation sorts' USING ERRCODE=p_code; END IF;
    FOR item IN SELECT value FROM jsonb_array_elements(p_presentation->'sorts') LOOP
      PERFORM internal.assert_sheet_definition_object(item,ARRAY['columnId','direction'],ARRAY['columnId','direction'],'presentation.sorts');
      column_id:=internal.sheet_definition_uuid(item->>'columnId','presentation sort column')::text;
      IF (p_column_ids IS NOT NULL AND column_id<>ALL(p_column_ids)) OR item->>'direction' NOT IN ('asc','desc') THEN RAISE EXCEPTION 'invalid presentation sort' USING ERRCODE=p_code; END IF;
    END LOOP;
  END IF;
END $$;
--> statement-breakpoint
ALTER FUNCTION internal.validate_sheet_presentation_queries(p_presentation jsonb, p_column_ids text[], p_code text) OWNER TO migrator;
