CREATE FUNCTION internal.validate_user_profile() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $_$
BEGIN
  IF NEW.initials IS NOT NULL THEN
    NEW.initials := upper(btrim(NEW.initials));
    IF NEW.initials !~ '^[A-Z]{1,4}$' THEN
      RAISE EXCEPTION 'initials must be one to four letters' USING ERRCODE = '22023';
    END IF;
  END IF;
  IF NEW.job_title IS NOT NULL THEN
    NEW.job_title := nullif(btrim(NEW.job_title), '');
    IF length(coalesce(NEW.job_title, '')) > 120 THEN
      RAISE EXCEPTION 'job title is too long' USING ERRCODE = '22023';
    END IF;
  END IF;
  IF NEW.timezone IS NOT NULL THEN
    NEW.timezone := btrim(NEW.timezone);
    IF NOT EXISTS (SELECT 1 FROM pg_catalog.pg_timezone_names z WHERE z.name = NEW.timezone) THEN
      RAISE EXCEPTION 'unknown time zone' USING ERRCODE = '22023';
    END IF;
  END IF;
  RETURN NEW;
END $_$;
--> statement-breakpoint
ALTER FUNCTION internal.validate_user_profile() OWNER TO migrator;
--> statement-breakpoint
CREATE FUNCTION internal.validate_versioned_model_fields(p_workspace uuid, p_model text, p_new jsonb, p_old jsonb, p_version uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $_$
DECLARE d record; k text; v jsonb; out jsonb:=coalesce(p_new,'{}'); target api.records;
BEGIN
 IF jsonb_typeof(out)<>'object' THEN RAISE EXCEPTION 'custom_fields must be an object' USING ERRCODE='22023'; END IF;
 FOR d IN SELECT * FROM internal.record_model_fields(p_workspace,p_model,p_version)
   WHERE workspace_id=p_workspace AND kind=p_model AND lifecycle='retired' AND coalesce(p_old,'{}') ? field_name
 LOOP
   IF NOT out ? d.field_name OR out->d.field_name IS DISTINCT FROM p_old->d.field_name THEN
     RAISE EXCEPTION 'retired custom field % is immutable',d.field_name USING ERRCODE='SB070';
   END IF;
 END LOOP;
 FOR k IN SELECT jsonb_object_keys(out) LOOP
   IF EXISTS(SELECT 1 FROM api.model_base_fields WHERE model_key=p_model AND field_key=k) THEN RAISE EXCEPTION 'protected custom field: %',k USING ERRCODE='SB070'; END IF;
   SELECT * INTO d FROM internal.record_model_fields(p_workspace,p_model,p_version) WHERE workspace_id=p_workspace AND kind=p_model AND field_name=k;
   IF NOT FOUND THEN RAISE EXCEPTION 'unknown custom field: %',k USING ERRCODE='SB070'; END IF;
   IF d.lifecycle NOT IN ('active','backfilling') THEN
     IF NOT coalesce(p_old,'{}') ? k OR p_old->k IS DISTINCT FROM out->k THEN RAISE EXCEPTION 'retired custom field: %',k USING ERRCODE='SB070'; END IF;
     CONTINUE;
   END IF;
   v:=out->k;
   IF v='null' AND NOT d.nullable THEN RAISE EXCEPTION 'field % may not be null',k USING ERRCODE='SB071'; END IF;
   IF v='null' THEN CONTINUE; END IF;
   IF (d.logical_type='text' AND jsonb_typeof(v)<>'string') OR
      (d.logical_type='integer' AND (jsonb_typeof(v)<>'number' OR (v#>>'{}') !~ '^-?[0-9]+$')) OR
      (d.logical_type='decimal' AND jsonb_typeof(v)<>'number') OR
      (d.logical_type='boolean' AND jsonb_typeof(v)<>'boolean') OR
      (d.logical_type IN ('date','timestamp','category','reference') AND jsonb_typeof(v)<>'string') THEN
      RAISE EXCEPTION 'invalid % value for %',d.logical_type,k USING ERRCODE='SB071'; END IF;
   IF d.logical_type='date' THEN BEGIN PERFORM (v#>>'{}')::date; EXCEPTION WHEN others THEN RAISE EXCEPTION 'invalid date' USING ERRCODE='SB071'; END; END IF;
   IF d.logical_type='timestamp' THEN BEGIN PERFORM (v#>>'{}')::timestamptz; EXCEPTION WHEN others THEN RAISE EXCEPTION 'invalid timestamp' USING ERRCODE='SB071'; END; END IF;
   IF d.logical_type='text' AND ((d.validation ? 'minLength' AND length(v#>>'{}')<(d.validation->>'minLength')::integer) OR (d.validation ? 'maxLength' AND length(v#>>'{}')>(d.validation->>'maxLength')::integer) OR (d.validation ? 'regex' AND NOT (v#>>'{}' ~ (d.validation->>'regex')))) THEN RAISE EXCEPTION 'text validation failed for %',k USING ERRCODE='SB071'; END IF;
   IF d.logical_type IN ('integer','decimal') AND ((d.validation ? 'min' AND (v#>>'{}')::numeric<(d.validation->>'min')::numeric) OR (d.validation ? 'max' AND (v#>>'{}')::numeric>(d.validation->>'max')::numeric)) THEN RAISE EXCEPTION 'numeric validation failed for %',k USING ERRCODE='SB071'; END IF;
   IF d.logical_type='category' AND NOT EXISTS(SELECT 1 FROM internal.record_model_options(p_version,d.id) o WHERE o.definition_id=d.id AND o.key=v#>>'{}' AND (o.lifecycle='active' OR p_old->k IS NOT DISTINCT FROM v)) THEN RAISE EXCEPTION 'inactive category option' USING ERRCODE='SB071'; END IF;
   IF d.logical_type='reference' THEN
     IF d.validation->>'targetModelKey' IS NULL THEN RAISE EXCEPTION 'reference targetModelKey required' USING ERRCODE='SB071'; END IF;
     BEGIN
       SELECT r.* INTO target FROM api.records r JOIN (SELECT key,record_kind FROM api.model_kinds UNION ALL SELECT key,key FROM api.record_models WHERE workspace_id=p_workspace) m ON m.record_kind=r.kind
        WHERE r.id=(v#>>'{}')::uuid AND r.workspace_id=p_workspace AND m.key=d.validation->>'targetModelKey'
          AND (r.deleted_at IS NULL OR p_old->k IS NOT DISTINCT FROM v);
     EXCEPTION WHEN invalid_text_representation THEN RAISE EXCEPTION 'invalid reference' USING ERRCODE='SB071'; END;
     IF NOT FOUND THEN RAISE EXCEPTION 'invalid reference' USING ERRCODE='SB071'; END IF;
   END IF;
 END LOOP;
 FOR d IN SELECT * FROM internal.record_model_fields(p_workspace,p_model,p_version) WHERE workspace_id=p_workspace AND kind=p_model AND lifecycle='active' LOOP
   IF p_old IS NULL AND NOT out ? d.field_name AND d.default_value IS NOT NULL THEN out:=out||jsonb_build_object(d.field_name,d.default_value); END IF;
   IF NOT d.nullable AND (NOT out ? d.field_name OR out->d.field_name='null') THEN RAISE EXCEPTION 'required field % missing',d.field_name USING ERRCODE='SB071'; END IF;
 END LOOP;
 RETURN out;
END $_$;
--> statement-breakpoint
ALTER FUNCTION internal.validate_versioned_model_fields(p_workspace uuid, p_model text, p_new jsonb, p_old jsonb, p_version uuid) OWNER TO migrator;
--> statement-breakpoint
CREATE FUNCTION internal.verify_audit_chain(p_workspace_id uuid) RETURNS TABLE(ok boolean, checked integer, first_bad_sequence bigint, first_bad_id uuid)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
  r record;
  v_previous text;
  v_expected text;
  v_checked integer := 0;
BEGIN
  FOR r IN SELECT * FROM api.change_events e WHERE e.workspace_id = p_workspace_id ORDER BY e.sequence LOOP
    v_expected := internal.audit_entry_hash(
      v_previous, r.workspace_id, r.sequence, r.entity_type, r.entity_uuid,
      r.operation, r.record_id, r.project_id, r.client_id, r.payload, r.created_at);
    v_checked := v_checked + 1;
    IF r.previous_hash IS DISTINCT FROM v_previous OR r.entry_hash IS DISTINCT FROM v_expected THEN
      RETURN QUERY SELECT false, v_checked, r.sequence, r.id;
      RETURN;
    END IF;
    v_previous := r.entry_hash;
  END LOOP;
  RETURN QUERY SELECT true, v_checked, NULL::bigint, NULL::uuid;
END $$;
--> statement-breakpoint
ALTER FUNCTION internal.verify_audit_chain(p_workspace_id uuid) OWNER TO migrator;
--> statement-breakpoint
CREATE FUNCTION internal.verify_signed_revisions(p_workspace_id uuid) RETURNS TABLE(ok boolean, checked integer, first_bad_signature_id uuid, first_bad_revision_id uuid)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
  r record;
  v_expected text;
  v_checked integer := 0;
BEGIN
  FOR r IN
    SELECT s.id AS signature_id, s.revision_id, s.revision_integrity_digest AS signed_digest,
           rev.canonical_snapshot, rev.integrity_digest AS stored_digest
      FROM api.signatures s
      JOIN api.revisions rev ON rev.id = s.revision_id
     WHERE s.workspace_id = p_workspace_id
     ORDER BY s.signed_at, s.id
  LOOP
    v_expected := internal.revision_integrity_digest(r.canonical_snapshot);
    v_checked := v_checked + 1;
    IF v_expected IS DISTINCT FROM r.signed_digest OR v_expected IS DISTINCT FROM r.stored_digest THEN
      RETURN QUERY SELECT false, v_checked, r.signature_id, r.revision_id;
      RETURN;
    END IF;
  END LOOP;
  RETURN QUERY SELECT true, v_checked, NULL::uuid, NULL::uuid;
END $$;
--> statement-breakpoint
ALTER FUNCTION internal.verify_signed_revisions(p_workspace_id uuid) OWNER TO migrator;
--> statement-breakpoint
CREATE FUNCTION internal.write_sheet_record_reference(p_workspace uuid, p_record_id uuid, p_target jsonb) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
  dataset api.datasets;
  existing_row api.dataset_rows;
  field api.dataset_schema_version_fields;
  v_row_id uuid;
  v_field_id uuid;
  instance api.sheet_instances;
  model_record api.records;
BEGIN
  IF jsonb_typeof(p_target) <> 'object' OR p_target->>'kind' IS NULL THEN
    RAISE EXCEPTION 'sheet write-back target is required' USING ERRCODE = '22023';
  END IF;
  IF p_target->>'kind' = 'dataset' THEN
    SELECT * INTO dataset FROM api.datasets
     WHERE id = (p_target->>'datasetId')::uuid AND workspace_id = p_workspace
     FOR UPDATE;
    IF dataset.id IS NULL OR dataset.lifecycle <> 'active' THEN
      RAISE EXCEPTION 'dataset write-back target denied' USING ERRCODE = '42501';
    END IF;
    IF dataset.revision <> (p_target->>'expectedDatasetRevision')::bigint THEN
      RAISE EXCEPTION 'stale dataset revision' USING ERRCODE = 'SB001';
    END IF;
    v_row_id := (p_target->>'rowId')::uuid;
    v_field_id := (p_target->>'fieldId')::uuid;
    SELECT * INTO existing_row FROM api.dataset_rows
     WHERE id = v_row_id AND dataset_id = dataset.id FOR UPDATE;
    IF existing_row.id IS NULL THEN
      RAISE EXCEPTION 'dataset row missing' USING ERRCODE = '22023';
    END IF;
    IF existing_row.revision <> (p_target->>'expectedRowRevision')::bigint THEN
      RAISE EXCEPTION 'stale row revision' USING ERRCODE = 'SB001';
    END IF;
    SELECT * INTO field FROM api.dataset_schema_version_fields
     WHERE schema_version_id = dataset.schema_version_id
       AND field_id = v_field_id AND lifecycle = 'active';
    IF field.id IS NULL OR field.logical_type <> 'reference' THEN
      RAISE EXCEPTION 'write-back field is not an active reference' USING ERRCODE = '22023';
    END IF;
    DELETE FROM api.dataset_row_values WHERE row_id = v_row_id AND field_id = v_field_id;
    INSERT INTO api.dataset_row_values (row_id, field_id, ordinal, reference_id)
    VALUES (v_row_id, v_field_id, 0, p_record_id);
    UPDATE api.dataset_rows SET revision = revision + 1, updated_at = now() WHERE id = v_row_id;
    UPDATE api.datasets SET revision = revision + 1, updated_at = now() WHERE id = dataset.id;
  ELSIF p_target->>'kind' = 'local' THEN
    PERFORM api.mutate_sheet_instance_local_state(
      (p_target->>'instanceId')::uuid,
      (p_target->>'expectedRevision')::bigint,
      gen_random_uuid(),
      '[]'::jsonb,
      jsonb_build_array(jsonb_build_object(
        'kind', 'composed',
        'rowKey', p_target->>'rowKey',
        'identityValues', p_target->'identityValues',
        'compositionOffset', coalesce((p_target->>'compositionOffset')::integer, 0)
      )),
      jsonb_build_array(jsonb_build_object(
        'rowKey', p_target->>'rowKey',
        'fieldId', p_target->>'fieldId',
        'value', to_jsonb(p_record_id::text)
      ))
    );
  ELSIF p_target->>'kind' = 'model' THEN
    SELECT * INTO model_record FROM api.records
     WHERE id = (p_target->>'recordId')::uuid AND workspace_id = p_workspace
     FOR UPDATE;
    IF model_record.id IS NULL THEN
      RAISE EXCEPTION 'model write-back record denied' USING ERRCODE = '42501';
    END IF;
    IF model_record.metadata_version <> (p_target->>'expectedMetadataVersion')::integer THEN
      RAISE EXCEPTION 'metadata version mismatch' USING ERRCODE = 'SB001';
    END IF;
    UPDATE api.records
       SET custom_fields = custom_fields || jsonb_build_object(p_target->>'fieldName', p_record_id::text),
           metadata_version = metadata_version + 1,
           updated_at = now(),
           updated_by_user_id = api.current_user_id()
     WHERE id = model_record.id;
  ELSE
    RAISE EXCEPTION 'unknown sheet write-back kind' USING ERRCODE = '22023';
  END IF;
END
$$;
--> statement-breakpoint
ALTER FUNCTION internal.write_sheet_record_reference(p_workspace uuid, p_record_id uuid, p_target jsonb) OWNER TO migrator;
