CREATE VIEW api.formula_results WITH (security_invoker='true', security_barrier='true') AS
 SELECT f.id AS formula_id,
    f.workspace_id,
    f.record_id,
    f.target_table_id,
    f.target_row_id,
    f.target_column_id,
    f.source_expression,
    'formula'::text AS cell_kind,
    false AS value_is_authoritative,
    f.status AS definition_status,
    f.version AS formula_version,
    r.calculation_input_revision AS current_input_revision,
        CASE
            WHEN (f.status = 'unsupported'::text) THEN 'unavailable'::text
            WHEN (c.formula_id IS NULL) THEN 'pending'::text
            WHEN ((c.formula_version <> f.version) OR (c.input_revision <> r.calculation_input_revision)) THEN 'stale'::text
            WHEN (c.status = 'completed'::text) THEN 'current'::text
            ELSE c.status
        END AS calculation_status,
        CASE
            WHEN ((c.status = 'completed'::text) AND (c.result_kind = 'value'::text) AND (c.formula_version = f.version) AND (c.input_revision = r.calculation_input_revision)) THEN c.value
            ELSE NULL::jsonb
        END AS calculated_value,
        CASE
            WHEN ((c.formula_version = f.version) AND (c.input_revision = r.calculation_input_revision)) THEN c.error_code
            ELSE NULL::text
        END AS calculation_error_code,
    c.input_revision AS cache_input_revision,
    c.schema_versions,
    c.engine_version,
    c.profile_fingerprint,
    c.runtime_fingerprint,
    c.calculated_at
   FROM ((api.formula_definitions f
     JOIN api.records r ON ((r.id = f.record_id)))
     LEFT JOIN internal.formula_result_cache c ON ((c.formula_id = f.id)));
--> statement-breakpoint
ALTER VIEW api.formula_results OWNER TO migrator;
