                            old_1_1_1.connector_id,
                                CASE
                                    WHEN ((old_1_1_1.kind = 'review_requested'::text) AND (old_1_1_1.revision_id IS NULL)) THEN ( SELECT rs.revision_id
                                       FROM api.review_submissions rs
                                      WHERE ((rs.record_id = old_1_1_1.record_id) AND (rs.state = 'submitted'::text) AND (api.current_user_id() = ANY (rs.assigned_reviewer_user_ids)))
