            old_1_1_1_1_1_1_1_1_1.created_at,
            NULL::text AS source_type,
            NULL::uuid AS source_id,
            NULL::uuid AS parser_version_id
           FROM ( SELECT 'review_requested'::text AS kind,
              r.id AS record_id,
              r.identifier,
              r.title,
              r.project_id,
              'Review requested'::text AS reason,
              NULL::timestamp with time zone AS due_at,
              'needs_action'::text AS state,
              rs.submitted_at AS created_at
             FROM (api.review_submissions rs
               JOIN api.records r ON ((r.id = rs.record_id)))
            WHERE ((rs.state = 'submitted'::text) AND (api.current_user_id() = ANY (rs.assigned_reviewer_user_ids)))
          UNION ALL
           SELECT 'run_failed'::text AS kind,
              NULL::uuid AS record_id,
              pd.key AS identifier,
              pd.name AS title,
              NULL::uuid AS project_id,
              COALESCE(pr.error_message, 'Pipeline run failed'::text) AS reason,
              NULL::timestamp with time zone AS due_at,
              'needs_action'::text AS state,
              pr.finished_at AS created_at
             FROM ((api.pipeline_runs pr
               JOIN api.pipeline_definition_versions pdv ON ((pdv.id = pr.definition_version_id)))
               JOIN api.pipeline_definitions pd ON ((pd.id = pdv.definition_id)))
            WHERE ((pr.status = 'failed'::text) AND (pd.created_by_user_id = api.current_user_id()))
          UNION ALL
