CREATE VIEW api.milestone_risks WITH (security_invoker='true') AS
 WITH conditions AS (
         SELECT d.task_id,
            count(*) AS total_count,
            count(*) FILTER (WHERE (d.status <> 'delivered'::text)) AS open_count
           FROM api.study_deliverables d
          GROUP BY d.task_id
        ), unfinished_dependencies AS (
         SELECT dep.successor_id AS task_id,
            count(*) AS unfinished_count,
            min(p.title) AS blocking_title
           FROM (api.study_task_dependencies dep
             JOIN api.study_tasks p ON (((p.id = dep.predecessor_id) AND (p.status <> 'completed'::text))))
          GROUP BY dep.successor_id
        ), base AS (
         SELECT t.id AS task_id,
            t.workspace_id,
            t.project_id,
            t.due_at,
            t.status,
            (COALESCE(c.total_count, (0)::bigint))::integer AS conditions_total,
            (COALESCE(c.open_count, (0)::bigint))::integer AS conditions_open,
            (COALESCE(u.unfinished_count, (0)::bigint))::integer AS unfinished_dependencies,
            u.blocking_title,
                CASE
                    WHEN (t.status = 'completed'::text) THEN 'done'::text
                    WHEN ((t.due_at IS NOT NULL) AND ((t.due_at)::date < CURRENT_DATE)) THEN 'late'::text
                    WHEN ((t.due_at IS NOT NULL) AND ((t.due_at)::date <= (CURRENT_DATE + 14)) AND ((COALESCE(c.open_count, (0)::bigint) > 0) OR (COALESCE(u.unfinished_count, (0)::bigint) > 0))) THEN 'at_risk'::text
                    ELSE 'on_track'::text
                END AS risk
           FROM ((api.study_tasks t
             LEFT JOIN conditions c ON ((c.task_id = t.id)))
             LEFT JOIN unfinished_dependencies u ON ((u.task_id = t.id)))
          WHERE (t.task_type = 'milestone'::text)
        )
 SELECT task_id,
    workspace_id,
    project_id,
    due_at,
    status,
    conditions_total,
    conditions_open,
    unfinished_dependencies,
    blocking_title,
    (risk = 'late'::text) AS late,
    risk,
        CASE risk
            WHEN 'done'::text THEN 'Completed'::text
            WHEN 'late'::text THEN ('Due date passed'::text ||
            CASE
                WHEN (conditions_open > 0) THEN (((('; '::text || conditions_open) || ' of '::text) || conditions_total) || ' conditions still open'::text)
                ELSE ''::text
            END)
            WHEN 'at_risk'::text THEN (('Due within 14 days'::text ||
            CASE
                WHEN (conditions_open > 0) THEN (((('; '::text || conditions_open) || ' of '::text) || conditions_total) || ' conditions still open'::text)
                ELSE ''::text
            END) ||
            CASE
                WHEN (unfinished_dependencies > 0) THEN (('; depends on "'::text || blocking_title) || '"'::text)
                ELSE ''::text
            END)
            ELSE 'On track'::text
        END AS risk_reason
   FROM base;
--> statement-breakpoint
ALTER VIEW api.milestone_risks OWNER TO migrator;
