CREATE TABLE internal.pipeline_run_jobs (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    run_id uuid NOT NULL,
    workspace_id uuid NOT NULL,
    kind text DEFAULT 'execute'::text NOT NULL,
    actor_user_id text NOT NULL,
    payload jsonb DEFAULT '{}'::jsonb NOT NULL,
    state text DEFAULT 'queued'::text NOT NULL,
    attempts integer DEFAULT 0 NOT NULL,
    max_attempts integer DEFAULT 3 NOT NULL,
    available_at timestamp with time zone DEFAULT now() NOT NULL,
    claimed_by text,
    claimed_at timestamp with time zone,
    lease_expires_at timestamp with time zone,
    last_error text,
    enqueued_at timestamp with time zone DEFAULT now() NOT NULL,
    finished_at timestamp with time zone,
    CONSTRAINT chk_pipeline_run_jobs_attempts CHECK (((attempts >= 0) AND (max_attempts >= 1))),
    CONSTRAINT chk_pipeline_run_jobs_claim CHECK (((state = 'claimed'::text) = ((claimed_by IS NOT NULL) AND (lease_expires_at IS NOT NULL)))),
    CONSTRAINT chk_pipeline_run_jobs_finished CHECK (((state = ANY (ARRAY['done'::text, 'dead'::text])) = (finished_at IS NOT NULL))),
    CONSTRAINT chk_pipeline_run_jobs_kind CHECK ((kind = ANY (ARRAY['execute'::text, 'resume'::text]))),
    CONSTRAINT chk_pipeline_run_jobs_state CHECK ((state = ANY (ARRAY['queued'::text, 'claimed'::text, 'done'::text, 'dead'::text])))
);
--> statement-breakpoint
ALTER TABLE internal.pipeline_run_jobs OWNER TO migrator;
--> statement-breakpoint
COMMENT ON TABLE internal.pipeline_run_jobs IS 'PIPE-EXEC durable run queue. One open job per run; claimed with FOR UPDATE SKIP LOCKED under a heartbeat lease; the run row insert enqueues in the same transaction.';
--> statement-breakpoint
